INSERT INTO bible_versions (version_id, code, title, language, source_path) VALUES
('nvi', 'NVI', 'Nueva Versión Internacional', 'es', 'resources/biblias/NVI.xml')
INSERT INTO bible_verses (version_id, ref, book, chapter, verse, text) VALUES
('nvi', 'Génesis 1:1', 'Génesis', 1, 1, 'Dios, en el principio, creó los cielos y la tierra.'),
('nvi', 'Génesis 1:2', 'Génesis', 1, 2, 'La tierra era un caos total, las tinieblas cubrían el abismo, y el Espíritu de Dios iba y venía sobre la superficie de las aguas.'),
('nvi', 'Génesis 1:3', 'Génesis', 1, 3, 'Y dijo Dios: «¡Que exista la luz!» Y la luz llegó a existir.'),
('nvi', 'Génesis 1:4', 'Génesis', 1, 4, 'Dios consideró que la luz era buena y la separó de las tinieblas.'),
('nvi', 'Génesis 1:5', 'Génesis', 1, 5, 'A la luz la llamó «día», y a las tinieblas, «noche». Y vino la noche, y llegó la mañana: ése fue el primer día.'),
('nvi', 'Génesis 1:6', 'Génesis', 1, 6, 'Y dijo Dios: «¡Que exista el firmamento en medio de las aguas, y que las separe!»'),
('nvi', 'Génesis 1:7', 'Génesis', 1, 7, 'Y así sucedió: Dios hizo el firmamento y separó las aguas que están abajo, de las aguas que están arriba.'),
('nvi', 'Génesis 1:8', 'Génesis', 1, 8, 'Al firmamento Dios lo llamó «cielo». Y vino la noche, y llegó la mañana: ése fue el segundo día.'),
('nvi', 'Génesis 1:9', 'Génesis', 1, 9, 'Y dijo Dios: «¡Que las aguas debajo del cielo se reúnan en un solo lugar, y que aparezca lo seco!» Y así sucedió.'),
('nvi', 'Génesis 1:10', 'Génesis', 1, 10, 'A lo seco Dios lo llamó «tierra», y al conjunto de aguas lo llamó «mar». Y Dios consideró que esto era bueno.'),
('nvi', 'Génesis 1:11', 'Génesis', 1, 11, 'Y dijo Dios: «¡Que haya vegetación sobre la tierra; que ésta produzca hierbas que den semilla, y árboles que den su fruto con semilla, todos según su especie!» Y así sucedió.'),
('nvi', 'Génesis 1:12', 'Génesis', 1, 12, 'Comenzó a brotar la vegetación: hierbas que dan semilla, y árboles que dan su fruto con semilla, todos según su especie. Y Dios consideró que esto era bueno.'),
('nvi', 'Génesis 1:13', 'Génesis', 1, 13, 'Y vino la noche, y llegó la mañana: ése fue el tercer día.'),
('nvi', 'Génesis 1:14', 'Génesis', 1, 14, 'Y dijo Dios: «¡Que haya luces en el firmamento que separen el día de la noche; que sirvan como señales de las estaciones, de los días y de los años,'),
('nvi', 'Génesis 1:15', 'Génesis', 1, 15, 'y que brillen en el firmamento para iluminar la tierra!» Y sucedió así.'),
('nvi', 'Génesis 1:16', 'Génesis', 1, 16, 'Dios hizo los dos grandes astros: el astro mayor para gobernar el día, y el menor para gobernar la noche. También hizo las estrellas.'),
('nvi', 'Génesis 1:17', 'Génesis', 1, 17, 'Dios colocó en el firmamento los astros para alumbrar la tierra.'),
('nvi', 'Génesis 1:18', 'Génesis', 1, 18, 'Los hizo para gobernar el día y la noche, y para separar la luz de las tinieblas. Y Dios consideró que esto era bueno.'),
('nvi', 'Génesis 1:19', 'Génesis', 1, 19, 'Y vino la noche, y llegó la mañana: ése fue el cuarto día.'),
('nvi', 'Génesis 1:20', 'Génesis', 1, 20, 'Y dijo Dios: «¡Que rebosen de seres vivientes las aguas, y que vuelen las aves sobre la tierra a lo largo del firmamento!»'),
('nvi', 'Génesis 1:21', 'Génesis', 1, 21, 'Y creó Dios los grandes animales marinos, y todos los seres vivientes que se mueven y pululan en las aguas y todas las aves, según su especie. Y Dios consideró que esto era bueno,'),
('nvi', 'Génesis 1:22', 'Génesis', 1, 22, 'y los bendijo con estas palabras: «Sean fructíferos y multiplíquense; llenen las aguas de los mares. ¡Que las aves se multipliquen sobre la tierra!»'),
('nvi', 'Génesis 1:23', 'Génesis', 1, 23, 'Y vino la noche, y llegó la mañana: ése fue el quinto día.'),
('nvi', 'Génesis 1:24', 'Génesis', 1, 24, 'Y dijo Dios: «¡Que produzca la tierra seres vivientes: animales domésticos, animales salvajes, y reptiles, según su especie!» Y sucedió así.'),
('nvi', 'Génesis 1:25', 'Génesis', 1, 25, 'Dios hizo los animales domésticos, los animales salvajes, y todos los reptiles, según su especie. Y Dios consideró que esto era bueno,'),
('nvi', 'Génesis 1:26', 'Génesis', 1, 26, 'y dijo: «Hagamos al ser humano a nuestra imagen y semejanza. Que tenga dominio sobre los peces del mar, y sobre las aves del cielo; sobre los animales domésticos, sobre los animales salvajes, y sobre todos los reptiles que se arrastran por el suelo.»'),
('nvi', 'Génesis 1:27', 'Génesis', 1, 27, 'Y Dios creó al ser humano a su imagen; lo creó a imagen de Dios. Hombre y mujer los creó,'),
('nvi', 'Génesis 1:28', 'Génesis', 1, 28, 'y los bendijo con estas palabras: «Sean fructíferos y multiplíquense; llenen la tierra y sométanla; dominen a los peces del mar y a las aves del cielo, y a todos los reptiles que se arrastran por el suelo.»'),
('nvi', 'Génesis 1:29', 'Génesis', 1, 29, 'También les dijo: «Yo les doy de la tierra todas las plantas que producen semilla y todos los árboles que dan fruto con semilla; todo esto les servirá de alimento.'),
('nvi', 'Génesis 1:30', 'Génesis', 1, 30, 'Y doy la hierba verde como alimento a todas las fieras de la tierra, a todas las aves del cielo y a todos los seres vivientes que se arrastran por la tierra.» Y así sucedió.'),
('nvi', 'Génesis 1:31', 'Génesis', 1, 31, 'Dios miró todo lo que había hecho, y consideró que era muy bueno. Y vino la noche, y llegó la mañana: ése fue el sexto día.'),
('nvi', 'Génesis 2:1', 'Génesis', 2, 1, 'Así quedaron terminados los cielos y la tierra, y todo lo que hay en ellos.'),
('nvi', 'Génesis 2:2', 'Génesis', 2, 2, 'Al llegar el séptimo día, Dios descansó porque había terminado la obra que había emprendido.'),
('nvi', 'Génesis 2:3', 'Génesis', 2, 3, 'Dios bendijo el séptimo día, y lo santificó, porque en ese día descansó de toda su obra creadora.'),
('nvi', 'Génesis 2:4', 'Génesis', 2, 4, 'Ésta es la historia de la creación de los cielos y la tierra. Cuando Dios el SEÑOR hizo la tierra y los cielos,'),
('nvi', 'Génesis 2:5', 'Génesis', 2, 5, 'aún no había ningún arbusto del campo sobre la tierra, ni había brotado la hierba, porque Dios el SEÑOR todavía no había hecho llover sobre la tierra ni existía el hombre para que la cultivara.'),
('nvi', 'Génesis 2:6', 'Génesis', 2, 6, 'No obstante, salía de la tierra un manantial que regaba toda la superficie del suelo.'),
('nvi', 'Génesis 2:7', 'Génesis', 2, 7, 'Y Dios el SEÑOR formó al hombre del polvo de la tierra, y sopló en su nariz hálito de vida, y el hombre se convirtió en un ser viviente.'),
('nvi', 'Génesis 2:8', 'Génesis', 2, 8, 'Dios el SEÑOR plantó un jardín al oriente del Edén, y allí puso al hombre que había formado.'),
('nvi', 'Génesis 2:9', 'Génesis', 2, 9, 'Dios el SEÑOR hizo que creciera toda clase de árboles hermosos, los cuales daban frutos buenos y apetecibles. En medio del jardín hizo crecer el árbol de la vida y también el árbol del conocimiento del bien y del mal.'),
('nvi', 'Génesis 2:10', 'Génesis', 2, 10, 'Del Edén nacía un río que regaba el jardín, y que desde allí se dividía en cuatro ríos menores.'),
('nvi', 'Génesis 2:11', 'Génesis', 2, 11, 'El primero se llamaba Pisón, y recorría toda la región de Javilá, donde había oro.'),
('nvi', 'Génesis 2:12', 'Génesis', 2, 12, 'El oro de esa región era fino, y también había allí resina muy buena y piedra de ónice.'),
('nvi', 'Génesis 2:13', 'Génesis', 2, 13, 'El segundo se llamaba Guijón, que recorría toda la región de Cus.'),
('nvi', 'Génesis 2:14', 'Génesis', 2, 14, 'El tercero se llamaba Tigris, que corría al este de Asiria. El cuarto era el Éufrates.'),
('nvi', 'Génesis 2:15', 'Génesis', 2, 15, 'Dios el SEÑOR tomó al hombre y lo puso en el jardín del Edén para que lo cultivara y lo cuidara,'),
('nvi', 'Génesis 2:16', 'Génesis', 2, 16, 'y le dio este mandato: «Puedes comer de todos los árboles del jardín,'),
('nvi', 'Génesis 2:17', 'Génesis', 2, 17, 'pero del árbol del conocimiento del bien y del mal no deberás comer. El día que de él comas, ciertamente morirás.»'),
('nvi', 'Génesis 2:18', 'Génesis', 2, 18, 'Luego Dios el SEÑOR dijo: «No es bueno que el hombre esté solo. Voy a hacerle una ayuda adecuada.»'),
('nvi', 'Génesis 2:19', 'Génesis', 2, 19, 'Entonces Dios el SEÑOR formó de la tierra toda ave del cielo y todo animal del campo, y se los llevó al hombre para ver qué nombre les pondría. El hombre les puso nombre a todos los seres vivos, y con ese nombre se les conoce.'),
('nvi', 'Génesis 2:20', 'Génesis', 2, 20, 'Así el hombre fue poniéndoles nombre a todos los animales domésticos, a todas las aves del cielo y a todos los animales del campo. Sin embargo, no se encontró entre ellos la ayuda adecuada para el hombre.'),
('nvi', 'Génesis 2:21', 'Génesis', 2, 21, 'Entonces Dios el SEÑOR hizo que el hombre cayera en un sueño profundo y, mientras éste dormía, le sacó una costilla y le cerró la herida.'),
('nvi', 'Génesis 2:22', 'Génesis', 2, 22, 'De la costilla que le había quitado al hombre, Dios el SEÑOR hizo una mujer y se la presentó al hombre,'),
('nvi', 'Génesis 2:23', 'Génesis', 2, 23, 'el cual exclamó: «Ésta sí es hueso de mis huesos y carne de mi carne. Se llamará “mujer” porque del hombre fue sacada.»'),
('nvi', 'Génesis 2:24', 'Génesis', 2, 24, 'Por eso el hombre deja a su padre y a su madre, y se une a su mujer, y los dos se funden en un solo ser.'),
('nvi', 'Génesis 2:25', 'Génesis', 2, 25, 'En ese tiempo el hombre y la mujer estaban desnudos, pero ninguno de los dos sentía vergüenza.'),
('nvi', 'Génesis 3:1', 'Génesis', 3, 1, 'La serpiente era más astuta que todos los animales del campo que Dios el SEÑOR había hecho, así que le preguntó a la mujer: —¿Es verdad que Dios les dijo que no comieran de ningún árbol del jardín?'),
('nvi', 'Génesis 3:2', 'Génesis', 3, 2, '—Podemos comer del fruto de todos los árboles —respondió la mujer—.'),
('nvi', 'Génesis 3:3', 'Génesis', 3, 3, 'Pero, en cuanto al fruto del árbol que está en medio del jardín, Dios nos ha dicho: “No coman de ese árbol, ni lo toquen; de lo contrario, morirán.”'),
('nvi', 'Génesis 3:4', 'Génesis', 3, 4, 'Pero la serpiente le dijo a la mujer: —¡No es cierto, no van a morir!'),
('nvi', 'Génesis 3:5', 'Génesis', 3, 5, 'Dios sabe muy bien que, cuando coman de ese árbol, se les abrirán los ojos y llegarán a ser como Dios, conocedores del bien y del mal.'),
('nvi', 'Génesis 3:6', 'Génesis', 3, 6, 'La mujer vio que el fruto del árbol era bueno para comer, y que tenía buen aspecto y era deseable para adquirir sabiduría, así que tomó de su fruto y comió. Luego le dio a su esposo, y también él comió.'),
('nvi', 'Génesis 3:7', 'Génesis', 3, 7, 'En ese momento se les abrieron los ojos, y tomaron conciencia de su desnudez. Por eso, para cubrirse entretejieron hojas de higuera.'),
('nvi', 'Génesis 3:8', 'Génesis', 3, 8, 'Cuando el día comenzó a refrescar, oyeron el hombre y la mujer que Dios andaba recorriendo el jardín; entonces corrieron a esconderse entre los árboles, para que Dios no los viera.'),
('nvi', 'Génesis 3:9', 'Génesis', 3, 9, 'Pero Dios el SEÑOR llamó al hombre y le dijo: —¿Dónde estás?'),
('nvi', 'Génesis 3:10', 'Génesis', 3, 10, 'El hombre contestó: —Escuché que andabas por el jardín, y tuve miedo porque estoy desnudo. Por eso me escondí.'),
('nvi', 'Génesis 3:11', 'Génesis', 3, 11, '—¿Y quién te ha dicho que estás desnudo? —le preguntó Dios—. ¿Acaso has comido del fruto del árbol que yo te prohibí comer?'),
('nvi', 'Génesis 3:12', 'Génesis', 3, 12, 'Él respondió: —La mujer que me diste por compañera me dio de ese fruto, y yo lo comí.'),
('nvi', 'Génesis 3:13', 'Génesis', 3, 13, 'Entonces Dios el SEÑOR le preguntó a la mujer: —¿Qué es lo que has hecho? —La serpiente me engañó, y comí —contestó ella.'),
('nvi', 'Génesis 3:14', 'Génesis', 3, 14, 'Dios el SEÑOR dijo entonces a la serpiente: «Por causa de lo que has hecho, ¡maldita serás entre todos los animales, tanto domésticos como salvajes! Te arrastrarás sobre tu vientre, y comerás polvo todos los días de tu vida.'),
('nvi', 'Génesis 3:15', 'Génesis', 3, 15, 'Pondré enemistad entre tú y la mujer, y entre tu simiente y la de ella; su simiente te aplastará la cabeza, pero tú le morderás el talón.»'),
('nvi', 'Génesis 3:16', 'Génesis', 3, 16, 'A la mujer le dijo: «Multiplicaré tus dolores en el parto, y darás a luz a tus hijos con dolor. Desearás a tu marido, y él te dominará.»'),
('nvi', 'Génesis 3:17', 'Génesis', 3, 17, 'Al hombre le dijo: «Por cuanto le hiciste caso a tu mujer, y comiste del árbol del que te prohibí comer, ¡maldita será la tierra por tu culpa! Con penosos trabajos comerás de ella todos los días de tu vida.'),
('nvi', 'Génesis 3:18', 'Génesis', 3, 18, 'La tierra te producirá cardos y espinas, y comerás hierbas silvestres.'),
('nvi', 'Génesis 3:19', 'Génesis', 3, 19, 'Te ganarás el pan con el sudor de tu frente, hasta que vuelvas a la misma tierra de la cual fuiste sacado. Porque polvo eres, y al polvo volverás.»'),
('nvi', 'Génesis 3:20', 'Génesis', 3, 20, 'El hombre llamó Eva a su mujer, porque ella sería la madre de todo ser viviente.'),
('nvi', 'Génesis 3:21', 'Génesis', 3, 21, 'Dios el SEÑOR hizo ropa de pieles para el hombre y su mujer, y los vistió.'),
('nvi', 'Génesis 3:22', 'Génesis', 3, 22, 'Y dijo: «El ser humano ha llegado a ser como uno de nosotros, pues tiene conocimiento del bien y del mal. No vaya a ser que extienda su mano y también tome del fruto del árbol de la vida, y lo coma y viva para siempre.»'),
('nvi', 'Génesis 3:23', 'Génesis', 3, 23, 'Entonces Dios el SEÑOR expulsó al ser humano del jardín del Edén, para que trabajara la tierra de la cual había sido hecho.'),
('nvi', 'Génesis 3:24', 'Génesis', 3, 24, 'Luego de expulsarlo, puso al oriente del jardín del Edén a los querubines, y una espada ardiente que se movía por todos lados, para custodiar el camino que lleva al árbol de la vida.'),
('nvi', 'Génesis 4:1', 'Génesis', 4, 1, 'El hombre se unió a su mujer Eva, y ella concibió y dio a luz a Caín. Y dijo: «¡Con la ayuda del SEÑOR, he tenido un hijo varón!»'),
('nvi', 'Génesis 4:2', 'Génesis', 4, 2, 'Después dio a luz a Abel, hermano de Caín. Abel se dedicó a pastorear ovejas, mientras que Caín se dedicó a trabajar la tierra.'),
('nvi', 'Génesis 4:3', 'Génesis', 4, 3, 'Tiempo después, Caín presentó al SEÑOR una ofrenda del fruto de la tierra.'),
('nvi', 'Génesis 4:4', 'Génesis', 4, 4, 'Abel también presentó al SEÑOR lo mejor de su rebaño, es decir, los primogénitos con su grasa. Y el SEÑOR miró con agrado a Abel y a su ofrenda,'),
('nvi', 'Génesis 4:5', 'Génesis', 4, 5, 'pero no miró así a Caín ni a su ofrenda. Por eso Caín se enfureció y andaba cabizbajo.'),
('nvi', 'Génesis 4:6', 'Génesis', 4, 6, 'Entonces el SEÑOR le dijo: «¿Por qué estás tan enojado? ¿Por qué andas cabizbajo?'),
('nvi', 'Génesis 4:7', 'Génesis', 4, 7, 'Si hicieras lo bueno, podrías andar con la frente en alto. Pero si haces lo malo, el pecado te acecha, como una fiera lista para atraparte. No obstante, tú puedes dominarlo.»'),
('nvi', 'Génesis 4:8', 'Génesis', 4, 8, 'Caín habló con su hermano Abel. Mientras estaban en el campo, Caín atacó a su hermano y lo mató.'),
('nvi', 'Génesis 4:9', 'Génesis', 4, 9, 'El SEÑOR le preguntó a Caín: —¿Dónde está tu hermano Abel? —No lo sé —respondió—. ¿Acaso soy yo el que debe cuidar a mi hermano?'),
('nvi', 'Génesis 4:10', 'Génesis', 4, 10, '—¡Qué has hecho! —exclamó el SEÑOR—. Desde la tierra, la sangre de tu hermano reclama justicia.'),
('nvi', 'Génesis 4:11', 'Génesis', 4, 11, 'Por eso, ahora quedarás bajo la maldición de la tierra, la cual ha abierto sus fauces para recibir la sangre de tu hermano, que tú has derramado.'),
('nvi', 'Génesis 4:12', 'Génesis', 4, 12, 'Cuando cultives la tierra, no te dará sus frutos, y en el mundo serás un fugitivo errante.'),
('nvi', 'Génesis 4:13', 'Génesis', 4, 13, '—Este castigo es más de lo que puedo soportar —le dijo Caín al SEÑOR—.'),
('nvi', 'Génesis 4:14', 'Génesis', 4, 14, 'Hoy me condenas al destierro, y nunca más podré estar en tu presencia. Andaré por el mundo errante como un fugitivo, y cualquiera que me encuentre me matará.'),
('nvi', 'Génesis 4:15', 'Génesis', 4, 15, '—No será así —replicó el SEÑOR—. El que mate a Caín, será castigado siete veces. Entonces el SEÑOR le puso una marca a Caín, para que no fuera a matarlo quien lo hallara.'),
('nvi', 'Génesis 4:16', 'Génesis', 4, 16, 'Así Caín se alejó de la presencia del SEÑOR y se fue a vivir a la región llamada Nod, al este del Edén.'),
('nvi', 'Génesis 4:17', 'Génesis', 4, 17, 'Caín se unió a su mujer, la cual concibió y dio a luz a Enoc. Caín había estado construyendo una ciudad, a la que le puso el nombre de su hijo Enoc.'),
('nvi', 'Génesis 4:18', 'Génesis', 4, 18, 'Luego Enoc tuvo un hijo llamado Irad, que fue el padre de Mejuyael. Éste, a su vez, fue el padre de Metusael, y Metusael fue el padre de Lamec.'),
('nvi', 'Génesis 4:19', 'Génesis', 4, 19, 'Lamec tuvo dos mujeres. Una de ellas se llamaba Ada, y la otra Zila.'),
('nvi', 'Génesis 4:20', 'Génesis', 4, 20, 'Ada dio a luz a Jabal, quien a su vez fue el antepasado de los que viven en tiendas de campaña y crían ganado.'),
('nvi', 'Génesis 4:21', 'Génesis', 4, 21, 'Jabal tuvo un hermano llamado Jubal, quien fue el antepasado de los que tocan el arpa y la flauta.'),
('nvi', 'Génesis 4:22', 'Génesis', 4, 22, 'Por su parte, Zila dio a luz a Tubal Caín, que fue herrero y forjador de toda clase de herramientas de bronce y de hierro. Tubal Caín tuvo una hermana que se llamaba Noamá.'),
('nvi', 'Génesis 4:23', 'Génesis', 4, 23, 'Lamec dijo a sus mujeres Ada y Zila: «¡Escuchen bien, mujeres de Lamec! ¡Escuchen mis palabras! Maté a un hombre por haberme herido, y a un muchacho por golpearme.'),
('nvi', 'Génesis 4:24', 'Génesis', 4, 24, 'Si Caín será vengado siete veces, setenta y siete veces será vengado Lamec.»'),
('nvi', 'Génesis 4:25', 'Génesis', 4, 25, 'Adán volvió a unirse a su mujer, y ella tuvo un hijo al que llamó Set, porque dijo: «Dios me ha concedido otro hijo en lugar de Abel, al que mató Caín.»'),
('nvi', 'Génesis 4:26', 'Génesis', 4, 26, 'También Set tuvo un hijo, a quien llamó Enós. Desde entonces se comenzó a invocar el nombre del SEÑOR.'),
('nvi', 'Génesis 5:1', 'Génesis', 5, 1, 'Ésta es la lista de los descendientes de Adán. Cuando Dios creó al ser humano, lo hizo a semejanza de Dios mismo.'),
('nvi', 'Génesis 5:2', 'Génesis', 5, 2, 'Los creó hombre y mujer, y los bendijo. El día que fueron creados los llamó «seres humanos».'),
('nvi', 'Génesis 5:3', 'Génesis', 5, 3, 'Cuando Adán llegó a la edad de ciento treinta años, tuvo un hijo a su imagen y semejanza, y lo llamó Set.'),
('nvi', 'Génesis 5:4', 'Génesis', 5, 4, 'Después del nacimiento de Set, Adán vivió ochocientos años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:5', 'Génesis', 5, 5, 'De modo que Adán murió a los novecientos treinta años de edad.'),
('nvi', 'Génesis 5:6', 'Génesis', 5, 6, 'Set tenía ciento cinco años cuando fue padre de Enós.'),
('nvi', 'Génesis 5:7', 'Génesis', 5, 7, 'Después del nacimiento de Enós, Set vivió ochocientos siete años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:8', 'Génesis', 5, 8, 'De modo que Set murió a los novecientos doce años de edad.'),
('nvi', 'Génesis 5:9', 'Génesis', 5, 9, 'Enós tenía noventa años cuando fue padre de Cainán.'),
('nvi', 'Génesis 5:10', 'Génesis', 5, 10, 'Después del nacimiento de Cainán, Enós vivió ochocientos quince años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:11', 'Génesis', 5, 11, 'De modo que Enós murió a los novecientos cinco años de edad.'),
('nvi', 'Génesis 5:12', 'Génesis', 5, 12, 'Cainán tenía setenta años cuando fue padre de Malalel.'),
('nvi', 'Génesis 5:13', 'Génesis', 5, 13, 'Después del nacimiento de Malalel, Cainán vivió ochocientos cuarenta años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:14', 'Génesis', 5, 14, 'De modo que Cainán murió a los novecientos diez años de edad.'),
('nvi', 'Génesis 5:15', 'Génesis', 5, 15, 'Malalel tenía sesenta y cinco años cuando fue padre de Jared.'),
('nvi', 'Génesis 5:16', 'Génesis', 5, 16, 'Después del nacimiento de Jared, Malalel vivió ochocientos treinta años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:17', 'Génesis', 5, 17, 'De modo que Malalel murió a los ochocientos noventa y cinco años de edad.'),
('nvi', 'Génesis 5:18', 'Génesis', 5, 18, 'Jared tenía ciento sesenta y dos años cuando fue padre de Enoc.'),
('nvi', 'Génesis 5:19', 'Génesis', 5, 19, 'Después del nacimiento de Enoc, Jared vivió ochocientos años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:20', 'Génesis', 5, 20, 'De modo que Jared murió a los novecientos sesenta y dos años de edad.'),
('nvi', 'Génesis 5:21', 'Génesis', 5, 21, 'Enoc tenía sesenta y cinco años cuando fue padre de Matusalén.'),
('nvi', 'Génesis 5:22', 'Génesis', 5, 22, 'Después del nacimiento de Matusalén, Enoc anduvo fielmente con Dios trescientos años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:23', 'Génesis', 5, 23, 'En total, Enoc vivió trescientos sesenta y cinco años,'),
('nvi', 'Génesis 5:24', 'Génesis', 5, 24, 'y como anduvo fielmente con Dios, un día desapareció porque Dios se lo llevó.'),
('nvi', 'Génesis 5:25', 'Génesis', 5, 25, 'Matusalén tenía ciento ochenta y siete años cuando fue padre de Lamec.'),
('nvi', 'Génesis 5:26', 'Génesis', 5, 26, 'Después del nacimiento de Lamec, Matusalén vivió setecientos ochenta y dos años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:27', 'Génesis', 5, 27, 'De modo que Matusalén murió a los novecientos sesenta y nueve años de edad.'),
('nvi', 'Génesis 5:28', 'Génesis', 5, 28, 'Lamec tenía ciento ochenta y dos años cuando fue padre de Noé.'),
('nvi', 'Génesis 5:29', 'Génesis', 5, 29, 'Le dio ese nombre porque dijo: «Este niño nos dará descanso en nuestra tarea y penosos trabajos, en esta tierra que maldijo el SEÑOR.»'),
('nvi', 'Génesis 5:30', 'Génesis', 5, 30, 'Después del nacimiento de Noé, Lamec vivió quinientos noventa y cinco años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 5:31', 'Génesis', 5, 31, 'De modo que Lamec murió a los setecientos setenta y siete años de edad.'),
('nvi', 'Génesis 5:32', 'Génesis', 5, 32, 'Noé ya había cumplido quinientos años cuando fue padre de Sem, Cam y Jafet.'),
('nvi', 'Génesis 6:1', 'Génesis', 6, 1, 'Cuando los seres humanos comenzaron a multiplicarse sobre la tierra y tuvieron hijas,'),
('nvi', 'Génesis 6:2', 'Génesis', 6, 2, 'los hijos de Dios vieron que las hijas de los seres humanos eran hermosas. Entonces tomaron como mujeres a todas las que desearon.'),
('nvi', 'Génesis 6:3', 'Génesis', 6, 3, 'Pero el SEÑOR dijo: «Mi espíritu no permanecerá en el ser humano para siempre, porque no es más que un simple mortal; por eso vivirá solamente ciento veinte años.»'),
('nvi', 'Génesis 6:4', 'Génesis', 6, 4, 'Al unirse los hijos de Dios con las hijas de los seres humanos y tener hijos con ellas, nacieron gigantes, que fueron los famosos héroes de antaño. A partir de entonces hubo gigantes en la tierra.'),
('nvi', 'Génesis 6:5', 'Génesis', 6, 5, 'Al ver el SEÑOR que la maldad del ser humano en la tierra era muy grande, y que todos sus pensamientos tendían siempre hacia el mal,'),
('nvi', 'Génesis 6:6', 'Génesis', 6, 6, 'se arrepintió de haber hecho al ser humano en la tierra, y le dolió en el corazón.'),
('nvi', 'Génesis 6:7', 'Génesis', 6, 7, 'Entonces dijo: «Voy a borrar de la tierra al ser humano que he creado. Y haré lo mismo con los animales, los reptiles y las aves del cielo. ¡Me arrepiento de haberlos creado!»'),
('nvi', 'Génesis 6:8', 'Génesis', 6, 8, 'Pero Noé contaba con el favor del SEÑOR.'),
('nvi', 'Génesis 6:9', 'Génesis', 6, 9, 'Ésta es la historia de Noé. Noé era un hombre justo y honrado entre su gente. Siempre anduvo fielmente con Dios.'),
('nvi', 'Génesis 6:10', 'Génesis', 6, 10, 'Tuvo tres hijos: Sem, Cam y Jafet.'),
('nvi', 'Génesis 6:11', 'Génesis', 6, 11, 'Pero Dios vio que la tierra estaba corrompida y llena de violencia.'),
('nvi', 'Génesis 6:12', 'Génesis', 6, 12, 'Al ver Dios tanta corrupción en la tierra, y tanta perversión en la gente,'),
('nvi', 'Génesis 6:13', 'Génesis', 6, 13, 'le dijo a Noé: «He decidido acabar con toda la gente, pues por causa de ella la tierra está llena de violencia. Así que voy a destruir a la gente junto con la tierra.'),
('nvi', 'Génesis 6:14', 'Génesis', 6, 14, 'Constrúyete un arca de madera resinosa, hazle compartimentos, y cúbrela con brea por dentro y por fuera.'),
('nvi', 'Génesis 6:15', 'Génesis', 6, 15, 'Dale las siguientes medidas: ciento cuarenta metros de largo, veintitrés de ancho y catorce de alto.'),
('nvi', 'Génesis 6:16', 'Génesis', 6, 16, 'Hazla de tres pisos, con una abertura a medio metro del techo y con una puerta en uno de sus costados.'),
('nvi', 'Génesis 6:17', 'Génesis', 6, 17, 'Porque voy a enviar un diluvio sobre la tierra, para destruir a todos los seres vivientes bajo el cielo. Todo lo que existe en la tierra morirá.'),
('nvi', 'Génesis 6:18', 'Génesis', 6, 18, 'Pero contigo estableceré mi pacto, y entrarán en el arca tú y tus hijos, tu esposa y tus nueras.'),
('nvi', 'Génesis 6:19', 'Génesis', 6, 19, 'Haz que entre en el arca una pareja de todos los seres vivientes, es decir, un macho y una hembra de cada especie, para que sobrevivan contigo.'),
('nvi', 'Génesis 6:20', 'Génesis', 6, 20, 'Contigo entrará también una pareja de cada especie de aves, de ganado y de reptiles, para que puedan sobrevivir.'),
('nvi', 'Génesis 6:21', 'Génesis', 6, 21, 'Recoge además toda clase de alimento, y almacénalo, para que a ti y a ellos les sirva de comida.»'),
('nvi', 'Génesis 6:22', 'Génesis', 6, 22, 'Y Noé hizo todo según lo que Dios le había mandado.'),
('nvi', 'Génesis 7:1', 'Génesis', 7, 1, 'El SEÑOR le dijo a Noé: «Entra en el arca con toda tu familia, porque tú eres el único hombre justo que he encontrado en esta generación.'),
('nvi', 'Génesis 7:2', 'Génesis', 7, 2, 'De todos los animales puros, lleva siete machos y siete hembras; pero de los impuros, sólo un macho y una hembra.'),
('nvi', 'Génesis 7:3', 'Génesis', 7, 3, 'Lleva también siete machos y siete hembras de las aves del cielo, para conservar su especie sobre la tierra.'),
('nvi', 'Génesis 7:4', 'Génesis', 7, 4, 'Porque dentro de siete días haré que llueva sobre la tierra durante cuarenta días y cuarenta noches, y así borraré de la faz de la tierra a todo ser viviente que hice.»'),
('nvi', 'Génesis 7:5', 'Génesis', 7, 5, 'Noé hizo todo de acuerdo con lo que el SEÑOR le había mandado.'),
('nvi', 'Génesis 7:6', 'Génesis', 7, 6, 'Tenía Noé seiscientos años de edad cuando las aguas del diluvio inundaron la tierra.'),
('nvi', 'Génesis 7:7', 'Génesis', 7, 7, 'Entonces entró en el arca junto con sus hijos, su esposa y sus nueras, para salvarse de las aguas del diluvio.'),
('nvi', 'Génesis 7:8', 'Génesis', 7, 8, 'De los animales puros e impuros, de las aves y de todos los seres que se arrastran por el suelo,'),
('nvi', 'Génesis 7:9', 'Génesis', 7, 9, 'entraron con Noé por parejas, el macho y su hembra, tal como Dios se lo había mandado.'),
('nvi', 'Génesis 7:10', 'Génesis', 7, 10, 'Al cabo de los siete días, las aguas del diluvio comenzaron a caer sobre la tierra.'),
('nvi', 'Génesis 7:11', 'Génesis', 7, 11, 'Cuando Noé tenía seiscientos años, precisamente en el día diecisiete del mes segundo, se reventaron las fuentes del mar profundo y se abrieron las compuertas del cielo.'),
('nvi', 'Génesis 7:12', 'Génesis', 7, 12, 'Cuarenta días y cuarenta noches llovió sobre la tierra.'),
('nvi', 'Génesis 7:13', 'Génesis', 7, 13, 'Ese mismo día entraron en el arca Noé, sus hijos Sem, Cam y Jafet, su esposa y sus tres nueras.'),
('nvi', 'Génesis 7:14', 'Génesis', 7, 14, 'Junto con ellos entró toda clase de animales salvajes y domésticos, de animales que se arrastran por el suelo, y de aves.'),
('nvi', 'Génesis 7:15', 'Génesis', 7, 15, 'Así entraron en el arca con Noé parejas de todos los seres vivientes;'),
('nvi', 'Génesis 7:16', 'Génesis', 7, 16, 'entraron un macho y una hembra de cada especie, tal como Dios se lo había mandado a Noé. Luego el SEÑOR cerró la puerta del arca.'),
('nvi', 'Génesis 7:17', 'Génesis', 7, 17, 'El diluvio cayó sobre la tierra durante cuarenta días. Cuando crecieron las aguas, elevaron el arca por encima de la tierra.'),
('nvi', 'Génesis 7:18', 'Génesis', 7, 18, 'Las aguas crecían y aumentaban cada vez más, pero el arca se mantenía a flote sobre ellas.'),
('nvi', 'Génesis 7:19', 'Génesis', 7, 19, 'Tanto crecieron las aguas, que cubrieron las montañas más altas que hay debajo de los cielos.'),
('nvi', 'Génesis 7:20', 'Génesis', 7, 20, 'El nivel del agua subió más de siete metros por encima de las montañas.'),
('nvi', 'Génesis 7:21', 'Génesis', 7, 21, 'Así murió todo ser viviente que se movía sobre la tierra: las aves, los animales salvajes y domésticos, todo tipo de animal que se arrastraba por el suelo, y todo ser humano.'),
('nvi', 'Génesis 7:22', 'Génesis', 7, 22, 'Pereció todo ser que habitaba la tierra firme y tenía aliento de vida.'),
('nvi', 'Génesis 7:23', 'Génesis', 7, 23, 'Dios borró de la faz de la tierra a todo ser viviente, desde los seres humanos hasta los ganados, los reptiles y las aves del cielo. Todos fueron borrados de la faz de la tierra. Sólo quedaron Noé y los que estaban con él en el arca.'),
('nvi', 'Génesis 7:24', 'Génesis', 7, 24, 'Y la tierra quedó inundada ciento cincuenta días.'),
('nvi', 'Génesis 8:1', 'Génesis', 8, 1, 'Dios se acordó entonces de Noé y de todos los animales salvajes y domésticos que estaban con él en el arca. Hizo que soplara un fuerte viento sobre la tierra, y las aguas comenzaron a bajar.'),
('nvi', 'Génesis 8:2', 'Génesis', 8, 2, 'Se cerraron las fuentes del mar profundo y las compuertas del cielo, y dejó de llover.'),
('nvi', 'Génesis 8:3', 'Génesis', 8, 3, 'Poco a poco las aguas se fueron retirando de la tierra. Al cabo de ciento cincuenta días las aguas habían disminuido.'),
('nvi', 'Génesis 8:4', 'Génesis', 8, 4, 'El día diecisiete del mes séptimo el arca se detuvo sobre las montañas de Ararat,'),
('nvi', 'Génesis 8:5', 'Génesis', 8, 5, 'y las aguas siguieron bajando hasta que el primer día del mes décimo pudieron verse las cimas de las montañas.'),
('nvi', 'Génesis 8:6', 'Génesis', 8, 6, 'Después de cuarenta días, Noé abrió la ventana del arca que había hecho'),
('nvi', 'Génesis 8:7', 'Génesis', 8, 7, 'y soltó un cuervo, el cual estuvo volando de un lado a otro, esperando a que se secara la tierra.'),
('nvi', 'Génesis 8:8', 'Génesis', 8, 8, 'Luego soltó una paloma, para ver si las aguas que cubrían la tierra ya se habían retirado.'),
('nvi', 'Génesis 8:9', 'Génesis', 8, 9, 'Pero la paloma no encontró un lugar donde posarse, y volvió al arca porque las aguas aún cubrían la tierra. Noé extendió la mano, tomó la paloma y la metió consigo en el arca.'),
('nvi', 'Génesis 8:10', 'Génesis', 8, 10, 'Esperó siete días más y volvió a soltar la paloma fuera del arca.'),
('nvi', 'Génesis 8:11', 'Génesis', 8, 11, 'Caía la noche cuando la paloma regresó, trayendo en su pico una ramita de olivo recién cortada. Así Noé se dio cuenta de que las aguas habían bajado hasta dejar la tierra al descubierto.'),
('nvi', 'Génesis 8:12', 'Génesis', 8, 12, 'Esperó siete días más y volvió a soltar la paloma, pero esta vez la paloma ya no regresó.'),
('nvi', 'Génesis 8:13', 'Génesis', 8, 13, 'Noé tenía seiscientos un años cuando las aguas se secaron. El primer día del primer mes de ese año, Noé quitó la cubierta del arca y vio que la tierra estaba seca.'),
('nvi', 'Génesis 8:14', 'Génesis', 8, 14, 'Para el día veintisiete del segundo mes, la tierra estaba ya completamente seca.'),
('nvi', 'Génesis 8:15', 'Génesis', 8, 15, 'Entonces Dios le dijo a Noé:'),
('nvi', 'Génesis 8:16', 'Génesis', 8, 16, '«Sal del arca junto con tus hijos, tu esposa y tus nueras.'),
('nvi', 'Génesis 8:17', 'Génesis', 8, 17, 'Saca también a todos los seres vivientes que están contigo: las aves, el ganado y todos los animales que se arrastran por el suelo. ¡Que sean fecundos! ¡Que se multipliquen y llenen la tierra!»'),
('nvi', 'Génesis 8:18', 'Génesis', 8, 18, 'Salieron, pues, del arca Noé y sus hijos, su esposa y sus nueras.'),
('nvi', 'Génesis 8:19', 'Génesis', 8, 19, 'Salieron también todos los animales: el ganado, las aves, y todos los reptiles que se mueven sobre la tierra, cada uno según su especie.'),
('nvi', 'Génesis 8:20', 'Génesis', 8, 20, 'Luego Noé construyó un altar al SEÑOR, y sobre ese altar ofreció como holocausto animales puros y aves puras.'),
('nvi', 'Génesis 8:21', 'Génesis', 8, 21, 'Cuando el SEÑOR percibió el grato aroma, se dijo a sí mismo: «Aunque las intenciones del ser humano son perversas desde su juventud, nunca más volveré a maldecir la tierra por culpa suya. Tampoco volveré a destruir a todos los seres vivientes, como acabo de hacerlo.'),
('nvi', 'Génesis 8:22', 'Génesis', 8, 22, '»Mientras la tierra exista, habrá siembra y cosecha, frío y calor, verano e invierno, y días y noches.»'),
('nvi', 'Génesis 9:1', 'Génesis', 9, 1, 'Dios bendijo a Noé y a sus hijos con estas palabras: «Sean fecundos, multiplíquense y llenen la tierra.'),
('nvi', 'Génesis 9:2', 'Génesis', 9, 2, 'Todos los animales de la tierra sentirán temor y respeto ante ustedes: las aves, las bestias salvajes, los animales que se arrastran por el suelo, y los peces del mar. Todos estarán bajo su dominio.'),
('nvi', 'Génesis 9:3', 'Génesis', 9, 3, 'Todo lo que se mueve y tiene vida, al igual que las verduras, les servirá de alimento. Yo les doy todo esto.'),
('nvi', 'Génesis 9:4', 'Génesis', 9, 4, 'Pero no deberán comer carne con su vida, es decir, con su sangre.'),
('nvi', 'Génesis 9:5', 'Génesis', 9, 5, 'Por cierto, de la sangre de ustedes yo habré de pedirles cuentas. A todos los animales y a todos los seres humanos les pediré cuentas de la vida de sus semejantes.'),
('nvi', 'Génesis 9:6', 'Génesis', 9, 6, '»Si alguien derrama la sangre de un ser humano, otro ser humano derramará la suya, porque el ser humano ha sido creado a imagen de Dios mismo.'),
('nvi', 'Génesis 9:7', 'Génesis', 9, 7, '»En cuanto a ustedes, sean fecundos y multiplíquense; sí, multiplíquense y llenen la tierra.»'),
('nvi', 'Génesis 9:8', 'Génesis', 9, 8, 'Dios les habló otra vez a Noé y a sus hijos, y les dijo:'),
('nvi', 'Génesis 9:9', 'Génesis', 9, 9, '«Yo establezco mi pacto con ustedes, con sus descendientes,'),
('nvi', 'Génesis 9:10', 'Génesis', 9, 10, 'y con todos los seres vivientes que están con ustedes, es decir, con todos los seres vivientes de la tierra que salieron del arca: las aves, y los animales domésticos y salvajes.'),
('nvi', 'Génesis 9:11', 'Génesis', 9, 11, 'Éste es mi pacto con ustedes: Nunca más serán exterminados los seres humanos por un diluvio; nunca más habrá un diluvio que destruya la tierra.»'),
('nvi', 'Génesis 9:12', 'Génesis', 9, 12, 'Y Dios añadió: «Ésta es la señal del pacto que establezco para siempre con ustedes y con todos los seres vivientes que los acompañan:'),
('nvi', 'Génesis 9:13', 'Génesis', 9, 13, 'He colocado mi arco iris en las nubes, el cual servirá como señal de mi pacto con la tierra.'),
('nvi', 'Génesis 9:14', 'Génesis', 9, 14, 'Cuando yo cubra la tierra de nubes, y en ellas aparezca el arco iris,'),
('nvi', 'Génesis 9:15', 'Génesis', 9, 15, 'me acordaré del pacto que he establecido con ustedes y con todos los seres vivientes. Nunca más las aguas se convertirán en un diluvio para destruir a todos los mortales.'),
('nvi', 'Génesis 9:16', 'Génesis', 9, 16, 'Cada vez que aparezca el arco iris entre las nubes, yo lo veré y me acordaré del pacto que establecí para siempre con todos los seres vivientes que hay sobre la tierra.»'),
('nvi', 'Génesis 9:17', 'Génesis', 9, 17, 'Dios concluyó diciéndole a Noé: «Éste es el pacto que establezco con todos los seres vivientes que hay en la tierra.»'),
('nvi', 'Génesis 9:18', 'Génesis', 9, 18, 'Los hijos de Noé que salieron del arca fueron Sem, Cam, que fue el padre de Canaán, y Jafet.'),
('nvi', 'Génesis 9:19', 'Génesis', 9, 19, 'Éstos fueron los tres hijos de Noé que con su descendencia poblaron toda la tierra.'),
('nvi', 'Génesis 9:20', 'Génesis', 9, 20, 'Noé se dedicó a cultivar la tierra, y plantó una viña.'),
('nvi', 'Génesis 9:21', 'Génesis', 9, 21, 'Un día, bebió vino y se embriagó, quedándose desnudo dentro de su carpa.'),
('nvi', 'Génesis 9:22', 'Génesis', 9, 22, 'Cam, el padre de Canaán, vio a su padre desnudo y fue a contárselo a sus hermanos, que estaban afuera.'),
('nvi', 'Génesis 9:23', 'Génesis', 9, 23, 'Entonces Sem y Jafet tomaron un manto, se lo echaron sobre los hombros, y caminando hacia atrás, cubrieron la desnudez de su padre. Como miraban en dirección opuesta, no lo vieron desnudo.'),
('nvi', 'Génesis 9:24', 'Génesis', 9, 24, 'Cuando Noé despertó de su borrachera y se enteró de lo que su hijo menor le había hecho,'),
('nvi', 'Génesis 9:25', 'Génesis', 9, 25, 'declaró: «¡Maldito sea Canaán! Será de sus dos hermanos el más bajo de sus esclavos.»'),
('nvi', 'Génesis 9:26', 'Génesis', 9, 26, 'Y agregó: «¡Bendito sea el SEÑOR, Dios de Sem! ¡Que Canaán sea su esclavo!'),
('nvi', 'Génesis 9:27', 'Génesis', 9, 27, '¡Que Dios extienda el territorio de Jafet! ¡Que habite Jafet en los campamentos de Sem, y que Canaán sea su esclavo!»'),
('nvi', 'Génesis 9:28', 'Génesis', 9, 28, 'Después del diluvio Noé vivió trescientos cincuenta años más,'),
('nvi', 'Génesis 9:29', 'Génesis', 9, 29, 'de modo que murió a la edad de novecientos cincuenta años.'),
('nvi', 'Génesis 10:1', 'Génesis', 10, 1, 'Ésta es la historia de Sem, Cam y Jafet, hijos de Noé, quienes después del diluvio tuvieron sus propios hijos.'),
('nvi', 'Génesis 10:2', 'Génesis', 10, 2, 'Los hijos de Jafet fueron Gómer, Magog, Maday, Javán, Tubal, Mésec y Tirás.'),
('nvi', 'Génesis 10:3', 'Génesis', 10, 3, 'Los hijos de Gómer fueron Asquenaz, Rifat y Togarma.'),
('nvi', 'Génesis 10:4', 'Génesis', 10, 4, 'Los hijos de Javán fueron Elisá, Tarsis, Quitín y Rodanín.'),
('nvi', 'Génesis 10:5', 'Génesis', 10, 5, 'Algunos de ellos, que poblaron las costas, formaron naciones y clanes en sus respectivos territorios y con sus propios idiomas.'),
('nvi', 'Génesis 10:6', 'Génesis', 10, 6, 'Los hijos de Cam fueron Cus, Misrayin, Fut y Canaán.'),
('nvi', 'Génesis 10:7', 'Génesis', 10, 7, 'Los hijos de Cus fueron Seba, Javilá, Sabtá, Ragama y Sabteca. Los hijos de Ragama fueron Sabá y Dedán.'),
('nvi', 'Génesis 10:8', 'Génesis', 10, 8, 'Cus fue el padre de Nimrod, conocido como el primer hombre fuerte de la tierra,'),
('nvi', 'Génesis 10:9', 'Génesis', 10, 9, 'quien llegó a ser un valiente cazador ante el SEÑOR. Por eso se dice: «Como Nimrod, valiente cazador ante el SEÑOR.»'),
('nvi', 'Génesis 10:10', 'Génesis', 10, 10, 'Las principales ciudades de su reino fueron Babel, Érec, Acad y Calné, en la región de Sinar.'),
('nvi', 'Génesis 10:11', 'Génesis', 10, 11, 'Desde esa región Nimrod salió hacia Asur, donde construyó las ciudades de Nínive, Rejobot Ir, Cala'),
('nvi', 'Génesis 10:12', 'Génesis', 10, 12, 'y Resén, la gran ciudad que está entre Nínive y Cala.'),
('nvi', 'Génesis 10:13', 'Génesis', 10, 13, 'Misrayin fue el antepasado de los ludeos, los anameos, los leabitas, los naftuitas,'),
('nvi', 'Génesis 10:14', 'Génesis', 10, 14, 'los patruseos, los caslujitas y los caftoritas, de quienes descienden los filisteos.'),
('nvi', 'Génesis 10:15', 'Génesis', 10, 15, 'Canaán fue el padre de Sidón, su primogénito, y de Het,'),
('nvi', 'Génesis 10:16', 'Génesis', 10, 16, 'y el antepasado de los jebuseos, los amorreos, los gergeseos,'),
('nvi', 'Génesis 10:17', 'Génesis', 10, 17, 'los heveos, los araceos, los sineos,'),
('nvi', 'Génesis 10:18', 'Génesis', 10, 18, 'los arvadeos, los zemareos y los jamatitas. Luego, estos clanes cananeos se dispersaron,'),
('nvi', 'Génesis 10:19', 'Génesis', 10, 19, 'y su territorio se extendió desde Sidón hasta Guerar y Gaza, y en dirección de Sodoma, Gomorra, Admá y Zeboyín, hasta Lasa.'),
('nvi', 'Génesis 10:20', 'Génesis', 10, 20, 'Éstos fueron los descendientes de Cam, según sus clanes e idiomas, territorios y naciones.'),
('nvi', 'Génesis 10:21', 'Génesis', 10, 21, 'Sem, antepasado de todos los hijos de Éber, y hermano mayor de Jafet, también tuvo hijos.'),
('nvi', 'Génesis 10:22', 'Génesis', 10, 22, 'Los hijos de Sem fueron Elam, Asur, Arfaxad, Lud y Aram.'),
('nvi', 'Génesis 10:23', 'Génesis', 10, 23, 'Los hijos de Aram fueron Uz, Hul, Guéter y Mas.'),
('nvi', 'Génesis 10:24', 'Génesis', 10, 24, 'Arfaxad fue el padre de Selaj. Selaj fue el padre de Éber.'),
('nvi', 'Génesis 10:25', 'Génesis', 10, 25, 'Éber tuvo dos hijos: el primero se llamó Péleg, porque en su tiempo se dividió la tierra; su hermano se llamó Joctán.'),
('nvi', 'Génesis 10:26', 'Génesis', 10, 26, 'Joctán fue el padre de Almodad, Sélef, Jazar Mávet, Yeraj,'),
('nvi', 'Génesis 10:27', 'Génesis', 10, 27, 'Hadorán, Uzal, Diclá,'),
('nvi', 'Génesis 10:28', 'Génesis', 10, 28, 'Obal, Abimael, Sabá,'),
('nvi', 'Génesis 10:29', 'Génesis', 10, 29, 'Ofir, Javilá y Jobab. Todos éstos fueron hijos de Joctán,'),
('nvi', 'Génesis 10:30', 'Génesis', 10, 30, 'y vivieron en la región que va desde Mesá hasta Sefar, en la región montañosa oriental.'),
('nvi', 'Génesis 10:31', 'Génesis', 10, 31, 'Éstos fueron los hijos de Sem, según sus clanes y sus idiomas, sus territorios y naciones.'),
('nvi', 'Génesis 10:32', 'Génesis', 10, 32, 'Éstos son los clanes de los hijos de Noé, según sus genealogías y sus naciones. A partir de estos clanes, las naciones se extendieron sobre la tierra después del diluvio.'),
('nvi', 'Génesis 11:1', 'Génesis', 11, 1, 'En ese entonces se hablaba un solo idioma en toda la tierra.'),
('nvi', 'Génesis 11:2', 'Génesis', 11, 2, 'Al emigrar al oriente, la gente encontró una llanura en la región de Sinar, y allí se asentaron.'),
('nvi', 'Génesis 11:3', 'Génesis', 11, 3, 'Un día se dijeron unos a otros: «Vamos a hacer ladrillos, y a cocerlos al fuego.» Fue así como usaron ladrillos en vez de piedras, y asfalto en vez de mezcla.'),
('nvi', 'Génesis 11:4', 'Génesis', 11, 4, 'Luego dijeron: «Construyamos una ciudad con una torre que llegue hasta el cielo. De ese modo nos haremos famosos y evitaremos ser dispersados por toda la tierra.»'),
('nvi', 'Génesis 11:5', 'Génesis', 11, 5, 'Pero el SEÑOR bajó para observar la ciudad y la torre que los hombres estaban construyendo,'),
('nvi', 'Génesis 11:6', 'Génesis', 11, 6, 'y se dijo: «Todos forman un solo pueblo y hablan un solo idioma; esto es sólo el comienzo de sus obras, y todo lo que se propongan lo podrán lograr.'),
('nvi', 'Génesis 11:7', 'Génesis', 11, 7, 'Será mejor que bajemos a confundir su idioma, para que ya no se entiendan entre ellos mismos.»'),
('nvi', 'Génesis 11:8', 'Génesis', 11, 8, 'De esta manera el SEÑOR los dispersó desde allí por toda la tierra, y por lo tanto dejaron de construir la ciudad.'),
('nvi', 'Génesis 11:9', 'Génesis', 11, 9, 'Por eso a la ciudad se le llamó Babel, porque fue allí donde el SEÑOR confundió el idioma de toda la gente de la tierra, y de donde los dispersó por todo el mundo.'),
('nvi', 'Génesis 11:10', 'Génesis', 11, 10, 'Ésta es la historia de Sem: Dos años después del diluvio, cuando Sem tenía cien años, nació su hijo Arfaxad.'),
('nvi', 'Génesis 11:11', 'Génesis', 11, 11, 'Después del nacimiento de Arfaxad, Sem vivió quinientos años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:12', 'Génesis', 11, 12, 'Cuando Arfaxad tenía treinta y cinco años, nació su hijo Selaj.'),
('nvi', 'Génesis 11:13', 'Génesis', 11, 13, 'Después del nacimiento de Selaj, Arfaxad vivió cuatrocientos tres años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:14', 'Génesis', 11, 14, 'Cuando Selaj tenía treinta años, nació su hijo Éber.'),
('nvi', 'Génesis 11:15', 'Génesis', 11, 15, 'Después del nacimiento de Éber, Selaj vivió cuatrocientos tres años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:16', 'Génesis', 11, 16, 'Cuando Éber tenía treinta y cuatro años, nació su hijo Péleg.'),
('nvi', 'Génesis 11:17', 'Génesis', 11, 17, 'Después del nacimiento de Péleg, Éber vivió cuatrocientos treinta años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:18', 'Génesis', 11, 18, 'Cuando Péleg tenía treinta años, nació su hijo Reú.'),
('nvi', 'Génesis 11:19', 'Génesis', 11, 19, 'Después del nacimiento de Reú, Péleg vivió doscientos nueve años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:20', 'Génesis', 11, 20, 'Cuando Reú tenía treinta y dos años, nació su hijo Serug.'),
('nvi', 'Génesis 11:21', 'Génesis', 11, 21, 'Después del nacimiento de Serug, Reú vivió doscientos siete años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:22', 'Génesis', 11, 22, 'Cuando Serug tenía treinta años, nació su hijo Najor.'),
('nvi', 'Génesis 11:23', 'Génesis', 11, 23, 'Después del nacimiento de Najor, Serug vivió doscientos años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:24', 'Génesis', 11, 24, 'Cuando Najor tenía veintinueve años, nació su hijo Téraj.'),
('nvi', 'Génesis 11:25', 'Génesis', 11, 25, 'Después del nacimiento de Téraj, Najor vivió ciento diecinueve años más, y tuvo otros hijos y otras hijas.'),
('nvi', 'Génesis 11:26', 'Génesis', 11, 26, 'Cuando Téraj tenía setenta años, ya habían nacido sus hijos Abram, Najor y Jarán.'),
('nvi', 'Génesis 11:27', 'Génesis', 11, 27, 'Ésta es la historia de Téraj, el padre de Abram, Najor y Jarán. Jarán fue el padre de Lot,'),
('nvi', 'Génesis 11:28', 'Génesis', 11, 28, 'y murió en Ur de los caldeos, su tierra natal, cuando su padre Téraj aún vivía.'),
('nvi', 'Génesis 11:29', 'Génesis', 11, 29, 'Abram se casó con Saray, y Najor se casó con Milca, la hija de Jarán, el cual tuvo otra hija llamada Iscá.'),
('nvi', 'Génesis 11:30', 'Génesis', 11, 30, 'Pero Saray era estéril; no podía tener hijos.'),
('nvi', 'Génesis 11:31', 'Génesis', 11, 31, 'Téraj salió de Ur de los caldeos rumbo a Canaán. Se fue con su hijo Abram, su nieto Lot y su nuera Saray, la esposa de Abram. Sin embargo, al llegar a la ciudad de Jarán, se quedaron a vivir en aquel lugar,'),
('nvi', 'Génesis 11:32', 'Génesis', 11, 32, 'y allí mismo murió Téraj a los doscientos años de edad.'),
('nvi', 'Génesis 12:1', 'Génesis', 12, 1, 'El SEÑOR le dijo a Abram: «Deja tu tierra, tus parientes y la casa de tu padre, y vete a la tierra que te mostraré.'),
('nvi', 'Génesis 12:2', 'Génesis', 12, 2, '»Haré de ti una nación grande, y te bendeciré; haré famoso tu nombre, y serás una bendición.'),
('nvi', 'Génesis 12:3', 'Génesis', 12, 3, 'Bendeciré a los que te bendigan y maldeciré a los que te maldigan; ¡por medio de ti serán bendecidas todas las familias de la tierra!»'),
('nvi', 'Génesis 12:4', 'Génesis', 12, 4, 'Abram partió, tal como el SEÑOR se lo había ordenado, y Lot se fue con él. Abram tenía setenta y cinco años cuando salió de Jarán.'),
('nvi', 'Génesis 12:5', 'Génesis', 12, 5, 'Al encaminarse hacia la tierra de Canaán, Abram se llevó a su esposa Saray, a su sobrino Lot, a toda la gente que habían adquirido en Jarán, y todos los bienes que habían acumulado. Cuando llegaron a Canaán,'),
('nvi', 'Génesis 12:6', 'Génesis', 12, 6, 'Abram atravesó toda esa región hasta llegar a Siquén, donde se encuentra la encina sagrada de Moré. En aquella época, los cananeos vivían en esa región.'),
('nvi', 'Génesis 12:7', 'Génesis', 12, 7, 'Allí el SEÑOR se le apareció a Abram y le dijo: «Yo le daré esta tierra a tu descendencia.» Entonces Abram erigió un altar al SEÑOR, porque se le había aparecido.'),
('nvi', 'Génesis 12:8', 'Génesis', 12, 8, 'De allí se dirigió a la región montañosa que está al este de Betel, donde armó su campamento, teniendo a Betel al oeste y Hai al este. También en ese lugar erigió un altar al SEÑOR e invocó su nombre.'),
('nvi', 'Génesis 12:9', 'Génesis', 12, 9, 'Después, Abram siguió su viaje por etapas hasta llegar a la región del Néguev.'),
('nvi', 'Génesis 12:10', 'Génesis', 12, 10, 'En ese entonces, hubo tanta hambre en aquella región que Abram se fue a vivir a Egipto.'),
('nvi', 'Génesis 12:11', 'Génesis', 12, 11, 'Cuando estaba por entrar a Egipto, le dijo a su esposa Saray: «Yo sé que eres una mujer muy hermosa.'),
('nvi', 'Génesis 12:12', 'Génesis', 12, 12, 'Estoy seguro que en cuanto te vean los egipcios, dirán: “Es su esposa”; entonces a mí me matarán, pero a ti te dejarán con vida.'),
('nvi', 'Génesis 12:13', 'Génesis', 12, 13, 'Por favor, di que eres mi hermana, para que gracias a ti me vaya bien y me dejen con vida.»'),
('nvi', 'Génesis 12:14', 'Génesis', 12, 14, 'Cuando Abram llegó a Egipto, los egipcios vieron que Saray era muy hermosa.'),
('nvi', 'Génesis 12:15', 'Génesis', 12, 15, 'También los funcionarios del faraón la vieron, y fueron a contarle al faraón lo hermosa que era. Entonces la llevaron al palacio real.'),
('nvi', 'Génesis 12:16', 'Génesis', 12, 16, 'Gracias a ella trataron muy bien a Abram. Le dieron ovejas, vacas, esclavos y esclavas, asnos y asnas, y camellos.'),
('nvi', 'Génesis 12:17', 'Génesis', 12, 17, 'Pero por causa de Saray, la esposa de Abram, el SEÑOR castigó al faraón y a su familia con grandes plagas.'),
('nvi', 'Génesis 12:18', 'Génesis', 12, 18, 'Entonces el faraón llamó a Abram y le dijo: «¿Qué me has hecho? ¿Por qué no me dijiste que era tu esposa?'),
('nvi', 'Génesis 12:19', 'Génesis', 12, 19, '¿Por qué dijiste que era tu hermana? ¡Yo pude haberla tomado por esposa! ¡Anda, toma a tu esposa y vete!»'),
('nvi', 'Génesis 12:20', 'Génesis', 12, 20, 'Y el faraón ordenó a sus hombres que expulsaran a Abram y a su esposa, junto con todos sus bienes.'),
('nvi', 'Génesis 13:1', 'Génesis', 13, 1, 'Abram salió de Egipto con su esposa, con Lot y con todos sus bienes, en dirección a la región del Néguev.'),
('nvi', 'Génesis 13:2', 'Génesis', 13, 2, 'Abram se había hecho muy rico en ganado, plata y oro.'),
('nvi', 'Génesis 13:3', 'Génesis', 13, 3, 'Desde el Néguev, Abram regresó por etapas hasta Betel, es decir, hasta el lugar donde había acampado al principio, entre Betel y Hai.'),
('nvi', 'Génesis 13:4', 'Génesis', 13, 4, 'En ese lugar había erigido antes un altar, y allí invocó Abram el nombre del SEÑOR.'),
('nvi', 'Génesis 13:5', 'Génesis', 13, 5, 'También Lot, que iba acompañando a Abram, tenía rebaños, ganado y tiendas de campaña.'),
('nvi', 'Génesis 13:6', 'Génesis', 13, 6, 'La región donde estaban no daba abasto para mantener a los dos, porque tenían demasiado como para vivir juntos.'),
('nvi', 'Génesis 13:7', 'Génesis', 13, 7, 'Por eso comenzaron las fricciones entre los pastores de los rebaños de Abram y los que cuidaban los ganados de Lot. Además, los cananeos y los ferezeos también habitaban allí en aquel tiempo.'),
('nvi', 'Génesis 13:8', 'Génesis', 13, 8, 'Así que Abram le dijo a Lot: «No debe haber pleitos entre nosotros, ni entre nuestros pastores, porque somos parientes.'),
('nvi', 'Génesis 13:9', 'Génesis', 13, 9, 'Allí tienes toda la tierra a tu disposición. Por favor, aléjate de mí. Si te vas a la izquierda, yo me iré a la derecha, y si te vas a la derecha, yo me iré a la izquierda.»'),
('nvi', 'Génesis 13:10', 'Génesis', 13, 10, 'Lot levantó la vista y observó que todo el valle del Jordán, hasta Zoar, era tierra de regadío, como el jardín del SEÑOR o como la tierra de Egipto. Así era antes de que el SEÑOR destruyera a Sodoma y a Gomorra.'),
('nvi', 'Génesis 13:11', 'Génesis', 13, 11, 'Entonces Lot escogió para sí todo el valle del Jordán, y partió hacia el oriente. Fue así como Abram y Lot se separaron.'),
('nvi', 'Génesis 13:12', 'Génesis', 13, 12, 'Abram se quedó a vivir en la tierra de Canaán, mientras que Lot se fue a vivir entre las ciudades del valle, estableciendo su campamento cerca de la ciudad de Sodoma.'),
('nvi', 'Génesis 13:13', 'Génesis', 13, 13, 'Los habitantes de Sodoma eran malvados y cometían muy graves pecados contra el SEÑOR.'),
('nvi', 'Génesis 13:14', 'Génesis', 13, 14, 'Después de que Lot se separó de Abram, el SEÑOR le dijo: «Abram, levanta la vista desde el lugar donde estás, y mira hacia el norte y hacia el sur, hacia el este y hacia el oeste.'),
('nvi', 'Génesis 13:15', 'Génesis', 13, 15, 'Yo te daré a ti y a tu descendencia, para siempre, toda la tierra que abarca tu mirada.'),
('nvi', 'Génesis 13:16', 'Génesis', 13, 16, 'Multiplicaré tu descendencia como el polvo de la tierra. Si alguien puede contar el polvo de la tierra, también podrá contar tus descendientes.'),
('nvi', 'Génesis 13:17', 'Génesis', 13, 17, '¡Ve y recorre el país a lo largo y a lo ancho, porque a ti te lo daré!»'),
('nvi', 'Génesis 13:18', 'Génesis', 13, 18, 'Entonces Abram levantó su campamento y se fue a vivir cerca de Hebrón, junto al encinar de Mamré. Allí erigió un altar al SEÑOR.'),
('nvi', 'Génesis 14:1', 'Génesis', 14, 1, 'En aquel tiempo los reyes Amrafel de Sinar, Arioc de Elasar, Quedorlaómer de Elam, y Tidal de Goyim'),
('nvi', 'Génesis 14:2', 'Génesis', 14, 2, 'estuvieron en guerra contra los reyes Bera de Sodoma, Birsá de Gomorra, Sinab de Admá, Semeber de Zeboyín, y el rey de Bela, es decir, de Zoar.'),
('nvi', 'Génesis 14:3', 'Génesis', 14, 3, 'Estos cinco últimos aunaron fuerzas en el valle de Sidín, conocido como el Mar Muerto.'),
('nvi', 'Génesis 14:4', 'Génesis', 14, 4, 'Durante doce años habían estado bajo el dominio de Quedorlaómer, pero en el año trece se rebelaron contra él.'),
('nvi', 'Génesis 14:5', 'Génesis', 14, 5, 'Al año siguiente, Quedorlaómer y los reyes que estaban con él salieron y derrotaron a los refaítas en la región de Astarot Carnayin; luego derrotaron a los zuzitas en Jam, a los emitas en Save Quiriatayin,'),
('nvi', 'Génesis 14:6', 'Génesis', 14, 6, 'y a los horeos en los montes de Seír, hasta El Parán, que está cerca del desierto.'),
('nvi', 'Génesis 14:7', 'Génesis', 14, 7, 'Al volver, llegaron hasta Enmispat, es decir, Cades, y conquistaron todo el territorio de los amalecitas, y también el de los amorreos que vivían en la región de Jazezón Tamar.'),
('nvi', 'Génesis 14:8', 'Génesis', 14, 8, 'Entonces los reyes de Sodoma, Gomorra, Admá, Zeboyín y Bela, es decir, Zoar, salieron al valle de Sidín y presentaron batalla'),
('nvi', 'Génesis 14:9', 'Génesis', 14, 9, 'a los reyes Quedorlaómer de Elam, Tidal de Goyim, Amrafel de Sinar, y Arioc de Elasar. Eran cuatro reyes contra cinco.'),
('nvi', 'Génesis 14:10', 'Génesis', 14, 10, 'El valle de Sidín estaba lleno de pozos de asfalto, y cuando los reyes de Sodoma y Gomorra huyeron, se cayeron en ellos, pero los demás lograron escapar hacia los montes.'),
('nvi', 'Génesis 14:11', 'Génesis', 14, 11, 'Los vencedores saquearon todos los bienes de Sodoma y de Gomorra, junto con todos los alimentos, y luego se retiraron.'),
('nvi', 'Génesis 14:12', 'Génesis', 14, 12, 'Y como Lot, el sobrino de Abram, habitaba en Sodoma, también se lo llevaron a él, con todas sus posesiones.'),
('nvi', 'Génesis 14:13', 'Génesis', 14, 13, 'Uno de los que habían escapado le informó todo esto a Abram el hebreo, que estaba acampando junto al encinar de Mamré el amorreo. Mamré era hermano de Escol y de Aner, y éstos eran aliados de Abram.'),
('nvi', 'Génesis 14:14', 'Génesis', 14, 14, 'En cuanto Abram supo que su sobrino estaba cautivo, convocó a trescientos dieciocho hombres adiestrados que habían nacido en su casa, y persiguió a los invasores hasta Dan.'),
('nvi', 'Génesis 14:15', 'Génesis', 14, 15, 'Durante la noche Abram y sus siervos desplegaron sus fuerzas y los derrotaron, persiguiéndolos hasta Hobá, que está al norte de Damasco.'),
('nvi', 'Génesis 14:16', 'Génesis', 14, 16, 'Así recuperó todos los bienes, y también rescató a su sobrino Lot, junto con sus posesiones, las mujeres y la demás gente.'),
('nvi', 'Génesis 14:17', 'Génesis', 14, 17, 'Cuando Abram volvía de derrotar a Quedorlaómer y a los reyes que estaban con él, el rey de Sodoma salió a su encuentro en el valle de Save, es decir, en el valle del Rey.'),
('nvi', 'Génesis 14:18', 'Génesis', 14, 18, 'Y Melquisedec, rey de Salén y sacerdote del Dios altísimo, le ofreció pan y vino.'),
('nvi', 'Génesis 14:19', 'Génesis', 14, 19, 'Luego bendijo a Abram con estas palabras: «¡Que el Dios altísimo, creador del cielo y de la tierra, bendiga a Abram!'),
('nvi', 'Génesis 14:20', 'Génesis', 14, 20, '¡Bendito sea el Dios altísimo, que entregó en tus manos a tus enemigos!» Entonces Abram le dio el diezmo de todo.'),
('nvi', 'Génesis 14:21', 'Génesis', 14, 21, 'El rey de Sodoma le dijo a Abram: —Dame las personas y quédate con los bienes.'),
('nvi', 'Génesis 14:22', 'Génesis', 14, 22, 'Pero Abram le contestó: —He jurado por el SEÑOR, el Dios altísimo, creador del cielo y de la tierra,'),
('nvi', 'Génesis 14:23', 'Génesis', 14, 23, 'que no tomaré nada de lo que es tuyo, ni siquiera un hilo ni la correa de una sandalia. Así nunca podrás decir: “Yo hice rico a Abram.”'),
('nvi', 'Génesis 14:24', 'Génesis', 14, 24, 'No quiero nada para mí, salvo lo que mis hombres ya han comido. En cuanto a los hombres que me acompañaron, es decir, Aner, Escol y Mamré, que tomen ellos su parte.'),
('nvi', 'Génesis 15:1', 'Génesis', 15, 1, 'Después de esto, la palabra del SEÑOR vino a Abram en una visión: «No temas, Abram. Yo soy tu escudo, y muy grande será tu recompensa.»'),
('nvi', 'Génesis 15:2', 'Génesis', 15, 2, 'Pero Abram le respondió: —SEÑOR y Dios, ¿para qué vas a darme algo, si aún sigo sin tener hijos, y el heredero de mis bienes será Eliezer de Damasco?'),
('nvi', 'Génesis 15:3', 'Génesis', 15, 3, 'Como no me has dado ningún hijo, mi herencia la recibirá uno de mis criados.'),
('nvi', 'Génesis 15:4', 'Génesis', 15, 4, '—¡No! Ese hombre no ha de ser tu heredero —le contestó el SEÑOR—. Tu heredero será tu propio hijo.'),
('nvi', 'Génesis 15:5', 'Génesis', 15, 5, 'Luego el SEÑOR lo llevó afuera y le dijo: —Mira hacia el cielo y cuenta las estrellas, a ver si puedes. ¡Así de numerosa será tu descendencia!'),
('nvi', 'Génesis 15:6', 'Génesis', 15, 6, 'Abram creyó al SEÑOR, y el SEÑOR lo reconoció a él como justo.'),
('nvi', 'Génesis 15:7', 'Génesis', 15, 7, 'Además, le dijo: —Yo soy el SEÑOR, que te hice salir de Ur de los caldeos para darte en posesión esta tierra.'),
('nvi', 'Génesis 15:8', 'Génesis', 15, 8, 'Pero Abram le preguntó: —SEÑOR y Dios, ¿cómo sabré que voy a poseerla?'),
('nvi', 'Génesis 15:9', 'Génesis', 15, 9, 'El SEÑOR le respondió: —Tráeme una ternera, una cabra y un carnero, todos ellos de tres años, y también una tórtola y un pichón de paloma.'),
('nvi', 'Génesis 15:10', 'Génesis', 15, 10, 'Abram llevó todos estos animales, los partió por la mitad, y puso una mitad frente a la otra, pero a las aves no las partió.'),
('nvi', 'Génesis 15:11', 'Génesis', 15, 11, 'Y las aves de rapiña comenzaron a lanzarse sobre los animales muertos, pero Abram las espantaba.'),
('nvi', 'Génesis 15:12', 'Génesis', 15, 12, 'Al anochecer, Abram cayó en un profundo sueño, y lo envolvió una oscuridad aterradora.'),
('nvi', 'Génesis 15:13', 'Génesis', 15, 13, 'El SEÑOR le dijo: —Debes saber que tus descendientes vivirán como extranjeros en tierra extraña, donde serán esclavizados y maltratados durante cuatrocientos años.'),
('nvi', 'Génesis 15:14', 'Génesis', 15, 14, 'Pero yo castigaré a la nación que los esclavizará, y luego tus descendientes saldrán en libertad y con grandes riquezas.'),
('nvi', 'Génesis 15:15', 'Génesis', 15, 15, 'Tú, en cambio, te reunirás en paz con tus antepasados, y te enterrarán cuando ya seas muy anciano.'),
('nvi', 'Génesis 15:16', 'Génesis', 15, 16, 'Cuatro generaciones después tus descendientes volverán a este lugar, porque antes de eso no habrá llegado al colmo la iniquidad de los amorreos.'),
('nvi', 'Génesis 15:17', 'Génesis', 15, 17, 'Cuando el sol se puso y cayó la noche, aparecieron una hornilla humeante y una antorcha encendida, las cuales pasaban entre los animales descuartizados.'),
('nvi', 'Génesis 15:18', 'Génesis', 15, 18, 'En aquel día el SEÑOR hizo un pacto con Abram. Le dijo: —A tus descendientes les daré esta tierra, desde el río de Egipto hasta el gran río, el Éufrates.'),
('nvi', 'Génesis 15:19', 'Génesis', 15, 19, 'Me refiero a la tierra de los quenitas, los quenizitas, los cadmoneos,'),
('nvi', 'Génesis 15:20', 'Génesis', 15, 20, 'los hititas, los ferezeos, los refaítas,'),
('nvi', 'Génesis 15:21', 'Génesis', 15, 21, 'los amorreos, los cananeos, los gergeseos y los jebuseos.'),
('nvi', 'Génesis 16:1', 'Génesis', 16, 1, 'Saray, la esposa de Abram, no le había dado hijos. Pero como tenía una esclava egipcia llamada Agar,'),
('nvi', 'Génesis 16:2', 'Génesis', 16, 2, 'Saray le dijo a Abram: —El SEÑOR me ha hecho estéril. Por lo tanto, ve y acuéstate con mi esclava Agar. Tal vez por medio de ella podré tener hijos. Abram aceptó la propuesta que le hizo Saray.'),
('nvi', 'Génesis 16:3', 'Génesis', 16, 3, 'Entonces ella tomó a Agar, la esclava egipcia, y se la entregó a Abram como mujer. Esto ocurrió cuando ya hacía diez años que Abram vivía en Canaán.'),
('nvi', 'Génesis 16:4', 'Génesis', 16, 4, 'Abram tuvo relaciones con Agar, y ella concibió un hijo. Al darse cuenta Agar de que estaba embarazada, comenzó a mirar con desprecio a su dueña.'),
('nvi', 'Génesis 16:5', 'Génesis', 16, 5, 'Entonces Saray le dijo a Abram: —¡Tú tienes la culpa de mi afrenta! Yo puse a mi esclava en tus brazos, y ahora que se ve embarazada me mira con desprecio. ¡Que el SEÑOR juzgue entre tú y yo!'),
('nvi', 'Génesis 16:6', 'Génesis', 16, 6, '—Tu esclava está en tus manos —contestó Abram—; haz con ella lo que bien te parezca. Y de tal manera comenzó Saray a maltratar a Agar, que ésta huyó al desierto.'),
('nvi', 'Génesis 16:7', 'Génesis', 16, 7, 'Allí, junto a un manantial que está en el camino a la región de Sur, la encontró el ángel del SEÑOR'),
('nvi', 'Génesis 16:8', 'Génesis', 16, 8, 'y le preguntó: —Agar, esclava de Saray, ¿de dónde vienes y a dónde vas? —Estoy huyendo de mi dueña Saray —respondió ella.'),
('nvi', 'Génesis 16:9', 'Génesis', 16, 9, '—Vuelve junto a ella y sométete a su autoridad —le dijo el ángel—.'),
('nvi', 'Génesis 16:10', 'Génesis', 16, 10, 'De tal manera multiplicaré tu descendencia, que no se podrá contar.'),
('nvi', 'Génesis 16:11', 'Génesis', 16, 11, '»Estás embarazada, y darás a luz un hijo, y le pondrás por nombre Ismael, porque el SEÑOR ha escuchado tu aflicción.'),
('nvi', 'Génesis 16:12', 'Génesis', 16, 12, 'Será un hombre indómito como asno salvaje. Luchará contra todos, y todos lucharán contra él; y vivirá en conflicto con todos sus hermanos.'),
('nvi', 'Génesis 16:13', 'Génesis', 16, 13, 'Como el SEÑOR le había hablado, Agar le puso por nombre «El Dios que me ve», pues se decía: «Ahora he visto al que me ve.»'),
('nvi', 'Génesis 16:14', 'Génesis', 16, 14, 'Por eso también el pozo que está entre Cades y Béred se conoce con el nombre de «Pozo del Viviente que me ve».'),
('nvi', 'Génesis 16:15', 'Génesis', 16, 15, 'Agar le dio a Abram un hijo, a quien Abram llamó Ismael.'),
('nvi', 'Génesis 16:16', 'Génesis', 16, 16, 'Abram tenía ochenta y seis años cuando nació Ismael.'),
('nvi', 'Génesis 17:1', 'Génesis', 17, 1, 'Cuando Abram tenía noventa y nueve años, el SEÑOR se le apareció y le dijo: —Yo soy el Dios Todopoderoso. Vive en mi presencia y sé intachable.'),
('nvi', 'Génesis 17:2', 'Génesis', 17, 2, 'Así confirmaré mi pacto contigo, y multiplicaré tu descendencia en gran manera.'),
('nvi', 'Génesis 17:3', 'Génesis', 17, 3, 'Al oír que Dios le hablaba, Abram cayó rostro en tierra, y Dios continuó:'),
('nvi', 'Génesis 17:4', 'Génesis', 17, 4, '—Éste es el pacto que establezco contigo: Tú serás el padre de una multitud de naciones.'),
('nvi', 'Génesis 17:5', 'Génesis', 17, 5, 'Ya no te llamarás Abram, sino que de ahora en adelante tu nombre será Abraham, porque te he confirmado como padre de una multitud de naciones.'),
('nvi', 'Génesis 17:6', 'Génesis', 17, 6, 'Te haré tan fecundo que de ti saldrán reyes y naciones.'),
('nvi', 'Génesis 17:7', 'Génesis', 17, 7, 'Estableceré mi pacto contigo y con tu descendencia, como pacto perpetuo, por todas las generaciones. Yo seré tu Dios, y el Dios de tus descendientes.'),
('nvi', 'Génesis 17:8', 'Génesis', 17, 8, 'A ti y a tu descendencia les daré, en posesión perpetua, toda la tierra de Canaán, donde ahora andan peregrinando. Y yo seré su Dios.'),
('nvi', 'Génesis 17:9', 'Génesis', 17, 9, 'Dios también le dijo a Abraham: —Cumple con mi pacto, tú y toda tu descendencia, por todas las generaciones.'),
('nvi', 'Génesis 17:10', 'Génesis', 17, 10, 'Y éste es el pacto que establezco contigo y con tu descendencia, y que todos deberán cumplir: Todos los varones entre ustedes deberán ser circuncidados.'),
('nvi', 'Génesis 17:11', 'Génesis', 17, 11, 'Circuncidarán la carne de su prepucio, y ésa será la señal del pacto entre nosotros.'),
('nvi', 'Génesis 17:12', 'Génesis', 17, 12, 'Todos los varones de cada generación deberán ser circuncidados a los ocho días de nacidos, tanto los niños nacidos en casa como los que hayan sido comprados por dinero a un extranjero y que, por lo tanto, no sean de la estirpe de ustedes.'),
('nvi', 'Génesis 17:13', 'Génesis', 17, 13, 'Todos sin excepción, tanto el nacido en casa como el que haya sido comprado por dinero, deberán ser circuncidados. De esta manera mi pacto quedará como una marca indeleble en la carne de ustedes, como un pacto perpetuo.'),
('nvi', 'Génesis 17:14', 'Génesis', 17, 14, 'Pero el varón incircunciso, al que no se le haya cortado la carne del prepucio, será eliminado de su pueblo por quebrantar mi pacto.'),
('nvi', 'Génesis 17:15', 'Génesis', 17, 15, 'También le dijo Dios a Abraham: —A Saray, tu esposa, ya no la llamarás Saray, sino que su nombre será Sara.'),
('nvi', 'Génesis 17:16', 'Génesis', 17, 16, 'Yo la bendeciré, y por medio de ella te daré un hijo. Tanto la bendeciré, que será madre de naciones, y de ella surgirán reyes de pueblos.'),
('nvi', 'Génesis 17:17', 'Génesis', 17, 17, 'Entonces Abraham inclinó el rostro hasta el suelo y se rió de pensar: «¿Acaso puede un hombre tener un hijo a los cien años, y ser madre Sara a los noventa?»'),
('nvi', 'Génesis 17:18', 'Génesis', 17, 18, 'Por eso le dijo a Dios: —¡Concédele a Ismael vivir bajo tu bendición!'),
('nvi', 'Génesis 17:19', 'Génesis', 17, 19, 'A lo que Dios contestó: —¡Pero es Sara, tu esposa, la que te dará un hijo, al que llamarás Isaac! Yo estableceré mi pacto con él y con sus descendientes, como pacto perpetuo.'),
('nvi', 'Génesis 17:20', 'Génesis', 17, 20, 'En cuanto a Ismael, ya te he escuchado. Yo lo bendeciré, lo haré fecundo y le daré una descendencia numerosa. Él será el padre de doce príncipes. Haré de él una nación muy grande.'),
('nvi', 'Génesis 17:21', 'Génesis', 17, 21, 'Pero mi pacto lo estableceré con Isaac, el hijo que te dará Sara de aquí a un año, por estos días.'),
('nvi', 'Génesis 17:22', 'Génesis', 17, 22, 'Cuando Dios terminó de hablar con Abraham, se retiró de su presencia.'),
('nvi', 'Génesis 17:23', 'Génesis', 17, 23, 'Ese mismo día Abraham tomó a su hijo Ismael, a los criados nacidos en su casa, a los que había comprado con su dinero y a todos los otros varones que había en su casa, y los circuncidó, tal como Dios se lo había mandado.'),
('nvi', 'Génesis 17:24', 'Génesis', 17, 24, 'Abraham tenía noventa y nueve años cuando fue circuncidado,'),
('nvi', 'Génesis 17:25', 'Génesis', 17, 25, 'mientras que su hijo Ismael tenía trece.'),
('nvi', 'Génesis 17:26', 'Génesis', 17, 26, 'Así que ambos fueron circuncidados el mismo día'),
('nvi', 'Génesis 17:27', 'Génesis', 17, 27, 'junto con todos los varones de su casa, tanto los nacidos en ella como los comprados a extranjeros.'),
('nvi', 'Génesis 18:1', 'Génesis', 18, 1, 'El SEÑOR se le apareció a Abraham junto al encinar de Mamré, cuando Abraham estaba sentado a la entrada de su carpa, a la hora más calurosa del día.'),
('nvi', 'Génesis 18:2', 'Génesis', 18, 2, 'Abraham alzó la vista, y vio a tres hombres de pie cerca de él. Al verlos, corrió desde la entrada de la carpa a saludarlos. Inclinándose hasta el suelo,'),
('nvi', 'Génesis 18:3', 'Génesis', 18, 3, 'dijo: —Mi señor, si este servidor suyo cuenta con su favor, le ruego que no me pase de largo.'),
('nvi', 'Génesis 18:4', 'Génesis', 18, 4, 'Haré que les traigan un poco de agua para que ustedes se laven los pies, y luego podrán descansar bajo el árbol.'),
('nvi', 'Génesis 18:5', 'Génesis', 18, 5, 'Ya que han pasado por donde está su servidor, déjenme traerles algo de comer para que se sientan mejor antes de seguir su camino. —¡Está bien —respondieron ellos—, hazlo así!'),
('nvi', 'Génesis 18:6', 'Génesis', 18, 6, 'Abraham fue rápidamente a la carpa donde estaba Sara, y le dijo: —¡Date prisa! Toma unos veinte kilos de harina fina, amásalos y haz unos panes.'),
('nvi', 'Génesis 18:7', 'Génesis', 18, 7, 'Después Abraham fue corriendo adonde estaba el ganado, eligió un ternero bueno y tierno, y se lo dio a su sirviente, quien a toda prisa se puso a prepararlo.'),
('nvi', 'Génesis 18:8', 'Génesis', 18, 8, 'Luego les sirvió requesón y leche con el ternero que estaba preparado. Mientras comían, Abraham se quedó de pie junto a ellos, debajo del árbol.'),
('nvi', 'Génesis 18:9', 'Génesis', 18, 9, 'Entonces ellos le preguntaron: —¿Dónde está Sara, tu esposa? —Allí en la carpa —les respondió.'),
('nvi', 'Génesis 18:10', 'Génesis', 18, 10, '—Dentro de un año volveré a verte —dijo uno de ellos—, y para entonces tu esposa Sara tendrá un hijo. Sara estaba escuchando a la entrada de la carpa, a espaldas del que hablaba.'),
('nvi', 'Génesis 18:11', 'Génesis', 18, 11, 'Abraham y Sara eran ya bastante ancianos, y Sara ya había dejado de menstruar.'),
('nvi', 'Génesis 18:12', 'Génesis', 18, 12, 'Por eso, Sara se rió y pensó: «¿Acaso voy a tener este placer, ahora que ya estoy consumida y mi esposo es tan viejo?»'),
('nvi', 'Génesis 18:13', 'Génesis', 18, 13, 'Pero el SEÑOR le dijo a Abraham: —¿Por qué se ríe Sara? ¿No cree que podrá tener un hijo en su vejez?'),
('nvi', 'Génesis 18:14', 'Génesis', 18, 14, '¿Acaso hay algo imposible para el SEÑOR? El año que viene volveré a visitarte en esta fecha, y para entonces Sara habrá tenido un hijo.'),
('nvi', 'Génesis 18:15', 'Génesis', 18, 15, 'Sara, por su parte, tuvo miedo y mintió al decirle: —Yo no me estaba riendo. Pero el SEÑOR le replicó: —Sí te reíste.'),
('nvi', 'Génesis 18:16', 'Génesis', 18, 16, 'Luego aquellos visitantes se levantaron y partieron de allí en dirección a Sodoma. Abraham los acompañó para despedirlos.'),
('nvi', 'Génesis 18:17', 'Génesis', 18, 17, 'Pero el SEÑOR estaba pensando: «¿Le ocultaré a Abraham lo que estoy por hacer?'),
('nvi', 'Génesis 18:18', 'Génesis', 18, 18, 'Es un hecho que Abraham se convertirá en una nación grande y poderosa, y en él serán bendecidas todas las naciones de la tierra.'),
('nvi', 'Génesis 18:19', 'Génesis', 18, 19, 'Yo lo he elegido para que instruya a sus hijos y a su familia, a fin de que se mantengan en el camino del SEÑOR y pongan en práctica lo que es justo y recto. Así el SEÑOR cumplirá lo que le ha prometido.»'),
('nvi', 'Génesis 18:20', 'Génesis', 18, 20, 'Entonces el SEÑOR le dijo a Abraham: —El clamor contra Sodoma y Gomorra resulta ya insoportable, y su pecado es gravísimo.'),
('nvi', 'Génesis 18:21', 'Génesis', 18, 21, 'Por eso bajaré, a ver si realmente sus acciones son tan malas como el clamor contra ellas me lo indica; y si no, he de saberlo.'),
('nvi', 'Génesis 18:22', 'Génesis', 18, 22, 'Dos de los visitantes partieron de allí y se encaminaron a Sodoma, pero Abraham se quedó de pie frente al SEÑOR.'),
('nvi', 'Génesis 18:23', 'Génesis', 18, 23, 'Entonces se acercó al SEÑOR y le dijo: —¿De veras vas a exterminar al justo junto con el malvado?'),
('nvi', 'Génesis 18:24', 'Génesis', 18, 24, 'Quizá haya cincuenta justos en la ciudad. ¿Exterminarás a todos, y no perdonarás a ese lugar por amor a los cincuenta justos que allí hay?'),
('nvi', 'Génesis 18:25', 'Génesis', 18, 25, '¡Lejos de ti el hacer tal cosa! ¿Matar al justo junto con el malvado, y que ambos sean tratados de la misma manera? ¡Jamás hagas tal cosa! Tú, que eres el Juez de toda la tierra, ¿no harás justicia?'),
('nvi', 'Génesis 18:26', 'Génesis', 18, 26, 'El SEÑOR le respondió: —Si encuentro cincuenta justos en Sodoma, por ellos perdonaré a toda la ciudad.'),
('nvi', 'Génesis 18:27', 'Génesis', 18, 27, 'Abraham le dijo: —Reconozco que he sido muy atrevido al dirigirme a mi SEÑOR, yo, que apenas soy polvo y ceniza.'),
('nvi', 'Génesis 18:28', 'Génesis', 18, 28, 'Pero tal vez falten cinco justos para completar los cincuenta. ¿Destruirás a toda la ciudad si faltan esos cinco? —Si encuentro cuarenta y cinco justos no la destruiré —contestó el SEÑOR.'),
('nvi', 'Génesis 18:29', 'Génesis', 18, 29, 'Pero Abraham insistió: —Tal vez se encuentren sólo cuarenta. —Por esos cuarenta justos, no destruiré la ciudad —respondió el SEÑOR.'),
('nvi', 'Génesis 18:30', 'Génesis', 18, 30, 'Abraham volvió a insistir: —No se enoje mi SEÑOR, pero permítame seguir hablando. Tal vez se encuentren sólo treinta. —No lo haré si encuentro allí a esos treinta —contestó el SEÑOR.'),
('nvi', 'Génesis 18:31', 'Génesis', 18, 31, 'Abraham siguió insistiendo: —Sé que he sido muy atrevido en hablarle así a mi SEÑOR, pero tal vez se encuentren sólo veinte. —Por esos veinte no la destruiré.'),
('nvi', 'Génesis 18:32', 'Génesis', 18, 32, 'Abraham volvió a decir: —No se enoje mi SEÑOR, pero permítame hablar una vez más. Tal vez se encuentren sólo diez... —Aun por esos diez no la destruiré —respondió el SEÑOR por última vez.'),
('nvi', 'Génesis 18:33', 'Génesis', 18, 33, 'Cuando el SEÑOR terminó de hablar con Abraham, se fue de allí, y Abraham regresó a su carpa.'),
('nvi', 'Génesis 19:1', 'Génesis', 19, 1, 'Caía la tarde cuando los dos ángeles llegaron a Sodoma. Lot estaba sentado a la entrada de la ciudad. Al verlos, se levantó para recibirlos y se postró rostro en tierra.'),
('nvi', 'Génesis 19:2', 'Génesis', 19, 2, 'Les dijo: —Por favor, señores, les ruego que pasen la noche en la casa de este servidor suyo. Allí podrán lavarse los pies, y mañana al amanecer seguirán su camino. —No, gracias —respondieron ellos—. Pasaremos la noche en la plaza.'),
('nvi', 'Génesis 19:3', 'Génesis', 19, 3, 'Pero tanto les insistió Lot que fueron con él y entraron en su casa. Allí Lot les preparó una buena comida y coció panes sin levadura, y ellos comieron.'),
('nvi', 'Génesis 19:4', 'Génesis', 19, 4, 'Aún no se habían acostado cuando los hombres de la ciudad de Sodoma rodearon la casa. Todo el pueblo sin excepción, tanto jóvenes como ancianos, estaba allí presente.'),
('nvi', 'Génesis 19:5', 'Génesis', 19, 5, 'Llamaron a Lot y le dijeron: —¿Dónde están los hombres que vinieron a pasar la noche en tu casa? ¡Échalos afuera! ¡Queremos acostarnos con ellos!'),
('nvi', 'Génesis 19:6', 'Génesis', 19, 6, 'Lot salió a la puerta y, cerrándola detrás de sí,'),
('nvi', 'Génesis 19:7', 'Génesis', 19, 7, 'les dijo: —Por favor, amigos míos, no cometan tal perversidad.'),
('nvi', 'Génesis 19:8', 'Génesis', 19, 8, 'Tengo dos hijas que todavía son vírgenes; voy a traérselas para que hagan con ellas lo que les plazca, pero a estos hombres no les hagan nada, pues han venido a hospedarse bajo mi techo.'),
('nvi', 'Génesis 19:9', 'Génesis', 19, 9, '—¡Quítate de ahí! —le contestaron, y añadieron—: Éste ni siquiera es de aquí, y ahora nos quiere mandar. ¡Pues ahora te vamos a tratar peor que a ellos! Entonces se lanzaron contra Lot y se acercaron a la puerta con intenciones de derribarla.'),
('nvi', 'Génesis 19:10', 'Génesis', 19, 10, 'Pero los dos hombres extendieron los brazos, metieron a Lot en la casa y cerraron la puerta.'),
('nvi', 'Génesis 19:11', 'Génesis', 19, 11, 'Luego, a los jóvenes y ancianos que se agolparon contra la puerta de la casa los dejaron ciegos, de modo que ya no podían encontrar la puerta.'),
('nvi', 'Génesis 19:12', 'Génesis', 19, 12, 'Luego le advirtieron a Lot: —¿Tienes otros familiares aquí? Saca de esta ciudad a tus yernos, hijos, hijas, y a todos los que te pertenezcan,'),
('nvi', 'Génesis 19:13', 'Génesis', 19, 13, 'porque vamos a destruirla. El clamor contra esta gente ha llegado hasta el SEÑOR, y ya resulta insoportable. Por eso nos ha enviado a destruirla.'),
('nvi', 'Génesis 19:14', 'Génesis', 19, 14, 'Lot salió para hablar con sus futuros yernos, es decir, con los prometidos de sus hijas. —¡Apúrense! —les dijo—. ¡Abandonen la ciudad, porque el SEÑOR está por destruirla! Pero ellos creían que Lot estaba bromeando,'),
('nvi', 'Génesis 19:15', 'Génesis', 19, 15, 'así que al amanecer los ángeles insistieron con Lot. Exclamaron: —¡Apúrate! Llévate a tu esposa y a tus dos hijas que están aquí, para que no perezcan cuando la ciudad sea castigada.'),
('nvi', 'Génesis 19:16', 'Génesis', 19, 16, 'Como Lot titubeaba, los hombres lo tomaron de la mano, lo mismo que a su esposa y a sus dos hijas, y los sacaron de la ciudad, porque el SEÑOR les tuvo compasión.'),
('nvi', 'Génesis 19:17', 'Génesis', 19, 17, 'Cuando ya los habían sacado de la ciudad, uno de los ángeles le dijo: —¡Escápate! No mires hacia atrás, ni te detengas en ninguna parte del valle. Huye hacia las montañas, no sea que perezcas.'),
('nvi', 'Génesis 19:18', 'Génesis', 19, 18, '—¡No, señor mío, por favor! —respondió Lot—.'),
('nvi', 'Génesis 19:19', 'Génesis', 19, 19, 'Tú has visto con buenos ojos a este siervo tuyo, y tu lealtad ha sido grande al salvarme la vida. Pero yo no puedo escaparme a las montañas, no sea que la destrucción me alcance y pierda yo la vida.'),
('nvi', 'Génesis 19:20', 'Génesis', 19, 20, 'Cerca de aquí hay una ciudad pequeña, en la que podría refugiarme. ¿Por qué no dejan que me escape hacia allá? Es una ciudad muy pequeña, y en ella me pondré a salvo.'),
('nvi', 'Génesis 19:21', 'Génesis', 19, 21, '—Está bien —le respondió—; también esta petición te la concederé. No destruiré la ciudad de que hablas.'),
('nvi', 'Génesis 19:22', 'Génesis', 19, 22, 'Pero date prisa y huye de una vez, porque no puedo hacer nada hasta que llegues allí. Por eso aquella ciudad recibió el nombre de Zoar.'),
('nvi', 'Génesis 19:23', 'Génesis', 19, 23, 'Lot llegó a Zoar cuando estaba amaneciendo.'),
('nvi', 'Génesis 19:24', 'Génesis', 19, 24, 'Entonces el SEÑOR hizo que cayera del cielo una lluvia de fuego y azufre sobre Sodoma y Gomorra.'),
('nvi', 'Génesis 19:25', 'Génesis', 19, 25, 'Así destruyó a esas ciudades y a todos sus habitantes, junto con toda la llanura y la vegetación del suelo.'),
('nvi', 'Génesis 19:26', 'Génesis', 19, 26, 'Pero la esposa de Lot miró hacia atrás, y se quedó convertida en estatua de sal.'),
('nvi', 'Génesis 19:27', 'Génesis', 19, 27, 'Al día siguiente Abraham madrugó y regresó al lugar donde se había encontrado con el SEÑOR.'),
('nvi', 'Génesis 19:28', 'Génesis', 19, 28, 'Volvió la mirada hacia Sodoma y Gomorra, y hacia toda la llanura, y vio que de la tierra subía humo, como de un horno.'),
('nvi', 'Génesis 19:29', 'Génesis', 19, 29, 'Así arrasó Dios a las ciudades de la llanura, pero se acordó de Abraham y sacó a Lot de en medio de la catástrofe que destruyó a las ciudades en que había habitado.'),
('nvi', 'Génesis 19:30', 'Génesis', 19, 30, 'Luego, por miedo a quedarse en Zoar, Lot se fue con sus dos hijas a vivir en la región montañosa. Allí vivió con ellas en una cueva.'),
('nvi', 'Génesis 19:31', 'Génesis', 19, 31, 'Un día, la hija mayor le dijo a la menor: —Nuestro padre ya está viejo, y no quedan hombres en esta región para que se casen con nosotras, como es la costumbre de todo el mundo.'),
('nvi', 'Génesis 19:32', 'Génesis', 19, 32, 'Ven, vamos a emborracharlo, y nos acostaremos con él; y así, por medio de él tendremos descendencia.'),
('nvi', 'Génesis 19:33', 'Génesis', 19, 33, 'Esa misma noche emborracharon a su padre y, sin que éste se diera cuenta de nada, la hija mayor fue y se acostó con él.'),
('nvi', 'Génesis 19:34', 'Génesis', 19, 34, 'A la mañana siguiente, la mayor le dijo a la menor: —Mira, anoche me acosté con mi padre. Vamos a emborracharlo de nuevo esta noche, y ahora tú te acostarás con él; y así, por medio de él tendremos descendencia.'),
('nvi', 'Génesis 19:35', 'Génesis', 19, 35, 'Esa misma noche volvieron a emborrachar a su padre y, sin que éste se diera cuenta de nada, la hija menor fue y se acostó con él.'),
('nvi', 'Génesis 19:36', 'Génesis', 19, 36, 'Así las dos hijas de Lot quedaron embarazadas de su padre.'),
('nvi', 'Génesis 19:37', 'Génesis', 19, 37, 'La mayor tuvo un hijo, a quien llamó Moab, padre de los actuales moabitas.'),
('nvi', 'Génesis 19:38', 'Génesis', 19, 38, 'La hija menor también tuvo un hijo, a quien llamó Ben Amí, padre de los actuales amonitas.'),
('nvi', 'Génesis 20:1', 'Génesis', 20, 1, 'Abraham partió desde allí en dirección a la región del Néguev, y se quedó a vivir entre Cades y Sur. Mientras vivía en Guerar,'),
('nvi', 'Génesis 20:2', 'Génesis', 20, 2, 'Abraham decía que Sara, su esposa, era su hermana. Entonces Abimélec, rey de Guerar, mandó llamar a Sara y la tomó por esposa.'),
('nvi', 'Génesis 20:3', 'Génesis', 20, 3, 'Pero aquella noche Dios se le apareció a Abimélec en sueños y le dijo: —Puedes darte por muerto a causa de la mujer que has tomado, porque ella es casada.'),
('nvi', 'Génesis 20:4', 'Génesis', 20, 4, 'Pero como Abimélec todavía no se había acostado con ella, le contestó: —Señor, ¿acaso vas a matar al inocente?'),
('nvi', 'Génesis 20:5', 'Génesis', 20, 5, 'Como Abraham me dijo que ella era su hermana, y ella me lo confirmó, yo hice todo esto de buena fe y sin mala intención.'),
('nvi', 'Génesis 20:6', 'Génesis', 20, 6, '—Sí, ya sé que has hecho todo esto de buena fe —le respondió Dios en el sueño—; por eso no te permití tocarla, para que no pecaras contra mí.'),
('nvi', 'Génesis 20:7', 'Génesis', 20, 7, 'Pero ahora devuelve esa mujer a su esposo, porque él es profeta y va a interceder por ti para que vivas. Si no lo haces, ten por seguro que morirás junto con todos los tuyos.'),
('nvi', 'Génesis 20:8', 'Génesis', 20, 8, 'En la madrugada del día siguiente, Abimélec se levantó y llamó a todos sus servidores para contarles en detalle lo que había ocurrido, y un gran temor se apoderó de ellos.'),
('nvi', 'Génesis 20:9', 'Génesis', 20, 9, 'Entonces Abimélec llamó a Abraham y le reclamó: —¡Qué nos has hecho! ¿En qué te he ofendido, que has traído un pecado tan grande sobre mí y sobre mi reino? ¡Lo que me has hecho no tiene nombre!'),
('nvi', 'Génesis 20:10', 'Génesis', 20, 10, '¿Qué pretendías conseguir con todo esto? Al reclamo de Abimélec,'),
('nvi', 'Génesis 20:11', 'Génesis', 20, 11, 'Abraham contestó: —Yo pensé que en este lugar no había temor de Dios, y que por causa de mi esposa me matarían.'),
('nvi', 'Génesis 20:12', 'Génesis', 20, 12, 'Pero en realidad ella es mi hermana, porque es hija de mi padre aunque no de mi madre; y además es mi esposa.'),
('nvi', 'Génesis 20:13', 'Génesis', 20, 13, 'Cuando Dios me mandó dejar la casa de mi padre y andar errante, yo le dije a mi esposa: “Te pido que me hagas este favor: Dondequiera que vayamos, di siempre que soy tu hermano.”'),
('nvi', 'Génesis 20:14', 'Génesis', 20, 14, 'Abimélec tomó entonces ovejas y vacas, esclavos y esclavas, y se los regaló a Abraham. Al mismo tiempo, le devolvió a Sara, su esposa,'),
('nvi', 'Génesis 20:15', 'Génesis', 20, 15, 'y le dijo: —Mira, ahí está todo mi territorio; quédate a vivir donde mejor te parezca.'),
('nvi', 'Génesis 20:16', 'Génesis', 20, 16, 'A Sara le dijo: —Le he dado a tu hermano mil monedas de plata, que servirán de compensación por todo lo que te ha pasado; así quedarás vindicada ante todos los que están contigo.'),
('nvi', 'Génesis 20:17', 'Génesis', 20, 17, 'Entonces Abraham oró a Dios, y Dios sanó a Abimélec y permitió que su esposa y sus siervas volvieran a tener hijos,'),
('nvi', 'Génesis 20:18', 'Génesis', 20, 18, 'porque a causa de lo ocurrido con Sara, la esposa de Abraham, el SEÑOR había hecho que todas las mujeres en la casa de Abimélec quedaran estériles.'),
('nvi', 'Génesis 21:1', 'Génesis', 21, 1, 'Tal como el SEÑOR lo había dicho, se ocupó de Sara y cumplió con la promesa que le había hecho.'),
('nvi', 'Génesis 21:2', 'Génesis', 21, 2, 'Sara quedó embarazada y le dio un hijo a Abraham en su vejez. Esto sucedió en el tiempo anunciado por Dios.'),
('nvi', 'Génesis 21:3', 'Génesis', 21, 3, 'Al hijo que Sara le dio, Abraham le puso por nombre Isaac.'),
('nvi', 'Génesis 21:4', 'Génesis', 21, 4, 'Cuando su hijo Isaac cumplió ocho días de nacido, Abraham lo circuncidó, tal como Dios se lo había ordenado.'),
('nvi', 'Génesis 21:5', 'Génesis', 21, 5, 'Abraham tenía ya cien años cuando nació su hijo Isaac.'),
('nvi', 'Génesis 21:6', 'Génesis', 21, 6, 'Sara dijo entonces: «Dios me ha hecho reír, y todos los que se enteren de que he tenido un hijo, se reirán conmigo.'),
('nvi', 'Génesis 21:7', 'Génesis', 21, 7, '¿Quién le hubiera dicho a Abraham que Sara amamantaría hijos? Sin embargo, le he dado un hijo en su vejez.»'),
('nvi', 'Génesis 21:8', 'Génesis', 21, 8, 'El niño Isaac creció y fue destetado. Ese mismo día, Abraham hizo un gran banquete.'),
('nvi', 'Génesis 21:9', 'Génesis', 21, 9, 'Pero Sara se dio cuenta de que el hijo que Agar la egipcia le había dado a Abraham se burlaba de su hijo Isaac.'),
('nvi', 'Génesis 21:10', 'Génesis', 21, 10, 'Por eso le dijo a Abraham: —¡Echa de aquí a esa esclava y a su hijo! El hijo de esa esclava jamás tendrá parte en la herencia con mi hijo Isaac.'),
('nvi', 'Génesis 21:11', 'Génesis', 21, 11, 'Este asunto angustió mucho a Abraham porque se trataba de su propio hijo.'),
('nvi', 'Génesis 21:12', 'Génesis', 21, 12, 'Pero Dios le dijo a Abraham: «No te angusties por el muchacho ni por la esclava. Hazle caso a Sara, porque tu descendencia se establecerá por medio de Isaac.'),
('nvi', 'Génesis 21:13', 'Génesis', 21, 13, 'Pero también del hijo de la esclava haré una gran nación, porque es hijo tuyo.»'),
('nvi', 'Génesis 21:14', 'Génesis', 21, 14, 'Al día siguiente, Abraham se levantó de madrugada, tomó un pan y un odre de agua, y se los dio a Agar, poniéndoselos sobre el hombro. Luego le entregó a su hijo y la despidió. Agar partió y anduvo errante por el desierto de Berseba.'),
('nvi', 'Génesis 21:15', 'Génesis', 21, 15, 'Cuando se acabó el agua del odre, puso al niño debajo de un arbusto'),
('nvi', 'Génesis 21:16', 'Génesis', 21, 16, 'y fue a sentarse sola a cierta distancia, pues pensaba: «No quiero ver morir al niño.» En cuanto ella se sentó, comenzó a llorar desconsoladamente.'),
('nvi', 'Génesis 21:17', 'Génesis', 21, 17, 'Cuando Dios oyó al niño sollozar, el ángel de Dios llamó a Agar desde el cielo y le dijo: «¿Qué te pasa, Agar? No temas, pues Dios ha escuchado los sollozos del niño.'),
('nvi', 'Génesis 21:18', 'Génesis', 21, 18, 'Levántate y tómalo de la mano, que yo haré de él una gran nación.»'),
('nvi', 'Génesis 21:19', 'Génesis', 21, 19, 'En ese momento Dios le abrió a Agar los ojos, y ella vio un pozo de agua. En seguida fue a llenar el odre y le dio de beber al niño.'),
('nvi', 'Génesis 21:20', 'Génesis', 21, 20, 'Dios acompañó al niño, y éste fue creciendo; vivió en el desierto y se convirtió en un experto arquero;'),
('nvi', 'Génesis 21:21', 'Génesis', 21, 21, 'habitó en el desierto de Parán y su madre lo casó con una egipcia.'),
('nvi', 'Génesis 21:22', 'Génesis', 21, 22, 'En aquel tiempo Abimélec, que estaba acompañado por Ficol, jefe de su ejército, le dijo a Abraham: —Dios está contigo en todo lo que haces.'),
('nvi', 'Génesis 21:23', 'Génesis', 21, 23, 'Júrame ahora, por Dios mismo, que no me tratarás a mí con falsedad, ni tampoco a mis hijos ni a mis descendientes. Júrame que a mí y al país que te ha recibido como extranjero nos tratarás con la misma lealtad con que yo te he tratado.'),
('nvi', 'Génesis 21:24', 'Génesis', 21, 24, '—¡Lo juro! —respondió Abraham.'),
('nvi', 'Génesis 21:25', 'Génesis', 21, 25, 'Luego Abraham se quejó ante Abimélec por causa de un pozo de agua del cual los siervos de Abimélec se habían apropiado.'),
('nvi', 'Génesis 21:26', 'Génesis', 21, 26, 'Pero Abimélec dijo: —No sé quién pudo haberlo hecho. Me acabo de enterar, pues tú no me lo habías dicho.'),
('nvi', 'Génesis 21:27', 'Génesis', 21, 27, 'Entonces Abraham llevó ovejas y vacas, y se las dio a Abimélec, y los dos hicieron un pacto.'),
('nvi', 'Génesis 21:28', 'Génesis', 21, 28, 'Pero Abraham apartó siete corderas del rebaño,'),
('nvi', 'Génesis 21:29', 'Génesis', 21, 29, 'por lo que Abimélec le preguntó: —¿Qué pasa? ¿Por qué has apartado estas siete corderas?'),
('nvi', 'Génesis 21:30', 'Génesis', 21, 30, '—Acepta estas siete corderas —le contestó Abraham—. Ellas servirán de prueba de que yo cavé este pozo.'),
('nvi', 'Génesis 21:31', 'Génesis', 21, 31, 'Por eso a aquel lugar le dieron el nombre de Berseba, porque allí los dos hicieron un juramento.'),
('nvi', 'Génesis 21:32', 'Génesis', 21, 32, 'Después de haber hecho el pacto en Berseba, Abimélec y Ficol, el jefe de su ejército, volvieron al país de los filisteos.'),
('nvi', 'Génesis 21:33', 'Génesis', 21, 33, 'Abraham plantó un tamarisco en Berseba, y en ese lugar invocó el nombre del SEÑOR, el Dios eterno.'),
('nvi', 'Génesis 21:34', 'Génesis', 21, 34, 'Y se quedó en el país de los filisteos durante mucho tiempo.'),
('nvi', 'Génesis 22:1', 'Génesis', 22, 1, 'Pasado cierto tiempo, Dios puso a prueba a Abraham y le dijo: —¡Abraham! —Aquí estoy —respondió.'),
('nvi', 'Génesis 22:2', 'Génesis', 22, 2, 'Y Dios le ordenó: —Toma a tu hijo, el único que tienes y al que tanto amas, y ve a la región de Moria. Una vez allí, ofrécelo como holocausto en el monte que yo te indicaré.'),
('nvi', 'Génesis 22:3', 'Génesis', 22, 3, 'Abraham se levantó de madrugada y ensilló su asno. También cortó leña para el holocausto y, junto con dos de sus criados y su hijo Isaac, se encaminó hacia el lugar que Dios le había indicado.'),
('nvi', 'Génesis 22:4', 'Génesis', 22, 4, 'Al tercer día, Abraham alzó los ojos y a lo lejos vio el lugar.'),
('nvi', 'Génesis 22:5', 'Génesis', 22, 5, 'Entonces le dijo a sus criados: —Quédense aquí con el asno. El muchacho y yo seguiremos adelante para adorar a Dios, y luego regresaremos junto a ustedes.'),
('nvi', 'Génesis 22:6', 'Génesis', 22, 6, 'Abraham tomó la leña del holocausto y la puso sobre Isaac, su hijo; él, por su parte, cargó con el fuego y el cuchillo. Y los dos siguieron caminando juntos.'),
('nvi', 'Génesis 22:7', 'Génesis', 22, 7, 'Isaac le dijo a Abraham: —¡Padre! —Dime, hijo mío. —Aquí tenemos el fuego y la leña —continuó Isaac—; pero, ¿dónde está el cordero para el holocausto?'),
('nvi', 'Génesis 22:8', 'Génesis', 22, 8, '—El cordero, hijo mío, lo proveerá Dios —le respondió Abraham. Y siguieron caminando juntos.'),
('nvi', 'Génesis 22:9', 'Génesis', 22, 9, 'Cuando llegaron al lugar señalado por Dios, Abraham construyó un altar y preparó la leña. Después ató a su hijo Isaac y lo puso sobre el altar, encima de la leña.'),
('nvi', 'Génesis 22:10', 'Génesis', 22, 10, 'Entonces tomó el cuchillo para sacrificar a su hijo,'),
('nvi', 'Génesis 22:11', 'Génesis', 22, 11, 'pero en ese momento el ángel del SEÑOR le gritó desde el cielo: —¡Abraham! ¡Abraham! —Aquí estoy —respondió.'),
('nvi', 'Génesis 22:12', 'Génesis', 22, 12, '—No pongas tu mano sobre el muchacho, ni le hagas ningún daño —le dijo el ángel—. Ahora sé que temes a Dios, porque ni siquiera te has negado a darme a tu único hijo.'),
('nvi', 'Génesis 22:13', 'Génesis', 22, 13, 'Abraham alzó la vista y, en un matorral, vio un carnero enredado por los cuernos. Fue entonces, tomó el carnero y lo ofreció como holocausto, en lugar de su hijo.'),
('nvi', 'Génesis 22:14', 'Génesis', 22, 14, 'A ese sitio Abraham le puso por nombre: «El SEÑOR provee.» Por eso hasta el día de hoy se dice: «En un monte provee el SEÑOR.»'),
('nvi', 'Génesis 22:15', 'Génesis', 22, 15, 'El ángel del SEÑOR llamó a Abraham por segunda vez desde el cielo,'),
('nvi', 'Génesis 22:16', 'Génesis', 22, 16, 'y le dijo: —Como has hecho esto, y no me has negado a tu único hijo, juro por mí mismo —afirma el SEÑOR—'),
('nvi', 'Génesis 22:17', 'Génesis', 22, 17, 'que te bendeciré en gran manera, y que multiplicaré tu descendencia como las estrellas del cielo y como la arena del mar. Además, tus descendientes conquistarán las ciudades de sus enemigos.'),
('nvi', 'Génesis 22:18', 'Génesis', 22, 18, 'Puesto que me has obedecido, todas las naciones del mundo serán bendecidas por medio de tu descendencia.'),
('nvi', 'Génesis 22:19', 'Génesis', 22, 19, 'Abraham regresó al lugar donde estaban sus criados, y juntos partieron hacia Berseba, donde Abraham se quedó a vivir.'),
('nvi', 'Génesis 22:20', 'Génesis', 22, 20, 'Pasado cierto tiempo, Abraham recibió la noticia de que también Milca le había dado hijos a su hermano Najor.'),
('nvi', 'Génesis 22:21', 'Génesis', 22, 21, 'Su hijo primogénito fue Uz; luego nacieron sus hermanos Buz y Quemuel. Este último fue el padre de Aram.'),
('nvi', 'Génesis 22:22', 'Génesis', 22, 22, 'Después siguieron Quésed, Jazó, Pildás, Yidlaf y Betuel,'),
('nvi', 'Génesis 22:23', 'Génesis', 22, 23, 'que fue el padre de Rebeca. Éstos fueron los ocho hijos que Milca le dio a Najor, hermano de Abraham.'),
('nvi', 'Génesis 22:24', 'Génesis', 22, 24, 'Najor también tuvo hijos con Reumá, su concubina. Ellos fueron Tébaj, Gaján, Tajás y Macá.'),
('nvi', 'Génesis 23:1', 'Génesis', 23, 1, 'Sara vivió ciento veintisiete años,'),
('nvi', 'Génesis 23:2', 'Génesis', 23, 2, 'y murió en Quiriat Arbá, es decir, en la ciudad de Hebrón, en la tierra de Canaán. Abraham hizo duelo y lloró por ella.'),
('nvi', 'Génesis 23:3', 'Génesis', 23, 3, 'Luego se retiró de donde estaba la difunta y fue a proponer a los hititas lo siguiente:'),
('nvi', 'Génesis 23:4', 'Génesis', 23, 4, '—Entre ustedes yo soy un extranjero; no obstante, quiero pedirles que me vendan un sepulcro para enterrar a mi esposa.'),
('nvi', 'Génesis 23:5', 'Génesis', 23, 5, 'Los hititas le respondieron:'),
('nvi', 'Génesis 23:6', 'Génesis', 23, 6, '—Escúchenos, señor; usted es un príncipe poderoso entre nosotros. Sepulte a su esposa en el mejor de nuestros sepulcros. Ninguno de nosotros le negará su tumba para que pueda sepultar a su esposa.'),
('nvi', 'Génesis 23:7', 'Génesis', 23, 7, 'Abraham se levantó, hizo una reverencia ante los hititas del lugar,'),
('nvi', 'Génesis 23:8', 'Génesis', 23, 8, 'y les dijo: —Si les parece bien que yo entierre aquí a mi difunta, les ruego que intercedan ante Efrón hijo de Zojar'),
('nvi', 'Génesis 23:9', 'Génesis', 23, 9, 'para que me venda la cueva de Macpela, que está en los linderos de su campo. Díganle que me la venda en su justo precio, y así tendré entre ustedes un sepulcro para mi familia.'),
('nvi', 'Génesis 23:10', 'Génesis', 23, 10, 'Efrón el hitita, que estaba sentado allí entre su gente, le respondió a Abraham en presencia de todos ellos y de los que pasaban por la puerta de su ciudad:'),
('nvi', 'Génesis 23:11', 'Génesis', 23, 11, '—No, señor mío, escúcheme bien: yo le regalo el campo, y también la cueva que está en él. Los hijos de mi pueblo son testigos de que yo se los regalo. Entierre usted a su esposa.'),
('nvi', 'Génesis 23:12', 'Génesis', 23, 12, 'Una vez más, Abraham hizo una reverencia ante la gente de ese lugar,'),
('nvi', 'Génesis 23:13', 'Génesis', 23, 13, 'y en presencia de los que allí estaban le dijo a Efrón: —Escúcheme, por favor. Yo insisto en pagarle el precio justo del campo. Acéptelo usted, y así yo podré enterrar allí a mi esposa.'),
('nvi', 'Génesis 23:14', 'Génesis', 23, 14, 'Efrón le contestó a Abraham:'),
('nvi', 'Génesis 23:15', 'Génesis', 23, 15, '—Señor mío, escúcheme. El campo vale cuatrocientas monedas de plata. ¿Qué es eso entre nosotros? Vaya tranquilo y entierre a su esposa.'),
('nvi', 'Génesis 23:16', 'Génesis', 23, 16, 'Abraham se puso de acuerdo con Efrón, y en presencia de los hititas le pagó lo convenido: cuatrocientas monedas de plata, moneda corriente entre los comerciantes.'),
('nvi', 'Génesis 23:17', 'Génesis', 23, 17, 'Así fue como el campo de Efrón, que estaba en Macpela, cerca de Mamré, pasó a ser propiedad de Abraham, junto con la cueva y todos los árboles que estaban dentro de los límites del campo.'),
('nvi', 'Génesis 23:18', 'Génesis', 23, 18, 'La transacción se hizo en presencia de los hititas y de los que pasaban por la puerta de su ciudad.'),
('nvi', 'Génesis 23:19', 'Génesis', 23, 19, 'Luego Abraham sepultó a su esposa Sara en la cueva del campo de Macpela que está cerca de Mamré, es decir, en Hebrón, en la tierra de Canaán.'),
('nvi', 'Génesis 23:20', 'Génesis', 23, 20, 'De esta manera, el campo y la cueva que estaba en él dejó de ser de los hititas y pasó a ser propiedad de Abraham para sepultura.'),
('nvi', 'Génesis 24:1', 'Génesis', 24, 1, 'Abraham estaba ya entrado en años, y el SEÑOR lo había bendecido en todo.'),
('nvi', 'Génesis 24:2', 'Génesis', 24, 2, 'Un día, Abraham le dijo al criado más antiguo de su casa, que era quien le administraba todos sus bienes: —Pon tu mano debajo de mi muslo,'),
('nvi', 'Génesis 24:3', 'Génesis', 24, 3, 'y júrame por el SEÑOR, el Dios del cielo y de la tierra, que no tomarás de esta tierra de Canaán, donde yo habito, una mujer para mi hijo'),
('nvi', 'Génesis 24:4', 'Génesis', 24, 4, 'Isaac, sino que irás a mi tierra, donde vive mi familia, y de allí le escogerás una esposa.'),
('nvi', 'Génesis 24:5', 'Génesis', 24, 5, '—¿Qué pasa si la mujer no está dispuesta a venir conmigo a esta tierra? —respondió el criado—. ¿Debo entonces llevar a su hijo hasta la tierra de donde usted vino?'),
('nvi', 'Génesis 24:6', 'Génesis', 24, 6, '—¡De ninguna manera debes llevar a mi hijo hasta allá! —le replicó Abraham—.'),
('nvi', 'Génesis 24:7', 'Génesis', 24, 7, 'El SEÑOR, el Dios del cielo, que me sacó de la casa de mi padre y de la tierra de mis familiares, y que bajo juramento me prometió dar esta tierra a mis descendientes, enviará su ángel delante de ti para que puedas traer de allá una mujer para mi hijo.'),
('nvi', 'Génesis 24:8', 'Génesis', 24, 8, 'Si la mujer no está dispuesta a venir contigo, quedarás libre de este juramento; pero ¡en ningún caso llevarás a mi hijo hasta allá!'),
('nvi', 'Génesis 24:9', 'Génesis', 24, 9, 'El criado puso la mano debajo del muslo de Abraham, su amo, y le juró que cumpliría con su encargo.'),
('nvi', 'Génesis 24:10', 'Génesis', 24, 10, 'Luego tomó diez camellos de su amo, y toda clase de regalos, y partió hacia la ciudad de Najor en Aram Najarayin.'),
('nvi', 'Génesis 24:11', 'Génesis', 24, 11, 'Allí hizo que los camellos se arrodillaran junto al pozo de agua que estaba en las afueras de la ciudad. Caía la tarde, que es cuando las mujeres salen a buscar agua.'),
('nvi', 'Génesis 24:12', 'Génesis', 24, 12, 'Entonces comenzó a orar: «SEÑOR, Dios de mi amo Abraham, te ruego que hoy me vaya bien, y que demuestres el amor que le tienes a mi amo.'),
('nvi', 'Génesis 24:13', 'Génesis', 24, 13, 'Aquí me tienes, a la espera junto a la fuente, mientras las jóvenes de esta ciudad vienen a sacar agua.'),
('nvi', 'Génesis 24:14', 'Génesis', 24, 14, 'Permite que la joven a quien le diga: “Por favor, baje usted su cántaro para que tome yo un poco de agua”, y que me conteste: “Tome usted, y además les daré agua a sus camellos”, sea la que tú has elegido para tu siervo Isaac. Así estaré seguro de que tú has demostrado el amor que le tienes a mi amo.»'),
('nvi', 'Génesis 24:15', 'Génesis', 24, 15, 'Aún no había terminado de orar cuando vio que se acercaba Rebeca, con su cántaro al hombro. Rebeca era hija de Betuel, que a su vez era hijo de Milca y Najor, el hermano de Abraham.'),
('nvi', 'Génesis 24:16', 'Génesis', 24, 16, 'La joven era muy hermosa, y además virgen, pues no había tenido relaciones sexuales con ningún hombre. Bajó hacia la fuente y llenó su cántaro. Ya se preparaba para subir'),
('nvi', 'Génesis 24:17', 'Génesis', 24, 17, 'cuando el criado corrió a su encuentro y le dijo: —¿Podría usted darme un poco de agua de su cántaro?'),
('nvi', 'Génesis 24:18', 'Génesis', 24, 18, '—Sírvase, mi señor —le respondió. Y en seguida bajó el cántaro y, sosteniéndolo entre sus manos, le dio de beber.'),
('nvi', 'Génesis 24:19', 'Génesis', 24, 19, 'Cuando ya el criado había bebido, ella le dijo: —Voy también a sacar agua para que sus camellos beban todo lo que quieran.'),
('nvi', 'Génesis 24:20', 'Génesis', 24, 20, 'De inmediato vació su cántaro en el bebedero, y volvió corriendo al pozo para buscar más agua, repitiendo la acción hasta que hubo suficiente agua para todos los camellos.'),
('nvi', 'Génesis 24:21', 'Génesis', 24, 21, 'Mientras tanto, el criado de Abraham la observaba en silencio, para ver si el SEÑOR había coronado su viaje con el éxito.'),
('nvi', 'Génesis 24:22', 'Génesis', 24, 22, 'Cuando los camellos terminaron de beber, el criado tomó un anillo de oro que pesaba seis gramos, y se lo puso a la joven en la nariz; también le colocó en los brazos dos pulseras de oro que pesaban más de cien gramos, y le preguntó:'),
('nvi', 'Génesis 24:23', 'Génesis', 24, 23, '—¿Podría usted decirme de quién es hija, y si habrá lugar en la casa de su padre para hospedarnos?'),
('nvi', 'Génesis 24:24', 'Génesis', 24, 24, '—Soy hija de Betuel, el hijo de Milca y Najor —respondió ella,'),
('nvi', 'Génesis 24:25', 'Génesis', 24, 25, 'a lo que agregó—: No sólo tenemos lugar para ustedes, sino que también tenemos paja y forraje en abundancia para los camellos.'),
('nvi', 'Génesis 24:26', 'Génesis', 24, 26, 'Entonces el criado de Abraham se arrodilló y adoró al SEÑOR'),
('nvi', 'Génesis 24:27', 'Génesis', 24, 27, 'con estas palabras: «Bendito sea el SEÑOR, el Dios de mi amo Abraham, que no ha dejado de manifestarle su amor y fidelidad, y que a mí me ha guiado a la casa de sus parientes.»'),
('nvi', 'Génesis 24:28', 'Génesis', 24, 28, 'La joven corrió hasta la casa de su madre, y allí contó lo que le había sucedido.'),
('nvi', 'Génesis 24:29', 'Génesis', 24, 29, 'Tenía Rebeca un hermano llamado Labán, que salió corriendo al encuentro del criado, quien seguía junto a la fuente.'),
('nvi', 'Génesis 24:30', 'Génesis', 24, 30, 'Labán se había fijado en el anillo y las pulseras en los brazos de su hermana, y también la había escuchado contar lo que el criado le había dicho. Por eso salió en busca del criado, y lo encontró junto a la fuente, con sus camellos.'),
('nvi', 'Génesis 24:31', 'Génesis', 24, 31, '—¡Ven, bendito del SEÑOR! —le dijo—. ¿Por qué te quedas afuera? ¡Ya he preparado la casa y un lugar para los camellos!'),
('nvi', 'Génesis 24:32', 'Génesis', 24, 32, 'El criado entró en la casa. En seguida Labán desaparejó los camellos, les dio paja y forraje, y llevó agua para que el criado y sus acompañantes se lavaran los pies.'),
('nvi', 'Génesis 24:33', 'Génesis', 24, 33, 'Cuando le sirvieron de comer, el criado dijo: —No comeré hasta haberles dicho lo que tengo que decir. —Habla con toda confianza —respondió Labán.'),
('nvi', 'Génesis 24:34', 'Génesis', 24, 34, '—Yo soy criado de Abraham —comenzó él—.'),
('nvi', 'Génesis 24:35', 'Génesis', 24, 35, 'El SEÑOR ha bendecido mucho a mi amo y lo ha prosperado. Le ha dado ovejas y ganado, oro y plata, siervos y siervas, camellos y asnos.'),
('nvi', 'Génesis 24:36', 'Génesis', 24, 36, 'Sara, la esposa de mi amo, le dio en su vejez un hijo, al que mi amo le ha dejado todo lo que tiene.'),
('nvi', 'Génesis 24:37', 'Génesis', 24, 37, 'Mi amo me hizo jurar, y me dijo: “No tomarás para mi hijo una mujer de entre las hijas de los cananeos, en cuyo país habito.'),
('nvi', 'Génesis 24:38', 'Génesis', 24, 38, 'Al contrario, irás a la familia de mi padre, y le buscarás una esposa entre las mujeres de mis parientes.”'),
('nvi', 'Génesis 24:39', 'Génesis', 24, 39, 'Yo le pregunté a mi amo: “¿Y si la mujer no acepta venir conmigo?”'),
('nvi', 'Génesis 24:40', 'Génesis', 24, 40, 'Él me respondió: “El SEÑOR, en cuya presencia he caminado, enviará su ángel contigo, y él hará prosperar tu viaje para que consigas para mi hijo una esposa que pertenezca a la familia de mi padre.'),
('nvi', 'Génesis 24:41', 'Génesis', 24, 41, 'Sólo quedarás libre del juramento si vas a ver a mi familia y ellos no te conceden a la joven.”'),
('nvi', 'Génesis 24:42', 'Génesis', 24, 42, '»Cuando hoy llegué a la fuente, dije: “SEÑOR, Dios de mi amo Abraham, si es tu voluntad, te ruego que hagas prosperar mi viaje.'),
('nvi', 'Génesis 24:43', 'Génesis', 24, 43, 'Aquí me tienes, a la espera junto a la fuente. Si una joven sale a buscar agua, y yo le digo: ‘Por favor, déjeme usted beber un poco de agua de su cántaro’,'),
('nvi', 'Génesis 24:44', 'Génesis', 24, 44, 'y ella me contesta: ‘Beba usted, y también le daré agua a sus camellos’, que sea ella la mujer que tú, SEÑOR, has escogido para el hijo de mi amo.”'),
('nvi', 'Génesis 24:45', 'Génesis', 24, 45, '»Todavía no había terminado yo de orar cuando vi que Rebeca se acercaba con un cántaro sobre el hombro. Bajó a la fuente para sacar agua, y yo le dije: “Por favor, déme usted de beber.”'),
('nvi', 'Génesis 24:46', 'Génesis', 24, 46, 'En seguida bajó ella su cántaro y me dijo: “Beba usted, y también les daré de beber a sus camellos.”Mientras yo bebía, ella les dio agua a los camellos.'),
('nvi', 'Génesis 24:47', 'Génesis', 24, 47, 'Luego le pregunté: “¿Hija de quién es usted?”Y cuando ella me respondió: “Soy hija de Betuel, el hijo de Najor y de Milca”, yo le puse un anillo en la nariz y pulseras en los brazos,'),
('nvi', 'Génesis 24:48', 'Génesis', 24, 48, 'y me incliné para adorar al SEÑOR. Bendije al SEÑOR, el Dios de Abraham, que me guió por el camino correcto para llevarle al hijo de mi amo una parienta cercana suya.'),
('nvi', 'Génesis 24:49', 'Génesis', 24, 49, 'Y ahora, si desean mostrarle lealtad y fidelidad a mi amo, díganmelo; y si no, díganmelo también. Así yo sabré qué hacer.'),
('nvi', 'Génesis 24:50', 'Génesis', 24, 50, 'Labán y Betuel respondieron: —Sin duda todo esto proviene del SEÑOR, y nosotros no podemos decir ni que sí ni que no.'),
('nvi', 'Génesis 24:51', 'Génesis', 24, 51, 'Aquí está Rebeca; tómela usted y llévesela para que sea la esposa del hijo de su amo, tal como el SEÑOR lo ha dispuesto.'),
('nvi', 'Génesis 24:52', 'Génesis', 24, 52, 'Al escuchar esto, el criado de Abraham se postró en tierra delante del SEÑOR.'),
('nvi', 'Génesis 24:53', 'Génesis', 24, 53, 'Luego sacó joyas de oro y de plata, y vestidos, y se los dio a Rebeca. También entregó regalos a su hermano y a su madre.'),
('nvi', 'Génesis 24:54', 'Génesis', 24, 54, 'Más tarde, él y sus acompañantes comieron y bebieron, y pasaron allí la noche. A la mañana siguiente, cuando se levantaron, el criado de Abraham dijo: —Déjenme ir a la casa de mi amo.'),
('nvi', 'Génesis 24:55', 'Génesis', 24, 55, 'Pero el hermano y la madre de Rebeca le respondieron: —Que se quede la joven con nosotros unos diez días, y luego podrás irte.'),
('nvi', 'Génesis 24:56', 'Génesis', 24, 56, '—No me detengan —repuso el criado—. El SEÑOR ha prosperado mi viaje, así que déjenme ir a la casa de mi amo.'),
('nvi', 'Génesis 24:57', 'Génesis', 24, 57, '—Llamemos a la joven, a ver qué piensa ella —respondieron.'),
('nvi', 'Génesis 24:58', 'Génesis', 24, 58, 'Así que llamaron a Rebeca y le preguntaron: —¿Quieres irte con este hombre? —Sí —respondió ella.'),
('nvi', 'Génesis 24:59', 'Génesis', 24, 59, 'Entonces dejaron ir a su hermana Rebeca y a su nodriza con el criado de Abraham y sus acompañantes.'),
('nvi', 'Génesis 24:60', 'Génesis', 24, 60, 'Y bendijeron a Rebeca con estas palabras: «Hermana nuestra: ¡que seas madre de millares! ¡Que dominen tus descendientes las ciudades de sus enemigos!»'),
('nvi', 'Génesis 24:61', 'Génesis', 24, 61, 'Luego Rebeca y sus criadas se prepararon, montaron en los camellos y siguieron al criado de Abraham. Así fue como él tomó a Rebeca y se marchó de allí.'),
('nvi', 'Génesis 24:62', 'Génesis', 24, 62, 'Ahora bien, Isaac había vuelto del pozo de Lajay Roí, porque vivía en la región del Néguev.'),
('nvi', 'Génesis 24:63', 'Génesis', 24, 63, 'Una tarde, salió a dar un paseo por el campo. De pronto, al levantar la vista, vio que se acercaban unos camellos.'),
('nvi', 'Génesis 24:64', 'Génesis', 24, 64, 'También Rebeca levantó la vista y, al ver a Isaac, se bajó del camello'),
('nvi', 'Génesis 24:65', 'Génesis', 24, 65, 'y le preguntó al criado: —¿Quién es ese hombre que viene por el campo a nuestro encuentro? —Es mi amo —contestó el criado. Entonces ella tomó el velo y se cubrió.'),
('nvi', 'Génesis 24:66', 'Génesis', 24, 66, 'El criado le contó a Isaac todo lo que había hecho.'),
('nvi', 'Génesis 24:67', 'Génesis', 24, 67, 'Luego Isaac llevó a Rebeca a la carpa de Sara, su madre, y la tomó por esposa. Isaac amó a Rebeca, y así se consoló de la muerte de su madre.'),
('nvi', 'Génesis 25:1', 'Génesis', 25, 1, 'Abraham volvió a casarse, esta vez con una mujer llamada Cetura.'),
('nvi', 'Génesis 25:2', 'Génesis', 25, 2, 'Los hijos que tuvo con ella fueron: Zimrán, Jocsán, Medán, Madián, Isbac y Súaj.'),
('nvi', 'Génesis 25:3', 'Génesis', 25, 3, 'Jocsán fue el padre de Sabá y Dedán. Los descendientes de Dedán fueron los asureos, los letuseos y los leumeos.'),
('nvi', 'Génesis 25:4', 'Génesis', 25, 4, 'Los hijos de Madián fueron Efá, Éfer, Janoc, Abidá y Eldá. Todos éstos fueron hijos de Cetura.'),
('nvi', 'Génesis 25:5', 'Génesis', 25, 5, 'Abraham entregó todos sus bienes a Isaac.'),
('nvi', 'Génesis 25:6', 'Génesis', 25, 6, 'A los hijos de sus concubinas les hizo regalos y, mientras él todavía estaba con vida, los separó de su hijo Isaac, enviándolos a las regiones orientales.'),
('nvi', 'Génesis 25:7', 'Génesis', 25, 7, 'Abraham vivió ciento setenta y cinco años,'),
('nvi', 'Génesis 25:8', 'Génesis', 25, 8, 'y murió en buena vejez, luego de haber vivido muchos años, y fue a reunirse con sus antepasados.'),
('nvi', 'Génesis 25:9', 'Génesis', 25, 9, 'Sus hijos Isaac e Ismael lo sepultaron en la cueva de Macpela, que está cerca de Mamré, es decir, en el campo del hitita Efrón hijo de Zojar.'),
('nvi', 'Génesis 25:10', 'Génesis', 25, 10, 'Éste era el campo que Abraham les había comprado a los hititas. Allí lo enterraron, junto a su esposa Sara.'),
('nvi', 'Génesis 25:11', 'Génesis', 25, 11, 'Luego de la muerte de Abraham, Dios bendijo a Isaac, hijo de Abraham, quien se quedó a vivir cerca del pozo de Lajay Roí.'),
('nvi', 'Génesis 25:12', 'Génesis', 25, 12, 'Ésta es la descendencia de Ismael, el hijo que Abraham tuvo con Agar, la criada egipcia de Sara.'),
('nvi', 'Génesis 25:13', 'Génesis', 25, 13, 'Éstos son los nombres de los hijos de Ismael, comenzando por el primogénito: Nebayot, Cedar, Adbel, Mibsán,'),
('nvi', 'Génesis 25:14', 'Génesis', 25, 14, 'Mismá, Dumá, Masá,'),
('nvi', 'Génesis 25:15', 'Génesis', 25, 15, 'Hadar, Temá, Jetur, Nafis y Cedema.'),
('nvi', 'Génesis 25:16', 'Génesis', 25, 16, 'Éstos fueron los hijos de Ismael, y éstos los nombres de los doce jefes de tribus, según sus propios territorios y campamentos.'),
('nvi', 'Génesis 25:17', 'Génesis', 25, 17, 'Ismael vivió ciento treinta y siete años. Al morir, fue a reunirse con sus antepasados.'),
('nvi', 'Génesis 25:18', 'Génesis', 25, 18, 'Sus descendientes se quedaron a vivir en la región que está entre Javilá y Sur, cerca de Egipto, en la ruta que conduce a Asiria. Allí se establecieron en franca oposición a todos sus hermanos.'),
('nvi', 'Génesis 25:19', 'Génesis', 25, 19, 'Ésta es la historia de Isaac, el hijo que tuvo Abraham.'),
('nvi', 'Génesis 25:20', 'Génesis', 25, 20, 'Isaac tenía cuarenta años cuando se casó con Rebeca, que era hija de Betuel y hermana de Labán. Betuel y Labán eran arameos de Padán Aram.'),
('nvi', 'Génesis 25:21', 'Génesis', 25, 21, 'Isaac oró al SEÑOR en favor de su esposa, porque era estéril. El SEÑOR oyó su oración, y ella quedó embarazada.'),
('nvi', 'Génesis 25:22', 'Génesis', 25, 22, 'Pero como los niños luchaban dentro de su seno, ella se preguntó: «Si esto va a seguir así, ¿para qué sigo viviendo?» Entonces fue a consultar al SEÑOR,'),
('nvi', 'Génesis 25:23', 'Génesis', 25, 23, 'y él le contestó: «Dos naciones hay en tu seno; dos pueblos se dividen desde tus entrañas. Uno será más fuerte que el otro, y el mayor servirá al menor.»'),
('nvi', 'Génesis 25:24', 'Génesis', 25, 24, 'Cuando le llegó el momento de dar a luz, resultó que en su seno había mellizos.'),
('nvi', 'Génesis 25:25', 'Génesis', 25, 25, 'El primero en nacer era pelirrojo, y tenía todo el cuerpo cubierto de vello. A éste lo llamaron Esaú.'),
('nvi', 'Génesis 25:26', 'Génesis', 25, 26, 'Luego nació su hermano, agarrado con una mano del talón de Esaú. A éste lo llamaron Jacob. Cuando nacieron los mellizos, Isaac tenía sesenta años.'),
('nvi', 'Génesis 25:27', 'Génesis', 25, 27, 'Los niños crecieron. Esaú era un hombre de campo y se convirtió en un excelente cazador, mientras que Jacob era un hombre tranquilo que prefería quedarse en el campamento.'),
('nvi', 'Génesis 25:28', 'Génesis', 25, 28, 'Isaac quería más a Esaú, porque le gustaba comer de lo que él cazaba; pero Rebeca quería más a Jacob.'),
('nvi', 'Génesis 25:29', 'Génesis', 25, 29, 'Un día, cuando Jacob estaba preparando un guiso, Esaú llegó agotado del campo y le dijo:'),
('nvi', 'Génesis 25:30', 'Génesis', 25, 30, '—Dame de comer de ese guiso rojizo, porque estoy muy cansado. (Por eso a Esaú se le llamó Edom.)'),
('nvi', 'Génesis 25:31', 'Génesis', 25, 31, '—Véndeme primero tus derechos de hijo mayor —le respondió Jacob.'),
('nvi', 'Génesis 25:32', 'Génesis', 25, 32, '—Me estoy muriendo de hambre —contestó Esaú—, así que ¿de qué me sirven los derechos de primogénito?'),
('nvi', 'Génesis 25:33', 'Génesis', 25, 33, '—Véndeme entonces los derechos bajo juramento —insistió Jacob. Esaú se lo juró, y fue así como le vendió a Jacob sus derechos de primogénito.'),
('nvi', 'Génesis 25:34', 'Génesis', 25, 34, 'Jacob, por su parte, le dio a Esaú pan y guiso de lentejas. Luego de comer y beber, Esaú se levantó y se fue. De esta manera menospreció sus derechos de hijo mayor.'),
('nvi', 'Génesis 26:1', 'Génesis', 26, 1, 'En ese tiempo hubo mucha hambre en aquella región, además de la que hubo en tiempos de Abraham. Por eso Isaac se fue a Guerar, donde se encontraba Abimélec, rey de los filisteos.'),
('nvi', 'Génesis 26:2', 'Génesis', 26, 2, 'Allí el SEÑOR se le apareció y le dijo: «No vayas a Egipto. Quédate en la región de la que te he hablado.'),
('nvi', 'Génesis 26:3', 'Génesis', 26, 3, 'Vive en ese lugar por un tiempo. Yo estaré contigo y te bendeciré, porque a ti y a tu descendencia les daré todas esas tierras. Así confirmaré el juramento que le hice a tu padre Abraham.'),
('nvi', 'Génesis 26:4', 'Génesis', 26, 4, 'Multiplicaré a tus descendientes como las estrellas del cielo, y les daré todas esas tierras. Por medio de tu descendencia todas las naciones de la tierra serán bendecidas,'),
('nvi', 'Génesis 26:5', 'Génesis', 26, 5, 'porque Abraham me obedeció y cumplió mis preceptos y mis mandamientos, mis normas y mis enseñanzas.»'),
('nvi', 'Génesis 26:6', 'Génesis', 26, 6, 'Isaac se quedó en Guerar.'),
('nvi', 'Génesis 26:7', 'Génesis', 26, 7, 'Y cuando la gente del lugar le preguntaba a Isaac acerca de su esposa, él respondía que ella era su hermana. Tan bella era Rebeca que Isaac tenía miedo de decir que era su esposa, pues pensaba que por causa de ella podrían matarlo.'),
('nvi', 'Génesis 26:8', 'Génesis', 26, 8, 'Algún tiempo después, mientras Abimélec, el rey de los filisteos, miraba por una ventana, vio a Isaac acariciando a su esposa Rebeca.'),
('nvi', 'Génesis 26:9', 'Génesis', 26, 9, 'Entonces mandó llamar a Isaac y le dijo: —¡Conque ella es tu esposa! ¿Por qué dijiste que era tu hermana? —Yo pensé que por causa de ella podrían matarme —contestó Isaac.'),
('nvi', 'Génesis 26:10', 'Génesis', 26, 10, '—¿Por qué nos hiciste esto? —replicó Abimélec—. Alguno de nosotros podría haberse acostado con tu esposa, ¡y tú nos habrías hecho a todos culpables de ese pecado!'),
('nvi', 'Génesis 26:11', 'Génesis', 26, 11, 'Por eso Abimélec envió esta orden a todo el pueblo: —Si alguien molesta a este hombre o a su esposa, será condenado a muerte.'),
('nvi', 'Génesis 26:12', 'Génesis', 26, 12, 'Isaac sembró en aquella región, y ese año cosechó al ciento por uno, porque el SEÑOR lo había bendecido.'),
('nvi', 'Génesis 26:13', 'Génesis', 26, 13, 'Así Isaac fue acumulando riquezas, hasta que llegó a ser muy rico.'),
('nvi', 'Génesis 26:14', 'Génesis', 26, 14, 'Esto causó que los filisteos comenzaran a tenerle envidia, pues llegó a tener muchas ovejas, vacas y siervos.'),
('nvi', 'Génesis 26:15', 'Génesis', 26, 15, 'Ahora bien, los filisteos habían cegado todos los pozos de agua que los siervos del padre de Isaac habían cavado.'),
('nvi', 'Génesis 26:16', 'Génesis', 26, 16, 'Así que Abimélec le dijo a Isaac: —Aléjate de nosotros, pues ya eres más poderoso que nosotros.'),
('nvi', 'Génesis 26:17', 'Génesis', 26, 17, 'Isaac se fue de allí, y acampó en el valle de Guerar, donde se quedó a vivir.'),
('nvi', 'Génesis 26:18', 'Génesis', 26, 18, 'Abrió nuevamente los pozos de agua que habían sido cavados en tiempos de su padre Abraham, y que los filisteos habían tapado después de su muerte, y les puso los mismos nombres que su padre les había dado.'),
('nvi', 'Génesis 26:19', 'Génesis', 26, 19, 'Cierta vez, cuando los siervos de Isaac estaban cavando en el valle, encontraron un manantial.'),
('nvi', 'Génesis 26:20', 'Génesis', 26, 20, 'Pero los pastores de Guerar discutieron acaloradamente con los pastores de Isaac, alegando que el agua era de ellos. Por eso Isaac llamó a ese pozo Pleito, porque habían peleado con él.'),
('nvi', 'Génesis 26:21', 'Génesis', 26, 21, 'Después sus siervos cavaron otro pozo, por el cual también se pelearon. Por eso Isaac lo llamó Enemistad.'),
('nvi', 'Génesis 26:22', 'Génesis', 26, 22, 'Entonces Isaac se fue de allí y cavó otro pozo, pero esta vez no hubo ninguna disputa. A este pozo lo llamó Espacios libres, y dijo: «El SEÑOR nos ha dado espacio para que prosperemos en esta región.»'),
('nvi', 'Génesis 26:23', 'Génesis', 26, 23, 'De allí Isaac se dirigió a Berseba.'),
('nvi', 'Génesis 26:24', 'Génesis', 26, 24, 'Esa noche se le apareció el SEÑOR, y le dijo: «Yo soy el Dios de tu padre Abraham. No temas, que yo estoy contigo. Por amor a mi siervo Abraham, te bendeciré y multiplicaré tu descendencia.»'),
('nvi', 'Génesis 26:25', 'Génesis', 26, 25, 'Allí Isaac construyó un altar e invocó el nombre del SEÑOR. Acampó en ese lugar, y sus siervos cavaron un pozo.'),
('nvi', 'Génesis 26:26', 'Génesis', 26, 26, 'Cierto día, Abimélec fue a ver a Isaac desde Guerar. Llegó acompañado de su consejero Ajuzat, y de Ficol, el jefe de su ejército.'),
('nvi', 'Génesis 26:27', 'Génesis', 26, 27, 'Isaac les preguntó: —Si tanto me odian, que hasta me echaron de su tierra, ¿para qué vienen a verme?'),
('nvi', 'Génesis 26:28', 'Génesis', 26, 28, '—Nos hemos dado cuenta de que el SEÑOR está contigo —respondieron—. Hemos pensado que tú y nosotros debiéramos hacer un pacto, respaldado por un juramento. Ese pacto será el siguiente:'),
('nvi', 'Génesis 26:29', 'Génesis', 26, 29, 'Tú no nos harás ningún daño, ya que nosotros no te hemos perjudicado, sino que te hemos tratado bien y te hemos dejado ir en paz. ¡Ahora el bendecido del SEÑOR eres tú!'),
('nvi', 'Génesis 26:30', 'Génesis', 26, 30, 'Isaac les preparó un banquete, y comieron y bebieron.'),
('nvi', 'Génesis 26:31', 'Génesis', 26, 31, 'A la mañana siguiente se levantaron muy temprano, e hicieron un compromiso mutuo. Luego Isaac los despidió, y ellos se fueron en calidad de amigos.'),
('nvi', 'Génesis 26:32', 'Génesis', 26, 32, 'Aquel mismo día, los siervos de Isaac fueron y le informaron acerca de un pozo que habían cavado, y le dijeron: —¡Hemos encontrado agua!'),
('nvi', 'Génesis 26:33', 'Génesis', 26, 33, 'Isaac llamó a ese pozo Juramento. Por eso la ciudad se llama Berseba hasta el día de hoy.'),
('nvi', 'Génesis 26:34', 'Génesis', 26, 34, 'Esaú tenía cuarenta años de edad cuando se casó con Judit hija de Beerí, el hitita. También se casó con Basemat, hija de un hitita llamado Elón.'),
('nvi', 'Génesis 26:35', 'Génesis', 26, 35, 'Estas dos mujeres les causaron mucha amargura a Isaac y a Rebeca.'),
('nvi', 'Génesis 27:1', 'Génesis', 27, 1, 'Isaac había llegado a viejo y se había quedado ciego. Un día llamó a Esaú, su hijo mayor. —¡Hijo mío! —le dijo. —Aquí estoy —le contestó Esaú.'),
('nvi', 'Génesis 27:2', 'Génesis', 27, 2, '—Como te darás cuenta, ya estoy muy viejo y en cualquier momento puedo morirme.'),
('nvi', 'Génesis 27:3', 'Génesis', 27, 3, 'Toma, pues, tus armas, tu arco y tus flechas, y ve al campo a cazarme algún animal.'),
('nvi', 'Génesis 27:4', 'Génesis', 27, 4, 'Prepárame luego un buen guiso, como a mí me gusta, y tráemelo para que me lo coma. Entonces te bendeciré antes de que muera.'),
('nvi', 'Génesis 27:5', 'Génesis', 27, 5, 'Como Rebeca había estado escuchando mientras Isaac le hablaba a su hijo Esaú, en cuanto éste se fue al campo a cazar un animal para su padre,'),
('nvi', 'Génesis 27:6', 'Génesis', 27, 6, 'ella le dijo a su hijo Jacob: —Según acabo de escuchar, tu padre le ha pedido a tu hermano Esaú'),
('nvi', 'Génesis 27:7', 'Génesis', 27, 7, 'que cace un animal y se lo traiga para hacerle un guiso como a él le gusta. También le ha prometido que antes de morirse lo va a bendecir, poniendo al SEÑOR como testigo.'),
('nvi', 'Génesis 27:8', 'Génesis', 27, 8, 'Ahora bien, hijo mío, escúchame bien, y haz lo que te mando.'),
('nvi', 'Génesis 27:9', 'Génesis', 27, 9, 'Ve al rebaño y tráeme de allí dos de los mejores cabritos, para que yo le prepare a tu padre un guiso como a él le gusta.'),
('nvi', 'Génesis 27:10', 'Génesis', 27, 10, 'Tú se lo llevarás para que se lo coma, y así él te dará su bendición antes de morirse.'),
('nvi', 'Génesis 27:11', 'Génesis', 27, 11, 'Pero Jacob le dijo a su madre: —Hay un problema: mi hermano Esaú es muy velludo, y yo soy lampiño.'),
('nvi', 'Génesis 27:12', 'Génesis', 27, 12, 'Si mi padre me toca, se dará cuenta de que quiero engañarlo, y esto hará que me maldiga en vez de bendecirme.'),
('nvi', 'Génesis 27:13', 'Génesis', 27, 13, '—Hijo mío, ¡que esa maldición caiga sobre mí! —le contestó su madre—. Tan sólo haz lo que te pido, y ve a buscarme esos cabritos.'),
('nvi', 'Génesis 27:14', 'Génesis', 27, 14, 'Jacob fue a buscar los cabritos, se los llevó a su madre, y ella preparó el guiso tal como le gustaba a su padre.'),
('nvi', 'Génesis 27:15', 'Génesis', 27, 15, 'Luego sacó la mejor ropa de su hijo mayor Esaú, la cual tenía en casa, y con ella vistió a su hijo menor Jacob.'),
('nvi', 'Génesis 27:16', 'Génesis', 27, 16, 'Con la piel de los cabritos le cubrió los brazos y la parte lampiña del cuello,'),
('nvi', 'Génesis 27:17', 'Génesis', 27, 17, 'y le entregó a Jacob el guiso y el pan que había preparado.'),
('nvi', 'Génesis 27:18', 'Génesis', 27, 18, 'Jacob se presentó ante su padre y le dijo: —¡Padre! —Dime, hijo mío, ¿quién eres tú? —preguntó Isaac.'),
('nvi', 'Génesis 27:19', 'Génesis', 27, 19, '—Soy Esaú, tu primogénito —le contestó Jacob—. Ya hice todo lo que me pediste. Ven, por favor, y siéntate a comer de lo que he cazado; así podrás darme tu bendición.'),
('nvi', 'Génesis 27:20', 'Génesis', 27, 20, 'Pero Isaac le preguntó a su hijo: —¿Cómo fue que lo encontraste tan pronto, hijo mío? —El SEÑOR tu Dios me ayudó —respondió Jacob.'),
('nvi', 'Génesis 27:21', 'Génesis', 27, 21, 'Isaac le dijo: —Acércate, hijo mío, para que pueda tocarte y saber si de veras eres o no mi hijo Esaú.'),
('nvi', 'Génesis 27:22', 'Génesis', 27, 22, 'Jacob se acercó a su padre, quien al tocarlo dijo: —La voz es la de Jacob, pero las manos son las de Esaú.'),
('nvi', 'Génesis 27:23', 'Génesis', 27, 23, 'Así que no lo reconoció, porque sus manos eran velludas como las de Esaú. Ya se disponía a bendecirlo'),
('nvi', 'Génesis 27:24', 'Génesis', 27, 24, 'cuando volvió a preguntarle: —¿En serio eres mi hijo Esaú? —Claro que sí —respondió Jacob.'),
('nvi', 'Génesis 27:25', 'Génesis', 27, 25, 'Entonces su padre le dijo: —Tráeme lo que has cazado, para que lo coma, y te daré mi bendición. Jacob le sirvió, y su padre comió. También le llevó vino, y su padre lo bebió.'),
('nvi', 'Génesis 27:26', 'Génesis', 27, 26, 'Luego le dijo su padre: —Acércate ahora, hijo mío, y dame un beso.'),
('nvi', 'Génesis 27:27', 'Génesis', 27, 27, 'Jacob se acercó y lo besó. Cuando Isaac olió su ropa, lo bendijo con estas palabras: «El olor de mi hijo es como el de un campo bendecido por el SEÑOR.'),
('nvi', 'Génesis 27:28', 'Génesis', 27, 28, 'Que Dios te conceda el rocío del cielo; que de la riqueza de la tierra te dé trigo y vino en abundancia.'),
('nvi', 'Génesis 27:29', 'Génesis', 27, 29, 'Que te sirvan los pueblos; que ante ti se inclinen las naciones. Que seas señor de tus hermanos; que ante ti se inclinen los hijos de tu madre. Maldito sea el que te maldiga, y bendito el que te bendiga.»'),
('nvi', 'Génesis 27:30', 'Génesis', 27, 30, 'No bien había terminado Isaac de bendecir a Jacob, y éste de salir de la presencia de su padre, cuando Esaú volvió de cazar.'),
('nvi', 'Génesis 27:31', 'Génesis', 27, 31, 'También él preparó un guiso, se lo llevó a su padre y le dijo: —Levántate, padre mío, y come de lo que ha cazado tu hijo. Luego podrás darme tu bendición.'),
('nvi', 'Génesis 27:32', 'Génesis', 27, 32, 'Pero Isaac lo interrumpió: —¿Quién eres tú? —Soy Esaú, tu hijo primogénito —respondió.'),
('nvi', 'Génesis 27:33', 'Génesis', 27, 33, 'Isaac comenzó a temblar y, muy sobresaltado, dijo: —¿Quién fue el que ya me trajo lo que había cazado? Poco antes de que llegaras, yo me lo comí todo. Le di mi bendición, y bendecido quedará.'),
('nvi', 'Génesis 27:34', 'Génesis', 27, 34, 'Al escuchar Esaú las palabras de su padre, lanzó un grito aterrador y, lleno de amargura, le dijo: —¡Padre mío, te ruego que también a mí me bendigas!'),
('nvi', 'Génesis 27:35', 'Génesis', 27, 35, 'Pero Isaac le respondió: —Tu hermano vino y me engañó, y se llevó la bendición que a ti te correspondía.'),
('nvi', 'Génesis 27:36', 'Génesis', 27, 36, '—¡Con toda razón le pusieron Jacob! —replicó Esaú—. Ya van dos veces que me engaña: primero me quita mis derechos de primogénito, y ahora se lleva mi bendición. ¿No te queda ninguna bendición para mí?'),
('nvi', 'Génesis 27:37', 'Génesis', 27, 37, 'Isaac le respondió: —Ya lo he puesto por señor tuyo: todos sus hermanos serán siervos suyos; lo he sustentado con trigo y con vino. ¿Qué puedo hacer ahora por ti, hijo mío?'),
('nvi', 'Génesis 27:38', 'Génesis', 27, 38, 'Pero Esaú insistió: —¿Acaso tienes una sola bendición, padre mío? ¡Bendíceme también a mí! Y se echó a llorar.'),
('nvi', 'Génesis 27:39', 'Génesis', 27, 39, 'Entonces su padre le dijo: «Vivirás lejos de las riquezas de la tierra, lejos del rocío que cae del cielo.'),
('nvi', 'Génesis 27:40', 'Génesis', 27, 40, 'Gracias a tu espada, vivirás y servirás a tu hermano. Pero cuando te impacientes, te librarás de su opresión.»'),
('nvi', 'Génesis 27:41', 'Génesis', 27, 41, 'A partir de ese momento, Esaú guardó un profundo rencor hacia su hermano por causa de la bendición que le había dado su padre, y pensaba: «Ya falta poco para que hagamos duelo por mi padre; después de eso, mataré a mi hermano Jacob.»'),
('nvi', 'Génesis 27:42', 'Génesis', 27, 42, 'Cuando Rebeca se enteró de lo que estaba pensando Esaú, mandó llamar a Jacob, y le dijo: —Mira, tu hermano Esaú está planeando matarte para vengarse de ti.'),
('nvi', 'Génesis 27:43', 'Génesis', 27, 43, 'Por eso, hijo mío, obedéceme: Prepárate y huye en seguida a Jarán, a la casa de mi hermano Labán,'),
('nvi', 'Génesis 27:44', 'Génesis', 27, 44, 'y quédate con él por un tiempo, hasta que se calme el enojo de tu hermano.'),
('nvi', 'Génesis 27:45', 'Génesis', 27, 45, 'Cuando ya se haya tranquilizado, y olvide lo que le has hecho, yo enviaré a buscarte. ¿Por qué voy a perder a mis dos hijos en un solo día?'),
('nvi', 'Génesis 27:46', 'Génesis', 27, 46, 'Luego Rebeca le dijo a Isaac: —Estas mujeres hititas me tienen harta. Me han quitado las ganas de vivir. Si Jacob se llega a casar con una de las hititas que viven en este país, ¡más me valdría morir!'),
('nvi', 'Génesis 28:1', 'Génesis', 28, 1, 'Isaac llamó a Jacob, lo bendijo y le ordenó: —No te cases con ninguna mujer de aquí de Canaán.'),
('nvi', 'Génesis 28:2', 'Génesis', 28, 2, 'Vete ahora mismo a Padán Aram, a la casa de Betuel, tu abuelo materno, y cásate allá con una de las hijas de tu tío Labán.'),
('nvi', 'Génesis 28:3', 'Génesis', 28, 3, 'Que el Dios Todopoderoso te bendiga, te haga fecundo y haga que salgan de ti numerosas naciones.'),
('nvi', 'Génesis 28:4', 'Génesis', 28, 4, 'Que también te dé, a ti y a tu descendencia, la bendición de Abraham, para que puedan poseer esta tierra donde ahora vives como extranjero, esta tierra que Dios le prometió a Abraham.'),
('nvi', 'Génesis 28:5', 'Génesis', 28, 5, 'Así envió Isaac a Jacob a Padán Aram, a la casa de Labán, quien era hijo de Betuel el arameo, y hermano de Rebeca, la madre de Jacob y de Esaú.'),
('nvi', 'Génesis 28:6', 'Génesis', 28, 6, 'Esaú supo que Isaac había bendecido a Jacob, y que lo había enviado a Padán Aram para casarse allá. También se enteró de que, al bendecirlo, le dio la orden de no casarse con ninguna cananea,'),
('nvi', 'Génesis 28:7', 'Génesis', 28, 7, 'y de que Jacob había partido hacia Padán Aram en obediencia a su padre y a su madre.'),
('nvi', 'Génesis 28:8', 'Génesis', 28, 8, 'Entonces Esaú se dio cuenta de la antipatía de su padre por las cananeas.'),
('nvi', 'Génesis 28:9', 'Génesis', 28, 9, 'Por eso, aunque ya tenía otras esposas cananeas, Esaú fue hasta donde vivía Ismael hijo de Abraham y se casó con su hija Majalat, que era hermana de Nebayot.'),
('nvi', 'Génesis 28:10', 'Génesis', 28, 10, 'Jacob partió de Berseba y se encaminó hacia Jarán.'),
('nvi', 'Génesis 28:11', 'Génesis', 28, 11, 'Cuando llegó a cierto lugar, se detuvo para pasar la noche, porque ya estaba anocheciendo. Tomó una piedra, la usó como almohada, y se acostó a dormir en ese lugar.'),
('nvi', 'Génesis 28:12', 'Génesis', 28, 12, 'Allí soñó que había una escalinata apoyada en la tierra, y cuyo extremo superior llegaba hasta el cielo. Por ella subían y bajaban los ángeles de Dios.'),
('nvi', 'Génesis 28:13', 'Génesis', 28, 13, 'En el sueño, el SEÑOR estaba de pie junto a él y le decía: «Yo soy el SEÑOR, el Dios de tu abuelo Abraham y de tu padre Isaac. A ti y a tu descendencia les daré la tierra sobre la que estás acostado.'),
('nvi', 'Génesis 28:14', 'Génesis', 28, 14, 'Tu descendencia será tan numerosa como el polvo de la tierra. Te extenderás de norte a sur, y de oriente a occidente, y todas las familias de la tierra serán bendecidas por medio de ti y de tu descendencia.'),
('nvi', 'Génesis 28:15', 'Génesis', 28, 15, 'Yo estoy contigo. Te protegeré por dondequiera que vayas, y te traeré de vuelta a esta tierra. No te abandonaré hasta cumplir con todo lo que te he prometido.»'),
('nvi', 'Génesis 28:16', 'Génesis', 28, 16, 'Al despertar Jacob de su sueño, pensó: «En realidad, el SEÑOR está en este lugar, y yo no me había dado cuenta.»'),
('nvi', 'Génesis 28:17', 'Génesis', 28, 17, 'Y con mucho temor, añadió: «¡Qué asombroso es este lugar! Es nada menos que la casa de Dios; ¡es la puerta del cielo!»'),
('nvi', 'Génesis 28:18', 'Génesis', 28, 18, 'A la mañana siguiente Jacob se levantó temprano, tomó la piedra que había usado como almohada, la erigió como una estela y derramó aceite sobre ella.'),
('nvi', 'Génesis 28:19', 'Génesis', 28, 19, 'En aquel lugar había una ciudad que se llamaba Luz, pero Jacob le cambió el nombre y le puso Betel.'),
('nvi', 'Génesis 28:20', 'Génesis', 28, 20, 'Luego Jacob hizo esta promesa: «Si Dios me acompaña y me protege en este viaje que estoy haciendo, y si me da alimento y ropa para vestirme,'),
('nvi', 'Génesis 28:21', 'Génesis', 28, 21, 'y si regreso sano y salvo a la casa de mi padre, entonces el SEÑOR será mi Dios.'),
('nvi', 'Génesis 28:22', 'Génesis', 28, 22, 'Y esta piedra que yo erigí como pilar será casa de Dios, y de todo lo que Dios me dé, le daré la décima parte.»'),
('nvi', 'Génesis 29:1', 'Génesis', 29, 1, 'Jacob continuó su viaje y llegó a la tierra de los orientales.'),
('nvi', 'Génesis 29:2', 'Génesis', 29, 2, 'Al llegar vio, en medio del campo, un pozo donde descansaban tres rebaños de ovejas, ya que éstas bebían agua de allí. Sobre la boca del pozo había una piedra muy grande.'),
('nvi', 'Génesis 29:3', 'Génesis', 29, 3, 'Por eso los pastores corrían la piedra sólo cuando estaban juntos todos los rebaños, y luego de abrevar a las ovejas volvían a colocarla en su lugar, sobre la boca del pozo.'),
('nvi', 'Génesis 29:4', 'Génesis', 29, 4, 'Jacob les preguntó a los pastores: —¿De dónde son ustedes? —Somos de Jarán —respondieron.'),
('nvi', 'Génesis 29:5', 'Génesis', 29, 5, '—¿Conocen a Labán, el hijo de Najor? —volvió a preguntar Jacob. —Claro que sí —respondieron.'),
('nvi', 'Génesis 29:6', 'Génesis', 29, 6, 'Jacob siguió preguntando: —¿Se encuentra bien de salud? —Sí, está bien —le contestaron—. A propósito, ahí viene su hija Raquel con las ovejas.'),
('nvi', 'Génesis 29:7', 'Génesis', 29, 7, 'Entonces Jacob les dijo: —Todavía estamos en pleno día, y es muy temprano para encerrar el rebaño. ¿Por qué no les dan de beber a las ovejas y las llevan a pastar?'),
('nvi', 'Génesis 29:8', 'Génesis', 29, 8, 'Y ellos respondieron: —No podemos hacerlo hasta que se junten todos los rebaños y los pastores quiten la piedra que está sobre la boca del pozo. Sólo entonces podremos dar de beber a las ovejas.'),
('nvi', 'Génesis 29:9', 'Génesis', 29, 9, 'Todavía estaba Jacob hablando con ellos, cuando Raquel llegó con las ovejas de su padre, pues era ella quien las cuidaba.'),
('nvi', 'Génesis 29:10', 'Génesis', 29, 10, 'En cuanto Jacob vio a Raquel, hija de su tío Labán, con las ovejas de éste, se acercó y quitó la piedra que estaba sobre la boca del pozo, y les dio de beber a las ovejas.'),
('nvi', 'Génesis 29:11', 'Génesis', 29, 11, 'Luego besó a Raquel, rompió en llanto,'),
('nvi', 'Génesis 29:12', 'Génesis', 29, 12, 'y le contó que era pariente de Labán, por ser hijo de su hermana Rebeca. Raquel salió entonces corriendo a contárselo a su padre.'),
('nvi', 'Génesis 29:13', 'Génesis', 29, 13, 'Al oír Labán las noticias acerca de su sobrino Jacob, salió a recibirlo y, entre abrazos y besos, lo llevó a su casa. Allí Jacob le contó todo lo que había sucedido,'),
('nvi', 'Génesis 29:14', 'Génesis', 29, 14, 'y Labán le dijo: «Realmente, tú eres de mi propia sangre.» Jacob había estado ya un mes con Labán'),
('nvi', 'Génesis 29:15', 'Génesis', 29, 15, 'cuando éste le dijo: —Por más que seas mi pariente, no vas a trabajar para mí gratis. Dime cuánto quieres ganar.'),
('nvi', 'Génesis 29:16', 'Génesis', 29, 16, 'Labán tenía dos hijas. La mayor se llamaba Lea, y la menor, Raquel.'),
('nvi', 'Génesis 29:17', 'Génesis', 29, 17, 'Lea tenía ojos apagados, mientras que Raquel era una mujer muy hermosa.'),
('nvi', 'Génesis 29:18', 'Génesis', 29, 18, 'Como Jacob se había enamorado de Raquel, le dijo a su tío: —Me ofrezco a trabajar para ti siete años, a cambio de Raquel, tu hija menor.'),
('nvi', 'Génesis 29:19', 'Génesis', 29, 19, 'Labán le contestó: —Es mejor que te la entregue a ti, y no a un extraño. Quédate conmigo.'),
('nvi', 'Génesis 29:20', 'Génesis', 29, 20, 'Así que Jacob trabajó siete años para poder casarse con Raquel, pero como estaba muy enamorado de ella le pareció poco tiempo.'),
('nvi', 'Génesis 29:21', 'Génesis', 29, 21, 'Entonces Jacob le dijo a Labán: —Ya he cumplido con el tiempo pactado. Dame mi mujer para que me case con ella.'),
('nvi', 'Génesis 29:22', 'Génesis', 29, 22, 'Labán reunió a toda la gente del lugar y ofreció una gran fiesta.'),
('nvi', 'Génesis 29:23', 'Génesis', 29, 23, 'Pero cuando llegó la noche, tomó a su hija Lea y se la entregó a Jacob, y Jacob se acostó con ella.'),
('nvi', 'Génesis 29:24', 'Génesis', 29, 24, 'Además, como Lea tenía una criada que se llamaba Zilpá, Labán se la dio, para que la atendiera.'),
('nvi', 'Génesis 29:25', 'Génesis', 29, 25, 'A la mañana siguiente, Jacob se dio cuenta de que había estado con Lea, y le reclamó a Labán: —¿Qué me has hecho? ¿Acaso no trabajé contigo para casarme con Raquel? ¿Por qué me has engañado?'),
('nvi', 'Génesis 29:26', 'Génesis', 29, 26, 'Labán le contestó: —La costumbre en nuestro país es casar primero a la mayor y luego a la menor.'),
('nvi', 'Génesis 29:27', 'Génesis', 29, 27, 'Por eso, cumple ahora con la semana nupcial de ésta, y por siete años más de trabajo te daré la otra.'),
('nvi', 'Génesis 29:28', 'Génesis', 29, 28, 'Así lo hizo Jacob, y cuando terminó la semana nupcial de la primera, Labán le entregó a Raquel por esposa.'),
('nvi', 'Génesis 29:29', 'Génesis', 29, 29, 'También Raquel tenía una criada, llamada Bilhá, y Labán se la dio para que la atendiera.'),
('nvi', 'Génesis 29:30', 'Génesis', 29, 30, 'Jacob entonces se acostó con Raquel, y la amó mucho más que a Lea, aunque tuvo que trabajar para Labán siete años más.'),
('nvi', 'Génesis 29:31', 'Génesis', 29, 31, 'Cuando el SEÑOR vio que Lea no era amada, le concedió hijos. Mientras tanto, Raquel permaneció estéril.'),
('nvi', 'Génesis 29:32', 'Génesis', 29, 32, 'Lea quedó embarazada y dio a luz un hijo, al que llamó Rubén, porque dijo: «El SEÑOR ha visto mi aflicción; ahora sí me amará mi esposo.»'),
('nvi', 'Génesis 29:33', 'Génesis', 29, 33, 'Lea volvió a quedar embarazada y dio a luz otro hijo, al que llamó Simeón, porque dijo: «Llegó a oídos del SEÑOR que no soy amada, y por eso me dio también este hijo.»'),
('nvi', 'Génesis 29:34', 'Génesis', 29, 34, 'Luego quedó embarazada de nuevo y dio a luz un tercer hijo, al que llamó Leví, porque dijo: «Ahora sí me amará mi esposo, porque le he dado tres hijos.»'),
('nvi', 'Génesis 29:35', 'Génesis', 29, 35, 'Lea volvió a quedar embarazada, y dio a luz un cuarto hijo, al que llamó Judá porque dijo: «Esta vez alabaré al SEÑOR.» Después de esto, dejó de dar a luz.'),
('nvi', 'Génesis 30:1', 'Génesis', 30, 1, 'Cuando Raquel se dio cuenta de que no le podía dar hijos a Jacob, tuvo envidia de su hermana y le dijo a Jacob: —¡Dame hijos! Si no me los das, ¡me muero!'),
('nvi', 'Génesis 30:2', 'Génesis', 30, 2, 'Pero Jacob se enojó muchísimo con ella y le dijo: —¿Acaso crees que soy Dios? ¡Es él quien te ha hecho estéril!'),
('nvi', 'Génesis 30:3', 'Génesis', 30, 3, '—Aquí tienes a mi criada Bilhá —propuso Raquel—. Acuéstate con ella. Así ella dará a luz sobre mis rodillas, y por medio de ella también yo podré formar una familia.'),
('nvi', 'Génesis 30:4', 'Génesis', 30, 4, 'Entonces Raquel le dio a Jacob por mujer su criada Bilhá, y Jacob se acostó con ella.'),
('nvi', 'Génesis 30:5', 'Génesis', 30, 5, 'Bilhá quedó embarazada y le dio un hijo a Jacob.'),
('nvi', 'Génesis 30:6', 'Génesis', 30, 6, 'Y Raquel exclamó: «¡Dios me ha hecho justicia! ¡Escuchó mi plegaria y me ha dado un hijo!» Por eso Raquel le puso por nombre Dan.'),
('nvi', 'Génesis 30:7', 'Génesis', 30, 7, 'Después Bilhá, la criada de Raquel, quedó embarazada otra vez y dio a luz un segundo hijo de Jacob.'),
('nvi', 'Génesis 30:8', 'Génesis', 30, 8, 'Y Raquel dijo: «He tenido una lucha muy grande con mi hermana, pero he vencido.» Por eso Raquel lo llamó Neftalí.'),
('nvi', 'Génesis 30:9', 'Génesis', 30, 9, 'Lea, al ver que ya no podía tener hijos, tomó a su criada Zilpá y se la entregó a Jacob por mujer,'),
('nvi', 'Génesis 30:10', 'Génesis', 30, 10, 'y ésta le dio a Jacob un hijo.'),
('nvi', 'Génesis 30:11', 'Génesis', 30, 11, 'Entonces Lea exclamó: «¡Qué suerte!» Por eso lo llamó Gad.'),
('nvi', 'Génesis 30:12', 'Génesis', 30, 12, 'Zilpá, la criada de Lea, le dio un segundo hijo a Jacob.'),
('nvi', 'Génesis 30:13', 'Génesis', 30, 13, 'Lea volvió a exclamar: «¡Qué feliz soy! Las mujeres me dirán que soy feliz.» Por eso lo llamó Aser.'),
('nvi', 'Génesis 30:14', 'Génesis', 30, 14, 'Durante los días de la cosecha de trigo, Rubén salió al campo. Allí encontró unas frutas llamadas mandrágoras, y se las llevó a Lea, su madre. Entonces Raquel le dijo a Lea: —Por favor, dame algunas mandrágoras de las que te trajo tu hijo.'),
('nvi', 'Génesis 30:15', 'Génesis', 30, 15, 'Pero Lea le contestó: —¿Te parece poco el haberme quitado a mi marido, que ahora quieres también quitarme las mandrágoras de mi hijo? —Bueno —contestó Raquel—, te propongo que, a cambio de las mandrágoras de tu hijo, Jacob duerma contigo esta noche.'),
('nvi', 'Génesis 30:16', 'Génesis', 30, 16, 'Al anochecer, cuando Jacob volvía del campo, Lea salió a su encuentro y le dijo: —Hoy te acostarás conmigo, porque te he alquilado a cambio de las mandrágoras de mi hijo. Y Jacob durmió con ella esa noche.'),
('nvi', 'Génesis 30:17', 'Génesis', 30, 17, 'Dios escuchó a Lea, y ella quedó embarazada y le dio a Jacob un quinto hijo.'),
('nvi', 'Génesis 30:18', 'Génesis', 30, 18, 'Entonces dijo Lea: «Dios me ha recompensado, porque yo le entregué mi criada a mi esposo.» Por eso lo llamó Isacar.'),
('nvi', 'Génesis 30:19', 'Génesis', 30, 19, 'Lea quedó embarazada de nuevo, y le dio a Jacob un sexto hijo.'),
('nvi', 'Génesis 30:20', 'Génesis', 30, 20, '«Dios me ha favorecido con un buen regalo —dijo Lea—. Esta vez mi esposo se quedará conmigo, porque le he dado seis hijos.» Por eso lo llamó Zabulón.'),
('nvi', 'Génesis 30:21', 'Génesis', 30, 21, 'Luego Lea dio a luz una hija, a la cual llamó Dina.'),
('nvi', 'Génesis 30:22', 'Génesis', 30, 22, 'Pero Dios también se acordó de Raquel; la escuchó y le quitó la esterilidad.'),
('nvi', 'Génesis 30:23', 'Génesis', 30, 23, 'Fue así como ella quedó embarazada y dio a luz un hijo. Entonces exclamó: «Dios ha borrado mi desgracia.»'),
('nvi', 'Génesis 30:24', 'Génesis', 30, 24, 'Por eso lo llamó José, y dijo: «Quiera el SEÑOR darme otro hijo.»'),
('nvi', 'Génesis 30:25', 'Génesis', 30, 25, 'Después de que Raquel dio a luz a José, Jacob le dijo a Labán: —Déjame regresar a mi hogar y a mi propia tierra.'),
('nvi', 'Génesis 30:26', 'Génesis', 30, 26, 'Dame las mujeres por las que te he servido, y mis hijos, y déjame ir. Tú bien sabes cómo he trabajado para ti.'),
('nvi', 'Génesis 30:27', 'Génesis', 30, 27, 'Pero Labán le contestó: —Por favor, quédate. He sabido por adivinación que, gracias a ti, el SEÑOR me ha bendecido.'),
('nvi', 'Génesis 30:28', 'Génesis', 30, 28, 'Y le propuso: —Fija tú mismo el salario que quieras ganar, y yo te lo pagaré.'),
('nvi', 'Génesis 30:29', 'Génesis', 30, 29, 'Jacob le respondió: —Tú bien sabes cómo he trabajado, y cómo gracias a mis desvelos han mejorado tus animales.'),
('nvi', 'Génesis 30:30', 'Génesis', 30, 30, 'Lo que tenías antes de mi venida, que era muy poco, se ha multiplicado enormemente. Gracias a mí, el SEÑOR te ha bendecido. Ahora quiero hacer algo por mi propia familia.'),
('nvi', 'Génesis 30:31', 'Génesis', 30, 31, '—¿Cuánto quieres que te pague? —preguntó Labán. —No tienes que pagarme nada —respondió Jacob—. Si aceptas lo que estoy por proponerte, seguiré cuidando tus ovejas.'),
('nvi', 'Génesis 30:32', 'Génesis', 30, 32, 'Hoy, cuando pase yo con todo tu rebaño, tú irás apartando toda oveja manchada o moteada, y todos los corderos negros, y todos los cabritos manchados o moteados. Ellos serán mi salario.'),
('nvi', 'Génesis 30:33', 'Génesis', 30, 33, 'Así, el día de mañana, cuando vengas a controlar lo que he ganado, mi honradez responderá por mí: si encuentras alguna oveja o cabrito que no sea manchado o moteado, o algún cordero que no sea negro, será que te lo he robado.'),
('nvi', 'Génesis 30:34', 'Génesis', 30, 34, '—Está bien —acordó Labán—, acepto tu propuesta.'),
('nvi', 'Génesis 30:35', 'Génesis', 30, 35, 'Ese mismo día Labán apartó todos los chivos rayados y moteados, todas las cabras manchadas y moteadas, todas las que tenían alguna mancha blanca, y todos los corderos negros, y los puso al cuidado de sus hijos.'),
('nvi', 'Génesis 30:36', 'Génesis', 30, 36, 'Después de eso, puso una distancia de tres días de viaje entre él y Jacob. Mientras tanto, Jacob seguía cuidando las otras ovejas de Labán.'),
('nvi', 'Génesis 30:37', 'Génesis', 30, 37, 'Jacob cortó ramas verdes de álamo, de almendro y de plátano, y las peló de tal manera que quedaran franjas blancas al descubierto.'),
('nvi', 'Génesis 30:38', 'Génesis', 30, 38, 'Luego tomó las ramas que había pelado, y las puso en todos los abrevaderos para que el rebaño las tuviera enfrente cuando se acercara a beber agua. Cuando las ovejas estaban en celo y llegaban a los abrevaderos,'),
('nvi', 'Génesis 30:39', 'Génesis', 30, 39, 'los machos se unían con las hembras frente a las ramas, y así tenían crías rayadas, moteadas o manchadas.'),
('nvi', 'Génesis 30:40', 'Génesis', 30, 40, 'Entonces Jacob apartaba estos corderos y los ponía frente a los animales rayados y negros del rebaño de Labán. De esta manera logró crear su propio rebaño, diferente al de Labán.'),
('nvi', 'Génesis 30:41', 'Génesis', 30, 41, 'Además, cuando las hembras más robustas estaban en celo, Jacob colocaba las ramas en los bebederos, frente a los animales, para que se unieran mirando hacia las ramas.'),
('nvi', 'Génesis 30:42', 'Génesis', 30, 42, 'Pero cuando llegaban los animales más débiles, no colocaba las ramas. Así los animales débiles eran para Labán y los robustos eran para Jacob.'),
('nvi', 'Génesis 30:43', 'Génesis', 30, 43, 'De esta manera Jacob prosperó muchísimo y llegó a tener muchos rebaños, criados y criadas, camellos y asnos.'),
('nvi', 'Génesis 31:1', 'Génesis', 31, 1, 'Pero Jacob se enteró de que los hijos de Labán andaban diciendo: «Jacob se ha ido apoderando de todo lo que le pertenecía a nuestro padre, y se ha enriquecido a costa suya.»'),
('nvi', 'Génesis 31:2', 'Génesis', 31, 2, 'También notó que Labán ya no lo trataba como antes.'),
('nvi', 'Génesis 31:3', 'Génesis', 31, 3, 'Entonces el SEÑOR le dijo a Jacob: «Vuélvete a la tierra de tus padres, donde están tus parientes, que yo estaré contigo.»'),
('nvi', 'Génesis 31:4', 'Génesis', 31, 4, 'Jacob mandó llamar a Raquel y a Lea al campo donde estaba el rebaño,'),
('nvi', 'Génesis 31:5', 'Génesis', 31, 5, 'y les dijo: —Me he dado cuenta de que su padre ya no me trata como antes. ¡Pero el Dios de mi padre ha estado conmigo!'),
('nvi', 'Génesis 31:6', 'Génesis', 31, 6, 'Ustedes saben muy bien que yo he trabajado para su padre Labán con todas mis fuerzas.'),
('nvi', 'Génesis 31:7', 'Génesis', 31, 7, 'No obstante, él me ha engañado y me ha cambiado el salario muchas veces. Pero Dios no le ha permitido causarme ningún daño.'),
('nvi', 'Génesis 31:8', 'Génesis', 31, 8, 'Si él acordaba conmigo: “Los animales manchados serán tu salario”, todas las hembras tenían crías manchadas; y si él acordaba: “Los animales rayados serán tu salario”, todas las hembras tenían crías rayadas.'),
('nvi', 'Génesis 31:9', 'Génesis', 31, 9, 'Así Dios le ha quitado el ganado al padre de ustedes, y me lo ha dado a mí.'),
('nvi', 'Génesis 31:10', 'Génesis', 31, 10, '»En cierta ocasión, durante la época en que los animales estaban en celo, tuve un sueño. En ese sueño veía que los chivos que cubrían a las cabras eran rayados, manchados o moteados.'),
('nvi', 'Génesis 31:11', 'Génesis', 31, 11, 'En ese mismo sueño, el ángel de Dios me llamó: “¡Jacob!”Y yo le respondí: “Aquí estoy.”'),
('nvi', 'Génesis 31:12', 'Génesis', 31, 12, 'Entonces él me dijo: “Fíjate bien, y te darás cuenta de que todos los chivos que cubren a las cabras son rayados, manchados o moteados. Yo he visto todo lo que te ha hecho Labán.'),
('nvi', 'Génesis 31:13', 'Génesis', 31, 13, 'Yo soy el Dios de Betel, donde ungiste una estela y me hiciste una promesa. Vete ahora de esta tierra, y vuelve a la tierra de tu origen.”'),
('nvi', 'Génesis 31:14', 'Génesis', 31, 14, 'Raquel y Lea le respondieron: —Ya no tenemos ninguna parte ni herencia en la casa de nuestro padre.'),
('nvi', 'Génesis 31:15', 'Génesis', 31, 15, 'Al contrario, nos ha tratado como si fuéramos extranjeras. Nos ha vendido, y se ha gastado todo lo que recibió por nosotras.'),
('nvi', 'Génesis 31:16', 'Génesis', 31, 16, 'Lo cierto es que toda la riqueza que Dios le ha quitado a nuestro padre es nuestra y de nuestros hijos. Por eso, haz ahora todo lo que Dios te ha ordenado.'),
('nvi', 'Génesis 31:17', 'Génesis', 31, 17, 'Entonces Jacob se preparó y montó a sus hijos y a sus esposas en los camellos,'),
('nvi', 'Génesis 31:18', 'Génesis', 31, 18, 'puso en marcha todo su ganado, junto con todos los bienes que había acumulado en Padán Aram, y se dirigió hacia la tierra de Canaán, donde vivía su padre Isaac.'),
('nvi', 'Génesis 31:19', 'Génesis', 31, 19, 'Mientras Labán estaba ausente esquilando sus ovejas, Raquel aprovechó el momento para robarse los ídolos familiares.'),
('nvi', 'Génesis 31:20', 'Génesis', 31, 20, 'Fue así como Jacob engañó a Labán el arameo y huyó sin decirle nada.'),
('nvi', 'Génesis 31:21', 'Génesis', 31, 21, 'Jacob se escapó con todo lo que tenía. Una vez que cruzó el río Éufrates, se encaminó hacia la región montañosa de Galaad.'),
('nvi', 'Génesis 31:22', 'Génesis', 31, 22, 'Al tercer día le informaron a Labán que Jacob se había escapado.'),
('nvi', 'Génesis 31:23', 'Génesis', 31, 23, 'Entonces Labán reunió a sus parientes y lo persiguió durante siete días, hasta que lo alcanzó en los montes de Galaad.'),
('nvi', 'Génesis 31:24', 'Génesis', 31, 24, 'Pero esa misma noche Dios se le apareció en un sueño a Labán el arameo, y le dijo: «¡Cuidado con amenazar a Jacob!»'),
('nvi', 'Génesis 31:25', 'Génesis', 31, 25, 'Labán alcanzó a Jacob en los montes de Galaad, donde éste había acampado. También Labán acampó allí, junto con sus parientes,'),
('nvi', 'Génesis 31:26', 'Génesis', 31, 26, 'y le reclamó a Jacob: —¿Qué has hecho? ¡Me has engañado, y te has llevado a mis hijas como si fueran prisioneras de guerra!'),
('nvi', 'Génesis 31:27', 'Génesis', 31, 27, '¿Por qué has huido en secreto, con engaños y sin decirme nada? Yo te habría despedido con alegría, y con música de tambores y de arpa.'),
('nvi', 'Génesis 31:28', 'Génesis', 31, 28, 'Ni siquiera me dejaste besar a mis hijas y a mis nietos. ¡Te has comportado como un necio!'),
('nvi', 'Génesis 31:29', 'Génesis', 31, 29, 'Mi poder es más que suficiente para hacerles daño, pero anoche el Dios de tu padre me habló y me dijo: “¡Cuidado con amenazar a Jacob!”'),
('nvi', 'Génesis 31:30', 'Génesis', 31, 30, 'Ahora bien, entiendo que hayas querido irte porque añoras la casa de tu padre, pero, ¿por qué me robaste mis dioses?'),
('nvi', 'Génesis 31:31', 'Génesis', 31, 31, 'Jacob le respondió: —La verdad es que me entró mucho miedo, porque pensé que podrías quitarme a tus hijas por la fuerza.'),
('nvi', 'Génesis 31:32', 'Génesis', 31, 32, 'Pero si encuentras tus dioses en poder de alguno de los que están aquí, tal persona no quedará con vida. Pongo a nuestros parientes como testigos: busca lo que sea tuyo, y llévatelo. Pero Jacob no sabía que Raquel se había robado los ídolos de Labán,'),
('nvi', 'Génesis 31:33', 'Génesis', 31, 33, 'así que Labán entró en la carpa de Jacob, luego en la de Lea y en la de las dos criadas, pero no encontró lo que buscaba. Cuando salió de la carpa de Lea, entró en la de Raquel.'),
('nvi', 'Génesis 31:34', 'Génesis', 31, 34, 'Pero Raquel, luego de tomar los ídolos y esconderlos bajo la montura del camello, se sentó sobre ellos. Labán los buscó por toda la carpa, pero no los encontró.'),
('nvi', 'Génesis 31:35', 'Génesis', 31, 35, 'Entonces Raquel le dijo a su padre: —Por favor, no se enoje mi padre si no puedo levantarme ante usted, pero es que estoy en mi período de menstruación. Labán buscó los ídolos, pero no logró encontrarlos.'),
('nvi', 'Génesis 31:36', 'Génesis', 31, 36, 'Entonces Jacob se enojó con Labán, e indignado le reclamó: —¿Qué crimen o pecado he cometido, para que me acoses de esta manera?'),
('nvi', 'Génesis 31:37', 'Génesis', 31, 37, 'Ya has registrado todas mis cosas, ¿y acaso has encontrado algo que te pertenezca? Si algo has encontrado, ponlo aquí, frente a nuestros parientes, y que ellos determinen quién de los dos tiene la razón.'),
('nvi', 'Génesis 31:38', 'Génesis', 31, 38, 'Durante los veinte años que estuve contigo, nunca abortaron tus ovejas ni tus cabras, ni jamás me comí un carnero de tus rebaños.'),
('nvi', 'Génesis 31:39', 'Génesis', 31, 39, 'Nunca te traje un animal despedazado por las fieras, ya que yo mismo me hacía cargo de esa pérdida. Además, lo que se robaban de día o de noche, tú me lo reclamabas.'),
('nvi', 'Génesis 31:40', 'Génesis', 31, 40, 'De día me consumía el calor, y de noche me moría de frío, y ni dormir podía.'),
('nvi', 'Génesis 31:41', 'Génesis', 31, 41, 'De los veinte años que estuve en tu casa, catorce te serví por tus dos hijas, y seis por tu ganado, y muchas veces me cambiaste el salario.'),
('nvi', 'Génesis 31:42', 'Génesis', 31, 42, 'Si no hubiera estado conmigo el Dios de mi padre, el Dios de Abraham, el Dios a quien Isaac temía, seguramente me habrías despedido con las manos vacías. Pero Dios vio mi aflicción y el trabajo de mis manos, y anoche me hizo justicia.'),
('nvi', 'Génesis 31:43', 'Génesis', 31, 43, 'Labán le replicó a Jacob: —Estas mujeres son mis hijas, y estos muchachos son mis nietos; mías también son las ovejas; todo lo que ves me pertenece. Pero, ¿qué podría hacerles ahora a mis hijas y a mis nietos?'),
('nvi', 'Génesis 31:44', 'Génesis', 31, 44, 'Hagamos un pacto tú y yo, y que ese pacto nos sirva como testimonio.'),
('nvi', 'Génesis 31:45', 'Génesis', 31, 45, 'Entonces Jacob tomó una piedra, la levantó como una estela,'),
('nvi', 'Génesis 31:46', 'Génesis', 31, 46, 'y les dijo a sus parientes: —¡Junten piedras! Ellos juntaron piedras, las amontonaron, y comieron allí, junto al montón de piedras.'),
('nvi', 'Génesis 31:47', 'Génesis', 31, 47, 'A ese lugar Labán le puso por nombre Yegar Saduta, mientras que Jacob lo llamó Galaad.'),
('nvi', 'Génesis 31:48', 'Génesis', 31, 48, '—Este montón de piedras —declaró Labán—nos servirá de testimonio. Por eso se le llamó Galaad a ese lugar,'),
('nvi', 'Génesis 31:49', 'Génesis', 31, 49, 'y también se le llamó Mizpa, porque Labán juró: —Que el SEÑOR nos vigile cuando ya estemos lejos el uno del otro.'),
('nvi', 'Génesis 31:50', 'Génesis', 31, 50, 'Si tú maltratas a mis hijas, o tomas otras mujeres que no sean ellas, recuerda que Dios es nuestro testigo, aunque no haya ningún otro testigo entre nosotros.'),
('nvi', 'Génesis 31:51', 'Génesis', 31, 51, 'Mira este montón de piedras y la estela que he levantado entre nosotros —señaló Labán—.'),
('nvi', 'Génesis 31:52', 'Génesis', 31, 52, 'Ambos serán testigos de que ni tú ni yo cruzaremos esta línea con el propósito de hacernos daño.'),
('nvi', 'Génesis 31:53', 'Génesis', 31, 53, '¡Que el Dios de Abraham y el Dios de Najor sea nuestro juez! Entonces Jacob juró por el Dios a quien temía su padre Isaac.'),
('nvi', 'Génesis 31:54', 'Génesis', 31, 54, 'Luego ofreció un sacrificio en lo alto de un monte, e invitó a sus parientes a participar en la comida. Después de que todos comieron, pasaron la noche allí.'),
('nvi', 'Génesis 31:55', 'Génesis', 31, 55, 'A la madrugada del día siguiente Labán se levantó, besó y bendijo a sus nietos y a sus hijas, y regresó a su casa.'),
('nvi', 'Génesis 32:1', 'Génesis', 32, 1, 'Jacob también siguió su camino, pero unos ángeles de Dios salieron a su encuentro.'),
('nvi', 'Génesis 32:2', 'Génesis', 32, 2, 'Al verlos, exclamó: «¡Éste es el campamento de Dios!» Por eso llamó a ese lugar Majanayin.'),
('nvi', 'Génesis 32:3', 'Génesis', 32, 3, 'Luego Jacob envió mensajeros a su hermano Esaú, que estaba en la tierra de Seír, en la región de Edom.'),
('nvi', 'Génesis 32:4', 'Génesis', 32, 4, 'Y les ordenó que le dijeran: «Mi señor Esaú, su siervo Jacob nos ha enviado a decirle que él ha vivido en la casa de Labán todo este tiempo,'),
('nvi', 'Génesis 32:5', 'Génesis', 32, 5, 'y que ahora tiene vacas, asnos, ovejas, esclavos y esclavas. Le manda este mensaje, con la esperanza de ganarse su favor.»'),
('nvi', 'Génesis 32:6', 'Génesis', 32, 6, 'Cuando los mensajeros regresaron, le dijeron a Jacob: «Fuimos a hablar con su hermano Esaú, y ahora viene al encuentro de usted, acompañado de cuatrocientos hombres.»'),
('nvi', 'Génesis 32:7', 'Génesis', 32, 7, 'Jacob sintió mucho miedo, y se puso muy angustiado. Por eso dividió en dos grupos a la gente que lo acompañaba, y lo mismo hizo con las ovejas, las vacas y los camellos,'),
('nvi', 'Génesis 32:8', 'Génesis', 32, 8, 'pues pensó: «Si Esaú ataca a un grupo, el otro grupo podrá escapar.»'),
('nvi', 'Génesis 32:9', 'Génesis', 32, 9, 'Entonces Jacob se puso a orar: «SEÑOR, Dios de mi abuelo Abraham y de mi padre Isaac, que me dijiste que regresara a mi tierra y a mis familiares, y que me harías prosperar:'),
('nvi', 'Génesis 32:10', 'Génesis', 32, 10, 'realmente yo, tu siervo, no soy digno de la bondad y fidelidad con que me has privilegiado. Cuando crucé este río Jordán, no tenía más que mi bastón; pero ahora he llegado a formar dos campamentos.'),
('nvi', 'Génesis 32:11', 'Génesis', 32, 11, '¡Líbrame del poder de mi hermano Esaú, pues tengo miedo de que venga a matarme a mí y a las madres y a los niños!'),
('nvi', 'Génesis 32:12', 'Génesis', 32, 12, 'Tú mismo afirmaste que me harías prosperar, y que mis descendientes serían tan numerosos como la arena del mar, que no se puede contar.»'),
('nvi', 'Génesis 32:13', 'Génesis', 32, 13, 'Jacob pasó la noche en aquel lugar, y de lo que tenía consigo escogió, como regalo para su hermano Esaú,'),
('nvi', 'Génesis 32:14', 'Génesis', 32, 14, 'doscientas cabras, veinte chivos, doscientas ovejas, veinte carneros,'),
('nvi', 'Génesis 32:15', 'Génesis', 32, 15, 'treinta camellas con sus crías, cuarenta vacas, diez novillos, veinte asnas y diez asnos.'),
('nvi', 'Génesis 32:16', 'Génesis', 32, 16, 'Luego los puso a cargo de sus siervos, cada manada por separado, y les dijo: «Vayan adelante, pero dejen un buen espacio entre manada y manada.»'),
('nvi', 'Génesis 32:17', 'Génesis', 32, 17, 'Al que iba al frente, le ordenó: «Cuando te encuentres con mi hermano Esaú y te pregunte de quién eres, a dónde te diriges y de quién es el ganado que llevas,'),
('nvi', 'Génesis 32:18', 'Génesis', 32, 18, 'le contestarás: “Es un regalo para usted, mi señor Esaú, que de sus ganados le manda su siervo Jacob. Además, él mismo viene detrás de nosotros.”»'),
('nvi', 'Génesis 32:19', 'Génesis', 32, 19, 'Jacob les dio la misma orden al segundo y al tercer grupo, y a todos los demás que iban detrás del ganado. Les dijo: «Cuando se encuentren con Esaú, le dirán todo esto,'),
('nvi', 'Génesis 32:20', 'Génesis', 32, 20, 'y añadirán: “Su siervo Jacob viene detrás de nosotros.”» Jacob pensaba: «Lo apaciguaré con los regalos que le llegarán primero, y luego me presentaré ante él; tal vez así me reciba bien.»'),
('nvi', 'Génesis 32:21', 'Génesis', 32, 21, 'De esta manera los regalos lo precedieron, pero Jacob se quedó esa noche en el campamento.'),
('nvi', 'Génesis 32:22', 'Génesis', 32, 22, 'Aquella misma noche Jacob se levantó, tomó a sus dos esposas, a sus dos esclavas y a sus once hijos, y cruzó el vado del río Jaboc.'),
('nvi', 'Génesis 32:23', 'Génesis', 32, 23, 'Una vez que lo habían cruzado, hizo pasar también todas sus posesiones,'),
('nvi', 'Génesis 32:24', 'Génesis', 32, 24, 'quedándose solo. Entonces un hombre luchó con él hasta el amanecer.'),
('nvi', 'Génesis 32:25', 'Génesis', 32, 25, 'Cuando ese hombre se dio cuenta de que no podía vencer a Jacob, lo tocó en la coyuntura de la cadera, y ésta se le dislocó mientras luchaban.'),
('nvi', 'Génesis 32:26', 'Génesis', 32, 26, 'Entonces el hombre le dijo: —¡Suéltame, que ya está por amanecer! —¡No te soltaré hasta que me bendigas! —respondió Jacob.'),
('nvi', 'Génesis 32:27', 'Génesis', 32, 27, '—¿Cómo te llamas? —le preguntó el hombre. —Me llamo Jacob —respondió.'),
('nvi', 'Génesis 32:28', 'Génesis', 32, 28, 'Entonces el hombre le dijo: —Ya no te llamarás Jacob, sino Israel, porque has luchado con Dios y con los hombres, y has vencido.'),
('nvi', 'Génesis 32:29', 'Génesis', 32, 29, '—Y tú, ¿cómo te llamas? —le preguntó Jacob. —¿Por qué preguntas cómo me llamo? —le respondió el hombre. Y en ese mismo lugar lo bendijo.'),
('nvi', 'Génesis 32:30', 'Génesis', 32, 30, 'Jacob llamó a ese lugar Penuel, porque dijo: «He visto a Dios cara a cara, y todavía sigo con vida.»'),
('nvi', 'Génesis 32:31', 'Génesis', 32, 31, 'Cruzaba Jacob por el lugar llamado Penuel, cuando salió el sol. A causa de su cadera dislocada iba rengueando.'),
('nvi', 'Génesis 32:32', 'Génesis', 32, 32, 'Por esta razón los israelitas no comen el tendón que está en la coyuntura de la cadera, porque a Jacob se le tocó en dicho tendón.'),
('nvi', 'Génesis 33:1', 'Génesis', 33, 1, 'Cuando Jacob alzó la vista y vio que Esaú se acercaba con cuatrocientos hombres, repartió a los niños entre Lea, Raquel y las dos esclavas.'),
('nvi', 'Génesis 33:2', 'Génesis', 33, 2, 'Al frente de todos colocó a las criadas con sus hijos, luego a Lea con sus hijos, y por último a Raquel con José.'),
('nvi', 'Génesis 33:3', 'Génesis', 33, 3, 'Jacob, por su parte, se adelantó a ellos, inclinándose hasta el suelo siete veces mientras se iba acercando a su hermano.'),
('nvi', 'Génesis 33:4', 'Génesis', 33, 4, 'Pero Esaú corrió a su encuentro y, echándole los brazos al cuello, lo abrazó y lo besó. Entonces los dos se pusieron a llorar.'),
('nvi', 'Génesis 33:5', 'Génesis', 33, 5, 'Luego Esaú alzó la vista y, al ver a las mujeres y a los niños, preguntó: —¿Quiénes son estos que te acompañan? —Son los hijos que Dios le ha concedido a tu siervo —respondió Jacob.'),
('nvi', 'Génesis 33:6', 'Génesis', 33, 6, 'Las esclavas y sus hijos se acercaron y se inclinaron ante Esaú.'),
('nvi', 'Génesis 33:7', 'Génesis', 33, 7, 'Luego, Lea y sus hijos hicieron lo mismo y, por último, también se inclinaron José y Raquel.'),
('nvi', 'Génesis 33:8', 'Génesis', 33, 8, '—¿Qué significan todas estas manadas que han salido a mi encuentro? —preguntó Esaú. —Intentaba con ellas ganarme tu confianza —contestó Jacob.'),
('nvi', 'Génesis 33:9', 'Génesis', 33, 9, '—Hermano mío —repuso Esaú—, ya tengo más que suficiente. Quédate con lo que te pertenece.'),
('nvi', 'Génesis 33:10', 'Génesis', 33, 10, '—No, por favor —insistió Jacob—; si me he ganado tu confianza, acepta este presente que te ofrezco. Ya que me has recibido tan bien, ¡ver tu rostro es como ver a Dios mismo!'),
('nvi', 'Génesis 33:11', 'Génesis', 33, 11, 'Acéptame el regalo que te he traído. Dios ha sido muy bueno conmigo, y tengo más de lo que necesito. Fue tanta la insistencia de Jacob que, finalmente, Esaú aceptó.'),
('nvi', 'Génesis 33:12', 'Génesis', 33, 12, 'Más tarde, Esaú le dijo: —Sigamos nuestro viaje; yo te acompañaré.'),
('nvi', 'Génesis 33:13', 'Génesis', 33, 13, 'Pero Jacob se disculpó: —Mi hermano y señor debe saber que los niños son todavía muy débiles, y que las ovejas y las vacas acaban de tener cría, y debo cuidarlas. Si les exijo demasiado, en un solo día se me puede morir todo el rebaño.'),
('nvi', 'Génesis 33:14', 'Génesis', 33, 14, 'Es mejor que mi señor se adelante a su siervo, que yo seguiré al paso de la manada y de los niños, hasta que nos encontremos en Seír.'),
('nvi', 'Génesis 33:15', 'Génesis', 33, 15, '—Está bien —accedió Esaú—, pero permíteme dejarte algunos de mis hombres para que te acompañen. —¿Para qué te vas a molestar? —contestó Jacob—. Lo importante es que me he ganado tu confianza.'),
('nvi', 'Génesis 33:16', 'Génesis', 33, 16, 'Aquel mismo día, Esaú regresó a Seír.'),
('nvi', 'Génesis 33:17', 'Génesis', 33, 17, 'Jacob, en cambio, se fue hacia Sucot, y allí se hizo una casa para él y cobertizos para su ganado. Por eso a ese lugar se le llamó Sucot.'),
('nvi', 'Génesis 33:18', 'Génesis', 33, 18, 'Cuando Jacob volvió de Padán Aram, llegó sano y salvo a la ciudad de Siquén, en Canaán, y acampó frente a ella.'),
('nvi', 'Génesis 33:19', 'Génesis', 33, 19, 'Luego, por cien monedas de plata les compró una parcela a los hijos de Jamor, el padre de Siquén, y allí instaló su carpa.'),
('nvi', 'Génesis 33:20', 'Génesis', 33, 20, 'También construyó un altar, y lo llamó El Elohé Israel.'),
('nvi', 'Génesis 34:1', 'Génesis', 34, 1, 'En cierta ocasión Dina, la hija que Jacob tuvo con Lea, salió a visitar a las mujeres del lugar.'),
('nvi', 'Génesis 34:2', 'Génesis', 34, 2, 'Cuando la vio Siquén, que era hijo de Jamor el heveo, jefe del lugar, la agarró por la fuerza, se acostó con ella y la violó.'),
('nvi', 'Génesis 34:3', 'Génesis', 34, 3, 'Pero luego se enamoró de ella y trató de ganarse su afecto.'),
('nvi', 'Génesis 34:4', 'Génesis', 34, 4, 'Entonces le dijo a su padre: «Consígueme a esta muchacha para que sea mi esposa.»'),
('nvi', 'Génesis 34:5', 'Génesis', 34, 5, 'Jacob se enteró de que Siquén había violado a su hija Dina pero, como sus hijos estaban en el campo cuidando el ganado, no dijo nada hasta que ellos regresaron.'),
('nvi', 'Génesis 34:6', 'Génesis', 34, 6, 'Mientras tanto Jamor, el padre de Siquén, salió en busca de Jacob para hablar con él.'),
('nvi', 'Génesis 34:7', 'Génesis', 34, 7, 'Cuando los hijos de Jacob volvieron del campo y se enteraron de lo sucedido, quedaron muy dolidos y, a la vez, llenos de ira. Siquén había cometido una ofensa muy grande contra Israel al abusar de su hija; era algo que nunca debió haber hecho.'),
('nvi', 'Génesis 34:8', 'Génesis', 34, 8, 'Pero Jamor les dijo: —Mi hijo Siquén está enamorado de la hermana de ustedes. Por favor, permitan que ella se case con él.'),
('nvi', 'Génesis 34:9', 'Génesis', 34, 9, 'Háganse parientes nuestros. Intercambiemos nuestras hijas en casamiento.'),
('nvi', 'Génesis 34:10', 'Génesis', 34, 10, 'Así ustedes podrán vivir entre nosotros y el país quedará a su disposición para que lo habiten, hagan negocios y adquieran terrenos.'),
('nvi', 'Génesis 34:11', 'Génesis', 34, 11, 'Siquén, por su parte, les dijo al padre y a los hermanos de Dina: —Si ustedes me hallan digno de su favor, yo les daré lo que me pidan.'),
('nvi', 'Génesis 34:12', 'Génesis', 34, 12, 'Pueden pedirme cuanta dote quieran, y exigirme muchos regalos, pero permitan que la muchacha se case conmigo.'),
('nvi', 'Génesis 34:13', 'Génesis', 34, 13, 'Sin embargo, por el hecho de que su hermana Dina había sido deshonrada, los hijos de Jacob les respondieron con engaños a Siquén y a su padre Jamor.'),
('nvi', 'Génesis 34:14', 'Génesis', 34, 14, '—Nosotros no podemos hacer algo así —les explicaron—. Sería una vergüenza para todos nosotros entregarle nuestra hermana a un hombre que no está circuncidado.'),
('nvi', 'Génesis 34:15', 'Génesis', 34, 15, 'Sólo aceptaremos con esta condición: que todos los varones entre ustedes se circunciden para que sean como nosotros.'),
('nvi', 'Génesis 34:16', 'Génesis', 34, 16, 'Entonces sí intercambiaremos nuestras hijas con las de ustedes en casamiento, y viviremos entre ustedes y formaremos un solo pueblo.'),
('nvi', 'Génesis 34:17', 'Génesis', 34, 17, 'Pero si no aceptan nuestra condición de circuncidarse, nos llevaremos a nuestra hermana y nos iremos de aquí.'),
('nvi', 'Génesis 34:18', 'Génesis', 34, 18, 'Jamor y Siquén estuvieron de acuerdo con la propuesta;'),
('nvi', 'Génesis 34:19', 'Génesis', 34, 19, 'y tan enamorado estaba Siquén de la hija de Jacob que no demoró en circuncidarse. Como Siquén era el hombre más respetado en la familia,'),
('nvi', 'Génesis 34:20', 'Génesis', 34, 20, 'su padre Jamor lo acompañó hasta la entrada de la ciudad, y allí hablaron con todos sus conciudadanos. Les dijeron:'),
('nvi', 'Génesis 34:21', 'Génesis', 34, 21, '—Estos hombres se han portado como amigos. Dejen que se establezcan en nuestro país, y que lleven a cabo sus negocios aquí, ya que hay suficiente espacio para ellos. Además, nosotros nos podremos casar con sus hijas, y ellos con las nuestras.'),
('nvi', 'Génesis 34:22', 'Génesis', 34, 22, 'Pero ellos aceptan quedarse entre nosotros y formar un solo pueblo, con una sola condición: que todos nuestros varones se circunciden, como lo hacen ellos.'),
('nvi', 'Génesis 34:23', 'Génesis', 34, 23, 'Aceptemos su condición, para que se queden a vivir entre nosotros. De esta manera su ganado, sus propiedades y todos sus animales serán nuestros.'),
('nvi', 'Génesis 34:24', 'Génesis', 34, 24, 'Todos los que se reunían a la entrada de la ciudad estuvieron de acuerdo con Jamor y con su hijo Siquén, y fue así como todos los varones fueron circuncidados.'),
('nvi', 'Génesis 34:25', 'Génesis', 34, 25, 'Al tercer día, cuando los varones todavía estaban muy adoloridos, dos de los hijos de Jacob, Simeón y Leví, hermanos de Dina, empuñaron cada uno su espada y fueron a la ciudad, donde los varones se encontraban desprevenidos, y los mataron a todos.'),
('nvi', 'Génesis 34:26', 'Génesis', 34, 26, 'También mataron a filo de espada a Jamor y a su hijo Siquén, sacaron a Dina de la casa de Siquén y se retiraron.'),
('nvi', 'Génesis 34:27', 'Génesis', 34, 27, 'Luego los otros hijos de Jacob llegaron y, pasando sobre los cadáveres, saquearon la ciudad en venganza por la deshonra que había sufrido su hermana.'),
('nvi', 'Génesis 34:28', 'Génesis', 34, 28, 'Se apropiaron de sus ovejas, ganado y asnos, y de todo lo que había en la ciudad y en el campo.'),
('nvi', 'Génesis 34:29', 'Génesis', 34, 29, 'Se llevaron todos sus bienes, y sus hijos y mujeres, y saquearon todo lo que encontraron en las casas.'),
('nvi', 'Génesis 34:30', 'Génesis', 34, 30, 'Entonces Jacob les dijo a Simeón y Leví: —Me han provocado un problema muy serio. De ahora en adelante los cananeos y ferezeos, habitantes de este lugar, me van a odiar. Si ellos se unen contra mí y me atacan, me matarán a mí y a toda mi familia, pues cuento con muy pocos hombres.'),
('nvi', 'Génesis 34:31', 'Génesis', 34, 31, 'Pero ellos replicaron: —¿Acaso podíamos dejar que él tratara a nuestra hermana como a una prostituta?'),
('nvi', 'Génesis 35:1', 'Génesis', 35, 1, 'Dios le dijo a Jacob: «Ponte en marcha, y vete a vivir a Betel. Erige allí un altar al Dios que se te apareció cuando escapabas de tu hermano Esaú.»'),
('nvi', 'Génesis 35:2', 'Génesis', 35, 2, 'Entonces Jacob dijo a su familia y a quienes lo acompañaban: «Desháganse de todos los dioses extraños que tengan con ustedes, purifíquense y cámbiense de ropa.'),
('nvi', 'Génesis 35:3', 'Génesis', 35, 3, 'Vámonos a Betel. Allí construiré un altar al Dios que me socorrió cuando estaba yo en peligro, y que me ha acompañado en mi camino.»'),
('nvi', 'Génesis 35:4', 'Génesis', 35, 4, 'Así que le entregaron a Jacob todos los dioses extraños que tenían, junto con los aretes que llevaban en las orejas, y Jacob los enterró a la sombra de la encina que estaba cerca de Siquén.'),
('nvi', 'Génesis 35:5', 'Génesis', 35, 5, 'Cuando partieron, nadie persiguió a la familia de Jacob, porque un terror divino se apoderó de las ciudades vecinas.'),
('nvi', 'Génesis 35:6', 'Génesis', 35, 6, 'Fue así como Jacob y quienes lo acompañaban llegaron a Luz, es decir, Betel, en la tierra de Canaán.'),
('nvi', 'Génesis 35:7', 'Génesis', 35, 7, 'Erigió un altar y llamó a ese lugar El Betel, porque allí se le había revelado Dios cuando escapaba de su hermano Esaú.'),
('nvi', 'Génesis 35:8', 'Génesis', 35, 8, 'Por esos días murió Débora, la nodriza de Rebeca, y la sepultaron a la sombra de la encina que se encuentra cerca de Betel. Por eso Jacob llamó a ese lugar Elón Bacut.'),
('nvi', 'Génesis 35:9', 'Génesis', 35, 9, 'Cuando Jacob regresó de Padán Aram, Dios se le apareció otra vez y lo bendijo'),
('nvi', 'Génesis 35:10', 'Génesis', 35, 10, 'con estas palabras: «Tu nombre es Jacob, pero ya no te llamarás así. De aquí en adelante te llamarás Israel.» Y, en efecto, ese fue el nombre que le puso.'),
('nvi', 'Génesis 35:11', 'Génesis', 35, 11, 'Luego Dios añadió: «Yo soy el Dios Todopoderoso. Sé fecundo y multiplícate. De ti nacerá una nación y una comunidad de naciones, y habrá reyes entre tus vástagos.'),
('nvi', 'Génesis 35:12', 'Génesis', 35, 12, 'La tierra que les di a Abraham y a Isaac te la doy a ti, y también a tus descendientes.»'),
('nvi', 'Génesis 35:13', 'Génesis', 35, 13, 'Y Dios se alejó del lugar donde había hablado con Jacob.'),
('nvi', 'Génesis 35:14', 'Génesis', 35, 14, 'Jacob erigió una estela de piedra en el lugar donde Dios le había hablado. Vertió sobre ella una libación, y la ungió con aceite,'),
('nvi', 'Génesis 35:15', 'Génesis', 35, 15, 'y al lugar donde Dios le había hablado lo llamó Betel.'),
('nvi', 'Génesis 35:16', 'Génesis', 35, 16, 'Después partieron de Betel. Cuando todavía estaban lejos de Efrata, Raquel dio a luz, pero tuvo un parto muy difícil.'),
('nvi', 'Génesis 35:17', 'Génesis', 35, 17, 'En el momento más difícil del parto, la partera le dijo: «¡No temas; estás por tener otro varón!»'),
('nvi', 'Génesis 35:18', 'Génesis', 35, 18, 'No obstante, ella se estaba muriendo, y en sus últimos suspiros alcanzó a llamar a su hijo Benoní, pero Jacob, su padre, le puso por nombre Benjamín.'),
('nvi', 'Génesis 35:19', 'Génesis', 35, 19, 'Así murió Raquel, y la sepultaron en el camino que va hacia Efrata, que es Belén.'),
('nvi', 'Génesis 35:20', 'Génesis', 35, 20, 'Sobre la tumba Jacob erigió una estela, que hasta el día de hoy señala el lugar donde Raquel fue sepultada.'),
('nvi', 'Génesis 35:21', 'Génesis', 35, 21, 'Israel siguió su camino y acampó más allá de Migdal Edar.'),
('nvi', 'Génesis 35:22', 'Génesis', 35, 22, 'Mientras vivía en esa región, Rubén fue y se acostó con Bilhá, la concubina de su padre. Cuando Israel se enteró de esto, se enojó muchísimo. Jacob tuvo doce hijos:'),
('nvi', 'Génesis 35:23', 'Génesis', 35, 23, 'Los hijos de Lea fueron Rubén, que era el primogénito de Jacob, Simeón, Leví, Judá, Isacar y Zabulón.'),
('nvi', 'Génesis 35:24', 'Génesis', 35, 24, 'Los hijos de Raquel fueron José y Benjamín.'),
('nvi', 'Génesis 35:25', 'Génesis', 35, 25, 'Los hijos de Bilhá, la esclava de Raquel, fueron Dan y Neftalí.'),
('nvi', 'Génesis 35:26', 'Génesis', 35, 26, 'Los hijos de Zilpá, la esclava de Lea, fueron Gad y Aser. Éstos fueron los hijos que tuvo Jacob en Padán Aram.'),
('nvi', 'Génesis 35:27', 'Génesis', 35, 27, 'Jacob volvió a la casa de su padre Isaac en Mamré, cerca de Quiriat Arbá, es decir, Hebrón, donde también habían vivido Abraham e Isaac.'),
('nvi', 'Génesis 35:28', 'Génesis', 35, 28, 'Isaac tenía ciento ochenta años'),
('nvi', 'Génesis 35:29', 'Génesis', 35, 29, 'cuando se reunió con sus antepasados. Era ya muy anciano cuando murió, y lo sepultaron sus hijos Esaú y Jacob.'),
('nvi', 'Génesis 36:1', 'Génesis', 36, 1, 'Éstos son los descendientes de Esaú, o sea Edom.'),
('nvi', 'Génesis 36:2', 'Génesis', 36, 2, 'Esaú se casó con mujeres cananeas: con Ada, hija de Elón el hitita; con Aholibama, hija de Aná y nieta de Zibeón el heveo;'),
('nvi', 'Génesis 36:3', 'Génesis', 36, 3, 'y con Basemat, hija de Ismael y hermana de Nebayot.'),
('nvi', 'Génesis 36:4', 'Génesis', 36, 4, 'Esaú tuvo estos hijos: con Ada tuvo a Elifaz; con Basemat, a Reuel;'),
('nvi', 'Génesis 36:5', 'Génesis', 36, 5, 'con Aholibama, a Jeús, Jalán y Coré. Éstos fueron los hijos que tuvo Esaú mientras vivía en la tierra de Canaán.'),
('nvi', 'Génesis 36:6', 'Génesis', 36, 6, 'Después Esaú tomó a sus esposas, hijos e hijas, y a todas las personas que lo acompañaban, junto con su ganado y todos sus animales, y todos los bienes que había adquirido en la tierra de Canaán, y se trasladó a otra región para alejarse de su hermano Jacob.'),
('nvi', 'Génesis 36:7', 'Génesis', 36, 7, 'Los dos habían acumulado tantos bienes que no podían estar juntos; la tierra donde vivían no bastaba para alimentar al ganado de ambos.'),
('nvi', 'Génesis 36:8', 'Génesis', 36, 8, 'Fue así como Esaú, o sea Edom, se asentó en la región montañosa de Seír.'),
('nvi', 'Génesis 36:9', 'Génesis', 36, 9, 'Éstos son los descendientes de Esaú, padre de los edomitas, que habitaron en la región montañosa de Seír.'),
('nvi', 'Génesis 36:10', 'Génesis', 36, 10, 'Los nombres de sus hijos son éstos: Elifaz hijo de Ada, esposa de Esaú; y Reuel hijo de Basemat, esposa de Esaú.'),
('nvi', 'Génesis 36:11', 'Génesis', 36, 11, 'Los hijos de Elifaz fueron Temán, Omar, Zefo, Gatán y Quenaz.'),
('nvi', 'Génesis 36:12', 'Génesis', 36, 12, 'Elifaz tuvo un hijo con una concubina suya, llamada Timná, al que llamó Amalec. Todos éstos fueron nietos de Ada, esposa de Esaú.'),
('nvi', 'Génesis 36:13', 'Génesis', 36, 13, 'Los hijos de Reuel fueron Najat, Zera, Sama y Mizá. Éstos fueron los nietos de Basemat, esposa de Esaú.'),
('nvi', 'Génesis 36:14', 'Génesis', 36, 14, 'Los hijos de la otra esposa de Esaú, Aholibama, que era hija de Aná y nieta de Zibeón fueron Jeús, Jalán y Coré.'),
('nvi', 'Génesis 36:15', 'Génesis', 36, 15, 'Éstos fueron los jefes de los descendientes de Esaú: De los hijos de Elifaz, primogénito de Esaú, los jefes fueron Temán, Omar, Zefo, Quenaz,'),
('nvi', 'Génesis 36:16', 'Génesis', 36, 16, 'Coré, Gatán y Amalec. Éstos fueron los jefes de los descendientes de Elifaz en la tierra de Edom, y todos ellos fueron nietos de Ada.'),
('nvi', 'Génesis 36:17', 'Génesis', 36, 17, 'De los hijos de Reuel hijo de Esaú, los jefes fueron Najat, Zera, Sama y Mizá. Éstos fueron los jefes de los descendientes de Reuel en la tierra de Edom, y todos ellos fueron nietos de Basemat, esposa de Esaú.'),
('nvi', 'Génesis 36:18', 'Génesis', 36, 18, 'De los hijos de Aholibama, hija de Aná y esposa de Esaú, los jefes fueron Jeús, Jalán y Coré.'),
('nvi', 'Génesis 36:19', 'Génesis', 36, 19, 'Éstos fueron descendientes de Esaú, también llamado Edom, y a su vez jefes de sus respectivas tribus.'),
('nvi', 'Génesis 36:20', 'Génesis', 36, 20, 'Éstos fueron los descendientes de Seír el horeo, que habitaban en aquella región: Lotán, Sobal, Zibeón, Aná,'),
('nvi', 'Génesis 36:21', 'Génesis', 36, 21, 'Disón, Ezer y Disán. Estos descendientes de Seír fueron los jefes de los horeos en la tierra de Edom.'),
('nvi', 'Génesis 36:22', 'Génesis', 36, 22, 'Los hijos de Lotán fueron Horí y Homán. Lotán tenía una hermana llamada Timná.'),
('nvi', 'Génesis 36:23', 'Génesis', 36, 23, 'Los hijos de Sobal fueron: Alván, Manajat, Ebal, Sefó y Onam.'),
('nvi', 'Génesis 36:24', 'Génesis', 36, 24, 'Los hijos de Zibeón fueron Ayá y Aná. Este último es el mismo que encontró las aguas termales en el desierto mientras cuidaba los asnos de su padre Zibeón.'),
('nvi', 'Génesis 36:25', 'Génesis', 36, 25, 'Los hijos de Aná fueron: Disón y Aholibama, hija de Aná.'),
('nvi', 'Génesis 36:26', 'Génesis', 36, 26, 'Los hijos de Disón fueron Hemdán, Esbán, Itrán y Querán.'),
('nvi', 'Génesis 36:27', 'Génesis', 36, 27, 'Los hijos de Ezer fueron Bilán, Zaván y Acán.'),
('nvi', 'Génesis 36:28', 'Génesis', 36, 28, 'Los hijos de Disán fueron Uz y Arán.'),
('nvi', 'Génesis 36:29', 'Génesis', 36, 29, 'Los jefes de los horeos fueron Lotán, Sobal, Zibeón, Aná,'),
('nvi', 'Génesis 36:30', 'Génesis', 36, 30, 'Disón, Ezer y Disán. Cada uno de ellos fue jefe de su tribu en la región de Seír.'),
('nvi', 'Génesis 36:31', 'Génesis', 36, 31, 'Antes de que los israelitas tuvieran rey, éstos fueron los reyes que reinaron en el país de Edom:'),
('nvi', 'Génesis 36:32', 'Génesis', 36, 32, 'Bela hijo de Beor, que reinó en Edom. El nombre de su ciudad era Dinaba.'),
('nvi', 'Génesis 36:33', 'Génesis', 36, 33, 'Cuando murió Bela, reinó en su lugar Jobab hijo de Zera, que provenía de Bosra.'),
('nvi', 'Génesis 36:34', 'Génesis', 36, 34, 'Cuando murió Jobab, reinó en su lugar Jusán, que venía de la región de Temán.'),
('nvi', 'Génesis 36:35', 'Génesis', 36, 35, 'Cuando murió Jusán, reinó en su lugar Hadad hijo de Bedad. Éste derrotó a Madián en el campo de Moab. El nombre de su ciudad era Avit.'),
('nvi', 'Génesis 36:36', 'Génesis', 36, 36, 'Cuando murió Hadad, reinó en su lugar Samla, que era del pueblo de Masreca.'),
('nvi', 'Génesis 36:37', 'Génesis', 36, 37, 'Cuando murió Samla, reinó en su lugar Saúl de Rejobot del Río.'),
('nvi', 'Génesis 36:38', 'Génesis', 36, 38, 'Cuando murió Saúl, reinó en su lugar Baal Janán hijo de Acbor.'),
('nvi', 'Génesis 36:39', 'Génesis', 36, 39, 'Cuando murió Baal Janán hijo de Acbor, reinó en su lugar Hadad. El nombre de su ciudad era Pau. Su esposa se llamaba Mehitabel, y era hija de Matred y nieta de Mezab.'),
('nvi', 'Génesis 36:40', 'Génesis', 36, 40, 'Éstos son los nombres de los jefes que descendieron de Esaú, cada uno según su clan y región: Timná, Alvá, Jetet,'),
('nvi', 'Génesis 36:41', 'Génesis', 36, 41, 'Aholibama, Elá, Pinón,'),
('nvi', 'Génesis 36:42', 'Génesis', 36, 42, 'Quenaz, Temán, Mibzar,'),
('nvi', 'Génesis 36:43', 'Génesis', 36, 43, 'Magdiel e Iram. Éstos fueron los jefes de Edom, según los lugares que habitaron. Éste fue Esaú, padre de los edomitas.'),
('nvi', 'Génesis 37:1', 'Génesis', 37, 1, 'Jacob se estableció en la tierra de Canaán, donde su padre había residido como extranjero.'),
('nvi', 'Génesis 37:2', 'Génesis', 37, 2, 'Ésta es la historia de Jacob y su familia. Cuando José tenía diecisiete años, apacentaba el rebaño junto a sus hermanos, los hijos de Bilhá y de Zilpá, que eran concubinas de su padre. El joven José solía informar a su padre de la mala fama que tenían estos hermanos suyos.'),
('nvi', 'Génesis 37:3', 'Génesis', 37, 3, 'Israel amaba a José más que a sus otros hijos, porque lo había tenido en su vejez. Por eso mandó que le confeccionaran una túnica especial de mangas largas.'),
('nvi', 'Génesis 37:4', 'Génesis', 37, 4, 'Viendo sus hermanos que su padre amaba más a José que a ellos, comenzaron a odiarlo y ni siquiera lo saludaban.'),
('nvi', 'Génesis 37:5', 'Génesis', 37, 5, 'Cierto día José tuvo un sueño y, cuando se lo contó a sus hermanos, éstos le tuvieron más odio todavía,'),
('nvi', 'Génesis 37:6', 'Génesis', 37, 6, 'pues les dijo: —Préstenme atención, que les voy a contar lo que he soñado.'),
('nvi', 'Génesis 37:7', 'Génesis', 37, 7, 'Resulta que estábamos todos nosotros en el campo atando gavillas. De pronto, mi gavilla se levantó y quedó erguida, mientras que las de ustedes se juntaron alrededor de la mía y le hicieron reverencias.'),
('nvi', 'Génesis 37:8', 'Génesis', 37, 8, 'Sus hermanos replicaron: —¿De veras crees que vas a reinar sobre nosotros, y que nos vas a someter? Y lo odiaron aún más por los sueños que él les contaba.'),
('nvi', 'Génesis 37:9', 'Génesis', 37, 9, 'Después José tuvo otro sueño, y se lo contó a sus hermanos. Les dijo: —Tuve otro sueño, en el que veía que el sol, la luna y once estrellas me hacían reverencias.'),
('nvi', 'Génesis 37:10', 'Génesis', 37, 10, 'Cuando se lo contó a su padre y a sus hermanos, su padre lo reprendió: —¿Qué quieres decirnos con este sueño que has tenido? —le preguntó—. ¿Acaso tu madre, tus hermanos y yo vendremos a hacerte reverencias?'),
('nvi', 'Génesis 37:11', 'Génesis', 37, 11, 'Sus hermanos le tenían envidia, pero su padre meditaba en todo esto.'),
('nvi', 'Génesis 37:12', 'Génesis', 37, 12, 'En cierta ocasión, los hermanos de José se fueron a Siquén para apacentar las ovejas de su padre.'),
('nvi', 'Génesis 37:13', 'Génesis', 37, 13, 'Israel le dijo a José: —Tus hermanos están en Siquén apacentando las ovejas. Quiero que vayas a verlos. —Está bien —contestó José.'),
('nvi', 'Génesis 37:14', 'Génesis', 37, 14, 'Israel continuó: —Vete a ver cómo están tus hermanos y el rebaño, y tráeme noticias frescas. Y lo envió desde el valle de Hebrón. Cuando José llegó a Siquén,'),
('nvi', 'Génesis 37:15', 'Génesis', 37, 15, 'un hombre lo encontró perdido en el campo y le preguntó: —¿Qué andas buscando?'),
('nvi', 'Génesis 37:16', 'Génesis', 37, 16, '—Ando buscando a mis hermanos —contestó José—. ¿Podría usted indicarme dónde están apacentando el rebaño?'),
('nvi', 'Génesis 37:17', 'Génesis', 37, 17, '—Ya se han marchado de aquí —le informó el hombre—. Les oí decir que se dirigían a Dotán. José siguió buscando a sus hermanos, y los encontró cerca de Dotán.'),
('nvi', 'Génesis 37:18', 'Génesis', 37, 18, 'Como ellos alcanzaron a verlo desde lejos, antes de que se acercara tramaron un plan para matarlo.'),
('nvi', 'Génesis 37:19', 'Génesis', 37, 19, 'Se dijeron unos a otros: —Ahí viene ese soñador.'),
('nvi', 'Génesis 37:20', 'Génesis', 37, 20, 'Ahora sí que le llegó la hora. Vamos a matarlo y echarlo en una de estas cisternas, y diremos que lo devoró un animal salvaje. ¡Y a ver en qué terminan sus sueños!'),
('nvi', 'Génesis 37:21', 'Génesis', 37, 21, 'Cuando Rubén escuchó esto, intentó librarlo de las garras de sus hermanos, así que les propuso: —No lo matemos.'),
('nvi', 'Génesis 37:22', 'Génesis', 37, 22, 'No derramen sangre. Arrójenlo en esta cisterna en el desierto, pero no le pongan la mano encima. Rubén dijo esto porque su intención era rescatar a José y devolverlo a su padre.'),
('nvi', 'Génesis 37:23', 'Génesis', 37, 23, 'Cuando José llegó adonde estaban sus hermanos, le arrancaron la túnica especial de mangas largas,'),
('nvi', 'Génesis 37:24', 'Génesis', 37, 24, 'lo agarraron y lo echaron en una cisterna que estaba vacía y seca.'),
('nvi', 'Génesis 37:25', 'Génesis', 37, 25, 'Luego se sentaron a comer. En eso, al levantar la vista, divisaron una caravana de ismaelitas que venía de Galaad. Sus camellos estaban cargados de perfumes, bálsamo y mirra, que llevaban a Egipto.'),
('nvi', 'Génesis 37:26', 'Génesis', 37, 26, 'Entonces Judá les propuso a sus hermanos: —¿Qué ganamos con matar a nuestro hermano y ocultar su muerte?'),
('nvi', 'Génesis 37:27', 'Génesis', 37, 27, 'En vez de eliminarlo, vendámoslo a los ismaelitas; al fin de cuentas, es nuestro propio hermano. Sus hermanos estuvieron de acuerdo con él,'),
('nvi', 'Génesis 37:28', 'Génesis', 37, 28, 'así que cuando los mercaderes madianitas se acercaron, sacaron a José de la cisterna y se lo vendieron a los ismaelitas por veinte monedas de plata. Fue así como se llevaron a José a Egipto.'),
('nvi', 'Génesis 37:29', 'Génesis', 37, 29, 'Cuando Rubén volvió a la cisterna y José ya no estaba allí, se rasgó las vestiduras en señal de duelo.'),
('nvi', 'Génesis 37:30', 'Génesis', 37, 30, 'Regresó entonces adonde estaban sus hermanos, y les reclamó: —¡Ya no está ese mocoso! Y ahora, ¿qué hago?'),
('nvi', 'Génesis 37:31', 'Génesis', 37, 31, 'En seguida los hermanos tomaron la túnica especial de José, degollaron un cabrito, y con la sangre empaparon la túnica.'),
('nvi', 'Génesis 37:32', 'Génesis', 37, 32, 'Luego la mandaron a su padre con el siguiente mensaje: «Encontramos esto. Fíjate bien si es o no la túnica de tu hijo.»'),
('nvi', 'Génesis 37:33', 'Génesis', 37, 33, 'En cuanto Jacob la reconoció, exclamó: «¡Sí, es la túnica de mi hijo! ¡Seguro que un animal salvaje se lo devoró y lo hizo pedazos!»'),
('nvi', 'Génesis 37:34', 'Génesis', 37, 34, 'Y Jacob se rasgó las vestiduras y se vistió de luto, y por mucho tiempo hizo duelo por su hijo.'),
('nvi', 'Génesis 37:35', 'Génesis', 37, 35, 'Todos sus hijos y sus hijas intentaban calmarlo, pero él no se dejaba consolar, sino que decía: «No. Guardaré luto hasta que descienda al sepulcro para reunirme con mi hijo.» Así Jacob siguió llorando la muerte de José.'),
('nvi', 'Génesis 37:36', 'Génesis', 37, 36, 'En Egipto, los madianitas lo vendieron a un tal Potifar, funcionario del faraón y capitán de la guardia.'),
('nvi', 'Génesis 38:1', 'Génesis', 38, 1, 'Por esos días, Judá se apartó de sus hermanos y se fue a vivir a la casa de un hombre llamado Hirá, residente del pueblo de Adulán.'),
('nvi', 'Génesis 38:2', 'Génesis', 38, 2, 'Allí Judá conoció a una mujer, hija de un cananeo llamado Súa, y se casó con ella. Luego de tener relaciones con él,'),
('nvi', 'Génesis 38:3', 'Génesis', 38, 3, 'ella concibió y dio a luz un hijo, al que llamó Er.'),
('nvi', 'Génesis 38:4', 'Génesis', 38, 4, 'Tiempo después volvió a concebir, y dio a luz otro hijo, al que llamó Onán.'),
('nvi', 'Génesis 38:5', 'Génesis', 38, 5, 'Pasado el tiempo tuvo otro hijo, al que llamó Selá, el cual nació en Quezib.'),
('nvi', 'Génesis 38:6', 'Génesis', 38, 6, 'Judá consiguió para Er, su hijo mayor, una esposa que se llamaba Tamar.'),
('nvi', 'Génesis 38:7', 'Génesis', 38, 7, 'Pero al SEÑOR no le agradó la conducta del primogénito de Judá, y le quitó la vida.'),
('nvi', 'Génesis 38:8', 'Génesis', 38, 8, 'Entonces Judá le dijo a Onán: «Cásate con la viuda de tu hermano y cumple con tu deber de cuñado; así le darás descendencia a tu hermano.»'),
('nvi', 'Génesis 38:9', 'Génesis', 38, 9, 'Pero Onán sabía que los hijos que nacieran no serían reconocidos como suyos. Por eso, cada vez que tenía relaciones con ella, derramaba el semen en el suelo, y así evitaba que su hermano tuviera descendencia.'),
('nvi', 'Génesis 38:10', 'Génesis', 38, 10, 'Esta conducta ofendió mucho al SEÑOR, así que también a él le quitó la vida.'),
('nvi', 'Génesis 38:11', 'Génesis', 38, 11, 'Entonces Judá le dijo a su nuera Tamar: «Quédate como viuda en la casa de tu padre, hasta que mi hijo Selá tenga edad de casarse.» Pero en realidad Judá pensaba que Selá podría morirse, lo mismo que sus hermanos. Así que Tamar se fue a vivir a la casa de su padre.'),
('nvi', 'Génesis 38:12', 'Génesis', 38, 12, 'Después de mucho tiempo, murió la esposa de Judá, la hija de Súa. Al concluir el tiempo de duelo, Judá fue al pueblo de Timnat para esquilar sus ovejas. Lo acompañó su amigo Hirá, el adulanita.'),
('nvi', 'Génesis 38:13', 'Génesis', 38, 13, 'Cuando Tamar se enteró de que su suegro se dirigía hacia Timnat para esquilar sus ovejas,'),
('nvi', 'Génesis 38:14', 'Génesis', 38, 14, 'se quitó el vestido de viuda, se cubrió con un velo para que nadie la reconociera, y se sentó a la entrada del pueblo de Enayin, que está en el camino a Timnat. Esto lo hizo porque se dio cuenta de que Selá ya tenía edad de casarse y aún no se lo daban a ella por esposo.'),
('nvi', 'Génesis 38:15', 'Génesis', 38, 15, 'Cuando Judá la vio con el rostro cubierto, la tomó por una prostituta.'),
('nvi', 'Génesis 38:16', 'Génesis', 38, 16, 'No sabiendo que era su nuera, se acercó a la orilla del camino y le dijo: —Deja que me acueste contigo. —¿Qué me das si te digo que sí? —le preguntó ella.'),
('nvi', 'Génesis 38:17', 'Génesis', 38, 17, '—Te mandaré uno de los cabritos de mi rebaño —respondió Judá. —Está bien —respondió ella—, pero déjame algo en garantía hasta que me lo mandes.'),
('nvi', 'Génesis 38:18', 'Génesis', 38, 18, '—¿Qué prenda quieres que te deje? —preguntó Judá. —Dame tu sello y su cordón, y el bastón que llevas en la mano —respondió Tamar. Judá se los entregó, se acostó con ella y la dejó embarazada.'),
('nvi', 'Génesis 38:19', 'Génesis', 38, 19, 'Cuando ella se levantó, se fue inmediatamente de allí, se quitó el velo y volvió a ponerse la ropa de viuda.'),
('nvi', 'Génesis 38:20', 'Génesis', 38, 20, 'Más tarde, Judá envió el cabrito por medio de su amigo adulanita, para recuperar las prendas que había dejado con la mujer; pero su amigo no dio con ella.'),
('nvi', 'Génesis 38:21', 'Génesis', 38, 21, 'Entonces le preguntó a la gente del lugar: —¿Dónde está la prostituta de Enayin, la que se sentaba junto al camino? —Aquí nunca ha habido una prostituta así —le contestaron.'),
('nvi', 'Génesis 38:22', 'Génesis', 38, 22, 'El amigo regresó adonde estaba Judá y le dijo: —No la pude encontrar. Además, la gente del lugar me informó que allí nunca había estado una prostituta como ésa.'),
('nvi', 'Génesis 38:23', 'Génesis', 38, 23, '—Que se quede con las prendas —replicó Judá—; no es cuestión de que hagamos el ridículo. Pero que quede claro: yo le envié el cabrito, y tú no la encontraste.'),
('nvi', 'Génesis 38:24', 'Génesis', 38, 24, 'Como tres meses después, le informaron a Judá lo siguiente: —Tu nuera Tamar se ha prostituido, y como resultado de sus andanzas ha quedado embarazada. —¡Sáquenla y quémenla! —exclamó Judá.'),
('nvi', 'Génesis 38:25', 'Génesis', 38, 25, 'Pero cuando la estaban sacando, ella mandó este mensaje a su suegro: «El dueño de estas prendas fue quien me embarazó. A ver si reconoce usted de quién son este sello, el cordón del sello, y este bastón.»'),
('nvi', 'Génesis 38:26', 'Génesis', 38, 26, 'Judá los reconoció y declaró: «Su conducta es más justa que la mía, pues yo no la di por esposa a mi hijo Selá.» Y no volvió a acostarse con ella.'),
('nvi', 'Génesis 38:27', 'Génesis', 38, 27, 'Cuando llegó el tiempo de que Tamar diera a luz, resultó que tenía mellizos en su seno.'),
('nvi', 'Génesis 38:28', 'Génesis', 38, 28, 'En el momento de nacer, uno de los mellizos sacó la mano; la partera le ató un hilo rojo en la mano, y dijo: «Éste salió primero.»'),
('nvi', 'Génesis 38:29', 'Génesis', 38, 29, 'Pero en ese momento el niño metió la mano, y salió primero el otro. Entonces la partera dijo: «¡Cómo te abriste paso!» Por eso al niño lo llamaron Fares.'),
('nvi', 'Génesis 38:30', 'Génesis', 38, 30, 'Luego salió su hermano, con el hilo rojo atado en la mano, y lo llamaron Zera.'),
('nvi', 'Génesis 39:1', 'Génesis', 39, 1, 'Cuando José fue llevado a Egipto, los ismaelitas que lo habían trasladado allá lo vendieron a Potifar, un egipcio que era funcionario del faraón y capitán de su guardia.'),
('nvi', 'Génesis 39:2', 'Génesis', 39, 2, 'Ahora bien, el SEÑOR estaba con José y las cosas le salían muy bien. Mientras José vivía en la casa de su patrón egipcio,'),
('nvi', 'Génesis 39:3', 'Génesis', 39, 3, 'éste se dio cuenta de que el SEÑOR estaba con José y lo hacía prosperar en todo.'),
('nvi', 'Génesis 39:4', 'Génesis', 39, 4, 'José se ganó la confianza de Potifar, y éste lo nombró mayordomo de toda su casa y le confió la administración de todos sus bienes.'),
('nvi', 'Génesis 39:5', 'Génesis', 39, 5, 'Por causa de José, el SEÑOR bendijo la casa del egipcio Potifar a partir del momento en que puso a José a cargo de su casa y de todos sus bienes. La bendición del SEÑOR se extendió sobre todo lo que tenía el egipcio, tanto en la casa como en el campo.'),
('nvi', 'Génesis 39:6', 'Génesis', 39, 6, 'Por esto Potifar dejó todo a cargo de José, y tan sólo se preocupaba por lo que tenía que comer. José tenía muy buen físico y era muy atractivo.'),
('nvi', 'Génesis 39:7', 'Génesis', 39, 7, 'Después de algún tiempo, la esposa de su patrón empezó a echarle el ojo y le propuso: —Acuéstate conmigo.'),
('nvi', 'Génesis 39:8', 'Génesis', 39, 8, 'Pero José no quiso saber nada, sino que le contestó: —Mire, señora: mi patrón ya no tiene que preocuparse de nada en la casa, porque todo me lo ha confiado a mí.'),
('nvi', 'Génesis 39:9', 'Génesis', 39, 9, 'En esta casa no hay nadie más importante que yo. Mi patrón no me ha negado nada, excepto meterme con usted, que es su esposa. ¿Cómo podría yo cometer tal maldad y pecar así contra Dios?'),
('nvi', 'Génesis 39:10', 'Génesis', 39, 10, 'Y por más que ella lo acosaba día tras día para que se acostara con ella y le hiciera compañía, José se mantuvo firme en su rechazo.'),
('nvi', 'Génesis 39:11', 'Génesis', 39, 11, 'Un día, en un momento en que todo el personal de servicio se encontraba ausente, José entró en la casa para cumplir con sus responsabilidades.'),
('nvi', 'Génesis 39:12', 'Génesis', 39, 12, 'Entonces la mujer de Potifar lo agarró del manto y le rogó: «¡Acuéstate conmigo!» Pero José, dejando el manto en manos de ella, salió corriendo de la casa.'),
('nvi', 'Génesis 39:13', 'Génesis', 39, 13, 'Al ver ella que él había dejado el manto en sus manos y había salido corriendo,'),
('nvi', 'Génesis 39:14', 'Génesis', 39, 14, 'llamó a los siervos de la casa y les dijo: «¡Miren!, el hebreo que nos trajo mi esposo sólo ha venido a burlarse de nosotros. Entró a la casa con la intención de acostarse conmigo, pero yo grité con todas mis fuerzas.'),
('nvi', 'Génesis 39:15', 'Génesis', 39, 15, 'En cuanto me oyó gritar, salió corriendo y dejó su manto a mi lado.»'),
('nvi', 'Génesis 39:16', 'Génesis', 39, 16, 'La mujer guardó el manto de José hasta que su marido volvió a su casa.'),
('nvi', 'Génesis 39:17', 'Génesis', 39, 17, 'Entonces le contó la misma historia: «El esclavo hebreo que nos trajiste quiso aprovecharse de mí.'),
('nvi', 'Génesis 39:18', 'Génesis', 39, 18, 'Pero en cuanto grité con todas mis fuerzas, salió corriendo y dejó su manto a mi lado.»'),
('nvi', 'Génesis 39:19', 'Génesis', 39, 19, 'Cuando el patrón de José escuchó de labios de su mujer cómo la había tratado el esclavo, se enfureció'),
('nvi', 'Génesis 39:20', 'Génesis', 39, 20, 'y mandó que echaran a José en la cárcel donde estaban los presos del rey. Pero aun en la cárcel'),
('nvi', 'Génesis 39:21', 'Génesis', 39, 21, 'el SEÑOR estaba con él y no dejó de mostrarle su amor. Hizo que se ganara la confianza del guardia de la cárcel,'),
('nvi', 'Génesis 39:22', 'Génesis', 39, 22, 'el cual puso a José a cargo de todos los prisioneros y de todo lo que allí se hacía.'),
('nvi', 'Génesis 39:23', 'Génesis', 39, 23, 'Como el SEÑOR estaba con José y hacía prosperar todo lo que él hacía, el guardia de la cárcel no se preocupaba de nada de lo que dejaba en sus manos.'),
('nvi', 'Génesis 40:1', 'Génesis', 40, 1, 'Tiempo después, el copero y el panadero del rey de Egipto ofendieron a su señor.'),
('nvi', 'Génesis 40:2', 'Génesis', 40, 2, 'El faraón se enojó contra estos dos funcionarios suyos, es decir, contra el jefe de los coperos y el jefe de los panaderos,'),
('nvi', 'Génesis 40:3', 'Génesis', 40, 3, 'así que los mandó presos a la casa del capitán de la guardia, que era la misma cárcel donde estaba preso José.'),
('nvi', 'Génesis 40:4', 'Génesis', 40, 4, 'Allí el capitán de la guardia le encargó a José que atendiera a estos funcionarios. Después de haber estado algún tiempo en la cárcel,'),
('nvi', 'Génesis 40:5', 'Génesis', 40, 5, 'una noche los dos funcionarios, es decir, el copero y el panadero, tuvieron cada uno un sueño, cada sueño con su propio significado.'),
('nvi', 'Génesis 40:6', 'Génesis', 40, 6, 'A la mañana siguiente, cuando José fue a verlos, los encontró muy preocupados,'),
('nvi', 'Génesis 40:7', 'Génesis', 40, 7, 'y por eso les preguntó: —¿Por qué andan hoy tan cabizbajos?'),
('nvi', 'Génesis 40:8', 'Génesis', 40, 8, '—Los dos tuvimos un sueño —respondieron—, y no hay nadie que nos lo interprete. —¿Acaso no es Dios quien da la interpretación? —preguntó José—. ¿Por qué no me cuentan lo que soñaron?'),
('nvi', 'Génesis 40:9', 'Génesis', 40, 9, 'Entonces el jefe de los coperos le contó a José el sueño que había tenido: —Soñé que frente a mí había una vid,'),
('nvi', 'Génesis 40:10', 'Génesis', 40, 10, 'la cual tenía tres ramas. En cuanto la vid echó brotes, floreció; y maduraron las uvas en los racimos.'),
('nvi', 'Génesis 40:11', 'Génesis', 40, 11, 'Yo tenía la copa del faraón en la mano. Tomé las uvas, las exprimí en la copa, y luego puse la copa en manos del faraón.'),
('nvi', 'Génesis 40:12', 'Génesis', 40, 12, 'Entonces José le dijo: —Ésta es la interpretación de su sueño: Las tres ramas son tres días.'),
('nvi', 'Génesis 40:13', 'Génesis', 40, 13, 'Dentro de los próximos tres días el faraón lo indultará a usted y volverá a colocarlo en su cargo. Usted volverá a poner la copa del faraón en su mano, tal como lo hacía antes, cuando era su copero.'),
('nvi', 'Génesis 40:14', 'Génesis', 40, 14, 'Yo le ruego que no se olvide de mí. Por favor, cuando todo se haya arreglado, háblele usted de mí al faraón para que me saque de esta cárcel.'),
('nvi', 'Génesis 40:15', 'Génesis', 40, 15, 'A mí me trajeron por la fuerza, de la tierra de los hebreos. ¡Yo no hice nada aquí para que me echaran en la cárcel!'),
('nvi', 'Génesis 40:16', 'Génesis', 40, 16, 'Al ver que la interpretación había sido favorable, el jefe de los panaderos le dijo a José: —Yo también tuve un sueño. En ese sueño, llevaba yo tres canastas de pan sobre la cabeza.'),
('nvi', 'Génesis 40:17', 'Génesis', 40, 17, 'En la canasta de arriba había un gran surtido de repostería para el faraón, pero las aves venían a comer de la canasta que llevaba sobre la cabeza.'),
('nvi', 'Génesis 40:18', 'Génesis', 40, 18, 'José le respondió: —Ésta es la interpretación de su sueño: Las tres canastas son tres días.'),
('nvi', 'Génesis 40:19', 'Génesis', 40, 19, 'Dentro de los próximos tres días, el faraón mandará que a usted lo decapiten y lo cuelguen de un árbol, y las aves devorarán su cuerpo.'),
('nvi', 'Génesis 40:20', 'Génesis', 40, 20, 'En efecto, tres días después el faraón celebró su cumpleaños y ofreció una gran fiesta para todos sus funcionarios. En presencia de éstos, mandó sacar de la cárcel al jefe de los coperos y al jefe de los panaderos.'),
('nvi', 'Génesis 40:21', 'Génesis', 40, 21, 'Al jefe de los coperos lo restituyó en su cargo para que, una vez más, pusiera la copa en manos del faraón.'),
('nvi', 'Génesis 40:22', 'Génesis', 40, 22, 'Pero, tal como lo había predicho José, al jefe de los panaderos mandó que lo ahorcaran.'),
('nvi', 'Génesis 40:23', 'Génesis', 40, 23, 'Sin embargo, el jefe de los coperos no se acordó de José, sino que se olvidó de él por completo.'),
('nvi', 'Génesis 41:1', 'Génesis', 41, 1, 'Dos años más tarde, el faraón tuvo un sueño: Estaba de pie junto al río Nilo'),
('nvi', 'Génesis 41:2', 'Génesis', 41, 2, 'cuando, de pronto, del río salieron siete vacas hermosas y gordas que se pusieron a pastar entre los juncos.'),
('nvi', 'Génesis 41:3', 'Génesis', 41, 3, 'Detrás de ellas salieron otras siete vacas, feas y flacas, que se pararon a orillas del Nilo, junto a las primeras.'),
('nvi', 'Génesis 41:4', 'Génesis', 41, 4, '¡Y las vacas feas y flacas se comieron a las vacas hermosas y gordas! En ese momento el faraón se despertó.'),
('nvi', 'Génesis 41:5', 'Génesis', 41, 5, 'Pero volvió a dormirse, y tuvo otro sueño: Siete espigas de trigo, grandes y hermosas, crecían de un solo tallo.'),
('nvi', 'Génesis 41:6', 'Génesis', 41, 6, 'Tras ellas brotaron otras siete espigas, delgadas y quemadas por el viento solano.'),
('nvi', 'Génesis 41:7', 'Génesis', 41, 7, '¡Y las siete espigas delgadas se comieron a las espigas grandes y hermosas! En eso el faraón se despertó y se dio cuenta de que sólo era un sueño.'),
('nvi', 'Génesis 41:8', 'Génesis', 41, 8, 'Sin embargo, a la mañana siguiente se levantó muy preocupado, mandó llamar a todos los magos y sabios de Egipto, y les contó los dos sueños. Pero nadie se los pudo interpretar.'),
('nvi', 'Génesis 41:9', 'Génesis', 41, 9, 'Entonces el jefe de los coperos le dijo al faraón: «Ahora me doy cuenta del grave error que he cometido.'),
('nvi', 'Génesis 41:10', 'Génesis', 41, 10, 'Cuando el faraón se enojó con sus servidores, es decir, conmigo y con el jefe de los panaderos, nos mandó a la cárcel, bajo la custodia del capitán de la guardia.'),
('nvi', 'Génesis 41:11', 'Génesis', 41, 11, 'Una misma noche, los dos tuvimos un sueño, cada sueño con su propio significado.'),
('nvi', 'Génesis 41:12', 'Génesis', 41, 12, 'Allí, con nosotros, había un joven hebreo, esclavo del capitán de la guardia. Le contamos nuestros sueños, y a cada uno nos interpretó el sueño.'),
('nvi', 'Génesis 41:13', 'Génesis', 41, 13, '¡Y todo sucedió tal como él lo había interpretado! A mí me restituyeron mi cargo, y al jefe de los panaderos lo ahorcaron.»'),
('nvi', 'Génesis 41:14', 'Génesis', 41, 14, 'El faraón mandó llamar a José, y en seguida lo sacaron de la cárcel. Luego de afeitarse y cambiarse de ropa, José se presentó ante el faraón,'),
('nvi', 'Génesis 41:15', 'Génesis', 41, 15, 'quien le dijo: —Tuve un sueño que nadie ha podido interpretar. Pero me he enterado de que, cuando tú oyes un sueño, eres capaz de interpretarlo.'),
('nvi', 'Génesis 41:16', 'Génesis', 41, 16, '—No soy yo quien puede hacerlo —respondió José—, sino que es Dios quien le dará al faraón una respuesta favorable.'),
('nvi', 'Génesis 41:17', 'Génesis', 41, 17, 'El faraón le contó a José lo siguiente: —En mi sueño, estaba yo de pie a orillas del río Nilo.'),
('nvi', 'Génesis 41:18', 'Génesis', 41, 18, 'De pronto, salieron del río siete vacas gordas y hermosas, y se pusieron a pastar entre los juncos.'),
('nvi', 'Génesis 41:19', 'Génesis', 41, 19, 'Detrás de ellas salieron otras siete vacas, feas y flacas. ¡Jamás se habían visto vacas tan raquíticas en toda la tierra de Egipto!'),
('nvi', 'Génesis 41:20', 'Génesis', 41, 20, 'Y las siete vacas feas y flacas se comieron a las siete vacas gordas.'),
('nvi', 'Génesis 41:21', 'Génesis', 41, 21, 'Pero, después de habérselas comido, no se les notaba en lo más mínimo, porque seguían tan feas como antes. Entonces me desperté.'),
('nvi', 'Génesis 41:22', 'Génesis', 41, 22, '»Después tuve otro sueño: Siete espigas de trigo, grandes y hermosas, crecían de un solo tallo.'),
('nvi', 'Génesis 41:23', 'Génesis', 41, 23, 'Tras ellas brotaron otras siete espigas marchitas, delgadas y quemadas por el viento solano.'),
('nvi', 'Génesis 41:24', 'Génesis', 41, 24, 'Las siete espigas delgadas se comieron a las espigas grandes y hermosas. Todo esto se lo conté a los magos, pero ninguno de ellos me lo pudo interpretar.'),
('nvi', 'Génesis 41:25', 'Génesis', 41, 25, 'José le explicó al faraón: —En realidad, los dos sueños del faraón son uno solo. Dios le ha anunciado lo que está por hacer.'),
('nvi', 'Génesis 41:26', 'Génesis', 41, 26, 'Las siete vacas hermosas y las siete espigas hermosas son siete años. Se trata del mismo sueño.'),
('nvi', 'Génesis 41:27', 'Génesis', 41, 27, 'Y las siete vacas flacas y feas, que salieron detrás de las otras, y las siete espigas delgadas y quemadas por el viento solano, son también siete años. Pero éstos serán siete años de hambre.'),
('nvi', 'Génesis 41:28', 'Génesis', 41, 28, '»Tal como le he dicho al faraón, Dios le está mostrando lo que está por hacer.'),
('nvi', 'Génesis 41:29', 'Génesis', 41, 29, 'Están por venir siete años de mucha abundancia en todo Egipto,'),
('nvi', 'Génesis 41:30', 'Génesis', 41, 30, 'a los que les seguirán siete años de hambre, que harán olvidar toda la abundancia que antes hubo. ¡El hambre acabará con Egipto!'),
('nvi', 'Génesis 41:31', 'Génesis', 41, 31, 'Tan terrible será el hambre, que nadie se acordará de la abundancia que antes hubo en el país.'),
('nvi', 'Génesis 41:32', 'Génesis', 41, 32, 'El faraón tuvo el mismo sueño dos veces porque Dios ha resuelto firmemente hacer esto, y lo llevará a cabo muy pronto.'),
('nvi', 'Génesis 41:33', 'Génesis', 41, 33, '»Por todo esto, el faraón debería buscar un hombre competente y sabio, para que se haga cargo de la tierra de Egipto.'),
('nvi', 'Génesis 41:34', 'Génesis', 41, 34, 'Además, el faraón debería nombrar inspectores en todo Egipto, para que durante los siete años de abundancia recauden la quinta parte de la cosecha en todo el país.'),
('nvi', 'Génesis 41:35', 'Génesis', 41, 35, 'Bajo el control del faraón, esos inspectores deberán juntar el grano de los años buenos que vienen y almacenarlo en las ciudades, para que haya una reserva de alimento.'),
('nvi', 'Génesis 41:36', 'Génesis', 41, 36, 'Este alimento almacenado le servirá a Egipto para los siete años de hambre que sufrirá, y así la gente del país no morirá de hambre.'),
('nvi', 'Génesis 41:37', 'Génesis', 41, 37, 'Al faraón y a sus servidores les pareció bueno el plan.'),
('nvi', 'Génesis 41:38', 'Génesis', 41, 38, 'Entonces el faraón les preguntó a sus servidores: —¿Podremos encontrar una persona así, en quien repose el espíritu de Dios?'),
('nvi', 'Génesis 41:39', 'Génesis', 41, 39, 'Luego le dijo a José: —Puesto que Dios te ha revelado todo esto, no hay nadie más competente y sabio que tú.'),
('nvi', 'Génesis 41:40', 'Génesis', 41, 40, 'Quedarás a cargo de mi palacio, y todo mi pueblo cumplirá tus órdenes. Sólo yo tendré más autoridad que tú, porque soy el rey.'),
('nvi', 'Génesis 41:41', 'Génesis', 41, 41, 'Así que el faraón le informó a José: —Mira, yo te pongo a cargo de todo el territorio de Egipto.'),
('nvi', 'Génesis 41:42', 'Génesis', 41, 42, 'De inmediato, el faraón se quitó el anillo oficial y se lo puso a José. Hizo que lo vistieran con ropas de lino fino, y que le pusieran un collar de oro en el cuello.'),
('nvi', 'Génesis 41:43', 'Génesis', 41, 43, 'Después lo invitó a subirse al carro reservado para el segundo en autoridad, y ordenó que gritaran: «¡Abran paso!» Fue así como el faraón puso a José al frente de todo el territorio de Egipto.'),
('nvi', 'Génesis 41:44', 'Génesis', 41, 44, 'Entonces el faraón le dijo: —Yo soy el faraón, pero nadie en todo Egipto podrá hacer nada sin tu permiso.'),
('nvi', 'Génesis 41:45', 'Génesis', 41, 45, 'Y le cambió el nombre a José, y lo llamó Zafenat Panea; además, le dio por esposa a Asenat, hija de Potifera, sacerdote de la ciudad de On. De este modo quedó José a cargo de Egipto.'),
('nvi', 'Génesis 41:46', 'Génesis', 41, 46, 'Tenía treinta años cuando comenzó a trabajar al servicio del faraón, rey de Egipto. Tan pronto como se retiró José de la presencia del faraón, se dedicó a recorrer todo el territorio de Egipto.'),
('nvi', 'Génesis 41:47', 'Génesis', 41, 47, 'Durante los siete años de abundancia la tierra produjo grandes cosechas,'),
('nvi', 'Génesis 41:48', 'Génesis', 41, 48, 'así que José fue recogiendo todo el alimento que se produjo en Egipto durante esos siete años, y lo almacenó en las ciudades.'),
('nvi', 'Génesis 41:49', 'Génesis', 41, 49, 'Juntó alimento como quien junta arena del mar, y fue tanto lo que recogió que dejó de contabilizarlo. ¡Ya no había forma de mantener el control!'),
('nvi', 'Génesis 41:50', 'Génesis', 41, 50, 'Antes de comenzar el primer año de hambre, José tuvo dos hijos con su esposa Asenat, la hija de Potifera, sacerdote de On.'),
('nvi', 'Génesis 41:51', 'Génesis', 41, 51, 'Al primero lo llamó Manasés, porque dijo: «Dios ha hecho que me olvide de todos mis problemas, y de mi casa paterna.»'),
('nvi', 'Génesis 41:52', 'Génesis', 41, 52, 'Al segundo lo llamó Efraín, porque dijo: «Dios me ha hecho fecundo en esta tierra donde he sufrido.»'),
('nvi', 'Génesis 41:53', 'Génesis', 41, 53, 'Los siete años de abundancia en Egipto llegaron a su fin'),
('nvi', 'Génesis 41:54', 'Génesis', 41, 54, 'y, tal como José lo había anunciado, comenzaron los siete años de hambre, la cual se extendió por todos los países. Pero a lo largo y a lo ancho del territorio de Egipto había alimento.'),
('nvi', 'Génesis 41:55', 'Génesis', 41, 55, 'Cuando también en Egipto comenzó a sentirse el hambre, el pueblo clamó al faraón pidiéndole comida. Entonces el faraón le dijo a todo el pueblo de Egipto: «Vayan a ver a José, y hagan lo que él les diga.»'),
('nvi', 'Génesis 41:56', 'Génesis', 41, 56, 'Cuando ya el hambre se había extendido por todo el territorio, y había arreciado, José abrió los graneros para vender alimento a los egipcios.'),
('nvi', 'Génesis 41:57', 'Génesis', 41, 57, 'Además, de todos los países llegaban a Egipto para comprarle alimento a José, porque el hambre cundía ya por todo el mundo.'),
('nvi', 'Génesis 42:1', 'Génesis', 42, 1, 'Cuando Jacob se enteró de que había alimento en Egipto, les dijo a sus hijos: «¿Qué hacen ahí parados, mirándose unos a otros?'),
('nvi', 'Génesis 42:2', 'Génesis', 42, 2, 'He sabido que hay alimento en Egipto. Vayan allá y compren comida para nosotros, para que no muramos, sino que podamos sobrevivir.»'),
('nvi', 'Génesis 42:3', 'Génesis', 42, 3, 'Diez de los hermanos de José fueron a Egipto a comprar alimento.'),
('nvi', 'Génesis 42:4', 'Génesis', 42, 4, 'Pero Jacob no dejó que Benjamín, el hermano de José, se fuera con ellos porque pensó que podría sucederle alguna desgracia.'),
('nvi', 'Génesis 42:5', 'Génesis', 42, 5, 'Fue así como los hijos de Israel fueron a comprar alimento, al igual que otros, porque el hambre se había apoderado de Canaán.'),
('nvi', 'Génesis 42:6', 'Génesis', 42, 6, 'José era el gobernador del país, y el que vendía trigo a todo el mundo. Cuando sus hermanos llegaron ante él, se postraron rostro en tierra.'),
('nvi', 'Génesis 42:7', 'Génesis', 42, 7, 'En cuanto José vio a sus hermanos, los reconoció; pero, fingiendo no conocerlos, les habló con rudeza: —¡Y ustedes!, ¿de dónde vienen? —Venimos de Canaán, para comprar alimento —contestaron.'),
('nvi', 'Génesis 42:8', 'Génesis', 42, 8, 'Aunque José los había reconocido, sus hermanos no lo reconocieron a él.'),
('nvi', 'Génesis 42:9', 'Génesis', 42, 9, 'En ese momento se acordó José de los sueños que había tenido acerca de ellos, y les dijo: —¡De seguro ustedes son espías, y han venido para investigar las zonas desprotegidas del país!'),
('nvi', 'Génesis 42:10', 'Génesis', 42, 10, '—¡No, señor! —respondieron—. Sus siervos hemos venido a comprar alimento.'),
('nvi', 'Génesis 42:11', 'Génesis', 42, 11, 'Todos nosotros somos hijos de un mismo padre, y además somos gente honrada. ¡Sus siervos no somos espías!'),
('nvi', 'Génesis 42:12', 'Génesis', 42, 12, '—¡No es verdad! —insistió José—. Ustedes han venido para investigar las zonas desprotegidas del país.'),
('nvi', 'Génesis 42:13', 'Génesis', 42, 13, 'Pero ellos volvieron a responder: —Nosotros, sus siervos, éramos doce hermanos, todos hijos de un mismo padre que vive en Canaán. El menor se ha quedado con nuestro padre, y el otro ya no vive.'),
('nvi', 'Génesis 42:14', 'Génesis', 42, 14, 'Pero José los increpó una vez más: —Es tal como les he dicho. ¡Ustedes son espías!'),
('nvi', 'Génesis 42:15', 'Génesis', 42, 15, 'Y con esto lo vamos a comprobar: Les juro por la vida del faraón, que de aquí no saldrán con vida a menos que traigan a su hermano menor.'),
('nvi', 'Génesis 42:16', 'Génesis', 42, 16, 'Manden a uno de ustedes a buscar a su hermano; los demás se quedarán en la cárcel. Así sabremos si es verdad lo que dicen. Y si no es así, ¡por la vida del faraón, ustedes son espías!'),
('nvi', 'Génesis 42:17', 'Génesis', 42, 17, 'José los encerró en la cárcel durante tres días.'),
('nvi', 'Génesis 42:18', 'Génesis', 42, 18, 'Al tercer día les dijo: —Yo soy un hombre temeroso de Dios. Hagan lo siguiente y salvarán su vida.'),
('nvi', 'Génesis 42:19', 'Génesis', 42, 19, 'Si en verdad son honrados, quédese uno de ustedes bajo custodia, y vayan los demás y lleven alimento para calmar el hambre de sus familias.'),
('nvi', 'Génesis 42:20', 'Génesis', 42, 20, 'Pero tráiganme a su hermano menor y pruébenme que dicen la verdad. Así no morirán. Ellos aceptaron la propuesta,'),
('nvi', 'Génesis 42:21', 'Génesis', 42, 21, 'pero se decían unos a otros: —Sin duda estamos sufriendo las consecuencias de lo que hicimos con nuestro hermano. Aunque vimos su angustia cuando nos suplicaba que le tuviéramos compasión, no le hicimos caso. Por eso ahora nos vemos en aprietos.'),
('nvi', 'Génesis 42:22', 'Génesis', 42, 22, 'Entonces habló Rubén: —Yo les advertí que no le hicieran daño al muchacho, pero no me hicieron caso. ¡Ahora tenemos que pagar el precio de su sangre!'),
('nvi', 'Génesis 42:23', 'Génesis', 42, 23, 'Como José les hablaba por medio de un intérprete, ellos no sabían que él entendía todo lo que estaban diciendo.'),
('nvi', 'Génesis 42:24', 'Génesis', 42, 24, 'José se apartó de ellos y se echó a llorar. Luego, cuando se controló y pudo hablarles, apartó a Simeón y ordenó que lo ataran en presencia de ellos.'),
('nvi', 'Génesis 42:25', 'Génesis', 42, 25, 'José dio también la orden de que llenaran de alimentos sus costales, que repusieran en cada una de sus bolsas el dinero que habían pagado, y que les dieran provisiones para el viaje. Y así se hizo.'),
('nvi', 'Génesis 42:26', 'Génesis', 42, 26, 'Entonces ellos cargaron el alimento sobre sus asnos y emprendieron el viaje de vuelta.'),
('nvi', 'Génesis 42:27', 'Génesis', 42, 27, 'Cuando llegaron al lugar donde acamparían esa noche, uno de ellos abrió su bolsa para darle de comer a su asno, ¡y allí en la abertura descubrió su dinero!'),
('nvi', 'Génesis 42:28', 'Génesis', 42, 28, 'Entonces les dijo a sus hermanos: —¡Me devolvieron el dinero! Miren, ¡aquí está, en mi bolsa! Los otros se asustaron mucho, y temblando se decían unos a otros: —¿Qué es lo que Dios nos ha hecho?'),
('nvi', 'Génesis 42:29', 'Génesis', 42, 29, 'Al llegar a Canaán, donde estaba su padre Jacob, le contaron todo lo que les había sucedido:'),
('nvi', 'Génesis 42:30', 'Génesis', 42, 30, '—El hombre que gobierna aquel país nos trató con rudeza, a tal grado que nos acusó de ser espías.'),
('nvi', 'Génesis 42:31', 'Génesis', 42, 31, 'Nosotros le dijimos: “Somos gente honrada. No somos espías.”'),
('nvi', 'Génesis 42:32', 'Génesis', 42, 32, 'Además, le dijimos: “Somos doce hermanos, hijos de un mismo padre. Uno ya no vive, y el menor se ha quedado con nuestro padre en Canaán.”'),
('nvi', 'Génesis 42:33', 'Génesis', 42, 33, '»Entonces el hombre que gobierna aquel país nos dijo: “Con esto voy a comprobar si en verdad son gente honrada. Dejen aquí conmigo a uno de sus hermanos, y vayan a llevar alimento para calmar el hambre de sus familias.'),
('nvi', 'Génesis 42:34', 'Génesis', 42, 34, 'Pero a la vuelta tráiganme a su hermano menor. Así comprobaré que no son espías, y que en verdad son gente honrada. Luego les entregaré de vuelta a su hermano, y podrán moverse con libertad por el país.”'),
('nvi', 'Génesis 42:35', 'Génesis', 42, 35, 'Cuando comenzaron a vaciar sus costales, se encontraron con que la bolsa de dinero de cada uno estaba allí. Esto hizo que ellos y su padre se llenaran de temor.'),
('nvi', 'Génesis 42:36', 'Génesis', 42, 36, 'Entonces Jacob, su padre, les dijo: —¡Ustedes me van a dejar sin hijos! José ya no está con nosotros, Simeón tampoco está aquí, ¡y ahora se quieren llevar a Benjamín! ¡Todo esto me perjudica!'),
('nvi', 'Génesis 42:37', 'Génesis', 42, 37, 'Pero Rubén le dijo a su padre: —Yo me hago cargo de Benjamín. Si no te lo devuelvo, podrás matar a mis dos hijos.'),
('nvi', 'Génesis 42:38', 'Génesis', 42, 38, '—¡Mi hijo no se irá con ustedes! —replicó Jacob—. Su hermano José ya está muerto, y ahora sólo él me queda. Si le llega a pasar una desgracia en el viaje que van a emprender, ustedes tendrán la culpa de que este pobre viejo se muera de tristeza.'),
('nvi', 'Génesis 43:1', 'Génesis', 43, 1, 'El hambre seguía aumentando en aquel país.'),
('nvi', 'Génesis 43:2', 'Génesis', 43, 2, 'Llegó el momento en que se les acabó el alimento que habían llevado de Egipto. Entonces su padre les dijo: —Vuelvan a Egipto y compren un poco más de alimento para nosotros.'),
('nvi', 'Génesis 43:3', 'Génesis', 43, 3, 'Pero Judá le recordó: —Aquel hombre nos advirtió claramente que no nos presentáramos ante él, a menos que lo hiciéramos con nuestro hermano menor.'),
('nvi', 'Génesis 43:4', 'Génesis', 43, 4, 'Si tú nos permites llevar a nuestro hermano menor, iremos a comprarte alimento.'),
('nvi', 'Génesis 43:5', 'Génesis', 43, 5, 'De lo contrario, no tiene objeto que vayamos. Aquel hombre fue muy claro en cuanto a no presentarnos ante él sin nuestro hermano menor.'),
('nvi', 'Génesis 43:6', 'Génesis', 43, 6, '—¿Por qué me han causado este mal? —inquirió Israel—. ¿Por qué le dijeron a ese hombre que tenían otro hermano?'),
('nvi', 'Génesis 43:7', 'Génesis', 43, 7, '—Porque aquel hombre nos preguntó específicamente acerca de nuestra familia —respondieron ellos—. “¿Vive todavía el padre de ustedes? —nos preguntó—. ¿Tienen algún otro hermano?”Lo único que hicimos fue responder a sus preguntas. ¿Cómo íbamos a saber que nos pediría llevar a nuestro hermano menor?'),
('nvi', 'Génesis 43:8', 'Génesis', 43, 8, 'Judá le dijo a su padre Israel: —Bajo mi responsabilidad, envía al muchacho y nos iremos ahora mismo, para que nosotros y nuestros hijos podamos seguir viviendo.'),
('nvi', 'Génesis 43:9', 'Génesis', 43, 9, 'Yo te respondo por su seguridad; a mí me pedirás cuentas. Si no te lo devuelvo sano y salvo, yo seré el culpable ante ti para toda la vida.'),
('nvi', 'Génesis 43:10', 'Génesis', 43, 10, 'Si no nos hubiéramos demorado tanto, ¡ya habríamos ido y vuelto dos veces!'),
('nvi', 'Génesis 43:11', 'Génesis', 43, 11, 'Entonces Israel, su padre, les dijo: —Ya que no hay más remedio, hagan lo siguiente: Echen en sus costales los mejores productos de esta región, y llévenselos de regalo a ese hombre: un poco de bálsamo, un poco de miel, perfumes, mirra, nueces, almendras.'),
('nvi', 'Génesis 43:12', 'Génesis', 43, 12, 'Lleven también el doble del dinero, pues deben devolver el que estaba en sus bolsas, ya que seguramente fue un error.'),
('nvi', 'Génesis 43:13', 'Génesis', 43, 13, 'Vayan con su hermano menor y preséntense ante ese hombre.'),
('nvi', 'Génesis 43:14', 'Génesis', 43, 14, '¡Que el Dios Todopoderoso permita que ese hombre les tenga compasión y deje libre a su otro hermano, y además vuelvan con Benjamín! En cuanto a mí, si he de perder a mis hijos, ¡qué le voy a hacer! ¡Los perderé!'),
('nvi', 'Génesis 43:15', 'Génesis', 43, 15, 'Ellos tomaron los regalos, el doble del dinero, y a Benjamín, y emprendieron el viaje a Egipto. Allí se presentaron ante José.'),
('nvi', 'Génesis 43:16', 'Génesis', 43, 16, 'Cuando éste vio a Benjamín con ellos, le dijo a su mayordomo: «Lleva a estos hombres a mi casa. Luego, mata un animal y prepáralo, pues estos hombres comerán conmigo al mediodía.»'),
('nvi', 'Génesis 43:17', 'Génesis', 43, 17, 'El mayordomo cumplió la orden y los llevó a la casa de José.'),
('nvi', 'Génesis 43:18', 'Génesis', 43, 18, 'Al ver ellos que los llevaban a la casa de José, se asustaron mucho y se dijeron: «Nos llevan por causa del dinero que se puso en nuestras bolsas la vez pasada. Ahora nos atacarán, nos acusarán, y hasta nos harán sus esclavos, con nuestros animales y todo.»'),
('nvi', 'Génesis 43:19', 'Génesis', 43, 19, 'Entonces se acercaron al mayordomo de la casa de José, y antes de entrar le dijeron:'),
('nvi', 'Génesis 43:20', 'Génesis', 43, 20, '—Perdón, señor: nosotros ya vinimos antes para comprar alimento;'),
('nvi', 'Génesis 43:21', 'Génesis', 43, 21, 'pero a nuestro regreso, cuando acampamos para pasar la noche, descubrimos que en cada una de nuestras bolsas estaba el dinero que habíamos pagado. ¡Pero lo hemos traído para devolverlo!'),
('nvi', 'Génesis 43:22', 'Génesis', 43, 22, 'También hemos traído más dinero para comprar alimento. ¡No sabemos quién pudo haber puesto el dinero de vuelta en nuestras bolsas!'),
('nvi', 'Génesis 43:23', 'Génesis', 43, 23, '—Está bien, no tengan miedo —contestó aquel hombre—. El Dios de ustedes y de su padre habrá puesto ese tesoro en sus bolsas. A mí me consta que recibí el dinero que ustedes pagaron. El mayordomo les llevó a Simeón,'),
('nvi', 'Génesis 43:24', 'Génesis', 43, 24, 'y a todos los hizo pasar a la casa de José. Allí les dio agua para que se lavaran los pies, y les dio de comer a sus asnos.'),
('nvi', 'Génesis 43:25', 'Génesis', 43, 25, 'Ellos, por su parte, prepararon los regalos, mientras esperaban que José llegara al mediodía, pues habían oído que comerían allí.'),
('nvi', 'Génesis 43:26', 'Génesis', 43, 26, 'Cuando José entró en su casa, le entregaron los regalos que le habían llevado, y rostro en tierra se postraron ante él.'),
('nvi', 'Génesis 43:27', 'Génesis', 43, 27, 'José les preguntó cómo estaban, y añadió: —¿Cómo está su padre, el anciano del cual me hablaron? ¿Vive todavía?'),
('nvi', 'Génesis 43:28', 'Génesis', 43, 28, '—Nuestro padre, su siervo, se encuentra bien, y todavía vive —respondieron ellos. Y en seguida le hicieron una reverencia para honrarlo.'),
('nvi', 'Génesis 43:29', 'Génesis', 43, 29, 'José miró a su alrededor y, al ver a Benjamín, su hermano de padre y madre, les preguntó: —¿Es éste su hermano menor, del cual me habían hablado? ¡Que Dios te guarde, hijo mío!'),
('nvi', 'Génesis 43:30', 'Génesis', 43, 30, 'Conmovido por la presencia de su hermano, y no pudiendo contener el llanto, José salió de prisa. Entró en su habitación, y allí se echó a llorar desconsoladamente.'),
('nvi', 'Génesis 43:31', 'Génesis', 43, 31, 'Después se lavó la cara y, ya más calmado, salió y ordenó: «¡Sirvan la comida!»'),
('nvi', 'Génesis 43:32', 'Génesis', 43, 32, 'A José le sirvieron en un sector, a los hermanos en otro, y en otro más a los egipcios que comían con José. Los egipcios no comían con los hebreos porque, para los habitantes de Egipto, era una abominación.'),
('nvi', 'Génesis 43:33', 'Génesis', 43, 33, 'Los hermanos de José estaban sentados frente a él, de mayor a menor, y unos a otros se miraban con asombro.'),
('nvi', 'Génesis 43:34', 'Génesis', 43, 34, 'Las porciones les eran servidas desde la mesa de José, pero a Benjamín se le servían porciones mucho más grandes que a los demás. En compañía de José, todos bebieron y se alegraron.'),
('nvi', 'Génesis 44:1', 'Génesis', 44, 1, 'Más tarde, José ordenó al mayordomo de su casa: «Llena con todo el alimento que les quepa los costales de estos hombres, y pon en sus bolsas el dinero de cada uno de ellos.'),
('nvi', 'Génesis 44:2', 'Génesis', 44, 2, 'Luego mete mi copa de plata en la bolsa del hermano menor, junto con el dinero que pagó por el alimento.» Y el mayordomo hizo todo lo que José le ordenó.'),
('nvi', 'Génesis 44:3', 'Génesis', 44, 3, 'A la mañana siguiente, muy temprano, los hermanos de José fueron enviados de vuelta, junto con sus asnos.'),
('nvi', 'Génesis 44:4', 'Génesis', 44, 4, 'Todavía no estaban muy lejos de la ciudad cuando José le dijo al mayordomo de su casa: «¡Anda! ¡Persigue a esos hombres! Cuando los alcances, diles: “¿Por qué me han pagado mal por bien?'),
('nvi', 'Génesis 44:5', 'Génesis', 44, 5, '¿Por qué han robado la copa que usa mi señor para beber y para adivinar? ¡Esto que han hecho está muy mal!”»'),
('nvi', 'Génesis 44:6', 'Génesis', 44, 6, 'Cuando el mayordomo los alcanzó, les repitió esas mismas palabras.'),
('nvi', 'Génesis 44:7', 'Génesis', 44, 7, 'Pero ellos respondieron: —¿Por qué nos dice usted tales cosas, mi señor? ¡Lejos sea de nosotros actuar de esa manera!'),
('nvi', 'Génesis 44:8', 'Génesis', 44, 8, 'Es más, nosotros le trajimos de vuelta de Canaán el dinero que habíamos pagado, pero que encontramos en nuestras bolsas. ¿Por qué, entonces, habríamos de robar oro o plata de la casa de su señor?'),
('nvi', 'Génesis 44:9', 'Génesis', 44, 9, 'Si se encuentra la copa en poder de alguno de nosotros, que muera el que la tenga, y el resto de nosotros seremos esclavos de mi señor.'),
('nvi', 'Génesis 44:10', 'Génesis', 44, 10, '—Está bien —respondió el mayordomo—, se hará como ustedes dicen, pero sólo el que tenga la copa en su poder será mi esclavo; el resto de ustedes quedará libre de todo cargo.'),
('nvi', 'Génesis 44:11', 'Génesis', 44, 11, 'En seguida cada uno de ellos bajó al suelo su bolsa y la abrió.'),
('nvi', 'Génesis 44:12', 'Génesis', 44, 12, 'El mayordomo revisó cada bolsa, comenzando con la del hermano mayor y terminando con la del menor. ¡Y encontró la copa en la bolsa de Benjamín!'),
('nvi', 'Génesis 44:13', 'Génesis', 44, 13, 'Al ver esto, los hermanos de José se rasgaron las vestiduras en señal de duelo y, luego de cargar sus asnos, volvieron a la ciudad.'),
('nvi', 'Génesis 44:14', 'Génesis', 44, 14, 'Todavía estaba José en su casa cuando llegaron Judá y sus hermanos. Entonces se postraron rostro en tierra,'),
('nvi', 'Génesis 44:15', 'Génesis', 44, 15, 'y José les dijo: —¿Qué manera de portarse es ésta? ¿Acaso no saben que un hombre como yo puede adivinar?'),
('nvi', 'Génesis 44:16', 'Génesis', 44, 16, '—¡No sabemos qué decirle, mi señor! —contestó Judá—. ¡No hay excusa que valga! ¿Cómo podemos demostrar nuestra inocencia? Dios ha puesto al descubierto la maldad de sus siervos. Aquí nos tiene usted: somos sus esclavos, nosotros y el que tenía la copa.'),
('nvi', 'Génesis 44:17', 'Génesis', 44, 17, '—¡Jamás podría yo actuar de ese modo! —respondió José—. Sólo será mi esclavo el que tenía la copa en su poder. En cuanto a ustedes, regresen tranquilos a la casa de su padre.'),
('nvi', 'Génesis 44:18', 'Génesis', 44, 18, 'Entonces Judá se acercó a José para decirle: —Mi señor, no se enoje usted conmigo, pero le ruego que me permita hablarle en privado. Para mí, usted es tan importante como el faraón.'),
('nvi', 'Génesis 44:19', 'Génesis', 44, 19, 'Cuando mi señor nos preguntó si todavía teníamos un padre o algún otro hermano,'),
('nvi', 'Génesis 44:20', 'Génesis', 44, 20, 'nosotros le contestamos que teníamos un padre anciano, y un hermano que le nació a nuestro padre en su vejez. Nuestro padre quiere muchísimo a este último porque es el único que le queda de la misma madre, ya que el otro murió.'),
('nvi', 'Génesis 44:21', 'Génesis', 44, 21, 'Entonces usted nos obligó a traer a este hermano menor para conocerlo.'),
('nvi', 'Génesis 44:22', 'Génesis', 44, 22, 'Nosotros le dijimos que el joven no podía dejar a su padre porque, si lo hacía, seguramente su padre moriría.'),
('nvi', 'Génesis 44:23', 'Génesis', 44, 23, 'Pero usted insistió y nos advirtió que, si no traíamos a nuestro hermano menor, nunca más seríamos recibidos en su presencia.'),
('nvi', 'Génesis 44:24', 'Génesis', 44, 24, 'Entonces regresamos adonde vive mi padre, su siervo, y le informamos de todo lo que usted nos había dicho.'),
('nvi', 'Génesis 44:25', 'Génesis', 44, 25, 'Tiempo después nuestro padre nos dijo: “Vuelvan otra vez a comprar un poco de alimento.”'),
('nvi', 'Génesis 44:26', 'Génesis', 44, 26, 'Nosotros le contestamos: “No podemos ir si nuestro hermano menor no va con nosotros. No podremos presentarnos ante hombre tan importante, a menos que nuestro hermano menor nos acompañe.”'),
('nvi', 'Génesis 44:27', 'Génesis', 44, 27, 'Mi padre, su siervo, respondió: Üstedes saben que mi esposa me dio dos hijos.'),
('nvi', 'Génesis 44:28', 'Génesis', 44, 28, 'Uno desapareció de mi lado, y no he vuelto a verlo. Con toda seguridad fue despedazado por las fieras.'),
('nvi', 'Génesis 44:29', 'Génesis', 44, 29, 'Si también se llevan a éste, y le pasa alguna desgracia, ¡ustedes tendrán la culpa de que este pobre viejo se muera de tristeza!”'),
('nvi', 'Génesis 44:30', 'Génesis', 44, 30, '»Así que, si yo regreso a mi padre, su siervo, y el joven, cuya vida está tan unida a la de mi padre, no regresa con nosotros,'),
('nvi', 'Génesis 44:31', 'Génesis', 44, 31, 'seguramente mi padre, al no verlo, morirá, y nosotros seremos los culpables de que nuestro padre se muera de tristeza.'),
('nvi', 'Génesis 44:32', 'Génesis', 44, 32, 'Este siervo suyo quedó ante mi padre como responsable del joven. Le dije: “Si no te lo devuelvo, padre mío, seré culpable ante ti toda mi vida.”'),
('nvi', 'Génesis 44:33', 'Génesis', 44, 33, 'Por eso, permita usted que yo me quede como esclavo suyo en lugar de mi hermano menor, y que él regrese con sus hermanos.'),
('nvi', 'Génesis 44:34', 'Génesis', 44, 34, '¿Cómo podré volver junto a mi padre si mi hermano menor no está conmigo? ¡No soy capaz de ver la desgracia que le sobrevendrá a mi padre!'),
('nvi', 'Génesis 45:1', 'Génesis', 45, 1, 'José ya no pudo controlarse delante de sus servidores, así que ordenó: «¡Que salgan todos de mi presencia!» Y ninguno de ellos quedó con él. Cuando se dio a conocer a sus hermanos,'),
('nvi', 'Génesis 45:2', 'Génesis', 45, 2, 'comenzó a llorar tan fuerte que los egipcios se enteraron, y la noticia llegó hasta la casa del faraón.'),
('nvi', 'Génesis 45:3', 'Génesis', 45, 3, '—Yo soy José —les declaró a sus hermanos—. ¿Vive todavía mi padre? Pero ellos estaban tan pasmados que no atinaban a contestarle.'),
('nvi', 'Génesis 45:4', 'Génesis', 45, 4, 'No obstante, José insistió: —¡Acérquense! Cuando ellos se acercaron, él añadió: —Yo soy José, el hermano de ustedes, a quien vendieron a Egipto.'),
('nvi', 'Génesis 45:5', 'Génesis', 45, 5, 'Pero ahora, por favor no se aflijan más ni se reprochen el haberme vendido, pues en realidad fue Dios quien me mandó delante de ustedes para salvar vidas.'),
('nvi', 'Génesis 45:6', 'Génesis', 45, 6, 'Desde hace dos años la región está sufriendo de hambre, y todavía faltan cinco años más en que no habrá siembras ni cosechas.'),
('nvi', 'Génesis 45:7', 'Génesis', 45, 7, 'Por eso Dios me envió delante de ustedes: para salvarles la vida de manera extraordinaria y de ese modo asegurarles descendencia sobre la tierra.'),
('nvi', 'Génesis 45:8', 'Génesis', 45, 8, 'Fue Dios quien me envió aquí, y no ustedes. Él me ha puesto como asesor del faraón y administrador de su casa, y como gobernador de todo Egipto.'),
('nvi', 'Génesis 45:9', 'Génesis', 45, 9, '¡Vamos, apúrense! Vuelvan a la casa de mi padre y díganle: “Así dice tu hijo José: ‘Dios me ha hecho gobernador de todo Egipto. Ven a verme. No te demores.'),
('nvi', 'Génesis 45:10', 'Génesis', 45, 10, 'Vivirás en la región de Gosén, cerca de mí, con tus hijos y tus nietos, y con tus ovejas, y vacas y todas tus posesiones.'),
('nvi', 'Génesis 45:11', 'Génesis', 45, 11, 'Yo les proveeré alimento allí, porque aún quedan cinco años más de hambre. De lo contrario, tú y tu familia, y todo lo que te pertenece, caerán en la miseria.’ ”'),
('nvi', 'Génesis 45:12', 'Génesis', 45, 12, 'Además, ustedes y mi hermano Benjamín son testigos de que yo mismo lo he dicho.'),
('nvi', 'Génesis 45:13', 'Génesis', 45, 13, 'Cuéntenle a mi padre del prestigio que tengo en Egipto, y de todo lo que han visto. ¡Pero apúrense y tráiganlo ya!'),
('nvi', 'Génesis 45:14', 'Génesis', 45, 14, 'Y abrazó José a su hermano Benjamín, y comenzó a llorar. Benjamín, a su vez, también lloró abrazado a su hermano José.'),
('nvi', 'Génesis 45:15', 'Génesis', 45, 15, 'Luego José, bañado en lágrimas, besó a todos sus hermanos. Sólo entonces se animaron ellos a hablarle.'),
('nvi', 'Génesis 45:16', 'Génesis', 45, 16, 'Cuando llegó al palacio del faraón la noticia de que habían llegado los hermanos de José, tanto el faraón como sus funcionarios se alegraron.'),
('nvi', 'Génesis 45:17', 'Génesis', 45, 17, 'Y el faraón le dijo a José: «Ordena a tus hermanos que carguen sus animales y vuelvan a Canaán.'),
('nvi', 'Génesis 45:18', 'Génesis', 45, 18, 'Que me traigan a su padre y a sus familias. Yo les daré lo mejor de Egipto, y comerán de la abundancia de este país.'),
('nvi', 'Génesis 45:19', 'Génesis', 45, 19, 'Diles, además, que se lleven carros de Egipto para traer a sus niños y mujeres, y también al padre de ustedes,'),
('nvi', 'Génesis 45:20', 'Génesis', 45, 20, 'y que no se preocupen por las cosas que tengan que dejar, porque lo mejor de todo Egipto será para ustedes.»'),
('nvi', 'Génesis 45:21', 'Génesis', 45, 21, 'Así lo hicieron los hijos de Israel. José les proporcionó los carros, conforme al mandato del faraón, y también les dio provisiones para el viaje.'),
('nvi', 'Génesis 45:22', 'Génesis', 45, 22, 'Además, a cada uno le dio ropa nueva, y a Benjamín le entregó trescientas monedas de plata y cinco mudas de ropa.'),
('nvi', 'Génesis 45:23', 'Génesis', 45, 23, 'A su padre le envió lo siguiente: diez asnos cargados con lo mejor de Egipto, diez asnas cargadas de cereales, y pan y otras provisiones para el viaje de su padre.'),
('nvi', 'Génesis 45:24', 'Génesis', 45, 24, 'Al despedirse de sus hermanos, José les recomendó: «¡No se vayan peleando por el camino!»'),
('nvi', 'Génesis 45:25', 'Génesis', 45, 25, 'Los hermanos de José salieron de Egipto y llegaron a Canaán, donde residía su padre Jacob.'),
('nvi', 'Génesis 45:26', 'Génesis', 45, 26, 'Al llegar le dijeron: «¡José vive, José vive! ¡Es el gobernador de todo Egipto!» Jacob quedó atónito y no les creía,'),
('nvi', 'Génesis 45:27', 'Génesis', 45, 27, 'pero ellos le repetían una y otra vez todo lo que José les había dicho. Y cuando su padre Jacob vio los carros que José había enviado para llevarlo, se reanimó.'),
('nvi', 'Génesis 45:28', 'Génesis', 45, 28, 'Entonces exclamó: «¡Con esto me basta! ¡Mi hijo José aún vive! Iré a verlo antes de morirme.»'),
('nvi', 'Génesis 46:1', 'Génesis', 46, 1, 'Israel emprendió el viaje con todas sus pertenencias. Al llegar a Berseba, ofreció sacrificios al Dios de su padre Isaac.'),
('nvi', 'Génesis 46:2', 'Génesis', 46, 2, 'Esa noche Dios le habló a Israel en una visión: —¡Jacob! ¡Jacob! —Aquí estoy —respondió.'),
('nvi', 'Génesis 46:3', 'Génesis', 46, 3, '—Yo soy Dios, el Dios de tu padre —le dijo—. No tengas temor de ir a Egipto, porque allí haré de ti una gran nación.'),
('nvi', 'Génesis 46:4', 'Génesis', 46, 4, 'Yo te acompañaré a Egipto, y yo mismo haré que vuelvas. Además, cuando mueras, será José quien te cierre los ojos.'),
('nvi', 'Génesis 46:5', 'Génesis', 46, 5, 'Luego Jacob salió de Berseba, y los hijos de Israel hicieron que su padre Jacob, y sus hijos y sus mujeres, subieran en los carros que el faraón había enviado para trasladarlos.'),
('nvi', 'Génesis 46:6', 'Génesis', 46, 6, 'También se llevaron el ganado y las posesiones que habían adquirido en Canaán. Fue así como Jacob y sus descendientes llegaron a Egipto.'),
('nvi', 'Génesis 46:7', 'Génesis', 46, 7, 'Con él se llevó a todos sus hijos, hijas, nietos y nietas, es decir, a todos sus descendientes.'),
('nvi', 'Génesis 46:8', 'Génesis', 46, 8, 'Éstos son los nombres de los israelitas que fueron a Egipto, es decir, Jacob y sus hijos: Rubén, el primogénito de Jacob.'),
('nvi', 'Génesis 46:9', 'Génesis', 46, 9, 'Los hijos de Rubén: Janoc, Falú, Jezrón y Carmí.'),
('nvi', 'Génesis 46:10', 'Génesis', 46, 10, 'Los hijos de Simeón: Jemuel, Jamín, Oad, Jaquín, Zojar y Saúl, hijo de una cananea.'),
('nvi', 'Génesis 46:11', 'Génesis', 46, 11, 'Los hijos de Leví: Guersón, Coat y Merari.'),
('nvi', 'Génesis 46:12', 'Génesis', 46, 12, 'Los hijos de Judá: Er, Onán, Selá, Fares y Zera. (Er y Onán habían muerto en Canaán). Los hijos de Fares: Jezrón y Jamul.'),
('nvi', 'Génesis 46:13', 'Génesis', 46, 13, 'Los hijos de Isacar: Tola, Fuvá, Job y Simrón.'),
('nvi', 'Génesis 46:14', 'Génesis', 46, 14, 'Los hijos de Zabulón: Séred, Elón y Yalel.'),
('nvi', 'Génesis 46:15', 'Génesis', 46, 15, 'Éstos fueron los hijos que Jacob tuvo con Lea en Padán Aram, además de su hija Dina. En total, entre hombres y mujeres eran treinta y tres personas.'),
('nvi', 'Génesis 46:16', 'Génesis', 46, 16, 'Los hijos de Gad: Zefón, Jaguí, Esbón, Suni, Erí, Arodí y Arelí.'),
('nvi', 'Génesis 46:17', 'Génesis', 46, 17, 'Los hijos de Aser: Imná, Isvá, Isví, Beriá, y su hermana que se llamaba Sera. Los hijos de Beriá: Héber y Malquiel.'),
('nvi', 'Génesis 46:18', 'Génesis', 46, 18, 'Éstos fueron los hijos que Zilpá tuvo con Jacob. Zilpá era la esclava que Labán le había regalado a su hija Lea. Sus descendientes eran en total dieciséis personas.'),
('nvi', 'Génesis 46:19', 'Génesis', 46, 19, 'Los hijos de Raquel, la esposa de Jacob: José y Benjamín.'),
('nvi', 'Génesis 46:20', 'Génesis', 46, 20, 'En Egipto, José tuvo los siguientes hijos con Asenat, hija de Potifera, sacerdote de On: Manasés y Efraín.'),
('nvi', 'Génesis 46:21', 'Génesis', 46, 21, 'Los hijos de Benjamín: Bela, Béquer, Asbel, Guerá, Naamán, Ehí, Ros, Mupín, Jupín y Ard.'),
('nvi', 'Génesis 46:22', 'Génesis', 46, 22, 'Éstos fueron los descendientes de Jacob y Raquel, en total catorce personas.'),
('nvi', 'Génesis 46:23', 'Génesis', 46, 23, 'El hijo de Dan: Jusín.'),
('nvi', 'Génesis 46:24', 'Génesis', 46, 24, 'Los hijos de Neftalí: Yazel, Guní, Jéser y Silén.'),
('nvi', 'Génesis 46:25', 'Génesis', 46, 25, 'Éstos fueron los hijos que Jacob tuvo con Bilhá. Ella era la esclava que Labán le regaló a su hija Raquel. El total de sus descendientes fue de siete personas.'),
('nvi', 'Génesis 46:26', 'Génesis', 46, 26, 'Todos los familiares de Jacob que llegaron a Egipto, y que eran de su misma sangre, fueron sesenta y seis, sin contar a las nueras.'),
('nvi', 'Génesis 46:27', 'Génesis', 46, 27, 'José tenía dos hijos que le nacieron en Egipto. En total los familiares de Jacob que llegaron a Egipto fueron setenta.'),
('nvi', 'Génesis 46:28', 'Génesis', 46, 28, 'Jacob mandó a Judá que se adelantara para que le anunciara a José su llegada y éste lo recibiera en Gosén. Cuando llegaron a esa región,'),
('nvi', 'Génesis 46:29', 'Génesis', 46, 29, 'José hizo que prepararan su carruaje, y salió a Gosén para recibir a su padre Israel. Cuando se encontraron, José se fundió con su padre en un abrazo, y durante un largo rato lloró sobre su hombro.'),
('nvi', 'Génesis 46:30', 'Génesis', 46, 30, 'Entonces Israel le dijo a José: —¡Ya me puedo morir! ¡Te he visto y aún estás con vida!'),
('nvi', 'Génesis 46:31', 'Génesis', 46, 31, 'José les dijo a sus hermanos y a la familia de su padre: —Voy a informarle al faraón que mis hermanos y la familia de mi padre, quienes vivían en Canaán, han venido a quedarse conmigo.'),
('nvi', 'Génesis 46:32', 'Génesis', 46, 32, 'Le diré que ustedes son pastores que cuidan ganado, y que han traído sus ovejas y sus vacas, y todo cuanto tenían.'),
('nvi', 'Génesis 46:33', 'Génesis', 46, 33, 'Por eso, cuando el faraón los llame y les pregunte a qué se dedican,'),
('nvi', 'Génesis 46:34', 'Génesis', 46, 34, 'díganle que siempre se han ocupado de cuidar ganado, al igual que sus antepasados. Así podrán establecerse en la región de Gosén, pues los egipcios detestan el oficio de pastor.'),
('nvi', 'Génesis 47:1', 'Génesis', 47, 1, 'José fue a informarle al faraón, y le dijo: —Mi padre y mis hermanos han venido desde Canaán con sus ovejas y sus vacas y todas sus pertenencias. Ya se encuentran en la región de Gosén.'),
('nvi', 'Génesis 47:2', 'Génesis', 47, 2, 'Además, José había elegido a cinco de sus hermanos para presentárselos al faraón.'),
('nvi', 'Génesis 47:3', 'Génesis', 47, 3, 'Y éste les preguntó: —¿En qué trabajan ustedes? —Nosotros, sus siervos, somos pastores, al igual que nuestros antepasados —respondieron ellos—.'),
('nvi', 'Génesis 47:4', 'Génesis', 47, 4, 'Hemos venido a vivir en este país porque en Canaán ya no hay pastos para nuestros rebaños. ¡Es terrible el hambre que acosa a ese país! Por eso le rogamos a usted nos permita vivir en la región de Gosén.'),
('nvi', 'Génesis 47:5', 'Génesis', 47, 5, 'Entonces el faraón le dijo a José: —Tu padre y tus hermanos han venido a estar contigo.'),
('nvi', 'Génesis 47:6', 'Génesis', 47, 6, 'La tierra de Egipto está a tu disposición. Haz que se asienten en lo mejor de la tierra; que residan en la región de Gosén. Y si sabes que hay entre ellos hombres capaces, ponlos a cargo de mi propio ganado.'),
('nvi', 'Génesis 47:7', 'Génesis', 47, 7, 'Luego José llevó a Jacob, su padre, y se lo presentó al faraón. Jacob saludó al faraón con reverencia,'),
('nvi', 'Génesis 47:8', 'Génesis', 47, 8, 'y el faraón le preguntó: —¿Cuántos años tienes?'),
('nvi', 'Génesis 47:9', 'Génesis', 47, 9, '—Ya tengo ciento treinta años —respondió Jacob—. Mis años de andar peregrinando de un lado a otro han sido pocos y difíciles, pero no se comparan con los años de peregrinaje de mis antepasados.'),
('nvi', 'Génesis 47:10', 'Génesis', 47, 10, 'Luego Jacob se despidió del faraón con sumo respeto, y se retiró de su presencia.'),
('nvi', 'Génesis 47:11', 'Génesis', 47, 11, 'José instaló a su padre y a sus hermanos, y les entregó terrenos en la mejor región de Egipto, es decir, en el distrito de Ramsés, tal como lo había ordenado el faraón.'),
('nvi', 'Génesis 47:12', 'Génesis', 47, 12, 'José también proveyó de alimentos a su padre y a sus hermanos, y a todos sus familiares, según las necesidades de cada uno.'),
('nvi', 'Génesis 47:13', 'Génesis', 47, 13, 'El hambre en Egipto y en Canaán era terrible. No había alimento en ninguna parte, y la gente estaba a punto de morir.'),
('nvi', 'Génesis 47:14', 'Génesis', 47, 14, 'Todo el dinero que los habitantes de Egipto y de Canaán habían pagado por el alimento, José lo recaudó para depositarlo en el palacio del faraón.'),
('nvi', 'Génesis 47:15', 'Génesis', 47, 15, 'Cuando a egipcios y cananeos se les acabó el dinero, los egipcios fueron a ver a José y le reclamaron: —¡Dénos de comer! ¿Hemos de morir en su presencia sólo porque no tenemos más dinero?'),
('nvi', 'Génesis 47:16', 'Génesis', 47, 16, 'Y José les contestó: —Si ya se les acabó el dinero, traigan su ganado y, a cambio, les daré alimento.'),
('nvi', 'Génesis 47:17', 'Génesis', 47, 17, 'Los egipcios llevaron a José su ganado, es decir, sus caballos, vacas, ovejas y asnos, y a cambio de ellos José les dio alimento durante todo ese año.'),
('nvi', 'Génesis 47:18', 'Génesis', 47, 18, 'Al año siguiente fueron a decirle a José: —Señor, no podemos ocultar el hecho de que ya no tenemos más dinero, y de que todo nuestro ganado ya es suyo. Ya no tenemos nada que ofrecerle, de no ser nuestros propios cuerpos y nuestras tierras.'),
('nvi', 'Génesis 47:19', 'Génesis', 47, 19, '¿Va usted a permitir que nos muramos junto con nuestras tierras? Cómprenos usted a nosotros y a nuestras tierras, a cambio de alimento. Así seremos esclavos del faraón junto con nuestras tierras. ¡Pero dénos usted semilla, para que podamos vivir y la tierra no quede desolada!'),
('nvi', 'Génesis 47:20', 'Génesis', 47, 20, 'De esta manera José adquirió para el faraón todas las tierras de Egipto, porque los egipcios, obligados por el hambre, le vendieron todos sus terrenos. Fue así como todo el país llegó a ser propiedad del faraón,'),
('nvi', 'Génesis 47:21', 'Génesis', 47, 21, 'y todos en Egipto quedaron reducidos a la esclavitud.'),
('nvi', 'Génesis 47:22', 'Génesis', 47, 22, 'Los únicos terrenos que José no compró fueron los que pertenecían a los sacerdotes. Éstos no tuvieron que vender sus terrenos porque recibían una ración de alimento de parte del faraón.'),
('nvi', 'Génesis 47:23', 'Génesis', 47, 23, 'Luego José le informó al pueblo: —Desde ahora ustedes y sus tierras pertenecen al faraón, porque yo los he comprado. Aquí tienen semilla. Siembren la tierra.'),
('nvi', 'Génesis 47:24', 'Génesis', 47, 24, 'Cuando llegue la cosecha, deberán entregarle al faraón la quinta parte de lo cosechado. Las otras cuatro partes serán para la siembra de los campos, y para alimentarlos a ustedes, a sus hijos y a sus familiares.'),
('nvi', 'Génesis 47:25', 'Génesis', 47, 25, '—¡Usted nos ha salvado la vida, y hemos contado con su favor! —respondieron ellos—. ¡Seremos esclavos del faraón!'),
('nvi', 'Génesis 47:26', 'Génesis', 47, 26, 'José estableció esta ley en toda la tierra de Egipto, que hasta el día de hoy sigue vigente: la quinta parte de la cosecha le pertenece al faraón. Sólo las tierras de los sacerdotes no llegaron a ser del faraón.'),
('nvi', 'Génesis 47:27', 'Génesis', 47, 27, 'Los israelitas se asentaron en Egipto, en la región de Gosén. Allí adquirieron propiedades, prosperaron y llegaron a ser muy numerosos.'),
('nvi', 'Génesis 47:28', 'Génesis', 47, 28, 'Jacob residió diecisiete años en Egipto, y llegó a vivir un total de ciento cuarenta y siete años.'),
('nvi', 'Génesis 47:29', 'Génesis', 47, 29, 'Cuando Israel estaba a punto de morir, mandó llamar a su hijo José y le dijo: —Si de veras me quieres, pon tu mano debajo de mi muslo y prométeme amor y lealtad. ¡Por favor, no me entierres en Egipto!'),
('nvi', 'Génesis 47:30', 'Génesis', 47, 30, 'Cuando vaya a descansar junto a mis antepasados, sácame de Egipto y entiérrame en el sepulcro de ellos. —Haré lo que me pides —contestó José.'),
('nvi', 'Génesis 47:31', 'Génesis', 47, 31, '—¡Júramelo! —insistió su padre. José se lo juró, e Israel se reclinó sobre la cabecera de la cama.'),
('nvi', 'Génesis 48:1', 'Génesis', 48, 1, 'Poco tiempo después le informaron a José que su padre estaba enfermo. Entonces fue a visitarlo y llevó consigo a sus dos hijos, Manasés y Efraín.'),
('nvi', 'Génesis 48:2', 'Génesis', 48, 2, 'Cuando le avisaron a Jacob que su hijo venía a verlo, hizo un esfuerzo, se sentó en la cama'),
('nvi', 'Génesis 48:3', 'Génesis', 48, 3, 'y le dijo a José: —El Dios Todopoderoso se me apareció en Luz, en la tierra de Canaán, y me bendijo'),
('nvi', 'Génesis 48:4', 'Génesis', 48, 4, 'con esta promesa: “Te haré fecundo, te multiplicaré, y haré que tus descendientes formen una comunidad de naciones. Además, a tu descendencia le daré esta tierra como su posesión perpetua.”'),
('nvi', 'Génesis 48:5', 'Génesis', 48, 5, 'Ahora bien, los dos hijos que te nacieron aquí en Egipto, antes de que me reuniera contigo, serán considerados míos. Efraín y Manasés serán tan míos como lo son Rubén y Simeón.'),
('nvi', 'Génesis 48:6', 'Génesis', 48, 6, 'Los hijos que tengas después de ellos serán tuyos, y a través de sus hermanos recibirán su herencia.'),
('nvi', 'Génesis 48:7', 'Génesis', 48, 7, 'Cuando yo regresaba de Padán Aram, tu madre murió cerca de Efrata, en tierra de Canaán, y allí la sepulté junto al camino de Efrata, es decir, Belén.'),
('nvi', 'Génesis 48:8', 'Génesis', 48, 8, 'Al ver a los hijos de José, Israel preguntó: —Y estos chicos, ¿quiénes son?'),
('nvi', 'Génesis 48:9', 'Génesis', 48, 9, '—Son los hijos que Dios me ha concedido aquí —le respondió José a su padre. Entonces Israel le dijo: —Acércalos, por favor, para que les dé mi bendición.'),
('nvi', 'Génesis 48:10', 'Génesis', 48, 10, 'Israel ya era muy anciano, y por su avanzada edad casi no podía ver; por eso José los acercó, y su padre los besó y abrazó.'),
('nvi', 'Génesis 48:11', 'Génesis', 48, 11, 'Luego le dijo a José: —Ya había perdido la esperanza de volver a verte, ¡y ahora Dios me ha concedido ver también a tus hijos!'),
('nvi', 'Génesis 48:12', 'Génesis', 48, 12, 'José los retiró de las rodillas de Israel y se postró rostro en tierra.'),
('nvi', 'Génesis 48:13', 'Génesis', 48, 13, 'Luego tomó a sus dos hijos, a Efraín con la derecha y a Manasés con la izquierda, y se los presentó a su padre. De esta manera Efraín quedó a la izquierda de Israel y Manasés a su derecha.'),
('nvi', 'Génesis 48:14', 'Génesis', 48, 14, 'Pero Israel, al extender las manos, las entrecruzó y puso su derecha sobre la cabeza de Efraín, aunque era el menor, y su izquierda sobre la cabeza de Manasés, aunque era el mayor.'),
('nvi', 'Génesis 48:15', 'Génesis', 48, 15, 'Y los bendijo con estas palabras: «Que el Dios en cuya presencia caminaron mis padres, Abraham e Isaac, el Dios que me ha guiado desde el día en que nací hasta hoy,'),
('nvi', 'Génesis 48:16', 'Génesis', 48, 16, 'el ángel que me ha rescatado de todo mal, bendiga a estos jóvenes. Que por medio de ellos sea recordado mi nombre y el de mis padres, Abraham e Isaac. Que crezcan y se multipliquen sobre la tierra.»'),
('nvi', 'Génesis 48:17', 'Génesis', 48, 17, 'A José no le agradó ver que su padre pusiera su mano derecha sobre la cabeza de Efraín, así que tomando la mano de su padre, la pasó de la cabeza de Efraín a la de Manasés,'),
('nvi', 'Génesis 48:18', 'Génesis', 48, 18, 'mientras le reclamaba: —¡Así no, padre mío! ¡Pon tu mano derecha sobre la cabeza de éste, que es el primogénito!'),
('nvi', 'Génesis 48:19', 'Génesis', 48, 19, 'Pero su padre se resistió, y le contestó: —¡Ya lo sé, hijo, ya lo sé! También él gestará a un pueblo, y llegará a ser importante. Pero su hermano menor será aún más importante, y su descendencia dará origen a muchas naciones.'),
('nvi', 'Génesis 48:20', 'Génesis', 48, 20, 'Aquel día Jacob los bendijo así: «Ésta será la bendición que en Israel se habrá de pronunciar: “Que Dios cuide de ti como cuidó de Efraín y de Manasés.”» De este modo, Israel dio a Efraín la primacía sobre Manasés.'),
('nvi', 'Génesis 48:21', 'Génesis', 48, 21, 'Finalmente, Israel le dijo a José: —Yo estoy a punto de morir; pero Dios estará con ustedes y los hará volver a la tierra de sus antepasados.'),
('nvi', 'Génesis 48:22', 'Génesis', 48, 22, 'Y a ti, que estás por encima de tus hermanos, te doy Siquén, tierra que luchando a brazo partido arrebaté a los amorreos.'),
('nvi', 'Génesis 49:1', 'Génesis', 49, 1, 'Jacob llamó a sus hijos y les dijo: «Reúnanse, que voy a declararles lo que les va a suceder en el futuro:'),
('nvi', 'Génesis 49:2', 'Génesis', 49, 2, '»Hijos de Jacob: acérquense y escuchen; presten atención a su padre Israel.'),
('nvi', 'Génesis 49:3', 'Génesis', 49, 3, '»Tú, Rubén, eres mi primogénito, primer fruto de mi fuerza y virilidad, primero en honor y en poder.'),
('nvi', 'Génesis 49:4', 'Génesis', 49, 4, 'Impetuoso como un torrente, ya no serás el primero: te acostaste en mi cama; profanaste la cama de tu propio padre.'),
('nvi', 'Génesis 49:5', 'Génesis', 49, 5, '»Simeón y Leví son chacales; sus espadas son instrumentos de violencia.'),
('nvi', 'Génesis 49:6', 'Génesis', 49, 6, '¡No quiero participar de sus reuniones, ni arriesgar mi honor en sus asambleas! En su furor mataron hombres, y por capricho mutilaron toros.'),
('nvi', 'Génesis 49:7', 'Génesis', 49, 7, '¡Malditas sean la violencia de su enojo y la crueldad de su furor! Los dispersaré en el país de Jacob, los desparramaré en la tierra de Israel.'),
('nvi', 'Génesis 49:8', 'Génesis', 49, 8, '»Tú, Judá, serás alabado por tu hermanos; dominarás a tus enemigos, y tus propios hermanos se inclinarán ante ti.'),
('nvi', 'Génesis 49:9', 'Génesis', 49, 9, 'Mi hijo Judá es como un cachorro de león que se ha nutrido de la presa. Se tiende al acecho como león, como leona que nadie se atreve a molestar.'),
('nvi', 'Génesis 49:10', 'Génesis', 49, 10, 'El cetro no se apartará de Judá, ni de entre sus pies el bastón de mando, hasta que llegue el verdadero rey, quien merece la obediencia de los pueblos.'),
('nvi', 'Génesis 49:11', 'Génesis', 49, 11, 'Judá amarra su asno a la vid, y la cría de su asno a la mejor cepa; lava su ropa en vino; su manto, en la sangre de las uvas.'),
('nvi', 'Génesis 49:12', 'Génesis', 49, 12, 'Sus ojos son más oscuros que el vino; sus dientes, más blancos que la leche.'),
('nvi', 'Génesis 49:13', 'Génesis', 49, 13, '»Zabulón vivirá a la orilla del mar; será puerto seguro para las naves, y sus fronteras llegarán hasta Sidón.'),
('nvi', 'Génesis 49:14', 'Génesis', 49, 14, '»Isacar es un asno fuerte echado entre dos alforjas.'),
('nvi', 'Génesis 49:15', 'Génesis', 49, 15, 'Al ver que el establo era bueno y que la tierra era agradable, agachó el hombro para llevar la carga y se sometió a la esclavitud.'),
('nvi', 'Génesis 49:16', 'Génesis', 49, 16, '»Dan hará justicia en su pueblo, como una de las tribus de Israel.'),
('nvi', 'Génesis 49:17', 'Génesis', 49, 17, 'Dan es una serpiente junto al camino, una víbora junto al sendero, que muerde los talones del caballo y hace caer de espaldas al jinete.'),
('nvi', 'Génesis 49:18', 'Génesis', 49, 18, '»¡SEÑOR, espero tu salvación!'),
('nvi', 'Génesis 49:19', 'Génesis', 49, 19, '»Las hordas atacan a Gad, pero él las atacará por la espalda.'),
('nvi', 'Génesis 49:20', 'Génesis', 49, 20, '»Aser disfrutará de comidas deliciosas; ofrecerá manjares de reyes.'),
('nvi', 'Génesis 49:21', 'Génesis', 49, 21, '»Neftalí es una gacela libre, que tiene hermosos cervatillos.'),
('nvi', 'Génesis 49:22', 'Génesis', 49, 22, '»José es un retoño fértil, fértil retoño junto al agua, cuyas ramas trepan por el muro.'),
('nvi', 'Génesis 49:23', 'Génesis', 49, 23, 'Los arqueros lo atacaron sin piedad; le tiraron flechas, lo hostigaron.'),
('nvi', 'Génesis 49:24', 'Génesis', 49, 24, 'Pero su arco se mantuvo firme, porque sus brazos son fuertes. ¡Gracias al Dios fuerte de Jacob, al Pastor y Roca de Israel!'),
('nvi', 'Génesis 49:25', 'Génesis', 49, 25, '¡Gracias al Dios de tu padre, que te ayuda! ¡Gracias al Todopoderoso, que te bendice! ¡Con bendiciones de lo alto! ¡Con bendiciones del abismo! ¡Con bendiciones de los pechos y del seno materno!'),
('nvi', 'Génesis 49:26', 'Génesis', 49, 26, 'Son mejores las bendiciones de tu padre que las de los montes de antaño, que la abundancia de las colinas eternas. ¡Que descansen estas bendiciones sobre la cabeza de José, sobre la frente del escogido entre sus hermanos!'),
('nvi', 'Génesis 49:27', 'Génesis', 49, 27, '»Benjamín es un lobo rapaz que en la mañana devora la presa y en la tarde reparte los despojos.»'),
('nvi', 'Génesis 49:28', 'Génesis', 49, 28, 'Éstas son las doce tribus de Israel, y esto es lo que su padre les dijo cuando impartió a cada una de ellas su bendición.'),
('nvi', 'Génesis 49:29', 'Génesis', 49, 29, 'Además, Jacob les dio estas instrucciones: «Ya estoy a punto de reunirme con los míos. Entiérrenme junto a mis antepasados, en la cueva que está en el campo de Efrón el hitita.'),
('nvi', 'Génesis 49:30', 'Génesis', 49, 30, 'Se trata de la cueva de Macpela, frente a Mamré, en la tierra de Canaán. Está en el campo que Abraham le compró a Efrón el hitita, para que fuera el sepulcro de la familia.'),
('nvi', 'Génesis 49:31', 'Génesis', 49, 31, 'Allí fueron sepultados Abraham y su esposa Sara, Isaac y su esposa Rebeca, y allí también enterré a Lea.'),
('nvi', 'Génesis 49:32', 'Génesis', 49, 32, 'Ese campo y su cueva se les compró a los hititas.»'),
('nvi', 'Génesis 49:33', 'Génesis', 49, 33, 'Cuando Jacob terminó de dar estas instrucciones a sus hijos, volvió a acostarse, exhaló el último suspiro, y fue a reunirse con sus antepasados.'),
('nvi', 'Génesis 50:1', 'Génesis', 50, 1, 'Entonces José se abrazó al cuerpo de su padre y, llorando, lo besó.'),
('nvi', 'Génesis 50:2', 'Génesis', 50, 2, 'Luego ordenó a los médicos a su servicio que embalsamaran el cuerpo, y así lo hicieron.'),
('nvi', 'Génesis 50:3', 'Génesis', 50, 3, 'El proceso para embalsamarlo tardó unos cuarenta días, que es el tiempo requerido. Los egipcios, por su parte, guardaron luto por Israel durante setenta días.'),
('nvi', 'Génesis 50:4', 'Génesis', 50, 4, 'Pasados los días de duelo, José se dirigió así a los miembros de la corte del faraón: —Si me he ganado el respeto de la corte, díganle por favor al faraón'),
('nvi', 'Génesis 50:5', 'Génesis', 50, 5, 'que mi padre, antes de morirse, me hizo jurar que yo lo sepultaría en la tumba que él mismo se preparó en la tierra de Canaán. Por eso le ruego encarecidamente me permita ir a sepultar a mi padre, y luego volveré.'),
('nvi', 'Génesis 50:6', 'Génesis', 50, 6, 'El faraón le respondió: —Ve a sepultar a tu padre, conforme a la promesa que te pidió hacerle.'),
('nvi', 'Génesis 50:7', 'Génesis', 50, 7, 'José fue a sepultar a su padre, y lo acompañaron los servidores del faraón, es decir, los ancianos de su corte y todos los ancianos de Egipto.'),
('nvi', 'Génesis 50:8', 'Génesis', 50, 8, 'A éstos se sumaron todos los familiares de José, es decir, sus hermanos y los de la casa de Jacob. En la región de Gosén dejaron únicamente a los niños y a los animales.'),
('nvi', 'Génesis 50:9', 'Génesis', 50, 9, 'También salieron con él carros y jinetes, formando así un cortejo muy grande.'),
('nvi', 'Génesis 50:10', 'Génesis', 50, 10, 'Al llegar a la era de Hatad, que está cerca del río Jordán, hicieron grandes y solemnes lamentaciones. Allí José guardó luto por su padre durante siete días.'),
('nvi', 'Génesis 50:11', 'Génesis', 50, 11, 'Cuando los cananeos que vivían en esa región vieron en la era de Hatad aquellas manifestaciones de duelo, dijeron: «Los egipcios están haciendo un duelo muy solemne.» Por eso al lugar, que está cerca del Jordán, lo llamaron Abel Misrayin.'),
('nvi', 'Génesis 50:12', 'Génesis', 50, 12, 'Los hijos de Jacob hicieron con su padre lo que él les había pedido:'),
('nvi', 'Génesis 50:13', 'Génesis', 50, 13, 'lo llevaron a la tierra de Canaán y lo sepultaron en la cueva que está en el campo de Macpela, frente a Mamré, en el mismo campo que Abraham le había comprado a Efrón el hitita para sepultura de la familia.'),
('nvi', 'Génesis 50:14', 'Génesis', 50, 14, 'Luego de haber sepultado a su padre, José regresó a Egipto junto con sus hermanos y con toda la gente que lo había acompañado.'),
('nvi', 'Génesis 50:15', 'Génesis', 50, 15, 'Al reflexionar sobre la muerte de su padre, los hermanos de José concluyeron: «Tal vez José nos guarde rencor, y ahora quiera vengarse de todo el mal que le hicimos.»'),
('nvi', 'Génesis 50:16', 'Génesis', 50, 16, 'Por eso le mandaron a decir: «Antes de morir tu padre, dejó estas instrucciones:'),
('nvi', 'Génesis 50:17', 'Génesis', 50, 17, '“Díganle a José que perdone, por favor, la terrible maldad que sus hermanos cometieron contra él.”Así que, por favor, perdona la maldad de los siervos del Dios de tu padre.» Cuando José escuchó estas palabras, se echó a llorar.'),
('nvi', 'Génesis 50:18', 'Génesis', 50, 18, 'Luego sus hermanos se presentaron ante José, se inclinaron delante de él y le dijeron: —Aquí nos tienes; somos tus esclavos.'),
('nvi', 'Génesis 50:19', 'Génesis', 50, 19, '—No tengan miedo —les contestó José—. ¿Puedo acaso tomar el lugar de Dios?'),
('nvi', 'Génesis 50:20', 'Génesis', 50, 20, 'Es verdad que ustedes pensaron hacerme mal, pero Dios transformó ese mal en bien para lograr lo que hoy estamos viendo: salvar la vida de mucha gente.'),
('nvi', 'Génesis 50:21', 'Génesis', 50, 21, 'Así que, ¡no tengan miedo! Yo cuidaré de ustedes y de sus hijos. Y así, con el corazón en la mano, José los reconfortó.'),
('nvi', 'Génesis 50:22', 'Génesis', 50, 22, 'José y la familia de su padre permanecieron en Egipto. Alcanzó la edad de ciento diez años,'),
('nvi', 'Génesis 50:23', 'Génesis', 50, 23, 'y llegó a ver nacer a los hijos de Efraín hasta la tercera generación. Además, cuando nacieron los hijos de Maquir, hijo de Manasés, él los recibió sobre sus rodillas.'),
('nvi', 'Génesis 50:24', 'Génesis', 50, 24, 'Tiempo después, José les dijo a sus hermanos: «Yo estoy a punto de morir, pero sin duda Dios vendrá a ayudarlos, y los llevará de este país a la tierra que prometió a Abraham, Isaac y Jacob.»'),
('nvi', 'Génesis 50:25', 'Génesis', 50, 25, 'Entonces José hizo que sus hijos le prestaran juramento. Les dijo: «Sin duda Dios vendrá a ayudarlos. Cuando esto ocurra, ustedes deberán llevarse de aquí mis huesos.»'),
('nvi', 'Génesis 50:26', 'Génesis', 50, 26, 'José murió en Egipto a los ciento diez años de edad. Una vez que lo embalsamaron, lo pusieron en un ataúd.'),
('nvi', 'Éxodo 1:1', 'Éxodo', 1, 1, 'Éstos son los nombres de los hijos de Israel que, acompañados de sus familias, llegaron con Jacob a Egipto:'),
('nvi', 'Éxodo 1:2', 'Éxodo', 1, 2, 'Rubén, Simeón, Leví, Judá,'),
('nvi', 'Éxodo 1:3', 'Éxodo', 1, 3, 'Isacar, Zabulón, Benjamín,'),
('nvi', 'Éxodo 1:4', 'Éxodo', 1, 4, 'Dan, Neftalí, Gad y Aser.'),
('nvi', 'Éxodo 1:5', 'Éxodo', 1, 5, 'En total, los descendientes de Jacob eran setenta. José ya estaba en Egipto.'),
('nvi', 'Éxodo 1:6', 'Éxodo', 1, 6, 'Murieron José y sus hermanos y toda aquella generación.'),
('nvi', 'Éxodo 1:7', 'Éxodo', 1, 7, 'Sin embargo, los israelitas tuvieron muchos hijos, y a tal grado se multiplicaron que fueron haciéndose más y más poderosos. El país se fue llenando de ellos.'),
('nvi', 'Éxodo 1:8', 'Éxodo', 1, 8, 'Pero llegó al poder en Egipto otro rey que no había conocido a José,'),
('nvi', 'Éxodo 1:9', 'Éxodo', 1, 9, 'y le dijo a su pueblo: «¡Cuidado con los israelitas, que ya son más fuertes y numerosos que nosotros!'),
('nvi', 'Éxodo 1:10', 'Éxodo', 1, 10, 'Vamos a tener que manejarlos con mucha astucia; de lo contrario, seguirán aumentando y, si estalla una guerra, se unirán a nuestros enemigos, nos combatirán y se irán del país.»'),
('nvi', 'Éxodo 1:11', 'Éxodo', 1, 11, 'Fue así como los egipcios pusieron capataces para que oprimieran a los israelitas. Les impusieron trabajos forzados, tales como los de edificar para el faraón las ciudades de almacenaje Pitón y Ramsés.'),
('nvi', 'Éxodo 1:12', 'Éxodo', 1, 12, 'Pero cuanto más los oprimían, más se multiplicaban y se extendían, de modo que los egipcios llegaron a tenerles miedo;'),
('nvi', 'Éxodo 1:13', 'Éxodo', 1, 13, 'por eso les imponían trabajos pesados y los trataban con crueldad.'),
('nvi', 'Éxodo 1:14', 'Éxodo', 1, 14, 'Les amargaban la vida obligándolos a hacer mezcla y ladrillos, y todas las labores del campo. En todos los trabajos de esclavos que los israelitas realizaban, los egipcios los trataban con crueldad.'),
('nvi', 'Éxodo 1:15', 'Éxodo', 1, 15, 'Había dos parteras hebreas, llamadas Sifrá y Fuvá, a las que el rey de Egipto ordenó:'),
('nvi', 'Éxodo 1:16', 'Éxodo', 1, 16, '—Cuando ayuden a las hebreas en sus partos, fíjense en el sexo: si es niño, mátenlo; pero si es niña, déjenla con vida.'),
('nvi', 'Éxodo 1:17', 'Éxodo', 1, 17, 'Sin embargo, las parteras temían a Dios, así que no siguieron las órdenes del rey de Egipto sino que dejaron con vida a los varones.'),
('nvi', 'Éxodo 1:18', 'Éxodo', 1, 18, 'Entonces el rey de Egipto mandó llamar a las parteras, y les preguntó: —¿Por qué han hecho esto? ¿Por qué han dejado con vida a los varones?'),
('nvi', 'Éxodo 1:19', 'Éxodo', 1, 19, 'Las parteras respondieron: —Resulta que las hebreas no son como las egipcias, sino que están llenas de vida y dan a luz antes de que lleguemos.'),
('nvi', 'Éxodo 1:20', 'Éxodo', 1, 20, 'De este modo los israelitas se hicieron más fuertes y más numerosos. Además, Dios trató muy bien a las parteras'),
('nvi', 'Éxodo 1:21', 'Éxodo', 1, 21, 'y, por haberse mostrado temerosas de Dios, les concedió tener muchos hijos.'),
('nvi', 'Éxodo 1:22', 'Éxodo', 1, 22, 'El faraón, por su parte, dio esta orden a todo su pueblo: —¡Tiren al río a todos los niños hebreos que nazcan! A las niñas, déjenlas con vida.'),
('nvi', 'Éxodo 2:1', 'Éxodo', 2, 1, 'Hubo un levita que tomó por esposa a una mujer de su propia tribu.'),
('nvi', 'Éxodo 2:2', 'Éxodo', 2, 2, 'La mujer quedó embarazada y tuvo un hijo, y al verlo tan hermoso lo escondió durante tres meses.'),
('nvi', 'Éxodo 2:3', 'Éxodo', 2, 3, 'Cuando ya no pudo seguir ocultándolo, preparó una cesta de papiro, la embadurnó con brea y asfalto y, poniendo en ella al niño, fue a dejar la cesta entre los juncos que había a la orilla del Nilo.'),
('nvi', 'Éxodo 2:4', 'Éxodo', 2, 4, 'Pero la hermana del niño se quedó a cierta distancia para ver qué pasaría con él.'),
('nvi', 'Éxodo 2:5', 'Éxodo', 2, 5, 'En eso, la hija del faraón bajó a bañarse en el Nilo. Sus doncellas, mientras tanto, se paseaban por la orilla del río. De pronto la hija del faraón vio la cesta entre los juncos, y ordenó a una de sus esclavas que fuera por ella.'),
('nvi', 'Éxodo 2:6', 'Éxodo', 2, 6, 'Cuando la hija del faraón abrió la cesta y vio allí dentro un niño que lloraba, le tuvo compasión, pero aclaró que se trataba de un niño hebreo.'),
('nvi', 'Éxodo 2:7', 'Éxodo', 2, 7, 'La hermana del niño preguntó entonces a la hija del faraón: —¿Quiere usted que vaya y llame a una nodriza hebrea, para que críe al niño por usted?'),
('nvi', 'Éxodo 2:8', 'Éxodo', 2, 8, '—Ve a llamarla —contestó. La muchacha fue y trajo a la madre del niño,'),
('nvi', 'Éxodo 2:9', 'Éxodo', 2, 9, 'y la hija del faraón le dijo: —Llévate a este niño y críamelo. Yo te pagaré por hacerlo. Fue así como la madre del niño se lo llevó y lo crió.'),
('nvi', 'Éxodo 2:10', 'Éxodo', 2, 10, 'Ya crecido el niño, se lo llevó a la hija del faraón, y ella lo adoptó como hijo suyo; además, le puso por nombre Moisés, pues dijo: «¡Yo lo saqué del río!»'),
('nvi', 'Éxodo 2:11', 'Éxodo', 2, 11, 'Un día, cuando ya Moisés era mayor de edad, fue a ver a sus hermanos de sangre y pudo observar sus penurias. De pronto, vio que un egipcio golpeaba a uno de sus hermanos, es decir, a un hebreo.'),
('nvi', 'Éxodo 2:12', 'Éxodo', 2, 12, 'Miró entonces a uno y otro lado y, al no ver a nadie, mató al egipcio y lo escondió en la arena.'),
('nvi', 'Éxodo 2:13', 'Éxodo', 2, 13, 'Al día siguiente volvió a salir y, al ver que dos hebreos peleaban entre sí, le preguntó al culpable: —¿Por qué golpeas a tu compañero?'),
('nvi', 'Éxodo 2:14', 'Éxodo', 2, 14, '—¿Y quién te nombró a ti gobernante y juez sobre nosotros? —respondió aquél—. ¿Acaso piensas matarme a mí, como mataste al egipcio? Esto le causó temor a Moisés, pues pensó: «¡Ya se supo lo que hice!»'),
('nvi', 'Éxodo 2:15', 'Éxodo', 2, 15, 'Y, en efecto, el faraón se enteró de lo sucedido y trató de matar a Moisés; pero Moisés huyó del faraón y se fue a la tierra de Madián, donde se quedó a vivir junto al pozo.'),
('nvi', 'Éxodo 2:16', 'Éxodo', 2, 16, 'El sacerdote de Madián tenía siete hijas, las cuales solían ir a sacar agua para llenar los abrevaderos y dar de beber a las ovejas de su padre.'),
('nvi', 'Éxodo 2:17', 'Éxodo', 2, 17, 'Pero los pastores llegaban y las echaban de allí. Un día, Moisés intervino en favor de ellas: las puso a salvo de los pastores y dio de beber a sus ovejas.'),
('nvi', 'Éxodo 2:18', 'Éxodo', 2, 18, 'Cuando las muchachas volvieron a la casa de Reuel, su padre, éste les preguntó: —¿Por qué volvieron hoy tan temprano?'),
('nvi', 'Éxodo 2:19', 'Éxodo', 2, 19, '—Porque un egipcio nos libró de los pastores —le respondieron—. ¡Hasta nos sacó el agua del pozo y dio de beber al rebaño!'),
('nvi', 'Éxodo 2:20', 'Éxodo', 2, 20, '—¿Y dónde está ese hombre? —les contestó—. ¿Por qué lo dejaron solo? ¡Invítenlo a comer!'),
('nvi', 'Éxodo 2:21', 'Éxodo', 2, 21, 'Moisés convino en quedarse a vivir en casa de aquel hombre, quien le dio por esposa a su hija Séfora.'),
('nvi', 'Éxodo 2:22', 'Éxodo', 2, 22, 'Ella tuvo un hijo, y Moisés le puso por nombre Guersón, pues razonó: «Soy un extranjero en tierra extraña.»'),
('nvi', 'Éxodo 2:23', 'Éxodo', 2, 23, 'Mucho tiempo después murió el rey de Egipto. Los israelitas, sin embargo, seguían lamentando su condición de esclavos y clamaban pidiendo ayuda. Sus gritos desesperados llegaron a oídos de Dios,'),
('nvi', 'Éxodo 2:24', 'Éxodo', 2, 24, 'quien al oír sus quejas se acordó del pacto que había hecho con Abraham, Isaac y Jacob.'),
('nvi', 'Éxodo 2:25', 'Éxodo', 2, 25, 'Fue así como Dios se fijó en los israelitas y los tomó en cuenta.'),
('nvi', 'Éxodo 3:1', 'Éxodo', 3, 1, 'Un día en que Moisés estaba cuidando el rebaño de Jetro, su suegro, que era sacerdote de Madián, llevó las ovejas hasta el otro extremo del desierto y llegó a Horeb, la montaña de Dios.'),
('nvi', 'Éxodo 3:2', 'Éxodo', 3, 2, 'Estando allí, el ángel del SEÑOR se le apareció entre las llamas de una zarza ardiente. Moisés notó que la zarza estaba envuelta en llamas, pero que no se consumía,'),
('nvi', 'Éxodo 3:3', 'Éxodo', 3, 3, 'así que pensó: «¡Qué increíble! Voy a ver por qué no se consume la zarza.»'),
('nvi', 'Éxodo 3:4', 'Éxodo', 3, 4, 'Cuando el SEÑOR vio que Moisés se acercaba a mirar, lo llamó desde la zarza: —¡Moisés, Moisés! —Aquí me tienes —respondió.'),
('nvi', 'Éxodo 3:5', 'Éxodo', 3, 5, '—No te acerques más —le dijo Dios—. Quítate las sandalias, porque estás pisando tierra santa.'),
('nvi', 'Éxodo 3:6', 'Éxodo', 3, 6, 'Yo soy el Dios de tu padre. Soy el Dios de Abraham, de Isaac y de Jacob. Al oír esto, Moisés se cubrió el rostro, pues tuvo miedo de mirar a Dios.'),
('nvi', 'Éxodo 3:7', 'Éxodo', 3, 7, 'Pero el SEÑOR siguió diciendo: —Ciertamente he visto la opresión que sufre mi pueblo en Egipto. Los he escuchado quejarse de sus capataces, y conozco bien sus penurias.'),
('nvi', 'Éxodo 3:8', 'Éxodo', 3, 8, 'Así que he descendido para librarlos del poder de los egipcios y sacarlos de ese país, para llevarlos a una tierra buena y espaciosa, tierra donde abundan la leche y la miel. Me refiero al país de los cananeos, hititas, amorreos, ferezeos, heveos y jebuseos.'),
('nvi', 'Éxodo 3:9', 'Éxodo', 3, 9, 'Han llegado a mis oídos los gritos desesperados de los israelitas, y he visto también cómo los oprimen los egipcios.'),
('nvi', 'Éxodo 3:10', 'Éxodo', 3, 10, 'Así que dispónte a partir. Voy a enviarte al faraón para que saques de Egipto a los israelitas, que son mi pueblo.'),
('nvi', 'Éxodo 3:11', 'Éxodo', 3, 11, 'Pero Moisés le dijo a Dios: —¿Y quién soy yo para presentarme ante el faraón y sacar de Egipto a los israelitas?'),
('nvi', 'Éxodo 3:12', 'Éxodo', 3, 12, '—Yo estaré contigo —le respondió Dios—. Y te voy a dar una señal de que soy yo quien te envía: Cuando hayas sacado de Egipto a mi pueblo, todos ustedes me rendirán culto en esta montaña.'),
('nvi', 'Éxodo 3:13', 'Éxodo', 3, 13, 'Pero Moisés insistió: —Supongamos que me presento ante los israelitas y les digo: “El Dios de sus antepasados me ha enviado a ustedes.”¿Qué les respondo si me preguntan: “¿Y cómo se llama?”'),
('nvi', 'Éxodo 3:14', 'Éxodo', 3, 14, '—Yo soy el que soy —respondió Dios a Moisés—. Y esto es lo que tienes que decirles a los israelitas: “Yo soy me ha enviado a ustedes.”'),
('nvi', 'Éxodo 3:15', 'Éxodo', 3, 15, 'Además, Dios le dijo a Moisés: —Diles esto a los israelitas: “El SEÑOR, el Dios de sus antepasados, el Dios de Abraham, de Isaac y de Jacob, me ha enviado a ustedes. Éste es mi nombre eterno; éste es mi nombre por todas las generaciones.”'),
('nvi', 'Éxodo 3:16', 'Éxodo', 3, 16, 'Y tú, anda y reúne a los ancianos de Israel, y diles: “El SEÑOR, el Dios de sus antepasados, el Dios de Abraham, de Isaac y de Jacob, se me apareció y me dijo: ‘Yo he estado pendiente de ustedes. He visto cómo los han maltratado en Egipto.'),
('nvi', 'Éxodo 3:17', 'Éxodo', 3, 17, 'Por eso me propongo sacarlos de su opresión en Egipto y llevarlos al país de los cananeos, hititas, amorreos, ferezeos, heveos y jebuseos. ¡Es una tierra donde abundan la leche y la miel!’ ”'),
('nvi', 'Éxodo 3:18', 'Éxodo', 3, 18, 'Los ancianos de Israel te harán caso. Entonces ellos y tú se presentarán ante el rey de Egipto y le dirán: “El SEÑOR, Dios de los hebreos, ha venido a nuestro encuentro. Déjanos hacer un viaje de tres días al desierto, para ofrecerle sacrificios al SEÑOR nuestro Dios.”'),
('nvi', 'Éxodo 3:19', 'Éxodo', 3, 19, 'Yo sé bien que el rey de Egipto no va a dejarlos ir, a no ser por la fuerza.'),
('nvi', 'Éxodo 3:20', 'Éxodo', 3, 20, 'Entonces manifestaré mi poder y heriré de muerte a los egipcios con todas las maravillas que realizaré entre ellos. Después de eso el faraón los dejará ir.'),
('nvi', 'Éxodo 3:21', 'Éxodo', 3, 21, 'Pero yo haré que este pueblo se gane la simpatía de los egipcios, de modo que cuando ustedes salgan de Egipto no se vayan con las manos vacías.'),
('nvi', 'Éxodo 3:22', 'Éxodo', 3, 22, 'Toda mujer israelita le pedirá a su vecina, y a cualquier otra mujer que viva en su casa, objetos de oro y de plata, y ropa para vestir a sus hijos y a sus hijas. Así despojarán ustedes a los egipcios.'),
('nvi', 'Éxodo 4:1', 'Éxodo', 4, 1, 'Moisés volvió a preguntar: —¿Y qué hago si no me creen ni me hacen caso? ¿Qué hago si me dicen: “El SEÑOR no se te ha aparecido”?'),
('nvi', 'Éxodo 4:2', 'Éxodo', 4, 2, '—¿Qué tienes en la mano? —preguntó el SEÑOR. —Una vara —respondió Moisés.'),
('nvi', 'Éxodo 4:3', 'Éxodo', 4, 3, '—Déjala caer al suelo —ordenó el SEÑOR. Moisés la dejó caer al suelo, y la vara se convirtió en una serpiente. Moisés trató de huir de ella,'),
('nvi', 'Éxodo 4:4', 'Éxodo', 4, 4, 'pero el SEÑOR le mandó que la agarrara por la cola. En cuanto Moisés agarró la serpiente, ésta se convirtió en una vara en sus propias manos.'),
('nvi', 'Éxodo 4:5', 'Éxodo', 4, 5, '—Esto es para que crean que yo el SEÑOR, el Dios de sus padres, Dios de Abraham, de Isaac y de Jacob, me he aparecido a ti.'),
('nvi', 'Éxodo 4:6', 'Éxodo', 4, 6, 'Y ahora —ordenó el SEÑOR—, ¡llévate la mano al pecho! Moisés se llevó la mano al pecho y, cuando la sacó, la tenía toda cubierta de lepra y blanca como la nieve.'),
('nvi', 'Éxodo 4:7', 'Éxodo', 4, 7, '—¡Llévatela otra vez al pecho! —insistió el Señor. Moisés se llevó de nuevo la mano al pecho y, cuando la sacó, la tenía tan sana como el resto de su cuerpo.'),
('nvi', 'Éxodo 4:8', 'Éxodo', 4, 8, '—Si con la primera señal milagrosa no te creen ni te hacen caso —dijo el SEÑOR—, tal vez te crean con la segunda.'),
('nvi', 'Éxodo 4:9', 'Éxodo', 4, 9, 'Pero si no te creen ni te hacen caso después de estas dos señales, toma agua del Nilo y derrámala en el suelo. En cuanto el agua del río toque el suelo, se convertirá en sangre.'),
('nvi', 'Éxodo 4:10', 'Éxodo', 4, 10, '—SEÑOR, yo nunca me he distinguido por mi facilidad de palabra —objetó Moisés—. Y esto no es algo que haya comenzado ayer ni anteayer, ni hoy que te diriges a este servidor tuyo. Francamente, me cuesta mucho trabajo hablar.'),
('nvi', 'Éxodo 4:11', 'Éxodo', 4, 11, '—¿Y quién le puso la boca al hombre? —le respondió el SEÑOR—. ¿Acaso no soy yo, el SEÑOR, quien lo hace sordo o mudo, quien le da la vista o se la quita?'),
('nvi', 'Éxodo 4:12', 'Éxodo', 4, 12, 'Anda, ponte en marcha, que yo te ayudaré a hablar y te diré lo que debas decir.'),
('nvi', 'Éxodo 4:13', 'Éxodo', 4, 13, '—SEÑOR—insistió Moisés—, te ruego que envíes a alguna otra persona.'),
('nvi', 'Éxodo 4:14', 'Éxodo', 4, 14, 'Entonces el SEÑOR ardió en ira contra Moisés y le dijo: —¿Y qué hay de tu hermano Aarón, el levita? Yo sé que él es muy elocuente. Además, ya ha salido a tu encuentro, y cuando te vea se le alegrará el corazón.'),
('nvi', 'Éxodo 4:15', 'Éxodo', 4, 15, 'Tú hablarás con él y le pondrás las palabras en la boca; yo los ayudaré a hablar, a ti y a él, y les enseñaré lo que tienen que hacer.'),
('nvi', 'Éxodo 4:16', 'Éxodo', 4, 16, 'Él hablará por ti al pueblo, como si tú mismo le hablaras, y tú le hablarás a él por mí, como si le hablara yo mismo.'),
('nvi', 'Éxodo 4:17', 'Éxodo', 4, 17, 'Pero no te olvides de llevar contigo esta vara, porque con ella harás señales milagrosas.'),
('nvi', 'Éxodo 4:18', 'Éxodo', 4, 18, 'Moisés se fue de allí y volvió a la casa de Jetro, su suegro. Al llegar le dijo: —Debo marcharme. Quiero volver a Egipto, donde están mis hermanos de sangre. Voy a ver si todavía viven. —Anda, pues; que te vaya bien —le contestó Jetro.'),
('nvi', 'Éxodo 4:19', 'Éxodo', 4, 19, 'Ya en Madián el SEÑOR le había dicho a Moisés: «Vuelve a Egipto, que ya han muerto todos los que querían matarte.»'),
('nvi', 'Éxodo 4:20', 'Éxodo', 4, 20, 'Así que Moisés tomó a su mujer y a sus hijos, los montó en un asno y volvió a Egipto. En la mano llevaba la vara de Dios.'),
('nvi', 'Éxodo 4:21', 'Éxodo', 4, 21, 'El SEÑOR le había advertido a Moisés: «Cuando vuelvas a Egipto, no dejes de hacer ante el faraón todos los prodigios que te he dado el poder de realizar. Yo, por mi parte, endureceré su corazón para que no deje ir al pueblo.'),
('nvi', 'Éxodo 4:22', 'Éxodo', 4, 22, 'Entonces tú le dirás de mi parte al faraón: “Israel es mi primogénito.'),
('nvi', 'Éxodo 4:23', 'Éxodo', 4, 23, 'Ya te he dicho que dejes ir a mi hijo para que me rinda culto, pero tú no has querido dejarlo ir. Por lo tanto, voy a quitarle la vida a tu primogénito.”»'),
('nvi', 'Éxodo 4:24', 'Éxodo', 4, 24, 'Ya en el camino, el SEÑOR salió al encuentro de Moisés en una posada y estuvo a punto de matarlo.'),
('nvi', 'Éxodo 4:25', 'Éxodo', 4, 25, 'Pero Séfora, tomando un cuchillo de pedernal, le cortó el prepucio a su hijo; luego tocó los pies de Moisés con el prepucio y le dijo: «No hay duda. Tú eres para mí un esposo de sangre.»'),
('nvi', 'Éxodo 4:26', 'Éxodo', 4, 26, 'Después de eso, el SEÑOR se apartó de Moisés. Pero Séfora había llamado a Moisés «esposo de sangre» por causa de la circuncisión.'),
('nvi', 'Éxodo 4:27', 'Éxodo', 4, 27, 'El SEÑOR le dijo a Aarón: «Anda a recibir a Moisés en el desierto.» Aarón fue y se encontró con Moisés en la montaña de Dios, y lo besó.'),
('nvi', 'Éxodo 4:28', 'Éxodo', 4, 28, 'Entonces Moisés le comunicó a Aarón todo lo que el SEÑOR le había ordenado decir y todas las señales milagrosas que le mandaba realizar.'),
('nvi', 'Éxodo 4:29', 'Éxodo', 4, 29, 'Luego Moisés y Aarón reunieron a todos los ancianos israelitas,'),
('nvi', 'Éxodo 4:30', 'Éxodo', 4, 30, 'y Aarón, además de repetirles todo lo que el SEÑOR le había dicho a Moisés, realizó también las señales a la vista del pueblo,'),
('nvi', 'Éxodo 4:31', 'Éxodo', 4, 31, 'con lo que el pueblo creyó. Y al oír que el SEÑOR había estado pendiente de ellos y había visto su aflicción, los israelitas se inclinaron y adoraron al SEÑOR.'),
('nvi', 'Éxodo 5:1', 'Éxodo', 5, 1, 'Después de eso, Moisés y Aarón se presentaron ante el faraón y le dijeron: —Así dice el SEÑOR, Dios de Israel: “Deja ir a mi pueblo para que celebre en el desierto una fiesta en mi honor.”'),
('nvi', 'Éxodo 5:2', 'Éxodo', 5, 2, '—¿Y quién es el SEÑOR—respondió el faraón—para que yo le obedezca y deje ir a Israel? ¡Ni conozco al SEÑOR, ni voy a dejar que Israel se vaya!'),
('nvi', 'Éxodo 5:3', 'Éxodo', 5, 3, '—El Dios de los hebreos nos ha salido al encuentro —contestaron—. Así que debemos hacer un viaje de tres días, hasta el desierto, para ofrecer sacrificios al SEÑOR nuestro Dios. De lo contrario, podría castigarnos con plagas o matarnos a filo de espada.'),
('nvi', 'Éxodo 5:4', 'Éxodo', 5, 4, '—Moisés y Aarón —replicó el rey de Egipto—, ¿por qué distraen al pueblo de sus quehaceres? ¡Vuelvan a sus obligaciones!'),
('nvi', 'Éxodo 5:5', 'Éxodo', 5, 5, 'Dense cuenta de que es mucha la gente de este país, y ustedes no la dejan trabajar.'),
('nvi', 'Éxodo 5:6', 'Éxodo', 5, 6, 'Ese mismo día el faraón les ordenó a los capataces y a los jefes de cuadrilla:'),
('nvi', 'Éxodo 5:7', 'Éxodo', 5, 7, '«Ya no le den paja a la gente para hacer ladrillos. ¡Que vayan ellos mismos a recogerla!'),
('nvi', 'Éxodo 5:8', 'Éxodo', 5, 8, 'Pero sigan exigiéndoles la misma cantidad de ladrillos que han estado haciendo. ¡No les reduzcan la cuota! Son unos holgazanes, y por eso me ruegan: “Déjanos ir a ofrecerle sacrificios a nuestro Dios.”'),
('nvi', 'Éxodo 5:9', 'Éxodo', 5, 9, 'Impónganles tareas más pesadas. Manténganlos ocupados. Así no harán caso de mentiras.»'),
('nvi', 'Éxodo 5:10', 'Éxodo', 5, 10, 'Los capataces y los jefes de cuadrilla salieron de allí y fueron a decirle al pueblo: «Así dice el faraón: “Ya no voy a darles paja.'),
('nvi', 'Éxodo 5:11', 'Éxodo', 5, 11, 'Vayan ustedes mismos a recogerla donde la encuentren. Pero eso sí, ¡en nada se les rebajará la tarea!”»'),
('nvi', 'Éxodo 5:12', 'Éxodo', 5, 12, 'Fue así como el pueblo se esparció por todo Egipto para recoger rastrojo y usarlo en lugar de paja.'),
('nvi', 'Éxodo 5:13', 'Éxodo', 5, 13, 'Los capataces no dejaban de apremiarlos y decirles: «Cumplan con su tarea diaria, como cuando se les daba paja.»'),
('nvi', 'Éxodo 5:14', 'Éxodo', 5, 14, 'Además, esos mismos capataces del faraón golpeaban a los jefes de cuadrilla israelitas que ellos mismos habían nombrado, y les preguntaban: «¿Por qué ni ayer ni hoy cumplieron con su cuota de ladrillos, como antes lo hacían?»'),
('nvi', 'Éxodo 5:15', 'Éxodo', 5, 15, 'Los jefes de cuadrilla israelitas fueron entonces a quejarse ante el faraón. Le dijeron: —¿Por qué Su Majestad trata así a sus siervos?'),
('nvi', 'Éxodo 5:16', 'Éxodo', 5, 16, '¡Ya ni paja recibimos! A pesar de eso, ¡se nos exige hacer ladrillos y, como si fuera poco, se nos golpea! ¡La gente de Su Majestad no está actuando bien!'),
('nvi', 'Éxodo 5:17', 'Éxodo', 5, 17, '—¡Haraganes, haraganes! —exclamó el faraón—. ¡Eso es lo que son! Por eso andan diciendo: “Déjanos ir a ofrecerle sacrificios al SEÑOR.”'),
('nvi', 'Éxodo 5:18', 'Éxodo', 5, 18, 'Ahora, ¡vayan a trabajar! No se les va a dar paja, pero tienen que entregar su cuota de ladrillos.'),
('nvi', 'Éxodo 5:19', 'Éxodo', 5, 19, 'Los jefes de cuadrilla israelitas se dieron cuenta de que estaban en un aprieto cuando se les dijo que la cuota diaria de ladrillos no se les iba a rebajar.'),
('nvi', 'Éxodo 5:20', 'Éxodo', 5, 20, 'Así que al encontrarse con Moisés y Aarón, que los estaban esperando a la salida,'),
('nvi', 'Éxodo 5:21', 'Éxodo', 5, 21, 'les dijeron: «¡Que el SEÑOR los examine y los juzgue! ¡Por culpa de ustedes somos unos apestados ante el faraón y sus siervos! ¡Ustedes mismos les han puesto la espada en la mano, para que nos maten!»'),
('nvi', 'Éxodo 5:22', 'Éxodo', 5, 22, 'Moisés se volvió al SEÑOR y le dijo: —¡Ay, SEÑOR! ¿Por qué tratas tan mal a este pueblo? ¿Para esto me enviaste?'),
('nvi', 'Éxodo 5:23', 'Éxodo', 5, 23, 'Desde que me presenté ante el faraón y le hablé en tu nombre, no ha hecho más que maltratar a este pueblo, que es tu pueblo. ¡Y tú no has hecho nada para librarlo!'),
('nvi', 'Éxodo 6:1', 'Éxodo', 6, 1, 'El SEÑOR le respondió: —Ahora verás lo que voy a hacer con el faraón. Realmente, sólo por mi mano poderosa va a dejar que se vayan; sólo por mi mano poderosa va a echarlos de su país.'),
('nvi', 'Éxodo 6:2', 'Éxodo', 6, 2, 'En otra ocasión, Dios habló con Moisés y le dijo: «Yo soy el SEÑOR.'),
('nvi', 'Éxodo 6:3', 'Éxodo', 6, 3, 'Me aparecí a Abraham, a Isaac y a Jacob bajo el nombre de Dios Todopoderoso, pero no les revelé mi verdadero nombre, que es el SEÑOR.'),
('nvi', 'Éxodo 6:4', 'Éxodo', 6, 4, 'También con ellos confirmé mi pacto de darles la tierra de Canaán, donde residieron como forasteros.'),
('nvi', 'Éxodo 6:5', 'Éxodo', 6, 5, 'He oído además el gemir de los israelitas, a quienes los egipcios han esclavizado, y he recordado mi pacto.'),
('nvi', 'Éxodo 6:6', 'Éxodo', 6, 6, 'Así que ve y diles a los israelitas: “Yo soy el SEÑOR, y voy a quitarles de encima la opresión de los egipcios. Voy a librarlos de su esclavitud; voy a liberarlos con gran despliegue de poder y con grandes actos de justicia.'),
('nvi', 'Éxodo 6:7', 'Éxodo', 6, 7, 'Haré de ustedes mi pueblo; y yo seré su Dios. Así sabrán que yo soy el SEÑOR su Dios, que los libró de la opresión de los egipcios.'),
('nvi', 'Éxodo 6:8', 'Éxodo', 6, 8, 'Y los llevaré a la tierra que bajo juramento prometí darles a Abraham, Isaac y Jacob. Yo, el SEÑOR, les daré a ustedes posesión de ella.”»'),
('nvi', 'Éxodo 6:9', 'Éxodo', 6, 9, 'Moisés les dio a conocer esto a los israelitas, pero por su desánimo y las penurias de su esclavitud ellos no le hicieron caso.'),
('nvi', 'Éxodo 6:10', 'Éxodo', 6, 10, 'Entonces el SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 6:11', 'Éxodo', 6, 11, '—Ve y habla con el faraón, el rey de Egipto. Dile que deje salir de su país a los israelitas.'),
('nvi', 'Éxodo 6:12', 'Éxodo', 6, 12, 'Pero Moisés se enfrentó al SEÑOR y le dijo: —¿Y cómo va a hacerme caso el faraón, si ni siquiera los israelitas me creen? Además, no tengo facilidad de palabra.'),
('nvi', 'Éxodo 6:13', 'Éxodo', 6, 13, 'En otra ocasión el SEÑOR habló con Moisés y Aarón acerca de los israelitas y del faraón, rey egipcio, y les ordenó sacar de Egipto a los israelitas.'),
('nvi', 'Éxodo 6:14', 'Éxodo', 6, 14, 'Éstos fueron los jefes de las familias patriarcales: Los hijos de Rubén, primogénito de Israel: Janoc, Falú, Jezrón y Carmí. Éstos fueron los clanes de Rubén.'),
('nvi', 'Éxodo 6:15', 'Éxodo', 6, 15, 'Los hijos de Simeón: Jemuel, Jamín, Oad, Jaquín, Zojar y Saúl, hijo de la cananea. Éstos fueron los clanes de Simeón.'),
('nvi', 'Éxodo 6:16', 'Éxodo', 6, 16, 'Según los registros familiares, éstos son los nombres de los hijos de Leví, quien vivió ciento treinta y siete años: Guersón, Coat y Merari.'),
('nvi', 'Éxodo 6:17', 'Éxodo', 6, 17, 'Los hijos de Guersón, según sus clanes: Libní y Simí.'),
('nvi', 'Éxodo 6:18', 'Éxodo', 6, 18, 'Los hijos de Coat, quien vivió ciento treinta y tres años: Amirán, Izar, Hebrón y Uziel.'),
('nvi', 'Éxodo 6:19', 'Éxodo', 6, 19, 'Los hijos de Merari: Majlí y Musí. Éstos fueron los clanes de Leví, según sus registros familiares.'),
('nvi', 'Éxodo 6:20', 'Éxodo', 6, 20, 'Amirán, que vivió ciento treinta y siete años, se casó con su tía Jocabed, la cual le dio dos hijos, Aarón y Moisés.'),
('nvi', 'Éxodo 6:21', 'Éxodo', 6, 21, 'Los hijos de Izar: Coré, Néfeg y Zicrí.'),
('nvi', 'Éxodo 6:22', 'Éxodo', 6, 22, 'Los hijos de Uziel: Misael, Elzafán y Sitri.'),
('nvi', 'Éxodo 6:23', 'Éxodo', 6, 23, 'Aarón se casó con Elisabet, hija de Aminadab y hermana de Naasón, y ella le dio cuatro hijos: Nadab, Abiú, Eleazar e Itamar.'),
('nvi', 'Éxodo 6:24', 'Éxodo', 6, 24, 'Los hijos de Coré: Asir, Elcaná y Abiasaf. Éstos fueron los clanes de Coré.'),
('nvi', 'Éxodo 6:25', 'Éxodo', 6, 25, 'Eleazar hijo de Aarón se casó con una de las hijas de Futiel, la cual le dio un hijo, Finés. Éstos fueron los jefes de los clanes levitas, en orden de familias.'),
('nvi', 'Éxodo 6:26', 'Éxodo', 6, 26, 'Aarón y Moisés son los mismos a quienes el SEÑOR mandó que sacaran de Egipto a los israelitas, ordenados en escuadrones.'),
('nvi', 'Éxodo 6:27', 'Éxodo', 6, 27, 'Son ellos quienes hablaron con el faraón, rey egipcio, en cuanto a sacar de Egipto a los israelitas.'),
('nvi', 'Éxodo 6:28', 'Éxodo', 6, 28, 'Cuando el SEÑOR habló con Moisés en Egipto,'),
('nvi', 'Éxodo 6:29', 'Éxodo', 6, 29, 'le dijo: —Yo soy el SEÑOR. Habla con el faraón, rey de Egipto, y comunícale todo lo que yo te diga.'),
('nvi', 'Éxodo 6:30', 'Éxodo', 6, 30, 'Pero Moisés se enfrentó al SEÑOR y le dijo: —¿Y cómo va a hacerme caso el faraón, si yo no tengo facilidad de palabra?'),
('nvi', 'Éxodo 7:1', 'Éxodo', 7, 1, '—Toma en cuenta —le dijo el SEÑOR a Moisés—que te pongo por Dios ante el faraón. Tu hermano Aarón será tu profeta.'),
('nvi', 'Éxodo 7:2', 'Éxodo', 7, 2, 'Tu obligación es decir todo lo que yo te ordene que digas; tu hermano Aarón, por su parte, le pedirá al faraón que deje salir de su país a los israelitas.'),
('nvi', 'Éxodo 7:3', 'Éxodo', 7, 3, 'Yo voy a endurecer el corazón del faraón, y aunque haré muchas señales milagrosas y prodigios en Egipto,'),
('nvi', 'Éxodo 7:4', 'Éxodo', 7, 4, 'él no les hará caso. Entonces descargaré mi poder sobre Egipto; ¡con grandes actos de justicia sacaré de allí a los escuadrones de mi pueblo, los israelitas!'),
('nvi', 'Éxodo 7:5', 'Éxodo', 7, 5, 'Y cuando yo despliegue mi poder contra Egipto y saque de allí a los israelitas, sabrán los egipcios que yo soy el SEÑOR.'),
('nvi', 'Éxodo 7:6', 'Éxodo', 7, 6, 'Moisés y Aarón cumplieron al pie de la letra las órdenes del SEÑOR.'),
('nvi', 'Éxodo 7:7', 'Éxodo', 7, 7, 'Cuando hablaron con el faraón, Moisés tenía ochenta años y Aarón ochenta y tres.'),
('nvi', 'Éxodo 7:8', 'Éxodo', 7, 8, 'El SEÑOR les dijo a Moisés y a Aarón:'),
('nvi', 'Éxodo 7:9', 'Éxodo', 7, 9, '«Cuando el faraón les pida que hagan un milagro, le dirás a Aarón que tome la vara y la arroje al suelo ante el faraón. Así la vara se convertirá en serpiente.»'),
('nvi', 'Éxodo 7:10', 'Éxodo', 7, 10, 'Moisés y Aarón fueron a ver al faraón y cumplieron las órdenes del SEÑOR. Aarón arrojó su vara al suelo ante el faraón y sus funcionarios, y la vara se convirtió en serpiente.'),
('nvi', 'Éxodo 7:11', 'Éxodo', 7, 11, 'Pero el faraón llamó a los sabios y hechiceros y, mediante sus artes secretas, también los magos egipcios hicieron lo mismo:'),
('nvi', 'Éxodo 7:12', 'Éxodo', 7, 12, 'Cada uno de ellos arrojó su vara al suelo, y cada vara se convirtió en una serpiente. Sin embargo, la vara de Aarón se tragó las varas de todos ellos.'),
('nvi', 'Éxodo 7:13', 'Éxodo', 7, 13, 'A pesar de esto, y tal como lo había advertido el SEÑOR, el faraón endureció su corazón y no les hizo caso.'),
('nvi', 'Éxodo 7:14', 'Éxodo', 7, 14, 'El SEÑOR le dijo a Moisés: «El corazón del faraón se ha obstinado, y se niega a dejar salir al pueblo.'),
('nvi', 'Éxodo 7:15', 'Éxodo', 7, 15, 'Anda a verlo por la mañana, cuando salga a bañarse. Espéralo a orillas del río Nilo, y sal luego a su encuentro. No dejes de llevar la vara que se convirtió en serpiente.'),
('nvi', 'Éxodo 7:16', 'Éxodo', 7, 16, 'Dile allí: “El SEÑOR, Dios de los hebreos, me ha enviado a decirte: ‘¡Deja ir a mi pueblo para que me rinda culto en el desierto!’Como no has querido obedecer,'),
('nvi', 'Éxodo 7:17', 'Éxodo', 7, 17, 'el SEÑOR dice: ‘¡Ahora vas a saber que yo soy el SEÑOR!’Con esta vara que llevo en la mano voy a golpear las aguas del Nilo, y el río se convertirá en sangre.'),
('nvi', 'Éxodo 7:18', 'Éxodo', 7, 18, 'Morirán los peces que hay en el río, y el río apestará y los egipcios no podrán beber agua de allí.”»'),
('nvi', 'Éxodo 7:19', 'Éxodo', 7, 19, 'Dijo también el SEÑOR a Moisés: «Dile a Aarón que tome su vara y extienda el brazo sobre las aguas de Egipto, para que se conviertan en sangre sus arroyos y canales, y sus lagunas y depósitos de agua. Habrá sangre por todo el territorio de Egipto, ¡hasta en las vasijas de madera y de piedra!»'),
('nvi', 'Éxodo 7:20', 'Éxodo', 7, 20, 'Moisés y Aarón cumplieron las órdenes del SEÑOR. En presencia del faraón y de sus funcionarios, Aarón levantó su vara y golpeó las aguas del Nilo. ¡Y toda el agua del río se convirtió en sangre!'),
('nvi', 'Éxodo 7:21', 'Éxodo', 7, 21, 'Murieron los peces que había en el Nilo, y tan mal olía el río que los egipcios no podían beber agua de allí. Por todo Egipto se veía sangre.'),
('nvi', 'Éxodo 7:22', 'Éxodo', 7, 22, 'Sin embargo, mediante sus artes secretas los magos egipcios hicieron lo mismo, de modo que el faraón endureció su corazón y, tal como el SEÑOR lo había advertido, no les hizo caso ni a Aarón ni a Moisés.'),
('nvi', 'Éxodo 7:23', 'Éxodo', 7, 23, 'Como si nada hubiera pasado, se dio media vuelta y regresó a su palacio.'),
('nvi', 'Éxodo 7:24', 'Éxodo', 7, 24, 'Mientras tanto, todos los egipcios hacían pozos a la orilla del Nilo en busca de agua potable, porque no podían beber el agua del río.'),
('nvi', 'Éxodo 7:25', 'Éxodo', 7, 25, 'Siete días pasaron después de que el SEÑOR golpeó el Nilo.'),
('nvi', 'Éxodo 8:1', 'Éxodo', 8, 1, 'El SEÑOR le ordenó a Moisés: «Ve a advertirle al faraón que así dice el SEÑOR: “Deja ir a mi pueblo para que me rinda culto.'),
('nvi', 'Éxodo 8:2', 'Éxodo', 8, 2, 'Si no los dejas ir, infestaré de ranas todo tu país.'),
('nvi', 'Éxodo 8:3', 'Éxodo', 8, 3, 'El Nilo hervirá de ranas, y se meterán en tu palacio, y hasta en tu alcoba y en tu cama, y en las casas de tus funcionarios y de tu pueblo, y en tus hornos y artesas.'),
('nvi', 'Éxodo 8:4', 'Éxodo', 8, 4, 'Se treparán sobre ti, sobre tu pueblo y sobre tus funcionarios.”»'),
('nvi', 'Éxodo 8:5', 'Éxodo', 8, 5, 'Luego el SEÑOR le dijo a Moisés: «Dile a Aarón que extienda su vara sobre ríos, arroyos y lagunas, para que todo Egipto se llene de ranas.»'),
('nvi', 'Éxodo 8:6', 'Éxodo', 8, 6, 'Aarón extendió su brazo sobre las aguas de Egipto, y las ranas llegaron a cubrir todo el país.'),
('nvi', 'Éxodo 8:7', 'Éxodo', 8, 7, 'Pero, mediante sus artes secretas, los magos hicieron lo mismo, de modo que hicieron venir ranas sobre todo Egipto.'),
('nvi', 'Éxodo 8:8', 'Éxodo', 8, 8, 'Entonces el faraón mandó llamar a Moisés y a Aarón, y les dijo: —Ruéguenle al SEÑOR que aleje las ranas de mí y de mi pueblo, y yo dejaré ir al pueblo para que le ofrezca sacrificios.'),
('nvi', 'Éxodo 8:9', 'Éxodo', 8, 9, 'Moisés le respondió: —Dime cuándo quieres que ruegue al SEÑOR por ti, por tus funcionarios y por tu pueblo. Las ranas se quedarán sólo en el Nilo, y tú y tus casas se librarán de ellas.'),
('nvi', 'Éxodo 8:10', 'Éxodo', 8, 10, '—Mañana mismo —contestó el faraón. —Así se hará —respondió Moisés—, y sabrás que no hay dios como el SEÑOR, nuestro Dios.'),
('nvi', 'Éxodo 8:11', 'Éxodo', 8, 11, 'Las ranas se apartarán de ti y de tus casas, de tus funcionarios y de tu pueblo, y se quedarán únicamente en el Nilo.'),
('nvi', 'Éxodo 8:12', 'Éxodo', 8, 12, 'Tan pronto como salieron Moisés y Aarón de hablar con el faraón, Moisés clamó al SEÑOR en cuanto a las ranas que había mandado sobre el faraón.'),
('nvi', 'Éxodo 8:13', 'Éxodo', 8, 13, 'El SEÑOR atendió a los ruegos de Moisés, y las ranas comenzaron a morirse en las casas, en los patios y en los campos.'),
('nvi', 'Éxodo 8:14', 'Éxodo', 8, 14, 'La gente las recogía y las amontonaba, y el hedor de las ranas llenaba el país.'),
('nvi', 'Éxodo 8:15', 'Éxodo', 8, 15, 'Pero en cuanto el faraón experimentó alivio, endureció su corazón y, tal como el SEÑOR lo había advertido, ya no quiso saber nada de Moisés ni de Aarón.'),
('nvi', 'Éxodo 8:16', 'Éxodo', 8, 16, 'El SEÑOR le ordenó a Moisés que le dijera a Aarón: «Extiende tu vara y golpea el suelo, para que en todo Egipto el polvo se convierta en mosquitos.»'),
('nvi', 'Éxodo 8:17', 'Éxodo', 8, 17, 'Así lo hizo. Y Aarón extendió su brazo, golpeó el suelo con la vara, y del polvo salieron mosquitos que picaban a hombres y animales. En todo Egipto el polvo se convirtió en mosquitos.'),
('nvi', 'Éxodo 8:18', 'Éxodo', 8, 18, 'Los magos, recurriendo a sus artes secretas, trataron también de producir mosquitos, pero no pudieron. Mientras tanto, los mosquitos picaban a hombres y animales.'),
('nvi', 'Éxodo 8:19', 'Éxodo', 8, 19, '«En todo esto anda la mano de Dios», admitieron los magos ante el faraón, pero éste había endurecido su corazón, así que no les hizo caso, tal como el SEÑOR lo había advertido.'),
('nvi', 'Éxodo 8:20', 'Éxodo', 8, 20, 'El SEÑOR le dijo a Moisés: «Mañana vas a madrugar. Le saldrás al paso al faraón cuando baje al río, y le advertirás: “Así dice el SEÑOR: ‘Deja ir a mi pueblo para que me rinda culto.'),
('nvi', 'Éxodo 8:21', 'Éxodo', 8, 21, 'Si no lo dejas ir, enviaré enjambres de tábanos sobre ti y sobre tus funcionarios, sobre tu pueblo y sobre tus casas. Todas las casas egipcias, y aun el suelo que pisan, se llenarán de tábanos.'),
('nvi', 'Éxodo 8:22', 'Éxodo', 8, 22, 'Cuando eso suceda, la única región donde no habrá tábanos será la de Gosén, porque allí vive mi pueblo. Así sabrás que yo, el SEÑOR, estoy en este país.'),
('nvi', 'Éxodo 8:23', 'Éxodo', 8, 23, 'Haré distinción entre mi pueblo y tu pueblo. Esta señal milagrosa tendrá lugar mañana.’ ”»'),
('nvi', 'Éxodo 8:24', 'Éxodo', 8, 24, 'Y así lo hizo el SEÑOR. Densas nubes de tábanos irrumpieron en el palacio del faraón y en las casas de sus funcionarios, y por todo Egipto. Por causa de los tábanos, el país quedó arruinado.'),
('nvi', 'Éxodo 8:25', 'Éxodo', 8, 25, 'Llamó entonces el faraón a Moisés y a Aarón, y les dijo: —Vayan y ofrezcan sacrificios a su Dios aquí en el país.'),
('nvi', 'Éxodo 8:26', 'Éxodo', 8, 26, '—No estaría bien hacerlo así —contestó Moisés—, porque los sacrificios que ofrecemos al SEÑOR nuestro Dios resultan ofensivos para los egipcios. Si a la vista de ellos ofrecemos sacrificios que les son ofensivos, seguramente nos apedrearán.'),
('nvi', 'Éxodo 8:27', 'Éxodo', 8, 27, 'Tenemos que hacer un viaje de tres días, hasta el desierto, para ofrecerle sacrificios al SEÑOR nuestro Dios, pues así nos lo ha ordenado.'),
('nvi', 'Éxodo 8:28', 'Éxodo', 8, 28, 'El faraón respondió: —Voy a dejarlos ir para que ofrezcan sacrificios al SEÑOR su Dios en el desierto, con tal de que no se vayan muy lejos y de que rueguen a Dios por mí.'),
('nvi', 'Éxodo 8:29', 'Éxodo', 8, 29, '—En cuanto salga yo de aquí —le aseguró Moisés al faraón—, rogaré por ti al SEÑOR, y de aquí a mañana los tábanos se habrán apartado de ti, de tus funcionarios y de tu pueblo. Pero tú no debes seguir engañándonos ni impidiendo que el pueblo vaya a ofrecerle sacrificios al SEÑOR.'),
('nvi', 'Éxodo 8:30', 'Éxodo', 8, 30, 'Así que Moisés salió y le rogó al SEÑOR por el faraón.'),
('nvi', 'Éxodo 8:31', 'Éxodo', 8, 31, 'El SEÑOR accedió a los ruegos de Moisés y apartó los tábanos del faraón, de sus funcionarios y de su pueblo. No quedó un sólo tábano.'),
('nvi', 'Éxodo 8:32', 'Éxodo', 8, 32, 'Pero una vez más el faraón endureció su corazón y no dejó que el pueblo se fuera.'),
('nvi', 'Éxodo 9:1', 'Éxodo', 9, 1, 'El SEÑOR le ordenó a Moisés que fuera a hablar con el faraón y le advirtiera: «Así dice el SEÑOR, Dios de los hebreos: “Deja ir a mi pueblo para que me rinda culto.”'),
('nvi', 'Éxodo 9:2', 'Éxodo', 9, 2, 'Si te niegas a dejarlos ir y sigues reteniéndolos,'),
('nvi', 'Éxodo 9:3', 'Éxodo', 9, 3, 'la mano del SEÑOR provocará una terrible plaga entre los ganados que tienes en el campo, y entre tus caballos, asnos, camellos, vacas y ovejas.'),
('nvi', 'Éxodo 9:4', 'Éxodo', 9, 4, 'Pero el SEÑOR hará distinción entre el ganado de Israel y el de Egipto, de modo que no morirá un solo animal que pertenezca a los israelitas.»'),
('nvi', 'Éxodo 9:5', 'Éxodo', 9, 5, 'Además, el SEÑOR fijó un plazo y dijo: «Mañana yo, el SEÑOR, haré esto en el país.»'),
('nvi', 'Éxodo 9:6', 'Éxodo', 9, 6, 'En efecto, al día siguiente murió todo el ganado de los egipcios, pero del ganado de los israelitas no murió ni un solo animal.'),
('nvi', 'Éxodo 9:7', 'Éxodo', 9, 7, 'Envió el faraón gente a ver los ganados de los israelitas, y se encontraron con que ni un solo animal había muerto. Sin embargo, el faraón endureció su corazón y no quiso dejar ir al pueblo.'),
('nvi', 'Éxodo 9:8', 'Éxodo', 9, 8, 'Entonces el SEÑOR les dijo a Moisés y a Aarón: «Tomen de algún horno puñados de ceniza, y que la arroje Moisés al aire en presencia del faraón.'),
('nvi', 'Éxodo 9:9', 'Éxodo', 9, 9, 'La ceniza se convertirá en polvo fino, y caerá sobre todo Egipto y abrirá úlceras en personas y animales en todo el país.»'),
('nvi', 'Éxodo 9:10', 'Éxodo', 9, 10, 'Moisés y Aarón tomaron ceniza de un horno y se plantaron ante el faraón. Allí Moisés la arrojó al aire, y se abrieron úlceras purulentas en personas y animales.'),
('nvi', 'Éxodo 9:11', 'Éxodo', 9, 11, 'Los magos no pudieron enfrentarse a Moisés, pues ellos y todos los egipcios tenían úlceras.'),
('nvi', 'Éxodo 9:12', 'Éxodo', 9, 12, 'Pero el SEÑOR endureció el corazón del faraón y, tal como el SEÑOR se lo había advertido a Moisés, no quiso el faraón saber nada de Moisés ni de Aarón.'),
('nvi', 'Éxodo 9:13', 'Éxodo', 9, 13, 'El SEÑOR le ordenó a Moisés madrugar al día siguiente, y salirle al paso al faraón para advertirle: «Así dice el SEÑOR y Dios de los hebreos: “Deja ir a mi pueblo para que me rinda culto.'),
('nvi', 'Éxodo 9:14', 'Éxodo', 9, 14, 'Porque esta vez voy a enviar el grueso de mis plagas contra ti, y contra tus funcionarios y tu pueblo, para que sepas que no hay en toda la tierra nadie como yo.'),
('nvi', 'Éxodo 9:15', 'Éxodo', 9, 15, 'Si en este momento desplegara yo mi poder, y a ti y a tu pueblo los azotara con una plaga, desaparecerían de la tierra.'),
('nvi', 'Éxodo 9:16', 'Éxodo', 9, 16, 'Pero te he dejado con vida precisamente para mostrarte mi poder, y para que mi nombre sea proclamado por toda la tierra.'),
('nvi', 'Éxodo 9:17', 'Éxodo', 9, 17, 'Tú, sin embargo, sigues enfrentándote a mi pueblo y no quieres dejarlo ir.'),
('nvi', 'Éxodo 9:18', 'Éxodo', 9, 18, 'Por eso mañana a esta hora enviaré la peor granizada que haya caído en Egipto desde su fundación.'),
('nvi', 'Éxodo 9:19', 'Éxodo', 9, 19, 'Ordena inmediatamente que se pongan bajo techo tus ganados y todo lo que tengas en el campo, lo mismo personas que animales, porque el granizo caerá sobre los que anden al aire libre y los matará.”»'),
('nvi', 'Éxodo 9:20', 'Éxodo', 9, 20, 'Algunos funcionarios del faraón temieron la palabra del SEÑOR y se apresuraron a poner bajo techo a sus esclavos y ganados,'),
('nvi', 'Éxodo 9:21', 'Éxodo', 9, 21, 'pero otros no hicieron caso de la palabra de Dios y dejaron en el campo a sus esclavos y ganados.'),
('nvi', 'Éxodo 9:22', 'Éxodo', 9, 22, 'Entonces el SEÑOR le dijo a Moisés: «Levanta los brazos al cielo, para que en todo Egipto caiga granizo sobre la gente y los animales, y sobre todo lo que crece en el campo.»'),
('nvi', 'Éxodo 9:23', 'Éxodo', 9, 23, 'Moisés levantó su vara hacia el cielo, y el SEÑOR hizo que cayera granizo sobre todo Egipto: envió truenos, granizo y rayos sobre toda la tierra.'),
('nvi', 'Éxodo 9:24', 'Éxodo', 9, 24, 'Llovió granizo, y con el granizo caían rayos zigzagueantes. Nunca en toda la historia de Egipto como nación hubo una tormenta peor que ésta.'),
('nvi', 'Éxodo 9:25', 'Éxodo', 9, 25, 'El granizo arrasó con todo lo que había en los campos de Egipto, y con personas y animales; acabó con todos los cultivos y derribó todos los árboles.'),
('nvi', 'Éxodo 9:26', 'Éxodo', 9, 26, 'El único lugar en donde no granizó fue en la tierra de Gosén, donde estaban los israelitas.'),
('nvi', 'Éxodo 9:27', 'Éxodo', 9, 27, 'Entonces el faraón mandó llamar a Moisés y a Aarón, y les dijo: —Esta vez reconozco mi pecado. El SEÑOR ha actuado con justicia, mientras que yo y mi pueblo hemos actuado mal.'),
('nvi', 'Éxodo 9:28', 'Éxodo', 9, 28, 'No voy a detenerlos más tiempo; voy a dejarlos ir. Pero rueguen por mí al SEÑOR, que truenos y granizo los hemos tenido de sobra.'),
('nvi', 'Éxodo 9:29', 'Éxodo', 9, 29, '—En cuanto yo salga de la ciudad —le contestó Moisés—, elevaré mis manos en oración al SEÑOR, y cesarán los truenos y dejará de granizar. Así sabrás que la tierra es del SEÑOR.'),
('nvi', 'Éxodo 9:30', 'Éxodo', 9, 30, 'Sin embargo, yo sé que tú y tus funcionarios aún no tienen temor de Dios.'),
('nvi', 'Éxodo 9:31', 'Éxodo', 9, 31, 'El lino y la cebada fueron destruidos, ya que la cebada estaba en espiga, y el lino en flor.'),
('nvi', 'Éxodo 9:32', 'Éxodo', 9, 32, 'Sin embargo, el trigo y la espelta no se echaron a perder porque maduran más tarde.'),
('nvi', 'Éxodo 9:33', 'Éxodo', 9, 33, 'Tan pronto como Moisés dejó al faraón y salió de la ciudad, elevó sus manos en oración al SEÑOR y, en seguida, cesaron los truenos y dejó de granizar y de llover sobre la tierra.'),
('nvi', 'Éxodo 9:34', 'Éxodo', 9, 34, 'Pero en cuanto vio el faraón que habían cesado la lluvia, el granizo y los truenos, reincidió en su pecado, y tanto él como sus funcionarios endurecieron su corazón.'),
('nvi', 'Éxodo 9:35', 'Éxodo', 9, 35, 'Tal como el SEÑOR lo había advertido por medio de Moisés, el faraón endureció su corazón y ya no dejó que los israelitas se fueran.'),
('nvi', 'Éxodo 10:1', 'Éxodo', 10, 1, 'El SEÑOR le dijo a Moisés: «Ve a hablar con el faraón. En realidad, soy yo quien ha endurecido su corazón y el de sus funcionarios, para realizar entre ellos mis señales milagrosas.'),
('nvi', 'Éxodo 10:2', 'Éxodo', 10, 2, 'Lo hice para que puedas contarles a tus hijos y a tus nietos la dureza con que traté a los egipcios, y las señales que realicé entre ellos. Así sabrán que yo soy el SEÑOR.»'),
('nvi', 'Éxodo 10:3', 'Éxodo', 10, 3, 'Moisés y Aarón se presentaron ante el faraón, y le advirtieron: «Así dice el SEÑOR y Dios de los hebreos: “¿Hasta cuándo te opondrás a humillarte en mi presencia? Deja ir a mi pueblo para que me rinda culto.'),
('nvi', 'Éxodo 10:4', 'Éxodo', 10, 4, 'Si te niegas a dejarlos ir, mañana mismo traeré langostas sobre tu país.'),
('nvi', 'Éxodo 10:5', 'Éxodo', 10, 5, 'De tal manera cubrirán la superficie de la tierra que no podrá verse el suelo. Se comerán lo poco que haya quedado después del granizo, y acabarán con todos los árboles que haya en los campos.'),
('nvi', 'Éxodo 10:6', 'Éxodo', 10, 6, 'Infestarán tus casas, y las de tus funcionarios y las de todos los egipcios. ¡Será algo que ni tus padres ni tus antepasados vieron jamás, desde el día en que se establecieron en este país hasta la fecha!”» Dicho esto, Moisés se dio media vuelta y se retiró de la presencia del faraón.'),
('nvi', 'Éxodo 10:7', 'Éxodo', 10, 7, 'Entonces los funcionarios le dijeron al faraón: —¿Hasta cuándo este individuo será una trampa para nosotros? ¡Deja que el pueblo se vaya y que rinda culto al SEÑOR su Dios! ¿Acaso no sabes que Egipto está arruinado?'),
('nvi', 'Éxodo 10:8', 'Éxodo', 10, 8, 'El faraón mandó llamar a Moisés y a Aarón, y les dijo: —Vayan y rindan culto al SEÑOR su Dios. Tan sólo díganme quiénes van a ir.'),
('nvi', 'Éxodo 10:9', 'Éxodo', 10, 9, '—Nos van a acompañar nuestros jóvenes y nuestros ancianos —respondió Moisés—. También nos acompañarán nuestros hijos y nuestras hijas, y nuestros rebaños y nuestros ganados, pues vamos a celebrar la fiesta del SEÑOR.'),
('nvi', 'Éxodo 10:10', 'Éxodo', 10, 10, '—Que el SEÑOR los acompañe —repuso el faraón—, ¡si es que yo dejo que se vayan con sus mujeres y sus hijos! ¡Claramente se ven sus malas intenciones!'),
('nvi', 'Éxodo 10:11', 'Éxodo', 10, 11, '¡Pero no será como ustedes quieren! Si lo que quieren es rendirle culto al SEÑOR, ¡vayan sólo ustedes los hombres! Y Moisés y Aarón fueron arrojados de la presencia del faraón.'),
('nvi', 'Éxodo 10:12', 'Éxodo', 10, 12, 'Entonces el SEÑOR le dijo a Moisés: «Extiende los brazos sobre todo Egipto, para que vengan langostas y cubran todo el país, y se coman todo lo que crece en los campos y todo lo que dejó el granizo.»'),
('nvi', 'Éxodo 10:13', 'Éxodo', 10, 13, 'Moisés extendió su vara sobre Egipto, y el SEÑOR hizo que todo ese día y toda esa noche un viento del este soplara sobre el país. A la mañana siguiente, el viento del este había traído las langostas,'),
('nvi', 'Éxodo 10:14', 'Éxodo', 10, 14, 'las cuales invadieron todo Egipto y se asentaron en gran número por todos los rincones del país. ¡Nunca antes hubo semejante plaga de langostas, ni la habrá después!'),
('nvi', 'Éxodo 10:15', 'Éxodo', 10, 15, 'Eran tantas las langostas que cubrían la superficie de la tierra, que ni el suelo podía verse. Se comieron todas las plantas del campo y todos los frutos de los árboles que dejó el granizo. En todo Egipto no quedó nada verde, ni en los árboles ni en las plantas.'),
('nvi', 'Éxodo 10:16', 'Éxodo', 10, 16, 'A toda prisa mandó llamar el faraón a Moisés y a Aarón, y admitió: «He pecado contra el SEÑOR su Dios y contra ustedes.'),
('nvi', 'Éxodo 10:17', 'Éxodo', 10, 17, 'Yo les pido que perdonen mi pecado una vez más, y que rueguen por mí al SEÑOR su Dios, para que por lo menos aleje de donde yo estoy esta plaga mortal.»'),
('nvi', 'Éxodo 10:18', 'Éxodo', 10, 18, 'En cuanto Moisés salió de la presencia del faraón, rogó al SEÑOR por el faraón.'),
('nvi', 'Éxodo 10:19', 'Éxodo', 10, 19, 'El SEÑOR hizo entonces que el viento cambiara, y que un fuerte viento del oeste se llevara las langostas y las echara al Mar Rojo. En todo Egipto no quedó una sola langosta.'),
('nvi', 'Éxodo 10:20', 'Éxodo', 10, 20, 'Pero el SEÑOR endureció el corazón del faraón, y éste no dejó que los israelitas se fueran.'),
('nvi', 'Éxodo 10:21', 'Éxodo', 10, 21, 'El SEÑOR le dijo a Moisés: «Levanta los brazos al cielo, para que todo Egipto se cubra de tinieblas, ¡tinieblas tan densas que se puedan palpar!»'),
('nvi', 'Éxodo 10:22', 'Éxodo', 10, 22, 'Moisés levantó los brazos al cielo, y durante tres días todo Egipto quedó envuelto en densas tinieblas.'),
('nvi', 'Éxodo 10:23', 'Éxodo', 10, 23, 'Durante ese tiempo los egipcios no podían verse unos a otros, ni moverse de su sitio. Sin embargo, en todos los hogares israelitas había luz.'),
('nvi', 'Éxodo 10:24', 'Éxodo', 10, 24, 'Entonces el faraón mandó llamar a Moisés y le dijo: —Vayan y rindan culto al SEÑOR. Llévense también a sus hijos, pero dejen atrás sus rebaños y sus ganados.'),
('nvi', 'Éxodo 10:25', 'Éxodo', 10, 25, 'A esto replicó Moisés: —¡Al contrario!, tú vas a darnos los sacrificios y holocaustos que hemos de presentar al SEÑOR nuestro Dios,'),
('nvi', 'Éxodo 10:26', 'Éxodo', 10, 26, 'y además nuestro ganado tiene que ir con nosotros. ¡No puede quedarse aquí ni una sola pezuña! Para rendirle culto al SEÑOR nuestro Dios tendremos que tomar algunos de nuestros animales, y no sabremos cuáles debemos presentar como ofrenda hasta que lleguemos allá.'),
('nvi', 'Éxodo 10:27', 'Éxodo', 10, 27, 'Pero el SEÑOR endureció el corazón del faraón, y éste no quiso dejarlos ir,'),
('nvi', 'Éxodo 10:28', 'Éxodo', 10, 28, 'sino que le gritó a Moisés: —¡Largo de aquí! ¡Y cuidado con volver a presentarte ante mí! El día que vuelvas a verme, puedes darte por muerto.'),
('nvi', 'Éxodo 10:29', 'Éxodo', 10, 29, '—¡Bien dicho! —le respondió Moisés—. ¡Jamás volveré a verte!'),
('nvi', 'Éxodo 11:1', 'Éxodo', 11, 1, 'El SEÑOR le dijo a Moisés: «Voy a traer una plaga más sobre el faraón y sobre Egipto. Después de eso, dejará que se vayan. Y cuando lo haga, los echará de aquí para siempre.'),
('nvi', 'Éxodo 11:2', 'Éxodo', 11, 2, 'Habla con el pueblo y diles que todos ellos, hombres y mujeres, deben pedirles a sus vecinos y vecinas objetos de oro y de plata.»'),
('nvi', 'Éxodo 11:3', 'Éxodo', 11, 3, 'El SEÑOR hizo que los egipcios vieran con buenos ojos a los israelitas. Además, en todo Egipto Moisés mismo era altamente respetado por los funcionarios del faraón y por el pueblo.'),
('nvi', 'Éxodo 11:4', 'Éxodo', 11, 4, 'Moisés anunció: «Así dice el SEÑOR: “Hacia la medianoche pasaré por todo Egipto,'),
('nvi', 'Éxodo 11:5', 'Éxodo', 11, 5, 'y todo primogénito egipcio morirá: desde el primogénito del faraón que ahora ocupa el trono hasta el primogénito de la esclava que trabaja en el molino, lo mismo que todo primogénito del ganado.'),
('nvi', 'Éxodo 11:6', 'Éxodo', 11, 6, 'En todo Egipto habrá grandes lamentos, como no los ha habido ni volverá a haberlos.'),
('nvi', 'Éxodo 11:7', 'Éxodo', 11, 7, 'Pero entre los israelitas, ni los perros le ladrarán a persona o animal alguno. Así sabrán que el SEÑOR hace distinción entre Egipto e Israel.'),
('nvi', 'Éxodo 11:8', 'Éxodo', 11, 8, 'Todos estos funcionarios tuyos vendrán a verme, y de rodillas me suplicarán: ‘¡Vete ya, con todo el pueblo que te sigue!’Cuando esto suceda, me iré.”» Y ardiendo de ira, salió Moisés de la presencia del faraón,'),
('nvi', 'Éxodo 11:9', 'Éxodo', 11, 9, 'aunque ya el SEÑOR le había advertido a Moisés que el faraón no les iba a hacer caso, y que tenía que ser así para que las maravillas del SEÑOR se multiplicaran en Egipto.'),
('nvi', 'Éxodo 11:10', 'Éxodo', 11, 10, 'Moisés y Aarón realizaron ante el faraón todas estas maravillas; pero el SEÑOR endureció el corazón del faraón, y éste no dejó salir de su país a los israelitas.'),
('nvi', 'Éxodo 12:1', 'Éxodo', 12, 1, 'En Egipto el SEÑOR habló con Moisés y Aarón. Les dijo:'),
('nvi', 'Éxodo 12:2', 'Éxodo', 12, 2, '«Este mes será para ustedes el más importante, pues será el primer mes del año.'),
('nvi', 'Éxodo 12:3', 'Éxodo', 12, 3, 'Hablen con toda la comunidad de Israel, y díganles que el día décimo de este mes todos ustedes tomarán un cordero por familia, uno por cada casa.'),
('nvi', 'Éxodo 12:4', 'Éxodo', 12, 4, 'Si alguna familia es demasiado pequeña para comerse un cordero entero, deberá compartirlo con sus vecinos más cercanos, teniendo en cuenta el número de personas que sean y las raciones de cordero que se necesiten, según lo que cada persona haya de comer.'),
('nvi', 'Éxodo 12:5', 'Éxodo', 12, 5, 'El animal que se escoja puede ser un cordero o un cabrito de un año y sin defecto,'),
('nvi', 'Éxodo 12:6', 'Éxodo', 12, 6, 'al que cuidarán hasta el catorce del mes, día en que la comunidad de Israel en pleno lo sacrificará al caer la noche.'),
('nvi', 'Éxodo 12:7', 'Éxodo', 12, 7, 'Tomarán luego un poco de sangre y la untarán en los dos postes y en el dintel de la puerta de la casa donde coman el cordero.'),
('nvi', 'Éxodo 12:8', 'Éxodo', 12, 8, 'Deberán comer la carne esa misma noche, asada al fuego y acompañada de hierbas amargas y pan sin levadura.'),
('nvi', 'Éxodo 12:9', 'Éxodo', 12, 9, 'No deberán comerla cruda ni hervida, sino asada al fuego, junto con la cabeza, las patas y los intestinos.'),
('nvi', 'Éxodo 12:10', 'Éxodo', 12, 10, 'Y no deben dejar nada. En caso de que algo quede, lo quemarán al día siguiente.'),
('nvi', 'Éxodo 12:11', 'Éxodo', 12, 11, 'Comerán el cordero de este modo: con el manto ceñido a la cintura, con las sandalias puestas, con la vara en la mano, y de prisa. Se trata de la Pascua del SEÑOR.'),
('nvi', 'Éxodo 12:12', 'Éxodo', 12, 12, '»Esa misma noche pasaré por todo Egipto y heriré de muerte a todos los primogénitos, tanto de personas como de animales, y ejecutaré mi sentencia contra todos los dioses de Egipto. Yo soy el SEÑOR.'),
('nvi', 'Éxodo 12:13', 'Éxodo', 12, 13, 'La sangre servirá para señalar las casas donde ustedes se encuentren, pues al verla pasaré de largo. Así, cuando hiera yo de muerte a los egipcios, no los tocará a ustedes ninguna plaga destructora.'),
('nvi', 'Éxodo 12:14', 'Éxodo', 12, 14, '»Éste es un día que por ley deberán conmemorar siempre. Es una fiesta en honor del SEÑOR, y las generaciones futuras deberán celebrarla.'),
('nvi', 'Éxodo 12:15', 'Éxodo', 12, 15, 'Durante siete días comerán pan sin levadura, de modo que deben retirar de sus casas la levadura el primer día. Todo el que coma algo con levadura desde el día primero hasta el séptimo será eliminado de Israel.'),
('nvi', 'Éxodo 12:16', 'Éxodo', 12, 16, 'Celebrarán una reunión solemne el día primero, y otra el día séptimo. En todo ese tiempo no harán ningún trabajo, excepto preparar los alimentos que cada uno haya de comer. Sólo eso podrán hacer.'),
('nvi', 'Éxodo 12:17', 'Éxodo', 12, 17, '»Celebrarán la fiesta de los Panes sin levadura, porque fue ese día cuando los saqué de Egipto formados en escuadrones. Por ley, las generaciones futuras siempre deberán celebrar ese día.'),
('nvi', 'Éxodo 12:18', 'Éxodo', 12, 18, 'Comerán pan sin levadura desde la tarde del día catorce del mes primero hasta la tarde del día veintiuno del mismo mes.'),
('nvi', 'Éxodo 12:19', 'Éxodo', 12, 19, 'Durante siete días se abstendrán de tener levadura en sus casas. Todo el que coma algo con levadura, sea extranjero o israelita, será eliminado de la comunidad de Israel.'),
('nvi', 'Éxodo 12:20', 'Éxodo', 12, 20, 'No coman nada que tenga levadura. Dondequiera que vivan ustedes, comerán pan sin levadura.»'),
('nvi', 'Éxodo 12:21', 'Éxodo', 12, 21, 'Convocó entonces Moisés a todos los ancianos israelitas, y les dijo: «Vayan en seguida a sus rebaños, escojan el cordero para sus respectivas familias, y mátenlo para celebrar la Pascua.'),
('nvi', 'Éxodo 12:22', 'Éxodo', 12, 22, 'Tomen luego un manojo de hisopo, mójenlo en la sangre recogida en la palangana, unten de sangre el dintel y los dos postes de la puerta, ¡y no salga ninguno de ustedes de su casa hasta la mañana siguiente!'),
('nvi', 'Éxodo 12:23', 'Éxodo', 12, 23, 'Cuando el SEÑOR pase por el país para herir de muerte a los egipcios, verá la sangre en el dintel y en los postes de la puerta, y pasará de largo por esa casa. No permitirá el SEÑOR que el ángel exterminador entre en las casas de ustedes y los hiera.'),
('nvi', 'Éxodo 12:24', 'Éxodo', 12, 24, '»Obedezcan estas instrucciones. Será una ley perpetua para ustedes y para sus hijos.'),
('nvi', 'Éxodo 12:25', 'Éxodo', 12, 25, 'Cuando entren en la tierra que el SEÑOR ha prometido darles, ustedes seguirán celebrando esta ceremonia.'),
('nvi', 'Éxodo 12:26', 'Éxodo', 12, 26, 'Y cuando sus hijos les pregunten: “¿Qué significa para ustedes esta ceremonia?”,'),
('nvi', 'Éxodo 12:27', 'Éxodo', 12, 27, 'les responderán: “Este sacrificio es la Pascua del SEÑOR, que en Egipto pasó de largo por las casas israelitas. Hirió de muerte a los egipcios, pero a nuestras familias les salvó la vida.”» Al oír esto, los israelitas se inclinaron y adoraron al SEÑOR,'),
('nvi', 'Éxodo 12:28', 'Éxodo', 12, 28, 'y fueron y cumplieron al pie de la letra lo que el SEÑOR les había ordenado a Moisés y a Aarón.'),
('nvi', 'Éxodo 12:29', 'Éxodo', 12, 29, 'A medianoche el SEÑOR hirió de muerte a todos los primogénitos egipcios, desde el primogénito del faraón en el trono hasta el primogénito del preso en la cárcel, así como a las primeras crías de todo el ganado.'),
('nvi', 'Éxodo 12:30', 'Éxodo', 12, 30, 'Todos en Egipto se levantaron esa noche, lo mismo el faraón que sus funcionarios, y hubo grandes lamentos en el país. No había una sola casa egipcia donde no hubiera algún muerto.'),
('nvi', 'Éxodo 12:31', 'Éxodo', 12, 31, 'Esa misma noche mandó llamar el faraón a Moisés y a Aarón, y les ordenó: «¡Largo de aquí! ¡Aléjense de mi pueblo ustedes y los israelitas! ¡Vayan a adorar al SEÑOR, como lo han estado pidiendo!'),
('nvi', 'Éxodo 12:32', 'Éxodo', 12, 32, 'Llévense también sus rebaños y sus ganados, como lo han pedido, ¡pero váyanse ya, que para mí será una bendición!»'),
('nvi', 'Éxodo 12:33', 'Éxodo', 12, 33, 'El pueblo egipcio, por su parte, instaba a los israelitas a que abandonaran pronto el país. «De lo contrario —decían—, ¡podemos darnos por muertos!»'),
('nvi', 'Éxodo 12:34', 'Éxodo', 12, 34, 'Entonces los israelitas tomaron las artesas de masa todavía sin leudar y, luego de envolverlas en sus ropas, se las echaron al hombro.'),
('nvi', 'Éxodo 12:35', 'Éxodo', 12, 35, 'Después, siguiendo las instrucciones que Moisés les había dado, pidieron a los egipcios que les dieran objetos de oro y de plata, y también ropa.'),
('nvi', 'Éxodo 12:36', 'Éxodo', 12, 36, 'El SEÑOR hizo que los egipcios vieran con buenos ojos a los israelitas, así que les dieron todo lo que les pedían. De este modo los israelitas despojaron por completo a los egipcios.'),
('nvi', 'Éxodo 12:37', 'Éxodo', 12, 37, 'Los israelitas partieron de Ramsés, en dirección a Sucot. Sin contar a las mujeres y a los niños, eran unos seiscientos mil hombres de a pie.'),
('nvi', 'Éxodo 12:38', 'Éxodo', 12, 38, 'Con ellos salió también gente de toda laya, y grandes manadas de ganado, tanto de ovejas como de vacas.'),
('nvi', 'Éxodo 12:39', 'Éxodo', 12, 39, 'Con la masa que sacaron de Egipto cocieron panes sin levadura, pues la masa aún no había fermentado. Como los echaron de Egipto, no tuvieron tiempo de preparar comida.'),
('nvi', 'Éxodo 12:40', 'Éxodo', 12, 40, 'Los israelitas habían vivido en Egipto cuatrocientos treinta años.'),
('nvi', 'Éxodo 12:41', 'Éxodo', 12, 41, 'Precisamente el día en que se cumplían los cuatrocientos treinta años, todos los escuadrones del SEÑOR salieron de Egipto.'),
('nvi', 'Éxodo 12:42', 'Éxodo', 12, 42, 'Aquella noche el SEÑOR la pasó en vela para sacar de Egipto a los israelitas. Por eso también las generaciones futuras de israelitas deben pasar esa noche en vela, en honor del SEÑOR.'),
('nvi', 'Éxodo 12:43', 'Éxodo', 12, 43, 'El SEÑOR les dijo a Moisés y a Aarón: «Éstas son las normas para la Pascua: »Ningún extranjero podrá participar de ella.'),
('nvi', 'Éxodo 12:44', 'Éxodo', 12, 44, '»Podrán participar de ella todos los esclavos que hayas comprado con tu dinero, siempre y cuando los hayas circuncidado antes.'),
('nvi', 'Éxodo 12:45', 'Éxodo', 12, 45, '»Ningún residente temporal ni trabajador a sueldo podrá participar de ella.'),
('nvi', 'Éxodo 12:46', 'Éxodo', 12, 46, '»La Pascua deberá comerse en casa, y de allí no se sacará ni un solo pedazo de carne. Tampoco se le quebrará ningún hueso al animal sacrificado.'),
('nvi', 'Éxodo 12:47', 'Éxodo', 12, 47, '»Toda la comunidad de Israel debe celebrar la Pascua.'),
('nvi', 'Éxodo 12:48', 'Éxodo', 12, 48, '»Todo extranjero que viva entre ustedes y quiera celebrar la Pascua del SEÑOR, deberá primero circuncidar a todos los varones de su familia; sólo entonces podrá participar de la Pascua como si fuera nativo del país. »Ningún incircunciso podrá participar de ella.'),
('nvi', 'Éxodo 12:49', 'Éxodo', 12, 49, '»La misma ley se aplicará al nativo y al extranjero que viva entre ustedes.»'),
('nvi', 'Éxodo 12:50', 'Éxodo', 12, 50, 'Todos los israelitas cumplieron al pie de la letra lo que el SEÑOR les había ordenado a Moisés y a Aarón.'),
('nvi', 'Éxodo 12:51', 'Éxodo', 12, 51, 'Ese mismo día el SEÑOR sacó de Egipto a los israelitas, escuadrón por escuadrón.'),
('nvi', 'Éxodo 13:1', 'Éxodo', 13, 1, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 13:2', 'Éxodo', 13, 2, '«Conságrame el primogénito de todo vientre. Míos son todos los primogénitos israelitas y todos los primeros machos de sus animales.»'),
('nvi', 'Éxodo 13:3', 'Éxodo', 13, 3, 'Moisés le dijo al pueblo: «Acuérdense de este día en que salen de Egipto, país donde han sido esclavos y de donde el SEÑOR los saca desplegando su poder. No coman pan con levadura.'),
('nvi', 'Éxodo 13:4', 'Éxodo', 13, 4, 'Ustedes salen hoy, en el mes de aviv,'),
('nvi', 'Éxodo 13:5', 'Éxodo', 13, 5, 'y en este mismo mes deberán celebrar esta ceremonia, cuando ya el SEÑOR los haya hecho entrar en la tierra que prometió dar a los antepasados de ustedes. Se trata de la tierra de los cananeos, hititas, amorreos, heveos y jebuseos: ¡tierra donde abundan la leche y la miel!'),
('nvi', 'Éxodo 13:6', 'Éxodo', 13, 6, 'Durante siete días comerán pan sin levadura, y el día séptimo celebrarán una fiesta en honor al SEÑOR.'),
('nvi', 'Éxodo 13:7', 'Éxodo', 13, 7, 'En ningún lugar de su territorio debe haber nada que contenga levadura. Ni siquiera habrá levadura entre ustedes. Comerán pan sin levadura durante esos siete días.'),
('nvi', 'Éxodo 13:8', 'Éxodo', 13, 8, '»Ese día ustedes les dirán a sus hijos: “Esto lo hacemos por lo que hizo el SEÑOR por nosotros cuando salimos de Egipto.”'),
('nvi', 'Éxodo 13:9', 'Éxodo', 13, 9, 'Y será para ustedes como una marca distintiva en la mano o en la frente, que les hará recordar que la ley del SEÑOR debe estar en sus labios, porque el SEÑOR los sacó de Egipto desplegando su poder.'),
('nvi', 'Éxodo 13:10', 'Éxodo', 13, 10, 'Año tras año, en la misma fecha, cumplirán con esta ley.'),
('nvi', 'Éxodo 13:11', 'Éxodo', 13, 11, '»Una vez que el SEÑOR los haga entrar en la tierra de los cananeos y se la haya dado, conforme al juramento que les hizo a ustedes y a sus antepasados,'),
('nvi', 'Éxodo 13:12', 'Éxodo', 13, 12, 'le dedicarán al SEÑOR el primogénito de todo vientre, y todo primer macho de su ganado, pues éstos le pertenecen al SEÑOR.'),
('nvi', 'Éxodo 13:13', 'Éxodo', 13, 13, 'El primogénito de una asna podrá ser rescatado a cambio de un cordero; pero si no se rescata, se le quebrará el cuello. Todos los primogénitos de ustedes o de sus descendientes deberán ser rescatados.'),
('nvi', 'Éxodo 13:14', 'Éxodo', 13, 14, '»El día de mañana, cuando sus hijos les pregunten: “¿Y esto qué significa?”, les dirán: “El SEÑOR, desplegando su poder, nos sacó de Egipto, país donde fuimos esclavos.'),
('nvi', 'Éxodo 13:15', 'Éxodo', 13, 15, 'Cuando el faraón se empeñó en no dejarnos ir, el SEÑOR les quitó la vida a todos los primogénitos de Egipto, tanto de hombres como de animales. Por eso le ofrecemos al SEÑOR en sacrificio el primer macho que nace, y rescatamos a nuestros primogénitos.”'),
('nvi', 'Éxodo 13:16', 'Éxodo', 13, 16, 'Esto será para ustedes como una marca distintiva en la mano o en la frente, de que el SEÑOR nos sacó de Egipto desplegando su poder.»'),
('nvi', 'Éxodo 13:17', 'Éxodo', 13, 17, 'Cuando el faraón dejó salir a los israelitas, Dios no los llevó por el camino que atraviesa la tierra de los filisteos, que era el más corto, pues pensó: «Si se les presentara batalla, podrían cambiar de idea y regresar a Egipto.»'),
('nvi', 'Éxodo 13:18', 'Éxodo', 13, 18, 'Por eso les hizo dar un rodeo por el camino del desierto, en dirección al Mar Rojo. Los israelitas salieron de Egipto en formación de combate.'),
('nvi', 'Éxodo 13:19', 'Éxodo', 13, 19, 'Moisés se llevó consigo los restos de José, según éste se lo había pedido a los israelitas bajo juramento. Éstas habían sido las palabras de José: «Pueden contar ustedes con que Dios vendrá en su ayuda. Cuando eso suceda, llévense de aquí mis restos.»'),
('nvi', 'Éxodo 13:20', 'Éxodo', 13, 20, 'Los israelitas partieron de Sucot y acamparon en Etam, donde comienza el desierto.'),
('nvi', 'Éxodo 13:21', 'Éxodo', 13, 21, 'De día, el SEÑOR iba al frente de ellos en una columna de nube para indicarles el camino; de noche, los alumbraba con una columna de fuego. De ese modo podían viajar de día y de noche.'),
('nvi', 'Éxodo 13:22', 'Éxodo', 13, 22, 'Jamás la columna de nube dejaba de guiar al pueblo durante el día, ni la columna de fuego durante la noche.'),
('nvi', 'Éxodo 14:1', 'Éxodo', 14, 1, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 14:2', 'Éxodo', 14, 2, '«Ordénales a los israelitas que regresen y acampen frente a Pi Ajirot, entre Migdol y el mar. Que acampen junto al mar, frente a Baal Zefón.'),
('nvi', 'Éxodo 14:3', 'Éxodo', 14, 3, 'El faraón va a pensar: “Los israelitas andan perdidos en esa tierra. ¡El desierto los tiene acorralados!”'),
('nvi', 'Éxodo 14:4', 'Éxodo', 14, 4, 'Yo, por mi parte, endureceré el corazón del faraón para que él los persiga. Voy a cubrirme de gloria, a costa del faraón y de todo su ejército. ¡Y los egipcios sabrán que yo soy el SEÑOR!» Así lo hicieron los israelitas.'),
('nvi', 'Éxodo 14:5', 'Éxodo', 14, 5, 'Y cuando el rey de Egipto se enteró de que el pueblo se había escapado, tanto él como sus funcionarios cambiaron de parecer en cuanto a los israelitas y dijeron: «¡Pero qué hemos hecho! ¿Cómo pudimos dejar que se fueran los israelitas y abandonaran su trabajo?»'),
('nvi', 'Éxodo 14:6', 'Éxodo', 14, 6, 'Al momento ordenó el faraón que le prepararan su carro y, echando mano de su ejército,'),
('nvi', 'Éxodo 14:7', 'Éxodo', 14, 7, 'se llevó consigo seiscientos de los mejores carros y todos los demás carros de Egipto, cada uno de ellos bajo el mando de un oficial.'),
('nvi', 'Éxodo 14:8', 'Éxodo', 14, 8, 'El SEÑOR endureció el corazón del faraón, rey de Egipto, para que saliera en persecución de los israelitas, los cuales marchaban con aire triunfal.'),
('nvi', 'Éxodo 14:9', 'Éxodo', 14, 9, 'Todo el ejército del faraón —caballos, carros, jinetes y tropas de Egipto—salió tras los israelitas y les dio alcance cuando éstos acampaban junto al mar, cerca de Pi Ajirot y frente a Baal Zefón.'),
('nvi', 'Éxodo 14:10', 'Éxodo', 14, 10, 'El faraón iba acercándose. Cuando los israelitas se fijaron y vieron a los egipcios pisándoles los talones, sintieron mucho miedo y clamaron al SEÑOR.'),
('nvi', 'Éxodo 14:11', 'Éxodo', 14, 11, 'Entonces le reclamaron a Moisés: —¿Acaso no había sepulcros en Egipto, que nos sacaste de allá para morir en el desierto? ¿Qué has hecho con nosotros? ¿Para qué nos sacaste de Egipto?'),
('nvi', 'Éxodo 14:12', 'Éxodo', 14, 12, 'Ya en Egipto te decíamos: “¡Déjanos en paz! ¡Preferimos servir a los egipcios!”¡Mejor nos hubiera sido servir a los egipcios que morir en el desierto!'),
('nvi', 'Éxodo 14:13', 'Éxodo', 14, 13, '—No tengan miedo —les respondió Moisés—. Mantengan sus posiciones, que hoy mismo serán testigos de la salvación que el SEÑOR realizará en favor de ustedes. A esos egipcios que hoy ven, ¡jamás volverán a verlos!'),
('nvi', 'Éxodo 14:14', 'Éxodo', 14, 14, 'Ustedes quédense quietos, que el SEÑOR presentará batalla por ustedes.'),
('nvi', 'Éxodo 14:15', 'Éxodo', 14, 15, 'Pero el SEÑOR le dijo a Moisés: «¿Por qué clamas a mí? ¡Ordena a los israelitas que se pongan en marcha!'),
('nvi', 'Éxodo 14:16', 'Éxodo', 14, 16, 'Y tú, levanta tu vara, extiende tu brazo sobre el mar y divide las aguas, para que los israelitas lo crucen sobre terreno seco.'),
('nvi', 'Éxodo 14:17', 'Éxodo', 14, 17, 'Yo voy a endurecer el corazón de los egipcios, para que los persigan. ¡Voy a cubrirme de gloria a costa del faraón y de su ejército, y de sus carros y jinetes!'),
('nvi', 'Éxodo 14:18', 'Éxodo', 14, 18, 'Y cuando me haya cubierto de gloria a costa de ellos, los egipcios sabrán que yo soy el SEÑOR.»'),
('nvi', 'Éxodo 14:19', 'Éxodo', 14, 19, 'Entonces el ángel de Dios, que marchaba al frente del ejército israelita, se dio vuelta y fue a situarse detrás de éste. Lo mismo sucedió con la columna de nube, que dejó su puesto de vanguardia y se desplazó hacia la retaguardia,'),
('nvi', 'Éxodo 14:20', 'Éxodo', 14, 20, 'quedando entre los egipcios y los israelitas. Durante toda la noche, la nube fue oscuridad para unos y luz para otros, así que en toda esa noche no pudieron acercarse los unos a los otros.'),
('nvi', 'Éxodo 14:21', 'Éxodo', 14, 21, 'Moisés extendió su brazo sobre el mar, y toda la noche el SEÑOR envió sobre el mar un recio viento del este que lo hizo retroceder, convirtiéndolo en tierra seca. Las aguas del mar se dividieron,'),
('nvi', 'Éxodo 14:22', 'Éxodo', 14, 22, 'y los israelitas lo cruzaron sobre tierra seca. El mar era para ellos una muralla de agua a la derecha y otra a la izquierda.'),
('nvi', 'Éxodo 14:23', 'Éxodo', 14, 23, 'Los egipcios los persiguieron. Todos los caballos y carros del faraón, y todos sus jinetes, entraron en el mar tras ellos.'),
('nvi', 'Éxodo 14:24', 'Éxodo', 14, 24, 'Cuando ya estaba por amanecer, el SEÑOR miró al ejército egipcio desde la columna de fuego y de nube, y sembró la confusión entre ellos:'),
('nvi', 'Éxodo 14:25', 'Éxodo', 14, 25, 'hizo que las ruedas de sus carros se atascaran, de modo que se les hacía muy difícil avanzar. Entonces exclamaron los egipcios: «¡Alejémonos de los israelitas, pues el SEÑOR está peleando por ellos y contra nosotros!»'),
('nvi', 'Éxodo 14:26', 'Éxodo', 14, 26, 'Entonces el SEÑOR le dijo a Moisés: «Extiende tu brazo sobre el mar, para que las aguas se vuelvan contra los egipcios y contra sus carros y jinetes.»'),
('nvi', 'Éxodo 14:27', 'Éxodo', 14, 27, 'Moisés extendió su brazo sobre el mar y, al despuntar el alba, el agua volvió a su estado normal. Los egipcios, en su huida, se toparon con el mar, y así el SEÑOR los hundió en el fondo del mar.'),
('nvi', 'Éxodo 14:28', 'Éxodo', 14, 28, 'Al recobrar las aguas su estado normal, se tragaron a todos los carros y jinetes del faraón, y a todo el ejército que había entrado al mar para perseguir a los israelitas. Ninguno de ellos quedó con vida.'),
('nvi', 'Éxodo 14:29', 'Éxodo', 14, 29, 'Los israelitas, sin embargo, cruzaron el mar sobre tierra seca, pues para ellos el mar formó una muralla de agua a la derecha y otra a la izquierda.'),
('nvi', 'Éxodo 14:30', 'Éxodo', 14, 30, 'En ese día el SEÑOR salvó a Israel del poder de Egipto. Los israelitas vieron los cadáveres de los egipcios tendidos a la orilla del mar.'),
('nvi', 'Éxodo 14:31', 'Éxodo', 14, 31, 'Y al ver los israelitas el gran poder que el SEÑOR había desplegado en contra de los egipcios, temieron al SEÑOR y creyeron en él y en su siervo Moisés.'),
('nvi', 'Éxodo 15:1', 'Éxodo', 15, 1, 'Entonces Moisés y los israelitas entonaron un cántico en honor del SEÑOR, que a la letra decía: Cantaré al SEÑOR, que se ha coronado de triunfo arrojando al mar caballos y jinetes.'),
('nvi', 'Éxodo 15:2', 'Éxodo', 15, 2, 'El SEÑOR es mi fuerza y mi cántico; él es mi salvación. Él es mi Dios, y lo alabaré; es el Dios de mi padre, y lo enalteceré.'),
('nvi', 'Éxodo 15:3', 'Éxodo', 15, 3, 'El SEÑOR es un guerrero; su nombre es el SEÑOR.'),
('nvi', 'Éxodo 15:4', 'Éxodo', 15, 4, 'El SEÑOR arrojó al mar los carros y el ejército del faraón. Los mejores oficiales egipcios se ahogaron en el Mar Rojo.'),
('nvi', 'Éxodo 15:5', 'Éxodo', 15, 5, 'Las aguas profundas se los tragaron; ¡como piedras se hundieron en los abismos!'),
('nvi', 'Éxodo 15:6', 'Éxodo', 15, 6, 'Tu diestra, SEÑOR, reveló su gran poder; tu diestra, SEÑOR, despedazó al enemigo.'),
('nvi', 'Éxodo 15:7', 'Éxodo', 15, 7, 'Fue tan grande tu victoria que derribaste a tus oponentes; diste rienda suelta a tu ardiente ira, y fueron consumidos como rastrojo.'),
('nvi', 'Éxodo 15:8', 'Éxodo', 15, 8, 'Bastó un soplo de tu nariz para que se amontonaran las aguas. Las olas se irguieron como murallas; ¡se inmovilizaron las aguas en el fondo del mar!'),
('nvi', 'Éxodo 15:9', 'Éxodo', 15, 9, '«Iré tras ellos y les daré alcance —alardeaba el enemigo—. Repartiré sus despojos hasta quedar hastiado. ¡Desenvainaré la espada y los destruiré con mi propia mano!»'),
('nvi', 'Éxodo 15:10', 'Éxodo', 15, 10, 'Pero con un soplo tuyo se los tragó el mar; ¡se hundieron como plomo en las aguas turbulentas!'),
('nvi', 'Éxodo 15:11', 'Éxodo', 15, 11, '¿Quién, SEÑOR, se te compara entre los dioses? ¿Quién se te compara en grandeza y santidad? Tú, hacedor de maravillas, nos impresionas con tus portentos.'),
('nvi', 'Éxodo 15:12', 'Éxodo', 15, 12, 'Extendiste tu brazo derecho, ¡y se los tragó la tierra!'),
('nvi', 'Éxodo 15:13', 'Éxodo', 15, 13, 'Por tu gran amor guías al pueblo que has rescatado; por tu fuerza los llevas a tu santa morada.'),
('nvi', 'Éxodo 15:14', 'Éxodo', 15, 14, 'Las naciones temblarán al escucharlo; la angustia dominará a los filisteos.'),
('nvi', 'Éxodo 15:15', 'Éxodo', 15, 15, 'Los jefes edomitas se llenarán de terror; temblarán de miedo los caudillos de Moab. Los cananeos perderán el ánimo,'),
('nvi', 'Éxodo 15:16', 'Éxodo', 15, 16, 'pues caerá sobre ellos pavor y espanto. Por tu gran poder, SEÑOR, quedarán mudos como piedras hasta que haya pasado tu pueblo, el pueblo que adquiriste para ti.'),
('nvi', 'Éxodo 15:17', 'Éxodo', 15, 17, 'Tú los harás entrar, y los plantarás, en el monte que te pertenece; en el lugar donde tú, SEÑOR, habitas; en el santuario que tú, Señor, te hiciste.'),
('nvi', 'Éxodo 15:18', 'Éxodo', 15, 18, '¡El SEÑOR reina por siempre y para siempre!'),
('nvi', 'Éxodo 15:19', 'Éxodo', 15, 19, 'Cuando los caballos y los carros del faraón entraron en el mar con sus jinetes, el SEÑOR hizo que las aguas se les vinieran encima. Los israelitas, sin embargo, cruzaron el mar sobre tierra seca.'),
('nvi', 'Éxodo 15:20', 'Éxodo', 15, 20, 'Entonces Miriam la profetisa, hermana de Aarón, tomó una pandereta, y mientras todas las mujeres la seguían danzando y tocando panderetas,'),
('nvi', 'Éxodo 15:21', 'Éxodo', 15, 21, 'Miriam les cantaba así: Canten al SEÑOR, que se ha coronado de triunfo arrojando al mar caballos y jinetes.'),
('nvi', 'Éxodo 15:22', 'Éxodo', 15, 22, 'Moisés les ordenó a los israelitas que partieran del Mar Rojo y se internaran en el desierto de Sur. Y los israelitas anduvieron tres días por el desierto sin hallar agua.'),
('nvi', 'Éxodo 15:23', 'Éxodo', 15, 23, 'Llegaron a Mara, lugar que se llama así porque sus aguas son amargas, y no pudieron apagar su sed allí.'),
('nvi', 'Éxodo 15:24', 'Éxodo', 15, 24, 'Comenzaron entonces a murmurar en contra de Moisés, y preguntaban: «¿Qué vamos a beber?»'),
('nvi', 'Éxodo 15:25', 'Éxodo', 15, 25, 'Moisés clamó al SEÑOR, y él le mostró un pedazo de madera, el cual echó Moisés al agua, y al instante el agua se volvió dulce. En ese lugar el SEÑOR los puso a prueba y les dio una ley como norma de conducta.'),
('nvi', 'Éxodo 15:26', 'Éxodo', 15, 26, 'Les dijo: «Yo soy el SEÑOR su Dios. Si escuchan mi voz y hacen lo que yo considero justo, y si cumplen mis leyes y mandamientos, no traeré sobre ustedes ninguna de las enfermedades que traje sobre los egipcios. Yo soy el SEÑOR, que les devuelve la salud.»'),
('nvi', 'Éxodo 15:27', 'Éxodo', 15, 27, 'Después los israelitas llegaron a Elim, donde había doce manantiales y setenta palmeras, y acamparon allí, cerca del agua.'),
('nvi', 'Éxodo 16:1', 'Éxodo', 16, 1, 'Toda la comunidad israelita partió de Elim y llegó al desierto de Sin, que está entre Elim y el Sinaí. Esto ocurrió a los quince días del mes segundo, contados a partir de su salida de Egipto.'),
('nvi', 'Éxodo 16:2', 'Éxodo', 16, 2, 'Allí, en el desierto, toda la comunidad murmuró contra Moisés y Aarón:'),
('nvi', 'Éxodo 16:3', 'Éxodo', 16, 3, '—¡Cómo quisiéramos que el SEÑOR nos hubiera quitado la vida en Egipto! —les decían los israelitas—. Allá nos sentábamos en torno a las ollas de carne y comíamos pan hasta saciarnos. ¡Ustedes han traído nuestra comunidad a este desierto para matarnos de hambre a todos!'),
('nvi', 'Éxodo 16:4', 'Éxodo', 16, 4, 'Entonces el SEÑOR le dijo a Moisés: «Voy a hacer que les llueva pan del cielo. El pueblo deberá salir todos los días a recoger su ración diaria. Voy a ponerlos a prueba, para ver si cumplen o no mis instrucciones.'),
('nvi', 'Éxodo 16:5', 'Éxodo', 16, 5, 'El día sexto recogerán una doble porción, y todo esto lo dejarán preparado.»'),
('nvi', 'Éxodo 16:6', 'Éxodo', 16, 6, 'Moisés y Aarón les dijeron a todos los israelitas: —Esta tarde sabrán que fue el SEÑOR quien los sacó de Egipto,'),
('nvi', 'Éxodo 16:7', 'Éxodo', 16, 7, 'y mañana por la mañana verán la gloria del SEÑOR. Ya él sabe que ustedes andan murmurando contra él. Nosotros no somos nadie, para que ustedes murmuren contra nosotros.'),
('nvi', 'Éxodo 16:8', 'Éxodo', 16, 8, 'Y añadió Moisés: —Esta tarde el SEÑOR les dará a comer carne, y mañana los saciará de pan, pues ya los oyó murmurar contra él. Porque ¿quiénes somos nosotros? ¡Ustedes no están murmurando contra nosotros sino contra el SEÑOR!'),
('nvi', 'Éxodo 16:9', 'Éxodo', 16, 9, 'Luego se dirigió Moisés a Aarón: —Dile a toda la comunidad israelita que se acerque al SEÑOR, pues los ha oído murmurar contra él.'),
('nvi', 'Éxodo 16:10', 'Éxodo', 16, 10, 'Mientras Aarón hablaba con toda la comunidad israelita, volvieron la mirada hacia el desierto, y vieron que la gloria del SEÑOR se hacía presente en una nube.'),
('nvi', 'Éxodo 16:11', 'Éxodo', 16, 11, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 16:12', 'Éxodo', 16, 12, '«Han llegado a mis oídos las murmuraciones de los israelitas. Diles que antes de que caiga la noche comerán carne, y que mañana por la mañana se hartarán de pan. Así sabrán que yo soy el SEÑOR su Dios.»'),
('nvi', 'Éxodo 16:13', 'Éxodo', 16, 13, 'Esa misma tarde el campamento se llenó de codornices, y por la mañana una capa de rocío rodeaba el campamento.'),
('nvi', 'Éxodo 16:14', 'Éxodo', 16, 14, 'Al desaparecer el rocío, sobre el desierto quedaron unos copos muy finos, semejantes a la escarcha que cae sobre la tierra.'),
('nvi', 'Éxodo 16:15', 'Éxodo', 16, 15, 'Como los israelitas no sabían lo que era, al verlo se preguntaban unos a otros: «¿Y esto qué es?» Moisés les respondió: —Es el pan que el SEÑOR les da para comer.'),
('nvi', 'Éxodo 16:16', 'Éxodo', 16, 16, 'Y éstas son las órdenes que el SEÑOR me ha dado: “Recoja cada uno de ustedes la cantidad que necesite para toda la familia, calculando dos litros por persona.”'),
('nvi', 'Éxodo 16:17', 'Éxodo', 16, 17, 'Así lo hicieron los israelitas. Algunos recogieron mucho; otros recogieron poco.'),
('nvi', 'Éxodo 16:18', 'Éxodo', 16, 18, 'Pero cuando lo midieron por litros, ni al que recogió mucho le sobraba, ni al que recogió poco le faltaba: cada uno recogió la cantidad necesaria.'),
('nvi', 'Éxodo 16:19', 'Éxodo', 16, 19, 'Entonces Moisés les dijo: —Nadie debe guardar nada para el día siguiente.'),
('nvi', 'Éxodo 16:20', 'Éxodo', 16, 20, 'Hubo algunos que no le hicieron caso a Moisés y guardaron algo para el día siguiente, pero lo guardado se llenó de gusanos y comenzó a apestar. Entonces Moisés se enojó contra ellos.'),
('nvi', 'Éxodo 16:21', 'Éxodo', 16, 21, 'Todas las mañanas cada uno recogía la cantidad que necesitaba, porque se derretía en cuanto calentaba el sol.'),
('nvi', 'Éxodo 16:22', 'Éxodo', 16, 22, 'Pero el día sexto recogieron el doble, es decir, cuatro litros por persona, así que los jefes de la comunidad fueron a informar de esto a Moisés.'),
('nvi', 'Éxodo 16:23', 'Éxodo', 16, 23, '—Esto es lo que el SEÑOR ha ordenado —les contestó—. Mañana sábado es día de reposo consagrado al SEÑOR. Así que cuezan lo que tengan que cocer, y hiervan lo que tengan que hervir. Lo que sobre, apártenlo y guárdenlo para mañana.'),
('nvi', 'Éxodo 16:24', 'Éxodo', 16, 24, 'Los israelitas cumplieron las órdenes de Moisés y guardaron para el día siguiente lo que les sobró, ¡y no se pudrió ni se agusanó!'),
('nvi', 'Éxodo 16:25', 'Éxodo', 16, 25, '—Cómanlo hoy sábado —les dijo Moisés—, que es el día de reposo consagrado al SEÑOR. Hoy no encontrarán nada en el campo.'),
('nvi', 'Éxodo 16:26', 'Éxodo', 16, 26, 'Deben recogerlo durante seis días, porque el día séptimo, que es sábado, no encontrarán nada.'),
('nvi', 'Éxodo 16:27', 'Éxodo', 16, 27, 'Algunos israelitas salieron a recogerlo el día séptimo, pero no encontraron nada,'),
('nvi', 'Éxodo 16:28', 'Éxodo', 16, 28, 'así que el SEÑOR le dijo a Moisés: «¿Hasta cuándo seguirán desobedeciendo mis leyes y mandamientos?'),
('nvi', 'Éxodo 16:29', 'Éxodo', 16, 29, 'Tomen en cuenta que yo, el SEÑOR, les he dado el sábado. Por eso en el día sexto les doy pan para dos días. El día séptimo nadie debe salir. Todos deben quedarse donde estén.»'),
('nvi', 'Éxodo 16:30', 'Éxodo', 16, 30, 'Fue así como los israelitas descansaron el día séptimo.'),
('nvi', 'Éxodo 16:31', 'Éxodo', 16, 31, 'Y llamaron al pan «maná». Era blanco como la semilla de cilantro, y dulce como las tortas con miel.'),
('nvi', 'Éxodo 16:32', 'Éxodo', 16, 32, '—Esto es lo que ha ordenado el SEÑOR—dijo Moisés—: “Tomen unos dos litros de maná, y guárdenlos para que las generaciones futuras puedan ver el pan que yo les di a comer en el desierto, cuando los saqué de Egipto.”'),
('nvi', 'Éxodo 16:33', 'Éxodo', 16, 33, 'Luego Moisés le dijo a Aarón: —Toma una vasija y pon en ella unos dos litros de maná. Colócala después en la presencia del SEÑOR, a fin de conservarla para las generaciones futuras.'),
('nvi', 'Éxodo 16:34', 'Éxodo', 16, 34, 'Aarón puso el maná ante el arca del pacto, para que fuera conservado como se lo ordenó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 16:35', 'Éxodo', 16, 35, 'Comieron los israelitas maná cuarenta años, hasta que llegaron a los límites de la tierra de Canaán, que fue su país de residencia.'),
('nvi', 'Éxodo 16:36', 'Éxodo', 16, 36, 'La medida de dos litros, a la que llamaban gómer, era la décima parte de la medida a la que llamaban efa.'),
('nvi', 'Éxodo 17:1', 'Éxodo', 17, 1, 'Toda la comunidad israelita partió del desierto de Sin por etapas, según lo había ordenado el SEÑOR. Acamparon en Refidín, pero no había allí agua para que bebieran,'),
('nvi', 'Éxodo 17:2', 'Éxodo', 17, 2, 'así que altercaron con Moisés. —Danos agua para beber —le exigieron. —¿Por qué pelean conmigo? —se defendió Moisés—. ¿Por qué provocan al SEÑOR?'),
('nvi', 'Éxodo 17:3', 'Éxodo', 17, 3, 'Pero los israelitas estaban sedientos, y murmuraron contra Moisés. —¿Para qué nos sacaste de Egipto? —reclamaban—. ¿Sólo para matarnos de sed a nosotros, a nuestros hijos y a nuestro ganado?'),
('nvi', 'Éxodo 17:4', 'Éxodo', 17, 4, 'Clamó entonces Moisés al SEÑOR, y le dijo: —¿Qué voy a hacer con este pueblo? ¡Sólo falta que me maten a pedradas!'),
('nvi', 'Éxodo 17:5', 'Éxodo', 17, 5, '—Adelántate al pueblo —le aconsejó el SEÑOR—y llévate contigo a algunos ancianos de Israel, pero lleva también la vara con que golpeaste el Nilo. Ponte en marcha,'),
('nvi', 'Éxodo 17:6', 'Éxodo', 17, 6, 'que yo estaré esperándote junto a la roca que está en Horeb. Aséstale un golpe a la roca, y de ella brotará agua para que beba el pueblo. Así lo hizo Moisés, a la vista de los ancianos de Israel.'),
('nvi', 'Éxodo 17:7', 'Éxodo', 17, 7, 'Además, a ese lugar lo llamó Masá, y también Meribá, porque los israelitas habían altercado con él y provocado al SEÑOR al decir: «¿Está o no está el SEÑOR entre nosotros?»'),
('nvi', 'Éxodo 17:8', 'Éxodo', 17, 8, 'Los amalecitas vinieron a Refidín y atacaron a los israelitas.'),
('nvi', 'Éxodo 17:9', 'Éxodo', 17, 9, 'Entonces Moisés le ordenó a Josué: «Escoge algunos de nuestros hombres y sal a combatir a los amalecitas. Mañana yo estaré en la cima de la colina con la vara de Dios en la mano.»'),
('nvi', 'Éxodo 17:10', 'Éxodo', 17, 10, 'Josué siguió las órdenes de Moisés y les presentó batalla a los amalecitas. Por su parte, Moisés, Aarón y Jur subieron a la cima de la colina.'),
('nvi', 'Éxodo 17:11', 'Éxodo', 17, 11, 'Mientras Moisés mantenía los brazos en alto, la batalla se inclinaba en favor de los israelitas; pero cuando los bajaba, se inclinaba en favor de los amalecitas.'),
('nvi', 'Éxodo 17:12', 'Éxodo', 17, 12, 'Cuando a Moisés se le cansaron los brazos, tomaron una piedra y se la pusieron debajo para que se sentara en ella; luego Aarón y Jur le sostuvieron los brazos, uno el izquierdo y otro el derecho, y así Moisés pudo mantenerlos firmes hasta la puesta del sol.'),
('nvi', 'Éxodo 17:13', 'Éxodo', 17, 13, 'Fue así como Josué derrotó al ejército amalecita a filo de espada.'),
('nvi', 'Éxodo 17:14', 'Éxodo', 17, 14, 'Entonces el SEÑOR le dijo a Moisés: «Pon esto por escrito en un rollo de cuero, para que se recuerde, y que lo oiga bien Josué: Yo borraré por completo, bajo el cielo, todo rastro de los amalecitas.»'),
('nvi', 'Éxodo 17:15', 'Éxodo', 17, 15, 'Moisés edificó un altar y lo llamó «El SEÑOR es mi estandarte».'),
('nvi', 'Éxodo 17:16', 'Éxodo', 17, 16, 'Y exclamó: «¡Echa mano al estandarte del SEÑOR! ¡La guerra del SEÑOR contra Amalec será de generación en generación!»')
INSERT INTO bible_verses (version_id, ref, book, chapter, verse, text) VALUES
('nvi', 'Éxodo 18:1', 'Éxodo', 18, 1, 'Todo lo que Dios había hecho por Moisés y por su pueblo Israel, y la manera como el SEÑOR había sacado a Israel de Egipto, llegó a oídos de Jetro, sacerdote de Madián y suegro de Moisés.'),
('nvi', 'Éxodo 18:2', 'Éxodo', 18, 2, 'Cuando Moisés despidió a Séfora, su esposa, Jetro la recibió a ella'),
('nvi', 'Éxodo 18:3', 'Éxodo', 18, 3, 'y a sus dos hijos. Uno de ellos se llamaba Guersón, porque dijo Moisés: «Soy un extranjero en tierra extraña»;'),
('nvi', 'Éxodo 18:4', 'Éxodo', 18, 4, 'el otro se llamaba Eliezer, porque dijo: «El Dios de mi padre me ayudó y me salvó de la espada del faraón.»'),
('nvi', 'Éxodo 18:5', 'Éxodo', 18, 5, 'Jetro fue al desierto para ver a Moisés, que estaba acampando junto a la montaña de Dios. Lo acompañaban la esposa y los hijos de Moisés.'),
('nvi', 'Éxodo 18:6', 'Éxodo', 18, 6, 'Jetro le había avisado: «Yo, tu suegro Jetro, voy a verte. Me acompañan tu esposa y tus dos hijos.»'),
('nvi', 'Éxodo 18:7', 'Éxodo', 18, 7, 'Moisés salió al encuentro de su suegro, se inclinó delante de él y lo besó. Luego de intercambiar saludos y desearse lo mejor, entraron en la tienda de campaña.'),
('nvi', 'Éxodo 18:8', 'Éxodo', 18, 8, 'Allí Moisés le contó a su suegro todo lo que el SEÑOR les había hecho al faraón y a los egipcios en favor de Israel, todas las dificultades con que se habían encontrado en el camino, y cómo el SEÑOR los había salvado.'),
('nvi', 'Éxodo 18:9', 'Éxodo', 18, 9, 'Jetro se alegró de saber que el SEÑOR había tratado bien a Israel y lo había rescatado del poder de los egipcios,'),
('nvi', 'Éxodo 18:10', 'Éxodo', 18, 10, 'y exclamó: «¡Alabado sea el SEÑOR, que los salvó a ustedes del poder de los egipcios! ¡Alabado sea el que salvó a los israelitas del poder opresor del faraón!'),
('nvi', 'Éxodo 18:11', 'Éxodo', 18, 11, 'Ahora sé que el SEÑOR es más grande que todos los dioses, por lo que hizo a quienes trataron a Israel con arrogancia.»'),
('nvi', 'Éxodo 18:12', 'Éxodo', 18, 12, 'Dicho esto, Jetro le presentó a Dios un holocausto y otros sacrificios, y Aarón y todos los ancianos de Israel se sentaron a comer con el suegro de Moisés en presencia de Dios.'),
('nvi', 'Éxodo 18:13', 'Éxodo', 18, 13, 'Al día siguiente, Moisés ocupó su lugar como juez del pueblo, y los israelitas estuvieron de pie ante Moisés desde la mañana hasta la noche.'),
('nvi', 'Éxodo 18:14', 'Éxodo', 18, 14, 'Cuando su suegro vio cómo procedía Moisés con el pueblo, le dijo: —¡Pero qué es lo que haces con esta gente! ¿Cómo es que sólo tú te sientas, mientras todo este pueblo se queda de pie ante ti desde la mañana hasta la noche?'),
('nvi', 'Éxodo 18:15', 'Éxodo', 18, 15, '—Es que el pueblo viene a verme para consultar a Dios —le contestó Moisés—.'),
('nvi', 'Éxodo 18:16', 'Éxodo', 18, 16, 'Cuando tienen algún problema, me lo traen a mí para que yo dicte sentencia entre las dos partes. Además, les doy a conocer las leyes y las enseñanzas de Dios.'),
('nvi', 'Éxodo 18:17', 'Éxodo', 18, 17, '—No está bien lo que estás haciendo —le respondió su suegro—,'),
('nvi', 'Éxodo 18:18', 'Éxodo', 18, 18, 'pues te cansas tú y se cansa la gente que te acompaña. La tarea es demasiado pesada para ti; no la puedes desempeñar tú solo.'),
('nvi', 'Éxodo 18:19', 'Éxodo', 18, 19, 'Oye bien el consejo que voy a darte, y que Dios te ayude. Tú debes representar al pueblo ante Dios y presentarle los problemas que ellos tienen.'),
('nvi', 'Éxodo 18:20', 'Éxodo', 18, 20, 'A ellos los debes instruir en las leyes y en las enseñanzas de Dios, y darles a conocer la conducta que deben llevar y las obligaciones que deben cumplir.'),
('nvi', 'Éxodo 18:21', 'Éxodo', 18, 21, 'Elige tú mismo entre el pueblo hombres capaces y temerosos de Dios, que amen la verdad y aborrezcan las ganancias mal habidas, y desígnalos jefes de mil, de cien, de cincuenta y de diez personas.'),
('nvi', 'Éxodo 18:22', 'Éxodo', 18, 22, 'Serán ellos los que funjan como jueces de tiempo completo, atendiendo los casos sencillos, y los casos difíciles te los traerán a ti. Eso te aligerará la carga, porque te ayudarán a llevarla.'),
('nvi', 'Éxodo 18:23', 'Éxodo', 18, 23, 'Si pones esto en práctica y Dios así te lo ordena, podrás aguantar; el pueblo, por su parte, se irá a casa satisfecho.'),
('nvi', 'Éxodo 18:24', 'Éxodo', 18, 24, 'Moisés atendió a la voz de su suegro y siguió sus sugerencias.'),
('nvi', 'Éxodo 18:25', 'Éxodo', 18, 25, 'Escogió entre todos los israelitas hombres capaces, y los puso al frente de los israelitas como jefes de mil, cien, cincuenta y diez personas.'),
('nvi', 'Éxodo 18:26', 'Éxodo', 18, 26, 'Estos jefes fungían como jueces de tiempo completo, atendiendo los casos sencillos pero remitiendo a Moisés los casos difíciles.'),
('nvi', 'Éxodo 18:27', 'Éxodo', 18, 27, 'Más tarde Moisés despidió a su suegro, quien volvió entonces a su país.'),
('nvi', 'Éxodo 19:1', 'Éxodo', 19, 1, 'Los israelitas llegaron al desierto de Sinaí a los tres meses de haber salido de Egipto.'),
('nvi', 'Éxodo 19:2', 'Éxodo', 19, 2, 'Después de partir de Refidín, se internaron en el desierto de Sinaí, y allí en el desierto acamparon, frente al monte,'),
('nvi', 'Éxodo 19:3', 'Éxodo', 19, 3, 'al cual subió Moisés para encontrarse con Dios. Y desde allí lo llamó el SEÑOR y le dijo: «Anúnciale esto al pueblo de Jacob; declárale esto al pueblo de Israel:'),
('nvi', 'Éxodo 19:4', 'Éxodo', 19, 4, '“Ustedes son testigos de lo que hice con Egipto, y de que los he traído hacia mí como sobre alas de águila.'),
('nvi', 'Éxodo 19:5', 'Éxodo', 19, 5, 'Si ahora ustedes me son del todo obedientes, y cumplen mi pacto, serán mi propiedad exclusiva entre todas las naciones. Aunque toda la tierra me pertenece,'),
('nvi', 'Éxodo 19:6', 'Éxodo', 19, 6, 'ustedes serán para mí un reino de sacerdotes y una nación santa.”»Comunícales todo esto a los israelitas.»'),
('nvi', 'Éxodo 19:7', 'Éxodo', 19, 7, 'Moisés volvió y convocó a los ancianos del pueblo para exponerles todas estas palabras que el SEÑOR le había ordenado comunicarles,'),
('nvi', 'Éxodo 19:8', 'Éxodo', 19, 8, 'y todo el pueblo respondió a una sola voz: «Cumpliremos con todo lo que el SEÑOR nos ha ordenado.» Así que Moisés le llevó al SEÑOR la respuesta del pueblo,'),
('nvi', 'Éxodo 19:9', 'Éxodo', 19, 9, 'y el SEÑOR le dijo: —Voy a presentarme ante ti en medio de una densa nube, para que el pueblo me oiga hablar contigo y así tenga siempre confianza en ti. Moisés refirió al SEÑOR lo que el pueblo le había dicho,'),
('nvi', 'Éxodo 19:10', 'Éxodo', 19, 10, 'y el SEÑOR le dijo: —Ve y consagra al pueblo hoy y mañana. Diles que laven sus ropas'),
('nvi', 'Éxodo 19:11', 'Éxodo', 19, 11, 'y que se preparen para el tercer día, porque en ese mismo día yo descenderé sobre el monte Sinaí, a la vista de todo el pueblo.'),
('nvi', 'Éxodo 19:12', 'Éxodo', 19, 12, 'Pon un cerco alrededor del monte para que el pueblo no pase. Diles que no suban al monte, y que ni siquiera pongan un pie en él, pues cualquiera que lo toque será condenado a muerte.'),
('nvi', 'Éxodo 19:13', 'Éxodo', 19, 13, 'Sea hombre o animal, no quedará con vida. Quien se atreva a tocarlo, morirá a pedradas o a flechazos. Sólo podrán subir al monte cuando se oiga el toque largo de la trompeta.'),
('nvi', 'Éxodo 19:14', 'Éxodo', 19, 14, 'En cuanto Moisés bajó del monte, consagró al pueblo; ellos, por su parte, lavaron sus ropas.'),
('nvi', 'Éxodo 19:15', 'Éxodo', 19, 15, 'Luego Moisés les dijo: «Prepárense para el tercer día, y absténganse de relaciones sexuales.»'),
('nvi', 'Éxodo 19:16', 'Éxodo', 19, 16, 'En la madrugada del tercer día hubo truenos y relámpagos, y una densa nube se posó sobre el monte. Un toque muy fuerte de trompeta puso a temblar a todos los que estaban en el campamento.'),
('nvi', 'Éxodo 19:17', 'Éxodo', 19, 17, 'Entonces Moisés sacó del campamento al pueblo para que fuera a su encuentro con Dios, y ellos se detuvieron al pie del monte Sinaí.'),
('nvi', 'Éxodo 19:18', 'Éxodo', 19, 18, 'El monte estaba cubierto de humo, porque el SEÑOR había descendido sobre él en medio de fuego. Era tanto el humo que salía del monte, que parecía un horno; todo el monte se sacudía violentamente,'),
('nvi', 'Éxodo 19:19', 'Éxodo', 19, 19, 'y el sonido de la trompeta era cada vez más fuerte. Entonces habló Moisés, y Dios le respondió en el trueno.'),
('nvi', 'Éxodo 19:20', 'Éxodo', 19, 20, 'El SEÑOR descendió a la cumbre del monte Sinaí, y desde allí llamó a Moisés para que subiera. Cuando Moisés llegó a la cumbre,'),
('nvi', 'Éxodo 19:21', 'Éxodo', 19, 21, 'el SEÑOR le dijo: —Baja y advierte al pueblo que no intenten ir más allá del cerco para verme, no sea que muchos de ellos pierdan la vida.'),
('nvi', 'Éxodo 19:22', 'Éxodo', 19, 22, 'Hasta los sacerdotes que se acercan a mí deben consagrarse; de lo contrario, yo arremeteré contra ellos.'),
('nvi', 'Éxodo 19:23', 'Éxodo', 19, 23, 'Moisés le dijo al SEÑOR: —El pueblo no puede subir al monte Sinaí, pues tú mismo nos has advertido: “Pon un cerco alrededor del monte, y conságramelo.”'),
('nvi', 'Éxodo 19:24', 'Éxodo', 19, 24, 'El SEÑOR le respondió: —Baja y dile a Aarón que suba contigo. Pero ni los sacerdotes ni el pueblo deben intentar subir adonde estoy, pues de lo contrario, yo arremeteré contra ellos.'),
('nvi', 'Éxodo 19:25', 'Éxodo', 19, 25, 'Moisés bajó y repitió eso mismo al pueblo.'),
('nvi', 'Éxodo 20:1', 'Éxodo', 20, 1, 'Dios habló, y dio a conocer todos estos mandamientos:'),
('nvi', 'Éxodo 20:2', 'Éxodo', 20, 2, '«Yo soy el SEÑOR tu Dios. Yo te saqué de Egipto, del país donde eras esclavo.'),
('nvi', 'Éxodo 20:3', 'Éxodo', 20, 3, '»No tengas otros dioses además de mí.'),
('nvi', 'Éxodo 20:4', 'Éxodo', 20, 4, '»No te hagas ningún ídolo, ni nada que guarde semejanza con lo que hay arriba en el cielo, ni con lo que hay abajo en la tierra, ni con lo que hay en las aguas debajo de la tierra.'),
('nvi', 'Éxodo 20:5', 'Éxodo', 20, 5, 'No te inclines delante de ellos ni los adores. Yo, el SEÑOR tu Dios, soy un Dios celoso. Cuando los padres son malvados y me odian, yo castigo a sus hijos hasta la tercera y cuarta generación.'),
('nvi', 'Éxodo 20:6', 'Éxodo', 20, 6, 'Por el contrario, cuando me aman y cumplen mis mandamientos, les muestro mi amor por mil generaciones.'),
('nvi', 'Éxodo 20:7', 'Éxodo', 20, 7, '»No pronuncies el nombre del SEÑOR tu Dios a la ligera. Yo, el SEÑOR, no tendré por inocente a quien se atreva a pronunciar mi nombre a la ligera.'),
('nvi', 'Éxodo 20:8', 'Éxodo', 20, 8, '»Acuérdate del sábado, para consagrarlo.'),
('nvi', 'Éxodo 20:9', 'Éxodo', 20, 9, 'Trabaja seis días, y haz en ellos todo lo que tengas que hacer,'),
('nvi', 'Éxodo 20:10', 'Éxodo', 20, 10, 'pero el día séptimo será un día de reposo para honrar al SEÑOR tu Dios. No hagas en ese día ningún trabajo, ni tampoco tu hijo, ni tu hija, ni tu esclavo, ni tu esclava, ni tus animales, ni tampoco los extranjeros que vivan en tus ciudades.'),
('nvi', 'Éxodo 20:11', 'Éxodo', 20, 11, 'Acuérdate de que en seis días hizo el SEÑOR los cielos y la tierra, el mar y todo lo que hay en ellos, y que descansó el séptimo día. Por eso el SEÑOR bendijo y consagró el día de reposo.'),
('nvi', 'Éxodo 20:12', 'Éxodo', 20, 12, '»Honra a tu padre y a tu madre, para que disfrutes de una larga vida en la tierra que te da el SEÑOR tu Dios.'),
('nvi', 'Éxodo 20:13', 'Éxodo', 20, 13, '»No mates.'),
('nvi', 'Éxodo 20:14', 'Éxodo', 20, 14, '»No cometas adulterio.'),
('nvi', 'Éxodo 20:15', 'Éxodo', 20, 15, '»No robes.'),
('nvi', 'Éxodo 20:16', 'Éxodo', 20, 16, '»No des falso testimonio en contra de tu prójimo.'),
('nvi', 'Éxodo 20:17', 'Éxodo', 20, 17, '»No codicies la casa de tu prójimo: No codicies su esposa, ni su esclavo, ni su esclava, ni su buey, ni su burro, ni nada que le pertenezca.»'),
('nvi', 'Éxodo 20:18', 'Éxodo', 20, 18, 'Ante ese espectáculo de truenos y relámpagos, de sonidos de trompeta y de la montaña envuelta en humo, los israelitas temblaban de miedo y se mantenían a distancia.'),
('nvi', 'Éxodo 20:19', 'Éxodo', 20, 19, 'Así que le suplicaron a Moisés: —Háblanos tú, y te escucharemos. Si Dios nos habla, seguramente moriremos.'),
('nvi', 'Éxodo 20:20', 'Éxodo', 20, 20, '—No tengan miedo —les respondió Moisés—. Dios ha venido a ponerlos a prueba, para que sientan temor de él y no pequen.'),
('nvi', 'Éxodo 20:21', 'Éxodo', 20, 21, 'Entonces Moisés se acercó a la densa oscuridad en la que estaba Dios, pero los israelitas se mantuvieron a distancia.'),
('nvi', 'Éxodo 20:22', 'Éxodo', 20, 22, 'El SEÑOR le ordenó a Moisés: «Diles lo siguiente a los israelitas: “Ustedes mismos han oído que les he hablado desde el cielo.'),
('nvi', 'Éxodo 20:23', 'Éxodo', 20, 23, 'No me ofendan; no se hagan dioses de plata o de oro, ni los adoren.'),
('nvi', 'Éxodo 20:24', 'Éxodo', 20, 24, 'Háganme un altar de tierra, y ofrézcanme sobre él sus holocaustos y sacrificios de comunión, sus ovejas y sus toros. Yo vendré al lugar donde les pida invocar mi nombre, y los bendeciré.'),
('nvi', 'Éxodo 20:25', 'Éxodo', 20, 25, 'Si me hacen un altar de piedra, no lo construyan con piedras labradas, pues las herramientas profanan la piedra.'),
('nvi', 'Éxodo 20:26', 'Éxodo', 20, 26, 'Y no le pongan escalones a mi altar, no sea que al subir se les vean los genitales.”'),
('nvi', 'Éxodo 21:1', 'Éxodo', 21, 1, '»Éstas son las leyes que tú les expondrás:'),
('nvi', 'Éxodo 21:2', 'Éxodo', 21, 2, '»Si alguien compra un esclavo hebreo, éste le servirá durante seis años, pero en el séptimo año recobrará su libertad sin pagar nada a cambio.'),
('nvi', 'Éxodo 21:3', 'Éxodo', 21, 3, '»Si el esclavo llega soltero, soltero se irá. »Si llega casado, su esposa se irá con él.'),
('nvi', 'Éxodo 21:4', 'Éxodo', 21, 4, '»Si el amo le da mujer al esclavo, como ella es propiedad del amo, serán también del amo los hijos o hijas que el esclavo tenga con ella. Así que el esclavo se irá solo.'),
('nvi', 'Éxodo 21:5', 'Éxodo', 21, 5, '»Si el esclavo llega a declarar: “Yo no quiero recobrar mi libertad, pues les tengo cariño a mi amo, a mi mujer y a mis hijos”,'),
('nvi', 'Éxodo 21:6', 'Éxodo', 21, 6, 'el amo lo hará comparecer ante los jueces, luego lo llevará a una puerta, o al marco de una puerta, y allí le horadará la oreja con un punzón. Así el esclavo se quedará de por vida con su amo.'),
('nvi', 'Éxodo 21:7', 'Éxodo', 21, 7, '»Si alguien vende a su hija como esclava, la muchacha no se podrá ir como los esclavos varones.'),
('nvi', 'Éxodo 21:8', 'Éxodo', 21, 8, '»Si el amo no toma a la muchacha como mujer por no ser ella de su agrado, deberá permitir que sea rescatada. Como la rechazó, no podrá vendérsela a ningún extranjero.'),
('nvi', 'Éxodo 21:9', 'Éxodo', 21, 9, '»Si el amo entrega la muchacha a su hijo, deberá tratarla con todos los derechos de una hija.'),
('nvi', 'Éxodo 21:10', 'Éxodo', 21, 10, '»Si toma como esposa a otra mujer, no podrá privar a su primera esposa de sus derechos conyugales, ni de alimentación y vestido.'),
('nvi', 'Éxodo 21:11', 'Éxodo', 21, 11, '»Si no le provee esas tres cosas, la mujer podrá irse sin que se pague nada por ella.'),
('nvi', 'Éxodo 21:12', 'Éxodo', 21, 12, '»El que hiera a otro y lo mate será condenado a muerte.'),
('nvi', 'Éxodo 21:13', 'Éxodo', 21, 13, '»Si el homicidio no fue intencional, pues ya estaba de Dios que ocurriera, el asesino podrá huir al lugar que yo designaré.'),
('nvi', 'Éxodo 21:14', 'Éxodo', 21, 14, '»Si el homicidio es premeditado, el asesino será condenado a muerte aun cuando busque refugio en mi altar.'),
('nvi', 'Éxodo 21:15', 'Éxodo', 21, 15, '»El que mate a su padre o a su madre será condenado a muerte.'),
('nvi', 'Éxodo 21:16', 'Éxodo', 21, 16, '»El que secuestre a otro y lo venda, o al ser descubierto lo tenga aún en su poder, será condenado a muerte.'),
('nvi', 'Éxodo 21:17', 'Éxodo', 21, 17, '»El que maldiga a su padre o a su madre será condenado a muerte.'),
('nvi', 'Éxodo 21:18', 'Éxodo', 21, 18, '»Si en una riña alguien golpea a otro con una piedra, o con el puño, y el herido no muere pero se ve obligado a guardar cama,'),
('nvi', 'Éxodo 21:19', 'Éxodo', 21, 19, 'el agresor deberá indemnizar al herido por daños y perjuicios. Sin embargo, quedará libre de culpa si el herido se levanta y puede caminar por sí mismo o con la ayuda de un bastón.'),
('nvi', 'Éxodo 21:20', 'Éxodo', 21, 20, '»Si alguien golpea con un palo a su esclavo o a su esclava, y como resultado del golpe él o ella muere, su crimen será castigado.'),
('nvi', 'Éxodo 21:21', 'Éxodo', 21, 21, 'Pero si después de uno o dos días el esclavo se recupera, el agresor no será castigado porque el esclavo era de su propiedad.'),
('nvi', 'Éxodo 21:22', 'Éxodo', 21, 22, '»Si en una riña los contendientes golpean a una mujer encinta, y la hacen abortar pero sin poner en peligro su vida, se les impondrá la multa que el marido de la mujer exija y que en justicia le corresponda.'),
('nvi', 'Éxodo 21:23', 'Éxodo', 21, 23, '»Si se pone en peligro la vida de la mujer, ésta será la indemnización: vida por vida,'),
('nvi', 'Éxodo 21:24', 'Éxodo', 21, 24, 'ojo por ojo, diente por diente, mano por mano, pie por pie,'),
('nvi', 'Éxodo 21:25', 'Éxodo', 21, 25, 'quemadura por quemadura, golpe por golpe, herida por herida.'),
('nvi', 'Éxodo 21:26', 'Éxodo', 21, 26, '»Si alguien golpea en el ojo a su esclavo o a su esclava, y se lo saca, en compensación por el ojo los pondrá en libertad.'),
('nvi', 'Éxodo 21:27', 'Éxodo', 21, 27, '»Si alguien le rompe un diente a su esclavo o a su esclava, en compensación por el diente los pondrá en libertad.'),
('nvi', 'Éxodo 21:28', 'Éxodo', 21, 28, '»Si un toro cornea y mata a un hombre o a una mujer, se matará al toro a pedradas y no se comerá su carne. En tal caso, no se hará responsable al dueño del toro.'),
('nvi', 'Éxodo 21:29', 'Éxodo', 21, 29, '»Si el toro tiene la costumbre de cornear, se le matará a pedradas si llega a matar a un hombre o a una mujer. Si su dueño sabía de la costumbre del toro, pero no lo mantuvo sujeto, también será condenado a muerte.'),
('nvi', 'Éxodo 21:30', 'Éxodo', 21, 30, '»Si a cambio de su vida se le exige algún pago, deberá pagarlo.'),
('nvi', 'Éxodo 21:31', 'Éxodo', 21, 31, '»Esta misma ley se aplicará en caso de que el toro cornee a un muchacho o a una muchacha.'),
('nvi', 'Éxodo 21:32', 'Éxodo', 21, 32, '»Si el toro cornea a un esclavo o a una esclava, el dueño del toro deberá pagarle treinta monedas de plata al amo del esclavo o de la esclava. El toro será apedreado.'),
('nvi', 'Éxodo 21:33', 'Éxodo', 21, 33, '»Si alguien deja abierto un pozo, o cava un pozo y no lo tapa, y llegan a caerse en él un buey o un asno,'),
('nvi', 'Éxodo 21:34', 'Éxodo', 21, 34, 'el dueño del pozo indemnizará al dueño del animal, y podrá quedarse con el animal muerto.'),
('nvi', 'Éxodo 21:35', 'Éxodo', 21, 35, '»Si un toro cornea a otro toro, y el toro corneado muere, se venderá el toro vivo, y los dos dueños se repartirán por partes iguales el dinero y el animal muerto.'),
('nvi', 'Éxodo 21:36', 'Éxodo', 21, 36, '»Si el toro tenía la maña de cornear, y su dueño le conocía esta maña pero no lo mantuvo amarrado, tendrá que pagar por el animal muerto con un animal vivo, pero podrá quedarse con el animal muerto.'),
('nvi', 'Éxodo 22:1', 'Éxodo', 22, 1, '»Si alguien roba un toro o una oveja, y lo mata o lo vende, deberá devolver cinco cabezas de ganado por el toro, y cuatro ovejas por la oveja.'),
('nvi', 'Éxodo 22:2', 'Éxodo', 22, 2, '»Si a alguien se le sorprende robando, y se le mata, su muerte no se considerará homicidio.'),
('nvi', 'Éxodo 22:3', 'Éxodo', 22, 3, '»Si se mata al ladrón a plena luz del día, su muerte se considerará homicidio. »El ladrón está obligado a restituir lo robado. Si no tiene con qué hacerlo, será vendido para restituir lo robado.'),
('nvi', 'Éxodo 22:4', 'Éxodo', 22, 4, '»Si el animal robado se halla en su poder y todavía con vida, deberá restituirlo doble, ya sea que se trate de un toro, un asno o una oveja.'),
('nvi', 'Éxodo 22:5', 'Éxodo', 22, 5, '»Si alguien apacienta su ganado en un campo o en una viña, y por dejar a sus animales sueltos ellos pastan en campo ajeno, el dueño del animal deberá reparar el daño con lo mejor de su cosecha.'),
('nvi', 'Éxodo 22:6', 'Éxodo', 22, 6, '»Si se prende fuego en pasto seco, y el fuego se propaga y quema algún trigal, o el trigo ya apilado, o algún campo sembrado, el que haya comenzado el fuego deberá reparar el daño.'),
('nvi', 'Éxodo 22:7', 'Éxodo', 22, 7, '»Si alguien deja dinero o bienes en la casa de un amigo, y esos bienes le son robados, el ladrón deberá devolver el doble, en caso de que lo atrapen.'),
('nvi', 'Éxodo 22:8', 'Éxodo', 22, 8, '»Si no se atrapa al ladrón, el dueño de la casa deberá comparecer ante los jueces para que se determine si no dispuso de los bienes del otro.'),
('nvi', 'Éxodo 22:9', 'Éxodo', 22, 9, '»En todos los casos de posesión ilegal, las dos partes deberán llevar el asunto ante los jueces. El que sea declarado culpable deberá restituir el doble a su prójimo, ya sea que se trate de un toro, o de un asno, o de una oveja, o de ropa, o de cualquier otra cosa perdida que alguien reclame como de su propiedad.'),
('nvi', 'Éxodo 22:10', 'Éxodo', 22, 10, '»Si alguien deja al cuidado de algún amigo suyo un asno, un toro, una oveja, o cualquier otro animal, y el animal muere, o sufre algún daño, o es robado sin que nadie lo vea,'),
('nvi', 'Éxodo 22:11', 'Éxodo', 22, 11, 'el amigo del dueño jurará ante el SEÑOR no haberse adueñado de la propiedad de su amigo. El dueño deberá aceptar ese juramento, y el amigo no deberá restituirle nada.'),
('nvi', 'Éxodo 22:12', 'Éxodo', 22, 12, '»Si el animal le fue robado al amigo, éste deberá indemnizar al dueño.'),
('nvi', 'Éxodo 22:13', 'Éxodo', 22, 13, '»Si el animal fue despedazado por una fiera, el amigo no tendrá que indemnizar al dueño si presenta como evidencia los restos del animal.'),
('nvi', 'Éxodo 22:14', 'Éxodo', 22, 14, '»Si alguien pide prestado un animal de algún amigo suyo, y el animal sufre algún daño, o muere, no estando presente su dueño, el que lo pidió prestado deberá restituirlo.'),
('nvi', 'Éxodo 22:15', 'Éxodo', 22, 15, '»Si el dueño del animal estaba presente, el que pidió prestado el animal no tendrá que pagar nada. »Si el animal fue alquilado, el precio del alquiler cubrirá la pérdida.'),
('nvi', 'Éxodo 22:16', 'Éxodo', 22, 16, '»Si alguien seduce a una mujer virgen que no esté comprometida para casarse, y se acuesta con ella, deberá pagarle su precio al padre y tomarla por esposa.'),
('nvi', 'Éxodo 22:17', 'Éxodo', 22, 17, 'Aun si el padre se niega a entregársela, el seductor deberá pagar el precio establecido para las vírgenes.'),
('nvi', 'Éxodo 22:18', 'Éxodo', 22, 18, '»No dejes con vida a ninguna hechicera.'),
('nvi', 'Éxodo 22:19', 'Éxodo', 22, 19, '»Todo el que tenga relaciones sexuales con un animal será condenado a muerte.'),
('nvi', 'Éxodo 22:20', 'Éxodo', 22, 20, '»Todo el que ofrezca sacrificios a otros dioses, en vez de ofrecérselos al SEÑOR, será condenado a muerte.'),
('nvi', 'Éxodo 22:21', 'Éxodo', 22, 21, '»No maltrates ni oprimas a los extranjeros, pues también tú y tu pueblo fueron extranjeros en Egipto.'),
('nvi', 'Éxodo 22:22', 'Éxodo', 22, 22, '»No explotes a las viudas ni a los huérfanos,'),
('nvi', 'Éxodo 22:23', 'Éxodo', 22, 23, 'porque si tú y tu pueblo lo hacen, y ellos me piden ayuda, yo te aseguro que atenderé a su clamor:'),
('nvi', 'Éxodo 22:24', 'Éxodo', 22, 24, 'arderá mi furor y los mataré a ustedes a filo de espada. ¡Y sus mujeres se quedarán viudas, y sus hijos se quedarán huérfanos!'),
('nvi', 'Éxodo 22:25', 'Éxodo', 22, 25, '»Si uno de ustedes presta dinero a algún necesitado de mi pueblo, no deberá tratarlo como los prestamistas ni le cobrará intereses.'),
('nvi', 'Éxodo 22:26', 'Éxodo', 22, 26, '»Si alguien toma en prenda el manto de su prójimo, deberá devolvérselo al caer la noche.'),
('nvi', 'Éxodo 22:27', 'Éxodo', 22, 27, 'Ese manto es lo único que tiene para abrigarse; no tiene otra cosa sobre la cual dormir. Si se queja ante mí, yo atenderé a su clamor, pues soy un Dios compasivo.'),
('nvi', 'Éxodo 22:28', 'Éxodo', 22, 28, '»No blasfemes nunca contra Dios, ni maldigas al jefe de tu pueblo.'),
('nvi', 'Éxodo 22:29', 'Éxodo', 22, 29, '»No te demores en presentarme las ofrendas de tus graneros y de tus lagares. »Tus hijos primogénitos serán para mí.'),
('nvi', 'Éxodo 22:30', 'Éxodo', 22, 30, '»También serán para mí tus toros y tus ovejas. Los dejarás con sus madres siete días, pero al octavo día me los entregarás.'),
('nvi', 'Éxodo 22:31', 'Éxodo', 22, 31, '»Ustedes serán mi pueblo santo. »No comerán la carne de ningún animal que haya sido despedazado por las fieras. Esa carne se la echarán a los perros.'),
('nvi', 'Éxodo 23:1', 'Éxodo', 23, 1, '»No divulgues informes falsos. »No te hagas cómplice del malvado ni apoyes los testimonios del violento.'),
('nvi', 'Éxodo 23:2', 'Éxodo', 23, 2, '»No imites la maldad de las mayorías. »No te dejes llevar por la mayoría en un proceso legal. »No perviertas la justicia tomando partido con la mayoría.'),
('nvi', 'Éxodo 23:3', 'Éxodo', 23, 3, '»No seas parcial con el pobre en sus demandas legales.'),
('nvi', 'Éxodo 23:4', 'Éxodo', 23, 4, '»Si encuentras un toro o un asno perdido, devuélvelo, aunque sea de tu enemigo.'),
('nvi', 'Éxodo 23:5', 'Éxodo', 23, 5, '»Si ves un asno caído bajo el peso de su carga, no lo dejes así; ayúdalo, aunque sea de tu enemigo.'),
('nvi', 'Éxodo 23:6', 'Éxodo', 23, 6, '»No tuerzas la justicia contra los pobres de tu pueblo en sus demandas legales.'),
('nvi', 'Éxodo 23:7', 'Éxodo', 23, 7, '»Manténte al margen de cuestiones fraudulentas. »No le quites la vida al que es inocente y honrado, porque yo no absuelvo al malvado.'),
('nvi', 'Éxodo 23:8', 'Éxodo', 23, 8, '»No aceptes soborno, porque nubla la vista y tuerce las sentencias justas.'),
('nvi', 'Éxodo 23:9', 'Éxodo', 23, 9, '»No opriman al extranjero, pues ya lo han experimentado en carne propia: ustedes mismos fueron extranjeros en Egipto.'),
('nvi', 'Éxodo 23:10', 'Éxodo', 23, 10, '»Seis años sembrarás tus campos y recogerás tus cosechas,'),
('nvi', 'Éxodo 23:11', 'Éxodo', 23, 11, 'pero el séptimo año no cultivarás la tierra. Déjala descansar, para que la gente pobre del pueblo obtenga de ella su alimento, y para que los animales del campo se coman lo que la gente deje. »Haz lo mismo con tus viñas y con tus olivares.'),
('nvi', 'Éxodo 23:12', 'Éxodo', 23, 12, '»Seis días trabajarás, pero el día séptimo descansarán tus bueyes y tus asnos, y recobrarán sus fuerzas los esclavos nacidos en casa y los extranjeros.'),
('nvi', 'Éxodo 23:13', 'Éxodo', 23, 13, '»Cumplan con todo lo que les he ordenado. »No invoquen los nombres de otros dioses. Jamás los pronuncien.'),
('nvi', 'Éxodo 23:14', 'Éxodo', 23, 14, '»Tres veces al año harás fiesta en mi honor.'),
('nvi', 'Éxodo 23:15', 'Éxodo', 23, 15, '»La fiesta de los Panes sin levadura la celebrarás en el mes de aviv, que es la fecha establecida. Fue en ese mes cuando ustedes salieron de Egipto. De acuerdo con mis instrucciones, siete días comerán pan sin levadura. »Nadie se presentará ante mí con las manos vacías.'),
('nvi', 'Éxodo 23:16', 'Éxodo', 23, 16, '»La fiesta de la cosecha la celebrarás cuando recojas las primicias de tus siembras. »La fiesta de recolección de fin de año la celebrarás cuando recojas tus cosechas.'),
('nvi', 'Éxodo 23:17', 'Éxodo', 23, 17, '»Tres veces al año todo varón se presentará ante mí, su SEÑOR y Dios.'),
('nvi', 'Éxodo 23:18', 'Éxodo', 23, 18, '»No mezcles con levadura la sangre del sacrificio que me ofrezcas. »No guardes hasta el día siguiente la grasa que me ofreces en las fiestas.'),
('nvi', 'Éxodo 23:19', 'Éxodo', 23, 19, '»Llevarás a la casa del SEÑOR tu Dios lo mejor de tus primicias. »No cocerás ningún cabrito en la leche de su madre.'),
('nvi', 'Éxodo 23:20', 'Éxodo', 23, 20, '»Date cuenta, Israel, que yo envío mi ángel delante de ti, para que te proteja en el camino y te lleve al lugar que te he preparado.'),
('nvi', 'Éxodo 23:21', 'Éxodo', 23, 21, 'Préstale atención y obedécelo. No te rebeles contra él, porque va en representación mía y no perdonará tu rebelión.'),
('nvi', 'Éxodo 23:22', 'Éxodo', 23, 22, 'Si lo obedeces y cumples con todas mis instrucciones, seré enemigo de tus enemigos y me opondré a quienes se te opongan.'),
('nvi', 'Éxodo 23:23', 'Éxodo', 23, 23, 'Mi ángel te guiará y te introducirá en la tierra de estos pueblos que voy a exterminar: tierra de amorreos, hititas, ferezeos, cananeos, heveos y jebuseos.'),
('nvi', 'Éxodo 23:24', 'Éxodo', 23, 24, '»No te inclines ante los dioses de esos pueblos. No les rindas culto ni imites sus prácticas. Más bien, derriba sus ídolos y haz pedazos sus piedras sagradas.'),
('nvi', 'Éxodo 23:25', 'Éxodo', 23, 25, '»Adora al SEÑOR tu Dios, y él bendecirá tu pan y tu agua. »Yo apartaré de ustedes toda enfermedad.'),
('nvi', 'Éxodo 23:26', 'Éxodo', 23, 26, '»En tu país ninguna mujer abortará ni será estéril. ¡Yo te concederé larga vida!'),
('nvi', 'Éxodo 23:27', 'Éxodo', 23, 27, '»En toda nación donde pongas el pie haré que tus enemigos te tengan miedo, se turben y huyan de ti.'),
('nvi', 'Éxodo 23:28', 'Éxodo', 23, 28, '»Delante de ti enviaré avispas, para que ahuyenten a los heveos, cananeos e hititas.'),
('nvi', 'Éxodo 23:29', 'Éxodo', 23, 29, 'Sin embargo, no los desalojaré en un solo año, no sea que, al quedarse desolada la tierra, aumente el número de animales salvajes y te ataquen.'),
('nvi', 'Éxodo 23:30', 'Éxodo', 23, 30, 'Los desalojaré poco a poco, hasta que seas lo bastante fuerte para tomar posesión de la tierra.'),
('nvi', 'Éxodo 23:31', 'Éxodo', 23, 31, '»Extenderé las fronteras de tu país, desde el Mar Rojo hasta el mar Mediterráneo, y desde el desierto hasta el río Éufrates. Pondré bajo tu dominio a los que habitan allí, y tú los desalojarás.'),
('nvi', 'Éxodo 23:32', 'Éxodo', 23, 32, '»No hagas ningún pacto con ellos ni con sus dioses.'),
('nvi', 'Éxodo 23:33', 'Éxodo', 23, 33, '»Si los dejas vivir en tu tierra, te pondrán una trampa para que adores a sus dioses, y acabarás pecando contra mí.»'),
('nvi', 'Éxodo 24:1', 'Éxodo', 24, 1, 'También le dijo el SEÑOR a Moisés: «Sube al monte a verme, junto con Aarón, Nadab y Abiú, y setenta de los ancianos de Israel. Ellos podrán arrodillarse a cierta distancia,'),
('nvi', 'Éxodo 24:2', 'Éxodo', 24, 2, 'pero sólo tú, Moisés, podrás acercarte a mí. El resto del pueblo no deberá acercarse ni subir contigo.»'),
('nvi', 'Éxodo 24:3', 'Éxodo', 24, 3, 'Moisés fue y refirió al pueblo todas las palabras y disposiciones del SEÑOR, y ellos respondieron a una voz: «Haremos todo lo que el SEÑOR ha dicho.»'),
('nvi', 'Éxodo 24:4', 'Éxodo', 24, 4, 'Moisés puso entonces por escrito lo que el SEÑOR había dicho. A la mañana siguiente, madrugó y levantó un altar al pie del monte, y en representación de las doce tribus de Israel consagró doce piedras.'),
('nvi', 'Éxodo 24:5', 'Éxodo', 24, 5, 'Luego envió a unos jóvenes israelitas para que ofrecieran al SEÑOR novillos como holocaustos y sacrificios de comunión.'),
('nvi', 'Éxodo 24:6', 'Éxodo', 24, 6, 'La mitad de la sangre la echó Moisés en unos tazones, y la otra mitad la roció sobre el altar.'),
('nvi', 'Éxodo 24:7', 'Éxodo', 24, 7, 'Después tomó el libro del pacto y lo leyó ante el pueblo, y ellos respondieron: —Haremos todo lo que el SEÑOR ha dicho, y le obedeceremos.'),
('nvi', 'Éxodo 24:8', 'Éxodo', 24, 8, 'Moisés tomó la sangre, roció al pueblo con ella y dijo: —Ésta es la sangre del pacto que, con base en estas palabras, el SEÑOR ha hecho con ustedes.'),
('nvi', 'Éxodo 24:9', 'Éxodo', 24, 9, 'Moisés y Aarón, Nadab y Abiú, y los setenta ancianos de Israel subieron'),
('nvi', 'Éxodo 24:10', 'Éxodo', 24, 10, 'y vieron al Dios de Israel. Bajo sus pies había una especie de pavimento de zafiro, tan claro como el cielo mismo.'),
('nvi', 'Éxodo 24:11', 'Éxodo', 24, 11, 'Y a pesar de que estos jefes de los israelitas vieron a Dios, siguieron con vida, pues Dios no alzó su mano contra ellos.'),
('nvi', 'Éxodo 24:12', 'Éxodo', 24, 12, 'El SEÑOR le dijo a Moisés: «Sube a encontrarte conmigo en el monte, y quédate allí. Voy a darte las tablas con la ley y los mandamientos que he escrito para guiarlos en la vida.»'),
('nvi', 'Éxodo 24:13', 'Éxodo', 24, 13, 'Moisés subió al monte de Dios, acompañado por su asistente Josué,'),
('nvi', 'Éxodo 24:14', 'Éxodo', 24, 14, 'pero a los ancianos les dijo: «Esperen aquí hasta que volvamos. Aarón y Jur se quedarán aquí con ustedes. Si alguno tiene un problema, que acuda a ellos.»'),
('nvi', 'Éxodo 24:15', 'Éxodo', 24, 15, 'En cuanto Moisés subió, una nube cubrió el monte,'),
('nvi', 'Éxodo 24:16', 'Éxodo', 24, 16, 'y la gloria del SEÑOR se posó sobre el Sinaí. Seis días la nube cubrió el monte. Al séptimo día, desde el interior de la nube el SEÑOR llamó a Moisés.'),
('nvi', 'Éxodo 24:17', 'Éxodo', 24, 17, 'A los ojos de los israelitas, la gloria del SEÑOR en la cumbre del monte parecía un fuego consumidor.'),
('nvi', 'Éxodo 24:18', 'Éxodo', 24, 18, 'Moisés se internó en la nube y subió al monte, y allí permaneció cuarenta días y cuarenta noches.'),
('nvi', 'Éxodo 25:1', 'Éxodo', 25, 1, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 25:2', 'Éxodo', 25, 2, '«Ordénales a los israelitas que me traigan una ofrenda. La deben presentar todos los que sientan deseos de traérmela.'),
('nvi', 'Éxodo 25:3', 'Éxodo', 25, 3, 'Como ofrenda se les aceptará lo siguiente: oro, plata, bronce,'),
('nvi', 'Éxodo 25:4', 'Éxodo', 25, 4, 'lana teñida de púrpura, carmesí y escarlata; lino fino, pelo de cabra,'),
('nvi', 'Éxodo 25:5', 'Éxodo', 25, 5, 'pieles de carnero teñidas de rojo, pieles de delfín, madera de acacia,'),
('nvi', 'Éxodo 25:6', 'Éxodo', 25, 6, 'aceite para las lámparas, especias para aromatizar el aceite de la unción y el incienso,'),
('nvi', 'Éxodo 25:7', 'Éxodo', 25, 7, 'y piedras de ónice y otras piedras preciosas para adornar el efod y el pectoral del sacerdote.'),
('nvi', 'Éxodo 25:8', 'Éxodo', 25, 8, 'Después me harán un santuario, para que yo habite entre ustedes.'),
('nvi', 'Éxodo 25:9', 'Éxodo', 25, 9, 'El santuario y todo su mobiliario deberán ser una réplica exacta del modelo que yo te mostraré.'),
('nvi', 'Éxodo 25:10', 'Éxodo', 25, 10, '»Haz un arca de madera de acacia, de un metro con diez centímetros de largo, setenta centímetros de ancho y setenta centímetros de alto.'),
('nvi', 'Éxodo 25:11', 'Éxodo', 25, 11, 'Recúbrela de oro puro por dentro y por fuera, y ponle en su derredor una moldura de oro.'),
('nvi', 'Éxodo 25:12', 'Éxodo', 25, 12, 'Funde cuatro anillos de oro para colocarlos en sus cuatro patas, dos en cada costado.'),
('nvi', 'Éxodo 25:13', 'Éxodo', 25, 13, 'Prepara luego unas varas de madera de acacia, y recúbrelas de oro.'),
('nvi', 'Éxodo 25:14', 'Éxodo', 25, 14, 'Introduce las varas en los anillos que van a los costados del arca, para transportarla.'),
('nvi', 'Éxodo 25:15', 'Éxodo', 25, 15, 'Deja las varas en los anillos del arca, y no las saques de allí,'),
('nvi', 'Éxodo 25:16', 'Éxodo', 25, 16, 'y pon dentro del arca la ley que voy a entregarte.'),
('nvi', 'Éxodo 25:17', 'Éxodo', 25, 17, '»Haz un propiciatorio de oro puro, de un metro con diez centímetros de largo por setenta centímetros de ancho,'),
('nvi', 'Éxodo 25:18', 'Éxodo', 25, 18, 'y también dos querubines de oro labrado a martillo, para los dos extremos del propiciatorio.'),
('nvi', 'Éxodo 25:19', 'Éxodo', 25, 19, 'En cada uno de los extremos irá un querubín. Hazlos de modo que formen una sola pieza con el propiciatorio.'),
('nvi', 'Éxodo 25:20', 'Éxodo', 25, 20, '»Los querubines deberán tener las alas extendidas por encima del propiciatorio, y cubrirlo con ellas. Quedarán el uno frente al otro, mirando hacia el propiciatorio.'),
('nvi', 'Éxodo 25:21', 'Éxodo', 25, 21, '»Coloca el propiciatorio encima del arca, y pon dentro de ella la ley que voy a entregarte.'),
('nvi', 'Éxodo 25:22', 'Éxodo', 25, 22, 'Yo me reuniré allí contigo en medio de los dos querubines que están sobre el arca del pacto. Desde la parte superior del propiciatorio te daré todas las instrucciones que habrás de comunicarles a los israelitas.'),
('nvi', 'Éxodo 25:23', 'Éxodo', 25, 23, '»Haz una mesa de madera de acacia, de noventa centímetros de largo por cuarenta y cinco de ancho y setenta de alto.'),
('nvi', 'Éxodo 25:24', 'Éxodo', 25, 24, 'Recúbrela de oro puro, y ponle en su derredor una moldura de oro.'),
('nvi', 'Éxodo 25:25', 'Éxodo', 25, 25, 'Haz también un reborde de veinte centímetros de ancho, y una moldura de oro para ponerla alrededor del reborde.'),
('nvi', 'Éxodo 25:26', 'Éxodo', 25, 26, '»Haz cuatro anillos de oro para la mesa, y sujétalos a sus cuatro esquinas, donde van las cuatro patas.'),
('nvi', 'Éxodo 25:27', 'Éxodo', 25, 27, 'Los anillos deben quedar junto al reborde, a fin de que por ellos pasen las varas para transportar la mesa.'),
('nvi', 'Éxodo 25:28', 'Éxodo', 25, 28, '»Esas varas deben ser de madera de acacia, y estar recubiertas de oro.'),
('nvi', 'Éxodo 25:29', 'Éxodo', 25, 29, 'También deben ser de oro puro sus platos y sus bandejas, así como sus jarras y tazones para verter las ofrendas.'),
('nvi', 'Éxodo 25:30', 'Éxodo', 25, 30, 'Sobre la mesa pondrás el pan de la Presencia, para que esté ante mí siempre.'),
('nvi', 'Éxodo 25:31', 'Éxodo', 25, 31, '»Haz un candelabro de oro puro labrado a martillo. Su base, su tallo y sus copas, cálices y flores, formarán una sola pieza.'),
('nvi', 'Éxodo 25:32', 'Éxodo', 25, 32, 'Seis de sus brazos se abrirán a los costados, tres de un lado y tres del otro.'),
('nvi', 'Éxodo 25:33', 'Éxodo', 25, 33, 'Cada uno de los seis brazos del candelabro tendrá tres copas en forma de flor de almendro, con cálices y pétalos.'),
('nvi', 'Éxodo 25:34', 'Éxodo', 25, 34, 'El candelabro mismo tendrá cuatro copas en forma de flor de almendro, con cálices y pétalos.'),
('nvi', 'Éxodo 25:35', 'Éxodo', 25, 35, 'Cada uno de los tres pares de brazos tendrá un cáliz en la parte inferior, donde se unen con el tallo del candelabro.'),
('nvi', 'Éxodo 25:36', 'Éxodo', 25, 36, 'Los cálices y los brazos deben formar una sola pieza con el candelabro, y ser de oro puro labrado a martillo.'),
('nvi', 'Éxodo 25:37', 'Éxodo', 25, 37, '»Hazle también sus siete lámparas, y colócalas de tal modo que alumbren hacia el frente.'),
('nvi', 'Éxodo 25:38', 'Éxodo', 25, 38, 'Sus cortapabilos y braseros deben ser de oro puro.'),
('nvi', 'Éxodo 25:39', 'Éxodo', 25, 39, 'Para hacer el candelabro y todos estos accesorios se usarán treinta y tres kilos de oro puro.'),
('nvi', 'Éxodo 25:40', 'Éxodo', 25, 40, '»Procura que todo esto sea una réplica exacta de lo que se te mostró en el monte.'),
('nvi', 'Éxodo 26:1', 'Éxodo', 26, 1, '»Haz el santuario con diez cortinas de lino fino y de lana teñida de púrpura, carmesí y escarlata, con dos querubines artísticamente bordados en ellas.'),
('nvi', 'Éxodo 26:2', 'Éxodo', 26, 2, 'Todas las cortinas deben medir lo mismo, es decir, doce metros y medio de largo por un metro con ochenta centímetros de ancho.'),
('nvi', 'Éxodo 26:3', 'Éxodo', 26, 3, '»Cose cinco cortinas, uniendo la una con la otra por el borde, y haz lo mismo con las otras cinco.'),
('nvi', 'Éxodo 26:4', 'Éxodo', 26, 4, 'En el borde superior del primer conjunto de cortinas pon unas presillas de lana teñida de púrpura, lo mismo que en el borde del otro conjunto de cortinas.'),
('nvi', 'Éxodo 26:5', 'Éxodo', 26, 5, 'En las cortinas del primer conjunto pon cincuenta presillas, lo mismo que en las cortinas del otro conjunto, de modo que cada presilla tenga su pareja.'),
('nvi', 'Éxodo 26:6', 'Éxodo', 26, 6, 'Haz luego cincuenta ganchos de oro para que las cortinas queden enganchadas una con otra, de modo que el santuario tenga unidad de conjunto.'),
('nvi', 'Éxodo 26:7', 'Éxodo', 26, 7, '»Haz once cortinas de pelo de cabra para cubrir el santuario a la manera de una tienda de campaña.'),
('nvi', 'Éxodo 26:8', 'Éxodo', 26, 8, 'Todas ellas deben medir lo mismo, es decir, trece metros y medio de largo por un metro con ochenta centímetros de ancho.'),
('nvi', 'Éxodo 26:9', 'Éxodo', 26, 9, 'Cose cinco cortinas en un conjunto, y las otras seis en otro conjunto, doblando la sexta cortina en la parte frontal del santuario.'),
('nvi', 'Éxodo 26:10', 'Éxodo', 26, 10, '»Haz cincuenta presillas en el borde de la cortina con que termina el primer conjunto, y otras cincuenta presillas en el borde de la cortina con que termina el segundo.'),
('nvi', 'Éxodo 26:11', 'Éxodo', 26, 11, 'Haz luego cincuenta ganchos de bronce y mételos en las presillas para formar el santuario, de modo que éste tenga unidad de conjunto.'),
('nvi', 'Éxodo 26:12', 'Éxodo', 26, 12, 'Las diez cortinas tendrán una cortina restante, que quedará colgando a espaldas del santuario.'),
('nvi', 'Éxodo 26:13', 'Éxodo', 26, 13, 'A esta cortina le sobrarán cincuenta centímetros en cada extremo, y con esa parte sobrante se cerrará el santuario.'),
('nvi', 'Éxodo 26:14', 'Éxodo', 26, 14, '»Haz para el santuario un toldo de piel de carnero, teñido de rojo, y para la parte superior un toldo de piel de delfín.'),
('nvi', 'Éxodo 26:15', 'Éxodo', 26, 15, 'Prepara para el santuario unos tablones de acacia, para que sirvan de pilares.'),
('nvi', 'Éxodo 26:16', 'Éxodo', 26, 16, 'Cada tablón debe medir cuatro metros y medio de largo por setenta centímetros de ancho,'),
('nvi', 'Éxodo 26:17', 'Éxodo', 26, 17, 'y contar con dos ranuras para que cada tablón encaje con el otro. Todos los tablones para el santuario los harás así.'),
('nvi', 'Éxodo 26:18', 'Éxodo', 26, 18, 'Serán veinte los tablones para el lado sur del santuario.'),
('nvi', 'Éxodo 26:19', 'Éxodo', 26, 19, '»Haz también cuarenta bases de plata para colocarlas debajo de los tablones, dos bases por tablón, para que las dos ranuras de cada tablón encajen en cada base.'),
('nvi', 'Éxodo 26:20', 'Éxodo', 26, 20, 'Para el lado opuesto, es decir, para el lado norte del santuario, prepararás también veinte tablones'),
('nvi', 'Éxodo 26:21', 'Éxodo', 26, 21, 'y cuarenta bases de plata, y pondrás dos bases debajo de cada tablón.'),
('nvi', 'Éxodo 26:22', 'Éxodo', 26, 22, 'Pondrás seis tablones en el lado posterior, que es el lado occidental del santuario,'),
('nvi', 'Éxodo 26:23', 'Éxodo', 26, 23, 'y dos tablones más en las esquinas de ese mismo lado.'),
('nvi', 'Éxodo 26:24', 'Éxodo', 26, 24, 'Estos dos tablones deben ser dobles en la base, quedando unidos por un solo anillo en la parte superior. Haz lo mismo en ambas esquinas,'),
('nvi', 'Éxodo 26:25', 'Éxodo', 26, 25, 'de modo que haya ocho tablones y dieciséis bases de plata, es decir, dos bases debajo de cada tablón.'),
('nvi', 'Éxodo 26:26', 'Éxodo', 26, 26, '»Prepara también unos travesaños de acacia: cinco para los tablones de un costado del santuario,'),
('nvi', 'Éxodo 26:27', 'Éxodo', 26, 27, 'cinco para los del costado opuesto, y cinco para los del costado occidental, es decir, para la parte posterior.'),
('nvi', 'Éxodo 26:28', 'Éxodo', 26, 28, 'El travesaño central deberá pasar de uno a otro extremo, a media altura de los tablones.'),
('nvi', 'Éxodo 26:29', 'Éxodo', 26, 29, 'Recubre de oro los tablones, y haz unos anillos de oro para que los travesaños pasen por ellos. También debes recubrir de oro los travesaños.'),
('nvi', 'Éxodo 26:30', 'Éxodo', 26, 30, 'Erige el santuario ciñéndote al modelo que se te mostró en el monte.'),
('nvi', 'Éxodo 26:31', 'Éxodo', 26, 31, '»Haz una cortina de púrpura, carmesí, escarlata y lino fino, con querubines artísticamente bordados en ella.'),
('nvi', 'Éxodo 26:32', 'Éxodo', 26, 32, 'Cuélgala con ganchos de oro en cuatro postes de madera de acacia recubiertos de oro, los cuales levantarás sobre cuatro bases de plata.'),
('nvi', 'Éxodo 26:33', 'Éxodo', 26, 33, 'Cuelga de los ganchos la cortina, la cual separará el Lugar Santo del Lugar Santísimo, y coloca el arca del pacto detrás de la cortina.'),
('nvi', 'Éxodo 26:34', 'Éxodo', 26, 34, 'Pon el propiciatorio sobre el arca del pacto, dentro del Lugar Santísimo,'),
('nvi', 'Éxodo 26:35', 'Éxodo', 26, 35, 'y coloca la mesa fuera de la cortina, en el lado norte del santuario. El candelabro lo pondrás frente a la mesa, en el lado sur.'),
('nvi', 'Éxodo 26:36', 'Éxodo', 26, 36, '»Haz para la entrada del santuario una cortina de púrpura, carmesí, escarlata y lino fino, recamada artísticamente.'),
('nvi', 'Éxodo 26:37', 'Éxodo', 26, 37, 'Para esta cortina prepara cinco postes de acacia recubiertos de oro, con sus respectivos ganchos de oro, y funde para los postes cinco bases de bronce.'),
('nvi', 'Éxodo 27:1', 'Éxodo', 27, 1, '»Haz un altar de madera de acacia, cuadrado, de dos metros con treinta centímetros por lado, y de un metro con treinta centímetros de alto.'),
('nvi', 'Éxodo 27:2', 'Éxodo', 27, 2, 'Ponle un cuerno en cada una de sus cuatro esquinas, de manera que los cuernos y el altar formen una sola pieza, y recubre de bronce el altar.'),
('nvi', 'Éxodo 27:3', 'Éxodo', 27, 3, 'Haz de bronce todos sus utensilios, es decir, sus portacenizas, sus tenazas, sus aspersorios, sus tridentes y sus braseros.'),
('nvi', 'Éxodo 27:4', 'Éxodo', 27, 4, 'Hazle también un enrejado de bronce, con un anillo del mismo metal en cada una de sus cuatro esquinas.'),
('nvi', 'Éxodo 27:5', 'Éxodo', 27, 5, 'El anillo irá bajo el reborde del altar, de modo que quede a media altura del mismo.'),
('nvi', 'Éxodo 27:6', 'Éxodo', 27, 6, 'Prepara para el altar varas de madera de acacia, y recúbrelas de bronce.'),
('nvi', 'Éxodo 27:7', 'Éxodo', 27, 7, 'Las varas deberán pasar por los anillos, de modo que sobresalgan en los dos extremos del altar para que éste pueda ser transportado.'),
('nvi', 'Éxodo 27:8', 'Éxodo', 27, 8, 'El altar lo harás hueco y de tablas, exactamente como el que se te mostró en el monte.'),
('nvi', 'Éxodo 27:9', 'Éxodo', 27, 9, '»Haz un atrio para el santuario. El lado sur debe medir cuarenta y cinco metros de largo, y tener cortinas de lino fino,'),
('nvi', 'Éxodo 27:10', 'Éxodo', 27, 10, 'veinte postes y veinte bases de bronce. Los postes deben contar con empalmes y ganchos de plata.'),
('nvi', 'Éxodo 27:11', 'Éxodo', 27, 11, 'También el lado norte debe medir cuarenta y cinco metros de largo y tener cortinas, veinte postes y veinte bases de bronce. Los postes deben también contar con empalmes y ganchos de plata.'),
('nvi', 'Éxodo 27:12', 'Éxodo', 27, 12, '»A todo lo ancho del lado occidental del atrio, que debe medir veintidós metros y medio, habrá cortinas, diez postes y diez bases.'),
('nvi', 'Éxodo 27:13', 'Éxodo', 27, 13, 'El lado oriental del atrio, que da hacia la salida del sol, también deberá medir veintidós metros y medio.'),
('nvi', 'Éxodo 27:14', 'Éxodo', 27, 14, 'Habrá cortinas de siete metros de largo, y tres postes y tres bases a un lado de la entrada,'),
('nvi', 'Éxodo 27:15', 'Éxodo', 27, 15, 'lo mismo que del otro lado.'),
('nvi', 'Éxodo 27:16', 'Éxodo', 27, 16, '»A la entrada del atrio habrá una cortina de nueve metros de largo, de púrpura, carmesí, escarlata y lino fino, recamada artísticamente, y además cuatro postes y cuatro bases.'),
('nvi', 'Éxodo 27:17', 'Éxodo', 27, 17, 'Todos los postes alrededor del atrio deben tener empalmes y ganchos de plata, y bases de bronce.'),
('nvi', 'Éxodo 27:18', 'Éxodo', 27, 18, 'El atrio medirá cuarenta y cinco metros de largo por veintidós metros y medio de ancho, con cortinas de lino fino de dos metros con treinta centímetros de alto, y con bases de bronce.'),
('nvi', 'Éxodo 27:19', 'Éxodo', 27, 19, 'Todas las estacas y los demás utensilios para el servicio del santuario serán de bronce, incluyendo las estacas del atrio.'),
('nvi', 'Éxodo 27:20', 'Éxodo', 27, 20, '»Ordénales a los israelitas que te traigan aceite puro de oliva, para que las lámparas estén siempre encendidas.'),
('nvi', 'Éxodo 27:21', 'Éxodo', 27, 21, 'Aarón y sus hijos deberán mantenerlas encendidas toda la noche en presencia del SEÑOR, en la Tienda de reunión, fuera de la cortina que está ante el arca del pacto. Esta ley deberá cumplirse entre los israelitas siempre, por todas las generaciones.'),
('nvi', 'Éxodo 28:1', 'Éxodo', 28, 1, '»Haz que comparezcan ante ti tu hermano Aarón y sus hijos Nadab, Abiú, Eleazar e Itamar. De entre todos los israelitas, ellos me servirán como sacerdotes.'),
('nvi', 'Éxodo 28:2', 'Éxodo', 28, 2, 'Hazle a tu hermano Aarón vestiduras sagradas que le confieran honra y dignidad.'),
('nvi', 'Éxodo 28:3', 'Éxodo', 28, 3, 'Habla con todos los expertos a quienes he dado habilidades especiales, para que hagan las vestiduras de Aarón, y así lo consagre yo como mi sacerdote.'),
('nvi', 'Éxodo 28:4', 'Éxodo', 28, 4, '»Las vestiduras que le harás son las siguientes: un pectoral, un efod, un manto, una túnica bordada, un turbante y una faja. Estas vestiduras sagradas se harán para tu hermano Aarón y para sus hijos, a fin de que me sirvan como sacerdotes.'),
('nvi', 'Éxodo 28:5', 'Éxodo', 28, 5, 'Al efecto se usará oro, púrpura, carmesí, escarlata y lino.'),
('nvi', 'Éxodo 28:6', 'Éxodo', 28, 6, '»El efod se bordará artísticamente con oro, púrpura, carmesí, escarlata y lino fino.'),
('nvi', 'Éxodo 28:7', 'Éxodo', 28, 7, 'En sus dos extremos tendrá hombreras con cintas, para que pueda sujetarse.'),
('nvi', 'Éxodo 28:8', 'Éxodo', 28, 8, 'El cinturón bordado con el que se sujeta el efod deberá ser del mismo material, es decir, de oro, púrpura, carmesí, escarlata y lino fino, y formará con el efod una sola pieza.'),
('nvi', 'Éxodo 28:9', 'Éxodo', 28, 9, '»Toma dos piedras de ónice, y graba en ellas los nombres de los doce hijos de Israel'),
('nvi', 'Éxodo 28:10', 'Éxodo', 28, 10, 'por orden de nacimiento, seis nombres en una piedra, y seis en la otra.'),
('nvi', 'Éxodo 28:11', 'Éxodo', 28, 11, 'Un joyero grabará los nombres en las dos piedras, como los orfebres graban sellos: engarzará las piedras en filigrana de oro'),
('nvi', 'Éxodo 28:12', 'Éxodo', 28, 12, 'y las sujetará a las hombreras del efod. Así Aarón llevará en sus hombros los nombres de los hijos de Israel, para recordarlos ante el SEÑOR.'),
('nvi', 'Éxodo 28:13', 'Éxodo', 28, 13, 'Haz también engastes en filigrana de oro,'),
('nvi', 'Éxodo 28:14', 'Éxodo', 28, 14, 'y dos cadenillas de oro puro, a manera de cordón, para fijar las cadenillas en los engastes.'),
('nvi', 'Éxodo 28:15', 'Éxodo', 28, 15, '»El pectoral para impartir justicia lo bordarás artísticamente con oro, púrpura, carmesí, escarlata y lino fino, como hiciste con el efod.'),
('nvi', 'Éxodo 28:16', 'Éxodo', 28, 16, 'Será doble y cuadrado, de veinte centímetros de largo por veinte de ancho.'),
('nvi', 'Éxodo 28:17', 'Éxodo', 28, 17, 'Engarzarás en él cuatro hileras de piedras preciosas. En la primera pondrás un rubí, un crisólito y una esmeralda;'),
('nvi', 'Éxodo 28:18', 'Éxodo', 28, 18, 'en la segunda, una turquesa, un zafiro y un jade;'),
('nvi', 'Éxodo 28:19', 'Éxodo', 28, 19, 'en la tercera, un jacinto, un ágata y una amatista,'),
('nvi', 'Éxodo 28:20', 'Éxodo', 28, 20, 'y en la cuarta, un topacio, un ónice y un jaspe. Engárzalas en filigrana de oro.'),
('nvi', 'Éxodo 28:21', 'Éxodo', 28, 21, 'Deben ser doce piedras, una por cada uno de los doce hijos de Israel. Cada una de las piedras llevará grabada como un sello el nombre de una de las doce tribus.'),
('nvi', 'Éxodo 28:22', 'Éxodo', 28, 22, '»Haz unas cadenillas de oro puro, en forma de cordón, para el pectoral.'),
('nvi', 'Éxodo 28:23', 'Éxodo', 28, 23, 'Ponle al pectoral dos anillos de oro, y sujétalos a sus dos extremos.'),
('nvi', 'Éxodo 28:24', 'Éxodo', 28, 24, 'Sujeta las dos cadenillas de oro a los anillos del pectoral,'),
('nvi', 'Éxodo 28:25', 'Éxodo', 28, 25, 'y une los extremos de las cadenillas a los dos engastes, para fijarlos por la parte delantera a las hombreras del efod.'),
('nvi', 'Éxodo 28:26', 'Éxodo', 28, 26, '»Haz otros dos anillos de oro, y fíjalos en los extremos del pectoral, en su borde interno cercano al efod.'),
('nvi', 'Éxodo 28:27', 'Éxodo', 28, 27, 'Haz dos anillos más, también de oro, para fijarlos por el frente del efod, pero por debajo de las hombreras, cerca de la costura que va justamente arriba del cinturón.'),
('nvi', 'Éxodo 28:28', 'Éxodo', 28, 28, 'Los anillos del pectoral deberán sujetarse a los anillos del efod con un cordón azul, trabándolo con el cinturón para que el pectoral y el efod queden unidos.'),
('nvi', 'Éxodo 28:29', 'Éxodo', 28, 29, 'De este modo, siempre que Aarón entre en el Lugar Santo llevará sobre su corazón, en el pectoral para impartir justicia, los nombres de los hijos de Israel para recordarlos siempre ante el SEÑOR.'),
('nvi', 'Éxodo 28:30', 'Éxodo', 28, 30, 'Sobre el pectoral para impartir justicia pondrás el urim y el tumim. De esta manera, siempre que Aarón se presente ante el SEÑOR, llevará en el pecho la causa de los israelitas.'),
('nvi', 'Éxodo 28:31', 'Éxodo', 28, 31, '»Haz de púrpura todo el manto del efod,'),
('nvi', 'Éxodo 28:32', 'Éxodo', 28, 32, 'con una abertura en el centro para meter la cabeza. Alrededor de la abertura le pondrás un refuerzo, como el que se pone a los chalecos, para que no se desgarre.'),
('nvi', 'Éxodo 28:33', 'Éxodo', 28, 33, 'En torno al borde inferior del manto pondrás granadas de púrpura, carmesí y escarlata, alternándolas con campanillas de oro.'),
('nvi', 'Éxodo 28:34', 'Éxodo', 28, 34, 'Por todo el borde del manto pondrás primero una campanilla y luego una granada.'),
('nvi', 'Éxodo 28:35', 'Éxodo', 28, 35, 'Aarón debe llevar puesto el manto mientras esté ejerciendo su ministerio, para que el tintineo de las campanillas se oiga todo el tiempo que él esté ante el SEÑOR en el Lugar Santo, y así él no muera.'),
('nvi', 'Éxodo 28:36', 'Éxodo', 28, 36, '»Haz una placa de oro puro, y graba en ella, a manera de sello: Consagarado al SEÑOR.'),
('nvi', 'Éxodo 28:37', 'Éxodo', 28, 37, 'Sujétala al turbante con un cordón púrpura, de modo que quede fija a éste por la parte delantera.'),
('nvi', 'Éxodo 28:38', 'Éxodo', 28, 38, 'Esta placa estará siempre sobre la frente de Aarón, para que el SEÑOR acepte todas las ofrendas de los israelitas, ya que Aarón llevará sobre sí el pecado en que ellos incurran al dedicar sus ofrendas sagradas.'),
('nvi', 'Éxodo 28:39', 'Éxodo', 28, 39, '»La túnica y el turbante los harás de lino. El cinturón deberá estar recamado artísticamente.'),
('nvi', 'Éxodo 28:40', 'Éxodo', 28, 40, 'A los hijos de Aarón les harás túnicas, cinturones y mitras, para conferirles honra y dignidad.'),
('nvi', 'Éxodo 28:41', 'Éxodo', 28, 41, 'Una vez que hayas vestido a tu hermano Aarón y a sus hijos, los ungirás para conferirles autoridad y consagrarlos como mis sacerdotes.'),
('nvi', 'Éxodo 28:42', 'Éxodo', 28, 42, '»Hazles también calzoncillos de lino que les cubran el cuerpo desde la cintura hasta el muslo.'),
('nvi', 'Éxodo 28:43', 'Éxodo', 28, 43, 'Aarón y sus hijos deberán ponérselos siempre que entren en la Tienda de reunión, o cuando se acerquen al altar para ejercer su ministerio en el Lugar Santo, a fin de que no incurran en pecado y mueran. Ésta es una ley perpetua para Aarón y sus descendientes.'),
('nvi', 'Éxodo 29:1', 'Éxodo', 29, 1, '»Para consagrarlos como sacerdotes a mi servicio, harás lo siguiente: Tomarás un novillo y dos carneros sin defecto,'),
('nvi', 'Éxodo 29:2', 'Éxodo', 29, 2, 'y con harina fina de trigo harás panes y tortas sin levadura amasadas con aceite, y obleas sin levadura untadas con aceite.'),
('nvi', 'Éxodo 29:3', 'Éxodo', 29, 3, 'Pondrás los panes, las tortas y las obleas en un canastillo, y me los presentarás junto con el novillo y los dos carneros.'),
('nvi', 'Éxodo 29:4', 'Éxodo', 29, 4, 'Luego llevarás a Aarón y a sus hijos a la entrada de la Tienda de reunión, y los bañarás.'),
('nvi', 'Éxodo 29:5', 'Éxodo', 29, 5, 'Tomarás las vestiduras y le pondrás a Aarón la túnica, el efod con su manto, y el pectoral. El efod se lo sujetarás con el cinturón.'),
('nvi', 'Éxodo 29:6', 'Éxodo', 29, 6, 'Le pondrás el turbante en la cabeza, y sobre el turbante, la tiara sagrada.'),
('nvi', 'Éxodo 29:7', 'Éxodo', 29, 7, 'Luego lo ungirás derramando el aceite de la unción sobre su cabeza.'),
('nvi', 'Éxodo 29:8', 'Éxodo', 29, 8, 'Acercarás entonces a sus hijos y les pondrás las túnicas'),
('nvi', 'Éxodo 29:9', 'Éxodo', 29, 9, 'y las mitras; a continuación, les ceñirás los cinturones a Aarón y a sus hijos. Así les conferirás autoridad, y el sacerdocio será para ellos una ley perpetua.'),
('nvi', 'Éxodo 29:10', 'Éxodo', 29, 10, '»Arrimarás el novillo a la entrada de la Tienda de reunión para que Aarón y sus hijos le pongan las manos sobre la cabeza,'),
('nvi', 'Éxodo 29:11', 'Éxodo', 29, 11, 'y allí, en presencia del SEÑOR, sacrificarás al novillo.'),
('nvi', 'Éxodo 29:12', 'Éxodo', 29, 12, 'Con el dedo tomarás un poco de la sangre del novillo y la untarás en los cuernos del altar, y al pie del altar derramarás la sangre restante.'),
('nvi', 'Éxodo 29:13', 'Éxodo', 29, 13, 'Al hígado y a los dos riñones les quitarás la grasa que los recubre, y la quemarás sobre el altar;'),
('nvi', 'Éxodo 29:14', 'Éxodo', 29, 14, 'pero la carne del novillo, su piel y su excremento los quemarás fuera del campamento, pues se trata de un sacrificio por el pecado.'),
('nvi', 'Éxodo 29:15', 'Éxodo', 29, 15, '»Tomarás luego uno de los carneros para que Aarón y sus hijos le pongan las manos sobre la cabeza;'),
('nvi', 'Éxodo 29:16', 'Éxodo', 29, 16, 'lo sacrificarás, y con la sangre rociarás el altar y sus cuatro costados.'),
('nvi', 'Éxodo 29:17', 'Éxodo', 29, 17, 'Destazarás el carnero y, luego de lavarle los intestinos y las piernas, los pondrás sobre los pedazos y la cabeza del carnero,'),
('nvi', 'Éxodo 29:18', 'Éxodo', 29, 18, 'y quemarás todo el carnero sobre el altar. Se trata de un holocausto, de una ofrenda presentada por fuego, de aroma grato al SEÑOR.'),
('nvi', 'Éxodo 29:19', 'Éxodo', 29, 19, '»Tomarás entonces el otro carnero para que Aarón y sus hijos le pongan las manos sobre la cabeza,'),
('nvi', 'Éxodo 29:20', 'Éxodo', 29, 20, 'y lo sacrificarás, poniendo un poco de su sangre en el lóbulo de la oreja derecha de Aarón y de sus hijos, lo mismo que en el pulgar derecho y en el dedo gordo derecho. Después de eso rociarás el altar y sus cuatro costados con la sangre,'),
('nvi', 'Éxodo 29:21', 'Éxodo', 29, 21, 'y rociarás también un poco de esa sangre y del aceite de la unción sobre Aarón y sus hijos, y sobre sus vestiduras. Así Aarón y sus hijos y sus vestiduras quedarán consagrados.'),
('nvi', 'Éxodo 29:22', 'Éxodo', 29, 22, '»De este carnero, que representa la autoridad conferida a los sacerdotes, tomarás la cola, la grasa que recubre las vísceras, el hígado, los dos riñones y el muslo derecho.'),
('nvi', 'Éxodo 29:23', 'Éxodo', 29, 23, 'Del canastillo del pan sin levadura que está ante el SEÑOR, tomarás uno de los panes, una torta hecha con aceite y una oblea,'),
('nvi', 'Éxodo 29:24', 'Éxodo', 29, 24, 'y meciéndolos ante el SEÑOR los pondrás en las manos de Aarón y de sus hijos. Se trata de una ofrenda mecida.'),
('nvi', 'Éxodo 29:25', 'Éxodo', 29, 25, 'Luego ellos deberán devolverte todo esto para que tú, en presencia del SEÑOR, lo quemes sobre el altar, junto con el holocausto de aroma grato. Ésta es una ofrenda presentada por fuego en honor del SEÑOR.'),
('nvi', 'Éxodo 29:26', 'Éxodo', 29, 26, 'Después de eso, tomarás el pecho del carnero que representa la autoridad conferida a Aarón, y lo mecerás ante el SEÑOR, pues se trata de una ofrenda mecida. Esa porción será la tuya.'),
('nvi', 'Éxodo 29:27', 'Éxodo', 29, 27, '»Aparta el pecho del carnero que fue mecido para conferirles autoridad a Aarón y a sus hijos, y también el muslo que fue presentado como ofrenda, pues son las porciones que a ellos les corresponden.'),
('nvi', 'Éxodo 29:28', 'Éxodo', 29, 28, 'Éstas son las porciones que, de sus sacrificios de comunión al SEÑOR, les darán siempre los israelitas a Aarón y a sus hijos como contribución.'),
('nvi', 'Éxodo 29:29', 'Éxodo', 29, 29, '»Las vestiduras sagradas de Aarón pasarán a ser de sus descendientes, para que sean ungidos y ordenados con ellas.'),
('nvi', 'Éxodo 29:30', 'Éxodo', 29, 30, 'Cualquiera de los sacerdotes descendientes de Aarón que se presente en la Tienda de reunión para ministrar en el Lugar Santo, deberá llevar puestas esas vestiduras durante siete días.'),
('nvi', 'Éxodo 29:31', 'Éxodo', 29, 31, '»Toma el carnero con que se les confirió autoridad, y cuece su carne en el lugar sagrado.'),
('nvi', 'Éxodo 29:32', 'Éxodo', 29, 32, 'A la entrada de la Tienda de reunión, Aarón y sus hijos comerán la carne del carnero y el pan que está en el canastillo.'),
('nvi', 'Éxodo 29:33', 'Éxodo', 29, 33, 'Con esas ofrendas se hizo expiación por ellos, se les confirió autoridad y se les consagró; sólo ellos podrán comerlas, y nadie más, porque son ofrendas sagradas.'),
('nvi', 'Éxodo 29:34', 'Éxodo', 29, 34, 'Si hasta el otro día queda algo del carnero con que se les confirió autoridad, o algo del pan, quémalo. No debe comerse, porque es parte de las ofrendas sagradas.'),
('nvi', 'Éxodo 29:35', 'Éxodo', 29, 35, '»Haz con Aarón y con sus hijos todo lo que te he ordenado. Dedica siete días a conferirles autoridad.'),
('nvi', 'Éxodo 29:36', 'Éxodo', 29, 36, 'Para hacer expiación, cada día ofrecerás un novillo como ofrenda por el pecado. Purificarás el altar haciendo expiación por él y ungiéndolo para consagrarlo.'),
('nvi', 'Éxodo 29:37', 'Éxodo', 29, 37, 'Esto lo harás durante siete días. Así el altar y cualquier cosa que lo toque quedarán consagrados.'),
('nvi', 'Éxodo 29:38', 'Éxodo', 29, 38, '»Todos los días ofrecerás sobre el altar dos corderos de un año.'),
('nvi', 'Éxodo 29:39', 'Éxodo', 29, 39, 'Al despuntar el día, ofrecerás uno de ellos, y al caer la tarde, el otro.'),
('nvi', 'Éxodo 29:40', 'Éxodo', 29, 40, 'Con el primer cordero ofrecerás, como ofrenda de libación, dos kilos de harina fina mezclada con un litro de aceite de oliva, y un litro de vino.'),
('nvi', 'Éxodo 29:41', 'Éxodo', 29, 41, 'El otro cordero lo sacrificarás al caer la tarde, como ofrenda presentada por fuego de aroma grato al SEÑOR, junto con una ofrenda de libación como la presentada en la mañana.'),
('nvi', 'Éxodo 29:42', 'Éxodo', 29, 42, '»Las generaciones futuras deberán ofrecer siempre este holocausto al SEÑOR. Lo harán a la entrada de la Tienda de reunión, donde yo me reuniré contigo y te hablaré,'),
('nvi', 'Éxodo 29:43', 'Éxodo', 29, 43, 'y donde también me reuniré con los israelitas. Mi gloriosa presencia santificará ese lugar.'),
('nvi', 'Éxodo 29:44', 'Éxodo', 29, 44, '»Consagraré la Tienda de reunión y el altar, y consagraré también a Aarón y a sus hijos para que me sirvan como sacerdotes.'),
('nvi', 'Éxodo 29:45', 'Éxodo', 29, 45, 'Habitaré entre los israelitas, y seré su Dios.'),
('nvi', 'Éxodo 29:46', 'Éxodo', 29, 46, 'Así sabrán que yo soy el SEÑOR su Dios, que los sacó de Egipto para habitar entre ellos. Yo soy el SEÑOR su Dios.'),
('nvi', 'Éxodo 30:1', 'Éxodo', 30, 1, '»Haz un altar de madera de acacia para quemar incienso.'),
('nvi', 'Éxodo 30:2', 'Éxodo', 30, 2, 'Hazlo cuadrado, de cuarenta y cinco centímetros de largo por cuarenta y cinco centímetros de ancho y noventa centímetros de alto. Sus cuernos deben formar una pieza con el altar.'),
('nvi', 'Éxodo 30:3', 'Éxodo', 30, 3, 'Recubre de oro puro su parte superior, sus cuatro costados y los cuernos, y ponle una moldura de oro alrededor.'),
('nvi', 'Éxodo 30:4', 'Éxodo', 30, 4, 'Ponle también dos anillos de oro en cada uno de sus costados, debajo de la moldura, para que pasen por ellos las varas para transportarlo.'),
('nvi', 'Éxodo 30:5', 'Éxodo', 30, 5, 'Prepara las varas de madera de acacia, y recúbrelas de oro.'),
('nvi', 'Éxodo 30:6', 'Éxodo', 30, 6, 'Pon el altar frente a la cortina que está ante el arca del pacto, es decir, ante el propiciatorio que está sobre el arca, que es donde me reuniré contigo.'),
('nvi', 'Éxodo 30:7', 'Éxodo', 30, 7, '»Cada mañana, cuando Aarón prepare las lámparas, quemará incienso aromático sobre el altar,'),
('nvi', 'Éxodo 30:8', 'Éxodo', 30, 8, 'y también al caer la tarde, cuando las encienda. Las generaciones futuras deberán quemar siempre incienso ante el SEÑOR.'),
('nvi', 'Éxodo 30:9', 'Éxodo', 30, 9, 'No ofrezcas sobre ese altar ningún otro incienso, ni holocausto ni ofrenda de grano, ni derrames sobre él libación alguna.'),
('nvi', 'Éxodo 30:10', 'Éxodo', 30, 10, 'Cada año Aarón hará expiación por el pecado de las generaciones futuras. Lo hará poniendo la sangre de la ofrenda de expiación sobre los cuernos del altar. Este altar estará completamente consagrado al SEÑOR.»'),
('nvi', 'Éxodo 30:11', 'Éxodo', 30, 11, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 30:12', 'Éxodo', 30, 12, '«Cuando hagas el censo y cuentes a los israelitas, cada uno deberá pagar al SEÑOR rescate por su vida, para que no le sobrevenga ninguna plaga durante el censo.'),
('nvi', 'Éxodo 30:13', 'Éxodo', 30, 13, 'Cada uno de los censados deberá pagar como ofrenda al SEÑOR seis gramos de plata, que es la mitad de la tasación oficial del santuario.'),
('nvi', 'Éxodo 30:14', 'Éxodo', 30, 14, 'Todos los censados mayores de veinte años deberán entregar esta ofrenda al SEÑOR.'),
('nvi', 'Éxodo 30:15', 'Éxodo', 30, 15, 'Al pagar su rescate, ni el rico dará más de seis gramos, ni el pobre dará menos.'),
('nvi', 'Éxodo 30:16', 'Éxodo', 30, 16, 'Tú mismo recibirás esta plata de manos de los israelitas, y la entregarás para el servicio de la Tienda de reunión. De esta manera el SEÑOR tendrá presente que los israelitas pagaron su rescate.»'),
('nvi', 'Éxodo 30:17', 'Éxodo', 30, 17, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 30:18', 'Éxodo', 30, 18, '«Haz un lavamanos de bronce, con un pedestal también de bronce, y colócalo entre la Tienda de reunión y el altar. Échale agua,'),
('nvi', 'Éxodo 30:19', 'Éxodo', 30, 19, 'pues con ella deben lavarse Aarón y sus hijos las manos y los pies.'),
('nvi', 'Éxodo 30:20', 'Éxodo', 30, 20, 'Siempre que entren en la Tienda de reunión, o cuando se acerquen al altar y presenten al SEÑOR alguna ofrenda por fuego, deberán lavarse con agua'),
('nvi', 'Éxodo 30:21', 'Éxodo', 30, 21, 'las manos y los pies para que no mueran. Ésta será una ley perpetua para Aarón y sus descendientes por todas las generaciones.»'),
('nvi', 'Éxodo 30:22', 'Éxodo', 30, 22, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 30:23', 'Éxodo', 30, 23, '«Toma las siguientes especias finas: seis kilos de mirra líquida, tres kilos de canela aromática, tres kilos de caña aromática,'),
('nvi', 'Éxodo 30:24', 'Éxodo', 30, 24, 'seis kilos de casia, y cuatro litros de aceite de oliva, según la tasación oficial del santuario.'),
('nvi', 'Éxodo 30:25', 'Éxodo', 30, 25, 'Con estos ingredientes harás un aceite, es decir, una mezcla aromática como las de los fabricantes de perfumes. Éste será el aceite de la unción sagrada.'),
('nvi', 'Éxodo 30:26', 'Éxodo', 30, 26, 'Con él deberás ungir la Tienda de reunión, el arca del pacto,'),
('nvi', 'Éxodo 30:27', 'Éxodo', 30, 27, 'la mesa y todos sus utensilios, el candelabro y sus accesorios, el altar del incienso,'),
('nvi', 'Éxodo 30:28', 'Éxodo', 30, 28, 'el altar de los holocaustos y todos sus utensilios, y el lavamanos con su pedestal.'),
('nvi', 'Éxodo 30:29', 'Éxodo', 30, 29, 'De este modo los consagrarás, y serán objetos santísimos; cualquier cosa que toque esos objetos quedará también consagrada.'),
('nvi', 'Éxodo 30:30', 'Éxodo', 30, 30, '»Unge a Aarón y a sus hijos, y conságralos para que me sirvan como sacerdotes.'),
('nvi', 'Éxodo 30:31', 'Éxodo', 30, 31, 'A los israelitas les darás las siguientes instrucciones: “De aquí en adelante, éste será mi aceite de la unción sagrada.'),
('nvi', 'Éxodo 30:32', 'Éxodo', 30, 32, 'No lo derramen sobre el cuerpo de cualquier hombre, ni preparen otro aceite con la misma fórmula. Es un aceite sagrado, y así deberán considerarlo.'),
('nvi', 'Éxodo 30:33', 'Éxodo', 30, 33, 'Cualquiera que haga un perfume como éste, y cualquiera que unja con él a alguien que no sea sacerdote, será eliminado de su pueblo.”»'),
('nvi', 'Éxodo 30:34', 'Éxodo', 30, 34, 'El SEÑOR le dijo a Moisés: «Toma una misma cantidad de resina, ámbar, gálbano e incienso puro,'),
('nvi', 'Éxodo 30:35', 'Éxodo', 30, 35, 'y mezcla todo esto para hacer un incienso aromático, como lo hacen los fabricantes de perfumes. Agrégale sal a la mezcla, para que sea un incienso puro y sagrado.'),
('nvi', 'Éxodo 30:36', 'Éxodo', 30, 36, 'Muele parte de la mezcla hasta hacerla polvo, y colócala en la Tienda de reunión, frente al arca del pacto, donde yo me reuniré contigo. Este incienso será para ustedes algo muy sagrado,'),
('nvi', 'Éxodo 30:37', 'Éxodo', 30, 37, 'y no deberá hacerse ningún otro incienso con la misma fórmula, pues le pertenece al SEÑOR. Ustedes deberán considerarlo como algo sagrado.'),
('nvi', 'Éxodo 30:38', 'Éxodo', 30, 38, 'Quien haga otro incienso parecido para disfrutar de su fragancia, será eliminado de su pueblo.»'),
('nvi', 'Éxodo 31:1', 'Éxodo', 31, 1, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 31:2', 'Éxodo', 31, 2, '«Toma en cuenta que he escogido a Bezalel, hijo de Uri y nieto de Jur, de la tribu de Judá,'),
('nvi', 'Éxodo 31:3', 'Éxodo', 31, 3, 'y lo he llenado del Espíritu de Dios, de sabiduría, inteligencia y capacidad creativa'),
('nvi', 'Éxodo 31:4', 'Éxodo', 31, 4, 'para hacer trabajos artísticos en oro, plata y bronce,'),
('nvi', 'Éxodo 31:5', 'Éxodo', 31, 5, 'para cortar y engastar piedras preciosas, para hacer tallados en madera y para realizar toda clase de artesanías.'),
('nvi', 'Éxodo 31:6', 'Éxodo', 31, 6, '»Además, he designado como su ayudante a Aholiab hijo de Ajisamac, de la tribu de Dan, y he dotado de habilidad a todos los artesanos para que hagan todo lo que te he mandado hacer, es decir:'),
('nvi', 'Éxodo 31:7', 'Éxodo', 31, 7, 'la Tienda de reunión, el arca del pacto, el propiciatorio que va encima de ella, el resto del mobiliario de la Tienda,'),
('nvi', 'Éxodo 31:8', 'Éxodo', 31, 8, 'la mesa y sus utensilios, el candelabro de oro puro y todos sus accesorios, el altar del incienso,'),
('nvi', 'Éxodo 31:9', 'Éxodo', 31, 9, 'el altar de los holocaustos y todos sus utensilios, el lavamanos con su pedestal,'),
('nvi', 'Éxodo 31:10', 'Éxodo', 31, 10, 'las vestiduras tejidas, tanto las vestiduras sagradas para Aarón el sacerdote como las vestiduras sacerdotales de sus hijos,'),
('nvi', 'Éxodo 31:11', 'Éxodo', 31, 11, 'el aceite de la unción, y el incienso aromático para el Lugar Santo. »Todo deberán hacerlo tal como te he mandado que lo hagas.»'),
('nvi', 'Éxodo 31:12', 'Éxodo', 31, 12, 'El SEÑOR le ordenó a Moisés:'),
('nvi', 'Éxodo 31:13', 'Éxodo', 31, 13, '«Diles lo siguiente a los israelitas: “Ustedes deberán observar mis sábados. En todas las generaciones venideras, el sábado será una señal entre ustedes y yo, para que sepan que yo, el SEÑOR, los he consagrado para que me sirvan.'),
('nvi', 'Éxodo 31:14', 'Éxodo', 31, 14, '» ”El sábado será para ustedes un día sagrado. Obsérvenlo. » ”Quien no lo observe será condenado a muerte. » ”Quien haga algún trabajo en sábado será eliminado de su pueblo.'),
('nvi', 'Éxodo 31:15', 'Éxodo', 31, 15, '» ”Durante seis días se podrá trabajar, pero el día séptimo, el sábado, será de reposo consagrado al SEÑOR. » ”Quien haga algún trabajo en sábado será condenado a muerte.”'),
('nvi', 'Éxodo 31:16', 'Éxodo', 31, 16, '»Los israelitas deberán observar el sábado. En todas las generaciones futuras será para ellos un pacto perpetuo,'),
('nvi', 'Éxodo 31:17', 'Éxodo', 31, 17, 'una señal eterna entre ellos y yo. »En efecto, en seis días hizo el SEÑOR los cielos y la tierra, y el séptimo día descansó.»'),
('nvi', 'Éxodo 31:18', 'Éxodo', 31, 18, 'Y cuando terminó de hablar con Moisés en el monte Sinaí, le dio las dos tablas de la ley, que eran dos lajas escritas por el dedo mismo de Dios.'),
('nvi', 'Éxodo 32:1', 'Éxodo', 32, 1, 'Al ver los israelitas que Moisés tardaba en bajar del monte, fueron a reunirse con Aarón y le dijeron: —Tienes que hacernos dioses que marchen al frente de nosotros, porque a ese Moisés que nos sacó de Egipto, ¡no sabemos qué pudo haberle pasado!'),
('nvi', 'Éxodo 32:2', 'Éxodo', 32, 2, 'Aarón les respondió: —Quítenles a sus mujeres los aretes de oro, y también a sus hijos e hijas, y tráiganmelos.'),
('nvi', 'Éxodo 32:3', 'Éxodo', 32, 3, 'Todos los israelitas se quitaron los aretes de oro que llevaban puestos, y se los llevaron a Aarón,'),
('nvi', 'Éxodo 32:4', 'Éxodo', 32, 4, 'quien los recibió y los fundió; luego cinceló el oro fundido e hizo un ídolo en forma de becerro. Entonces exclamó el pueblo: «Israel, ¡aquí tienes a tu dios que te sacó de Egipto!»'),
('nvi', 'Éxodo 32:5', 'Éxodo', 32, 5, 'Cuando Aarón vio esto, construyó un altar enfrente del becerro y anunció: —Mañana haremos fiesta en honor del SEÑOR.'),
('nvi', 'Éxodo 32:6', 'Éxodo', 32, 6, 'En efecto, al día siguiente los israelitas madrugaron y presentaron holocaustos y sacrificios de comunión. Luego el pueblo se sentó a comer y a beber, y se entregó al desenfreno.'),
('nvi', 'Éxodo 32:7', 'Éxodo', 32, 7, 'Entonces el SEÑOR le dijo a Moisés: —Baja, porque ya se ha corrompido el pueblo que sacaste de Egipto.'),
('nvi', 'Éxodo 32:8', 'Éxodo', 32, 8, 'Demasiado pronto se han apartado del camino que les ordené seguir, pues no sólo han fundido oro y se han hecho un ídolo en forma de becerro, sino que se han inclinado ante él, le han ofrecido sacrificios, y han declarado: “Israel, ¡aquí tienes a tu dios que te sacó de Egipto!”'),
('nvi', 'Éxodo 32:9', 'Éxodo', 32, 9, '»Ya me he dado cuenta de que éste es un pueblo terco —añadió el SEÑOR, dirigiéndose a Moisés—.'),
('nvi', 'Éxodo 32:10', 'Éxodo', 32, 10, 'Tú no te metas. Yo voy a descargar mi ira sobre ellos, y los voy a destruir. Pero de ti haré una gran nación.'),
('nvi', 'Éxodo 32:11', 'Éxodo', 32, 11, 'Moisés intentó apaciguar al SEÑOR su Dios, y le suplicó: —SEÑOR, ¿por qué ha de encenderse tu ira contra este pueblo tuyo, que sacaste de Egipto con gran poder y con mano poderosa?'),
('nvi', 'Éxodo 32:12', 'Éxodo', 32, 12, '¿Por qué dar pie a que los egipcios digan que nos sacaste de su país con la intención de matarnos en las montañas y borrarnos de la faz de la tierra? ¡Calma ya tu enojo! ¡Aplácate y no traigas sobre tu pueblo esa desgracia!'),
('nvi', 'Éxodo 32:13', 'Éxodo', 32, 13, 'Acuérdate de tus siervos Abraham, Isaac e Israel. Tú mismo les juraste que harías a sus descendientes tan numerosos como las estrellas del cielo; ¡tú les prometiste que a sus descendientes les darías toda esta tierra como su herencia eterna!'),
('nvi', 'Éxodo 32:14', 'Éxodo', 32, 14, 'Entonces el SEÑOR se calmó y desistió de hacerle a su pueblo el daño que le había sentenciado.'),
('nvi', 'Éxodo 32:15', 'Éxodo', 32, 15, 'Moisés volvió entonces del monte. Cuando bajó, traía en sus manos las dos tablas de la ley, las cuales estaban escritas por sus dos lados.'),
('nvi', 'Éxodo 32:16', 'Éxodo', 32, 16, 'Tanto las tablas como la escritura grabada en ellas eran obra de Dios.'),
('nvi', 'Éxodo 32:17', 'Éxodo', 32, 17, 'Cuando Josué oyó el ruido y los gritos del pueblo, le dijo a Moisés: —Se oyen en el campamento gritos de guerra.'),
('nvi', 'Éxodo 32:18', 'Éxodo', 32, 18, 'Pero Moisés respondió: «Lo que escucho no son gritos de victoria, ni tampoco lamentos de derrota; más bien, lo que escucho son canciones.»'),
('nvi', 'Éxodo 32:19', 'Éxodo', 32, 19, 'Cuando Moisés se acercó al campamento y vio el becerro y las danzas, ardió en ira y arrojó de sus manos las tablas de la ley, haciéndolas pedazos al pie del monte.'),
('nvi', 'Éxodo 32:20', 'Éxodo', 32, 20, 'Tomó entonces el becerro que habían hecho, lo arrojó al fuego y, luego de machacarlo hasta hacerlo polvo, lo esparció en el agua y se la dio a beber a los israelitas.'),
('nvi', 'Éxodo 32:21', 'Éxodo', 32, 21, 'A Aarón le dijo: —¿Qué te hizo este pueblo? ¿Por qué lo has hecho cometer semejante pecado?'),
('nvi', 'Éxodo 32:22', 'Éxodo', 32, 22, '—Hermano mío, no te enojes —contestó Aarón—. Tú bien sabes cuán inclinado al mal es este pueblo.'),
('nvi', 'Éxodo 32:23', 'Éxodo', 32, 23, 'Ellos me dijeron: “Tienes que hacernos dioses que marchen al frente de nosotros, porque a ese Moisés que nos sacó de Egipto, ¡no sabemos qué pudo haberle pasado!”'),
('nvi', 'Éxodo 32:24', 'Éxodo', 32, 24, 'Yo les contesté que todo el que tuviera joyas de oro se desprendiera de ellas. Ellos me dieron el oro, yo lo eché al fuego, ¡y lo que salió fue este becerro!'),
('nvi', 'Éxodo 32:25', 'Éxodo', 32, 25, 'Al ver Moisés que el pueblo estaba desenfrenado y que Aarón les había permitido desmandarse y convertirse en el hazmerreír de sus enemigos,'),
('nvi', 'Éxodo 32:26', 'Éxodo', 32, 26, 'se puso a la entrada del campamento y dijo: «Todo el que esté de parte del SEÑOR, que se pase de mi lado.» Y se le unieron todos los levitas.'),
('nvi', 'Éxodo 32:27', 'Éxodo', 32, 27, 'Entonces les dijo Moisés: «El SEÑOR, Dios de Israel, ordena lo siguiente: “Cíñase cada uno la espada y recorra todo el campamento de un extremo al otro, y mate al que se le ponga enfrente, sea hermano, amigo o vecino.”»'),
('nvi', 'Éxodo 32:28', 'Éxodo', 32, 28, 'Los levitas hicieron lo que les mandó Moisés, y aquel día mataron como a tres mil israelitas.'),
('nvi', 'Éxodo 32:29', 'Éxodo', 32, 29, 'Entonces dijo Moisés: «Hoy han recibido ustedes plena autoridad de parte del SEÑOR; él los ha bendecido este día, pues se pusieron en contra de sus propios hijos y hermanos.»'),
('nvi', 'Éxodo 32:30', 'Éxodo', 32, 30, 'Al día siguiente, Moisés les dijo a los israelitas: «Ustedes han cometido un gran pecado. Pero voy a subir ahora para reunirme con el SEÑOR, y tal vez logre yo que Dios les perdone su pecado.»'),
('nvi', 'Éxodo 32:31', 'Éxodo', 32, 31, 'Volvió entonces Moisés para hablar con el SEÑOR, y le dijo: —¡Qué pecado tan grande ha cometido este pueblo al hacerse dioses de oro!'),
('nvi', 'Éxodo 32:32', 'Éxodo', 32, 32, 'Sin embargo, yo te ruego que les perdones su pecado. Pero si no vas a perdonarlos, ¡bórrame del libro que has escrito!'),
('nvi', 'Éxodo 32:33', 'Éxodo', 32, 33, 'El SEÑOR le respondió a Moisés: —Sólo borraré de mi libro a quien haya pecado contra mí.'),
('nvi', 'Éxodo 32:34', 'Éxodo', 32, 34, 'Tú ve y lleva al pueblo al lugar del que te hablé. Delante de ti irá mi ángel. Llegará el día en que deba castigarlos por su pecado, y entonces los castigaré.'),
('nvi', 'Éxodo 32:35', 'Éxodo', 32, 35, 'Fue así como, por causa del becerro que había hecho Aarón, el SEÑOR lanzó una plaga sobre el pueblo.'),
('nvi', 'Éxodo 33:1', 'Éxodo', 33, 1, 'El SEÑOR le dijo a Moisés: «Anda, vete de este lugar, junto con el pueblo que sacaste de Egipto, y dirígete a la tierra que bajo juramento prometí a Abraham, Isaac y Jacob que les daría a sus descendientes.'),
('nvi', 'Éxodo 33:2', 'Éxodo', 33, 2, 'Enviaré un ángel delante de ti, y desalojaré a cananeos, amorreos, hititas, ferezeos, heveos y jebuseos.'),
('nvi', 'Éxodo 33:3', 'Éxodo', 33, 3, 'Ve a la tierra donde abundan la leche y la miel. Yo no los acompañaré, porque ustedes son un pueblo terco, y podría yo destruirlos en el camino.»'),
('nvi', 'Éxodo 33:4', 'Éxodo', 33, 4, 'Cuando los israelitas oyeron estas palabras tan demoledoras, comenzaron a llorar y nadie volvió a ponerse sus joyas,'),
('nvi', 'Éxodo 33:5', 'Éxodo', 33, 5, 'pues el SEÑOR le había dicho a Moisés: «Diles a los israelitas que son un pueblo terco. Si aun por un momento tuviera que acompañarlos, podría destruirlos. Diles que se quiten esas joyas, que ya decidiré qué hacer con ellos.»'),
('nvi', 'Éxodo 33:6', 'Éxodo', 33, 6, 'Por eso, a partir del monte Horeb los israelitas no volvieron a ponerse joyas.'),
('nvi', 'Éxodo 33:7', 'Éxodo', 33, 7, 'Moisés tomó una tienda de campaña y la armó a cierta distancia fuera del campamento. La llamó «la Tienda de la reunión con el SEÑOR». Cuando alguien quería consultar al SEÑOR, tenía que salir del campamento e ir a esa tienda.'),
('nvi', 'Éxodo 33:8', 'Éxodo', 33, 8, 'Siempre que Moisés se dirigía a ella, todo el pueblo se quedaba de pie a la entrada de su carpa y seguía a Moisés con la mirada, hasta que éste entraba en la Tienda de reunión.'),
('nvi', 'Éxodo 33:9', 'Éxodo', 33, 9, 'En cuanto Moisés entraba en ella, la columna de nube descendía y tapaba la entrada, mientras el SEÑOR hablaba con Moisés.'),
('nvi', 'Éxodo 33:10', 'Éxodo', 33, 10, 'Cuando los israelitas veían que la columna de nube se detenía a la entrada de la Tienda de reunión, todos ellos se inclinaban a la entrada de su carpa y adoraban al SEÑOR.'),
('nvi', 'Éxodo 33:11', 'Éxodo', 33, 11, 'Y hablaba el SEÑOR con Moisés cara a cara, como quien habla con un amigo. Después de eso, Moisés regresaba al campamento; pero Josué, su joven asistente, nunca se apartaba de la Tienda de reunión.'),
('nvi', 'Éxodo 33:12', 'Éxodo', 33, 12, 'Moisés le dijo al SEÑOR: —Tú insistes en que yo debo guiar a este pueblo, pero no me has dicho a quién enviarás conmigo. También me has dicho que soy tu amigo y que cuento con tu favor.'),
('nvi', 'Éxodo 33:13', 'Éxodo', 33, 13, 'Pues si realmente es así, dime qué quieres que haga. Así sabré que en verdad cuento con tu favor. Ten presente que los israelitas son tu pueblo.'),
('nvi', 'Éxodo 33:14', 'Éxodo', 33, 14, '—Yo mismo iré contigo y te daré descanso —respondió el SEÑOR.'),
('nvi', 'Éxodo 33:15', 'Éxodo', 33, 15, '—O vas con todos nosotros —replicó Moisés—, o mejor no nos hagas salir de aquí.'),
('nvi', 'Éxodo 33:16', 'Éxodo', 33, 16, 'Si no vienes con nosotros, ¿cómo vamos a saber, tu pueblo y yo, que contamos con tu favor? ¿En qué seríamos diferentes de los demás pueblos de la tierra?'),
('nvi', 'Éxodo 33:17', 'Éxodo', 33, 17, '—Está bien, haré lo que me pides —le dijo el SEÑOR a Moisés—, pues cuentas con mi favor y te considero mi amigo.'),
('nvi', 'Éxodo 33:18', 'Éxodo', 33, 18, '—Déjame verte en todo tu esplendor —insistió Moisés.'),
('nvi', 'Éxodo 33:19', 'Éxodo', 33, 19, 'Y el SEÑOR le respondió: —Voy a darte pruebas de mi bondad, y te daré a conocer mi nombre. Y verás que tengo clemencia de quien quiero tenerla, y soy compasivo con quien quiero serlo.'),
('nvi', 'Éxodo 33:20', 'Éxodo', 33, 20, 'Pero debo aclararte que no podrás ver mi rostro, porque nadie puede verme y seguir con vida.'),
('nvi', 'Éxodo 33:21', 'Éxodo', 33, 21, '»Cerca de mí hay un lugar sobre una roca —añadió el SEÑOR—. Puedes quedarte allí.'),
('nvi', 'Éxodo 33:22', 'Éxodo', 33, 22, 'Cuando yo pase en todo mi esplendor, te pondré en una hendidura de la roca y te cubriré con mi mano, hasta que haya pasado.'),
('nvi', 'Éxodo 33:23', 'Éxodo', 33, 23, 'Luego, retiraré la mano y podrás verme la espalda. Pero mi rostro no lo verás.'),
('nvi', 'Éxodo 34:1', 'Éxodo', 34, 1, 'El SEÑOR le dijo a Moisés: «Labra dos tablas de piedra semejantes a las primeras que rompiste. Voy a escribir en ellas lo mismo que estaba escrito en las primeras.'),
('nvi', 'Éxodo 34:2', 'Éxodo', 34, 2, 'Prepárate para subir mañana a la cumbre del monte Sinaí, y presentarte allí ante mí.'),
('nvi', 'Éxodo 34:3', 'Éxodo', 34, 3, 'Nadie debe acompañarte, ni debe verse a nadie en ninguna parte del monte. Ni siquiera las ovejas y las vacas deben pastar frente al monte.»'),
('nvi', 'Éxodo 34:4', 'Éxodo', 34, 4, 'Moisés labró dos tablas de piedra semejantes a las primeras, y muy de mañana subió con ellas al monte Sinaí, como se lo había ordenado el SEÑOR.'),
('nvi', 'Éxodo 34:5', 'Éxodo', 34, 5, 'El SEÑOR descendió en la nube y se puso junto a Moisés. Luego le dio a conocer su nombre:'),
('nvi', 'Éxodo 34:6', 'Éxodo', 34, 6, 'pasando delante de él, proclamó: —El SEÑOR, el SEÑOR, Dios clemente y compasivo, lento para la ira y grande en amor y fidelidad,'),
('nvi', 'Éxodo 34:7', 'Éxodo', 34, 7, 'que mantiene su amor hasta mil generaciones después, y que perdona la iniquidad, la rebelión y el pecado; pero que no deja sin castigo al culpable, sino que castiga la maldad de los padres en los hijos y en los nietos, hasta la tercera y la cuarta generación.'),
('nvi', 'Éxodo 34:8', 'Éxodo', 34, 8, 'En seguida Moisés se inclinó hasta el suelo, y oró al Señor'),
('nvi', 'Éxodo 34:9', 'Éxodo', 34, 9, 'de la siguiente manera: —Señor, si realmente cuento con tu favor, ven y quédate entre nosotros. Reconozco que éste es un pueblo terco, pero perdona nuestra iniquidad y nuestro pecado, y adóptanos como tu herencia.'),
('nvi', 'Éxodo 34:10', 'Éxodo', 34, 10, '—Mira el pacto que hago contigo —respondió el SEÑOR—. A la vista de todo tu pueblo haré maravillas que ante ninguna nación del mundo han sido realizadas. El pueblo en medio del cual vives verá las imponentes obras que yo, el SEÑOR, haré por ti.'),
('nvi', 'Éxodo 34:11', 'Éxodo', 34, 11, 'Por lo que a ti toca, cumple con lo que hoy te mando. Echaré de tu presencia a los amorreos, cananeos, hititas, ferezeos, heveos y jebuseos.'),
('nvi', 'Éxodo 34:12', 'Éxodo', 34, 12, 'Ten mucho cuidado de no hacer ningún pacto con los habitantes de la tierra que vas a ocupar, pues de lo contrario serán para ti una trampa.'),
('nvi', 'Éxodo 34:13', 'Éxodo', 34, 13, 'Derriba sus altares, y haz pedazos sus piedras sagradas y sus imágenes de la diosa Aserá.'),
('nvi', 'Éxodo 34:14', 'Éxodo', 34, 14, 'No adores a otros dioses, porque el SEÑOR es muy celoso. Su nombre es Dios celoso.'),
('nvi', 'Éxodo 34:15', 'Éxodo', 34, 15, '»No hagas ningún pacto con los habitantes de esta tierra, porque se prostituyen por ir tras sus dioses, y cuando les ofrezcan sacrificios a esos dioses, te invitarán a participar de ellos.'),
('nvi', 'Éxodo 34:16', 'Éxodo', 34, 16, 'Y si casas a tu hijo con una de sus mujeres, cuando ella se prostituya por ir tras sus dioses, inducirá a tu hijo a hacer lo mismo.'),
('nvi', 'Éxodo 34:17', 'Éxodo', 34, 17, '»No te hagas ídolos de metal fundido.'),
('nvi', 'Éxodo 34:18', 'Éxodo', 34, 18, '»Celebra la fiesta de los Panes sin levadura, y come de ese pan durante siete días, como te lo he ordenado. Celebra esa fiesta en el mes de aviv, que es la fecha señalada, pues en ese mes saliste de Egipto.'),
('nvi', 'Éxodo 34:19', 'Éxodo', 34, 19, '»Todo hijo primogénito me pertenece, incluyendo las primeras crías de tus vacas y de tus ovejas.'),
('nvi', 'Éxodo 34:20', 'Éxodo', 34, 20, 'Deberás rescatar a todos tus primogénitos. Al asno primogénito podrás rescatarlo a cambio de un cordero; pero si no lo rescatas, tendrás que romperle el cuello. »Nadie se presentará ante mí con las manos vacías.'),
('nvi', 'Éxodo 34:21', 'Éxodo', 34, 21, '»Trabaja durante seis días, pero descansa el séptimo. Ese día deberás descansar, incluso en el tiempo de arar y cosechar.'),
('nvi', 'Éxodo 34:22', 'Éxodo', 34, 22, '»Celebra con las primicias la fiesta de las Semanas, y también la fiesta de la cosecha de fin de año.'),
('nvi', 'Éxodo 34:23', 'Éxodo', 34, 23, '»Todos tus varones deberán presentarse ante mí, su SEÑOR y Dios, el Dios de Israel, tres veces al año.'),
('nvi', 'Éxodo 34:24', 'Éxodo', 34, 24, 'Entonces yo echaré de tu presencia a las naciones, ensancharé tu territorio y nadie codiciará tu tierra.'),
('nvi', 'Éxodo 34:25', 'Éxodo', 34, 25, '»Cuando me ofrezcas un animal, no mezcles con levadura su sangre. »Del animal que se ofrece en la fiesta de la Pascua no debe quedar nada para el día siguiente.'),
('nvi', 'Éxodo 34:26', 'Éxodo', 34, 26, '»Lleva tus mejores primicias a la casa del SEÑOR tu Dios. »No cuezas ningún cabrito en la leche de su madre.'),
('nvi', 'Éxodo 34:27', 'Éxodo', 34, 27, 'El SEÑOR le dijo a Moisés: —Pon estas palabras por escrito, pues en ellas se basa el pacto que ahora hago contigo y con Israel.'),
('nvi', 'Éxodo 34:28', 'Éxodo', 34, 28, 'Y Moisés se quedó en el monte, con el SEÑOR, cuarenta días y cuarenta noches, sin comer ni beber nada. Allí, en las tablas, escribió los términos del pacto, es decir, los diez mandamientos.'),
('nvi', 'Éxodo 34:29', 'Éxodo', 34, 29, 'Cuando Moisés descendió del monte Sinaí, traía en sus manos las dos tablas de la ley. Pero no sabía que, por haberle hablado el SEÑOR, de su rostro salía un haz de luz.'),
('nvi', 'Éxodo 34:30', 'Éxodo', 34, 30, 'Al ver Aarón y todos los israelitas el rostro resplandeciente de Moisés, tuvieron miedo de acercársele;'),
('nvi', 'Éxodo 34:31', 'Éxodo', 34, 31, 'pero Moisés llamó a Aarón y a todos los jefes, y ellos regresaron para hablar con él.'),
('nvi', 'Éxodo 34:32', 'Éxodo', 34, 32, 'Luego se le acercaron todos los israelitas, y Moisés les ordenó acatar todo lo que el SEÑOR le había dicho en el monte Sinaí.'),
('nvi', 'Éxodo 34:33', 'Éxodo', 34, 33, 'En cuanto Moisés terminó de hablar con ellos, se cubrió el rostro con un velo.'),
('nvi', 'Éxodo 34:34', 'Éxodo', 34, 34, 'Siempre que entraba a la presencia del SEÑOR para hablar con él, se quitaba el velo mientras no salía. Al salir, les comunicaba a los israelitas lo que el Señor le había ordenado decir.'),
('nvi', 'Éxodo 34:35', 'Éxodo', 34, 35, 'Y como los israelitas veían que su rostro resplandecía, Moisés se cubría de nuevo el rostro, hasta que entraba a hablar otra vez con el SEÑOR.'),
('nvi', 'Éxodo 35:1', 'Éxodo', 35, 1, 'Moisés reunió a toda la comunidad israelita, y les dijo: «Éstas son las órdenes que el SEÑOR les manda cumplir:'),
('nvi', 'Éxodo 35:2', 'Éxodo', 35, 2, 'Trabajen durante seis días, pero el séptimo día, el sábado, será para ustedes un día de reposo consagrado al SEÑOR. Quien haga algún trabajo en él será condenado a muerte.'),
('nvi', 'Éxodo 35:3', 'Éxodo', 35, 3, 'En sábado no se encenderá ningún fuego en ninguna de sus casas.»'),
('nvi', 'Éxodo 35:4', 'Éxodo', 35, 4, 'Moisés le dijo a toda la comunidad israelita: «Esto es lo que el SEÑOR les ordena:'),
('nvi', 'Éxodo 35:5', 'Éxodo', 35, 5, 'Tomen de entre sus pertenencias una ofrenda para el SEÑOR. Todo el que se sienta movido a hacerlo, presente al SEÑOR una ofrenda de oro, plata y bronce;'),
('nvi', 'Éxodo 35:6', 'Éxodo', 35, 6, 'lana púrpura, carmesí y escarlata; lino, pelo de cabra,'),
('nvi', 'Éxodo 35:7', 'Éxodo', 35, 7, 'pieles de carnero teñidas de rojo y pieles de delfín, madera de acacia,'),
('nvi', 'Éxodo 35:8', 'Éxodo', 35, 8, 'aceite de oliva para el alumbrado, especias para el aceite de la unción y para el incienso aromático,'),
('nvi', 'Éxodo 35:9', 'Éxodo', 35, 9, 'y piedras de ónice y otras piedras preciosas para engastarlas en el efod y en el pectoral.'),
('nvi', 'Éxodo 35:10', 'Éxodo', 35, 10, '»Todos los artesanos hábiles que haya entre ustedes deben venir y hacer todo lo que el SEÑOR ha ordenado que se haga:'),
('nvi', 'Éxodo 35:11', 'Éxodo', 35, 11, 'el santuario, con su tienda y su toldo, sus ganchos, sus tablones, sus travesaños, sus postes y sus bases;'),
('nvi', 'Éxodo 35:12', 'Éxodo', 35, 12, 'el arca con sus varas, el propiciatorio y la cortina que resguarda el arca;'),
('nvi', 'Éxodo 35:13', 'Éxodo', 35, 13, 'la mesa con sus varas y todos sus utensilios, y el pan de la Presencia;'),
('nvi', 'Éxodo 35:14', 'Éxodo', 35, 14, 'el candelabro para el alumbrado y sus accesorios, las lámparas y el aceite para el alumbrado;'),
('nvi', 'Éxodo 35:15', 'Éxodo', 35, 15, 'el altar del incienso con sus varas, el aceite de la unción y el incienso aromático, la cortina para la puerta a la entrada del santuario,'),
('nvi', 'Éxodo 35:16', 'Éxodo', 35, 16, 'el altar del los holocaustos con su enrejado de bronce, sus varas y todos sus utensilios, el lavamanos de bronce con su pedestal,'),
('nvi', 'Éxodo 35:17', 'Éxodo', 35, 17, 'las cortinas del atrio con sus postes y bases, la cortina para la entrada del atrio,'),
('nvi', 'Éxodo 35:18', 'Éxodo', 35, 18, 'las estacas del toldo para el santuario y para el atrio, y sus cuerdas;'),
('nvi', 'Éxodo 35:19', 'Éxodo', 35, 19, 'y las vestiduras tejidas que deben llevar los sacerdotes para ministrar en el santuario, tanto las vestiduras sagradas para Aarón como las vestiduras para sus hijos.»'),
('nvi', 'Éxodo 35:20', 'Éxodo', 35, 20, 'Toda la comunidad israelita se retiró de la presencia de Moisés,'),
('nvi', 'Éxodo 35:21', 'Éxodo', 35, 21, 'y todos los que en su interior se sintieron movidos a hacerlo llevaron una ofrenda al SEÑOR para las obras en la Tienda de reunión, para todo su servicio, y para las vestiduras sagradas.'),
('nvi', 'Éxodo 35:22', 'Éxodo', 35, 22, 'Así mismo, todos los que se sintieron movidos a hacerlo, tanto hombres como mujeres, llevaron como ofrenda toda clase de joyas de oro: broches, pendientes, anillos, y otros adornos de oro. Todos ellos presentaron su oro como ofrenda mecida al SEÑOR,'),
('nvi', 'Éxodo 35:23', 'Éxodo', 35, 23, 'o bien llevaron lo que tenían: lana púrpura, carmesí y escarlata, lino, pelo de cabra, pieles de carnero teñidas de rojo, y pieles de delfín.'),
('nvi', 'Éxodo 35:24', 'Éxodo', 35, 24, 'Los que tenían plata o bronce los presentaron como ofrenda al SEÑOR, lo mismo que quienes tenían madera de acacia, contribuyendo así con algo para la obra.'),
('nvi', 'Éxodo 35:25', 'Éxodo', 35, 25, 'Las mujeres expertas en artes manuales presentaron los hilos de lana púrpura, carmesí o escarlata que habían torcido, y lino.'),
('nvi', 'Éxodo 35:26', 'Éxodo', 35, 26, 'Otras, que conocían bien el oficio y se sintieron movidas a hacerlo, torcieron hilo de pelo de cabra.'),
('nvi', 'Éxodo 35:27', 'Éxodo', 35, 27, 'Los jefes llevaron piedras de ónice y otras piedras preciosas, para que se engastaran en el efod y en el pectoral.'),
('nvi', 'Éxodo 35:28', 'Éxodo', 35, 28, 'También llevaron especias y aceite de oliva para el alumbrado, el aceite de la unción y el incienso aromático.'),
('nvi', 'Éxodo 35:29', 'Éxodo', 35, 29, 'Todos los israelitas que se sintieron movidos a hacerlo, lo mismo hombres que mujeres, presentaron al SEÑOR ofrendas voluntarias para toda la obra que el SEÑOR, por medio de Moisés, les había mandado hacer.'),
('nvi', 'Éxodo 35:30', 'Éxodo', 35, 30, 'Moisés les dijo a los israelitas: «Tomen en cuenta que el SEÑOR ha escogido expresamente a Bezalel, hijo de Uri y nieto de Jur, de la tribu de Judá,'),
('nvi', 'Éxodo 35:31', 'Éxodo', 35, 31, 'y lo ha llenado del Espíritu de Dios, de sabiduría, inteligencia y capacidad creativa'),
('nvi', 'Éxodo 35:32', 'Éxodo', 35, 32, 'para hacer trabajos artísticos en oro, plata y bronce,'),
('nvi', 'Éxodo 35:33', 'Éxodo', 35, 33, 'para cortar y engastar piedras preciosas, para hacer tallados en madera y realizar toda clase de diseños artísticos y artesanías.'),
('nvi', 'Éxodo 35:34', 'Éxodo', 35, 34, 'Dios les ha dado a él y a Aholiab hijo de Ajisamac, de la tribu de Dan, la habilidad de enseñar a otros.'),
('nvi', 'Éxodo 35:35', 'Éxodo', 35, 35, 'Los ha llenado de gran sabiduría para realizar toda clase de artesanías, diseños y recamados en lana púrpura, carmesí y escarlata, y lino. Son expertos tejedores y hábiles artesanos en toda clase de labores y diseños.'),
('nvi', 'Éxodo 36:1', 'Éxodo', 36, 1, '»Así, pues, Bezalel y Aholiab llevarán a cabo los trabajos para el servicio del santuario, tal y como el SEÑOR lo ha ordenado, junto con todos los que tengan ese mismo espíritu artístico, y a quienes el SEÑOR haya dado pericia y habilidad para realizar toda la obra del servicio del santuario.»'),
('nvi', 'Éxodo 36:2', 'Éxodo', 36, 2, 'Moisés llamó a Bezalel y a Aholiab, y a todos los que tenían el mismo espíritu artístico, y a quienes el SEÑOR había dado pericia y habilidad y se sentían movidos a venir y hacer el trabajo,'),
('nvi', 'Éxodo 36:3', 'Éxodo', 36, 3, 'y les entregó todas las ofrendas que los israelitas habían llevado para realizar la obra del servicio del santuario. Pero como día tras día el pueblo seguía llevando ofrendas voluntarias,'),
('nvi', 'Éxodo 36:4', 'Éxodo', 36, 4, 'todos los artesanos y expertos que estaban ocupados en la obra del santuario suspendieron su trabajo'),
('nvi', 'Éxodo 36:5', 'Éxodo', 36, 5, 'para ir a decirle a Moisés: «La gente está trayendo más de lo que se necesita para llevar a cabo la obra que el SEÑOR mandó hacer.»'),
('nvi', 'Éxodo 36:6', 'Éxodo', 36, 6, 'Entonces Moisés ordenó que corriera la voz por todo el campamento: «¡Que nadie, ni hombre ni mujer, haga más labores ni traiga más ofrendas para el santuario!» De ese modo los israelitas dejaron de llevar más ofrendas,'),
('nvi', 'Éxodo 36:7', 'Éxodo', 36, 7, 'pues lo que ya habían hecho era más que suficiente para llevar a cabo toda la obra.'),
('nvi', 'Éxodo 36:8', 'Éxodo', 36, 8, 'Todos los obreros con espíritu artístico hicieron el santuario con diez cortinas de lino fino y de lana púrpura, carmesí y escarlata, con querubines artísticamente bordados en ellas.'),
('nvi', 'Éxodo 36:9', 'Éxodo', 36, 9, 'Todas las cortinas medían lo mismo, es decir, doce metros y medio de largo por un metro con ochenta centímetros de ancho.'),
('nvi', 'Éxodo 36:10', 'Éxodo', 36, 10, 'Cosieron cinco cortinas una con otra, e hicieron lo mismo con las otras cinco.'),
('nvi', 'Éxodo 36:11', 'Éxodo', 36, 11, 'En el borde de la cortina, en el extremo del primer conjunto, hicieron presillas de lana púrpura; lo mismo hicieron con la cortina que estaba en el extremo del otro conjunto.'),
('nvi', 'Éxodo 36:12', 'Éxodo', 36, 12, 'También hicieron cincuenta presillas en una cortina, y otras cincuenta presillas en la cortina del extremo del otro conjunto, quedando las presillas unas frente a las otras.'),
('nvi', 'Éxodo 36:13', 'Éxodo', 36, 13, 'Después hicieron cincuenta ganchos de oro y los usaron para sujetar los dos conjuntos de cortinas, de modo que el santuario tenía unidad de conjunto.'),
('nvi', 'Éxodo 36:14', 'Éxodo', 36, 14, 'Hicieron un total de once cortinas de pelo de cabra para cubrir el santuario a la manera de una tienda de campaña.'),
('nvi', 'Éxodo 36:15', 'Éxodo', 36, 15, 'Las once cortinas tenían las mismas medidas, es decir, trece metros y medio de largo por un metro con ochenta centímetros de ancho.'),
('nvi', 'Éxodo 36:16', 'Éxodo', 36, 16, 'Cosieron dos conjuntos de cortinas, uno de cinco y otro de seis;'),
('nvi', 'Éxodo 36:17', 'Éxodo', 36, 17, 'hicieron cincuenta presillas en el borde de la cortina del extremo de uno de los conjuntos, y también en el borde de la cortina del extremo del otro conjunto,'),
('nvi', 'Éxodo 36:18', 'Éxodo', 36, 18, 'e hicieron cincuenta ganchos de bronce para unir la tienda en un solo conjunto.'),
('nvi', 'Éxodo 36:19', 'Éxodo', 36, 19, 'Luego hicieron para la tienda un toldo de pieles de carnero teñidas de rojo, y sobre ese toldo pusieron otro de pieles de delfín.'),
('nvi', 'Éxodo 36:20', 'Éxodo', 36, 20, 'Hicieron tablones de madera de acacia para el santuario, y los colocaron en posición vertical.'),
('nvi', 'Éxodo 36:21', 'Éxodo', 36, 21, 'Cada tablón medía cuatro metros y medio de largo por setenta centímetros de ancho,'),
('nvi', 'Éxodo 36:22', 'Éxodo', 36, 22, 'con dos ranuras paralelas entre sí. Todos los tablones del santuario los hicieron así:'),
('nvi', 'Éxodo 36:23', 'Éxodo', 36, 23, 'Veinte tablones para el lado sur del santuario,'),
('nvi', 'Éxodo 36:24', 'Éxodo', 36, 24, 'con cuarenta bases de plata que iban debajo de ellos, dos por cada tablón, una debajo de cada ranura;'),
('nvi', 'Éxodo 36:25', 'Éxodo', 36, 25, 'veinte tablones para el lado opuesto, el lado norte del santuario,'),
('nvi', 'Éxodo 36:26', 'Éxodo', 36, 26, 'con cuarenta bases de plata que iban debajo de ellos, dos por cada tablón, una debajo de cada ranura;'),
('nvi', 'Éxodo 36:27', 'Éxodo', 36, 27, 'seis tablones para el extremo occidental del santuario, que era el más distante, y'),
('nvi', 'Éxodo 36:28', 'Éxodo', 36, 28, 'dos tablones más para las esquinas del santuario en el extremo opuesto.'),
('nvi', 'Éxodo 36:29', 'Éxodo', 36, 29, 'En estas dos esquinas los tablones eran dobles de abajo hacia arriba, pero quedaban unidos por un solo anillo. En ambas esquinas se hizo lo mismo,'),
('nvi', 'Éxodo 36:30', 'Éxodo', 36, 30, 'de modo que había ocho tablones y dieciséis bases de plata, dos debajo de cada tablón.'),
('nvi', 'Éxodo 36:31', 'Éxodo', 36, 31, 'También hicieron travesaños de madera de acacia: cinco para los tablones de un costado del santuario,'),
('nvi', 'Éxodo 36:32', 'Éxodo', 36, 32, 'cinco para los tablones del costado opuesto, y cinco para los tablones del costado occidental, en la parte posterior del santuario.'),
('nvi', 'Éxodo 36:33', 'Éxodo', 36, 33, 'El travesaño central lo hicieron de tal modo que pasaba de uno a otro extremo, a media altura de los tablones.'),
('nvi', 'Éxodo 36:34', 'Éxodo', 36, 34, 'Recubrieron de oro los tablones, e hicieron unos anillos de oro para que los travesaños pasaran por ellos. También recubrieron de oro los travesaños.'),
('nvi', 'Éxodo 36:35', 'Éxodo', 36, 35, 'La cortina la hicieron de lana púrpura, carmesí y escarlata, y de lino fino, con querubines artísticamente bordados en ella.'),
('nvi', 'Éxodo 36:36', 'Éxodo', 36, 36, 'Le hicieron cuatro postes de madera de acacia y los recubrieron de oro, les pusieron ganchos de oro, y fundieron para ellos cuatro bases de plata.'),
('nvi', 'Éxodo 36:37', 'Éxodo', 36, 37, 'Para la entrada de la tienda hicieron una cortina de lana teñida de púrpura, carmesí y escarlata, y de lino fino, recamada artísticamente,'),
('nvi', 'Éxodo 36:38', 'Éxodo', 36, 38, 'y cinco postes con ganchos, para los que hicieron cinco bases de bronce; también recubrieron de oro los capiteles y los empalmes de los postes.'),
('nvi', 'Éxodo 37:1', 'Éxodo', 37, 1, 'Bezalel hizo el arca de madera de acacia, de un metro con diez centímetros de largo por setenta centímetros de ancho y setenta centímetros de alto.'),
('nvi', 'Éxodo 37:2', 'Éxodo', 37, 2, 'La recubrió de oro puro por dentro y por fuera, y puso en su derredor una moldura de oro.'),
('nvi', 'Éxodo 37:3', 'Éxodo', 37, 3, 'Fundió cuatro anillos de oro para el arca, y se los ajustó a sus cuatro patas, colocando dos anillos en un lado y dos en el otro.'),
('nvi', 'Éxodo 37:4', 'Éxodo', 37, 4, 'Hizo luego unas varas de madera de acacia, las recubrió de oro,'),
('nvi', 'Éxodo 37:5', 'Éxodo', 37, 5, 'y las pasó a través de los anillos en los costados del arca para poder transportarla.'),
('nvi', 'Éxodo 37:6', 'Éxodo', 37, 6, 'El propiciatorio lo hizo de oro puro, de un metro con diez centímetros de largo por setenta centímetros de ancho.'),
('nvi', 'Éxodo 37:7', 'Éxodo', 37, 7, 'Para los dos extremos del propiciatorio hizo dos querubines de oro trabajado a martillo.'),
('nvi', 'Éxodo 37:8', 'Éxodo', 37, 8, 'Uno de ellos iba en uno de los extremos, y el otro iba en el otro extremo; los hizo de modo que en ambos extremos los dos querubines formaran una sola pieza con el propiciatorio.'),
('nvi', 'Éxodo 37:9', 'Éxodo', 37, 9, 'Los querubines tenían las alas extendidas por encima del propiciatorio, y con ellas lo cubrían. Quedaban el uno frente al otro, mirando hacia el propiciatorio.'),
('nvi', 'Éxodo 37:10', 'Éxodo', 37, 10, 'Bezalel hizo la mesa de madera de acacia, de noventa centímetros de largo por cuarenta y cinco centímetros de ancho y setenta centímetros de alto.'),
('nvi', 'Éxodo 37:11', 'Éxodo', 37, 11, 'La recubrió de oro puro y le puso en derredor una moldura de oro.'),
('nvi', 'Éxodo 37:12', 'Éxodo', 37, 12, 'También le hizo un reborde de veinte centímetros de ancho, y alrededor del reborde le puso una moldura de oro.'),
('nvi', 'Éxodo 37:13', 'Éxodo', 37, 13, 'Fundió cuatro anillos de oro para la mesa y se los sujetó a las cuatro esquinas, donde iban las cuatro patas.'),
('nvi', 'Éxodo 37:14', 'Éxodo', 37, 14, 'Los anillos fueron colocados cerca del reborde para pasar por ellos las varas empleadas para transportar la mesa.'),
('nvi', 'Éxodo 37:15', 'Éxodo', 37, 15, 'Esas varas eran de madera de acacia y estaban recubiertas de oro.'),
('nvi', 'Éxodo 37:16', 'Éxodo', 37, 16, 'Los utensilios para la mesa, y sus platos, bandejas, tazones, y jarras para derramar las ofrendas de libación, los hizo de oro puro.'),
('nvi', 'Éxodo 37:17', 'Éxodo', 37, 17, 'Bezalel hizo el candelabro de oro puro labrado a martillo. Su base y su tallo, y sus copas, cálices y flores formaban una sola pieza con él.'),
('nvi', 'Éxodo 37:18', 'Éxodo', 37, 18, 'De los costados del candelabro salían seis brazos, tres de un lado y tres del otro.'),
('nvi', 'Éxodo 37:19', 'Éxodo', 37, 19, 'En cada uno de los seis brazos del candelabro había tres copas en forma de flores de almendro, con cálices y pétalos.'),
('nvi', 'Éxodo 37:20', 'Éxodo', 37, 20, 'El candelabro mismo tenía cuatro copas en forma de flor de almendro, con cálices y pétalos.'),
('nvi', 'Éxodo 37:21', 'Éxodo', 37, 21, 'Debajo del primer par de brazos que salía del candelabro había un cáliz; debajo del segundo par de brazos había un segundo cáliz, y debajo del tercer par de brazos había un tercer cáliz.'),
('nvi', 'Éxodo 37:22', 'Éxodo', 37, 22, 'Los cálices y los brazos formaban una sola pieza con el candelabro, el cual era de oro puro labrado a martillo.'),
('nvi', 'Éxodo 37:23', 'Éxodo', 37, 23, 'Hizo también de oro puro sus siete lámparas, lo mismo que sus cortapabilos y braseros.'),
('nvi', 'Éxodo 37:24', 'Éxodo', 37, 24, 'Para hacer el candelabro y todos sus accesorios, usó treinta y tres kilos de oro puro.'),
('nvi', 'Éxodo 37:25', 'Éxodo', 37, 25, 'Bezalel hizo de madera de acacia el altar del incienso. Era cuadrado, de cuarenta y cinco centímetros de largo por cuarenta y cinco centímetros de ancho y noventa centímetros de alto. Sus cuernos formaban una sola pieza con el altar.'),
('nvi', 'Éxodo 37:26', 'Éxodo', 37, 26, 'Recubrió de oro puro su parte superior, sus cuatro costados y sus cuernos, y en su derredor le puso una moldura de oro.'),
('nvi', 'Éxodo 37:27', 'Éxodo', 37, 27, 'Debajo de la moldura le puso dos anillos de oro, es decir, dos en cada uno de sus costados, para pasar por ellos las varas empleadas para transportarlo.'),
('nvi', 'Éxodo 37:28', 'Éxodo', 37, 28, 'Las varas eran de madera de acacia, y las recubrió de oro.'),
('nvi', 'Éxodo 37:29', 'Éxodo', 37, 29, 'Bezalel hizo también el aceite de la unción sagrada y el incienso puro y aromático, como lo hacen los fabricantes de perfumes.'),
('nvi', 'Éxodo 38:1', 'Éxodo', 38, 1, 'Bezalel hizo de madera de acacia el altar de los holocaustos. Era cuadrado, de dos metros con treinta centímetros por lado, y de un metro con treinta centímetros de alto.'),
('nvi', 'Éxodo 38:2', 'Éxodo', 38, 2, 'Puso un cuerno en cada una de sus cuatro esquinas, los cuales formaban una sola pieza con el altar, y el altar lo recubrió de bronce.'),
('nvi', 'Éxodo 38:3', 'Éxodo', 38, 3, 'Hizo de bronce todos sus utensilios: sus portacenizas, sus tenazas, sus aspersorios, sus tridentes y sus braseros.'),
('nvi', 'Éxodo 38:4', 'Éxodo', 38, 4, 'Hizo también un enrejado para el altar —una rejilla de bronce—, y la puso bajo el reborde inferior del altar, a media altura del mismo.'),
('nvi', 'Éxodo 38:5', 'Éxodo', 38, 5, 'Fundió cuatro anillos de bronce para las cuatro esquinas del enrejado de bronce, para pasar por ellos las varas;'),
('nvi', 'Éxodo 38:6', 'Éxodo', 38, 6, 'hizo las varas de madera de acacia, las recubrió de bronce'),
('nvi', 'Éxodo 38:7', 'Éxodo', 38, 7, 'y las introdujo en los anillos, de modo que quedaron a los dos costados del altar para poder transportarlo. El altar lo hizo hueco y de tablas.'),
('nvi', 'Éxodo 38:8', 'Éxodo', 38, 8, 'Además, con el bronce de los espejos de las mujeres que servían a la entrada de la Tienda de reunión, hizo el lavamanos y su pedestal.'),
('nvi', 'Éxodo 38:9', 'Éxodo', 38, 9, 'Después hicieron el atrio. El lado sur medía cuarenta y cinco metros de largo, y tenía cortinas de lino fino,'),
('nvi', 'Éxodo 38:10', 'Éxodo', 38, 10, 'veinte postes y veinte bases de bronce, con ganchos y empalmes de plata en los postes.'),
('nvi', 'Éxodo 38:11', 'Éxodo', 38, 11, 'El lado norte medía también cuarenta y cinco metros de largo, y tenía veinte postes y veinte bases de bronce, con ganchos y empalmes de plata en los postes.'),
('nvi', 'Éxodo 38:12', 'Éxodo', 38, 12, 'El lado occidental medía veintidós metros y medio de ancho, y tenía cortinas y diez postes y diez bases, con ganchos y empalmes de plata en los postes.'),
('nvi', 'Éxodo 38:13', 'Éxodo', 38, 13, 'Por el lado oriental, hacia la salida del sol, medía también veintidós metros y medio de ancho.'),
('nvi', 'Éxodo 38:14', 'Éxodo', 38, 14, 'A un lado de la entrada había cortinas de siete metros de largo, tres postes y tres bases,'),
('nvi', 'Éxodo 38:15', 'Éxodo', 38, 15, 'y al otro lado de la entrada había también cortinas de siete metros de largo, tres postes y tres bases.'),
('nvi', 'Éxodo 38:16', 'Éxodo', 38, 16, 'Todas las cortinas que rodeaban el atrio eran de lino fino.'),
('nvi', 'Éxodo 38:17', 'Éxodo', 38, 17, 'Las bases para los postes eran de bronce, los ganchos y los empalmes en los postes eran de plata, y sus capiteles estaban recubiertos de plata. Todos los postes del atrio tenían empalmes de plata.'),
('nvi', 'Éxodo 38:18', 'Éxodo', 38, 18, 'La cortina a la entrada del atrio era de lana teñida de púrpura, carmesí y escarlata, y de lino fino, recamada artísticamente. Medía nueve metros de largo por dos metros con treinta centímetros de alto, como las cortinas del atrio,'),
('nvi', 'Éxodo 38:19', 'Éxodo', 38, 19, 'y tenía cuatro postes y cuatro bases de bronce. Sus ganchos y sus empalmes eran de plata, y sus capiteles estaban recubiertos de plata.'),
('nvi', 'Éxodo 38:20', 'Éxodo', 38, 20, 'Todas las estacas del toldo para el santuario y del atrio que lo rodeaba eran de bronce.'),
('nvi', 'Éxodo 38:21', 'Éxodo', 38, 21, 'Éstas son las cantidades de los materiales usados para el santuario del pacto. Los levitas hicieron este registro por orden de Moisés y bajo la dirección de Itamar, hijo del sacerdote Aarón.'),
('nvi', 'Éxodo 38:22', 'Éxodo', 38, 22, 'Bezalel, hijo de Uri y nieto de Jur, de la tribu de Judá, hizo todo lo que el SEÑOR le ordenó a Moisés.'),
('nvi', 'Éxodo 38:23', 'Éxodo', 38, 23, 'Con él estaba Aholiab hijo de Ajisamac, de la tribu de Dan, que era artesano, diseñador y recamador en lana teñida de púrpura, carmesí y escarlata, y en lino.'),
('nvi', 'Éxodo 38:24', 'Éxodo', 38, 24, 'El total del oro dado como ofrenda y empleado en toda la obra del santuario era de una tonelada, según la tasación oficial del santuario.'),
('nvi', 'Éxodo 38:25', 'Éxodo', 38, 25, 'La plata entregada por los miembros de la comunidad contados en el censo llegó a tres toneladas y media, según la tasación oficial del santuario.'),
('nvi', 'Éxodo 38:26', 'Éxodo', 38, 26, 'Todos los mayores de veinte años de edad que fueron censados llegaron a un total de seiscientos tres mil quinientos cincuenta, y cada uno de ellos dio seis gramos de plata, según la tasación oficial del santuario.'),
('nvi', 'Éxodo 38:27', 'Éxodo', 38, 27, 'Tres mil trescientos kilos de plata se emplearon en las cien bases fundidas para el santuario y para la cortina, de modo que cada base pesaba treinta y tres kilos.'),
('nvi', 'Éxodo 38:28', 'Éxodo', 38, 28, 'La plata restante se empleó en hacer los ganchos para los postes y recubrir los capiteles de los postes, y para hacer sus empalmes.'),
('nvi', 'Éxodo 38:29', 'Éxodo', 38, 29, 'El total del bronce dado como ofrenda fue de dos mil trescientos cuarenta kilos,'),
('nvi', 'Éxodo 38:30', 'Éxodo', 38, 30, 'y se empleó en las bases para la entrada de la Tienda de reunión, en el altar de bronce con su enrejado de bronce y todos sus utensilios,'),
('nvi', 'Éxodo 38:31', 'Éxodo', 38, 31, 'en las bases para el atrio y la entrada al atrio, y en todas las estacas del toldo para el santuario y para el atrio que lo rodeaba.'),
('nvi', 'Éxodo 39:1', 'Éxodo', 39, 1, 'Las vestiduras tejidas para ministrar en el santuario se hicieron de lana teñida de púrpura, carmesí y escarlata. También se hicieron vestiduras sagradas para Aarón, como se lo mandó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 39:2', 'Éxodo', 39, 2, 'El efod lo hizo Bezalel de oro, lana teñida de púrpura, carmesí y escarlata, y lino fino.'),
('nvi', 'Éxodo 39:3', 'Éxodo', 39, 3, 'Martillaron finas láminas de oro, y las cortaron en hebras para entretejerlas artísticamente con la lana teñida de púrpura, carmesí y escarlata, y con el lino.'),
('nvi', 'Éxodo 39:4', 'Éxodo', 39, 4, 'Se hicieron hombreras para el efod, las cuales se sujetaron a sus dos extremos.'),
('nvi', 'Éxodo 39:5', 'Éxodo', 39, 5, 'Su cinturón tenía la misma hechura que el efod, y formaba una sola pieza con él; estaba hecho de oro, lana teñida de púrpura, carmesí y escarlata, y lino fino, como se lo mandó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 39:6', 'Éxodo', 39, 6, 'Las piedras de ónice se engarzaron en los engastes de filigrana de oro, y en ellas se grabaron, a manera de sello, los nombres de los hijos de Israel.'),
('nvi', 'Éxodo 39:7', 'Éxodo', 39, 7, 'Luego las sujetaron a las hombreras del efod para recordar a los hijos de Israel, como se lo mandó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 39:8', 'Éxodo', 39, 8, 'Bezalel hizo también el pectoral, bordado artísticamente, como el efod, con hilo de oro, lana teñida de púrpura, carmesí y escarlata, y lino fino,'),
('nvi', 'Éxodo 39:9', 'Éxodo', 39, 9, 'doble y cuadrado, de veinte centímetros por lado.'),
('nvi', 'Éxodo 39:10', 'Éxodo', 39, 10, 'En él se engastaron cuatro filas de piedras preciosas. En la primera fila había un rubí, un crisólito y una esmeralda;'),
('nvi', 'Éxodo 39:11', 'Éxodo', 39, 11, 'en la segunda hilera, una turquesa, un zafiro y un jade;'),
('nvi', 'Éxodo 39:12', 'Éxodo', 39, 12, 'en la tercera hilera, un jacinto, un ágata y una amatista;'),
('nvi', 'Éxodo 39:13', 'Éxodo', 39, 13, 'en la cuarta hilera, un topacio, un ónice y un jaspe. Estaban engarzadas en engastes de filigrana de oro,'),
('nvi', 'Éxodo 39:14', 'Éxodo', 39, 14, 'y eran doce piedras, una por cada uno de los hijos de Israel, grabada a manera de sello con el nombre de cada una de las doce tribus.'),
('nvi', 'Éxodo 39:15', 'Éxodo', 39, 15, 'Para el pectoral se hicieron cadenillas de oro puro, a manera de cordón.'),
('nvi', 'Éxodo 39:16', 'Éxodo', 39, 16, 'Se hicieron dos engastes en filigrana de oro y dos anillos de oro, y se sujetaron los anillos en los dos extremos del pectoral;'),
('nvi', 'Éxodo 39:17', 'Éxodo', 39, 17, 'luego se sujetaron las dos cadenillas de oro en los anillos a los extremos del pectoral,'),
('nvi', 'Éxodo 39:18', 'Éxodo', 39, 18, 'y los otros dos extremos de las cadenillas en los dos engastes, asegurándolos a las hombreras del efod por la parte delantera.'),
('nvi', 'Éxodo 39:19', 'Éxodo', 39, 19, 'Se hicieron otros dos anillos de oro, y los sujetaron a los otros dos extremos del pectoral, en el borde interior, junto al efod.'),
('nvi', 'Éxodo 39:20', 'Éxodo', 39, 20, 'Además, se hicieron otros dos anillos de oro, los cuales sujetaron la parte inferior de las hombreras, por delante del efod y junto a la costura, exactamente encima del cinturón del efod.'),
('nvi', 'Éxodo 39:21', 'Éxodo', 39, 21, 'Con un cordón de lana púrpura ataron los anillos del pectoral a los anillos del efod, a fin de unir el pectoral al cinturón para que no se desprendiera del efod, como se lo mandó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 39:22', 'Éxodo', 39, 22, 'Bezalel hizo de lana teñida de púrpura, y tejido artísticamente, todo el manto del efod.'),
('nvi', 'Éxodo 39:23', 'Éxodo', 39, 23, 'Lo hizo con una abertura en el centro, como abertura para la cabeza, y con un refuerzo alrededor de la abertura, para que no se rasgara.'),
('nvi', 'Éxodo 39:24', 'Éxodo', 39, 24, 'En todo el borde inferior del manto se hicieron granadas de lana púrpura, carmesí y escarlata, y de lino fino,'),
('nvi', 'Éxodo 39:25', 'Éxodo', 39, 25, 'lo mismo que campanillas de oro puro, las cuales se colocaron en todo el borde inferior, entre las granadas.'),
('nvi', 'Éxodo 39:26', 'Éxodo', 39, 26, 'Las campanillas y las granadas se colocaron, en forma alternada, en todo el borde inferior del manto que debía llevarse para ejercer el ministerio, como se lo mandó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 39:27', 'Éxodo', 39, 27, 'Para Aarón y sus hijos se hicieron túnicas de lino tejidas artísticamente,'),
('nvi', 'Éxodo 39:28', 'Éxodo', 39, 28, 'las mitras y el turbante de lino, y la ropa interior de lino fino.'),
('nvi', 'Éxodo 39:29', 'Éxodo', 39, 29, 'La faja era de lino fino y de lana teñida de púrpura, carmesí y escarlata, recamada artísticamente, como se lo mandó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 39:30', 'Éxodo', 39, 30, 'La placa sagrada se hizo de oro puro, y se grabó en ella, a manera de sello, Santo para el SEÑOR.'),
('nvi', 'Éxodo 39:31', 'Éxodo', 39, 31, 'Luego se le ató un cordón de lana teñida de púrpura para sujetarla al turbante, como se lo mandó el SEÑOR a Moisés.'),
('nvi', 'Éxodo 39:32', 'Éxodo', 39, 32, 'Toda la obra del santuario, es decir, la Tienda de reunión, quedó terminada. Los israelitas lo hicieron todo tal y como el SEÑOR se lo mandó a Moisés,'),
('nvi', 'Éxodo 39:33', 'Éxodo', 39, 33, 'y le presentaron a Moisés el santuario, la tienda y todos sus utensilios, sus ganchos, tablones, travesaños, postes y bases,'),
('nvi', 'Éxodo 39:34', 'Éxodo', 39, 34, 'el toldo de pieles de carnero teñidas de rojo, el toldo de pieles de delfín y la cortina que resguardaba el arca,'),
('nvi', 'Éxodo 39:35', 'Éxodo', 39, 35, 'el arca del pacto con sus varas y el propiciatorio,'),
('nvi', 'Éxodo 39:36', 'Éxodo', 39, 36, 'la mesa con todos sus utensilios y el pan de la Presencia,'),
('nvi', 'Éxodo 39:37', 'Éxodo', 39, 37, 'el candelabro de oro puro con su hilera de lámparas y todos sus utensilios, y el aceite para el alumbrado;'),
('nvi', 'Éxodo 39:38', 'Éxodo', 39, 38, 'el altar de oro, el aceite de la unción, el incienso aromático y la cortina para la entrada de la tienda,'),
('nvi', 'Éxodo 39:39', 'Éxodo', 39, 39, 'el altar de bronce con su enrejado de bronce, sus varas y todos sus utensilios; el lavamanos y su pedestal,'),
('nvi', 'Éxodo 39:40', 'Éxodo', 39, 40, 'las cortinas del atrio con sus postes y bases, y la cortina para la entrada del atrio; las cuerdas y las estacas del toldo para el atrio; todos los utensilios para el santuario, la Tienda de reunión,'),
('nvi', 'Éxodo 39:41', 'Éxodo', 39, 41, 'y las vestiduras tejidas para ministrar en el santuario, tanto las vestiduras sagradas para el sacerdote Aarón como las vestiduras sacerdotales para sus hijos.'),
('nvi', 'Éxodo 39:42', 'Éxodo', 39, 42, 'Los israelitas hicieron toda la obra tal y como el SEÑOR se lo había ordenado a Moisés.'),
('nvi', 'Éxodo 39:43', 'Éxodo', 39, 43, 'Moisés, por su parte, inspeccionó la obra y, al ver que la habían hecho tal y como el SEÑOR se lo había ordenado, los bendijo.'),
('nvi', 'Éxodo 40:1', 'Éxodo', 40, 1, 'El SEÑOR habló con Moisés y le dijo:'),
('nvi', 'Éxodo 40:2', 'Éxodo', 40, 2, '«En el día primero del mes primero, levanta el santuario, es decir, la Tienda de reunión.'),
('nvi', 'Éxodo 40:3', 'Éxodo', 40, 3, 'Pon en su interior el arca del pacto, y cúbrela con la cortina.'),
('nvi', 'Éxodo 40:4', 'Éxodo', 40, 4, 'Lleva adentro la mesa y ponla en orden. Pon también dentro del santuario el candelabro, y enciende sus lámparas.'),
('nvi', 'Éxodo 40:5', 'Éxodo', 40, 5, 'Coloca el altar del incienso frente al arca del pacto, y cuelga la cortina a la entrada del santuario.'),
('nvi', 'Éxodo 40:6', 'Éxodo', 40, 6, '»Coloca el altar de los holocaustos frente a la entrada del santuario, la Tienda de reunión;'),
('nvi', 'Éxodo 40:7', 'Éxodo', 40, 7, 'coloca el lavamanos entre la Tienda de reunión y el altar, y pon agua en él.'),
('nvi', 'Éxodo 40:8', 'Éxodo', 40, 8, 'Levanta el atrio en su derredor, y coloca la cortina a la entrada del atrio.'),
('nvi', 'Éxodo 40:9', 'Éxodo', 40, 9, '»Toma el aceite de la unción, y unge el santuario y todo lo que haya en él; conságralo, junto con todos sus utensilios, para que sea un objeto sagrado.'),
('nvi', 'Éxodo 40:10', 'Éxodo', 40, 10, 'Unge también el altar de los holocaustos y todos sus utensilios; conságralo, para que sea un objeto muy sagrado.'),
('nvi', 'Éxodo 40:11', 'Éxodo', 40, 11, 'Unge además, y consagra, el lavamanos y su pedestal.'),
('nvi', 'Éxodo 40:12', 'Éxodo', 40, 12, '»Lleva luego a Aarón y a sus hijos a la entrada de la Tienda de reunión, haz que se bañen,'),
('nvi', 'Éxodo 40:13', 'Éxodo', 40, 13, 'y ponle a Aarón sus vestiduras sagradas. Úngelo y conságralo, para que ministre como sacerdote mío.'),
('nvi', 'Éxodo 40:14', 'Éxodo', 40, 14, 'Acerca entonces a sus hijos, ponles sus túnicas,'),
('nvi', 'Éxodo 40:15', 'Éxodo', 40, 15, 'y úngelos como ungiste a su padre, para que ministren como mis sacerdotes. La unción les conferirá un sacerdocio válido para todas las generaciones venideras.»'),
('nvi', 'Éxodo 40:16', 'Éxodo', 40, 16, 'Moisés hizo todo tal y como el SEÑOR se lo mandó.'),
('nvi', 'Éxodo 40:17', 'Éxodo', 40, 17, 'Fue así como el santuario se instaló el día primero del mes primero del año segundo.'),
('nvi', 'Éxodo 40:18', 'Éxodo', 40, 18, 'Al instalar el santuario, Moisés puso en su lugar las bases, levantó los tablones, los insertó en los travesaños, y levantó los postes;'),
('nvi', 'Éxodo 40:19', 'Éxodo', 40, 19, 'luego extendió la tienda de campaña sobre el santuario, y encima de ésta puso el toldo, tal y como el SEÑOR se lo mandó.'),
('nvi', 'Éxodo 40:20', 'Éxodo', 40, 20, 'A continuación, tomó el documento del pacto y lo puso en el arca; luego ajustó las varas al arca, y sobre ella puso el propiciatorio.'),
('nvi', 'Éxodo 40:21', 'Éxodo', 40, 21, 'Llevó el arca al interior del santuario, y colgó la cortina para resguardarla. De este modo protegió el arca del pacto, tal y como el SEÑOR se lo había ordenado.'),
('nvi', 'Éxodo 40:22', 'Éxodo', 40, 22, 'Moisés puso la mesa en la Tienda de reunión, en el lado norte del santuario, fuera de la cortina,'),
('nvi', 'Éxodo 40:23', 'Éxodo', 40, 23, 'y puso el pan en orden ante el SEÑOR, como el SEÑOR se lo había ordenado.'),
('nvi', 'Éxodo 40:24', 'Éxodo', 40, 24, 'Colocó luego el candelabro en la Tienda de reunión, frente a la mesa, en el lado sur del santuario,'),
('nvi', 'Éxodo 40:25', 'Éxodo', 40, 25, 'y encendió las lámparas ante el SEÑOR, como el SEÑOR se lo había ordenado.'),
('nvi', 'Éxodo 40:26', 'Éxodo', 40, 26, 'Puso también el altar de oro en la Tienda de reunión, frente a la cortina,'),
('nvi', 'Éxodo 40:27', 'Éxodo', 40, 27, 'y sobre él quemó incienso aromático, tal y como el SEÑOR se lo había ordenado.'),
('nvi', 'Éxodo 40:28', 'Éxodo', 40, 28, 'Después de eso colgó la cortina a la entrada del santuario.'),
('nvi', 'Éxodo 40:29', 'Éxodo', 40, 29, 'Moisés puso también el altar de los holocaustos a la entrada del santuario, la Tienda de reunión, y sobre él ofreció holocaustos y ofrendas de grano, tal y como el SEÑOR se lo había ordenado.'),
('nvi', 'Éxodo 40:30', 'Éxodo', 40, 30, 'Colocó luego el lavamanos entre la Tienda de reunión y el altar, y echó en ella agua para lavarse,'),
('nvi', 'Éxodo 40:31', 'Éxodo', 40, 31, 'y Moisés, Aarón y sus hijos se lavaron allí las manos y los pies.'),
('nvi', 'Éxodo 40:32', 'Éxodo', 40, 32, 'Siempre que entraban en la Tienda de reunión o se acercaban al altar se lavaban, tal y como el SEÑOR se lo había ordenado.'),
('nvi', 'Éxodo 40:33', 'Éxodo', 40, 33, 'Después levantó Moisés el atrio en torno al santuario y al altar, y colgó la cortina a la entrada del atrio. Así terminó Moisés la obra.'),
('nvi', 'Éxodo 40:34', 'Éxodo', 40, 34, 'En ese instante la nube cubrió la Tienda de reunión, y la gloria del SEÑOR llenó el santuario.'),
('nvi', 'Éxodo 40:35', 'Éxodo', 40, 35, 'Moisés no podía entrar en la Tienda de reunión porque la nube se había posado en ella y la gloria del SEÑOR llenaba el santuario.'),
('nvi', 'Éxodo 40:36', 'Éxodo', 40, 36, 'Siempre que la nube se levantaba y se apartaba del santuario, los israelitas levantaban campamento y se ponían en marcha.'),
('nvi', 'Éxodo 40:37', 'Éxodo', 40, 37, 'Si la nube no se levantaba, ellos no se ponían en marcha.'),
('nvi', 'Éxodo 40:38', 'Éxodo', 40, 38, 'Durante todas las marchas de los israelitas, la nube del SEÑOR reposaba sobre el santuario durante el día, pero durante la noche había fuego en la nube, a la vista de todo el pueblo de Israel.'),
('nvi', 'Levítico 1:1', 'Levítico', 1, 1, 'El SEÑOR llamó a Moisés y le habló desde la Tienda de reunión. Le ordenó'),
('nvi', 'Levítico 1:2', 'Levítico', 1, 2, 'que les dijera a los israelitas: «Cuando alguno de ustedes traiga una ofrenda al SEÑOR, deberá presentar un animal de ganado vacuno u ovino.'),
('nvi', 'Levítico 1:3', 'Levítico', 1, 3, '»Si el animal que ofrece en holocausto es de ganado vacuno, deberá presentar un macho sin defecto, a la entrada de la Tienda de reunión. Así será aceptable al SEÑOR.'),
('nvi', 'Levítico 1:4', 'Levítico', 1, 4, 'Pondrá su mano sobre la cabeza de la víctima, la cual le será aceptada en su lugar y le servirá de propiciación.'),
('nvi', 'Levítico 1:5', 'Levítico', 1, 5, 'Después degollará el novillo ante el SEÑOR, y los hijos de Aarón, los sacerdotes, tomarán la sangre y la derramarán alrededor del altar que está a la entrada de la Tienda de reunión.'),
('nvi', 'Levítico 1:6', 'Levítico', 1, 6, 'Luego desollará la víctima del holocausto y la cortará en trozos.'),
('nvi', 'Levítico 1:7', 'Levítico', 1, 7, 'Los hijos de Aarón, los sacerdotes, harán fuego sobre el altar y le echarán leña;'),
('nvi', 'Levítico 1:8', 'Levítico', 1, 8, 'después acomodarán los trozos sobre la leña encendida del altar, junto con la cabeza y el sebo.'),
('nvi', 'Levítico 1:9', 'Levítico', 1, 9, 'Las entrañas y las patas se lavarán con agua, y el sacerdote lo quemará todo en el altar. Es un holocausto, una ofrenda presentada por fuego de aroma grato al SEÑOR.'),
('nvi', 'Levítico 1:10', 'Levítico', 1, 10, '»Si alguien ofrece un holocausto de ganado ovino, sea de corderos o de cabras, deberá presentar un macho sin defecto.'),
('nvi', 'Levítico 1:11', 'Levítico', 1, 11, 'Lo degollará ante el SEÑOR, en el costado norte del altar, y los hijos de Aarón, los sacerdotes, derramarán la sangre alrededor del altar.'),
('nvi', 'Levítico 1:12', 'Levítico', 1, 12, 'Luego lo cortará en trozos, los cuales el sacerdote acomodará sobre la leña encendida del altar, junto con la cabeza y el sebo.'),
('nvi', 'Levítico 1:13', 'Levítico', 1, 13, 'Las entrañas y las patas se lavarán con agua, y el sacerdote lo tomará todo y lo quemará en el altar. Es un holocausto, una ofrenda presentada por fuego de aroma grato al SEÑOR.'),
('nvi', 'Levítico 1:14', 'Levítico', 1, 14, '»Si alguien ofrece al SEÑOR un holocausto de ave, deberá presentar una tórtola o un pichón de paloma.'),
('nvi', 'Levítico 1:15', 'Levítico', 1, 15, 'El sacerdote llevará el ave al altar y le arrancará la cabeza, y luego la quemará en el altar. Después exprimirá la sangre en un costado del altar,'),
('nvi', 'Levítico 1:16', 'Levítico', 1, 16, 'y le quitará también el buche y las entrañas, y los arrojará hacia el costado oriental del altar, donde se echa la ceniza.'),
('nvi', 'Levítico 1:17', 'Levítico', 1, 17, 'Después la desgarrará por las alas, pero sin arrancárselas. Entonces el sacerdote la quemará en el altar, sobre la leña encendida. Es un holocausto, una ofrenda presentada por fuego de aroma grato al SEÑOR.'),
('nvi', 'Levítico 2:1', 'Levítico', 2, 1, '»Si alguien presenta al SEÑOR una ofrenda de cereal, ésta será de flor de harina, sobre la cual pondrá aceite e incienso.'),
('nvi', 'Levítico 2:2', 'Levítico', 2, 2, 'Luego la llevará a los hijos de Aarón, los sacerdotes; allí tomará un puñado de flor de harina con aceite, junto con todo el incienso, y el sacerdote quemará esa ofrenda memorial en el altar. Es una ofrenda presentada por fuego de aroma grato al SEÑOR.'),
('nvi', 'Levítico 2:3', 'Levítico', 2, 3, 'El resto de la ofrenda de cereal será para Aarón y sus hijos. Entre las ofrendas por fuego que se presentan al SEÑOR, ésta es sumamente sagrada.'),
('nvi', 'Levítico 2:4', 'Levítico', 2, 4, '»Si presentas una ofrenda de cereal cocida al horno, ésta será de panes de flor de harina sin levadura, amasados con aceite, o de obleas sin levadura untadas con aceite.'),
('nvi', 'Levítico 2:5', 'Levítico', 2, 5, '»Si presentas una ofrenda de cereal cocida en la sartén, la ofrenda será de flor de harina sin levadura, amasada con aceite.'),
('nvi', 'Levítico 2:6', 'Levítico', 2, 6, 'La partirás en pedazos y le echarás aceite. Es una ofrenda de cereal.'),
('nvi', 'Levítico 2:7', 'Levítico', 2, 7, '»Si presentas una ofrenda de cereal cocida a la olla, la ofrenda será de flor de harina con aceite.'),
('nvi', 'Levítico 2:8', 'Levítico', 2, 8, 'Así preparada la ofrenda de cereal, se la llevarás al SEÑOR, es decir, se la llevarás al sacerdote, quien la presentará en el altar.'),
('nvi', 'Levítico 2:9', 'Levítico', 2, 9, 'El sacerdote, luego de tomar una parte como ofrenda memorial, la quemará en el altar. Es una ofrenda presentada por fuego de aroma grato al SEÑOR.'),
('nvi', 'Levítico 2:10', 'Levítico', 2, 10, 'El resto de la ofrenda de cereal será para Aarón y sus hijos. Entre las ofrendas por fuego que se presentan al SEÑOR, ésta es sumamente sagrada.'),
('nvi', 'Levítico 2:11', 'Levítico', 2, 11, '»Ninguna ofrenda de cereal que ustedes presenten al SEÑOR se hará de masa fermentada, porque en una ofrenda al Señor presentada por fuego no se deben quemar ni miel ni levadura.'),
('nvi', 'Levítico 2:12', 'Levítico', 2, 12, 'Llevarán al SEÑOR levadura y miel como ofrenda de primicias, pero no las pondrán sobre el altar como aroma grato.'),
('nvi', 'Levítico 2:13', 'Levítico', 2, 13, 'Todas las ofrendas de cereal las sazonarán con sal, y no dejarán que les falte la sal del pacto de su Dios. A todas las ofrendas deberán ponerles sal.'),
('nvi', 'Levítico 2:14', 'Levítico', 2, 14, '»Si le presentas al SEÑOR una ofrenda de las primicias de tus cereales, ésta será de trigo nuevo, molido y tostado al fuego. Es la ofrenda de cereal de tus primicias.'),
('nvi', 'Levítico 2:15', 'Levítico', 2, 15, 'Le pondrás aceite e incienso; es una ofrenda de cereal.'),
('nvi', 'Levítico 2:16', 'Levítico', 2, 16, 'El sacerdote quemará parte del trigo nuevo y molido como ofrenda memorial, junto con todo el incienso y el aceite. Es una ofrenda al SEÑOR presentada por fuego.'),
('nvi', 'Levítico 3:1', 'Levítico', 3, 1, '»Si alguien ofrece ganado vacuno al SEÑOR como sacrificio de comunión, deberá presentarle un animal sin defecto, sea macho o hembra.'),
('nvi', 'Levítico 3:2', 'Levítico', 3, 2, 'Pondrá su mano sobre la cabeza del animal, al que degollará a la entrada de la Tienda de reunión. Luego los hijos de Aarón, los sacerdotes, derramarán la sangre alrededor del altar.'),
('nvi', 'Levítico 3:3', 'Levítico', 3, 3, 'El oferente le presentará al SEÑOR, como ofrenda por fuego, las siguientes partes del sacrificio de comunión: la grasa que recubre los intestinos y la que se adhiere a éstos,'),
('nvi', 'Levítico 3:4', 'Levítico', 3, 4, 'los dos riñones y la grasa que los recubre, la grasa que recubre los lomos, y también el lóbulo del hígado, el cual se extraerá junto con los riñones.'),
('nvi', 'Levítico 3:5', 'Levítico', 3, 5, 'Entonces los hijos de Aarón quemarán todo esto en el altar, encima del holocausto que está sobre la leña encendida. Es una ofrenda presentada por fuego de aroma grato al SEÑOR.'),
('nvi', 'Levítico 3:6', 'Levítico', 3, 6, '»Si el sacrificio de comunión es de ganado ovino, el oferente deberá presentarle al SEÑOR un animal sin defecto, sea macho o hembra.'),
('nvi', 'Levítico 3:7', 'Levítico', 3, 7, 'Si la ofrenda es un cordero, lo presentará ante el SEÑOR'),
('nvi', 'Levítico 3:8', 'Levítico', 3, 8, 'y le impondrá la mano sobre la cabeza, degollando luego al animal ante la Tienda de reunión. Luego los hijos de Aarón derramarán la sangre alrededor del altar.'),
('nvi', 'Levítico 3:9', 'Levítico', 3, 9, 'El oferente le presentará al SEÑOR, como ofrenda por fuego, las siguientes partes de este sacrificio: la grasa, la cola entera (la cual cortará desde el espinazo), la grasa que recubre los intestinos y la que se adhiere a éstos,'),
('nvi', 'Levítico 3:10', 'Levítico', 3, 10, 'los dos riñones y la grasa que los recubre, la grasa que recubre los lomos, y también el lóbulo del hígado, el cual se extraerá junto con los riñones.'),
('nvi', 'Levítico 3:11', 'Levítico', 3, 11, 'Entonces el sacerdote quemará todo esto en el altar. Es una comida, una ofrenda presentada por fuego al SEÑOR.'),
('nvi', 'Levítico 3:12', 'Levítico', 3, 12, '»Si la ofrenda es una cabra, la presentará ante el SEÑOR'),
('nvi', 'Levítico 3:13', 'Levítico', 3, 13, 'poniendo la mano sobre la cabeza del animal, al que degollará ante la Tienda de reunión. Luego los hijos de Aarón derramarán la sangre alrededor del altar.'),
('nvi', 'Levítico 3:14', 'Levítico', 3, 14, 'El oferente le presentará al SEÑOR, como ofrenda por fuego, las siguientes partes del animal: la grasa que recubre los intestinos y la que se adhiere a éstos,'),
('nvi', 'Levítico 3:15', 'Levítico', 3, 15, 'los dos riñones y la grasa que los recubre, la grasa que recubre los lomos, y también el lóbulo del hígado, el cual se extraerá junto con los riñones.'),
('nvi', 'Levítico 3:16', 'Levítico', 3, 16, 'Entonces el sacerdote quemará todo esto en el altar. Es una comida, una ofrenda presentada por fuego de aroma grato. Toda la grasa pertenece al SEÑOR.'),
('nvi', 'Levítico 3:17', 'Levítico', 3, 17, '»Éste será un estatuto perpetuo para los descendientes de ustedes, dondequiera que habiten: No se comerán la grasa ni la sangre.»'),
('nvi', 'Levítico 4:1', 'Levítico', 4, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 4:2', 'Levítico', 4, 2, 'que les dijera a los israelitas: «Cuando alguien viole inadvertidamente cualquiera de los mandamientos del SEÑOR, e incurra en algo que esté prohibido, se procederá de la siguiente manera:'),
('nvi', 'Levítico 4:3', 'Levítico', 4, 3, '»Si el que peca es el sacerdote ungido, haciendo con ello culpable al pueblo, deberá ofrecer al SEÑOR, como sacrificio expiatorio por su pecado, un novillo sin defecto.'),
('nvi', 'Levítico 4:4', 'Levítico', 4, 4, 'Llevará el novillo ante el SEÑOR, a la entrada de la Tienda de reunión, e impondrá la mano sobre la cabeza del novillo, al que degollará en presencia del SEÑOR.'),
('nvi', 'Levítico 4:5', 'Levítico', 4, 5, 'El sacerdote ungido tomará un poco de la sangre del novillo y la llevará a la Tienda de reunión.'),
('nvi', 'Levítico 4:6', 'Levítico', 4, 6, 'Mojará el dedo en la sangre, y rociará con ella siete veces en dirección a la cortina del santuario, en presencia del SEÑOR.'),
('nvi', 'Levítico 4:7', 'Levítico', 4, 7, 'Después el sacerdote untará un poco de la sangre en los cuernos del altar del incienso aromático, que está ante el SEÑOR, en la Tienda de reunión. El resto de la sangre del novillo la derramará al pie del altar del holocausto, que está a la entrada de la Tienda de reunión.'),
('nvi', 'Levítico 4:8', 'Levítico', 4, 8, 'Luego, al novillo del sacrificio expiatorio le sacará toda la grasa que recubre los intestinos, y la que se adhiere a éstos,'),
('nvi', 'Levítico 4:9', 'Levítico', 4, 9, 'los dos riñones y la grasa que los recubre, la grasa que recubre los lomos, y también el lóbulo del hígado, el cual se extraerá junto con los riñones.'),
('nvi', 'Levítico 4:10', 'Levítico', 4, 10, 'Esto se hará tal y como se saca la grasa de la res para el sacrificio de comunión. Entonces el sacerdote quemará todo esto en el altar del holocausto,'),
('nvi', 'Levítico 4:11', 'Levítico', 4, 11, 'pero sacará del campamento la piel y toda la carne del novillo, junto con la cabeza, las patas, los intestinos y el excremento.'),
('nvi', 'Levítico 4:12', 'Levítico', 4, 12, 'Todo esto, es decir, el resto del novillo, lo sacará del campamento y lo llevará a un lugar ritualmente puro, al vertedero de la ceniza, y dejará que se consuma sobre la leña encendida. Sobre el vertedero de la ceniza se consumirá.'),
('nvi', 'Levítico 4:13', 'Levítico', 4, 13, '»Si la que peca inadvertidamente es toda la comunidad de Israel, toda la asamblea será culpable de haber hecho algo que los mandamientos del SEÑOR prohíben.'),
('nvi', 'Levítico 4:14', 'Levítico', 4, 14, 'Cuando la asamblea se dé cuenta del pecado que ha cometido, deberá ofrecer un novillo como sacrificio expiatorio. Lo llevarán a la Tienda de reunión,'),
('nvi', 'Levítico 4:15', 'Levítico', 4, 15, 'y allí, en presencia del SEÑOR, los ancianos de la comunidad impondrán las manos sobre la cabeza del novillo y lo degollarán.'),
('nvi', 'Levítico 4:16', 'Levítico', 4, 16, 'Luego el sacerdote ungido tomará un poco de la sangre del novillo y la llevará a la Tienda de reunión.'),
('nvi', 'Levítico 4:17', 'Levítico', 4, 17, 'Mojará el dedo en la sangre, y rociará con ella siete veces en dirección a la cortina en presencia del SEÑOR.'),
('nvi', 'Levítico 4:18', 'Levítico', 4, 18, 'Después untará un poco de la sangre en los cuernos del altar, que está ante el SEÑOR, en la Tienda de reunión. El resto de la sangre la derramará al pie del altar del holocausto, que está a la entrada de la Tienda de reunión,'),
('nvi', 'Levítico 4:19', 'Levítico', 4, 19, 'y sacará del animal toda la grasa, quemándola en el altar.'),
('nvi', 'Levítico 4:20', 'Levítico', 4, 20, 'Se hará con este novillo lo mismo que se hace con el de la ofrenda expiatoria. Así el sacerdote hará expiación por ellos, y serán perdonados.'),
('nvi', 'Levítico 4:21', 'Levítico', 4, 21, 'Luego sacará del campamento el resto del novillo y dejará que se consuma en el fuego, como el otro. Éste es el sacrificio expiatorio por la asamblea.'),
('nvi', 'Levítico 4:22', 'Levítico', 4, 22, '»Si el que peca inadvertidamente es uno de los gobernantes, e incurre en algo que los mandamientos del SEÑOR su Dios prohíben, será culpable.'),
('nvi', 'Levítico 4:23', 'Levítico', 4, 23, 'Cuando se le haga saber que ha cometido un pecado, llevará como ofrenda un macho cabrío sin defecto,'),
('nvi', 'Levítico 4:24', 'Levítico', 4, 24, 'pondrá la mano sobre la cabeza del macho cabrío, y lo degollará en presencia del SEÑOR, en el mismo lugar donde se degüellan los animales para el holocausto. Es un sacrificio expiatorio.'),
('nvi', 'Levítico 4:25', 'Levítico', 4, 25, 'Entonces el sacerdote tomará con el dedo un poco de la sangre del sacrificio expiatorio y la untará en los cuernos del altar del holocausto, después de lo cual derramará al pie del altar del holocausto el resto de la sangre.'),
('nvi', 'Levítico 4:26', 'Levítico', 4, 26, 'Toda la grasa del animal la quemará en el altar, tal como se hace con el sacrificio de comunión. Así el sacerdote hará expiación por el pecado del gobernante, y su pecado le será perdonado.'),
('nvi', 'Levítico 4:27', 'Levítico', 4, 27, '»Si el que peca inadvertidamente es alguien del pueblo, e incurre en algo que los mandamientos del SEÑOR prohíben, será culpable.'),
('nvi', 'Levítico 4:28', 'Levítico', 4, 28, 'Cuando se le haga saber que ha cometido un pecado, llevará como ofrenda por su pecado una cabra sin defecto.'),
('nvi', 'Levítico 4:29', 'Levítico', 4, 29, 'Pondrá la mano sobre la cabeza del animal, y lo degollará en el lugar donde se degüellan los animales para el holocausto.'),
('nvi', 'Levítico 4:30', 'Levítico', 4, 30, 'Entonces el sacerdote tomará con el dedo un poco de la sangre y la untará en los cuernos del altar del holocausto, después de lo cual derramará el resto de la sangre al pie del altar.'),
('nvi', 'Levítico 4:31', 'Levítico', 4, 31, 'Luego le sacará al animal toda la grasa, tal y como se le saca la grasa al sacrificio de comunión, y el sacerdote la quemará toda en el altar, como aroma grato al SEÑOR. Así el sacerdote hará expiación por él, y su pecado le será perdonado.'),
('nvi', 'Levítico 4:32', 'Levítico', 4, 32, '»Si la persona ofrece como sacrificio expiatorio un cordero, deberá presentar una hembra sin defecto.'),
('nvi', 'Levítico 4:33', 'Levítico', 4, 33, 'Pondrá la mano sobre la cabeza del animal, y lo degollará como sacrificio expiatorio en el lugar donde se degüellan los animales para el holocausto.'),
('nvi', 'Levítico 4:34', 'Levítico', 4, 34, 'Entonces el sacerdote tomará con el dedo un poco de la sangre del sacrificio expiatorio y la untará en los cuernos del altar del holocausto, después de lo cual derramará al pie del altar el resto de la sangre.'),
('nvi', 'Levítico 4:35', 'Levítico', 4, 35, 'Luego le sacará al animal toda la grasa, tal y como se le saca la grasa al cordero del sacrificio de comunión, y el sacerdote la quemará en el altar sobre la ofrenda presentada por fuego al SEÑOR. Así el sacerdote hará expiación por esa persona, y el pecado que haya cometido le será perdonado.'),
('nvi', 'Levítico 5:1', 'Levítico', 5, 1, '»Si alguien peca por negarse a declarar bajo juramento lo que vio o escuchó, sufrirá las consecuencias de su pecado.'),
('nvi', 'Levítico 5:2', 'Levítico', 5, 2, '»Si alguien sin darse cuenta toca alguna cosa ritualmente impura, tal como el cadáver de un animal impuro, sea o no doméstico, o el cadáver de un reptil impuro, se vuelve impuro él mismo y es culpable.'),
('nvi', 'Levítico 5:3', 'Levítico', 5, 3, '»Si alguien sin darse cuenta toca alguna impureza humana, cualquiera que ésta sea, se vuelve impuro él mismo. Pero al darse cuenta, será culpable.'),
('nvi', 'Levítico 5:4', 'Levítico', 5, 4, '»Si alguien hace uno de esos juramentos que se acostumbra hacer a la ligera, y sin saberlo jura hacer bien o mal, ha pecado. Pero al darse cuenta, será culpable de haber hecho ese juramento.'),
('nvi', 'Levítico 5:5', 'Levítico', 5, 5, '»Si alguien resulta culpable de alguna de estas cosas, deberá reconocer que ha pecado'),
('nvi', 'Levítico 5:6', 'Levítico', 5, 6, 'y llevarle al SEÑOR en sacrificio expiatorio por la culpa del pecado cometido, una hembra del rebaño, que podrá ser una oveja o una cabra. Así el sacerdote hará expiación por ese pecado.'),
('nvi', 'Levítico 5:7', 'Levítico', 5, 7, '»Si a alguien no le alcanza para comprar ganado menor, entonces le llevará al SEÑOR, como sacrificio por la culpa del pecado cometido, dos tórtolas o dos pichones de paloma, una de las aves como sacrificio por el pecado y la otra como holocausto.'),
('nvi', 'Levítico 5:8', 'Levítico', 5, 8, 'Se las llevará al sacerdote, quien primero ofrecerá el ave para el sacrificio expiatorio. Para esto, le retorcerá el cuello, pero sin desprenderle del todo la cabeza.'),
('nvi', 'Levítico 5:9', 'Levítico', 5, 9, 'Luego rociará un poco de la sangre del sacrificio expiatorio en un costado del altar, y al pie del altar exprimirá el resto de la sangre. Es un sacrificio expiatorio.'),
('nvi', 'Levítico 5:10', 'Levítico', 5, 10, 'Con la segunda ave hará un holocausto, como ya ha sido prescrito. Así el sacerdote hará expiación por el pecado cometido, y ese pecado le será perdonado.'),
('nvi', 'Levítico 5:11', 'Levítico', 5, 11, '»Si a esa persona tampoco le alcanza para comprar dos tórtolas o dos pichones, presentará entonces en sacrificio expiatorio, como ofrenda por el pecado cometido, dos litros de flor de harina. Como se trata de un sacrificio expiatorio, no se le pondrá aceite ni incienso.'),
('nvi', 'Levítico 5:12', 'Levítico', 5, 12, 'Llevará este sacrificio al sacerdote, quien tomará un puñado de la ofrenda memorial y lo quemará en el altar junto con los sacrificios presentados por fuego al SEÑOR. Es un sacrificio expiatorio.'),
('nvi', 'Levítico 5:13', 'Levítico', 5, 13, 'Así el sacerdote hará expiación por el pecado cometido en alguna de estas cosas, y ese pecado le será perdonado. El resto de la ofrenda será para el sacerdote, como sucede con la ofrenda de cereal.»'),
('nvi', 'Levítico 5:14', 'Levítico', 5, 14, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 5:15', 'Levítico', 5, 15, '«Si alguien comete una falta y peca inadvertidamente contra lo que ha sido consagrado al SEÑOR, le llevará al SEÑOR un carnero sin defecto como sacrificio por la culpa. Su precio será tasado en plata, según la tasación oficial del santuario. Es un sacrificio por la culpa.'),
('nvi', 'Levítico 5:16', 'Levítico', 5, 16, 'Además, el culpable hará restitución por haber pecado contra lo consagrado, añadiendo la quinta parte, la cual entregará al sacerdote. Así el sacerdote hará expiación por él mediante el carnero del sacrificio por la culpa, y ese pecado le será perdonado.'),
('nvi', 'Levítico 5:17', 'Levítico', 5, 17, '»Si alguien peca inadvertidamente e incurre en algo que los mandamientos del SEÑOR prohíben, es culpable y sufrirá las consecuencias de su pecado.'),
('nvi', 'Levítico 5:18', 'Levítico', 5, 18, 'Le llevará al sacerdote un carnero sin defecto, cuyo precio será fijado como sacrificio por la culpa. Así el sacerdote hará expiación por el pecado que esa persona cometió inadvertidamente, y ese pecado le será perdonado.'),
('nvi', 'Levítico 5:19', 'Levítico', 5, 19, 'Es un sacrificio por la culpa, de la que se hizo acreedor por pecar contra el SEÑOR.»'),
('nvi', 'Levítico 6:1', 'Levítico', 6, 1, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 6:2', 'Levítico', 6, 2, '«Si alguien comete una falta y peca contra el SEÑOR al defraudar a su prójimo en algo que se dejó a su cuidado, o si roba u oprime a su prójimo despojándolo de lo que es suyo,'),
('nvi', 'Levítico 6:3', 'Levítico', 6, 3, 'o si encuentra algo que se perdió y niega tenerlo, o si comete perjurio en alguna de las cosas en que se acostumbra pecar,'),
('nvi', 'Levítico 6:4', 'Levítico', 6, 4, 'será culpable y deberá devolver lo que haya robado, o quitado, o lo que se le haya dado a guardar, o el objeto perdido que niega tener,'),
('nvi', 'Levítico 6:5', 'Levítico', 6, 5, 'o cualquier otra cosa por la que haya cometido perjurio. Así que deberá restituirlo íntegramente y añadir la quinta parte de su valor. Todo esto lo entregará a su dueño el día que presente su sacrificio por la culpa.'),
('nvi', 'Levítico 6:6', 'Levítico', 6, 6, 'Le llevará al SEÑOR un carnero sin defecto, cuyo precio será fijado como sacrificio por la culpa. Lo presentará al sacerdote,'),
('nvi', 'Levítico 6:7', 'Levítico', 6, 7, 'quien hará expiación ante el SEÑOR por esa persona, y cualquier cosa por la que se haya hecho culpable le será perdonada.»'),
('nvi', 'Levítico 6:8', 'Levítico', 6, 8, '(El holocausto* El Señor le dijo a Moisés'),
('nvi', 'Levítico 6:9', 'Levítico', 6, 9, 'que les ordenara a Aarón y a sus hijos: "Ésta es la ley respecto al holocausto: El holocausto se dejará arder sobre el altar toda la noche hasta el amanecer, y el fuego del altar se mantendrá encendido.'),
('nvi', 'Levítico 6:10', 'Levítico', 6, 10, 'El sacerdote, vestido con su túnica de lino y su ropa interior de lino, removerá las cenizas del holocausto consumido por el fuego sobre el altar, y las echará a un lado del altar.'),
('nvi', 'Levítico 6:11', 'Levítico', 6, 11, 'Luego se cambiará de ropa y sacará del campamento las cenizas, llevándolas a un lugar ritualmente puro.'),
('nvi', 'Levítico 6:12', 'Levítico', 6, 12, 'Mientras tanto, el fuego se mantendrá encendido sobre el altar; no deberá apagarse. Cada mañana el sacerdote pondrá más leña sobre el altar, y encima de éste colocará el holocausto para quemar en él la grasa del sacrificio de comunión.'),
('nvi', 'Levítico 6:13', 'Levítico', 6, 13, 'El fuego sobre el altar no deberá apagarse nunca; siempre deberá estar encendido.'),
('nvi', 'Levítico 6:14', 'Levítico', 6, 14, '"Ésta es la ley respecto a la ofrenda de cereal: Los hijos de Aarón la presentarán ante el Señor, delante del altar.'),
('nvi', 'Levítico 6:15', 'Levítico', 6, 15, 'El sacerdote tomará de la ofrenda un puñado de flor de harina con aceite, así como todo el incienso que está sobre la ofrenda de cereal. Todo esto lo quemará en el altar, como ofrenda memorial de aroma grato al Señor.'),
('nvi', 'Levítico 6:16', 'Levítico', 6, 16, 'Aarón y sus hijos se comerán el resto de la ofrenda, pero sin levadura y en un lugar santo, que podrá ser el atrio de la Tienda de reunión.'),
('nvi', 'Levítico 6:17', 'Levítico', 6, 17, 'No se cocerá con levadura, porque esa es la porción que les doy de mis sacrificios presentados por fuego. Es una porción sumamente sagrada, como lo son el sacrificio expiatorio y el sacrificio por la culpa.'),
('nvi', 'Levítico 6:18', 'Levítico', 6, 18, 'Todos los hijos varones de Aarón podrán comer de ella. Es un estatuto perpetuo para los descendientes de ustedes, respecto a los sacrificios presentados por fuego al Señor. Cualquier cosa que toque los sacrificios quedará consagrada."'),
('nvi', 'Levítico 6:19', 'Levítico', 6, 19, 'El Señor le dijo a Moisés:'),
('nvi', 'Levítico 6:20', 'Levítico', 6, 20, '"Ésta es la ofrenda que Aarón y sus hijos deben presentar al Señor el día en que sean ungidos: dos kilos de flor de harina, como ofrenda regular de cereal. Una mitad de la ofrenda se presentará por la mañana, y la otra mitad por la tarde.'),
('nvi', 'Levítico 6:21', 'Levítico', 6, 21, 'Se preparará con aceite en una sartén, y se llevará amasada y se presentará en porciones, como una ofrenda de cereal de aroma grato al Señor.'),
('nvi', 'Levítico 6:22', 'Levítico', 6, 22, 'La preparará el hijo de Aarón que lo suceda como sacerdote ungido. Éste es el estatuto perpetuo del Señor: La ofrenda se quemará completamente.'),
('nvi', 'Levítico 6:23', 'Levítico', 6, 23, 'No se comerá ninguna de las ofrendas que presenten los sacerdotes; todas deberán quemarse por completo."'),
('nvi', 'Levítico 6:24', 'Levítico', 6, 24, 'El Señor le ordenó a Moisés'),
('nvi', 'Levítico 6:25', 'Levítico', 6, 25, 'que les dijera a Aarón y a sus hijos: "Ésta es la ley respecto al sacrificio expiatorio: La víctima deberá ser degollada ante el Señor, en el mismo lugar donde se degüellan los animales para el holocausto. Es algo sumamente sagrado.'),
('nvi', 'Levítico 6:26', 'Levítico', 6, 26, 'El mismo sacerdote que ofrezca el sacrificio expiatorio deberá comérselo. Se lo comerá en un lugar santo, que podrá ser el atrio de la Tienda de reunión.'),
('nvi', 'Levítico 6:27', 'Levítico', 6, 27, 'Cualquier cosa que toque la carne del sacrificio quedará consagrada. Si su sangre llega a salpicar algún vestido, éste deberá lavarse en un lugar santo.'),
('nvi', 'Levítico 6:28', 'Levítico', 6, 28, 'Además, deberá romperse la vasija de barro en que se haya cocido el sacrificio; pero si se cuece en una vasija de bronce, ésta se restregará y se enjuagará con agua.'),
('nvi', 'Levítico 6:29', 'Levítico', 6, 29, 'Todo varón entre los sacerdotes podrá comer del sacrificio. Es algo sumamente sagrado.'),
('nvi', 'Levítico 6:30', 'Levítico', 6, 30, 'Pero no se comerá ningún sacrificio expiatorio cuya sangre haya sido llevada a la Tienda de reunión para hacer propiciación en el santuario; este sacrificio se consumirá en el fuego.'),
('nvi', 'Levítico 7:1', 'Levítico', 7, 1, '»Ésta es la ley respecto al sacrificio por la culpa, el cual es sumamente sagrado:'),
('nvi', 'Levítico 7:2', 'Levítico', 7, 2, 'La víctima deberá ser degollada en el mismo lugar donde se degüellan los animales para el holocausto, y su sangre será derramada alrededor del altar.'),
('nvi', 'Levítico 7:3', 'Levítico', 7, 3, 'Luego se ofrecerá toda su grasa: la cola, la grasa que recubre los intestinos,'),
('nvi', 'Levítico 7:4', 'Levítico', 7, 4, 'los dos riñones y la grasa que los recubre, la grasa que recubre los lomos, y también el lóbulo del hígado, el cual se extraerá junto con los riñones.'),
('nvi', 'Levítico 7:5', 'Levítico', 7, 5, 'El sacerdote quemará todo esto en el altar como ofrenda presentada por fuego al SEÑOR. Es un sacrificio por la culpa.'),
('nvi', 'Levítico 7:6', 'Levítico', 7, 6, 'Todo varón entre los sacerdotes podrá comer del sacrificio, pero deberá comerlo en un lugar santo. Es algo sumamente sagrado.'),
('nvi', 'Levítico 7:7', 'Levítico', 7, 7, '»La misma ley se aplica tanto al sacrificio expiatorio como al sacrificio por la culpa: El animal pertenecerá al sacerdote que haga propiciación con él.'),
('nvi', 'Levítico 7:8', 'Levítico', 7, 8, 'La piel de la víctima del holocausto también será para el sacerdote que la ofrezca.'),
('nvi', 'Levítico 7:9', 'Levítico', 7, 9, 'Así mismo, toda ofrenda de cereal cocida al horno, a la olla o a la sartén, será del sacerdote que la ofrezca.'),
('nvi', 'Levítico 7:10', 'Levítico', 7, 10, 'Toda ofrenda de cereal, ya sea seca o amasada con aceite, pertenecerá a todos los hijos de Aarón, por partes iguales.'),
('nvi', 'Levítico 7:11', 'Levítico', 7, 11, '»Ésta es la ley respecto al sacrificio de comunión que se ofrece al SEÑOR:'),
('nvi', 'Levítico 7:12', 'Levítico', 7, 12, 'Si se ofrece en acción de gracias, entonces se ofrecerán también panes sin levadura amasados con aceite, obleas sin levadura untadas con aceite, o panes de flor de harina amasados con aceite.'),
('nvi', 'Levítico 7:13', 'Levítico', 7, 13, 'Junto con el sacrificio de comunión en acción de gracias, se deberá presentar una ofrenda de pan con levadura.'),
('nvi', 'Levítico 7:14', 'Levítico', 7, 14, 'De toda ofrenda deberá presentarse una parte como contribución al SEÑOR, y se destinará al sacerdote a quien le corresponda derramar la sangre del sacrificio de comunión.'),
('nvi', 'Levítico 7:15', 'Levítico', 7, 15, 'La carne de este sacrificio deberá comerse el día en que se ofrezca, sin dejar nada para el día siguiente.'),
('nvi', 'Levítico 7:16', 'Levítico', 7, 16, '»Si el sacrificio tiene que ver con un voto, o si se trata de una ofrenda voluntaria, no sólo se comerá en el día que se ofrezca el sacrificio, sino que podrá comerse el resto al día siguiente.'),
('nvi', 'Levítico 7:17', 'Levítico', 7, 17, 'Pero toda la carne que quede hasta el tercer día se quemará en el fuego.'),
('nvi', 'Levítico 7:18', 'Levítico', 7, 18, '»Si alguna carne del sacrificio de comunión llega a comerse al tercer día, tal sacrificio no será válido ni se tomará en cuenta, porque la carne ya está descompuesta. El que la coma sufrirá las consecuencias de su pecado.'),
('nvi', 'Levítico 7:19', 'Levítico', 7, 19, '»No deberá comerse la carne que haya tocado alguna cosa ritualmente impura, sino que se quemará en el fuego. En cuanto a otra carne, toda persona pura podrá comerla.'),
('nvi', 'Levítico 7:20', 'Levítico', 7, 20, '»Si una persona impura come la carne ofrecida al SEÑOR en el sacrificio de comunión, será eliminada de su pueblo.'),
('nvi', 'Levítico 7:21', 'Levítico', 7, 21, '»Si alguien toca cualquier clase de impureza humana, o de animal o de algo detestable, y luego come la carne ofrecida al SEÑOR en el sacrificio de comunión, será eliminado de su pueblo.»'),
('nvi', 'Levítico 7:22', 'Levítico', 7, 22, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 7:23', 'Levítico', 7, 23, 'que les dijera a los israelitas: Üstedes no comerán grasa de ganado vacuno, ovino o cabrío.'),
('nvi', 'Levítico 7:24', 'Levítico', 7, 24, 'La grasa de un animal muerto o destrozado podrá usarse con cualquier otro fin, menos para comerla.'),
('nvi', 'Levítico 7:25', 'Levítico', 7, 25, 'Todo el que coma grasa de animales presentados como ofrenda por fuego al SEÑOR, será eliminado de su pueblo.'),
('nvi', 'Levítico 7:26', 'Levítico', 7, 26, 'Vivan donde vivan, ustedes no comerán grasa ni sangre alguna, sea de ave o de otro animal.'),
('nvi', 'Levítico 7:27', 'Levítico', 7, 27, 'Todo el que coma cualquier clase de sangre, será eliminado de su pueblo.»'),
('nvi', 'Levítico 7:28', 'Levítico', 7, 28, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 7:29', 'Levítico', 7, 29, 'que les dijera a los israelitas: «El que ofrezca al SEÑOR un sacrificio de comunión deberá presentar al SEÑOR parte de ese sacrificio,'),
('nvi', 'Levítico 7:30', 'Levítico', 7, 30, 'y presentarle también una ofrenda por fuego. Llevará la grasa y el pecho, y mecerá ante el SEÑOR el pecho de la víctima como ofrenda mecida.'),
('nvi', 'Levítico 7:31', 'Levítico', 7, 31, 'El sacerdote quemará la grasa en el altar, pero el pecho será para Aarón y sus hijos.'),
('nvi', 'Levítico 7:32', 'Levítico', 7, 32, 'Al sacerdote se le dará, como contribución, el muslo derecho del sacrificio de comunión.'),
('nvi', 'Levítico 7:33', 'Levítico', 7, 33, 'El muslo derecho será la porción del sacerdote a quien le toque ofrecer la sangre y la grasa del sacrificio.'),
('nvi', 'Levítico 7:34', 'Levítico', 7, 34, 'Porque de los sacrificios de comunión que ofrecen los israelitas, yo he tomado el pecho mecido y el muslo para dárselos, como contribución, al sacerdote Aarón y a sus hijos. Éste será un estatuto perpetuo entre los israelitas.»'),
('nvi', 'Levítico 7:35', 'Levítico', 7, 35, 'De las ofrendas presentadas por fuego al SEÑOR, ésa es la porción consagrada para Aarón y sus hijos desde el día en que Moisés se los presentó al SEÑOR como sacerdotes.'),
('nvi', 'Levítico 7:36', 'Levítico', 7, 36, 'El día en que fueron ungidos, el SEÑOR ordenó a los israelitas darles esa porción. Es un estatuto perpetuo para sus descendientes.'),
('nvi', 'Levítico 7:37', 'Levítico', 7, 37, 'Ésta es la ley respecto a los holocaustos, las ofrendas de cereales, los sacrificios expiatorios, los sacrificios por la culpa, los sacrificios de ordenación y los sacrificios de comunión.'),
('nvi', 'Levítico 7:38', 'Levítico', 7, 38, 'El SEÑOR se la dio a Moisés en el monte Sinaí el día en que mandó a los israelitas presentarle ofrendas en el desierto de Sinaí.'),
('nvi', 'Levítico 8:1', 'Levítico', 8, 1, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 8:2', 'Levítico', 8, 2, '«Toma a Aarón y a sus hijos, junto con sus vestiduras, el aceite de la unción, el novillo para el sacrificio expiatorio, los dos carneros y el canastillo de los panes sin levadura,'),
('nvi', 'Levítico 8:3', 'Levítico', 8, 3, 'y congrega a toda la comunidad a la entrada de la Tienda de reunión.»'),
('nvi', 'Levítico 8:4', 'Levítico', 8, 4, 'Moisés llevó a cabo la orden del SEÑOR, y congregó a la comunidad a la entrada de la Tienda de reunión.'),
('nvi', 'Levítico 8:5', 'Levítico', 8, 5, 'Allí Moisés les dijo: «Esto es lo que el SEÑOR nos ha ordenado hacer.»'),
('nvi', 'Levítico 8:6', 'Levítico', 8, 6, 'Acto seguido, Moisés hizo que se acercaran Aarón y sus hijos, y los lavó con agua.'),
('nvi', 'Levítico 8:7', 'Levítico', 8, 7, 'A Aarón le puso la túnica y se la ciñó con la faja; luego lo cubrió con el manto, y encima le puso el efod, ciñéndoselo con la cinta del mismo.'),
('nvi', 'Levítico 8:8', 'Levítico', 8, 8, 'En seguida, le colocó el pectoral, y sobre éste puso el urimy eltumim.'),
('nvi', 'Levítico 8:9', 'Levítico', 8, 9, 'Por último, le colocó la tiara en la cabeza, y en la parte delantera puso la placa de oro, símbolo de su consagración, tal como el SEÑOR se lo había mandado.'),
('nvi', 'Levítico 8:10', 'Levítico', 8, 10, 'Después Moisés tomó el aceite de la unción, y ungió el santuario y todo lo que había en él, para consagrarlos.'),
('nvi', 'Levítico 8:11', 'Levítico', 8, 11, 'Siete veces roció el aceite sobre el altar, para ungirlo y consagrarlo junto con el lavamanos y su base, y todos sus utensilios.'),
('nvi', 'Levítico 8:12', 'Levítico', 8, 12, 'Luego, para consagrar a Aarón, lo ungió derramando sobre su cabeza el aceite de la unción.'),
('nvi', 'Levítico 8:13', 'Levítico', 8, 13, 'Acto seguido, Moisés hizo que los hijos de Aarón se acercaran, y los vistió con las túnicas; se las ciñó con la faja, y les sujetó las mitras, tal como el SEÑOR se lo había mandado.'),
('nvi', 'Levítico 8:14', 'Levítico', 8, 14, 'Luego hizo traer el novillo del sacrificio expiatorio, y Aarón y sus hijos pusieron las manos sobre la cabeza del novillo.'),
('nvi', 'Levítico 8:15', 'Levítico', 8, 15, 'Después Moisés lo degolló, y tomando un poco de sangre con el dedo, la untó en los cuernos alrededor del altar para purificarlo. El resto de la sangre la derramó al pie del altar, y así lo consagró e hizo propiciación por él.'),
('nvi', 'Levítico 8:16', 'Levítico', 8, 16, 'Luego Moisés tomó toda la grasa que recubre los intestinos, el lóbulo del hígado, los dos riñones y su grasa, y los quemó en el altar.'),
('nvi', 'Levítico 8:17', 'Levítico', 8, 17, 'Pero el resto del novillo, es decir, la piel, la carne y el excremento, lo quemó en el fuego, fuera del campamento, tal como el SEÑOR se lo había mandado.'),
('nvi', 'Levítico 8:18', 'Levítico', 8, 18, 'Moisés mandó traer el carnero del holocausto, y Aarón y sus hijos pusieron las manos sobre la cabeza del carnero.'),
('nvi', 'Levítico 8:19', 'Levítico', 8, 19, 'Moisés lo degolló, y derramó la sangre alrededor del altar.'),
('nvi', 'Levítico 8:20', 'Levítico', 8, 20, 'Cortó luego el carnero en trozos, y quemó la cabeza, los trozos y el sebo.'),
('nvi', 'Levítico 8:21', 'Levítico', 8, 21, 'Lavó con agua los intestinos y las patas, y luego quemó todo el carnero en el altar como holocausto de aroma grato, como ofrenda presentada por fuego al SEÑOR, tal como el SEÑOR se lo había mandado.'),
('nvi', 'Levítico 8:22', 'Levítico', 8, 22, 'Después Moisés mandó traer el otro carnero, el del sacrificio de ordenación, y Aarón y sus hijos pusieron las manos sobre la cabeza del carnero.'),
('nvi', 'Levítico 8:23', 'Levítico', 8, 23, 'Moisés lo degolló, y tomando un poco de la sangre, se la untó a Aarón en el lóbulo de la oreja derecha, en el pulgar de la mano derecha y en el dedo gordo del pie derecho.'),
('nvi', 'Levítico 8:24', 'Levítico', 8, 24, 'Además, hizo que los hijos de Aarón se acercaran, y les untó sangre en el lóbulo de la oreja derecha, en el pulgar de la mano derecha y en el dedo gordo del pie derecho. Luego derramó la sangre alrededor del altar.'),
('nvi', 'Levítico 8:25', 'Levítico', 8, 25, 'Tomó la grasa y la cola, y toda la grasa que recubre los intestinos, el lóbulo del hígado, los dos riñones y su grasa, y el muslo derecho,'),
('nvi', 'Levítico 8:26', 'Levítico', 8, 26, 'y tomando del canastillo que estaba colocado ante el SEÑOR un pan sin levadura, una oblea y una torta de pan amasada con aceite, lo puso todo sobre la grasa y el muslo derecho.'),
('nvi', 'Levítico 8:27', 'Levítico', 8, 27, 'Todo esto lo puso sobre las manos de Aarón y de sus hijos, y Aarón lo ofreció ante el SEÑOR como ofrenda mecida.'),
('nvi', 'Levítico 8:28', 'Levítico', 8, 28, 'Después se lo entregaron a Moisés, quien lo quemó en el altar, junto con el holocausto, como un sacrificio de ordenación de aroma grato, como una ofrenda presentada por fuego al SEÑOR.'),
('nvi', 'Levítico 8:29', 'Levítico', 8, 29, 'Luego, de la parte de la ofrenda que le pertenecía, Moisés tomó el pecho de la víctima y se lo presentó al SEÑOR como ofrenda mecida, tal como el SEÑOR se lo había mandado.'),
('nvi', 'Levítico 8:30', 'Levítico', 8, 30, 'Moisés tomó un poco del aceite de la unción y de la sangre del altar, y roció a Aarón y a sus hijos, junto con sus vestiduras. Así consagró Moisés a Aarón y a sus hijos, junto con sus vestiduras.'),
('nvi', 'Levítico 8:31', 'Levítico', 8, 31, 'Luego les dijo Moisés a Aarón y a sus hijos: «Cuezan la carne a la entrada de la Tienda de reunión, y cómanla allí junto con el pan del sacrificio de ordenación, tal como lo ordené cuando dije: “Aarón y sus hijos se lo comerán.”'),
('nvi', 'Levítico 8:32', 'Levítico', 8, 32, 'Quemen después en el fuego el resto de la carne y del pan.'),
('nvi', 'Levítico 8:33', 'Levítico', 8, 33, 'Quédense siete días a la entrada de la Tienda de reunión, hasta que se complete el rito de su ordenación, que dura siete días.'),
('nvi', 'Levítico 8:34', 'Levítico', 8, 34, 'El SEÑOR mandó que se hiciera propiciación por ustedes, tal como se ha hecho hoy.'),
('nvi', 'Levítico 8:35', 'Levítico', 8, 35, 'Así que siete días con sus noches se quedarán a la entrada de la Tienda de reunión, cumpliendo con lo que el SEÑOR ha prescrito, para que no mueran. Así me lo ha mandado el SEÑOR.»'),
('nvi', 'Levítico 8:36', 'Levítico', 8, 36, 'Y Aarón y sus hijos hicieron todo lo que el SEÑOR había mandado por medio de Moisés.'),
('nvi', 'Levítico 9:1', 'Levítico', 9, 1, 'Al octavo día Moisés llamó a Aarón y a sus hijos, y a los ancianos de Israel.'),
('nvi', 'Levítico 9:2', 'Levítico', 9, 2, 'A Aarón le dijo: «Toma un becerro para el sacrificio expiatorio y un carnero para el holocausto, ambos sin defecto, y preséntaselos al SEÑOR.'),
('nvi', 'Levítico 9:3', 'Levítico', 9, 3, 'Diles después a los israelitas: “Traigan un macho cabrío para el sacrificio expiatorio, y un becerro y un cordero para el holocausto, ambos de un año y sin defecto.'),
('nvi', 'Levítico 9:4', 'Levítico', 9, 4, 'Traigan también un toro y un carnero para ofrecérselos al SEÑOR como sacrificio de comunión; y traigan una ofrenda de cereal amasada con aceite. El SEÑOR se manifestará hoy ante ustedes.”»'),
('nvi', 'Levítico 9:5', 'Levítico', 9, 5, 'Los israelitas llevaron hasta la Tienda de reunión lo que Moisés había mandado; y toda la comunidad se acercó y se quedó de pie ante el SEÑOR.'),
('nvi', 'Levítico 9:6', 'Levítico', 9, 6, 'Y Moisés les dijo: «Esto es lo que el Señor les manda hacer, para que la gloria del SEÑOR se manifieste ante ustedes.»'),
('nvi', 'Levítico 9:7', 'Levítico', 9, 7, 'Después Moisés le dijo a Aarón: «Acércate al altar, y ofrece tu sacrificio expiatorio y tu holocausto. Haz propiciación por ti y por el pueblo. Presenta la ofrenda por el pueblo y haz propiciación por ellos, tal como el SEÑOR lo ha mandado.»'),
('nvi', 'Levítico 9:8', 'Levítico', 9, 8, 'Aarón se acercó al altar y degolló el becerro como sacrificio expiatorio por sí mismo.'),
('nvi', 'Levítico 9:9', 'Levítico', 9, 9, 'Sus hijos le llevaron la sangre, y él mojó el dedo en la sangre y la untó en los cuernos del altar, derramando luego la sangre al pie del altar.'),
('nvi', 'Levítico 9:10', 'Levítico', 9, 10, 'Luego quemó en el altar la grasa, los riñones y el lóbulo del hígado del animal sacrificado, tal como el SEÑOR se lo había mandado a Moisés.'),
('nvi', 'Levítico 9:11', 'Levítico', 9, 11, 'La carne y la piel las quemó fuera del campamento.'),
('nvi', 'Levítico 9:12', 'Levítico', 9, 12, 'Después Aarón degolló la víctima del holocausto. Sus hijos le llevaron la sangre, y él la derramó alrededor del altar.'),
('nvi', 'Levítico 9:13', 'Levítico', 9, 13, 'También le fueron pasando los trozos del animal y la cabeza, y él lo quemó todo en el altar.'),
('nvi', 'Levítico 9:14', 'Levítico', 9, 14, 'Lavó los intestinos y las patas, y luego quemó todo esto en el altar, junto con el holocausto.'),
('nvi', 'Levítico 9:15', 'Levítico', 9, 15, 'Entonces Aarón presentó la ofrenda del pueblo, es decir, el macho cabrío del sacrificio expiatorio. Lo tomó y lo degolló, ofreciéndolo como sacrificio expiatorio, como hizo con el primero.'),
('nvi', 'Levítico 9:16', 'Levítico', 9, 16, 'Luego presentó la víctima del holocausto, la cual sacrificó en la forma prescrita.'),
('nvi', 'Levítico 9:17', 'Levítico', 9, 17, 'También presentó la ofrenda de cereal, y tomando un puñado lo quemó en el altar, además del holocausto de la mañana.'),
('nvi', 'Levítico 9:18', 'Levítico', 9, 18, 'Después degolló el toro y el carnero como sacrificio de comunión por el pueblo. Sus hijos le llevaron la sangre, y él la derramó alrededor del altar.'),
('nvi', 'Levítico 9:19', 'Levítico', 9, 19, 'Pero tomó la grasa del toro y del carnero, es decir, la cola, el sebo que recubre los intestinos, los riñones y el lóbulo del hígado,'),
('nvi', 'Levítico 9:20', 'Levítico', 9, 20, 'y lo puso todo sobre el pecho de las víctimas para quemarlo en el altar.'),
('nvi', 'Levítico 9:21', 'Levítico', 9, 21, 'Aarón meció ante el SEÑOR el pecho y el muslo derecho de las víctimas. Fue una ofrenda mecida, tal como Moisés se lo había mandado.'),
('nvi', 'Levítico 9:22', 'Levítico', 9, 22, 'Aarón levantó las manos hacia el pueblo, y los bendijo. Una vez que terminó de ofrecer el sacrificio expiatorio, el holocausto y el sacrificio de comunión, se retiró del altar.'),
('nvi', 'Levítico 9:23', 'Levítico', 9, 23, 'Moisés y Aarón entraron en la Tienda de reunión. Al salir, bendijeron al pueblo, y la gloria del SEÑOR se manifestó a todo el pueblo.'),
('nvi', 'Levítico 9:24', 'Levítico', 9, 24, 'De la presencia del SEÑOR salió un fuego, que consumió el holocausto y la grasa que estaban sobre el altar. Al ver esto, todo el pueblo prorrumpió en gritos de júbilo y cayó rostro en tierra.'),
('nvi', 'Levítico 10:1', 'Levítico', 10, 1, 'Pero Nadab y Abiú, hijos de Aarón, tomaron cada uno su incensario y, poniendo en ellos fuego e incienso, ofrecieron ante el SEÑOR un fuego que no tenían por qué ofrecer, pues él no se lo había mandado.'),
('nvi', 'Levítico 10:2', 'Levítico', 10, 2, 'Entonces salió de la presencia del SEÑOR un fuego que los consumió, y murieron ante él.'),
('nvi', 'Levítico 10:3', 'Levítico', 10, 3, 'Moisés le dijo a Aarón: «De esto hablaba el SEÑOR cuando dijo: »“Entre los que se acercan a mí manifestaré mi santidad, y ante todo el pueblo manifestaré mi gloria.”» Y Aarón guardó silencio.'),
('nvi', 'Levítico 10:4', 'Levítico', 10, 4, 'Moisés mandó llamar a Misael y a Elzafán, hijos de Uziel, tío de Aarón, y les dijo: «Vengan acá y retiren del santuario a sus hermanos. ¡Sáquenlos del campamento!»'),
('nvi', 'Levítico 10:5', 'Levítico', 10, 5, 'Ellos se acercaron y, tomándolos por las túnicas, se los llevaron fuera del campamento, tal como Moisés lo había ordenado.'),
('nvi', 'Levítico 10:6', 'Levítico', 10, 6, 'Luego Moisés les dijo a Aarón y a sus hijos Eleazar e Itamar: «No anden ustedes con el pelo despeinado, ni se rasguen los vestidos. Así no morirán ustedes ni se irritará el SEÑOR contra toda la comunidad. Sus hermanos israelitas harán duelo por el incendio que produjo el SEÑOR,'),
('nvi', 'Levítico 10:7', 'Levítico', 10, 7, 'pero ustedes no vayan a salir de la Tienda de reunión, no sea que mueran, porque el aceite de la unción del SEÑOR está sobre ustedes.» Y ellos hicieron lo que Moisés les dijo.'),
('nvi', 'Levítico 10:8', 'Levítico', 10, 8, 'El SEÑOR le dijo a Aarón:'),
('nvi', 'Levítico 10:9', 'Levítico', 10, 9, '«Ni tú ni tus hijos deben beber vino ni licor cuando entren en la Tienda de reunión, pues de lo contrario morirán. Éste es un estatuto perpetuo para tus descendientes,'),
('nvi', 'Levítico 10:10', 'Levítico', 10, 10, 'para que puedan distinguir entre lo santo y lo profano, y entre lo puro y lo impuro,'),
('nvi', 'Levítico 10:11', 'Levítico', 10, 11, 'y puedan también enseñar a los israelitas todos los estatutos que el SEÑOR les ha dado a conocer por medio de Moisés.»'),
('nvi', 'Levítico 10:12', 'Levítico', 10, 12, 'Moisés le dijo a Aarón, y también a Eleazar e Itamar, los hijos que le quedaban a Aarón: «Tomen el resto de la ofrenda de cereal presentada al SEÑOR, y cómanla sin levadura, junto al altar, porque es sumamente sagrada.'),
('nvi', 'Levítico 10:13', 'Levítico', 10, 13, 'Cómanla en un lugar santo, porque así se me ha mandado. Es un estatuto para ti y para tus hijos con respecto a la ofrenda presentada por fuego al SEÑOR.'),
('nvi', 'Levítico 10:14', 'Levítico', 10, 14, '»Tú y tus hijos e hijas podrán comer también, en un lugar puro, el pecho que es ofrenda mecida y el muslo dado como contribución. Ambos son parte de los sacrificios de comunión de los israelitas, y a ti y a tus hijos se les han dado como estatuto.'),
('nvi', 'Levítico 10:15', 'Levítico', 10, 15, 'Tanto el muslo como el pecho serán presentados junto con la ofrenda de la grasa, para ofrecérselos al SEÑOR como ofrenda mecida. Será un estatuto perpetuo para ti y para tus hijos, tal como lo ha mandado el SEÑOR.»'),
('nvi', 'Levítico 10:16', 'Levítico', 10, 16, 'Moisés pidió con insistencia el macho cabrío del sacrificio expiatorio, pero éste ya había sido quemado en el fuego. Irritado con Eleazar e Itamar, los hijos sobrevivientes de Aarón, les preguntó:'),
('nvi', 'Levítico 10:17', 'Levítico', 10, 17, '—¿Por qué no comieron el sacrificio expiatorio dentro del santuario? Es un sacrificio sumamente sagrado; se les dio para quitar la culpa de la comunidad y hacer propiciación por ellos ante el SEÑOR.'),
('nvi', 'Levítico 10:18', 'Levítico', 10, 18, 'Si no se introdujo en el Lugar Santo la sangre del macho cabrío, ustedes debieron haberse comido el animal en el área del santuario, tal como se lo mandé.'),
('nvi', 'Levítico 10:19', 'Levítico', 10, 19, 'Entonces Aarón le respondió a Moisés: —Hoy mis hijos ofrecieron ante el SEÑOR su sacrificio expiatorio y su holocausto, ¡y es cuando tenía que sucederme semejante desgracia! Si hoy hubiera yo comido del sacrificio expiatorio, ¿le habría parecido correcto al SEÑOR?'),
('nvi', 'Levítico 10:20', 'Levítico', 10, 20, 'Al oír esto, Moisés quedó satisfecho con la respuesta.'),
('nvi', 'Levítico 11:1', 'Levítico', 11, 1, 'sobre animales puros e impuros *11:1-23—Dt 14:3-20) El SEÑOR les ordenó a Moisés y a Aarón'),
('nvi', 'Levítico 11:2', 'Levítico', 11, 2, 'que les dijeran a los israelitas: «De todas las bestias que hay en tierra firme, éstos son los animales que ustedes podrán comer:'),
('nvi', 'Levítico 11:3', 'Levítico', 11, 3, 'los rumiantes que tienen la pezuña partida en dos.'),
('nvi', 'Levítico 11:4', 'Levítico', 11, 4, 'Hay, sin embargo, rumiantes que no tienen la pezuña partida. De esos animales no podrán comer los siguientes: »El camello, porque es rumiante pero no tiene la pezuña partida; este animal será impuro para ustedes.'),
('nvi', 'Levítico 11:5', 'Levítico', 11, 5, '»El conejo, porque es rumiante pero no tiene la pezuña partida; este animal será impuro para ustedes.'),
('nvi', 'Levítico 11:6', 'Levítico', 11, 6, '»La liebre, porque es rumiante pero no tiene la pezuña partida; este animal será impuro para ustedes.'),
('nvi', 'Levítico 11:7', 'Levítico', 11, 7, '»El cerdo, porque tiene la pezuña partida en dos pero no es rumiante; este animal será impuro para ustedes.'),
('nvi', 'Levítico 11:8', 'Levítico', 11, 8, '»No comerán la carne ni tocarán el cadáver de estos animales. Ustedes los considerarán animales impuros.'),
('nvi', 'Levítico 11:9', 'Levítico', 11, 9, '»De los animales que hay en las aguas, es decir, en los mares y en los ríos, ustedes podrán comer los que tengan aletas y escamas.'),
('nvi', 'Levítico 11:10', 'Levítico', 11, 10, 'En cambio, considerarán inmundos a todos los animales de los mares y de los ríos que no tengan aletas ni escamas, sean reptiles u otros animales acuáticos.'),
('nvi', 'Levítico 11:11', 'Levítico', 11, 11, 'No comerán su carne, y rechazarán su cadáver, porque ustedes los considerarán animales inmundos.'),
('nvi', 'Levítico 11:12', 'Levítico', 11, 12, 'Todo animal acuático que no tenga aletas ni escamas será para ustedes un animal inmundo.'),
('nvi', 'Levítico 11:13', 'Levítico', 11, 13, '»Las siguientes aves ustedes las rechazarán y no las comerán, porque las considerarán animales inmundos: el águila, el quebrantahuesos, el águila marina,'),
('nvi', 'Levítico 11:14', 'Levítico', 11, 14, 'toda clase de milanos y gavilanes,'),
('nvi', 'Levítico 11:15', 'Levítico', 11, 15, 'toda clase de cuervos,'),
('nvi', 'Levítico 11:16', 'Levítico', 11, 16, 'el avestruz, la lechuza, toda clase de gaviotas,'),
('nvi', 'Levítico 11:17', 'Levítico', 11, 17, 'el búho, el avetoro, el cisne,'),
('nvi', 'Levítico 11:18', 'Levítico', 11, 18, 'la lechuza nocturna, el pelícano, el buitre,'),
('nvi', 'Levítico 11:19', 'Levítico', 11, 19, 'la cigüeña, toda clase de garzas, la abubilla y el murciélago.'),
('nvi', 'Levítico 11:20', 'Levítico', 11, 20, '»A todo insecto alado que camina en cuatro patas lo considerarán ustedes un animal inmundo.'),
('nvi', 'Levítico 11:21', 'Levítico', 11, 21, 'Hay, sin embargo, algunos insectos alados que caminan en cuatro patas y que ustedes podrán comer: los que además de sus patas tienen zancas para saltar,'),
('nvi', 'Levítico 11:22', 'Levítico', 11, 22, 'y también toda clase de langostas, grillos y saltamontes.'),
('nvi', 'Levítico 11:23', 'Levítico', 11, 23, 'Pero a los demás insectos alados que caminan en cuatro patas ustedes los considerarán animales inmundos.'),
('nvi', 'Levítico 11:24', 'Levítico', 11, 24, 'Üstedes quedarán impuros por lo siguiente: »Todo el que toque el cadáver de esos animales quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 11:25', 'Levítico', 11, 25, '»Todo el que recoja alguno de esos cadáveres deberá lavarse la ropa, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 11:26', 'Levítico', 11, 26, '»Considerarán impuro a todo animal que no tenga la pezuña partida ni sea rumiante. Cualquiera que lo toque quedará impuro.'),
('nvi', 'Levítico 11:27', 'Levítico', 11, 27, '»De los animales de cuatro patas, tendrán por impuro a todo el que se apoya sobre sus plantas. Cualquiera que toque su cadáver quedará impuro hasta el anochecer,'),
('nvi', 'Levítico 11:28', 'Levítico', 11, 28, 'y todo el que lo recoja deberá lavarse la ropa, y quedará impuro hasta el anochecer. A estos animales ustedes los considerarán impuros.'),
('nvi', 'Levítico 11:29', 'Levítico', 11, 29, '»Entre los animales que se arrastran, ustedes considerarán impuros a la comadreja, al ratón, a toda clase de lagartos,'),
('nvi', 'Levítico 11:30', 'Levítico', 11, 30, 'a la salamanquesa, a la iguana, al camaleón y a la salamandra.'),
('nvi', 'Levítico 11:31', 'Levítico', 11, 31, 'Éstos son los animales que ustedes considerarán impuros entre los que se arrastran. Todo el que toque el cadáver de esos animales quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 11:32', 'Levítico', 11, 32, '»Cuando el cadáver de algún animal impuro toque algún objeto de madera, o ropa, o piel, o un saco o cualquier utensilio de uso cotidiano, tal objeto quedará impuro. Deberá lavarse con agua, y quedará impuro hasta el anochecer. Entonces volverá a ser puro.'),
('nvi', 'Levítico 11:33', 'Levítico', 11, 33, '»Si el cadáver de alguno de estos animales cae dentro de una vasija de barro, todo lo que la vasija contenga quedará impuro, y habrá que romperla.'),
('nvi', 'Levítico 11:34', 'Levítico', 11, 34, 'Todo alimento sobre el que caiga agua de dicha vasija quedará impuro; lo mismo sucederá con todo líquido que haya en esa vasija.'),
('nvi', 'Levítico 11:35', 'Levítico', 11, 35, 'Cualquier cosa sobre la que caiga parte de estos cadáveres quedará impura, y habrá que destruir los hornos y los fogones con los que haya entrado en contacto. Los cadáveres son impuros, y así deberán considerarlos.'),
('nvi', 'Levítico 11:36', 'Levítico', 11, 36, 'Sólo las fuentes o las cisternas que recogen agua permanecerán puras; cualquier otra cosa que toque un cadáver quedará impura.'),
('nvi', 'Levítico 11:37', 'Levítico', 11, 37, '»Si alguno de esos cadáveres cae sobre la semilla destinada a la siembra, la semilla permanecerá pura.'),
('nvi', 'Levítico 11:38', 'Levítico', 11, 38, 'Pero si la semilla se remoja en agua, y alguno de esos cadáveres cae sobre ella, deberán considerarla impura.'),
('nvi', 'Levítico 11:39', 'Levítico', 11, 39, '»Si muere algún animal de los que está permitido comer, quien toque su cadáver quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 11:40', 'Levítico', 11, 40, 'Quien coma carne de ese cadáver se lavará la ropa y quedará impuro hasta el anochecer. Quien lo recoja se lavará la ropa y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 11:41', 'Levítico', 11, 41, '»No comerán ustedes ninguno de los animales que se arrastran, porque son inmundos.'),
('nvi', 'Levítico 11:42', 'Levítico', 11, 42, 'No comerán ningún animal que se arrastre sobre su vientre, o que se apoye sobre sus plantas, o que tenga más de cuatro patas. En resumen, no comerán ustedes ningún animal que se arrastra, porque es inmundo;'),
('nvi', 'Levítico 11:43', 'Levítico', 11, 43, 'es decir, no se contaminen por causa de su inmundicia, pues son animales inmundos.'),
('nvi', 'Levítico 11:44', 'Levítico', 11, 44, 'Yo soy el SEÑOR su Dios, así que santifíquense y manténganse santos, porque yo soy santo. No se hagan impuros por causa de los animales que se arrastran.'),
('nvi', 'Levítico 11:45', 'Levítico', 11, 45, 'Yo soy el SEÑOR, que los sacó de la tierra de Egipto, para ser su Dios. Sean, pues, santos, porque yo soy santo.'),
('nvi', 'Levítico 11:46', 'Levítico', 11, 46, '»Ésta es la ley acerca de los animales y de las aves, y de todo ser que se mueve dentro de las aguas o que se arrastra por el suelo,'),
('nvi', 'Levítico 11:47', 'Levítico', 11, 47, 'para que así puedan distinguir entre lo puro y lo impuro, y entre lo que se puede comer y lo que no se debe comer.»'),
('nvi', 'Levítico 12:1', 'Levítico', 12, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 12:2', 'Levítico', 12, 2, 'que les dijera a los israelitas: «Cuando una mujer conciba y dé a luz un niño, quedará impura durante siete días, como lo es en el tiempo de su menstruación.'),
('nvi', 'Levítico 12:3', 'Levítico', 12, 3, 'Al octavo día, el niño será circuncidado.'),
('nvi', 'Levítico 12:4', 'Levítico', 12, 4, 'La madre deberá permanecer treinta y tres días más purificándose de su flujo de sangre. No tocará ninguna cosa santa, ni irá al santuario, hasta que termine su período de purificación.'),
('nvi', 'Levítico 12:5', 'Levítico', 12, 5, '»Si da a luz una niña, la madre quedará impura durante dos semanas, como lo es en el tiempo de su menstruación, y permanecerá sesenta y seis días más purificándose de su flujo de sangre.'),
('nvi', 'Levítico 12:6', 'Levítico', 12, 6, '»Una vez cumplido su período de purificación, sea que haya tenido un niño o una niña, tomará un cordero de un año como holocausto, y un pichón de paloma o una tórtola como sacrificio expiatorio, y los llevará al sacerdote, a la entrada de la Tienda de reunión,'),
('nvi', 'Levítico 12:7', 'Levítico', 12, 7, 'quien los ofrecerá ante el SEÑOR. Así el sacerdote hará propiciación por la mujer, y la purificará de su flujo de sangre. »Ésta es la ley concerniente a la mujer que dé a luz un niño o una niña.'),
('nvi', 'Levítico 12:8', 'Levítico', 12, 8, 'Pero si no le alcanza para comprar un cordero, tomará dos tórtolas o dos pichones de paloma, uno como holocausto y el otro como sacrificio expiatorio. Así el sacerdote hará propiciación por la mujer, y ella quedará purificada.»'),
('nvi', 'Levítico 13:1', 'Levítico', 13, 1, 'El SEÑOR les dijo a Moisés y a Aarón:'),
('nvi', 'Levítico 13:2', 'Levítico', 13, 2, '«Cuando a una persona le salga en la piel alguna inflamación, erupción o mancha blancuzca que pueda convertirse en infección, se le llevará al sacerdote Aarón, o a alguno de sus descendientes los sacerdotes.'),
('nvi', 'Levítico 13:3', 'Levítico', 13, 3, 'El sacerdote examinará la llaga. Si el vello en la parte afectada se ha puesto blanco y la llaga se ve más hundida que la piel, entonces se trata de una enfermedad infecciosa. Después de examinar a la persona, el sacerdote la declarará impura.'),
('nvi', 'Levítico 13:4', 'Levítico', 13, 4, '»Si la mancha blancuzca no se ve más hundida que la piel, ni el vello se le ha puesto blanco, el sacerdote aislará a la persona enferma durante siete días,'),
('nvi', 'Levítico 13:5', 'Levítico', 13, 5, 'y al séptimo día la examinará de nuevo. Si juzga que la infección no ha seguido extendiéndose sobre la piel, aislará a esa persona otros siete días.'),
('nvi', 'Levítico 13:6', 'Levítico', 13, 6, 'Cumplidos los siete días, el sacerdote la examinará otra vez, y si el mal no se ha extendido sobre la piel sino que ha disminuido, la declarará pura. No era más que una erupción, así que la persona enferma se lavará la ropa y quedará pura.'),
('nvi', 'Levítico 13:7', 'Levítico', 13, 7, '»Si la erupción se le sigue extendiendo sobre la piel luego de haberse presentado ante el sacerdote para su purificación, la persona enferma tendrá que volver a presentarse ante él.'),
('nvi', 'Levítico 13:8', 'Levítico', 13, 8, 'El sacerdote la examinará, y si la erupción se ha extendido sobre la piel, declarará impura a esa persona, pues se trata de una enfermedad infecciosa.'),
('nvi', 'Levítico 13:9', 'Levítico', 13, 9, '»Cuando una persona tenga una infección en la piel, deberá ser llevada ante el sacerdote,'),
('nvi', 'Levítico 13:10', 'Levítico', 13, 10, 'quien la examinará. Si ocurre que la inflamación y el vello se han puesto blancos, y se ve la carne viva,'),
('nvi', 'Levítico 13:11', 'Levítico', 13, 11, 'se trata de una infección crónica. El sacerdote declarará impura a tal persona. Pero no hará falta aislarla otra vez, porque ya se sabe que es impura.'),
('nvi', 'Levítico 13:12', 'Levítico', 13, 12, '»Si la infección se ha extendido sobre la piel de tal manera que, hasta donde el sacerdote pueda ver, cubre toda la piel de la persona enferma,'),
('nvi', 'Levítico 13:13', 'Levítico', 13, 13, 'entonces el sacerdote la examinará. Si ve que la infección le cubre todo el cuerpo, la declarará pura. Esa persona es pura porque todo el cuerpo se le ha puesto blanco.'),
('nvi', 'Levítico 13:14', 'Levítico', 13, 14, 'Pero será impura en el momento en que le aparezca una llaga ulcerosa.'),
('nvi', 'Levítico 13:15', 'Levítico', 13, 15, 'Cuando el sacerdote examine la carne viva, declarará impura a esa persona. La carne viva es impura, pues se trata de una enfermedad infecciosa.'),
('nvi', 'Levítico 13:16', 'Levítico', 13, 16, 'Pero si la llaga ulcerosa se le pone blanca, la persona enferma deberá ir al sacerdote'),
('nvi', 'Levítico 13:17', 'Levítico', 13, 17, 'para que la examine. Si la llaga se le ha puesto blanca, el sacerdote declarará pura a esa persona, y en efecto lo será.'),
('nvi', 'Levítico 13:18', 'Levítico', 13, 18, '»Si alguien ha tenido un absceso en la piel, y luego sana'),
('nvi', 'Levítico 13:19', 'Levítico', 13, 19, 'pero en el sitio del absceso le aparece una inflamación blancuzca, o una mancha rojiza, deberá presentarse ante el sacerdote'),
('nvi', 'Levítico 13:20', 'Levítico', 13, 20, 'para que lo examine. Si la inflamación se ve más hundida que la piel y el vello se le ha puesto blanco, el sacerdote lo declarará impuro. Se trata de una enfermedad infecciosa que ha brotado en el sitio donde estaba el absceso.'),
('nvi', 'Levítico 13:21', 'Levítico', 13, 21, 'Pero si, al examinar al enfermo, encuentra el sacerdote que el vello no se le ha puesto blanco, y que el absceso no se ve más hundido que la piel sino que ha disminuido, entonces aislará al enfermo durante siete días.'),
('nvi', 'Levítico 13:22', 'Levítico', 13, 22, 'Si el absceso se extiende sobre la piel, declarará impuro al enfermo, pues se trata de una enfermedad.'),
('nvi', 'Levítico 13:23', 'Levítico', 13, 23, 'Si el absceso no se desarrolla ni la mancha blanca se extiende sino que ha cicatrizado, declarará puro al enfermo.'),
('nvi', 'Levítico 13:24', 'Levítico', 13, 24, '»Si alguien se quema, y sobre la quemadura le aparece una mancha blancuzca o rojiza,'),
('nvi', 'Levítico 13:25', 'Levítico', 13, 25, 'el sacerdote deberá examinarla. Si el vello de la mancha se le ha puesto blanco, y la mancha misma se ve más hundida que la piel, se trata de una enfermedad infecciosa que brotó en el sitio de la quemadura. El sacerdote declarará impuro al enfermo, pues se trata de una infección.'),
('nvi', 'Levítico 13:26', 'Levítico', 13, 26, '»Si al examinar la quemadura encuentra el sacerdote que el vello no se ha puesto blanco ni la mancha se ve más hundida que la piel, sino que ha disminuido, entonces aislará al enfermo durante siete días.'),
('nvi', 'Levítico 13:27', 'Levítico', 13, 27, 'Al séptimo día el sacerdote volverá a examinarlo, y si observa que la mancha se ha extendido sobre la piel, lo declarará impuro, pues se trata de una infección.'),
('nvi', 'Levítico 13:28', 'Levítico', 13, 28, 'En cambio, si la mancha blancuzca no ha seguido extendiéndose sobre la piel, se trata sólo de la inflamación de la quemadura. Entonces el sacerdote lo declarará puro, ya que se trata sólo de una quemadura cicatrizada.'),
('nvi', 'Levítico 13:29', 'Levítico', 13, 29, '»Si a un hombre o a una mujer les sale una llaga en la cabeza o en el mentón,'),
('nvi', 'Levítico 13:30', 'Levítico', 13, 30, 'el sacerdote deberá examinar la llaga. Si ésta se ve más hundida que la piel, y el pelo se ve amarillento y delgado, declarará impuro al enfermo. Se trata de tiña, que es una infección en la cabeza o en el mentón.'),
('nvi', 'Levítico 13:31', 'Levítico', 13, 31, 'Pero si al examinar la llaga tiñosa el sacerdote ve que no está más hundida que la piel ni tiene pelo negro, aislará al enfermo de tiña durante siete días.'),
('nvi', 'Levítico 13:32', 'Levítico', 13, 32, 'Al séptimo día el sacerdote deberá examinar otra vez al enfermo; si la tiña no se ha extendido, ni tiene pelo amarillento ni se ve más hundida que la piel,'),
('nvi', 'Levítico 13:33', 'Levítico', 13, 33, 'entonces el enfermo se afeitará el pelo, pero no la parte afectada, y el sacerdote lo aislará otros siete días.'),
('nvi', 'Levítico 13:34', 'Levítico', 13, 34, 'Al séptimo día el sacerdote volverá a examinar al enfermo; si la tiña no se ha extendido por la piel ni se ve más hundida que ésta, lo declarará puro. Entonces el enfermo se lavará la ropa y quedará puro.'),
('nvi', 'Levítico 13:35', 'Levítico', 13, 35, '»Si después de su purificación la tiña se extiende por toda la piel,'),
('nvi', 'Levítico 13:36', 'Levítico', 13, 36, 'el sacerdote deberá examinarlo. Si la tiña se ha extendido por toda la piel, ya no hará falta que el sacerdote busque pelo amarillento, porque el enfermo es impuro.'),
('nvi', 'Levítico 13:37', 'Levítico', 13, 37, 'En cambio, si considera que la tiña no se ha desarrollado y nota que le ha crecido pelo negro, entonces el enfermo ha sanado. Es puro, y así deberá declararlo el sacerdote.'),
('nvi', 'Levítico 13:38', 'Levítico', 13, 38, '»Si a un hombre o a una mujer les salen manchas blancuzcas en la piel,'),
('nvi', 'Levítico 13:39', 'Levítico', 13, 39, 'el sacerdote deberá examinarlas. Si las manchas resultan ser blancuzcas, se trata sólo de una erupción cutánea, de modo que la persona es pura.'),
('nvi', 'Levítico 13:40', 'Levítico', 13, 40, '»Si a alguien se le cae el pelo de la nuca, y se queda calvo, es puro.'),
('nvi', 'Levítico 13:41', 'Levítico', 13, 41, 'Si se le cae el pelo de las sienes y se queda calvo, también es puro.'),
('nvi', 'Levítico 13:42', 'Levítico', 13, 42, 'Pero si en su calvicie de la nuca o de las sienes le aparece una llaga rojiza, se trata de una infección que le ha brotado en la parte calva.'),
('nvi', 'Levítico 13:43', 'Levítico', 13, 43, 'El sacerdote deberá examinarlo. Si la inflamación es rojiza, parecida a las infecciones de la piel,'),
('nvi', 'Levítico 13:44', 'Levítico', 13, 44, 'se trata entonces de una persona infectada e impura. El sacerdote la declarará impura por esa llaga en la cabeza.'),
('nvi', 'Levítico 13:45', 'Levítico', 13, 45, '»La persona que contraiga una infección se vestirá de harapos y no se peinará; con el rostro semicubierto irá gritando: “¡Impuro! ¡Impuro!”,'),
('nvi', 'Levítico 13:46', 'Levítico', 13, 46, 'y será impuro todo el tiempo que le dure la enfermedad. Es impuro, así que deberá vivir aislado y fuera del campamento.'),
('nvi', 'Levítico 13:47', 'Levítico', 13, 47, '»Cuando la ropa de lana o de lino se llene de moho,'),
('nvi', 'Levítico 13:48', 'Levítico', 13, 48, 'o éste aparezca en la urdimbre o trama del lino o de la lana, o en algún cuero o artículo de piel,'),
('nvi', 'Levítico 13:49', 'Levítico', 13, 49, 'y su color sea verdusco o rojizo, se trata de una infección de moho, y deberá mostrársele al sacerdote,'),
('nvi', 'Levítico 13:50', 'Levítico', 13, 50, 'quien examinará la mancha y aislará durante siete días el objeto infectado.'),
('nvi', 'Levítico 13:51', 'Levítico', 13, 51, 'Al séptimo día el sacerdote examinará la mancha. Si ésta se ha extendido en la ropa o en la urdimbre, o en la trama, o en el cuero o en cualquier artículo de piel, se trata de un moho corrosivo. Tal objeto es impuro.'),
('nvi', 'Levítico 13:52', 'Levítico', 13, 52, 'Se le prenderá fuego a la ropa o a la urdimbre, trama, lana, lino o cualquier artículo de piel que haya sido infectado, porque se trata de un moho corrosivo. El objeto deberá ser quemado.'),
('nvi', 'Levítico 13:53', 'Levítico', 13, 53, '»Si al examinar el objeto, el sacerdote observa que la mancha no se ha extendido sobre el vestido, ni sobre la urdimbre, trama, lana, lino, o cualquier artículo de cuero,'),
('nvi', 'Levítico 13:54', 'Levítico', 13, 54, 'entonces mandará lavar el objeto infectado y lo aislará otros siete días.'),
('nvi', 'Levítico 13:55', 'Levítico', 13, 55, 'Una vez lavado el objeto, el sacerdote procederá a examinarlo. Si observa que la mancha no ha cambiado de aspecto, dicho objeto será considerado impuro aun cuando la mancha no se haya extendido. El objeto será quemado por estar corroído, sea por dentro o por fuera.'),
('nvi', 'Levítico 13:56', 'Levítico', 13, 56, '»Si después de lavado el objeto, el sacerdote lo examina y observa que la mancha ha disminuido, deberá arrancar la parte manchada del vestido, del cuero, de la urdimbre o de la trama.'),
('nvi', 'Levítico 13:57', 'Levítico', 13, 57, 'Si la mancha reaparece en la ropa, en la urdimbre, en la trama o en cualquier artículo de piel, significa que ha vuelto a brotar. La parte infectada será quemada,'),
('nvi', 'Levítico 13:58', 'Levítico', 13, 58, 'pero toda ropa, urdimbre, trama o artículo de piel que al lavarse pierda la mancha, se volverá a lavar, y el objeto quedará puro.»'),
('nvi', 'Levítico 13:59', 'Levítico', 13, 59, 'Ésta es la ley respecto al moho que infecta la ropa, la lana, el lino, la urdimbre, la trama o cualquier artículo de piel, para poder declararlos puros o impuros.'),
('nvi', 'Levítico 14:1', 'Levítico', 14, 1, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 14:2', 'Levítico', 14, 2, '«Ésta es la ley que se aplicará para declarar pura a una persona infectada. Será presentada ante el sacerdote,'),
('nvi', 'Levítico 14:3', 'Levítico', 14, 3, 'quien la examinará fuera del campamento. Si el sacerdote comprueba que la persona infectada se ha sanado de su enfermedad,'),
('nvi', 'Levítico 14:4', 'Levítico', 14, 4, 'mandará traer para la purificación de esa persona dos aves vivas y puras, un pedazo de madera de cedro, un paño escarlata y una rama de hisopo.'),
('nvi', 'Levítico 14:5', 'Levítico', 14, 5, 'Después el sacerdote mandará degollar la primera ave sobre una vasija de barro llena de agua de manantial.'),
('nvi', 'Levítico 14:6', 'Levítico', 14, 6, 'Tomará la otra ave viva, la madera de cedro, el paño escarlata y la rama de hisopo, y mojará todo esto junto con el ave viva en la sangre del ave que fue degollada sobre el agua de manantial.'),
('nvi', 'Levítico 14:7', 'Levítico', 14, 7, 'Luego rociará siete veces a quien va a ser purificado de la infección, y lo declarará puro. Entonces dejará libre a campo abierto el ave viva.'),
('nvi', 'Levítico 14:8', 'Levítico', 14, 8, '»El que se purifica deberá lavarse la ropa, afeitarse todo el pelo y bañarse. Así quedará puro. Después de esto podrá entrar en el campamento, pero se quedará fuera de su carpa durante siete días.'),
('nvi', 'Levítico 14:9', 'Levítico', 14, 9, 'Al séptimo día se rapará por completo el cabello, la barba y las cejas; se lavará la ropa y se bañará. Así quedará puro.'),
('nvi', 'Levítico 14:10', 'Levítico', 14, 10, '»Al octavo día, el que se purifica deberá traer dos corderos sin defecto y una cordera de un año, también sin defecto; como ofrenda de cereal traerá seis kilos de flor de harina amasada con aceite, junto con un tercio de litro de aceite.'),
('nvi', 'Levítico 14:11', 'Levítico', 14, 11, 'El sacerdote que oficia en la purificación presentará ante el SEÑOR, a la entrada de la Tienda de reunión, al que se purifica y a sus ofrendas.'),
('nvi', 'Levítico 14:12', 'Levítico', 14, 12, 'Después el sacerdote tomará uno de los corderos y, junto con el aceite, lo ofrecerá como sacrificio por la culpa. Lo mecerá ante el SEÑOR, pues se trata de una ofrenda mecida.'),
('nvi', 'Levítico 14:13', 'Levítico', 14, 13, 'Después degollará al cordero en el lugar santo, donde se degüellan las víctimas del sacrificio expiatorio y del holocausto, porque el sacrificio por la culpa, al igual que el sacrificio expiatorio, pertenecen al sacerdote. Se trata de algo sumamente sagrado.'),
('nvi', 'Levítico 14:14', 'Levítico', 14, 14, 'Luego tomará el sacerdote un poco de sangre del sacrificio por la culpa y la untará en el lóbulo de la oreja derecha, en el pulgar de la mano derecha y en el dedo gordo del pie derecho del que se purifica.'),
('nvi', 'Levítico 14:15', 'Levítico', 14, 15, 'El sacerdote tomará un poco de aceite y se lo echará en la palma de la mano izquierda.'),
('nvi', 'Levítico 14:16', 'Levítico', 14, 16, 'Mojará el índice de la mano derecha en el aceite que tiene en la palma izquierda, y rociará el aceite siete veces ante el SEÑOR.'),
('nvi', 'Levítico 14:17', 'Levítico', 14, 17, 'Luego, del aceite que le quede en la mano, el sacerdote untará un poco en el lóbulo de la oreja derecha, en el pulgar de la mano derecha y en el dedo gordo del pie derecho del que se purifica, sobre la sangre del sacrificio por la culpa.'),
('nvi', 'Levítico 14:18', 'Levítico', 14, 18, 'El sacerdote derramará sobre la cabeza del que se purifica el aceite que le quede en la mano. De este modo celebrará ante el SEÑOR el rito de propiciación por él.'),
('nvi', 'Levítico 14:19', 'Levítico', 14, 19, 'A continuación, el sacerdote ofrecerá el sacrificio expiatorio, haciendo propiciación por el que se purifica de su impureza. Hecho esto, degollará la víctima del holocausto,'),
('nvi', 'Levítico 14:20', 'Levítico', 14, 20, 'y la ofrecerá en el altar junto con la ofrenda de cereal. Así hará propiciación por él, y lo declarará puro.'),
('nvi', 'Levítico 14:21', 'Levítico', 14, 21, '»Si el que se purifica es pobre y no tiene para comprar lo requerido, tomará como sacrificio por la culpa un solo cordero, el cual será mecido para hacer propiciación por él. También llevará como ofrenda de cereal dos kilos de flor de harina amasada con aceite, y un cuarto de litro de aceite,'),
('nvi', 'Levítico 14:22', 'Levítico', 14, 22, 'junto con dos tórtolas o dos pichones de paloma, según lo que pueda pagar, uno como sacrificio expiatorio y otro como holocausto.'),
('nvi', 'Levítico 14:23', 'Levítico', 14, 23, 'Al octavo día los llevará a la entrada de la Tienda de reunión, ante el sacerdote, para su purificación en presencia del SEÑOR.'),
('nvi', 'Levítico 14:24', 'Levítico', 14, 24, 'El sacerdote tomará el cordero del sacrificio por la culpa, junto con el aceite, y los mecerá ante el SEÑOR, pues se trata de una ofrenda mecida.'),
('nvi', 'Levítico 14:25', 'Levítico', 14, 25, 'Después degollará al cordero del sacrificio por la culpa, tomará un poco de sangre y la untará en el lóbulo de la oreja derecha, en el pulgar de la mano derecha y en el dedo gordo del pie derecho del que se purifica.'),
('nvi', 'Levítico 14:26', 'Levítico', 14, 26, 'El sacerdote se echará aceite en la palma de la mano izquierda,'),
('nvi', 'Levítico 14:27', 'Levítico', 14, 27, 'y con el índice de la mano derecha lo rociará siete veces ante el SEÑOR.'),
('nvi', 'Levítico 14:28', 'Levítico', 14, 28, 'Luego, al que se purifica, el sacerdote le untará un poco del aceite que le quede en la mano. Se lo untará en el lóbulo de la oreja derecha, en el pulgar de la mano derecha y en el dedo gordo del pie derecho, allí donde puso la sangre del sacrificio por la culpa.'),
('nvi', 'Levítico 14:29', 'Levítico', 14, 29, 'El aceite que le quede en la mano lo untará el sacerdote en la cabeza del que se purifica, y así hará propiciación por él ante el SEÑOR.'),
('nvi', 'Levítico 14:30', 'Levítico', 14, 30, 'Luego ofrecerá las tórtolas o los pichones de paloma, según lo que pueda pagar el oferente,'),
('nvi', 'Levítico 14:31', 'Levítico', 14, 31, 'uno como sacrificio expiatorio y otro como holocausto, junto con la ofrenda de cereal. Así hará el sacerdote propiciación ante el SEÑOR en favor del que se purifica.»'),
('nvi', 'Levítico 14:32', 'Levítico', 14, 32, 'Esta ley se aplicará a la persona que haya contraído una infección cutánea y no tenga para pagar las ofrendas regulares de su purificación.'),
('nvi', 'Levítico 14:33', 'Levítico', 14, 33, 'El SEÑOR les dijo a Moisés y a Aarón:'),
('nvi', 'Levítico 14:34', 'Levítico', 14, 34, '«Si al entrar ustedes en la tierra de Canaán, la cual les doy en propiedad, yo pongo moho infeccioso en alguna de sus casas,'),
('nvi', 'Levítico 14:35', 'Levítico', 14, 35, 'el dueño de la casa deberá decirle al sacerdote: “En mi casa ha aparecido una especie de moho.”'),
('nvi', 'Levítico 14:36', 'Levítico', 14, 36, 'Entonces el sacerdote, antes de entrar para examinar el moho, mandará que desocupen la casa para que no se contamine todo lo que haya en ella. Hecho esto, el sacerdote entrará a examinarla.'),
('nvi', 'Levítico 14:37', 'Levítico', 14, 37, 'Si el moho de las paredes forma cavidades verduscas o rojizas que parezcan hundirse en la pared,'),
('nvi', 'Levítico 14:38', 'Levítico', 14, 38, 'el sacerdote saldrá de la casa y la clausurará durante siete días.'),
('nvi', 'Levítico 14:39', 'Levítico', 14, 39, 'Al séptimo día regresará y la examinará. Si el moho se ha extendido por las paredes de la casa,'),
('nvi', 'Levítico 14:40', 'Levítico', 14, 40, 'mandará quitar las piedras mohosas y tirarlas fuera de la ciudad, en un lugar impuro.'),
('nvi', 'Levítico 14:41', 'Levítico', 14, 41, 'También mandará raspar todo el interior de la casa, y el material raspado lo arrojará fuera de la ciudad, en un lugar impuro.'),
('nvi', 'Levítico 14:42', 'Levítico', 14, 42, 'Después se repondrán las antiguas piedras con otras nuevas, y se resanará la casa con estuco nuevo.'),
('nvi', 'Levítico 14:43', 'Levítico', 14, 43, '»Si después de haber quitado las piedras infectadas y de haber raspado y resanado la casa, vuelve a aparecer el moho y se extiende por toda ella,'),
('nvi', 'Levítico 14:44', 'Levítico', 14, 44, 'el sacerdote irá a examinarla. Si el moho se ha extendido por toda la casa, se trata de moho corrosivo. Por lo tanto, la casa es impura'),
('nvi', 'Levítico 14:45', 'Levítico', 14, 45, 'y deberán demolerla y arrojar, en un lugar impuro fuera de la ciudad, las piedras, el maderamen y el estuco.'),
('nvi', 'Levítico 14:46', 'Levítico', 14, 46, '»Cualquiera que entre en la casa mientras esté clausurada quedará impuro hasta el anochecer,'),
('nvi', 'Levítico 14:47', 'Levítico', 14, 47, 'y todo el que duerma o coma en dicha casa deberá lavarse la ropa.'),
('nvi', 'Levítico 14:48', 'Levítico', 14, 48, '»Si después de haber sido resanada la casa, el sacerdote la examina y el moho no se ha extendido, la declarará pura, porque la infección ha desaparecido.'),
('nvi', 'Levítico 14:49', 'Levítico', 14, 49, '»Para purificar la casa, el sacerdote deberá tomar dos aves, pedazos de madera de cedro, ramas de hisopo y un paño escarlata.'),
('nvi', 'Levítico 14:50', 'Levítico', 14, 50, 'Degollará una de las aves sobre una vasija de barro llena de agua de manantial;'),
('nvi', 'Levítico 14:51', 'Levítico', 14, 51, 'tomará la madera de cedro, las ramas de hisopo, el paño escarlata y la otra ave viva, y mojará todo esto en la sangre del ave degollada y en el agua de manantial.'),
('nvi', 'Levítico 14:52', 'Levítico', 14, 52, 'Luego rociará la casa siete veces, y así la purificará con la sangre del ave, con el agua de manantial y con el ave viva, la madera de cedro, las ramas de hisopo y el paño escarlata.'),
('nvi', 'Levítico 14:53', 'Levítico', 14, 53, 'Soltará entonces el ave viva a campo abierto. Así hará propiciación por la casa, y ésta quedará pura.'),
('nvi', 'Levítico 14:54', 'Levítico', 14, 54, '»Ésta es la ley respecto a cualquier tipo de infección cutánea o de tiña,'),
('nvi', 'Levítico 14:55', 'Levítico', 14, 55, 'o de moho, ya sea en la ropa o en una casa,'),
('nvi', 'Levítico 14:56', 'Levítico', 14, 56, 'o de inflamación, o erupción o mancha blancuzca'),
('nvi', 'Levítico 14:57', 'Levítico', 14, 57, 'para así poder enseñar al pueblo cuándo algo es puro o impuro. Ésta es la ley respecto a las infecciones.»'),
('nvi', 'Levítico 15:1', 'Levítico', 15, 1, 'El SEÑOR les ordenó a Moisés y a Aarón'),
('nvi', 'Levítico 15:2', 'Levítico', 15, 2, 'que les dijeran a los israelitas: «Si algún hombre tiene un derrame seminal, tal derrame es impuro,'),
('nvi', 'Levítico 15:3', 'Levítico', 15, 3, 'lo mismo que el hombre, ya sea que su órgano sexual emita el flujo o que el flujo obstruya el órgano. »El flujo causa impureza en los siguientes casos:'),
('nvi', 'Levítico 15:4', 'Levítico', 15, 4, '»Será impura toda cama donde se acueste el afectado por el flujo, lo mismo que todo objeto sobre el que se siente.'),
('nvi', 'Levítico 15:5', 'Levítico', 15, 5, '»Todo el que toque la cama del afectado por el flujo deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:6', 'Levítico', 15, 6, '»Todo el que se siente donde se haya sentado el afectado por el flujo deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:7', 'Levítico', 15, 7, '»Todo el que toque el cuerpo del afectado por el flujo deberá lavarse la ropa y bañarse con agua, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:8', 'Levítico', 15, 8, '»Si el afectado por el flujo escupe sobre alguien no contaminado, éste deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:9', 'Levítico', 15, 9, '»Toda montura sobre la que cabalgue el afectado por el flujo quedará impura.'),
('nvi', 'Levítico 15:10', 'Levítico', 15, 10, '»Todo el que toque algún objeto que haya estado debajo del afectado por el flujo quedará impuro hasta el anochecer; el que transporte dicho objeto deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:11', 'Levítico', 15, 11, '»Si el afectado por el flujo toca a alguien sin haberse lavado las manos con agua, el que fue tocado deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:12', 'Levítico', 15, 12, '»Si el afectado por el flujo toca alguna vasija de barro, se romperá la vasija; si toca algún utensilio de madera, éste deberá lavarse con agua.'),
('nvi', 'Levítico 15:13', 'Levítico', 15, 13, '»Si al afectado le cesa el flujo, deberá esperar siete días para el rito de su purificación. Se lavará la ropa y se bañará con agua de manantial, y así quedará puro.'),
('nvi', 'Levítico 15:14', 'Levítico', 15, 14, 'Al octavo día tomará dos tórtolas o dos pichones de paloma, y se presentará ante el SEÑOR, a la entrada de la Tienda de reunión. Allí entregará las aves al sacerdote,'),
('nvi', 'Levítico 15:15', 'Levítico', 15, 15, 'quien ofrecerá una como sacrificio expiatorio y la otra como holocausto. Así, en presencia del SEÑOR, el sacerdote hará propiciación por el afectado a causa de su flujo.'),
('nvi', 'Levítico 15:16', 'Levítico', 15, 16, '»Cuando un hombre tenga una eyaculación, deberá bañarse todo el cuerpo, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:17', 'Levítico', 15, 17, 'Toda ropa o piel sobre la que haya caído semen deberá lavarse con agua, y quedará impura hasta el anochecer.'),
('nvi', 'Levítico 15:18', 'Levítico', 15, 18, '»Cuando un hombre y una mujer tengan relaciones sexuales con eyaculación, ambos deberán bañarse, y quedarán impuros hasta el anochecer.'),
('nvi', 'Levítico 15:19', 'Levítico', 15, 19, '»Cuando a una mujer le llegue su menstruación, quedará impura durante siete días. »Todo el que la toque quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:20', 'Levítico', 15, 20, '»Todo aquello sobre lo que ella se acueste mientras dure su período menstrual quedará impuro. »Todo aquello sobre lo que ella se siente durante su período menstrual quedará impuro.'),
('nvi', 'Levítico 15:21', 'Levítico', 15, 21, '»Todo el que toque la cama de esa mujer deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:22', 'Levítico', 15, 22, '»Todo el que toque algún objeto donde ella se haya sentado, deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:23', 'Levítico', 15, 23, '»Si alguien toca algún objeto que estuvo sobre su cama o en el lugar donde ella se sentó, quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:24', 'Levítico', 15, 24, '»Si un hombre tiene relaciones sexuales con esa mujer, se contaminará con su menstruación y quedará impuro durante siete días. Además, toda cama en la que él se acueste quedará también impura.'),
('nvi', 'Levítico 15:25', 'Levítico', 15, 25, '»Cuando una mujer tenga flujo continuo de sangre fuera de su período menstrual, o cuando se le prolongue el flujo, quedará impura todo el tiempo que le dure, como durante su período.'),
('nvi', 'Levítico 15:26', 'Levítico', 15, 26, '»Toda cama en la que se acueste mientras dure su flujo quedará impura, como durante su período. »Todo aquello sobre lo que se siente quedará impuro, como durante su período.'),
('nvi', 'Levítico 15:27', 'Levítico', 15, 27, '»Todo el que toque cualquiera de estos objetos quedará impuro. Deberá lavarse la ropa y bañarse, y quedará impuro hasta el anochecer.'),
('nvi', 'Levítico 15:28', 'Levítico', 15, 28, '»Cuando ella sane de su flujo, deberá esperar siete días para el rito de su purificación.'),
('nvi', 'Levítico 15:29', 'Levítico', 15, 29, 'Al octavo día tomará dos tórtolas o dos pichones de paloma, y los llevará a la entrada de la Tienda de reunión, donde se los entregará al sacerdote,'),
('nvi', 'Levítico 15:30', 'Levítico', 15, 30, 'quien ofrecerá uno como sacrificio expiatorio y el otro como holocausto. Así, en presencia del SEÑOR, el sacerdote hará propiciación por ella a causa de su flujo.'),
('nvi', 'Levítico 15:31', 'Levítico', 15, 31, 'Üstedes deben mantener apartados de la impureza a los israelitas. Así evitarán que ellos mueran por haber contaminado mi santuario, que está en medio de ellos.'),
('nvi', 'Levítico 15:32', 'Levítico', 15, 32, '»Esta ley se aplicará a quien quede impuro por derrame seminal,'),
('nvi', 'Levítico 15:33', 'Levítico', 15, 33, 'a la que tenga flujo menstrual, al hombre y a la mujer que tenga relaciones sexuales con eyaculación, y a quien tenga relaciones sexuales con una mujer impura.»'),
('nvi', 'Levítico 16:1', 'Levítico', 16, 1, 'El SEÑOR le habló a Moisés después de la muerte de los dos hijos de Aarón, quienes murieron al acercarse imprudentemente al SEÑOR.'),
('nvi', 'Levítico 16:2', 'Levítico', 16, 2, 'Le dijo el SEÑOR a Moisés: «Dile a tu hermano Aarón que no entre a cualquier hora en la parte del santuario que está detrás de la cortina, es decir, delante del propiciatorio que está sobre el arca, no sea que muera cuando yo aparezca en la nube por encima del propiciatorio.'),
('nvi', 'Levítico 16:3', 'Levítico', 16, 3, '»Aarón deberá entrar en el santuario con un novillo para el sacrificio expiatorio y un carnero para el holocausto.'),
('nvi', 'Levítico 16:4', 'Levítico', 16, 4, 'Se pondrá la túnica sagrada de lino y la ropa interior de lino. Se ceñirá con la faja de lino y se pondrá la tiara de lino. Éstas son las vestiduras sagradas que se pondrá después de haberse bañado con agua.'),
('nvi', 'Levítico 16:5', 'Levítico', 16, 5, '»De la comunidad de los israelitas, Aarón tomará dos machos cabríos para el sacrificio expiatorio y un carnero para el holocausto.'),
('nvi', 'Levítico 16:6', 'Levítico', 16, 6, 'Después de que haya ofrecido el novillo del sacrificio expiatorio como propiciación por él y por su familia,'),
('nvi', 'Levítico 16:7', 'Levítico', 16, 7, 'tomará los dos machos cabríos y los presentará ante el SEÑOR, a la entrada de la Tienda de reunión.'),
('nvi', 'Levítico 16:8', 'Levítico', 16, 8, 'Entonces Aarón echará suertes sobre los dos machos cabríos, uno para el SEÑOR y otro para soltarlo en el desierto.'),
('nvi', 'Levítico 16:9', 'Levítico', 16, 9, 'Aarón ofrecerá como sacrificio expiatorio el macho cabrío que le tocó al SEÑOR,'),
('nvi', 'Levítico 16:10', 'Levítico', 16, 10, 'pero presentará vivo ante el SEÑOR, como propiciación, el macho cabrío que soltará en el desierto; es decir, lo enviará a Azazel.'),
('nvi', 'Levítico 16:11', 'Levítico', 16, 11, '»Aarón presentará el novillo para su propio sacrificio expiatorio, y hará propiciación por él y por su familia. Degollará el novillo para su propio sacrificio expiatorio;'),
('nvi', 'Levítico 16:12', 'Levítico', 16, 12, 'luego tomará del altar que está ante el SEÑOR un incensario lleno de brasas, junto con dos puñados llenos de incienso aromático en polvo, y los llevará tras la cortina;'),
('nvi', 'Levítico 16:13', 'Levítico', 16, 13, 'colocará entonces el incienso sobre el fuego, en presencia del SEÑOR, para que la nube de incienso cubra el propiciatorio que está sobre el arca del pacto. De esa manera Aarón no morirá.'),
('nvi', 'Levítico 16:14', 'Levítico', 16, 14, 'Después tomará un poco de la sangre del novillo y la rociará con su dedo al costado oriental del propiciatorio; la rociará delante del propiciatorio siete veces.'),
('nvi', 'Levítico 16:15', 'Levítico', 16, 15, '»Luego degollará el macho cabrío del sacrificio expiatorio en favor del pueblo. Llevará su sangre detrás de la cortina, y hará con esa sangre lo mismo que hizo con la del novillo: la rociará sobre y delante del propiciatorio.'),
('nvi', 'Levítico 16:16', 'Levítico', 16, 16, 'Así hará propiciación por el santuario para purificarlo de las impurezas y transgresiones de los israelitas, cualesquiera que hayan sido sus pecados. Hará lo mismo por la Tienda de reunión, que está entre ellos en medio de sus impurezas.'),
('nvi', 'Levítico 16:17', 'Levítico', 16, 17, 'Nadie deberá estar en la Tienda de reunión desde el momento en que Aarón entre para hacer propiciación en el santuario hasta que salga, es decir, mientras esté haciendo propiciación por sí mismo, por su familia y por toda la asamblea de Israel.'),
('nvi', 'Levítico 16:18', 'Levítico', 16, 18, '»Aarón saldrá luego para hacer propiciación por el altar que está delante del SEÑOR. Tomará sangre del novillo y del macho cabrío, y la untará sobre cada uno de los cuernos del altar,'),
('nvi', 'Levítico 16:19', 'Levítico', 16, 19, 'y con el dedo rociará con sangre el altar siete veces. Así lo santificará y lo purificará de las impurezas de los israelitas.'),
('nvi', 'Levítico 16:20', 'Levítico', 16, 20, '»Cuando Aarón haya terminado de hacer propiciación por el santuario, la Tienda de reunión y el altar, presentará el macho cabrío vivo,'),
('nvi', 'Levítico 16:21', 'Levítico', 16, 21, 'y le impondrá las manos sobre la cabeza. Confesará entonces todas las iniquidades y transgresiones de los israelitas, cualesquiera que hayan sido sus pecados. Así el macho cabrío cargará con ellos, y será enviado al desierto por medio de un hombre designado para esto.'),
('nvi', 'Levítico 16:22', 'Levítico', 16, 22, 'El hombre soltará en el desierto al macho cabrío, y éste se llevará a tierra árida todas las iniquidades.'),
('nvi', 'Levítico 16:23', 'Levítico', 16, 23, '»Entonces Aarón entrará en la Tienda de reunión, se quitará los vestidos de lino que se puso antes de entrar en el santuario, y allí los dejará.'),
('nvi', 'Levítico 16:24', 'Levítico', 16, 24, 'Se bañará con agua en un lugar santo y se volverá a vestir. Después saldrá y ofrecerá su propio holocausto y el del pueblo. Así hará propiciación por sí mismo y por el pueblo.'),
('nvi', 'Levítico 16:25', 'Levítico', 16, 25, 'Además, quemará sobre el altar la grasa del sacrificio expiatorio.'),
('nvi', 'Levítico 16:26', 'Levítico', 16, 26, '»El encargado de soltar el macho cabrío en el desierto deberá lavarse la ropa y bañarse con agua. Sólo después de hacer esto podrá volver al campamento.'),
('nvi', 'Levítico 16:27', 'Levítico', 16, 27, '»El novillo del sacrificio expiatorio y el macho cabrío del sacrificio expiatorio, cuya sangre se llevó para hacer propiciación por el santuario, se sacarán del campamento, y la piel, la carne y el excremento se quemarán.'),
('nvi', 'Levítico 16:28', 'Levítico', 16, 28, 'El que les prenda fuego deberá lavarse la ropa y bañarse. Sólo después de hacer esto podrá volver al campamento.'),
('nvi', 'Levítico 16:29', 'Levítico', 16, 29, '»Éste será para ustedes un estatuto perpetuo, tanto para el nativo como para el extranjero: El día diez del mes séptimo ayunarán y no realizarán ningún tipo de trabajo.'),
('nvi', 'Levítico 16:30', 'Levítico', 16, 30, 'En dicho día se hará propiciación por ustedes para purificarlos, y delante del SEÑOR serán purificados de todos sus pecados.'),
('nvi', 'Levítico 16:31', 'Levítico', 16, 31, 'Será para ustedes un día de completo reposo, en el cual ayunarán. Es un estatuto perpetuo.'),
('nvi', 'Levítico 16:32', 'Levítico', 16, 32, '»La propiciación la realizará el sacerdote que haya sido ungido y ordenado como sucesor de su padre. Se pondrá las vestiduras sagradas de lino,'),
('nvi', 'Levítico 16:33', 'Levítico', 16, 33, 'y hará propiciación por el lugar santísimo, por la Tienda de reunión y por el altar. También hará propiciación por los sacerdotes y por toda la comunidad allí reunida.'),
('nvi', 'Levítico 16:34', 'Levítico', 16, 34, '»Éste les será un estatuto perpetuo: Una vez al año se deberá hacer propiciación por todos los israelitas a causa de todos sus pecados.» Y se hizo tal como el SEÑOR se lo había mandado a Moisés.'),
('nvi', 'Levítico 17:1', 'Levítico', 17, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 17:2', 'Levítico', 17, 2, 'que les dijera a Aarón y a sus hijos, y a todos los israelitas: «Esto es lo que ha mandado el SEÑOR:'),
('nvi', 'Levítico 17:3', 'Levítico', 17, 3, '»Cuando algún israelita sacrifique una res, un cordero o una cabra dentro o fuera del campamento,'),
('nvi', 'Levítico 17:4', 'Levítico', 17, 4, 'será considerado culpable de haber derramado sangre si no lleva el animal a la entrada de la Tienda de reunión y lo presenta como ofrenda al SEÑOR ante su santuario. Por lo tanto, ese israelita será eliminado de su pueblo.'),
('nvi', 'Levítico 17:5', 'Levítico', 17, 5, 'El propósito de este mandamiento es que los israelitas lleven al SEÑOR los sacrificios que suelen hacer en el campo. Deberán llevarlos al sacerdote, a la entrada de la Tienda de reunión, y ofrecérselos al SEÑOR como sacrificios de comunión.'),
('nvi', 'Levítico 17:6', 'Levítico', 17, 6, 'El sacerdote derramará la sangre sobre el altar del SEÑOR, a la entrada de la Tienda de reunión, y quemará la grasa como aroma grato al SEÑOR.'),
('nvi', 'Levítico 17:7', 'Levítico', 17, 7, 'Y nunca más volverán a ofrecer ningún sacrificio a sus ídolos que tienen forma de machos cabríos, con los que se han prostituido. Éste es un estatuto perpetuo para ellos y para sus descendientes.'),
('nvi', 'Levítico 17:8', 'Levítico', 17, 8, '»Cuando algún israelita o extranjero que viva entre ustedes ofrezca un holocausto o sacrificio'),
('nvi', 'Levítico 17:9', 'Levítico', 17, 9, 'y no lo lleve a la entrada de la Tienda de reunión para ofrecerlo al SEÑOR, el tal será eliminado de su pueblo.'),
('nvi', 'Levítico 17:10', 'Levítico', 17, 10, '»Cuando algún israelita o extranjero que viva entre ustedes coma cualquier clase de sangre, yo me pondré en su contra y lo eliminaré de su pueblo.'),
('nvi', 'Levítico 17:11', 'Levítico', 17, 11, 'Porque la vida de toda criatura está en la sangre. Yo mismo se la he dado a ustedes sobre el altar, para que hagan propiciación por ustedes mismos, ya que la propiciación se hace por medio de la sangre.'),
('nvi', 'Levítico 17:12', 'Levítico', 17, 12, 'Por eso les digo: Ninguno de ustedes deberá comer sangre, ni tampoco deberá comerla el extranjero que viva entre ustedes.'),
('nvi', 'Levítico 17:13', 'Levítico', 17, 13, '»Cuando un israelita o algún extranjero que viva entre ustedes cace algún animal o ave que sea lícito comer, le extraerá la sangre y la cubrirá con tierra,'),
('nvi', 'Levítico 17:14', 'Levítico', 17, 14, 'pues la vida de toda criatura está en su sangre. Por eso les he dicho: No coman la sangre de ninguna criatura, porque la vida de toda criatura está en la sangre; cualquiera que la coma será eliminado.'),
('nvi', 'Levítico 17:15', 'Levítico', 17, 15, '»Todo nativo o extranjero que coma la carne de un animal que las fieras hayan matado o despedazado, deberá lavarse la ropa y bañarse con agua, y quedará impuro hasta el anochecer; después de eso quedará puro.'),
('nvi', 'Levítico 17:16', 'Levítico', 17, 16, 'Pero si no se lava la ropa ni se baña, sufrirá las consecuencias de su pecado.»'),
('nvi', 'Levítico 18:1', 'Levítico', 18, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 18:2', 'Levítico', 18, 2, 'que les dijera a los israelitas: «Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 18:3', 'Levítico', 18, 3, 'No imitarán ustedes las costumbres de Egipto, donde antes habitaban, ni tampoco las de Canaán, adonde los llevo. No se conducirán según sus estatutos,'),
('nvi', 'Levítico 18:4', 'Levítico', 18, 4, 'sino que pondrán en práctica mis preceptos y observarán atentamente mis leyes. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 18:5', 'Levítico', 18, 5, 'Observen mis estatutos y mis preceptos, pues todo el que los practique vivirá por ellos. Yo soy el SEÑOR.'),
('nvi', 'Levítico 18:6', 'Levítico', 18, 6, '»Nadie se acercará a ningún pariente cercano para tener relaciones sexuales con él o con ella. Yo soy el SEÑOR.'),
('nvi', 'Levítico 18:7', 'Levítico', 18, 7, '»No deshonrarás a tu padre, teniendo relaciones sexuales con tu madre. No lo hagas, porque es tu madre.'),
('nvi', 'Levítico 18:8', 'Levítico', 18, 8, '»No tendrás relaciones sexuales con la esposa de tu padre, porque sería como tenerlas con él.'),
('nvi', 'Levítico 18:9', 'Levítico', 18, 9, '»No tendrás relaciones sexuales con tu hermana por parte de padre o de madre, ya sea nacida en la misma casa o en otro lugar.'),
('nvi', 'Levítico 18:10', 'Levítico', 18, 10, '»No tendrás relaciones sexuales con la hija de tu hijo, ni con la hija de tu hija, porque sería deshonrarte a ti mismo.'),
('nvi', 'Levítico 18:11', 'Levítico', 18, 11, '»No tendrás relaciones sexuales con la hija que tu padre haya tenido con su mujer. No la deshonres, porque es tu hermana.'),
('nvi', 'Levítico 18:12', 'Levítico', 18, 12, '»No tendrás relaciones sexuales con la hermana de tu padre, porque sería como tenerlas con tu padre.'),
('nvi', 'Levítico 18:13', 'Levítico', 18, 13, '»No tendrás relaciones sexuales con la hermana de tu madre, porque sería como tenerlas con tu madre.'),
('nvi', 'Levítico 18:14', 'Levítico', 18, 14, '»No deshonrarás al hermano de tu padre, teniendo relaciones sexuales con su mujer, porque es tu tía.'),
('nvi', 'Levítico 18:15', 'Levítico', 18, 15, '»No tendrás relaciones sexuales con tu nuera. No las tendrás, porque sería como tenerlas con tu hijo.'),
('nvi', 'Levítico 18:16', 'Levítico', 18, 16, '»No tendrás relaciones sexuales con la mujer de tu hermano, porque sería como tenerlas con él mismo.'),
('nvi', 'Levítico 18:17', 'Levítico', 18, 17, '»No tendrás relaciones sexuales con dos mujeres que sean madre e hija, ni con las nietas de ellas, ya sea por parte de un hijo o de una hija de las mismas. Son parientes cercanas, de modo que eso sería una perversión.'),
('nvi', 'Levítico 18:18', 'Levítico', 18, 18, '»No te casarás con la hermana de tu esposa, ni tendrás relaciones sexuales con ella mientras tu esposa viva, para no crear rivalidades entre ellas.'),
('nvi', 'Levítico 18:19', 'Levítico', 18, 19, '»No tendrás relaciones sexuales con ninguna mujer durante su período de impureza menstrual.'),
('nvi', 'Levítico 18:20', 'Levítico', 18, 20, '»No tendrás trato sexual con la mujer de tu prójimo, para que no te hagas impuro por causa de ella.'),
('nvi', 'Levítico 18:21', 'Levítico', 18, 21, '»No profanarás el nombre de tu Dios, entregando a tus hijos para que sean quemados como sacrificio a Moloc. Yo soy el SEÑOR.'),
('nvi', 'Levítico 18:22', 'Levítico', 18, 22, '»No te acostarás con un hombre como quien se acuesta con una mujer. Eso es una abominación.'),
('nvi', 'Levítico 18:23', 'Levítico', 18, 23, '»No tendrás trato sexual con ningún animal. No te hagas impuro por causa de él. »Ninguna mujer tendrá trato sexual con ningún animal. Eso es una depravación.'),
('nvi', 'Levítico 18:24', 'Levítico', 18, 24, '»No se contaminen con estas prácticas, porque así se contaminaron las naciones que por amor a ustedes estoy por arrojar,'),
('nvi', 'Levítico 18:25', 'Levítico', 18, 25, 'y aun la tierra misma se contaminó. Por eso la castigué por su perversidad, y ella vomitó a sus habitantes.'),
('nvi', 'Levítico 18:26', 'Levítico', 18, 26, 'Ustedes obedezcan mis estatutos y preceptos. Ni los nativos ni los extranjeros que vivan entre ustedes deben practicar ninguna de estas abominaciones,'),
('nvi', 'Levítico 18:27', 'Levítico', 18, 27, 'pues las practicaron los que vivían en esta tierra antes que ustedes, y la tierra se contaminó.'),
('nvi', 'Levítico 18:28', 'Levítico', 18, 28, 'Si ustedes contaminan la tierra, ella los vomitará como vomitó a las naciones que la habitaron antes que ustedes.'),
('nvi', 'Levítico 18:29', 'Levítico', 18, 29, '»Cualquiera que practique alguna de estas abominaciones será eliminado de su pueblo.'),
('nvi', 'Levítico 18:30', 'Levítico', 18, 30, 'Ustedes observen mis mandamientos y absténganse de seguir las abominables costumbres que se practicaban en la tierra antes de que ustedes llegaran. No se contaminen por causa de ellas. Yo soy el SEÑOR su Dios.»'),
('nvi', 'Levítico 19:1', 'Levítico', 19, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 19:2', 'Levítico', 19, 2, 'que hablara con toda la asamblea de los israelitas y les dijera: «Sean santos, porque yo, el SEÑOR su Dios, soy santo.'),
('nvi', 'Levítico 19:3', 'Levítico', 19, 3, '»Respeten todos ustedes a su madre y a su padre, y observen mis sábados. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 19:4', 'Levítico', 19, 4, '»No se vuelvan a los ídolos inútiles, ni se hagan dioses de metal fundido. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 19:5', 'Levítico', 19, 5, '»Cuando le ofrezcan al SEÑOR un sacrificio de comunión, háganlo de tal manera que el SEÑOR lo acepte de buen grado.'),
('nvi', 'Levítico 19:6', 'Levítico', 19, 6, 'Cómanselo el día en que lo sacrifiquen, o al día siguiente. Lo que sobre para el tercer día deberán quemarlo.'),
('nvi', 'Levítico 19:7', 'Levítico', 19, 7, 'Si alguien lo come al tercer día, tal sacrificio no le será válido, pues la carne ya se habrá descompuesto.'),
('nvi', 'Levítico 19:8', 'Levítico', 19, 8, 'Cualquiera que lo coma sufrirá las consecuencias de su pecado por profanar lo que ha sido consagrado al SEÑOR. Tal persona será eliminada de su pueblo.'),
('nvi', 'Levítico 19:9', 'Levítico', 19, 9, '»Cuando llegue el tiempo de la cosecha, no sieguen hasta el último rincón de sus campos ni recojan todas las espigas que allí queden.'),
('nvi', 'Levítico 19:10', 'Levítico', 19, 10, '»No rebusquen hasta el último racimo de sus viñas, ni recojan las uvas que se hayan caído. Déjenlas para los pobres y los extranjeros. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 19:11', 'Levítico', 19, 11, '»No roben. »No mientan. »No engañen a su prójimo.'),
('nvi', 'Levítico 19:12', 'Levítico', 19, 12, '»No juren en mi nombre sólo por jurar, ni profanen el nombre de su Dios. Yo soy el SEÑOR.'),
('nvi', 'Levítico 19:13', 'Levítico', 19, 13, '»No explotes a tu prójimo, ni lo despojes de nada. »No retengas el salario de tu jornalero hasta el día siguiente.'),
('nvi', 'Levítico 19:14', 'Levítico', 19, 14, '»No maldigas al sordo, ni le pongas tropiezos al ciego, sino teme a tu Dios. Yo soy el SEÑOR.'),
('nvi', 'Levítico 19:15', 'Levítico', 19, 15, '»No perviertas la justicia, ni te muestres parcial en favor del pobre o del rico, sino juzga a todos con justicia.'),
('nvi', 'Levítico 19:16', 'Levítico', 19, 16, '»No andes difundiendo calumnias entre tu pueblo, ni expongas la vida de tu prójimo con falsos testimonios. Yo soy el SEÑOR.'),
('nvi', 'Levítico 19:17', 'Levítico', 19, 17, '»No alimentes odios secretos contra tu hermano, sino reprende con franqueza a tu prójimo para que no sufras las consecuencias de su pecado.'),
('nvi', 'Levítico 19:18', 'Levítico', 19, 18, '»No seas vengativo con tu prójimo, ni le guardes rencor. Ama a tu prójimo como a ti mismo. Yo soy el SEÑOR.'),
('nvi', 'Levítico 19:19', 'Levítico', 19, 19, '»Cumplan mis estatutos: »No crucen animales de especies diferentes. »No planten en su campo dos clases distintas de semilla. »No usen ropa tejida con dos clases distintas de hilo.'),
('nvi', 'Levítico 19:20', 'Levítico', 19, 20, '»Si un hombre se acuesta con una esclava prometida a otro en matrimonio, pero que aún no ha sido rescatada ni declarada libre, a los dos se les impondrá el castigo debido, pero no se les condenará a muerte porque ella aún no ha sido declarada libre.'),
('nvi', 'Levítico 19:21', 'Levítico', 19, 21, 'No obstante, el hombre deberá ofrecer al SEÑOR un carnero como ofrenda por su culpa. Lo llevará a la entrada de la Tienda de reunión,'),
('nvi', 'Levítico 19:22', 'Levítico', 19, 22, 'y el sacerdote hará expiación ante el SEÑOR por el pecado cometido. De este modo su pecado le será perdonado.'),
('nvi', 'Levítico 19:23', 'Levítico', 19, 23, '»Cuando ustedes entren en la tierra y planten cualquier clase de árboles frutales, durante tres años no comerán su fruto, sino que lo considerarán inmundo.'),
('nvi', 'Levítico 19:24', 'Levítico', 19, 24, 'En el cuarto año todo su fruto será consagrado como una ofrenda de alabanza al SEÑOR,'),
('nvi', 'Levítico 19:25', 'Levítico', 19, 25, 'y en el quinto año ya podrán comer de su fruto. De este modo aumentarán sus cosechas. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 19:26', 'Levítico', 19, 26, '»No coman nada que tenga sangre. »No practiquen la adivinación ni los sortilegios.'),
('nvi', 'Levítico 19:27', 'Levítico', 19, 27, '»No se corten el cabello en redondo ni se despunten la barba.'),
('nvi', 'Levítico 19:28', 'Levítico', 19, 28, '»No se hagan heridas en el cuerpo por causa de los muertos, ni tatuajes en la piel. Yo soy el SEÑOR.'),
('nvi', 'Levítico 19:29', 'Levítico', 19, 29, '»No degraden a su hija haciendo de ella una prostituta, para que tampoco se prostituya la tierra ni se llene de perversidad.'),
('nvi', 'Levítico 19:30', 'Levítico', 19, 30, '»Observen mis sábados, y tengan reverencia por mi santuario. Yo soy el SEÑOR.'),
('nvi', 'Levítico 19:31', 'Levítico', 19, 31, '»No acudan a la nigromancia, ni busquen a los espiritistas, porque se harán impuros por causa de ellos. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 19:32', 'Levítico', 19, 32, '»Ponte de pie en presencia de los mayores. »Respeta a los ancianos. »Teme a tu Dios. Yo soy el SEÑOR.'),
('nvi', 'Levítico 19:33', 'Levítico', 19, 33, '»Cuando algún extranjero se establezca en el país de ustedes, no lo traten mal.'),
('nvi', 'Levítico 19:34', 'Levítico', 19, 34, 'Al contrario, trátenlo como si fuera uno de ustedes. Ámenlo como a ustedes mismos, porque también ustedes fueron extranjeros en Egipto. Yo soy el SEÑOR y Dios de Israel.'),
('nvi', 'Levítico 19:35', 'Levítico', 19, 35, '»No cometan injusticias falseando las medidas de longitud, de peso y de capacidad.'),
('nvi', 'Levítico 19:36', 'Levítico', 19, 36, 'Usen balanzas, pesas y medidas justas. Yo soy el SEÑOR su Dios, que los saqué de Egipto.'),
('nvi', 'Levítico 19:37', 'Levítico', 19, 37, '»Obedezcan todos mis estatutos. Pongan por obra todos mis preceptos. Yo soy el SEÑOR.»'),
('nvi', 'Levítico 20:1', 'Levítico', 20, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 20:2', 'Levítico', 20, 2, 'que les dijera a los israelitas: «Todo israelita o extranjero residente en Israel que entregue a uno de sus hijos para quemarlo como sacrificio a Moloc, será condenado a muerte. Los miembros de la comunidad lo matarán a pedradas.'),
('nvi', 'Levítico 20:3', 'Levítico', 20, 3, 'Yo mismo me pondré en contra de ese hombre y lo eliminaré de su pueblo porque, al entregar a uno de sus hijos para quemarlo como sacrificio a Moloc, profana mi santuario y mi santo nombre.'),
('nvi', 'Levítico 20:4', 'Levítico', 20, 4, '»Si los miembros de la comunidad hacen caso omiso del hombre que haya entregado alguno de sus hijos a Moloc, y no lo condenan a muerte,'),
('nvi', 'Levítico 20:5', 'Levítico', 20, 5, 'yo mismo me pondré en contra de él y de su familia; eliminaré del pueblo a ese hombre y a todos los que se hayan prostituido con él, siguiendo a Moloc.'),
('nvi', 'Levítico 20:6', 'Levítico', 20, 6, '»También me pondré en contra de quien acuda a la nigromancia y a los espiritistas, y por seguirlos se prostituya. Lo eliminaré de su pueblo.'),
('nvi', 'Levítico 20:7', 'Levítico', 20, 7, '»Conságrense a mí, y sean santos, porque yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 20:8', 'Levítico', 20, 8, '»Obedezcan mis estatutos y pónganlos por obra. Yo soy el SEÑOR, que los santifica.'),
('nvi', 'Levítico 20:9', 'Levítico', 20, 9, '»Si alguien maldice a su padre o a su madre, será condenado a muerte: ha maldecido a su padre o a su madre, y será responsable de su propia muerte.'),
('nvi', 'Levítico 20:10', 'Levítico', 20, 10, '»Si alguien comete adulterio con la mujer de su prójimo, tanto el adúltero como la adúltera serán condenados a muerte.'),
('nvi', 'Levítico 20:11', 'Levítico', 20, 11, '»Si alguien se acuesta con la mujer de su padre, deshonra a su padre. Tanto el hombre como la mujer serán condenados a muerte, de la cual ellos mismos serán responsables.'),
('nvi', 'Levítico 20:12', 'Levítico', 20, 12, '»Si alguien se acuesta con su nuera, hombre y mujer serán condenados a muerte. Han cometido un acto depravado, y ellos mismos serán responsables de su propia muerte.'),
('nvi', 'Levítico 20:13', 'Levítico', 20, 13, '»Si alguien se acuesta con otro hombre como quien se acuesta con una mujer, comete un acto abominable y los dos serán condenados a muerte, de la cual ellos mismos serán responsables.'),
('nvi', 'Levítico 20:14', 'Levítico', 20, 14, '»Si alguien tiene relaciones sexuales con hija y madre, comete un acto depravado. Tanto él como ellas morirán quemados, para que no haya tal depravación entre ustedes.'),
('nvi', 'Levítico 20:15', 'Levítico', 20, 15, '»Si alguien tiene trato sexual con un animal, será condenado a muerte, y se matará también al animal.'),
('nvi', 'Levítico 20:16', 'Levítico', 20, 16, '»Si una mujer tiene trato sexual con un animal, se les dará muerte a ambos, y ellos serán responsables de su muerte.'),
('nvi', 'Levítico 20:17', 'Levítico', 20, 17, '»Si alguien tiene relaciones sexuales con una hermana suya, comete un acto vergonzoso y los dos serán ejecutados en público. Ha deshonrado a su hermana, y sufrirá las consecuencias de su pecado.'),
('nvi', 'Levítico 20:18', 'Levítico', 20, 18, '»Si alguien se acuesta con una mujer y tiene relaciones sexuales con ella durante su período menstrual, pone al descubierto su flujo, y también ella expone el flujo de su sangre. Los dos serán eliminados de su pueblo.'),
('nvi', 'Levítico 20:19', 'Levítico', 20, 19, '»No tendrás relaciones sexuales ni con tu tía materna ni con tu tía paterna, pues eso significaría la deshonra de un pariente cercano y los dos sufrirían las consecuencias de su pecado.'),
('nvi', 'Levítico 20:20', 'Levítico', 20, 20, '»Si alguien se acuesta con su tía, deshonra a su tío, y los dos sufrirán las consecuencias de su pecado: morirán sin tener descendencia.'),
('nvi', 'Levítico 20:21', 'Levítico', 20, 21, '»Si alguien viola a la esposa de su hermano, comete un acto de impureza: ha deshonrado a su hermano, y los dos se quedarán sin descendencia.'),
('nvi', 'Levítico 20:22', 'Levítico', 20, 22, '»Cumplan todos mis estatutos y preceptos; pónganlos por obra, para que no los vomite la tierra adonde los llevo a vivir.'),
('nvi', 'Levítico 20:23', 'Levítico', 20, 23, 'No vivan según las costumbres de las naciones que por amor a ustedes voy a expulsar. Porque ellas hicieron todas estas cosas, y yo las aborrecí.'),
('nvi', 'Levítico 20:24', 'Levítico', 20, 24, 'Pero a ustedes les digo: “Poseerán la tierra que perteneció a esas naciones, tierra donde abundan la leche y la miel. Yo mismo se la daré a ustedes como herencia.”»Yo soy el SEÑOR su Dios, que los he distinguido entre las demás naciones.'),
('nvi', 'Levítico 20:25', 'Levítico', 20, 25, 'Por consiguiente, también ustedes deben distinguir entre los animales puros y los impuros, y entre las aves puras y las impuras. No se hagan detestables ustedes mismos por causa de animales, de aves o de cualquier alimaña que se arrastra por el suelo, pues yo se los he señalado como impuros.'),
('nvi', 'Levítico 20:26', 'Levítico', 20, 26, 'Sean ustedes santos, porque yo, el SEÑOR, soy santo, y los he distinguido entre las demás naciones, para que sean míos.'),
('nvi', 'Levítico 20:27', 'Levítico', 20, 27, '»Cualquiera de ustedes, hombre o mujer, que sea nigromante o espiritista, será condenado a muerte. Morirá apedreado, y será responsable de su propia muerte.»'),
('nvi', 'Levítico 21:1', 'Levítico', 21, 1, 'El SEÑOR le ordenó a Moisés que les dijera a los sacerdotes, hijos de Aarón: «No se contaminen tocando el cadáver de alguien de su pueblo,'),
('nvi', 'Levítico 21:2', 'Levítico', 21, 2, 'excepto en el caso de un pariente cercano, como su madre, su padre, su hijo, su hija, su hermano'),
('nvi', 'Levítico 21:3', 'Levítico', 21, 3, 'o una hermana soltera que, por no tener marido, dependa de él.'),
('nvi', 'Levítico 21:4', 'Levítico', 21, 4, 'Como jefes de su pueblo, no deben hacerse impuros ni contaminarse.'),
('nvi', 'Levítico 21:5', 'Levítico', 21, 5, '»Los sacerdotes no se raparán la cabeza, ni se despuntarán la barba ni se harán heridas en el cuerpo.'),
('nvi', 'Levítico 21:6', 'Levítico', 21, 6, 'Deben ser santos para su Dios, y no profanar su nombre. Son ellos los que presentan al SEÑOR las ofrendas por fuego, que son como el pan de su Dios. Por eso deben ser santos.'),
('nvi', 'Levítico 21:7', 'Levítico', 21, 7, '»Ningún sacerdote se casará con una prostituta, ni con una divorciada, ni con una mujer que no sea virgen, porque está consagrado a su Dios.'),
('nvi', 'Levítico 21:8', 'Levítico', 21, 8, 'Considéralo santo, porque él ofrece el pan de tu Dios. Santo será para ti, porque santo soy yo, el SEÑOR, que los santifico a ustedes.'),
('nvi', 'Levítico 21:9', 'Levítico', 21, 9, '»La hija de un sacerdote que se hace prostituta se profana a sí misma y profana a su padre. Deberá ser quemada viva.'),
('nvi', 'Levítico 21:10', 'Levítico', 21, 10, '»Aquel que sea elegido sumo sacerdote entre sus hermanos, y sobre cuya cabeza se haya derramado el aceite de la unción, y a quien se le haya conferido autoridad para llevar las vestiduras sacerdotales, no deberá andar despeinado ni rasgarse las vestiduras.'),
('nvi', 'Levítico 21:11', 'Levítico', 21, 11, '»No entrará en ningún lugar donde haya un cadáver. »No deberá contaminarse, ni siquiera por su padre o por su madre.'),
('nvi', 'Levítico 21:12', 'Levítico', 21, 12, '»No saldrá del santuario, para no profanar el santuario de su Dios, porque ha sido consagrado mediante el aceite de la unción divina. Yo soy el SEÑOR.'),
('nvi', 'Levítico 21:13', 'Levítico', 21, 13, '»La mujer que tome por esposa debe ser virgen.'),
('nvi', 'Levítico 21:14', 'Levítico', 21, 14, 'No debe casarse con una viuda, ni con una divorciada ni con una prostituta. Debe casarse con una virgen de su mismo pueblo,'),
('nvi', 'Levítico 21:15', 'Levítico', 21, 15, 'para que no profane su descendencia entre su pueblo. Yo soy el SEÑOR, que lo santifica.»'),
('nvi', 'Levítico 21:16', 'Levítico', 21, 16, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 21:17', 'Levítico', 21, 17, 'que le dijera a Aarón: «Ninguno de tus descendientes que tenga defecto físico deberá acercarse jamás a su Dios para presentarle la ofrenda de pan.'),
('nvi', 'Levítico 21:18', 'Levítico', 21, 18, 'En efecto, no deberá acercarse nadie que tenga algún defecto físico: ninguno que sea ciego, cojo, mutilado, deforme,'),
('nvi', 'Levítico 21:19', 'Levítico', 21, 19, 'lisiado de pies o manos,'),
('nvi', 'Levítico 21:20', 'Levítico', 21, 20, 'jorobado o enano; o que tenga sarna o tiña, o cataratas en los ojos, o que haya sido castrado.'),
('nvi', 'Levítico 21:21', 'Levítico', 21, 21, 'Ningún descendiente del sacerdote Aarón que tenga algún defecto podrá acercarse a presentar al SEÑOR las ofrendas por fuego. No podrá acercarse para presentarle a su Dios la ofrenda de pan por tener un defecto.'),
('nvi', 'Levítico 21:22', 'Levítico', 21, 22, 'Podrá comer de la ofrenda de pan, tanto del alimento santo como del santísimo,'),
('nvi', 'Levítico 21:23', 'Levítico', 21, 23, 'pero por causa de su defecto no pasará más allá de la cortina ni se acercará al altar, para no profanar mi santuario. Yo soy el SEÑOR, que santifico a los sacerdotes.»'),
('nvi', 'Levítico 21:24', 'Levítico', 21, 24, 'Y Moisés les comunicó todo esto a Aarón y a sus hijos, y a todos los israelitas.'),
('nvi', 'Levítico 22:1', 'Levítico', 22, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 22:2', 'Levítico', 22, 2, 'que les dijera a Aarón y a sus hijos: «Traten con mucho respeto las ofrendas sagradas que me consagran los israelitas, para no profanar mi santo nombre. Yo soy el SEÑOR.»'),
('nvi', 'Levítico 22:3', 'Levítico', 22, 3, 'También le ordenó decirles: «Si alguno de los descendientes de Aarón está ritualmente impuro y se acerca a las ofrendas que los israelitas consagran al SEÑOR, será eliminado de mi presencia. Yo soy el SEÑOR.'),
('nvi', 'Levítico 22:4', 'Levítico', 22, 4, '»Si un descendiente de Aarón padece de alguna enfermedad infecciosa en la piel, o de derrame seminal, deberá abstenerse de comer de las ofrendas sagradas, hasta que se purifique. Cualquiera que toque un objeto contaminado por el contacto con un cadáver, o que tenga derrame de semen,'),
('nvi', 'Levítico 22:5', 'Levítico', 22, 5, 'o que toque algún animal u hombre impuros, cualquiera que sea la impureza,'),
('nvi', 'Levítico 22:6', 'Levítico', 22, 6, 'quedará impuro hasta el anochecer. Por tanto, se abstendrá de comer de las ofrendas sagradas. Lavará su cuerpo con agua,'),
('nvi', 'Levítico 22:7', 'Levítico', 22, 7, 'y al ponerse el sol quedará puro. Después de esto podrá comer de las ofrendas sagradas, porque son su alimento.'),
('nvi', 'Levítico 22:8', 'Levítico', 22, 8, 'No deberá comer nada que sea hallado muerto o despedazado por las fieras, pues de lo contrario quedará impuro. Yo soy el SEÑOR.'),
('nvi', 'Levítico 22:9', 'Levítico', 22, 9, '»Los sacerdotes cumplirán con mis instrucciones, y así no pecarán ni sufrirán la muerte por haber profanado las ofrendas. Yo soy el SEÑOR, que santifico a los sacerdotes.'),
('nvi', 'Levítico 22:10', 'Levítico', 22, 10, '»Nadie ajeno a la familia sacerdotal comerá de las ofrendas sagradas, ni tampoco comerá de ellas ningún huésped del sacerdote, ni su jornalero.'),
('nvi', 'Levítico 22:11', 'Levítico', 22, 11, 'Pero sí podrá comer de ellas el esclavo comprado por un sacerdote, y el esclavo nacido en casa del mismo.'),
('nvi', 'Levítico 22:12', 'Levítico', 22, 12, 'Si la hija de un sacerdote se casa con alguien que no sea sacerdote, no podrá comer de las ofrendas recibidas como contribución.'),
('nvi', 'Levítico 22:13', 'Levítico', 22, 13, 'Pero si queda viuda o divorciada y, sin haber tenido hijos, regresa a la casa de su padre como cuando era soltera, entonces sí podrá comer del alimento de su padre. Pero nadie ajeno a la familia sacerdotal está autorizado para comerlo.'),
('nvi', 'Levítico 22:14', 'Levítico', 22, 14, '»Si inadvertidamente alguien come de una ofrenda sagrada, deberá restituir la ofrenda al sacerdote y añadirle una quinta parte de su valor.'),
('nvi', 'Levítico 22:15', 'Levítico', 22, 15, '»No deberán los sacerdotes profanar las ofrendas sagradas que los israelitas presentan al SEÑOR,'),
('nvi', 'Levítico 22:16', 'Levítico', 22, 16, 'porque al permitir que las coman harán recaer sobre sí mismos un pecado que requiere un sacrificio por la culpa. Yo soy el SEÑOR, que los santifico.»'),
('nvi', 'Levítico 22:17', 'Levítico', 22, 17, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 22:18', 'Levítico', 22, 18, 'que les dijera a Aarón y a sus hijos, y a todos los israelitas: «Si alguno de ustedes, sea israelita o extranjero residente en Israel, presenta un holocausto al SEÑOR para cumplir un voto, o como ofrenda voluntaria,'),
('nvi', 'Levítico 22:19', 'Levítico', 22, 19, 'para que le sea aceptado deberá presentar un macho sin defecto de entre el ganado vacuno, ovino o cabrío.'),
('nvi', 'Levítico 22:20', 'Levítico', 22, 20, 'No presenten ningún animal que tenga algún defecto, porque no se les aceptará.'),
('nvi', 'Levítico 22:21', 'Levítico', 22, 21, '»Si alguien, para cumplir un voto especial o como ofrenda voluntaria, le presenta al SEÑOR ganado vacuno u ovino como sacrificio de comunión, para que el animal le sea aceptado no deberá tener ningún defecto.'),
('nvi', 'Levítico 22:22', 'Levítico', 22, 22, 'No deberán presentarle al SEÑOR, como ofrenda por fuego, animales ciegos, cojos, mutilados, llagados, sarnosos ni tiñosos. No ofrecerán en el altar ningún animal así.'),
('nvi', 'Levítico 22:23', 'Levítico', 22, 23, 'Podrán presentar como ofrenda voluntaria una res o una oveja deforme o enana, pero tal ofrenda no será aceptada en cumplimiento de un voto.'),
('nvi', 'Levítico 22:24', 'Levítico', 22, 24, '»No ofrecerán al SEÑOR ningún animal con los testículos lastimados, magullados, cortados o arrancados. No harán esto en su tierra.'),
('nvi', 'Levítico 22:25', 'Levítico', 22, 25, 'No recibirán de manos de un extranjero animales así, para ofrecerlos como alimento del Dios de ustedes. No se les aceptarán porque son deformes y tienen defectos.»'),
('nvi', 'Levítico 22:26', 'Levítico', 22, 26, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 22:27', 'Levítico', 22, 27, '«Cuando nazca un ternero, un cordero o un cabrito, se quedará con su madre durante siete días. Del octavo día en adelante será aceptable al SEÑOR como ofrenda por fuego.'),
('nvi', 'Levítico 22:28', 'Levítico', 22, 28, '»No degollarán el mismo día una vaca o una oveja con su cría.'),
('nvi', 'Levítico 22:29', 'Levítico', 22, 29, '»Cuando sacrifiquen una ofrenda de acción de gracias al SEÑOR, háganlo de tal modo que les sea aceptada.'),
('nvi', 'Levítico 22:30', 'Levítico', 22, 30, 'Deberá comerse ese mismo día, sin dejar nada para el siguiente. Yo soy el SEÑOR.'),
('nvi', 'Levítico 22:31', 'Levítico', 22, 31, '»Obedezcan mis mandamientos y pónganlos por obra. Yo soy el SEÑOR.'),
('nvi', 'Levítico 22:32', 'Levítico', 22, 32, '»No profanen mi santo nombre sino reconózcanme como santo en medio de los israelitas. Yo soy el SEÑOR, que los santifica.'),
('nvi', 'Levítico 22:33', 'Levítico', 22, 33, 'Yo los saqué de Egipto para ser su Dios. Yo soy el SEÑOR.»'),
('nvi', 'Levítico 23:1', 'Levítico', 23, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 23:2', 'Levítico', 23, 2, 'que les dijera a los israelitas: «Éstas son las fiestas que yo he establecido, y a las que ustedes han de convocar como fiestas solemnes en mi honor. Yo, el SEÑOR, las establecí.'),
('nvi', 'Levítico 23:3', 'Levítico', 23, 3, '»Trabajarán ustedes durante seis días, pero el séptimo día es de reposo, es un día de fiesta solemne en mi honor, en el que no harán ningún trabajo. Dondequiera que ustedes vivan, será sábado consagrado al SEÑOR.'),
('nvi', 'Levítico 23:4', 'Levítico', 23, 4, '»Éstas son las fiestas que el SEÑOR ha establecido, las fiestas solemnes en su honor que ustedes deberán convocar en las fechas señaladas para ellas:'),
('nvi', 'Levítico 23:5', 'Levítico', 23, 5, '»La Pascua del SEÑOR comienza el día catorce del mes primero, a la hora del crepúsculo.'),
('nvi', 'Levítico 23:6', 'Levítico', 23, 6, 'El día quince del mismo mes comienza la fiesta de los Panes sin levadura en honor al SEÑOR. Durante siete días comerán pan sin levadura.'),
('nvi', 'Levítico 23:7', 'Levítico', 23, 7, 'El primer día celebrarán una fiesta solemne en su honor; ese día no harán ningún trabajo.'),
('nvi', 'Levítico 23:8', 'Levítico', 23, 8, 'Durante siete días presentarán al SEÑOR ofrendas por fuego, y el séptimo día celebrarán una fiesta solemne en su honor; ese día no harán ningún trabajo.»'),
('nvi', 'Levítico 23:9', 'Levítico', 23, 9, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 23:10', 'Levítico', 23, 10, 'que les dijera a los israelitas: «Cuando ustedes hayan entrado en la tierra que les voy a dar, y sieguen la mies, deberán llevar al sacerdote una gavilla de las primeras espigas que cosechen.'),
('nvi', 'Levítico 23:11', 'Levítico', 23, 11, 'El sacerdote mecerá la gavilla ante el SEÑOR para que les sea aceptada. La mecerá a la mañana siguiente del sábado.'),
('nvi', 'Levítico 23:12', 'Levítico', 23, 12, 'Ese mismo día sacrificarán ustedes un cordero de un año, sin defecto, como holocausto al SEÑOR.'),
('nvi', 'Levítico 23:13', 'Levítico', 23, 13, 'También presentarán cuatro kilos de harina fina mezclada con aceite, como ofrenda de cereal, ofrenda por fuego, de aroma grato al SEÑOR, y un litro de vino como ofrenda de libación.'),
('nvi', 'Levítico 23:14', 'Levítico', 23, 14, 'No comerán pan, ni grano tostado o nuevo, hasta el día en que traigan esta ofrenda a su Dios. Éste será un estatuto perpetuo para todos tus descendientes, dondequiera que habiten.'),
('nvi', 'Levítico 23:15', 'Levítico', 23, 15, '»A partir del día siguiente al sábado, es decir, a partir del día en que traigan la gavilla de la ofrenda mecida, contarán siete semanas completas.'),
('nvi', 'Levítico 23:16', 'Levítico', 23, 16, 'En otras palabras, contarán cincuenta días incluyendo la mañana siguiente al séptimo sábado; entonces presentarán al SEÑOR una ofrenda de grano nuevo.'),
('nvi', 'Levítico 23:17', 'Levítico', 23, 17, 'Desde su lugar de residencia le llevarán al SEÑOR, como ofrenda mecida de las primicias, dos panes hechos con cuatro kilos de flor de harina, cocidos con levadura.'),
('nvi', 'Levítico 23:18', 'Levítico', 23, 18, 'Junto con el pan deberán presentar siete corderos de un año, sin defecto, un novillo y dos carneros. Serán, junto con sus ofrendas de cereal y sus ofrendas de libación, un holocausto al SEÑOR, una ofrenda presentada por fuego, de aroma grato al SEÑOR.'),
('nvi', 'Levítico 23:19', 'Levítico', 23, 19, 'Luego sacrificarán un macho cabrío como ofrenda por el pecado, y dos corderos de un año como sacrificio de comunión.'),
('nvi', 'Levítico 23:20', 'Levítico', 23, 20, 'El sacerdote mecerá los dos corderos, junto con el pan de las primicias. Son una ofrenda mecida ante el SEÑOR, una ofrenda consagrada al SEÑOR y reservada para el sacerdote.'),
('nvi', 'Levítico 23:21', 'Levítico', 23, 21, 'Ese mismo día convocarán ustedes a una fiesta solemne en honor al SEÑOR, y en ese día no harán ningún trabajo. Éste será un estatuto perpetuo para todos tus descendientes, dondequiera que habiten.'),
('nvi', 'Levítico 23:22', 'Levítico', 23, 22, '»Cuando llegue el tiempo de la cosecha, no sieguen hasta el último rincón del campo ni recojan todas las espigas que queden de la mies. Déjenlas para los pobres y los extranjeros. Yo soy el SEÑOR su Dios.»'),
('nvi', 'Levítico 23:23', 'Levítico', 23, 23, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 23:24', 'Levítico', 23, 24, 'que les dijera a los israelitas: «El primer día del mes séptimo será para ustedes un día de reposo, una conmemoración con toques de trompeta, una fiesta solemne en honor al SEÑOR.'),
('nvi', 'Levítico 23:25', 'Levítico', 23, 25, 'Ese día no harán ningún trabajo, sino que presentarán al SEÑOR ofrendas por fuego.»'),
('nvi', 'Levítico 23:26', 'Levítico', 23, 26, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 23:27', 'Levítico', 23, 27, '«El día diez del mes séptimo es el día del Perdón. Celebrarán una fiesta solemne en honor al SEÑOR, y ayunarán y le presentarán ofrendas por fuego.'),
('nvi', 'Levítico 23:28', 'Levítico', 23, 28, 'En ese día no harán ningún tipo de trabajo, porque es el día del Perdón, cuando se hace expiación por ustedes ante el SEÑOR su Dios.'),
('nvi', 'Levítico 23:29', 'Levítico', 23, 29, 'Cualquiera que no observe el ayuno será eliminado de su pueblo.'),
('nvi', 'Levítico 23:30', 'Levítico', 23, 30, 'Si alguien hace algún trabajo en ese día, yo mismo lo eliminaré de su pueblo.'),
('nvi', 'Levítico 23:31', 'Levítico', 23, 31, 'Por tanto, no harán ustedes ningún trabajo. Éste será un estatuto perpetuo para todos sus descendientes, dondequiera que habiten.'),
('nvi', 'Levítico 23:32', 'Levítico', 23, 32, 'Será para ustedes un sábado de solemne reposo, y deberán observar el ayuno. Este sábado lo observarán desde la tarde del día nueve del mes hasta la tarde siguiente.»'),
('nvi', 'Levítico 23:33', 'Levítico', 23, 33, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 23:34', 'Levítico', 23, 34, 'que les dijera a los israelitas: «El día quince del mes séptimo comienza la fiesta de las Enramadas en honor al SEÑOR, la cual durará siete días.'),
('nvi', 'Levítico 23:35', 'Levítico', 23, 35, 'El primer día se celebrará una fiesta solemne en honor al SEÑOR. Ese día no harán ningún trabajo.'),
('nvi', 'Levítico 23:36', 'Levítico', 23, 36, 'Durante siete días le presentarán al SEÑOR ofrendas por fuego. Al octavo día celebrarán una fiesta solemne en honor al SEÑOR y volverán a presentarle ofrendas por fuego. Es una fiesta solemne; ese día no harán ningún trabajo.'),
('nvi', 'Levítico 23:37', 'Levítico', 23, 37, '»Éstas son las fiestas que el SEÑOR ha establecido, y a las que ustedes habrán de convocar como fiestas solemnes en su honor, para presentarle ofrendas por fuego, holocaustos, ofrendas de cereal, y sacrificios y ofrendas de libación, tal como está prescrito para cada día.'),
('nvi', 'Levítico 23:38', 'Levítico', 23, 38, 'Todas estas fiestas son adicionales a los sábados del SEÑOR y a los tributos y ofrendas votivas o voluntarias que ustedes le presenten.'),
('nvi', 'Levítico 23:39', 'Levítico', 23, 39, '»A partir del día quince del mes séptimo, luego de que hayan recogido los frutos de la tierra, celebrarán durante siete días la fiesta del SEÑOR. El primer día y el octavo serán de descanso especial.'),
('nvi', 'Levítico 23:40', 'Levítico', 23, 40, 'El primer día tomarán frutos de los mejores árboles, ramas de palmera, de árboles frondosos y de sauces de los arroyos, y durante siete días se regocijarán en presencia del SEÑOR su Dios.'),
('nvi', 'Levítico 23:41', 'Levítico', 23, 41, 'Cada año, durante siete días, celebrarán esta fiesta en honor al SEÑOR. La celebrarán en el mes séptimo. Éste será un estatuto perpetuo para las generaciones venideras.'),
('nvi', 'Levítico 23:42', 'Levítico', 23, 42, 'Durante siete días vivirán bajo enramadas. Todos los israelitas nativos vivirán bajo enramadas,'),
('nvi', 'Levítico 23:43', 'Levítico', 23, 43, 'para que sus descendientes sepan que yo hice vivir así a los israelitas cuando los saqué de Egipto. Yo soy el SEÑOR su Dios.»'),
('nvi', 'Levítico 23:44', 'Levítico', 23, 44, 'Así anunció Moisés a los israelitas las fiestas establecidas por el SEÑOR.'),
('nvi', 'Levítico 24:1', 'Levítico', 24, 1, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 24:2', 'Levítico', 24, 2, '«Manda a los israelitas que te traigan aceite puro de olivas prensadas, para la iluminación del santuario. Así las lámparas se mantendrán siempre encendidas.'),
('nvi', 'Levítico 24:3', 'Levítico', 24, 3, 'Aarón preparará las lámparas en la Tienda de reunión, fuera de la cortina del pacto, para que ardan delante del SEÑOR toda la noche. Éste será un estatuto perpetuo para las generaciones venideras.'),
('nvi', 'Levítico 24:4', 'Levítico', 24, 4, 'Las lámparas que están sobre el candelabro de oro puro se mantendrán siempre encendidas delante del SEÑOR.'),
('nvi', 'Levítico 24:5', 'Levítico', 24, 5, '»Toma flor de harina y hornea doce tortas de pan. Cada torta debe pesar cuatro kilos.'),
('nvi', 'Levítico 24:6', 'Levítico', 24, 6, 'Ponlas ante el SEÑOR sobre la mesa de oro puro, en dos hileras de seis tortas cada una.'),
('nvi', 'Levítico 24:7', 'Levítico', 24, 7, 'En cada hilera pondrás incienso puro. Así el pan será una ofrenda memorial presentada por fuego al SEÑOR.'),
('nvi', 'Levítico 24:8', 'Levítico', 24, 8, 'Este pan se dispondrá regularmente ante el SEÑOR todos los sábados. Éste es un pacto perpetuo de los israelitas.'),
('nvi', 'Levítico 24:9', 'Levítico', 24, 9, 'El pan les pertenece a Aarón y a sus hijos, quienes lo comerán en un lugar santo. Es una parte sumamente sagrada de las ofrendas que se presentan por fuego al SEÑOR. Es un estatuto perpetuo.»'),
('nvi', 'Levítico 24:10', 'Levítico', 24, 10, 'Entre los israelitas vivía un hombre, hijo de madre israelita y de padre egipcio. Y sucedió que un día este hombre y un israelita iniciaron un pleito en el campamento.'),
('nvi', 'Levítico 24:11', 'Levítico', 24, 11, 'Pero el hijo de la mujer israelita, al lanzar una maldición, pronunció el nombre del SEÑOR; así que se lo llevaron a Moisés. (El nombre de su madre era Selomit hija de Dibrí, de la tribu de Dan.)'),
('nvi', 'Levítico 24:12', 'Levítico', 24, 12, 'Y lo pusieron bajo arresto hasta que el SEÑOR les dijera qué hacer con él.'),
('nvi', 'Levítico 24:13', 'Levítico', 24, 13, 'Entonces el SEÑOR le dijo a Moisés:'),
('nvi', 'Levítico 24:14', 'Levítico', 24, 14, '«Saca al blasfemo fuera del campamento. Quienes lo hayan oído impondrán las manos sobre su cabeza, y toda la asamblea lo apedreará.'),
('nvi', 'Levítico 24:15', 'Levítico', 24, 15, 'Diles a los israelitas: “Todo el que blasfeme contra su Dios sufrirá las consecuencias de su pecado.”'),
('nvi', 'Levítico 24:16', 'Levítico', 24, 16, 'Además, todo el que pronuncie el nombre del SEÑOR al maldecir a su prójimo será condenado a muerte. Toda la asamblea lo apedreará. Sea extranjero o nativo, si pronuncia el nombre del SEÑOR al maldecir a su prójimo, será condenado a muerte.'),
('nvi', 'Levítico 24:17', 'Levítico', 24, 17, '»El que le quite la vida a otro ser humano será condenado a muerte.'),
('nvi', 'Levítico 24:18', 'Levítico', 24, 18, '»El que le quite la vida a algún animal ajeno, reparará el daño con otro animal.'),
('nvi', 'Levítico 24:19', 'Levítico', 24, 19, '»Al que lesione a su prójimo se le infligirá el mismo daño que haya causado:'),
('nvi', 'Levítico 24:20', 'Levítico', 24, 20, 'fractura por fractura, ojo por ojo, diente por diente. Sufrirá en carne propia el mismo daño que haya causado.'),
('nvi', 'Levítico 24:21', 'Levítico', 24, 21, '»Todo el que mate un animal reparará el daño, pero el que mate a un hombre será condenado a muerte.'),
('nvi', 'Levítico 24:22', 'Levítico', 24, 22, 'Una sola ley regirá, tanto para el nativo como para el extranjero. Yo soy el SEÑOR su Dios.»'),
('nvi', 'Levítico 24:23', 'Levítico', 24, 23, 'Moisés les comunicó todo esto a los israelitas, y ellos sacaron al blasfemo fuera del campamento, y allí lo apedrearon. Los israelitas procedieron tal como el SEÑOR se lo ordenó a Moisés.'),
('nvi', 'Levítico 25:1', 'Levítico', 25, 1, 'En el monte Sinaí el SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 25:2', 'Levítico', 25, 2, 'que les dijera a los israelitas: «Cuando ustedes hayan entrado en la tierra que les voy a dar, la tierra misma deberá observar un año de reposo en honor al SEÑOR.'),
('nvi', 'Levítico 25:3', 'Levítico', 25, 3, 'Durante seis años sembrarás tus campos, podarás tus viñas y cosecharás sus productos;'),
('nvi', 'Levítico 25:4', 'Levítico', 25, 4, 'pero llegado el séptimo año la tierra gozará de un año de reposo en honor al SEÑOR. No sembrarás tus campos ni podarás tus viñas;'),
('nvi', 'Levítico 25:5', 'Levítico', 25, 5, 'no segarás lo que haya brotado por sí mismo ni vendimiarás las uvas de tus viñas no cultivadas. La tierra gozará de un año completo de reposo.'),
('nvi', 'Levítico 25:6', 'Levítico', 25, 6, 'Sin embargo, de todo lo que la tierra produzca durante ese año sabático, podrán comer no sólo tú sino también tu siervo y tu sierva, el jornalero y el residente transitorio entre ustedes.'),
('nvi', 'Levítico 25:7', 'Levítico', 25, 7, 'También podrán alimentarse tu ganado y los animales que haya en el país. Todo lo que la tierra produzca ese año será sólo para el consumo diario.'),
('nvi', 'Levítico 25:8', 'Levítico', 25, 8, '»Siete veces contarás siete años sabáticos, de modo que los siete años sabáticos sumen cuarenta y nueve años,'),
('nvi', 'Levítico 25:9', 'Levítico', 25, 9, 'y el día diez del mes séptimo, es decir, el día del Perdón, harás resonar la trompeta por todo el país.'),
('nvi', 'Levítico 25:10', 'Levítico', 25, 10, 'El año cincuenta será declarado santo, y se proclamará en el país la liberación de todos sus habitantes. Será para ustedes un jubileo, y cada uno volverá a su heredad familiar y a su propio clan.'),
('nvi', 'Levítico 25:11', 'Levítico', 25, 11, 'El año cincuenta será para ustedes un jubileo: ese año no sembrarán ni cosecharán lo que haya brotado por sí mismo, ni tampoco vendimiarán las viñas no cultivadas.'),
('nvi', 'Levítico 25:12', 'Levítico', 25, 12, 'Ese año es jubileo y será santo para ustedes. Comerán solamente lo que los campos produzcan por sí mismos.'),
('nvi', 'Levítico 25:13', 'Levítico', 25, 13, '»En el año de jubileo cada uno volverá a su heredad familiar.'),
('nvi', 'Levítico 25:14', 'Levítico', 25, 14, '»Si entre ustedes se realizan transacciones de compraventa, no se exploten los unos a los otros.'),
('nvi', 'Levítico 25:15', 'Levítico', 25, 15, 'Tú comprarás de tu prójimo a un precio proporcional al número de años que falten para el próximo jubileo, y él te venderá a un precio proporcional al número de años que queden por cosechar.'),
('nvi', 'Levítico 25:16', 'Levítico', 25, 16, 'Si aún faltan muchos años para el jubileo, aumentarás el precio en la misma proporción; pero si faltan pocos, rebajarás el precio proporcionalmente, porque lo que se te está vendiendo es sólo el número de cosechas.'),
('nvi', 'Levítico 25:17', 'Levítico', 25, 17, 'No se explotarán los unos a los otros, sino que temerán a su Dios. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 25:18', 'Levítico', 25, 18, '»Pongan en práctica mis estatutos y observen mis preceptos, y habitarán seguros en la tierra.'),
('nvi', 'Levítico 25:19', 'Levítico', 25, 19, 'La tierra dará su fruto, y comerán hasta saciarse, y allí vivirán seguros.'),
('nvi', 'Levítico 25:20', 'Levítico', 25, 20, '»Si acaso se preguntan: “¿Qué comeremos en el séptimo año, si no plantamos ni cosechamos nuestros productos?”,'),
('nvi', 'Levítico 25:21', 'Levítico', 25, 21, 'déjenme decirles que en el sexto año les enviaré una bendición tan grande que la tierra producirá como para tres años.'),
('nvi', 'Levítico 25:22', 'Levítico', 25, 22, 'Cuando ustedes siembren durante el octavo año, todavía estarán comiendo de la cosecha anterior, y continuarán comiendo de ella hasta la cosecha del año siguiente.'),
('nvi', 'Levítico 25:23', 'Levítico', 25, 23, '»La tierra no se venderá a perpetuidad, porque la tierra es mía y ustedes no son aquí más que forasteros y huéspedes.'),
('nvi', 'Levítico 25:24', 'Levítico', 25, 24, 'Por tanto, en el país habrá la posibilidad de recobrar todo terreno que haya sido heredad familiar.'),
('nvi', 'Levítico 25:25', 'Levítico', 25, 25, '»En el caso de que uno de tus compatriotas se empobrezca y tenga que vender parte de su heredad familiar, su pariente más cercano rescatará lo que su hermano haya vendido.'),
('nvi', 'Levítico 25:26', 'Levítico', 25, 26, 'Si el hombre no tiene a nadie que pague el rescate a su favor, pero él mismo llega a prosperar y consigue lo suficiente para rescatar su propiedad,'),
('nvi', 'Levítico 25:27', 'Levítico', 25, 27, 'deberá calcular el número de años transcurridos desde la venta y reembolsar el saldo a quien se la haya comprado. Así podrá volver a su propiedad.'),
('nvi', 'Levítico 25:28', 'Levítico', 25, 28, 'Pero si no consigue lo suficiente para rescatarla, la tierra quedará en posesión del comprador hasta el año del jubileo, cuando el que la vendió la recobrará, y ésta volverá a su heredad familiar.'),
('nvi', 'Levítico 25:29', 'Levítico', 25, 29, '»Si alguno vende una casa en una ciudad amurallada, tendrá derecho a rescatarla durante un año completo a partir de la fecha de venta. Ése es el tiempo que dura su derecho a rescatarla.'),
('nvi', 'Levítico 25:30', 'Levítico', 25, 30, 'Si no rescata la casa antes de cumplirse el año, no se le devolverá en el jubileo sino que pasará a ser propiedad perpetua del comprador y de sus descendientes.'),
('nvi', 'Levítico 25:31', 'Levítico', 25, 31, '»Las casas que estén en aldeas sin murallas se considerarán campo abierto, pero podrán rescatarse y se devolverán en el jubileo.'),
('nvi', 'Levítico 25:32', 'Levítico', 25, 32, '»Los levitas tendrán siempre el derecho de rescatar sus casas en las ciudades de su propiedad.'),
('nvi', 'Levítico 25:33', 'Levítico', 25, 33, 'Si alguno de los levitas hace valer su derecho, la casa que vendió en una de sus ciudades se le devolverá en el jubileo, porque las casas en las ciudades de los levitas son su heredad familiar entre los israelitas.'),
('nvi', 'Levítico 25:34', 'Levítico', 25, 34, 'Pero los campos alrededor de sus ciudades no se venderán, pues son su propiedad inalienable.'),
('nvi', 'Levítico 25:35', 'Levítico', 25, 35, '»Si alguno de tus compatriotas se empobrece y no tiene cómo sostenerse, ayúdale como lo harías con el extranjero o con el residente transitorio; así podrá seguir viviendo entre ustedes.'),
('nvi', 'Levítico 25:36', 'Levítico', 25, 36, 'No le exigirás interés cuando le prestes dinero o víveres, sino que temerás a tu Dios; así tu compatriota podrá seguir viviendo entre ustedes.'),
('nvi', 'Levítico 25:37', 'Levítico', 25, 37, 'Tampoco le prestarás dinero con intereses ni le impondrás recargo a los víveres que le fíes.'),
('nvi', 'Levítico 25:38', 'Levítico', 25, 38, 'Yo soy el SEÑOR su Dios, que los saqué de Egipto para darles la tierra de Canaán y para ser su Dios.'),
('nvi', 'Levítico 25:39', 'Levítico', 25, 39, '»Si alguno de tus compatriotas se empobrece y se ve obligado a venderse a ti, no lo hagas trabajar como esclavo.'),
('nvi', 'Levítico 25:40', 'Levítico', 25, 40, 'Trátalo como al jornalero o como al residente transitorio que vive entre ustedes. Trabajará para ti, sólo hasta el año del jubileo.'),
('nvi', 'Levítico 25:41', 'Levítico', 25, 41, 'Entonces lo pondrás en libertad junto con sus hijos, y podrán volver a su propia familia y a la heredad de sus antepasados.'),
('nvi', 'Levítico 25:42', 'Levítico', 25, 42, 'Todos los israelitas son mis siervos. Yo los saqué de Egipto, así que no serán vendidos como esclavos.'),
('nvi', 'Levítico 25:43', 'Levítico', 25, 43, 'No serás un amo cruel, sino que temerás a tu Dios.'),
('nvi', 'Levítico 25:44', 'Levítico', 25, 44, '»Asegúrate de que tus esclavos y esclavas provengan de las naciones vecinas; allí podrás comprarlos.'),
('nvi', 'Levítico 25:45', 'Levítico', 25, 45, 'También podrás comprar esclavos nacidos en tu país, siempre y cuando sean de las familias extranjeras que vivan en medio de ustedes. Ellos serán propiedad de ustedes,'),
('nvi', 'Levítico 25:46', 'Levítico', 25, 46, 'y podrán dejárselos a sus hijos como herencia para que les sirvan de por vida. En lo que respecta a tus compatriotas, no serás un amo cruel.'),
('nvi', 'Levítico 25:47', 'Levítico', 25, 47, '»Si un extranjero o un residente transitorio entre ustedes se enriquece, y uno de tus compatriotas se empobrece y tiene que venderse a un extranjero o a un familiar de ese extranjero,'),
('nvi', 'Levítico 25:48', 'Levítico', 25, 48, 'no perderá su derecho a ser rescatado después de haberse vendido. Podrá rescatarlo cualquiera de sus parientes:'),
('nvi', 'Levítico 25:49', 'Levítico', 25, 49, 'un tío, un primo o cualquier otro de sus parientes. Y si llegara a prosperar, él mismo podrá pagar su rescate.'),
('nvi', 'Levítico 25:50', 'Levítico', 25, 50, 'Él y su dueño calcularán el tiempo transcurrido, desde el año en que se vendió hasta el año del jubileo. El precio de su liberación se determinará en proporción al sueldo de un jornalero por ese número de años.'),
('nvi', 'Levítico 25:51', 'Levítico', 25, 51, 'Si aún faltan muchos años, pagará por su rescate una suma proporcional a la que se pagó por él.'),
('nvi', 'Levítico 25:52', 'Levítico', 25, 52, 'Si sólo faltan pocos años para el jubileo, calculará y pagará por su rescate en proporción a esos años.'),
('nvi', 'Levítico 25:53', 'Levítico', 25, 53, 'Ustedes vigilarán que su dueño lo trate como a los que trabajan por contrato anual, y que no lo trate con crueldad.'),
('nvi', 'Levítico 25:54', 'Levítico', 25, 54, '»Si tu compatriota no es rescatado por ninguno de esos medios, tanto él como sus hijos quedarán en libertad en el año del jubileo.'),
('nvi', 'Levítico 25:55', 'Levítico', 25, 55, '»Los israelitas son mis siervos. Yo los saqué de Egipto. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 26:1', 'Levítico', 26, 1, '»No se hagan ídolos, ni levanten imágenes ni piedras sagradas. No coloquen en su territorio piedras esculpidas ni se inclinen ante ellas. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 26:2', 'Levítico', 26, 2, '»Observen mis sábados y muestren reverencia por mi santuario. Yo soy el SEÑOR.'),
('nvi', 'Levítico 26:3', 'Levítico', 26, 3, '»Si se conducen según mis estatutos, y obedecen fielmente mis mandamientos,'),
('nvi', 'Levítico 26:4', 'Levítico', 26, 4, 'yo les enviaré lluvia a su tiempo, y la tierra y los árboles del campo darán sus frutos;'),
('nvi', 'Levítico 26:5', 'Levítico', 26, 5, 'la trilla durará hasta la vendimia, y la vendimia durará hasta la siembra. Comerán hasta saciarse y vivirán seguros en su tierra.'),
('nvi', 'Levítico 26:6', 'Levítico', 26, 6, '»Yo traeré paz al país, y ustedes podrán dormir sin ningún temor. Quitaré de la tierra las bestias salvajes, y no habrá guerra en su territorio.'),
('nvi', 'Levítico 26:7', 'Levítico', 26, 7, 'Perseguirán a sus enemigos, y ante ustedes caerán a filo de espada.'),
('nvi', 'Levítico 26:8', 'Levítico', 26, 8, 'Cinco de ustedes perseguirán a cien, y cien de ustedes perseguirán a diez mil, y ante ustedes sus enemigos caerán a filo de espada.'),
('nvi', 'Levítico 26:9', 'Levítico', 26, 9, '»Yo les mostraré mi favor. Yo los haré fecundos. Los multiplicaré, y mantendré mi pacto con ustedes.'),
('nvi', 'Levítico 26:10', 'Levítico', 26, 10, 'Todavía estarán comiendo de la cosecha del año anterior cuando tendrán que sacarla para dar lugar a la nueva.'),
('nvi', 'Levítico 26:11', 'Levítico', 26, 11, 'Estableceré mi morada en medio de ustedes, y no los aborreceré.'),
('nvi', 'Levítico 26:12', 'Levítico', 26, 12, 'Caminaré entre ustedes. Yo seré su Dios, y ustedes serán mi pueblo.'),
('nvi', 'Levítico 26:13', 'Levítico', 26, 13, 'Yo soy el SEÑOR su Dios, que los saqué de Egipto para que dejaran de ser esclavos. Yo rompí las coyundas de su yugo y los hice caminar con la cabeza erguida.'),
('nvi', 'Levítico 26:14', 'Levítico', 26, 14, '»Si ustedes no me obedecen ni ponen por obra todos estos mandamientos,'),
('nvi', 'Levítico 26:15', 'Levítico', 26, 15, 'sino que desprecian mis estatutos y aborrecen mis preceptos, y dejan de poner por obra todos mis mandamientos, violando así mi pacto,'),
('nvi', 'Levítico 26:16', 'Levítico', 26, 16, 'entonces yo mismo los castigaré con un terror repentino, con enfermedades y con fiebre que los debilitarán, les harán perder la vista y acabarán con su vida. En vano sembrarán su semilla, porque se la comerán sus enemigos.'),
('nvi', 'Levítico 26:17', 'Levítico', 26, 17, 'Yo les negaré mi favor, y sus adversarios los derrotarán. Sus enemigos los dominarán, y ustedes huirán sin que nadie los persiga.'),
('nvi', 'Levítico 26:18', 'Levítico', 26, 18, '»Si después de todo esto siguen sin obedecerme, siete veces los castigaré por sus pecados.'),
('nvi', 'Levítico 26:19', 'Levítico', 26, 19, 'Yo quebrantaré su orgullo y terquedad. Endureceré el cielo como el hierro y la tierra como el bronce,'),
('nvi', 'Levítico 26:20', 'Levítico', 26, 20, 'por lo que en vano agotarán sus fuerzas, y ni el suelo ni los árboles del campo les darán sus frutos.'),
('nvi', 'Levítico 26:21', 'Levítico', 26, 21, '»Si a pesar de esto siguen oponiéndose a mí, y se niegan a obedecerme, siete veces los castigaré por sus pecados.'),
('nvi', 'Levítico 26:22', 'Levítico', 26, 22, 'Lanzaré sobre ustedes fieras salvajes, que les arrebatarán sus hijos y destruirán su ganado. De tal manera los diezmarán, que sus caminos quedarán desiertos.'),
('nvi', 'Levítico 26:23', 'Levítico', 26, 23, '»Si a pesar de todo esto no aceptan mi disciplina, sino que continúan oponiéndose a mí,'),
('nvi', 'Levítico 26:24', 'Levítico', 26, 24, 'yo también seguiré oponiéndome a ustedes. Yo mismo los heriré siete veces por sus pecados.'),
('nvi', 'Levítico 26:25', 'Levítico', 26, 25, 'Dejaré caer sobre ustedes la espada de la venganza prescrita en el pacto. Cuando se retiren a sus ciudades, les enviaré una plaga, y caerán en poder del enemigo.'),
('nvi', 'Levítico 26:26', 'Levítico', 26, 26, 'Cuando yo destruya sus trigales, diez mujeres hornearán para ustedes pan en un solo horno. Y lo distribuirán racionado, de tal manera que comerán pero no se saciarán.'),
('nvi', 'Levítico 26:27', 'Levítico', 26, 27, '»Si a pesar de esto todavía no me obedecen, sino que continúan oponiéndose a mí,'),
('nvi', 'Levítico 26:28', 'Levítico', 26, 28, 'entonces yo también me pondré definitivamente en su contra. Siete veces los castigaré por sus pecados,'),
('nvi', 'Levítico 26:29', 'Levítico', 26, 29, 'y tendrán que comerse la carne de sus hijos y de sus hijas.'),
('nvi', 'Levítico 26:30', 'Levítico', 26, 30, 'Destruiré sus santuarios paganos, demoleré sus altares de incienso, y amontonaré sus cadáveres sobre las figuras sin vida de sus ídolos. Volcaré mi odio sobre ustedes;'),
('nvi', 'Levítico 26:31', 'Levítico', 26, 31, 'convertiré en ruinas sus ciudades, y asolaré sus santuarios. No me complaceré más en el aroma de sus ofrendas, que me era grato.'),
('nvi', 'Levítico 26:32', 'Levítico', 26, 32, 'De tal manera asolaré al país, que sus enemigos que vengan a ocuparlo quedarán atónitos.'),
('nvi', 'Levítico 26:33', 'Levítico', 26, 33, 'Los dispersaré entre las naciones: desenvainaré la espada, y los perseguiré hasta dejar desolada su tierra, y en ruinas sus ciudades.'),
('nvi', 'Levítico 26:34', 'Levítico', 26, 34, 'Entonces la tierra disfrutará de sus años sabáticos todo el tiempo que permanezca desolada, mientras ustedes vivan en el país de sus enemigos. Así la tierra descansará y disfrutará de sus sábados.'),
('nvi', 'Levítico 26:35', 'Levítico', 26, 35, 'Mientras la tierra esté desolada, tendrá el descanso que no tuvo durante los años sabáticos en que ustedes la habitaron.'),
('nvi', 'Levítico 26:36', 'Levítico', 26, 36, '»En cuanto a los que sobrevivan, tan profundo será el temor que les infundiré en tierra de sus enemigos, que hasta el susurro de una hoja movida por el viento los pondrá en fuga. Correrán como quien huye de la espada, y caerán sin que nadie los persiga.'),
('nvi', 'Levítico 26:37', 'Levítico', 26, 37, 'Como si huyeran de la espada, tropezarán unos con otros sin que nadie los persiga, y no podrán hacerles frente a sus enemigos.'),
('nvi', 'Levítico 26:38', 'Levítico', 26, 38, 'Perecerán en medio de las naciones; el país de sus enemigos los devorará.'),
('nvi', 'Levítico 26:39', 'Levítico', 26, 39, 'Aquellos de ustedes que sobrevivan serán abatidos en país enemigo, porque a sus pecados se añadirá el de sus padres.'),
('nvi', 'Levítico 26:40', 'Levítico', 26, 40, '»Pero si confiesan su maldad y la maldad de sus padres, y su traición y constante rebeldía contra mí,'),
('nvi', 'Levítico 26:41', 'Levítico', 26, 41, 'las cuales me han obligado a enviarlos al país de sus enemigos, y si su obstinado corazón se humilla y reconoce su pecado,'),
('nvi', 'Levítico 26:42', 'Levítico', 26, 42, 'entonces me acordaré de mi pacto con Jacob, Isaac y Abraham, y también me acordaré de la tierra.'),
('nvi', 'Levítico 26:43', 'Levítico', 26, 43, 'Al abandonar ellos la tierra, ésta disfrutará de sus sábados mientras permanezca deshabitada. Pero tendrán que reconocer sus pecados, por cuanto rechazaron mis preceptos y aborrecieron mis estatutos.'),
('nvi', 'Levítico 26:44', 'Levítico', 26, 44, '»A pesar de todo, y aunque estén en la tierra de sus enemigos, no los rechazaré ni los aborreceré hasta el punto de exterminarlos, ni romperé tampoco mi pacto con ellos. Yo soy el SEÑOR su Dios.'),
('nvi', 'Levítico 26:45', 'Levítico', 26, 45, 'Antes bien, recordaré en su favor el pacto que hice con sus antepasados, a quienes, a la vista de las naciones, saqué de Egipto para ser su Dios. Yo soy el SEÑOR.»'),
('nvi', 'Levítico 26:46', 'Levítico', 26, 46, 'Éstos son los estatutos, preceptos y leyes que, por medio de Moisés, estableció el SEÑOR en el monte Sinaí entre él y los israelitas.'),
('nvi', 'Levítico 27:1', 'Levítico', 27, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Levítico 27:2', 'Levítico', 27, 2, 'que les dijera a los israelitas: «Cuando alguien quiera hacerle al SEÑOR un voto especial equivalente al valor de una persona,'),
('nvi', 'Levítico 27:3', 'Levítico', 27, 3, 'se aplicará el siguiente cálculo: »Por los varones de veinte a sesenta años de edad se pagarán cincuenta monedas de plata, según la tasación oficial del santuario.'),
('nvi', 'Levítico 27:4', 'Levítico', 27, 4, '»Por las mujeres se pagarán treinta monedas de plata.'),
('nvi', 'Levítico 27:5', 'Levítico', 27, 5, '»Por los varones de cinco a veinte años de edad se pagarán veinte monedas, y diez monedas por las mujeres de la misma edad.'),
('nvi', 'Levítico 27:6', 'Levítico', 27, 6, '»Por los niños de un mes a cinco años se pagarán cinco monedas, y tres monedas por las niñas de la misma edad.'),
('nvi', 'Levítico 27:7', 'Levítico', 27, 7, '»Por los varones mayores de sesenta años se pagarán quince monedas, y diez monedas por las mujeres de la misma edad.'),
('nvi', 'Levítico 27:8', 'Levítico', 27, 8, '»Si quien hace el voto es tan pobre que ni el precio estipulado puede pagar, se le hará comparecer ante el sacerdote, el cual fijará el valor a pagar, según los recursos de quien haga el voto.'),
('nvi', 'Levítico 27:9', 'Levítico', 27, 9, '»Si lo que se presenta como ofrenda al SEÑOR es un animal, éste quedará consagrado por haber sido ofrecido al SEÑOR.'),
('nvi', 'Levítico 27:10', 'Levítico', 27, 10, 'No podrá cambiarse ni sustituirse un animal bueno por uno malo, ni un animal malo por uno bueno. Si se cambia un animal por otro, ambos quedarán consagrados.'),
('nvi', 'Levítico 27:11', 'Levítico', 27, 11, '»Si lo que se presenta como ofrenda al SEÑOR es un animal impuro, se llevará el animal ante el sacerdote,'),
('nvi', 'Levítico 27:12', 'Levítico', 27, 12, 'quien determinará el valor del animal. El cálculo aplicado por el sacerdote deberá aceptarse, cualquiera que éste sea.'),
('nvi', 'Levítico 27:13', 'Levítico', 27, 13, 'Si el dueño quiere rescatar el animal, deberá añadir una quinta parte al valor que haya fijado el sacerdote.'),
('nvi', 'Levítico 27:14', 'Levítico', 27, 14, '»Si alguno consagra su casa al SEÑOR, el sacerdote determinará su valor. El cálculo aplicado por el sacerdote deberá aceptarse, cualquiera que éste sea.'),
('nvi', 'Levítico 27:15', 'Levítico', 27, 15, 'Si el que consagró su casa quiere rescatarla, deberá añadir una quinta parte al valor que haya fijado el sacerdote, y la casa volverá a ser suya.'),
('nvi', 'Levítico 27:16', 'Levítico', 27, 16, '»Si alguno consagra al SEÑOR parte del campo de su heredad familiar, su precio se determinará según la cantidad de semilla que se requiera para sembrarlo, a razón de cincuenta monedas de plata por cada doscientos veinte litros de semilla de cebada.'),
('nvi', 'Levítico 27:17', 'Levítico', 27, 17, 'Si consagra su campo a partir del año del jubileo, dicho precio se mantendrá;'),
('nvi', 'Levítico 27:18', 'Levítico', 27, 18, 'pero si lo consagra después del jubileo, el sacerdote hará el cálculo según el número de años que falten para el próximo jubileo, con el descuento correspondiente.'),
('nvi', 'Levítico 27:19', 'Levítico', 27, 19, '»Si el que consagra su campo realmente quiere rescatarlo, deberá añadir una quinta parte al valor que haya fijado el sacerdote, y el campo volverá a ser suyo.'),
('nvi', 'Levítico 27:20', 'Levítico', 27, 20, 'Pero si no lo rescata, o se lo vende a otro, ya no podrá rescatarlo.'),
('nvi', 'Levítico 27:21', 'Levítico', 27, 21, 'Cuando en el jubileo el campo quede libre, será consagrado como campo reservado para el SEÑOR, y pasará a ser propiedad del sacerdote.'),
('nvi', 'Levítico 27:22', 'Levítico', 27, 22, '»Si alguno compra un campo que no sea parte de su heredad familiar, y lo consagra al SEÑOR,'),
('nvi', 'Levítico 27:23', 'Levítico', 27, 23, 'el sacerdote determinará su precio según el tiempo que falte para el año del jubileo. Ese mismo día, el que consagra el campo pagará el monto de su valor. Es algo consagrado al SEÑOR.'),
('nvi', 'Levítico 27:24', 'Levítico', 27, 24, 'En el año del jubileo, el campo volverá a ser parte de la heredad familiar de su dueño anterior.'),
('nvi', 'Levítico 27:25', 'Levítico', 27, 25, '»Todo precio se fijará según la tasación oficial del santuario, que es de diez gramos por moneda.'),
('nvi', 'Levítico 27:26', 'Levítico', 27, 26, '»Sin embargo, nadie podrá consagrar la primera cría de su ganado, sea de res o de oveja, pues por derecho las primeras crías le pertenecen al SEÑOR.'),
('nvi', 'Levítico 27:27', 'Levítico', 27, 27, 'Si se trata de animales impuros, se podrán rescatar pagando el valor fijado por el sacerdote, más una quinta parte. Si no se rescata, se venderá en el precio que el sacerdote haya fijado.'),
('nvi', 'Levítico 27:28', 'Levítico', 27, 28, '»Nadie podrá vender ni rescatar sus bienes, sean hombres, animales o campos, si los ha consagrado como propiedad exclusiva del SEÑOR. Todo cuanto se consagra como propiedad exclusiva del SEÑOR, es cosa santísima.'),
('nvi', 'Levítico 27:29', 'Levítico', 27, 29, 'Ninguna persona así consagrada podrá ser rescatada, sino que será condenada a muerte.'),
('nvi', 'Levítico 27:30', 'Levítico', 27, 30, '»El diezmo de todo producto del campo, ya sea grano de los sembrados o fruto de los árboles, pertenece al SEÑOR, pues le está consagrado.'),
('nvi', 'Levítico 27:31', 'Levítico', 27, 31, 'Si alguien desea rescatar algo de su diezmo, deberá añadir a su valor una quinta parte.'),
('nvi', 'Levítico 27:32', 'Levítico', 27, 32, 'En cuanto al diezmo del ganado mayor y menor, uno de cada diez animales contados será consagrado al SEÑOR.'),
('nvi', 'Levítico 27:33', 'Levítico', 27, 33, 'El pastor no hará distinción entre animales buenos y malos, ni hará sustitución alguna. En caso de cambiar un animal por otro, los dos quedarán consagrados y no se les podrá rescatar.»'),
('nvi', 'Levítico 27:34', 'Levítico', 27, 34, 'Éstos son los mandamientos que el SEÑOR le dio a Moisés para los israelitas, en el monte Sinaí.'),
('nvi', 'Números 1:1', 'Números', 1, 1, 'El SEÑOR le habló a Moisés en el desierto de Sinaí, en la Tienda de reunión, el día primero del mes segundo, en el segundo año después de que los israelitas salieron de Egipto. Le dijo:'),
('nvi', 'Números 1:2', 'Números', 1, 2, '«Hagan un censo de toda la comunidad de Israel por clanes y por familias patriarcales, anotando uno por uno los nombres de todos los varones.'),
('nvi', 'Números 1:3', 'Números', 1, 3, 'Tú y Aarón reclutarán por escuadrones a todos los varones israelitas mayores de veinte años que sean aptos para el servicio militar.'),
('nvi', 'Números 1:4', 'Números', 1, 4, 'Para esto contarán con la colaboración de un hombre de cada tribu, que sea jefe de una familia patriarcal.'),
('nvi', 'Números 1:5', 'Números', 1, 5, '»Éstos son los nombres de quienes habrán de ayudarles: por la tribu de Rubén, Elisur hijo de Sedeúr;'),
('nvi', 'Números 1:6', 'Números', 1, 6, 'por la de Simeón, Selumiel hijo de Zurisaday;'),
('nvi', 'Números 1:7', 'Números', 1, 7, 'por la de Judá, Naasón hijo de Aminadab;'),
('nvi', 'Números 1:8', 'Números', 1, 8, 'por la de Isacar, Natanael hijo de Zuar;'),
('nvi', 'Números 1:9', 'Números', 1, 9, 'por la de Zabulón, Eliab hijo de Helón;'),
('nvi', 'Números 1:10', 'Números', 1, 10, 'por las tribus de los hijos de José: Elisama hijo de Amiud por la tribu de Efraín, y Gamaliel hijo de Pedasur por la de Manasés;'),
('nvi', 'Números 1:11', 'Números', 1, 11, 'por la tribu de Benjamín, Abidán hijo de Gedeoni;'),
('nvi', 'Números 1:12', 'Números', 1, 12, 'por la de Dan, Ajiezer hijo de Amisaday;'),
('nvi', 'Números 1:13', 'Números', 1, 13, 'por la de Aser, Paguiel hijo de Ocrán;'),
('nvi', 'Números 1:14', 'Números', 1, 14, 'por la de Gad, Eliasaf hijo de Deuel;'),
('nvi', 'Números 1:15', 'Números', 1, 15, 'por la de Neftalí, Ajirá hijo de Enán.»'),
('nvi', 'Números 1:16', 'Números', 1, 16, 'A éstos la comunidad los nombró jefes de las tribus patriarcales y comandantes de los escuadrones de Israel.'),
('nvi', 'Números 1:17', 'Números', 1, 17, 'Moisés y Aarón tomaron consigo a los hombres que habían sido designados por nombre,'),
('nvi', 'Números 1:18', 'Números', 1, 18, 'y el día primero del mes segundo reunieron a toda la comunidad. Uno por uno fueron empadronados por clanes y por familias patriarcales. De este modo quedaron anotados los nombres de todos los varones mayores de veinte años,'),
('nvi', 'Números 1:19', 'Números', 1, 19, 'tal como el SEÑOR se lo había mandado a Moisés. Este censo lo hizo Moisés en el desierto de Sinaí.'),
('nvi', 'Números 1:20', 'Números', 1, 20, 'Los descendientes de Rubén, primogénito de Israel, quedaron registrados por clanes y por familias patriarcales, según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:21', 'Números', 1, 21, 'El número de la tribu de Rubén llegó a cuarenta y seis mil quinientos hombres.'),
('nvi', 'Números 1:22', 'Números', 1, 22, 'Los descendientes de Simeón quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:23', 'Números', 1, 23, 'El número de la tribu de Simeón llegó a cincuenta y nueve mil trescientos hombres.'),
('nvi', 'Números 1:24', 'Números', 1, 24, 'Los descendientes de Gad quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:25', 'Números', 1, 25, 'El número de la tribu de Gad llegó a cuarenta y cinco mil seiscientos cincuenta hombres.'),
('nvi', 'Números 1:26', 'Números', 1, 26, 'Los descendientes de Judá quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:27', 'Números', 1, 27, 'El número de la tribu de Judá llegó a setenta y cuatro mil seiscientos hombres.'),
('nvi', 'Números 1:28', 'Números', 1, 28, 'Los descendientes de Isacar quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:29', 'Números', 1, 29, 'El número de la tribu de Isacar llegó a cincuenta y cuatro mil cuatrocientos hombres.'),
('nvi', 'Números 1:30', 'Números', 1, 30, 'Los descendientes de Zabulón quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:31', 'Números', 1, 31, 'El número de la tribu de Zabulón llegó a cincuenta y siete mil cuatrocientos hombres.'),
('nvi', 'Números 1:32', 'Números', 1, 32, 'Los descendientes de José: Los descendientes de Efraín quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:33', 'Números', 1, 33, 'El número de la tribu de Efraín llegó a cuarenta mil quinientos hombres.'),
('nvi', 'Números 1:34', 'Números', 1, 34, 'Los descendientes de Manasés quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:35', 'Números', 1, 35, 'El número de la tribu de Manasés llegó a treinta y dos mil doscientos hombres.'),
('nvi', 'Números 1:36', 'Números', 1, 36, 'Los descendientes de Benjamín quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:37', 'Números', 1, 37, 'El número de la tribu de Benjamín llegó a treinta y cinco mil cuatrocientos hombres.'),
('nvi', 'Números 1:38', 'Números', 1, 38, 'Los descendientes de Dan quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:39', 'Números', 1, 39, 'El número de la tribu de Dan llegó a sesenta y dos mil setecientos hombres.'),
('nvi', 'Números 1:40', 'Números', 1, 40, 'Los descendientes de Aser quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:41', 'Números', 1, 41, 'El número de la tribu de Aser llegó a cuarenta y un mil quinientos hombres.'),
('nvi', 'Números 1:42', 'Números', 1, 42, 'Los descendientes de Neftalí quedaron registrados por clanes y por familias patriarcales según su genealogía. Uno por uno fueron empadronados todos los varones mayores de veinte años que eran aptos para el servicio militar.'),
('nvi', 'Números 1:43', 'Números', 1, 43, 'El número de la tribu de Neftalí llegó a cincuenta y tres mil cuatrocientos hombres.'),
('nvi', 'Números 1:44', 'Números', 1, 44, 'Éste es el resultado del censo que hicieron Moisés y Aarón, con la ayuda de los doce jefes de Israel, cada uno en representación de su familia patriarcal.'),
('nvi', 'Números 1:45', 'Números', 1, 45, 'Todos los israelitas mayores de veinte años que eran aptos para el servicio militar fueron anotados, según su familia patriarcal.'),
('nvi', 'Números 1:46', 'Números', 1, 46, 'El total llegó a seiscientos tres mil quinientos cincuenta israelitas censados.'),
('nvi', 'Números 1:47', 'Números', 1, 47, 'Los levitas no fueron censados con los demás,'),
('nvi', 'Números 1:48', 'Números', 1, 48, 'porque el SEÑOR le había dicho a Moisés:'),
('nvi', 'Números 1:49', 'Números', 1, 49, '«A la tribu de Leví no la incluirás en el censo de los hijos de Israel.'),
('nvi', 'Números 1:50', 'Números', 1, 50, 'Más bien, tú mismo los pondrás a cargo del santuario del pacto, de todos sus utensilios y de todo lo relacionado con él. Los levitas transportarán el santuario y todos sus utensilios. Además, serán los ministros del santuario y acamparán a su alrededor.'),
('nvi', 'Números 1:51', 'Números', 1, 51, 'Cuando haya que trasladar el santuario, los levitas se encargarán de desarmarlo; cuando haya que instalarlo, serán ellos quienes lo armen. Pero cualquiera que se acerque al santuario y no sea sacerdote, morirá.'),
('nvi', 'Números 1:52', 'Números', 1, 52, 'Todos los israelitas acamparán bajo su propio estandarte y en su propio campamento, según sus escuadrones.'),
('nvi', 'Números 1:53', 'Números', 1, 53, 'En cambio, los levitas acamparán alrededor del santuario del pacto, para evitar que Dios descargue su ira sobre la comunidad de Israel. Serán, pues, los levitas los encargados de cuidar el santuario del pacto.»'),
('nvi', 'Números 1:54', 'Números', 1, 54, 'Los israelitas hicieron todo conforme a lo que el SEÑOR le había mandado a Moisés.'),
('nvi', 'Números 2:1', 'Números', 2, 1, 'El SEÑOR les dijo a Moisés y a Aarón:'),
('nvi', 'Números 2:2', 'Números', 2, 2, '«Los israelitas acamparán alrededor de la Tienda de reunión, mirando hacia ella, cada cual bajo el estandarte de su propia familia patriarcal.'),
('nvi', 'Números 2:3', 'Números', 2, 3, '»Al este, por donde sale el sol, acamparán los que se agrupan bajo el estandarte del campamento de Judá, según sus escuadrones. Su jefe es Naasón hijo de Aminadab.'),
('nvi', 'Números 2:4', 'Números', 2, 4, 'Su ejército está integrado por setenta y cuatro mil seiscientos hombres.'),
('nvi', 'Números 2:5', 'Números', 2, 5, '»A un lado de Judá acampará la tribu de Isacar. Su jefe es Natanael hijo de Zuar.'),
('nvi', 'Números 2:6', 'Números', 2, 6, 'Su ejército está integrado por cincuenta y cuatro mil cuatrocientos hombres.'),
('nvi', 'Números 2:7', 'Números', 2, 7, '»Al otro lado acampará la tribu de Zabulón. Su jefe es Eliab hijo de Helón.'),
('nvi', 'Números 2:8', 'Números', 2, 8, 'Su ejército está integrado por cincuenta y siete mil cuatrocientos hombres.'),
('nvi', 'Números 2:9', 'Números', 2, 9, '»Todos los reclutas del campamento de Judá, según sus escuadrones, suman ciento ochenta y seis mil cuatrocientos hombres, los cuales marcharán a la cabeza.'),
('nvi', 'Números 2:10', 'Números', 2, 10, '»Al sur acamparán los que se agrupan bajo el estandarte del campamento de Rubén, según sus escuadrones. Su jefe es Elisur hijo de Sedeúr.'),
('nvi', 'Números 2:11', 'Números', 2, 11, 'Su ejército está integrado por cuarenta y seis mil quinientos hombres.'),
('nvi', 'Números 2:12', 'Números', 2, 12, '»A un lado de Rubén acampará la tribu de Simeón. Su jefe es Selumiel hijo de Zurisaday.'),
('nvi', 'Números 2:13', 'Números', 2, 13, 'Su ejército está integrado por cincuenta y nueve mil trescientos hombres.'),
('nvi', 'Números 2:14', 'Números', 2, 14, '»Al otro lado acampará la tribu de Gad. Su jefe es Eliasaf hijo de Reuel.'),
('nvi', 'Números 2:15', 'Números', 2, 15, 'Su ejército está integrado por cuarenta y cinco mil seiscientos cincuenta hombres.'),
('nvi', 'Números 2:16', 'Números', 2, 16, '»Todos los reclutas del campamento de Rubén, según sus escuadrones, suman ciento cincuenta y un mil cuatrocientos cincuenta hombres, los cuales marcharán en segundo lugar.'),
('nvi', 'Números 2:17', 'Números', 2, 17, '»Entonces se pondrá en marcha la Tienda de reunión junto con el campamento de los levitas que está situado en medio de los demás campamentos. Partirán en el mismo orden en que hayan acampado, cada uno en su lugar y bajo su estandarte.'),
('nvi', 'Números 2:18', 'Números', 2, 18, '»Al oeste acamparán los que se agrupan bajo el estandarte del campamento de Efraín, según sus escuadrones. Su jefe es Elisama hijo de Amiud.'),
('nvi', 'Números 2:19', 'Números', 2, 19, 'Su ejército está integrado por cuarenta mil quinientos hombres.'),
('nvi', 'Números 2:20', 'Números', 2, 20, '»A un lado de Efraín acampará la tribu de Manasés. Su jefe es Gamaliel hijo de Pedasur.'),
('nvi', 'Números 2:21', 'Números', 2, 21, 'Su ejército está integrado por treinta y dos mil doscientos hombres.'),
('nvi', 'Números 2:22', 'Números', 2, 22, '»Al otro lado acampará la tribu de Benjamín. Su jefe es Abidán hijo de Gedeoni.'),
('nvi', 'Números 2:23', 'Números', 2, 23, 'Su ejército está integrado por treinta y cinco mil cuatrocientos hombres.'),
('nvi', 'Números 2:24', 'Números', 2, 24, '»Todos los reclutas del campamento de Efraín, según sus escuadrones, suman ciento ocho mil cien hombres, los cuales marcharán en tercer lugar.'),
('nvi', 'Números 2:25', 'Números', 2, 25, '»Al norte, acamparán los que se agrupan bajo el estandarte del campamento de Dan, según sus escuadrones. Su jefe es Ajiezer hijo de Amisaday.'),
('nvi', 'Números 2:26', 'Números', 2, 26, 'Su ejército está integrado por sesenta y dos mil setecientos hombres.'),
('nvi', 'Números 2:27', 'Números', 2, 27, '»A un lado de Dan acampará la tribu de Aser. Su jefe es Paguiel hijo de Ocrán.'),
('nvi', 'Números 2:28', 'Números', 2, 28, 'Su escuadrón está integrado por cuarenta y un mil quinientos hombres.'),
('nvi', 'Números 2:29', 'Números', 2, 29, '»Al otro lado acampará la tribu de Neftalí. Su jefe es Ajirá hijo de Enán.'),
('nvi', 'Números 2:30', 'Números', 2, 30, 'Su escuadrón está integrado por cincuenta y tres mil cuatrocientos hombres.'),
('nvi', 'Números 2:31', 'Números', 2, 31, '»Todos los reclutas del campamento de Dan, según sus escuadrones, suman ciento cincuenta y siete mil seiscientos hombres, los cuales marcharán en último lugar, según sus estandartes.»'),
('nvi', 'Números 2:32', 'Números', 2, 32, 'Éstos son los israelitas reclutados de entre las familias patriarcales. El total de reclutas por escuadrones suma seiscientos tres mil quinientos cincuenta hombres.'),
('nvi', 'Números 2:33', 'Números', 2, 33, 'Pero los levitas no están incluidos con los demás israelitas, conforme a lo que el SEÑOR le había mandado a Moisés.'),
('nvi', 'Números 2:34', 'Números', 2, 34, 'Los israelitas hicieron todo lo que el SEÑOR le mandó a Moisés: acampaban bajo sus propios estandartes, y se ponían en marcha, según sus clanes y familias patriarcales.'),
('nvi', 'Números 3:1', 'Números', 3, 1, 'Así quedó registrada la familia de Aarón y Moisés cuando el SEÑOR habló con Moisés en el monte Sinaí.'),
('nvi', 'Números 3:2', 'Números', 3, 2, 'Los nombres de los hijos de Aarón son los siguientes: Nadab el primogénito, Abiú, Eleazar e Itamar.'),
('nvi', 'Números 3:3', 'Números', 3, 3, 'Ellos fueron los aaronitas ungidos, ordenados al sacerdocio.'),
('nvi', 'Números 3:4', 'Números', 3, 4, 'Nadab y Abiú murieron en presencia del SEÑOR cuando, en el desierto de Sinaí, le ofrecieron sacrificios con fuego profano. Como Nadab y Abiú no tuvieron hijos, sólo Eleazar e Itamar ejercieron el sacerdocio en vida de su padre Aarón.'),
('nvi', 'Números 3:5', 'Números', 3, 5, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Números 3:6', 'Números', 3, 6, '«Trae a la tribu de Leví y preséntasela a Aarón. Los levitas le ayudarán en el ministerio.'),
('nvi', 'Números 3:7', 'Números', 3, 7, 'Desempeñarán sus funciones en lugar de Aarón y de toda la comunidad, encargándose del servicio del santuario en la Tienda de reunión.'),
('nvi', 'Números 3:8', 'Números', 3, 8, 'Cuidarán allí de todos los utensilios de la Tienda de reunión y desempeñarán sus funciones en lugar de los israelitas, encargándose del servicio del santuario.'),
('nvi', 'Números 3:9', 'Números', 3, 9, 'Pondrás a los levitas a las órdenes de Aarón y de sus hijos. Entre los israelitas, serán ellos los que estén totalmente dedicados a mí.'),
('nvi', 'Números 3:10', 'Números', 3, 10, 'A Aarón y a sus hijos les asignarás el ministerio sacerdotal. Pero cualquiera que se acerque al santuario y no sea sacerdote, será condenado a muerte.»'),
('nvi', 'Números 3:11', 'Números', 3, 11, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Números 3:12', 'Números', 3, 12, '«Yo mismo he escogido a los levitas de entre los israelitas, como sustitutos de todo primogénito. Los levitas son míos,'),
('nvi', 'Números 3:13', 'Números', 3, 13, 'porque míos son todos los primogénitos. Cuando exterminé a todos los primogénitos de Egipto, consagré para mí a todo primogénito de Israel, tanto de hombres como de animales. Por lo tanto, son míos. Yo soy el SEÑOR.»'),
('nvi', 'Números 3:14', 'Números', 3, 14, 'El SEÑOR le dijo a Moisés en el desierto de Sinaí:'),
('nvi', 'Números 3:15', 'Números', 3, 15, '«Haz un censo de los levitas por clanes y por familias patriarcales, tomando en cuenta a todo varón mayor de un mes.»'),
('nvi', 'Números 3:16', 'Números', 3, 16, 'Moisés llevó a cabo el censo, tal como el SEÑOR mismo se lo había ordenado.'),
('nvi', 'Números 3:17', 'Números', 3, 17, 'Hijos de Leví: Guersón, Coat y Merari.'),
('nvi', 'Números 3:18', 'Números', 3, 18, 'Clanes guersonitas: Libní y Simí.'),
('nvi', 'Números 3:19', 'Números', 3, 19, 'Clanes coatitas: Amirán, Izar, Hebrón y Uziel.'),
('nvi', 'Números 3:20', 'Números', 3, 20, 'Clanes meraritas: Majlí y Musí. Éstos son los clanes levitas, según sus familias patriarcales.'),
('nvi', 'Números 3:21', 'Números', 3, 21, 'De Guersón procedían los clanes de Libní y de Simí. Éstos eran los clanes guersonitas.'),
('nvi', 'Números 3:22', 'Números', 3, 22, 'El total de los varones censados mayores de un mes llegó a siete mil quinientos.'),
('nvi', 'Números 3:23', 'Números', 3, 23, 'Los clanes guersonitas acampaban al oeste, detrás del santuario.'),
('nvi', 'Números 3:24', 'Números', 3, 24, 'El jefe de la familia patriarcal de los guersonitas era Eliasaf hijo de Lael.'),
('nvi', 'Números 3:25', 'Números', 3, 25, 'En lo que atañe a la Tienda de reunión, los guersonitas tenían a su cargo la tienda que cubría el santuario, su toldo, la cortina que estaba a la entrada,'),
('nvi', 'Números 3:26', 'Números', 3, 26, 'el cortinaje del atrio y la cortina a la entrada del atrio que rodea el santuario y el altar, como también las cuerdas y todo lo necesario para su servicio.'),
('nvi', 'Números 3:27', 'Números', 3, 27, 'De Coat procedían los clanes de Amirán, Izar, Hebrón y Uziel. Éstos eran los clanes coatitas,'),
('nvi', 'Números 3:28', 'Números', 3, 28, 'que tenían a su cargo el santuario. El total de los varones mayores de un mes llegó a ocho mil seiscientos.'),
('nvi', 'Números 3:29', 'Números', 3, 29, 'Los clanes coatitas acampaban al sur del santuario.'),
('nvi', 'Números 3:30', 'Números', 3, 30, 'El jefe de la familia patriarcal de los coatitas era Elizafán hijo de Uziel.'),
('nvi', 'Números 3:31', 'Números', 3, 31, 'Tenían a su cargo el arca, la mesa, el candelabro, los altares, los utensilios del santuario con los que ministraban, y la cortina de la entrada, como también todo lo necesario para su servicio.'),
('nvi', 'Números 3:32', 'Números', 3, 32, 'El jefe principal de los levitas era Eleazar, hijo de Aarón el sacerdote, a quien se designó como jefe de los que tenían a su cargo el santuario.'),
('nvi', 'Números 3:33', 'Números', 3, 33, 'De Merari procedían los clanes de Majlí y Musí. Éstos eran los clanes meraritas.'),
('nvi', 'Números 3:34', 'Números', 3, 34, 'El total de los varones censados mayores de un mes llegó a seis mil doscientos.'),
('nvi', 'Números 3:35', 'Números', 3, 35, 'El jefe de la familia patriarcal de los meraritas era Zuriel hijo de Abijaíl. Los clanes meraritas acampaban al norte del santuario.'),
('nvi', 'Números 3:36', 'Números', 3, 36, 'Tenían a su cargo el armazón del santuario, es decir, sus travesaños, postes y bases, junto con todos sus utensilios y todo lo necesario para su servicio.'),
('nvi', 'Números 3:37', 'Números', 3, 37, 'También cuidaban de los postes que estaban alrededor del atrio, junto con sus bases, estacas y cuerdas.'),
('nvi', 'Números 3:38', 'Números', 3, 38, 'Moisés, Aarón y sus hijos acampaban delante del santuario, es decir, al este de la Tienda de reunión, por donde sale el sol, ya que tenían a su cargo el santuario en representación de los israelitas. Pero cualquiera que, sin ser sacerdote, se acercaba al santuario, era condenado a muerte.'),
('nvi', 'Números 3:39', 'Números', 3, 39, 'Moisés y Aarón censaron a los levitas, tal como el SEÑOR mismo se lo había ordenado. El total de los levitas mayores de un mes censados por clanes llegó a veintidós mil.'),
('nvi', 'Números 3:40', 'Números', 3, 40, 'El SEÑOR le dijo a Moisés: «Haz un censo de todos los primogénitos israelitas mayores de un mes, y registra sus nombres.'),
('nvi', 'Números 3:41', 'Números', 3, 41, 'Apártame a los levitas en sustitución de todos los primogénitos israelitas, así como el ganado de los levitas en sustitución de todas las primeras crías del ganado de los israelitas. Yo soy el SEÑOR.»'),
('nvi', 'Números 3:42', 'Números', 3, 42, 'Moisés hizo el censo de todos los primogénitos israelitas, conforme a lo que el SEÑOR le había mandado.'),
('nvi', 'Números 3:43', 'Números', 3, 43, 'El total de los primogénitos mayores de un mes, anotados por nombre, llegó a veintidós mil doscientos setenta y tres.'),
('nvi', 'Números 3:44', 'Números', 3, 44, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Números 3:45', 'Números', 3, 45, '«Apártame a los levitas en sustitución de todos los primogénitos de los israelitas, así como el ganado de los levitas en sustitución del ganado de los israelitas. Los levitas son míos. Yo soy el SEÑOR.'),
('nvi', 'Números 3:46', 'Números', 3, 46, '»Para rescatar a los doscientos setenta y tres primogénitos israelitas que exceden al número de levitas,'),
('nvi', 'Números 3:47', 'Números', 3, 47, 'recaudarás cinco monedas de plata por cabeza, según la moneda oficial del santuario, que pesa once gramos.'),
('nvi', 'Números 3:48', 'Números', 3, 48, 'Esa suma se la entregarás a Aarón y a sus hijos, como rescate por los israelitas que exceden a su número.»'),
('nvi', 'Números 3:49', 'Números', 3, 49, 'Moisés recaudó el dinero del rescate de los israelitas que excedían al número de los rescatados por los levitas.'),
('nvi', 'Números 3:50', 'Números', 3, 50, 'En total recaudó mil trescientas sesenta y cinco monedas de plata, según la moneda oficial del santuario.'),
('nvi', 'Números 3:51', 'Números', 3, 51, 'Luego entregó ese dinero a Aarón y a sus hijos, tal como el SEÑOR mismo se lo había ordenado.'),
('nvi', 'Números 4:1', 'Números', 4, 1, 'El SEÑOR les dijo a Moisés y a Aarón:'),
('nvi', 'Números 4:2', 'Números', 4, 2, '«Hagan un censo, por clanes y por familias patriarcales, de los levitas que descienden de Coat.'),
('nvi', 'Números 4:3', 'Números', 4, 3, 'Incluye en él a todos los varones de treinta a cincuenta años de edad que sean aptos para trabajar en la Tienda de reunión.'),
('nvi', 'Números 4:4', 'Números', 4, 4, '»El ministerio de los coatitas en la Tienda de reunión consiste en cuidar de las cosas más sagradas.'),
('nvi', 'Números 4:5', 'Números', 4, 5, 'Cuando los israelitas deban ponerse en marcha, Aarón y sus hijos entrarán en el santuario y descolgarán la cortina que lo resguarda, y con ella cubrirán el arca del pacto.'),
('nvi', 'Números 4:6', 'Números', 4, 6, 'Después la cubrirán con piel de delfín y con un paño púrpura, y le colocarán las varas para transportarla.'),
('nvi', 'Números 4:7', 'Números', 4, 7, '»Sobre la mesa de la presencia del SEÑOR extenderán un paño púrpura y colocarán los platos, las bandejas, los tazones y las jarras para las libaciones. También estará allí el pan de la ofrenda permanente.'),
('nvi', 'Números 4:8', 'Números', 4, 8, 'Sobre todo esto extenderán un paño escarlata. Luego cubrirán la mesa con piel de delfín y le colocarán las varas para transportarla.'),
('nvi', 'Números 4:9', 'Números', 4, 9, '»Con un paño púrpura cubrirán el candelabro y sus lámparas, cortapabilos, ceniceros y utensilios que sirven para suministrarle aceite.'),
('nvi', 'Números 4:10', 'Números', 4, 10, 'Después cubrirán el candelabro y todos sus accesorios con piel de delfín, y lo colocarán sobre las andas.'),
('nvi', 'Números 4:11', 'Números', 4, 11, '»Extenderán un paño púrpura sobre el altar de oro, lo cubrirán con piel de delfín y le colocarán las varas para transportarlo.'),
('nvi', 'Números 4:12', 'Números', 4, 12, '»Envolverán en un paño púrpura todos los utensilios con los que ministran en el santuario, los cubrirán con piel de delfín, y luego los colocarán sobre las andas.'),
('nvi', 'Números 4:13', 'Números', 4, 13, '»Al altar del holocausto le quitarán las cenizas y lo cubrirán con un paño carmesí.'),
('nvi', 'Números 4:14', 'Números', 4, 14, 'Sobre el altar pondrán todos los utensilios que usan en su ministerio: ceniceros, tenedores, tenazas, aspersorios y todos los utensilios del altar. Luego lo cubrirán con piel de delfín y le colocarán las varas para transportarlo.'),
('nvi', 'Números 4:15', 'Números', 4, 15, '»Cuando Aarón y sus hijos hayan terminado de cubrir el santuario y todos sus accesorios, los israelitas podrán ponerse en marcha. Entonces vendrán los coatitas para transportar el santuario, pero sin tocarlo para que no mueran. También transportarán los objetos que están en la Tienda de reunión.'),
('nvi', 'Números 4:16', 'Números', 4, 16, '»En cambio, Eleazar hijo de Aarón estará a cargo del aceite para el candelabro, del incienso aromático, de la ofrenda permanente de cereal y del aceite de la unción. Además, cuidará del santuario y de todos sus utensilios.»'),
('nvi', 'Números 4:17', 'Números', 4, 17, 'El SEÑOR les dijo a Moisés y a Aarón:'),
('nvi', 'Números 4:18', 'Números', 4, 18, '«Asegúrense de que los clanes de Coat no vayan a ser eliminados de la tribu de Leví.'),
('nvi', 'Números 4:19', 'Números', 4, 19, 'Para que no mueran cuando se acerquen a las cosas más sagradas, deberán hacer lo siguiente: Aarón y sus hijos asignarán a cada uno lo que deba hacer y transportar.'),
('nvi', 'Números 4:20', 'Números', 4, 20, 'Pero los coatitas no mirarán ni por un momento las cosas sagradas; de lo contrario, morirán.»'),
('nvi', 'Números 4:21', 'Números', 4, 21, 'El SEÑOR les dijo a Moisés y a Aarón:'),
('nvi', 'Números 4:22', 'Números', 4, 22, '«Hagan también un censo de los guersonitas por clanes y por familias patriarcales.'),
('nvi', 'Números 4:23', 'Números', 4, 23, 'Incluyan a todos los varones de treinta a cincuenta años que sean aptos para servir en la Tienda de reunión.'),
('nvi', 'Números 4:24', 'Números', 4, 24, '»El ministerio de los clanes guersonitas consiste en encargarse del transporte.'),
('nvi', 'Números 4:25', 'Números', 4, 25, 'Llevarán las cortinas del santuario, la Tienda de reunión, su toldo, la cubierta de piel de delfín que va encima, y la cortina de la entrada a la Tienda de reunión.'),
('nvi', 'Números 4:26', 'Números', 4, 26, 'También transportarán el cortinaje del atrio y la cortina que está a la entrada del atrio que rodea el santuario y el altar, junto con las cuerdas y todos los utensilios necesarios para su servicio. Deberán ocuparse de todo lo relacionado con éstos.'),
('nvi', 'Números 4:27', 'Números', 4, 27, 'Todo su trabajo, ya sea transportando los utensilios o sirviendo en la Tienda, deberán hacerlo bajo la dirección de Aarón y de sus hijos. De ellos será la responsabilidad de todo el transporte.'),
('nvi', 'Números 4:28', 'Números', 4, 28, 'El servicio de los clanes de Guersón en la Tienda de reunión será supervisado por Itamar, hijo del sacerdote Aarón.'),
('nvi', 'Números 4:29', 'Números', 4, 29, '»Haz un censo de los meraritas por clanes y por familias patriarcales.'),
('nvi', 'Números 4:30', 'Números', 4, 30, 'Incluye a todos los varones de treinta a cincuenta años que sean aptos para servir en la Tienda de reunión.'),
('nvi', 'Números 4:31', 'Números', 4, 31, 'Su trabajo en la Tienda de reunión consistirá en transportar el armazón del santuario, es decir, sus travesaños, postes y bases,'),
('nvi', 'Números 4:32', 'Números', 4, 32, 'lo mismo que los postes que están alrededor del atrio, sus bases, estacas y cuerdas, como también todos los utensilios necesarios para su servicio. Asígnale a cada uno los objetos que deberá transportar.'),
('nvi', 'Números 4:33', 'Números', 4, 33, 'El servicio de los clanes de Merari en la Tienda de reunión será supervisado por Itamar, hijo del sacerdote Aarón.»'),
('nvi', 'Números 4:34', 'Números', 4, 34, 'Moisés, Aarón y los líderes de la comunidad hicieron un censo de los coatitas por clanes y por familias patriarcales.'),
('nvi', 'Números 4:35', 'Números', 4, 35, 'El censo incluía a todos los varones de treinta a cincuenta años que eran aptos para servir en la Tienda de reunión.'),
('nvi', 'Números 4:36', 'Números', 4, 36, 'El total de los censados por clanes llegó a dos mil setecientos cincuenta hombres.'),
('nvi', 'Números 4:37', 'Números', 4, 37, 'Éste fue el total de los censados entre los clanes de Coat para servir en la Tienda de reunión, según el recuento que hicieron Moisés y Aarón, conforme al mandato del SEÑOR por medio de Moisés.'),
('nvi', 'Números 4:38', 'Números', 4, 38, 'Se hizo un censo de guersonitas por clanes y por familias patriarcales.'),
('nvi', 'Números 4:39', 'Números', 4, 39, 'El censo incluía a todos los varones de treinta a cincuenta años que eran aptos para servir en la Tienda de reunión.'),
('nvi', 'Números 4:40', 'Números', 4, 40, 'El total de los censados por familias patriarcales llegó a dos mil seiscientos treinta hombres.'),
('nvi', 'Números 4:41', 'Números', 4, 41, 'Éste fue el total de los censados entre los clanes de Guersón para servir en la Tienda de reunión, según el recuento que hicieron Moisés y Aarón, conforme al mandato del SEÑOR.'),
('nvi', 'Números 4:42', 'Números', 4, 42, 'Se hizo un censo de los meraritas por clanes y por familias patriarcales.'),
('nvi', 'Números 4:43', 'Números', 4, 43, 'El censo incluía a todos los varones de treinta a cincuenta años que eran aptos para servir en la Tienda de reunión.'),
('nvi', 'Números 4:44', 'Números', 4, 44, 'El total de los censados por clanes llegó a tres mil doscientos hombres.'),
('nvi', 'Números 4:45', 'Números', 4, 45, 'Éste fue el total de los censados entre los clanes de Merari, según el recuento que hicieron Moisés y Aarón, conforme al mandato del SEÑOR por medio de Moisés.'),
('nvi', 'Números 4:46', 'Números', 4, 46, 'Moisés, Aarón y los líderes de Israel hicieron un censo de todos los levitas por clanes y por familias patriarcales.'),
('nvi', 'Números 4:47', 'Números', 4, 47, 'El total de los varones de treinta a cincuenta años, que eran aptos para servir en la Tienda de reunión y transportarla,'),
('nvi', 'Números 4:48', 'Números', 4, 48, 'llegó a ocho mil quinientos ochenta.'),
('nvi', 'Números 4:49', 'Números', 4, 49, 'Conforme al mandato del SEÑOR por medio de Moisés, a cada uno se le asignó lo que tenía que hacer y transportar. Así fueron censados, según el mandato que Moisés recibió del SEÑOR.'),
('nvi', 'Números 5:1', 'Números', 5, 1, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Números 5:2', 'Números', 5, 2, '«Ordénales a los israelitas que expulsen del campamento a cualquiera que tenga una infección en la piel, o padezca de flujo venéreo, o haya quedado ritualmente impuro por haber tocado un cadáver.'),
('nvi', 'Números 5:3', 'Números', 5, 3, 'Ya sea que se trate de hombres o de mujeres, los expulsarás del campamento para que no contaminen el lugar donde habito en medio de mi pueblo.»'),
('nvi', 'Números 5:4', 'Números', 5, 4, 'Y los israelitas los expulsaron del campamento, tal como el SEÑOR se lo había mandado a Moisés.'),
('nvi', 'Números 5:5', 'Números', 5, 5, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Números 5:6', 'Números', 5, 6, 'que les dijera a los israelitas: «El hombre o la mujer que peque contra su prójimo, traiciona al SEÑOR y tendrá que responder por ello.'),
('nvi', 'Números 5:7', 'Números', 5, 7, 'Deberá confesar su pecado y pagarle a la persona perjudicada una compensación por el daño causado, con un recargo del veinte por ciento.'),
('nvi', 'Números 5:8', 'Números', 5, 8, 'Pero si la persona perjudicada no tiene ningún pariente, la compensación será para el SEÑOR y se le entregará al sacerdote, junto con el carnero para expiación del culpable.'),
('nvi', 'Números 5:9', 'Números', 5, 9, 'Toda contribución que los israelitas consagren para dársela al sacerdote, será del sacerdote.'),
('nvi', 'Números 5:10', 'Números', 5, 10, 'Lo que cada uno consagra es suyo, pero lo que se da al sacerdote es del sacerdote.»'),
('nvi', 'Números 5:11', 'Números', 5, 11, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Números 5:12', 'Números', 5, 12, 'que les dijera a los israelitas: «Supongamos que una mujer se desvía del buen camino y le es infiel a su esposo'),
('nvi', 'Números 5:13', 'Números', 5, 13, 'acostándose con otro; supongamos también que el asunto se mantiene oculto, ya que ella se mancilló en secreto, y no hubo testigos ni fue sorprendida en el acto.'),
('nvi', 'Números 5:14', 'Números', 5, 14, 'Si al esposo le da un ataque de celos y sospecha que ella está mancillada, o le da un ataque de celos y sospecha de ella, aunque no esté mancillada,'),
('nvi', 'Números 5:15', 'Números', 5, 15, 'entonces la llevará ante el sacerdote y ofrecerá por ella dos kilos de harina de cebada. No derramará aceite sobre la ofrenda ni le pondrá incienso, puesto que se trata de una ofrenda por causa de celos, una ofrenda memorial de cereal para señalar un pecado.'),
('nvi', 'Números 5:16', 'Números', 5, 16, '»El sacerdote llevará a la mujer ante el SEÑOR,'),
('nvi', 'Números 5:17', 'Números', 5, 17, 'pondrá agua pura en un recipiente de barro, y le echará un poco de tierra del suelo del santuario.'),
('nvi', 'Números 5:18', 'Números', 5, 18, 'Luego llevará a la mujer ante el SEÑOR, le soltará el cabello y pondrá en sus manos la ofrenda memorial por los celos, mientras él sostiene la vasija con las aguas amargas de la maldición.'),
('nvi', 'Números 5:19', 'Números', 5, 19, 'Entonces el sacerdote pondrá a la mujer bajo juramento, y le dirá: “Si estando bajo la potestad de tu esposo no te has acostado con otro hombre, ni te has desviado hacia la impureza, estas aguas amargas de la maldición no te dañarán.'),
('nvi', 'Números 5:20', 'Números', 5, 20, 'Pero si estando bajo la potestad de tu esposo te has desviado, mancillándote y acostándote con otro hombre'),
('nvi', 'Números 5:21', 'Números', 5, 21, '—aquí el sacerdote pondrá a la mujer bajo el juramento del voto de maldición—, que el SEÑOR haga recaer sobre ti la maldición y el juramento en medio de tu pueblo, que te haga estéril, y que el vientre se te hinche.'),
('nvi', 'Números 5:22', 'Números', 5, 22, 'Cuando estas aguas de la maldición entren en tu cuerpo, que te hinchen el vientre y te hagan estéril.”Y la mujer responderá: “¡Amén! ¡Que así sea!”'),
('nvi', 'Números 5:23', 'Números', 5, 23, '»El sacerdote escribirá estas maldiciones en un documento, que lavará con las aguas amargas.'),
('nvi', 'Números 5:24', 'Números', 5, 24, 'Después hará que la mujer se beba las aguas amargas de la maldición, que entrarán en ella para causarle amargura.'),
('nvi', 'Números 5:25', 'Números', 5, 25, '»El sacerdote recibirá de ella la ofrenda por los celos. Procederá a mecer ante el SEÑOR la ofrenda de cereal, la cual presentará sobre el altar;'),
('nvi', 'Números 5:26', 'Números', 5, 26, 'tomará de la ofrenda un puñado de cereal como memorial, y lo quemará en el altar. Después hará que la mujer se beba las aguas.'),
('nvi', 'Números 5:27', 'Números', 5, 27, 'Cuando ella se haya bebido las aguas de la maldición, y éstas entren en ella para causarle amargura, si le fue infiel a su esposo y se mancilló, se le hinchará el vientre y quedará estéril. Así esa mujer caerá bajo maldición en medio de su pueblo.'),
('nvi', 'Números 5:28', 'Números', 5, 28, 'Pero si no se mancilló, sino que se mantuvo pura, entonces no sufrirá daño alguno y será fértil.'),
('nvi', 'Números 5:29', 'Números', 5, 29, '»Ésta es la ley en cuanto a los celos, cuando se dé el caso de que una mujer, estando bajo la potestad de su esposo, se desvíe del buen camino y se mancille a sí misma,'),
('nvi', 'Números 5:30', 'Números', 5, 30, 'o cuando al esposo le dé un ataque de celos y sospeche de su esposa. El sacerdote llevará a la mujer a la presencia del SEÑOR y le aplicará esta ley al pie de la letra.'),
('nvi', 'Números 5:31', 'Números', 5, 31, 'El esposo quedará exento de culpa, pero la mujer sufrirá las consecuencias de su pecado.»'),
('nvi', 'Números 6:1', 'Números', 6, 1, 'El SEÑOR le ordenó a Moisés'),
('nvi', 'Números 6:2', 'Números', 6, 2, 'que les dijera a los israelitas: «Cuando un hombre o una mujer haga un voto especial, un voto que lo consagre al SEÑOR como nazareo,'),
('nvi', 'Números 6:3', 'Números', 6, 3, 'deberá abstenerse de vino y de otras bebidas fermentadas. No beberá vinagre de vino ni de otra bebida fermentada; tampoco beberá jugo de uvas ni comerá uvas ni pasas.'),
('nvi', 'Números 6:4', 'Números', 6, 4, 'Mientras dure su voto de nazareo, no comerá ningún producto de la vid, desde la semilla hasta la cáscara.'),
('nvi', 'Números 6:5', 'Números', 6, 5, '»Mientras dure el tiempo de su consagración al SEÑOR, es decir, mientras dure su voto de nazareo, tampoco se cortará el cabello, sino que se lo dejará crecer y se mantendrá santo.'),
('nvi', 'Números 6:6', 'Números', 6, 6, '»Mientras dure el tiempo de su consagración al SEÑOR, no podrá acercarse a ningún cadáver,'),
('nvi', 'Números 6:7', 'Números', 6, 7, 'ni siquiera en caso de que muera su padre, su madre, su hermano o su hermana. No deberá hacerse ritualmente impuro a causa de ellos, porque lleva sobre la cabeza el símbolo de su consagración al SEÑOR.'),
('nvi', 'Números 6:8', 'Números', 6, 8, 'Mientras dure el tiempo de su consagración al SEÑOR, se mantendrá santo.'),
('nvi', 'Números 6:9', 'Números', 6, 9, '»Si de improviso alguien muere junto a él, la consagración de su cabeza quedará anulada; así que al cabo de siete días, en el día de su purificación, deberá rasurarse la cabeza.'),
('nvi', 'Números 6:10', 'Números', 6, 10, 'Al octavo día llevará dos palomas o dos tórtolas, y se las entregará al sacerdote a la entrada de la Tienda de reunión.'),
('nvi', 'Números 6:11', 'Números', 6, 11, 'El sacerdote ofrecerá una de ellas como sacrificio expiatorio, y la otra como holocausto. Así el sacerdote hará expiación por el nazareo, ya que éste pecó al entrar en contacto con un cadáver. Ese mismo día el nazareo volverá a santificarse la cabeza,'),
('nvi', 'Números 6:12', 'Números', 6, 12, 'consagrando al SEÑOR el tiempo de su nazareato y llevando un cordero de un año como sacrificio por la culpa. No se le tomará en cuenta el tiempo anterior, porque su consagración quedó anulada.'),
('nvi', 'Números 6:13', 'Números', 6, 13, '»Esta ley se aplicará al nazareo al cumplir su período de consagración. Será llevado a la entrada de la Tienda de reunión,'),
('nvi', 'Números 6:14', 'Números', 6, 14, 'y allí ofrecerá como holocausto al SEÑOR un cordero de un año, sin defecto; como sacrificio expiatorio una oveja de un año, sin defecto; y como sacrificio de comunión un carnero sin defecto.'),
('nvi', 'Números 6:15', 'Números', 6, 15, 'Ofrecerá además un canastillo de panes sin levadura, panes de flor de harina amasados con aceite, obleas sin levadura untadas con aceite, y también ofrendas de cereal y de libación.'),
('nvi', 'Números 6:16', 'Números', 6, 16, '»Entonces el sacerdote las presentará al SEÑOR y ofrecerá el sacrificio expiatorio y el holocausto en favor del nazareo.'),
('nvi', 'Números 6:17', 'Números', 6, 17, 'Ofrecerá el carnero al SEÑOR como sacrificio de comunión, junto con el canastillo de panes sin levadura. También presentará las ofrendas de cereal y de libación.'),
('nvi', 'Números 6:18', 'Números', 6, 18, '»Luego, a la entrada de la Tienda de reunión, el nazareo se rapará la cabeza. Tomará el cabello que consagró, y lo echará al fuego que arde bajo el sacrificio de comunión.'),
('nvi', 'Números 6:19', 'Números', 6, 19, 'Üna vez que el nazareo se haya rapado la cabeza, el sacerdote tomará del canastillo un pan sin levadura y una oblea sin levadura, más la pierna cocida del carnero, y pondrá todo esto en manos del nazareo,'),
('nvi', 'Números 6:20', 'Números', 6, 20, 'después de lo cual mecerá todo esto ante el SEÑOR como una ofrenda. Todo esto es santo y le pertenece al sacerdote, lo mismo que el pecho mecido y el muslo ofrecido como contribución. Finalizado este rito, el nazareo podrá beber vino.'),
('nvi', 'Números 6:21', 'Números', 6, 21, '»Esta ley se aplicará al nazareo que haga un voto. Ésta es la ofrenda que presentará al SEÑOR por su nazareato, aparte de lo que pueda dar según sus recursos. Según la ley del nazareato, deberá cumplir el voto que hizo.»'),
('nvi', 'Números 6:22', 'Números', 6, 22, 'El SEÑOR le ordenó a Moisés:'),
('nvi', 'Números 6:23', 'Números', 6, 23, '«Diles a Aarón y a sus hijos que impartan la bendición a los israelitas con estas palabras:'),
('nvi', 'Números 6:24', 'Números', 6, 24, '»“El SEÑOR te bendiga y te guarde;'),
('nvi', 'Números 6:25', 'Números', 6, 25, 'el SEÑOR te mire con agrado y te extienda su amor;'),
('nvi', 'Números 6:26', 'Números', 6, 26, 'el SEÑOR te muestre su favor y te conceda la paz.”'),
('nvi', 'Números 6:27', 'Números', 6, 27, '»Así invocarán mi nombre sobre los israelitas, para que yo los bendiga.»'),
('nvi', 'Números 7:1', 'Números', 7, 1, 'Cuando Moisés terminó de levantar el santuario, lo consagró ungiéndolo junto con todos sus utensilios. También ungió y consagró el altar y sus utensilios.'),
('nvi', 'Números 7:2', 'Números', 7, 2, 'Entonces los jefes de Israel, es decir, los jefes de las familias patriarcales y de las tribus, que habían presidido el censo, hicieron una ofrenda'),
('nvi', 'Números 7:3', 'Números', 7, 3, 'y la llevaron al santuario para presentarla ante el SEÑOR. La ofrenda consistía en una carreta por cada dos jefes, y un buey por cada uno de ellos; eran, en total, seis carretas cubiertas y doce bueyes.'),
('nvi', 'Números 7:4', 'Números', 7, 4, 'El SEÑOR le dijo a Moisés:'),
('nvi', 'Números 7:5', 'Números', 7, 5, '«Recibe estas ofrendas que te entregan, para que sean usadas en el ministerio de la Tienda de reunión. Tú se las entregarás a los levitas, según lo requiera el trabajo de cada uno.»'),
('nvi', 'Números 7:6', 'Números', 7, 6, 'Moisés recibió las carretas y los bueyes, y se los entregó a los levitas.'),
('nvi', 'Números 7:7', 'Números', 7, 7, 'A los guersonitas les dio dos carretas y cuatro bueyes, como lo requería su ministerio.'),
('nvi', 'Números 7:8', 'Números', 7, 8, 'A los meraritas les dio cuatro carretas y ocho bueyes, como lo requería su ministerio. Todos ellos estaban bajo las órdenes de Itamar, hijo del sacerdote Aarón.'),
('nvi', 'Números 7:9', 'Números', 7, 9, 'A los coatitas no les dio nada, porque la responsabilidad de ellos era llevar las cosas sagradas sobre sus propios hombros.'),
('nvi', 'Números 7:10', 'Números', 7, 10, 'Cuando el altar fue consagrado, los jefes llevaron una ofrenda de dedicación y la presentaron ante el altar,'),
('nvi', 'Números 7:11', 'Números', 7, 11, 'porque el SEÑOR le había dicho a Moisés: «Para presentar su ofrenda de dedicación del altar, cada jefe tendrá su propio día.»'),
('nvi', 'Números 7:12', 'Números', 7, 12, 'El primer día le tocó presentar su ofrenda a Naasón hijo de Aminadab, de la tribu de Judá.'),
('nvi', 'Números 7:13', 'Números', 7, 13, 'Para la ofrenda de cereal, presentó una fuente de plata y un aspersorio de plata, llenos de flor de harina amasada con aceite. Según la tasación oficial del santuario, la fuente pesaba un kilo y medio, y el aspersorio pesaba ochocientos gramos.'),
('nvi', 'Números 7:14', 'Números', 7, 14, 'También presentó una bandeja de oro de ciento diez gramos, llena de incienso.'),
('nvi', 'Números 7:15', 'Números', 7, 15, 'Para el holocausto, presentó un novillo, un carnero y un cordero de un año.'),
('nvi', 'Números 7:16', 'Números', 7, 16, 'Para el sacrificio expiatorio, presentó un macho cabrío.'),
('nvi', 'Números 7:17', 'Números', 7, 17, 'Para el sacrificio de comunión, presentó dos bueyes, cinco carneros, cinco machos cabríos y cinco corderos de un año. Ésta fue la ofrenda de Naasón hijo de Aminadab.'),
('nvi', 'Números 7:18', 'Números', 7, 18, 'El segundo día le tocó presentar su ofrenda a Natanael hijo de Zuar, jefe de la tribu de Isacar.'),
('nvi', 'Números 7:19', 'Números', 7, 19, 'Para la ofrenda de cereal, presentó una fuente de plata y un aspersorio de plata, llenos de flor de harina amasada con aceite. Según la tasación oficial del santuario, la fuente pesaba un kilo y medio, y el aspersorio pesaba ochocientos gramos.'),
